class PlanningStateConflict(RuntimeError):
    def __init__(self, current: dict[str, Any]):
        super().__init__("Planning state was updated by another session.")
        self.current = current


class ProtectedSettingsChange(RuntimeError):
    pass


PROTECTED_SETTINGS_FIELDS = ("processWaitSettings", "holidays", "calendarEvents", "setupSettings", "productWeights", "rawMaterialSettings", "flowSettings")


def protected_settings_changed(incoming: dict[str, Any], current: dict[str, Any] | None) -> bool:
    if current is None:
        return any(incoming.get(field) not in (None, [], {}) for field in PROTECTED_SETTINGS_FIELDS)
    return any(incoming.get(field) != current.get(field) for field in PROTECTED_SETTINGS_FIELDS)


def _insert_planning_history(
    db: sqlite3.Connection,
    seed: dict[str, Any],
    serialized_seed: str,
    timestamp: str,
    prefix: str = "planning",
    actor_id: str = "",
    actor_name: str = "",
) -> dict[str, Any]:
    history_id = f"{prefix}-{uuid.uuid4()}"
    state_hash = hashlib.sha256(serialized_seed.encode("utf-8")).hexdigest()
    db.execute(
        "INSERT INTO planning_state_history(id,seed_json,state_hash,created_at,created_by_id,created_by_name) VALUES(?,?,?,?,?,?)",
        (history_id, serialized_seed, state_hash, timestamp, actor_id, actor_name),
    )
    stale = db.execute(
        "SELECT id FROM planning_state_history ORDER BY created_at DESC LIMIT -1 OFFSET 20"
    ).fetchall()
    if stale:
        db.executemany("DELETE FROM planning_state_history WHERE id=?", [(row["id"],) for row in stale])
    return {"id": history_id, "seed": seed, "createdAt": timestamp, "createdBy": {"id": actor_id, "name": actor_name}}


OPERATIONAL_ROOT_FIELDS = (
    "productionInterruptions",
    "productionCancellations",
    "productionHistory",
    "wipLots",
    "wipMovements",
    "planningEvents",
    "processCurrentJobs",
)


def preserve_live_operations(incoming: dict[str, Any], current: dict[str, Any] | None, *, reconcile: bool = True) -> dict[str, Any]:
    """Apply planning inputs without allowing a stale snapshot to replace factory truth."""
    if current is None:
        return reconcile_turning_seed(incoming)
    merged = json.loads(json.dumps(incoming, ensure_ascii=False))
    changed_inputs = False
    for field in OPERATIONAL_ROOT_FIELDS:
        if field in current:
            if field != "planningEvents" and merged.get(field) != current[field]:
                changed_inputs = True
            merged[field] = current[field]

    current_machines = {
        machine.get("id"): machine
        for machine in current.get("machines", [])
        if isinstance(machine, dict) and isinstance(machine.get("id"), str)
    }
    for machine in merged.get("machines", []):
        if not isinstance(machine, dict):
            continue
        live_machine = current_machines.get(machine.get("id"))
        if live_machine is None:
            continue
        if "currentJob" in live_machine:
            changed_inputs |= machine.get("currentJob") != live_machine["currentJob"]
            machine["currentJob"] = live_machine["currentJob"]
        if "operationalAvailableStart" in live_machine:
            changed_inputs |= machine.get("operationalAvailableStart") != live_machine["operationalAvailableStart"]
            machine["operationalAvailableStart"] = live_machine["operationalAvailableStart"]
    incoming_ids = {machine.get("id") for machine in merged.get("machines", []) if isinstance(machine, dict)}
    missing_live = [machine for identity, machine in current_machines.items() if identity not in incoming_ids and machine.get("currentJob", {}).get("quantity", 0) > 0]
    if missing_live:
        merged["machines"] = merged.get("machines", []) + json.loads(json.dumps(missing_live))
        changed_inputs = True
    if changed_inputs or ("planNeedsRecalculation" not in incoming and current.get("planNeedsRecalculation")):
        merged["planNeedsRecalculation"] = True
    return reconcile_turning_seed(merged) if reconcile else merged


def _insert_production_archive_snapshot(
    db: sqlite3.Connection,
    seed: dict[str, Any],
    planning_updated_at: str,
    source: str,
) -> dict[str, Any] | None:
    archive = seed.get("productionHistory")
    if not isinstance(archive, list):
        archive = []
    serialized = json.dumps(archive, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    archive_hash = hashlib.sha256(serialized.encode("utf-8")).hexdigest()
    latest = db.execute(
        "SELECT archive_hash FROM production_archive_snapshots ORDER BY created_at DESC LIMIT 1"
    ).fetchone()
    if latest is not None and latest["archive_hash"] == archive_hash:
        return None
    snapshot_id = f"archive-{uuid.uuid4()}"
    created_at = now_iso()
    db.execute(
        """INSERT INTO production_archive_snapshots
        (id,archive_json,archive_hash,planning_updated_at,source,created_at)
        VALUES(?,?,?,?,?,?)""",
        (snapshot_id, serialized, archive_hash, planning_updated_at, source, created_at),
    )
    return {
        "id": snapshot_id,
        "productionHistory": archive,
        "archiveHash": archive_hash,
        "planningUpdatedAt": planning_updated_at,
        "source": source,
        "createdAt": created_at,
    }


def has_route_commitments(seed: dict[str, Any]) -> bool:
    return any(isinstance(batch, dict) and batch.get("routeCommitted") for batch in seed.get("manualBatches", [])) or any(
        isinstance(item, dict) and (item.get("routeMode") or item.get("queueOrder") is not None)
        for item in seed.get("processOperationOverrides", [])
    )


@_audited_planning_write
def save_planning_state(
    seed: dict[str, Any],
    expected_updated_at: str | None = None,
    force: bool = False,
    mode: str = "planning",
    actor_id: str = "",
    actor_name: str = "",
    can_manage_settings: bool = False,
    flow_settings_version: int = 0,
    route_placement_version: int = 0,
    production_split_version: int = 0,
    process_wait_settings_version: int = 0,
    identity_resolution: dict[str, Any] | None = None,
    request_id: str = "",
    session_id: str = "",
    delta: dict[str, Any] | None = None,
    base_hash: str = "",
    transaction_id: str = "",
    internal_connection: sqlite3.Connection | None = None,
    shared_inputs_only: bool = False,
) -> dict[str, Any]:
    with (nullcontext(internal_connection) if internal_connection is not None else connection()) as db:
        if not db.in_transaction:
            db.execute("BEGIN IMMEDIATE")
        timestamp = now_iso()
        row = db.execute("SELECT seed_json, updated_at, updated_by_id, updated_by_name FROM planning_state WHERE state_key='default'").fetchone()
        current = None if row is None else {"seed": _loads(row["seed_json"]), "updatedAt": row["updated_at"],
            "updatedBy": {"id": row["updated_by_id"], "name": row["updated_by_name"]},
            "stateHash": state_hash(_loads(row["seed_json"])), "patchVersion": 1}
        audit = _planning_audit.get()
        audit["currentRevision"] = current["updatedAt"] if current else ""
        audit["changes"] = _audit_changes(current["seed"] if current else None, seed)
        request_hash = ""
        if delta is not None:
            if (identity_resolution is not None or not planning_correlation_id(transaction_id)
                    or expected_updated_at is None):
                raise ValueError("Kayıt farkı için istek kimliği ve ortak sürüm gereklidir.")
            request_hash = state_hash({"delta": delta, "baseHash": base_hash,
                "expectedUpdatedAt": expected_updated_at, "mode": mode, "force": force,
                "flowSettingsVersion": flow_settings_version, "routePlacementVersion": route_placement_version,
                "productionSplitVersion": production_split_version, "processWaitSettingsVersion": process_wait_settings_version})
            receipt = db.execute("SELECT * FROM planning_write_receipts WHERE actor_id=? AND transaction_id=?",
                                 (actor_id, transaction_id)).fetchone()
            if receipt:
                if receipt["request_hash"] != request_hash:
                    raise ValueError("Aynı istek kimliği farklı bir değişiklik için kullanılamaz. Yerel kopyayı koruyun.")
                if current is None:
                    raise ValueError("Onaylı kaydın güncel ortak sürümü bulunamadı. Sistem yöneticisine bildirin.")
                audit.update(outcome="replayed", resultRevision=current["updatedAt"], changes={},
                             appliedRevision=receipt["result_revision"])
                _insert_planning_audit(db, audit)
                return {**current, "transactionId": transaction_id, "appliedRevision": receipt["result_revision"],
                        "replayed": True, "historyEntry": None, "archiveSnapshot": None}
            if (expected_updated_at != (current["updatedAt"] if current else "")
                    or base_hash != (current["stateHash"] if current else "")):
                raise PlanningStateConflict(current or {"seed": None, "updatedAt": "", "stateHash": "", "patchVersion": 1})
            seed = apply_delta(current["seed"] if current else {}, delta)
            audit["changes"] = _audit_changes(current["seed"] if current else None, seed)
        if shared_inputs_only:
            if current and expected_updated_at != current["updatedAt"]:
                raise PlanningStateConflict(current)
            from .collaboration import assert_shared_inputs_only
            assert_shared_inputs_only(current["seed"] if current else None, seed, can_manage_settings)
        submitted_seed = json.loads(json.dumps(seed)) if delta is not None else None
        unresolved = bool(current and inspect_turning_queue(current["seed"])["conflicts"])
        if (unresolved or identity_resolution is not None) and (expected_updated_at is None or expected_updated_at != (current["updatedAt"] if current else "")):
            raise PlanningStateConflict(current or {"seed": None, "updatedAt": ""})
        if identity_resolution is not None:
            if current is None:
                raise ValueError("Düzeltilecek ortak plan bulunamadı.")
            seed = repair_turning_identity(current["seed"], identity_resolution)
            target = next(b for b in current["seed"].get("manualBatches", []) if b.get("id") == identity_resolution["batchId"])
            detail = f'İş emri {target.get("workOrder", "")} → {identity_resolution.get("workOrder", "")}' if identity_resolution["action"] == "work-order" else "Doğrulanmış mükerrer kuyruk kaydı kaldırıldı; üretim kayıtları korundu"
            seed["planningEvents"] = [{"id": f"identity-review-{uuid.uuid4()}", "createdAt": timestamp,
                "type": "work-order" if identity_resolution["action"] == "work-order" else "remove",
                "machineId": target.get("machineId", ""), "batchId": target["id"],
                "message": f'{target.get("product", "")} · {detail}. Neden: {identity_resolution["reason"].strip()} · {actor_name}',
            }, *seed.get("planningEvents", [])][:200]
            seed["planNeedsRecalculation"] = True
            seed.pop("lastAutomaticPlan", None)
            seed.pop("planRunSequence", None)
        if "processWaitSettings" in seed:
            from .process_waits import validate_process_wait_settings
            validate_process_wait_settings(seed["processWaitSettings"])
        if process_wait_settings_version < 1 and ("processWaitSettings" in seed or current and "processWaitSettings" in current["seed"]):
            raise ValueError("Proses bekleme ayarlarını korumak için uygulamayı yenileyin.")
        if current and "processWaitSettings" in current["seed"] and "processWaitSettings" not in seed:
            seed = {**seed, "processWaitSettings": current["seed"]["processWaitSettings"]}
        if current and "flowSettings" in current["seed"] and "flowSettings" not in seed:
            seed = {**seed, "flowSettings": current["seed"]["flowSettings"]}
        seed = preserve_missing_weights(seed, current["seed"] if current else None)
        current_updated_at = current["updatedAt"] if current else ""
        if mode != "planning" and current and expected_updated_at is None:
            raise ValueError("Operasyon kaydı için güncel ortak sürüm gereklidir. Ortak veriyi yükleyin.")
        if (not force or mode != "planning") and expected_updated_at is not None and current_updated_at != expected_updated_at:
            raise PlanningStateConflict(current or {"seed": None, "updatedAt": ""})
        if "flowSettings" in seed:
            validate_flow_settings(seed["flowSettings"])
        if flow_settings_version < 1 and any((state.get("flowSettings") or {}).get("enabled") for state in [seed, current["seed"] if current else {}]):
            raise ValueError("Saat bazlı akış ayarlarını korumak için uygulamayı yenileyip ortak veriyi tekrar yükleyin.")
        if production_split_version < 1 and any(
            item.get("kind") == "partial-completion"
            for state in [seed, current["seed"] if current else {}]
            for item in state.get("productionInterruptions", [])
        ):
            raise ValueError("Kısmi üretim aktarımını korumak için uygulamayı yenileyip ortak veriyi tekrar yükleyin.")
        if route_placement_version < 1 and (has_route_commitments(seed) or current and has_route_commitments(current["seed"])):
            raise ValueError("Kaydedilmiş üretim akışı tercihlerini korumak için uygulamayı yenileyin. Eski sürümden kayıt yapılamaz.")
        if not can_manage_settings and protected_settings_changed(seed, current["seed"] if current else None):
            raise ProtectedSettingsChange("Ayarlar yalnızca yöneticiler tarafından değiştirilebilir")
        if "adviceSettings" in seed:
            advice = seed["adviceSettings"]
            days = advice.get("staleChargeDays") if isinstance(advice, dict) else None
            if not isinstance(advice, dict) or advice.get("version") != 1 or not isinstance(days, int) or isinstance(days, bool) or not 1 <= days <= 365:
                raise ValueError("Hareketsiz şarj eşiği 1–365 tam gün olmalıdır.")
        if "productWeights" in seed:
            validate_product_weights(seed["productWeights"])
        if "rawMaterialSettings" in seed:
            validate_raw_material_settings(seed["rawMaterialSettings"])
        if mode != "planning" and current and current["seed"].get("productionInterruptions") and "productionInterruptions" not in seed:
            raise ValueError("Yarım üretim kayıtlarını korumak için uygulamayı yenileyip ortak veriyi tekrar yükleyin.")
        saved_seed = preserve_live_operations(seed, current["seed"] if current else None, reconcile=not unresolved) if mode == "planning" else seed
        from .piston_controls import assert_pasif_transition, validate_production_cancellations
        if identity_resolution is None:
            assert_pasif_transition(current["seed"] if current else None, saved_seed)
        saved_seed = validate_production_cancellations(current["seed"] if current else None, saved_seed, actor_id, actor_name, timestamp)
        if identity_resolution is not None:
            # The server built and validated the complete repair from its own revision.
            pass
        elif unresolved:
            assert_turning_identity_transition(current["seed"], saved_seed)
            saved_seed = {**saved_seed, "planNeedsRecalculation": True}
        else:
            checked_seed = reconcile_turning_seed(saved_seed)
            if mode != "planning" and checked_seed != saved_seed:
                raise ValueError("Mevcut üretim veya tamamlanmış şarj kuyrukta tekrar bulunuyor. Ortak veriyi yükleyip işlemi yeniden deneyin.")
            saved_seed = checked_seed
        saved_hash = state_hash(saved_seed)
        correction = build_delta(submitted_seed, saved_seed) if delta is not None else None
        serialized_seed = json.dumps(saved_seed, ensure_ascii=False)
        db.execute(
            """INSERT INTO planning_state(state_key,seed_json,updated_at,updated_by_id,updated_by_name) VALUES('default',?,?,?,?)
            ON CONFLICT(state_key) DO UPDATE SET seed_json=excluded.seed_json,updated_at=excluded.updated_at,
            updated_by_id=excluded.updated_by_id,updated_by_name=excluded.updated_by_name""",
            (serialized_seed, timestamp, actor_id, actor_name),
        )
        # Order dates/milestones must commit with the seed and its version.
        # A separate browser PUT /orders can otherwise outlive a 409 conflict.
        if "orders" in saved_seed:
            orders = saved_seed["orders"]
            if not isinstance(orders, list) or any(not isinstance(order, dict) or not isinstance(order.get("id"), str) or not order["id"] for order in orders):
                raise ValueError("Sipariş kayıtları ve kimlikleri geçerli olmalıdır")
            _save_orders(db, orders, timestamp)
        history_entry = _insert_planning_history(db, saved_seed, serialized_seed, timestamp, actor_id=actor_id, actor_name=actor_name)
        archive_snapshot = _insert_production_archive_snapshot(db, saved_seed, timestamp, mode)
        audit.update(outcome="saved", resultRevision=timestamp, changes=_audit_changes(current["seed"] if current else None, saved_seed))
        _insert_planning_audit(db, audit)
        if delta is not None:
            _insert_planning_receipt(db, actor_id, transaction_id, request_hash, expected_updated_at, timestamp)
    return {"seed": saved_seed, "updatedAt": timestamp, "updatedBy": {"id": actor_id, "name": actor_name},
            "stateHash": saved_hash, "patchVersion": 1,
            "transactionId": transaction_id or None, "appliedRevision": timestamp, "replayed": False,
            "correction": correction,
            "historyEntry": history_entry, "archiveSnapshot": archive_snapshot}


class RefreshPreviewStale(Exception):
    """The reviewed preview no longer matches the stored or source state."""


PRODUCTION_SYNC_BACKUP_LIMIT = 30


def production_refresh_inputs() -> tuple[dict[str, Any] | None, str, dict[str, Any] | None]:
    """Local staging seed, its revision and the last production baseline (read-only)."""
    with connection() as db:
        local_row = db.execute("SELECT seed_json, updated_at FROM planning_state WHERE state_key='default'").fetchone()
        base_row = db.execute("SELECT seed_json FROM production_sync_baseline WHERE state_key='production'").fetchone()
    return (_loads(local_row["seed_json"]) if local_row else None, local_row["updated_at"] if local_row else "",
            _loads(base_row["seed_json"]) if base_row else None)


def replace_planning_state_from_production(
    seed: dict[str, Any],
    source_updated_at: str,
    source_url: str,
    scenario_records: list[dict[str, Any]],
    expected: dict[str, Any] | None = None,
    choices: dict[str, str] | None = None,
) -> dict[str, Any]:
    """Atomically apply a reviewed refresh.

    The local digest, revision and baseline digest are compared inside the
    write transaction; any difference rejects the write. The pre-change local
    seed is kept in production_sync_backup before anything is replaced.
    """
    from .production_merge import merge_production_refresh_reviewed, refresh_groups, resolve_refresh_choices, seed_digest
    timestamp = now_iso()
    source_seed = seed
    with connection() as db:
        db.execute("BEGIN IMMEDIATE")
        local_row = db.execute("SELECT seed_json, updated_at FROM planning_state WHERE state_key='default'").fetchone()
        base_row = db.execute("SELECT seed_json FROM production_sync_baseline WHERE state_key='production'").fetchone()
        local_seed = _loads(local_row["seed_json"]) if local_row else None
        baseline_seed = _loads(base_row["seed_json"]) if base_row else None
        if expected is not None:
            if (expected.get("localDigest") != seed_digest(local_seed)
                    or expected.get("localUpdatedAt", "") != (local_row["updated_at"] if local_row else "")
                    or expected.get("baselineDigest") != seed_digest(baseline_seed)):
                raise RefreshPreviewStale("Staging verisi önizlemeden sonra değişti. Önizlemeyi yenileyip yeniden inceleyin.")
        resolved = resolve_refresh_choices(refresh_groups(source_seed, local_seed, baseline_seed), choices)
        seed = merge_production_refresh_reviewed(source_seed, local_seed, baseline_seed, resolved)
        backup_id = None
        if local_seed is not None:
            backup_id = f"refresh-backup-{uuid.uuid4()}"
            db.execute("INSERT INTO production_sync_backup VALUES(?,?,?,?,?,?)",
                       (backup_id, timestamp, local_row["updated_at"], source_updated_at, json.dumps(resolved), local_row["seed_json"]))
            stale = db.execute("SELECT id FROM production_sync_backup ORDER BY created_at DESC LIMIT -1 OFFSET ?", (PRODUCTION_SYNC_BACKUP_LIMIT,)).fetchall()
            if stale:
                db.executemany("DELETE FROM production_sync_backup WHERE id=?", [(row["id"],) for row in stale])
        refreshed_hash = state_hash(seed)
        serialized_seed = json.dumps(seed, ensure_ascii=False)
        db.execute("INSERT INTO production_sync_baseline VALUES('production',?) ON CONFLICT(state_key) DO UPDATE SET seed_json=excluded.seed_json",
                   (json.dumps(source_seed, ensure_ascii=False),))
        db.execute(
            """INSERT INTO planning_state(state_key,seed_json,updated_at,updated_by_id,updated_by_name) VALUES('default',?,?,?,?)
            ON CONFLICT(state_key) DO UPDATE SET seed_json=excluded.seed_json,updated_at=excluded.updated_at,
            updated_by_id=excluded.updated_by_id,updated_by_name=excluded.updated_by_name""",
            (serialized_seed, timestamp, "system:production-sync", "Üretim senkronizasyonu"),
        )
        history_entry = _insert_planning_history(
            db,
            seed,
            serialized_seed,
            timestamp,
            "production-sync",
            "system:production-sync",
            "Üretim senkronizasyonu",
        )
        archive_snapshot = _insert_production_archive_snapshot(db, seed, timestamp, "production-sync")
        _save_orders(db, list(seed.get("orders") or []), timestamp, replace=True)
        db.executemany(
            """INSERT OR IGNORE INTO scenarios(id,name,created_at,notes,inputs_json,result_json)
            VALUES(?,?,?,?,?,?)""",
            [(
                scenario["id"],
                scenario["name"],
                scenario["createdAt"],
                scenario["notes"],
                json.dumps(scenario["seed"], ensure_ascii=False),
                json.dumps(scenario["result"], ensure_ascii=False),
            ) for scenario in scenario_records],
        )
        db.execute(
            """INSERT INTO production_sync_state(sync_key,source_updated_at,imported_at,source_url)
            VALUES('production',?,?,?) ON CONFLICT(sync_key) DO UPDATE SET
            source_updated_at=excluded.source_updated_at,imported_at=excluded.imported_at,source_url=excluded.source_url""",
            (source_updated_at, timestamp, source_url),
        )
    scenario_records = scenarios()
    planning_record = {"seed": seed, "updatedAt": timestamp, "stateHash": refreshed_hash, "patchVersion": 1}
    return {
        "planningState": planning_record,
        "sourceUpdatedAt": source_updated_at,
        "importedAt": timestamp,
        "sourceUrl": source_url,
        "historyEntry": history_entry,
        "archiveSnapshot": archive_snapshot,
        "scenarios": scenario_records,
        "backupId": backup_id,
        "appliedChoices": resolved,
    }


def demand_import_history() -> list[dict[str, Any]]:
    with connection() as db:
        rows = db.execute(
            "SELECT id,imported_at,source_file,snapshot_date,dataset_json,summary_json FROM demand_import_history ORDER BY imported_at DESC LIMIT 20"
        ).fetchall()
    return [{
        "id": row["id"],
        "importedAt": row["imported_at"],
        "sourceFile": row["source_file"],
        "snapshotDate": row["snapshot_date"],
        "dataset": _loads(row["dataset_json"]),
        "summary": _loads(row["summary_json"]),
    } for row in rows]


def save_demand_import_history(record: dict[str, Any]) -> dict[str, Any]:
    timestamp = now_iso()
    with connection() as db:
        db.execute(
            """INSERT INTO demand_import_history(id,imported_at,source_file,snapshot_date,dataset_json,summary_json,created_at)
            VALUES(?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET imported_at=excluded.imported_at,
            source_file=excluded.source_file,snapshot_date=excluded.snapshot_date,
            dataset_json=excluded.dataset_json,summary_json=excluded.summary_json""",
            (
                record["id"], record["importedAt"], record["sourceFile"], record["snapshotDate"],
                json.dumps(record["dataset"], ensure_ascii=False),
                json.dumps(record["summary"], ensure_ascii=False),
                timestamp,
            ),
        )
        stale = db.execute(
            "SELECT id FROM demand_import_history ORDER BY imported_at DESC LIMIT -1 OFFSET 20"
        ).fetchall()
        if stale:
            db.executemany("DELETE FROM demand_import_history WHERE id=?", [(row["id"],) for row in stale])
    return record


def scenarios() -> list[dict[str, Any]]:
    with connection() as db:
        rows = db.execute("SELECT s.* FROM scenarios s LEFT JOIN scenario_owners o ON o.scenario_id=s.id WHERE o.owner_id IS NULL OR o.shared=1 ORDER BY s.created_at DESC").fetchall()
    return [{"id": row["id"], "name": row["name"], "createdAt": row["created_at"], "notes": row["notes"], "seed": _loads(row["inputs_json"]), "result": _loads(row["result_json"])} for row in rows]


def scenario_summaries(limit: int = 20, offset: int = 0) -> dict[str, Any]:
    safe_limit = max(1, min(100, int(limit)))
    safe_offset = max(0, int(offset))
    with connection() as db:
        total = int(db.execute("SELECT COUNT(*) FROM scenarios").fetchone()[0])
        rows = db.execute(
            """SELECT id,name,created_at,notes,
            COALESCE(json_extract(result_json, '$.summary.plannedBatchCount'), 0) AS planned_batch_count,
            json_extract(result_json, '$.planRun') AS result_plan_run,
            json_extract(inputs_json, '$.activePlanRun') AS seed_plan_run
            FROM scenarios ORDER BY created_at DESC, id DESC LIMIT ? OFFSET ?""",
            (safe_limit, safe_offset),
        ).fetchall()
    items = []
    for row in rows:
        raw_plan_run = row["result_plan_run"] or row["seed_plan_run"]
        items.append({
            "id": row["id"],
            "name": row["name"],
            "createdAt": row["created_at"],
            "notes": row["notes"],
            "plannedBatchCount": max(0, int(row["planned_batch_count"] or 0)),
            "planRun": _loads(raw_plan_run) if raw_plan_run else None,
        })
    return {"items": items, "total": total, "limit": safe_limit, "offset": safe_offset, "hasMore": safe_offset + len(items) < total}


def scenario_record(scenario_id: str) -> dict[str, Any] | None:
    with connection() as db:
        row = db.execute("SELECT * FROM scenarios WHERE id=?", (scenario_id,)).fetchone()
    if row is None:
        return None
    return {"id": row["id"], "name": row["name"], "createdAt": row["created_at"], "notes": row["notes"], "seed": _loads(row["inputs_json"]), "result": _loads(row["result_json"])}


def revisions() -> list[dict[str, Any]]:
    with connection() as db:
        rows = db.execute("SELECT * FROM order_revisions ORDER BY approved_at DESC").fetchall()
    return [{"id": row["id"], "orderId": row["order_id"], "product": row["product"], "status": row["status"], "createdAt": row["created_at"], "approvedAt": row["approved_at"], "original": _loads(row["original_json"]), "requested": _loads(row["request_json"]), "impact": _loads(row["impact_json"]), "seed": _loads(row["seed_json"]), "result": _loads(row["result_json"])} for row in rows]


def app_update_record(db: sqlite3.Connection, update_id: str) -> dict[str, Any] | None:
    row = db.execute("SELECT * FROM app_updates WHERE id=?", (update_id,)).fetchone()
    if row is None:
        return None
    return {
        "id": row["id"],
        "title": row["title"],
        "bullets": _loads(row["bullets_json"]),
        "created_at": row["created_at"],
        "seen_at": row["seen_at"],
    }


def all_app_updates() -> list[dict[str, Any]]:
    with connection() as db:
        rows = db.execute("SELECT id FROM app_updates ORDER BY created_at DESC").fetchall()
        return [record for row in rows if (record := app_update_record(db, row["id"])) is not None]


def app_user_role(email: str) -> str | None:
    normalized = email.strip().lower()
    if not normalized:
        return None
    with connection() as db:
        row = db.execute("SELECT role FROM app_user_roles WHERE email=?", (normalized,)).fetchone()
    return str(row["role"]) if row else None


def feedback_record(db: sqlite3.Connection, feedback_id: str) -> dict[str, Any] | None:
    row = db.execute("SELECT * FROM feedbacks WHERE id=?", (feedback_id,)).fetchone()
    if row is None:
        return None
    comments = [dict(item) for item in db.execute("SELECT * FROM feedback_comments WHERE feedback_id=? ORDER BY created_at", (feedback_id,)).fetchall()]
    attachments = []
    for item in db.execute("SELECT * FROM feedback_attachments WHERE feedback_id=? ORDER BY created_at", (feedback_id,)).fetchall():
        attachment = dict(item)
        attachment["url"] = f"/api/attachments/{attachment['id']}/content"
        attachments.append(attachment)
    record = dict(row)
    record["comments"] = comments
    record["attachments"] = attachments
    return record


def all_feedback() -> list[dict[str, Any]]:
    with connection() as db:
        ids = [row["id"] for row in db.execute("SELECT id FROM feedbacks ORDER BY updated_at DESC").fetchall()]
        return [record for feedback_id in ids if (record := feedback_record(db, feedback_id)) is not None]

