        row = db.execute("SELECT feedback_id FROM feedback_comments WHERE id=?", (comment_id,)).fetchone()
        if row is None:
            raise HTTPException(status_code=404, detail="Yorum bulunamadı")
        timestamp = now_iso()
        db.execute("UPDATE feedback_comments SET body=?,updated_at=? WHERE id=?", (payload.body.strip(), timestamp, comment_id))
        db.execute("UPDATE feedbacks SET updated_at=? WHERE id=?", (timestamp, row["feedback_id"]))
        return feedback_record(db, row["feedback_id"])


@app.post("/api/feedbacks/{feedback_id}/attachments", status_code=201)
async def upload_attachments(feedback_id: str, files: list[UploadFile] = File(...), user: CurrentUser = Depends(current_user)):
    with connection() as db:
        require_feedback(db, feedback_id)
    for upload in files:
        content_type = (upload.content_type or mimetypes.guess_type(upload.filename or "")[0] or "application/octet-stream").lower()
        suffix = Path(upload.filename or "").suffix.lower()
        document_suffixes = {".doc", ".docx", ".pdf", ".rtf", ".txt", ".odt", ".xls", ".xlsx", ".xlsm", ".xlsb"}
        document_types = {
            "application/msword",
            "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
            "application/pdf",
            "application/rtf",
            "text/rtf",
            "text/plain",
            "application/vnd.oasis.opendocument.text",
            "application/vnd.ms-excel",
            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            "application/vnd.ms-excel.sheet.macroenabled.12",
            "application/vnd.ms-excel.sheet.binary.macroenabled.12",
            "application/octet-stream",
        }
        kind = "image" if content_type.startswith("image/") else "voice" if content_type.startswith("audio/") else "document" if suffix in document_suffixes and content_type in document_types else None
        if kind is None:
            raise HTTPException(status_code=415, detail="Yalnızca görüntü, ses, Excel, Word, PDF, RTF, ODT veya metin belgesi yüklenebilir")
        content = await upload.read()
        limit = 50 * 1024 * 1024 if kind == "voice" else 25 * 1024 * 1024 if kind == "document" else 20 * 1024 * 1024
        if not content or len(content) > limit:
            raise HTTPException(status_code=413, detail="Dosya boyutu sınırı aşıldı")
        suffix = suffix[:10]
        attachment_id, storage_key = str(uuid.uuid4()), f"{uuid.uuid4().hex}{suffix}"
        (settings.upload_dir / storage_key).write_bytes(content)
        timestamp = now_iso()
        with connection() as db:
            db.execute("INSERT INTO feedback_attachments(id,feedback_id,author_id,kind,original_name,content_type,size,storage_key,created_at) VALUES(?,?,?,?,?,?,?,?,?)",
                       (attachment_id, feedback_id, user.id, kind, upload.filename or f"{kind}{suffix}", content_type, len(content), storage_key, timestamp))
            db.execute("UPDATE feedbacks SET updated_at=? WHERE id=?", (timestamp, feedback_id))
    with connection() as db:
        return feedback_record(db, feedback_id)


@app.get("/api/attachments/{attachment_id}/content")
def attachment_content(attachment_id: str, _: CurrentUser = Depends(current_user)):
    with connection() as db:
        row = db.execute("SELECT * FROM feedback_attachments WHERE id=?", (attachment_id,)).fetchone()
    if row is None:
        raise HTTPException(status_code=404, detail="Dosya bulunamadı")
    path = settings.upload_dir / row["storage_key"]
    if not path.exists():
        raise HTTPException(status_code=404, detail="Dosya bulunamadı")
    return FileResponse(path, media_type=row["content_type"], filename=row["original_name"])


@app.delete("/api/attachments/{attachment_id}")
def delete_attachment(attachment_id: str, _: CurrentUser = Depends(current_user)):
    with connection() as db:
        row = db.execute("SELECT feedback_id,storage_key FROM feedback_attachments WHERE id=?", (attachment_id,)).fetchone()
        if row is None:
            raise HTTPException(status_code=404, detail="Dosya bulunamadı")
        db.execute("DELETE FROM feedback_attachments WHERE id=?", (attachment_id,))
        db.execute("UPDATE feedbacks SET updated_at=? WHERE id=?", (now_iso(), row["feedback_id"]))
    (settings.upload_dir / row["storage_key"]).unlink(missing_ok=True)
    return {"ok": True}

backend/app/order_import.py.source:
from __future__ import annotations

import re
import zipfile
from datetime import date, datetime, timedelta
from decimal import Decimal, InvalidOperation
from io import BytesIO
from pathlib import PurePosixPath
from xml.etree import ElementTree as ET


MAX_XLSX_BYTES = 5 * 1024 * 1024
MAX_UNCOMPRESSED_BYTES = 20 * 1024 * 1024
MAX_ROWS = 1_000
MAIN_NS = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
REL_NS = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"
PACKAGE_REL_NS = "http://schemas.openxmlformats.org/package/2006/relationships"


class OrderImportError(ValueError):
    pass


def _normalize_header(value: str) -> str:
    return " ".join(value.strip().lower().replace("ı", "i").replace("ş", "s").split())


def _sheet_paths(archive: zipfile.ZipFile) -> list[tuple[str, str]]:
    workbook = ET.fromstring(archive.read("xl/workbook.xml"))
    relationships = ET.fromstring(archive.read("xl/_rels/workbook.xml.rels"))
    relationship_targets = {
        item.attrib["Id"]: item.attrib["Target"]
        for item in relationships.findall(f"{{{PACKAGE_REL_NS}}}Relationship")
    }
    sheets = workbook.findall(f"{{{MAIN_NS}}}sheets/{{{MAIN_NS}}}sheet")
    if not sheets:
        raise OrderImportError("Excel dosyasında okunabilir bir sayfa bulunamadı.")
    paths: list[tuple[str, str]] = []
    for sheet in sheets:
        relationship_id = sheet.attrib.get(f"{{{REL_NS}}}id", "")
        target = relationship_targets.get(relationship_id, "")
        if not target:
            continue
        path = target.lstrip("/") if target.startswith("/") else str(PurePosixPath("xl") / target)
        paths.append((sheet.attrib.get("name", ""), path))
    if not paths:
        raise OrderImportError("Excel dosyasındaki sayfalar açılamadı.")
    return paths


def _first_sheet_path(archive: zipfile.ZipFile) -> str:
    return _sheet_paths(archive)[0][1]


def _sheet_path_by_name(archive: zipfile.ZipFile, expected_name: str) -> str | None:
    expected = expected_name.strip().casefold()
    return next((path for name, path in _sheet_paths(archive) if name.strip().casefold() == expected), None)


def _shared_strings(archive: zipfile.ZipFile) -> list[str]:
    if "xl/sharedStrings.xml" not in archive.namelist():
        return []
    root = ET.fromstring(archive.read("xl/sharedStrings.xml"))
    return ["".join(node.text or "" for node in item.iter(f"{{{MAIN_NS}}}t")) for item in root.findall(f"{{{MAIN_NS}}}si")]


def _cell_text(cell: ET.Element, shared: list[str]) -> tuple[str, bool]:
    cell_type = cell.attrib.get("t", "")
    if cell_type == "inlineStr":
        return "".join(node.text or "" for node in cell.iter(f"{{{MAIN_NS}}}t")), False
    value = cell.findtext(f"{{{MAIN_NS}}}v", default="")
    if cell_type == "s":
        try:
            return shared[int(value)], False
        except (ValueError, IndexError):
            raise OrderImportError("Excel metin tablosu okunamadı.") from None
    return value, cell_type not in {"str", "inlineStr", "s"}


def _parse_integer(value: str, numeric_cell: bool, row_number: int, label: str, allow_negative: bool = False) -> int:
    cleaned = value.strip().replace(" ", "")
    if not cleaned:
        return 0
    if not numeric_cell and re.fullmatch(r"\d{1,3}(?:[.,]\d{3})+", cleaned):
        cleaned = cleaned.replace(".", "").replace(",", "")
    elif not numeric_cell:
        cleaned = cleaned.replace(",", ".")
    try:
        number = Decimal(cleaned)
    except InvalidOperation:
        raise OrderImportError(f"{row_number}. satırdaki {label} sayı değil: {value}") from None
    if number < 0 and not allow_negative:
        raise OrderImportError(f"{row_number}. satırdaki {label} negatif olamaz.")
    if number != number.to_integral_value():
        raise OrderImportError(f"{row_number}. satırdaki {label} tam sayı olmalıdır.")
    return int(number)


def _parse_quantity(value: str, numeric_cell: bool, row_number: int) -> int:
    return _parse_integer(value, numeric_cell, row_number, "sipariş adeti")


def _sheet_values(sheet: ET.Element, shared: list[str]) -> dict[int, dict[str, tuple[str, bool]]]:
    values_by_row: dict[int, dict[str, tuple[str, bool]]] = {}
    for cell in sheet.iter(f"{{{MAIN_NS}}}c"):
        reference = cell.attrib.get("r", "")
        match = re.fullmatch(r"([A-Z]+)(\d+)", reference)
        if not match:
            continue
        row_number = int(match.group(2))
        values_by_row.setdefault(row_number, {})[match.group(1)] = _cell_text(cell, shared)
    return values_by_row


def _column_number(column: str) -> int:
    result = 0
    for character in column:
        result = result * 26 + ord(character) - 64
    return result


def _parse_snapshot_date(value: str) -> str:
    cleaned = value.strip()
    for pattern in ("%d.%m.%Y", "%Y-%m-%d"):
        try:
            return datetime.strptime(cleaned, pattern).date().isoformat()
        except ValueError:
            continue
    raise OrderImportError(f"Overview tarih değeri okunamadı: {value}")


def _parse_confirmed_overview(values_by_row: dict[int, dict[str, tuple[str, bool]]]) -> dict:
    headers = {column: value.strip() for column, (value, _) in values_by_row.get(1, {}).items()}
    normalized_headers = {_normalize_header(value): column for column, value in headers.items()}
    required = {
        "date": "Date",
        "material": "Material",
        "family of parts": "Family of Parts",
        "unit": "Unit",
        "available quantity": "Available quantity",
        "filter": "Filter",
    }
    missing = [display for normalized, display in required.items() if normalized not in normalized_headers]
    if missing:
        raise OrderImportError(f"'3. Overview (confirmed)' sayfasında beklenen kolonlar eksik: {', '.join(missing)}")

    baseline_columns = [
        (column, value)
        for column, value in headers.items()
        if re.fullmatch(r"<\s*CW\s+\d{1,2}\.\d{4}", value, re.IGNORECASE)
    ]
    if len(baseline_columns) != 1:
        raise OrderImportError("'3. Overview (confirmed)' sayfasında tek bir '< CW nn.yyyy' başlangıç kolonu bulunmalıdır.")
    baseline_column, baseline_label = baseline_columns[0]
    baseline_match = re.fullmatch(r"<\s*CW\s+(\d{1,2})\.(\d{4})", baseline_label, re.IGNORECASE)
    assert baseline_match is not None
    first_week_number = int(baseline_match.group(1))
    first_week_year = int(baseline_match.group(2))

    week_columns: list[dict[str, int | str]] = []
    for column, value in headers.items():
        match = re.fullmatch(r"CW\s+(\d{1,2})\.(\d{4})", value, re.IGNORECASE)
        if not match:
            continue
        iso_week = int(match.group(1))
        iso_year = int(match.group(2))
        try:
            week_start = date.fromisocalendar(iso_year, iso_week, 1)
            week_end = date.fromisocalendar(iso_year, iso_week, 6)
        except ValueError:
            raise OrderImportError(f"Geçersiz ISO hafta başlığı: {value}") from None
        week_columns.append({
            "column": column,
            "columnNumber": _column_number(column),
            "isoYear": iso_year,
            "isoWeek": iso_week,
            "id": f"{iso_year}-W{iso_week:02d}",
            "label": f"CW {iso_week}.{iso_year}",
            "weekStart": week_start.isoformat(),
            "weekEnd": week_end.isoformat(),
        })
    week_columns.sort(key=lambda item: int(item["columnNumber"]))
    if not week_columns:
        raise OrderImportError("'3. Overview (confirmed)' sayfasında 'CW nn.yyyy' haftaları bulunamadı.")
    if (week_columns[0]["isoWeek"], week_columns[0]["isoYear"]) != (first_week_number, first_week_year):
        raise OrderImportError("'< CW' başlangıç kolonu ile ilk haftalık kolon birbiriyle eşleşmiyor.")
    if int(week_columns[0]["columnNumber"]) != _column_number(baseline_column) + 1:
        raise OrderImportError("İlk haftalık kolon '< CW' başlangıç kolonunun hemen sağında olmalıdır.")
    for previous, current in zip(week_columns, week_columns[1:]):
        if date.fromisoformat(str(current["weekStart"])) != date.fromisoformat(str(previous["weekStart"])) + timedelta(days=7):
            raise OrderImportError(f"ISO hafta kolonları kesintisiz olmalıdır: {previous['label']} → {current['label']}")

    date_column = normalized_headers["date"]
    material_column = normalized_headers["material"]
    family_column = normalized_headers["family of parts"]
    unit_column = normalized_headers["unit"]
    available_column = normalized_headers["available quantity"]
    filter_column = normalized_headers["filter"]
    baseline_due_date = (date.fromisoformat(str(week_columns[0]["weekStart"])) - timedelta(days=2)).isoformat()
    products: list[dict] = []
    rows: list[dict[str, int | str]] = []
    seen: dict[str, int] = {}
    snapshot_dates: set[str] = set()
    ignored_blank_rows = 0

    for row_number in sorted(number for number in values_by_row if number > 1):
        cells = values_by_row[row_number]
        product = cells.get(material_column, ("", False))[0].strip().upper()
        if not product:
            if all(not cells.get(column, ("", False))[0].strip() for column in (family_column, available_column, baseline_column)):
                ignored_blank_rows += 1
                continue
            raise OrderImportError(f"{row_number}. satırda Material değeri boş.")
        if len(products) >= MAX_ROWS:
            raise OrderImportError(f"Excel dosyası en fazla {MAX_ROWS} ürün satırı içerebilir.")
        if not re.fullmatch(r"[A-Z0-9][A-Z0-9._/-]{1,63}", product):
            raise OrderImportError(f"{row_number}. satırdaki Material değeri geçersiz: {product}")
        if product in seen:
            raise OrderImportError(f"{product} tipi {seen[product]} ve {row_number}. satırlarda tekrar ediyor.")
        if cells.get(filter_column, ("", False))[0].strip().casefold() != "balance (confirmed)":
            raise OrderImportError(f"{row_number}. satır 'Balance (confirmed)' kaydı değil.")

        snapshot_dates.add(_parse_snapshot_date(cells.get(date_column, ("", False))[0]))
        available_text, available_numeric = cells.get(available_column, ("", True))
        baseline_text, baseline_numeric = cells.get(baseline_column, ("", True))
        if not available_text.strip() or not baseline_text.strip():
            raise OrderImportError(f"{row_number}. satırda stok veya '< CW' bakiyesi boş; Excel formülleri hesaplanmış olmalıdır.")
        available_quantity = _parse_integer(available_text, available_numeric, row_number, "Available quantity")
        baseline_balance = _parse_integer(baseline_text, baseline_numeric, row_number, "'< CW' bakiyesi", allow_negative=True)
        prior_demand = max(0, -baseline_balance)

        cumulative_quantity = prior_demand
        weekly_demands: list[dict] = []
        for week in week_columns:
            week_text, week_numeric = cells.get(str(week["column"]), ("", True))
            if not week_text.strip():
                raise OrderImportError(f"{row_number}. satırdaki {week['label']} bakiyesi boş; Excel formülleri hesaplanmış olmalıdır.")
            balance = _parse_integer(week_text, week_numeric, row_number, f"{week['label']} bakiyesi", allow_negative=True)
            required_quantity = max(0, -balance)
            next_cumulative_quantity = max(cumulative_quantity, required_quantity)
            quantity = next_cumulative_quantity - cumulative_quantity
            cumulative_quantity = next_cumulative_quantity
            weekly_demands.append({
                "weekId": week["id"],
                "isoYear": week["isoYear"],
                "isoWeek": week["isoWeek"],
                "label": week["label"],
                "weekStart": week["weekStart"],
                "weekEnd": week["weekEnd"],
                "quantity": quantity,
                "cumulativeQuantity": cumulative_quantity,
                "requiredQuantity": required_quantity,
                "balance": balance,
            })

        family = cells.get(family_column, ("", False))[0].strip()
        unit = cells.get(unit_column, ("", False))[0].strip()
        products.append({
            "product": product,
            "family": family,
            "unit": unit,
            "availableQuantity": available_quantity,
            "baselineBalance": baseline_balance,
            "priorDemand": prior_demand,
            "baselineDueDate": baseline_due_date,
            "weeklyDemands": weekly_demands,
            "totalDemand": cumulative_quantity,
        })
        rows.append({"product": product, "quantity": cumulative_quantity})
        seen[product] = row_number

    if not products:
        raise OrderImportError("'3. Overview (confirmed)' sayfasında ürün satırı bulunamadı.")
    if len(snapshot_dates) != 1:
        raise OrderImportError("'3. Overview (confirmed)' satırlarında tek bir ortak Date değeri bulunmalıdır.")

    weeks = []
    for week in week_columns:
        quantity = sum(
            int(next(item["quantity"] for item in product["weeklyDemands"] if item["weekId"] == week["id"]))
            for product in products
        )
        weeks.append({key: value for key, value in week.items() if key not in {"column", "columnNumber"}} | {"quantity": quantity})
    active = [product for product in products if int(product["totalDemand"]) > 0]
    first_week_requirement = sum(int(product["weeklyDemands"][0]["cumulativeQuantity"]) for product in products)
    last_week_requirement = sum(int(product["totalDemand"]) for product in products)
    return {
        "format": "confirmed-overview",
        "calculationModel": "net-shortage-v1",
        "sheetName": "3. Overview (confirmed)",
        "snapshotDate": next(iter(snapshot_dates)),
        "baselineLabel": baseline_label,
        "baselineDueDate": baseline_due_date,
        "weeks": weeks,
        "products": products,
        "rows": rows,
        "summary": {
            "productCount": len(products),
            "orderCount": len(active),
            "totalQuantity": last_week_requirement,
            "openingStock": sum(int(product["availableQuantity"]) for product in products),
            "priorDemand": sum(int(product["priorDemand"]) for product in products),
            "firstWeekRequirement": first_week_requirement,
            "lastWeekRequirement": last_week_requirement,
            "weekCount": len(weeks),
            "firstWeek": weeks[0]["id"],
            "lastWeek": weeks[-1]["id"],
            "ignoredBlankRows": ignored_blank_rows,
        },
    }


def _parse_simple_order_sheet(values_by_row: dict[int, dict[str, tuple[str, bool]]]) -> dict:
    values_by_row = {
        row_number: {column: value for column, value in cells.items() if column in {"A", "B"}}
        for row_number, cells in values_by_row.items()
    }

    first_header = _normalize_header(values_by_row.get(1, {}).get("A", ("", False))[0])
    second_header = _normalize_header(values_by_row.get(1, {}).get("B", ("", False))[0])
    if first_header != "tip no" or second_header not in {"plan adet", "siparis adeti", "siparis adedi"}:
        raise OrderImportError("Beklenen kolonlar bulunamadı. A1 'Tip no', B1 'Sipariş Adeti' veya 'Plan Adet' olmalıdır.")

    rows: list[dict[str, int | str]] = []
    seen: dict[str, int] = {}
    ignored_blank_rows = 0
    for row_number in sorted(number for number in values_by_row if number > 1):
        if len(rows) >= MAX_ROWS:
            raise OrderImportError(f"Excel dosyası en fazla {MAX_ROWS} ürün satırı içerebilir.")
        product = values_by_row[row_number].get("A", ("", False))[0].strip().upper()
        quantity_text, numeric_cell = values_by_row[row_number].get("B", ("", True))
        if not product and not quantity_text.strip():
            ignored_blank_rows += 1
            continue
        if not product:
            raise OrderImportError(f"{row_number}. satırda tip numarası boş.")
        if not re.fullmatch(r"[A-Z0-9][A-Z0-9._/-]{1,63}", product):
            raise OrderImportError(f"{row_number}. satırdaki tip numarası geçersiz: {product}")
        if product in seen:
            raise OrderImportError(f"{product} tipi {seen[product]} ve {row_number}. satırlarda tekrar ediyor.")
        quantity = _parse_quantity(quantity_text, numeric_cell, row_number)
        seen[product] = row_number
        rows.append({"product": product, "quantity": quantity})

    if not rows:
        raise OrderImportError("Excel dosyasında ürün satırı bulunamadı.")
    active = [row for row in rows if row["quantity"] > 0]
    return {
        "format": "simple-orders",
        "rows": rows,
        "summary": {
            "productCount": len(rows),
            "orderCount": len(active),
            "totalQuantity": sum(int(row["quantity"]) for row in active),
            "ignoredBlankRows": ignored_blank_rows,
        },
    }


def parse_order_xlsx(content: bytes) -> dict:
    if not content:
        raise OrderImportError("Excel dosyası boş.")
    if len(content) > MAX_XLSX_BYTES:
        raise OrderImportError("Excel dosyası 5 MB sınırını aşıyor.")
    try:
        with zipfile.ZipFile(BytesIO(content)) as archive:
            if len(archive.infolist()) > 200 or sum(item.file_size for item in archive.infolist()) > MAX_UNCOMPRESSED_BYTES:
                raise OrderImportError("Excel dosyası güvenli boyut sınırlarını aşıyor.")
            shared = _shared_strings(archive)
            confirmed_path = _sheet_path_by_name(archive, "3. Overview (confirmed)")
            target_path = confirmed_path or _first_sheet_path(archive)
            values_by_row = _sheet_values(ET.fromstring(archive.read(target_path)), shared)
    except OrderImportError:
        raise
    except (zipfile.BadZipFile, KeyError, ET.ParseError):
        raise OrderImportError("Dosya geçerli bir .xlsx çalışma kitabı değil.") from None

    return _parse_confirmed_overview(values_by_row) if confirmed_path else _parse_simple_order_sheet(values_by_row)

backend/app/piston_controls.py.source:
"""Server checks for Piston parameter deactivation and production cancellation.

The browser owns the calculation. The server rejects writes that bypass the
reviewed rules: a new Pasif assignment with undecided queued work, and
cancellation records that are malformed, altered or carry a client identity.
"""
from __future__ import annotations

from datetime import datetime, timedelta, timezone
from typing import Any


def _instant(value: Any) -> datetime | None:
    if not isinstance(value, str) or len(value) < 20:
        return None
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None
    return parsed.astimezone(timezone.utc) if parsed.tzinfo else None


def _code(value: Any) -> str:
    return str(value or "").strip().upper()


def _pasif_targets(seed: dict[str, Any]) -> set[tuple[str, str, str]]:
    targets: set[tuple[str, str, str]] = set()
    for product in seed.get("products") or []:
        for machine_id in product.get("inactiveMachineIds") or []:
            targets.add(("turning", _code(product.get("product")), str(machine_id)))
    for product in (seed.get("processMasterData") or {}).get("products") or []:
        for parameter in product.get("processes") or []:
            for resource_id in parameter.get("inactiveResourceIds") or []:
                targets.add((str(parameter.get("process")), _code(product.get("product")), str(resource_id)))
    return targets


def assert_pasif_transition(current: dict[str, Any] | None, seed: dict[str, Any]) -> None:
    """Reject a newly Pasif product-resource pair that still has queued work.

    Legacy Pasif pairs already present in the stored revision stay accepted, so
    an existing conflict never blocks unrelated saves or destroys evidence.
    """
    previous = _pasif_targets(current or {})
    added = _pasif_targets(seed) - previous
    if not added:
        return
    problems: list[str] = []
    running = {(job.get("batchId"), job.get("process")) for job in seed.get("processCurrentJobs") or []}
    lots = {lot.get("id"): lot for lot in seed.get("wipLots") or []}
    batches = seed.get("manualBatches") or []
    for process, product, resource_id in sorted(added):
        if process == "turning":
            for batch in batches:
                if batch.get("status") == "planned" and batch.get("machineId") == resource_id and _code(batch.get("product")) == product:
                    problems.append(f"{batch.get('product')} · {str(batch.get('workOrder') or '').strip() or batch.get('id')} · {resource_id} (Torna)")
            continue
        for override in seed.get("processOperationOverrides") or []:
            if override.get("process") != process or override.get("resourceId") != resource_id or override.get("routeMode") == "automatic":
                continue
            if (override.get("batchId"), process) in running:
                continue
            owner = override.get("sourceProduct") or (lots.get(override.get("batchId")) or {}).get("product") \
                or next((b.get("product") for b in batches if b.get("id") == override.get("batchId")), "")
            if _code(owner) == product:
                problems.append(f"{owner} · {override.get('batchId')} · {resource_id} ({process})")
    if problems:
        shown = "; ".join(problems[:5]) + (f" ve {len(problems) - 5} iş daha" if len(problems) > 5 else "")
        raise ValueError(
            "Parametreler: Pasif yapılan atamada kuyruktaki işler için karar gerekiyor. "
            f"{shown}. Uygulamayı yenileyip her iş için karar verin."
        )


CANCELLATION_STATUSES = {"pending", "replacement-approved", "replacement-declined"}
MAX_CLOSED_CANCELLATIONS = 200


def _positive_int(value: Any) -> bool:
    return isinstance(value, int) and not isinstance(value, bool) and value > 0


def _nonnegative_int(value: Any) -> bool:
    return isinstance(value, int) and not isinstance(value, bool) and value >= 0


def validate_production_cancellations(current: dict[str, Any] | None, seed: dict[str, Any], actor_id: str, actor_name: str, timestamp: str) -> dict[str, Any]:
    """Validate cancellation records and stamp server identity on new facts.

    Recorded facts (quantities, charge, reason, time) are immutable once saved.
    Only the review may move from pending to a decision; the reviewer is the
    authenticated user. A record cannot disappear while its review is open.
    """
    records = seed.get("productionCancellations")
    previous = {item.get("id"): item for item in (current or {}).get("productionCancellations") or [] if isinstance(item, dict)}
    if records is None:
        if any((item.get("review") or {}).get("status") != "replacement-approved" for item in previous.values()):
            raise ValueError("Üretim iptali kayıtlarını korumak için uygulamayı yenileyip ortak veriyi tekrar yükleyin.")
        return seed
    if not isinstance(records, list):
        raise ValueError("Üretim iptali kayıtları liste olmalıdır.")
    seen: set[str] = set()
    stamped: list[dict[str, Any]] = []
    fact_keys = ("product", "process", "chargeId", "workOrder", "machineId", "assignedQuantity", "completedQuantity", "cancelledQuantity", "reason", "cancelledAt", "orderIds", "orderQuantities", "historyEntryId")
    for raw in records:
        if not isinstance(raw, dict) or raw.get("version") != 1 or not isinstance(raw.get("id"), str) or not raw["id"] or raw["id"] in seen:
            raise ValueError("Üretim iptali kaydı geçersiz veya tekrarlı.")
        seen.add(raw["id"])
        item = dict(raw)
        if item.get("process") != "turning":
            raise ValueError("Yalnız Torna kalan üretimi iptal edilebilir.")
        if not _positive_int(item.get("assignedQuantity")) or not _nonnegative_int(item.get("completedQuantity")) or not _positive_int(item.get("cancelledQuantity")):
            raise ValueError(f"{item.get('product')} iptal adetleri pozitif tam sayı olmalıdır.")
        if item["completedQuantity"] + item["cancelledQuantity"] != item["assignedQuantity"]:
            raise ValueError(f"{item.get('product')} için üretilen + iptal edilen adet atanmış adede eşit olmalıdır.")
        cancelled_at = _instant(item.get("cancelledAt"))
        if cancelled_at is None:
            raise ValueError(f"{item.get('product')} iptal zamanı geçersiz.")
        if not str(item.get("reason") or "").strip():
            raise ValueError(f"{item.get('product')} için iptal nedeni zorunludur.")
        order_ids = item.get("orderIds")
        quantities = item.get("orderQuantities")
        if not isinstance(order_ids, list) or not all(isinstance(x, str) and x for x in order_ids) or len(set(order_ids)) != len(order_ids):
            raise ValueError(f"{item.get('product')} iptal kaydının sipariş bağlantısı geçersiz.")
        if not isinstance(quantities, dict) or set(quantities) != set(order_ids) or not all(_nonnegative_int(quantities[x]) for x in order_ids):
            raise ValueError(f"{item.get('product')} iptal kaydının sipariş adetleri geçersiz.")
        if "historyEntryId" in item and not (item["historyEntryId"] is None or isinstance(item["historyEntryId"], str)):
            raise ValueError(f"{item.get('product')} iptal kaydının üretim arşivi bağlantısı geçersiz.")
        review = item.get("review")
        if not isinstance(review, dict) or review.get("status") not in CANCELLATION_STATUSES:
            raise ValueError(f"{item.get('product')} iptal incelemesi geçersiz.")
        old = previous.get(item["id"])
        if old is None:
            now = _instant(timestamp)
            if now is not None and cancelled_at > now + timedelta(minutes=1):
                raise ValueError(f"{item.get('product')} iptal zamanı gelecekte olamaz.")
            if review["status"] != "pending":
                raise ValueError("Yeni iptal kaydı inceleme bekliyor durumunda olmalıdır.")
            item["recordedBy"] = actor_name or actor_id
            item["recordedById"] = actor_id
            item["review"] = {"status": "pending"}
        else:
            if any(old.get(key) != item.get(key) for key in fact_keys):
                raise ValueError(f"{item.get('product')} iptal kaydının adet, şarj ve neden bilgileri değiştirilemez.")
            item["recordedBy"] = old.get("recordedBy")
            item["recordedById"] = old.get("recordedById")
            old_review = old.get("review") or {}
            if review["status"] == old_review.get("status"):
                item["review"] = dict(old_review)
            elif old_review.get("status") == "pending":
                item["review"] = {"status": review["status"], "reviewedAt": timestamp, "reviewedBy": actor_name or actor_id, "reviewedById": actor_id,
                                  **({"note": str(review["note"])[:500]} if review.get("note") else {})}
            else:
                raise ValueError(f"{item.get('product')} iptal incelemesi zaten sonuçlandı.")
        stamped.append(item)
    for old_id, old in previous.items():
        if old_id not in seen and (old.get("review") or {}).get("status") != "replacement-approved":
            raise ValueError(f"{old.get('product')} için üretimi bekleten iptal kaydı silinemez.")
    # Pending and declined records still withhold production; only approved history is bounded.
    holding = [item for item in stamped if item["review"]["status"] != "replacement-approved"]
    approved = [item for item in stamped if item["review"]["status"] == "replacement-approved"][-MAX_CLOSED_CANCELLATIONS:]
    return {**seed, "productionCancellations": [*holding, *approved]}

