"""Three-way source refresh. Local edits win; related operational state moves together."""
from .turning_queue_identity import reconcile_turning_seed
from copy import deepcopy
from typing import Any


OPERATIONS = {
    "productionInterruptions", "productionCancellations", "scenarioProvenance",
    "machines", "productionHistory", "wipLots", "wipMovements", "planningEvents",
    "processCurrentJobs", "chargeJourneyNotes", "manualBatches", "savedBatches",
    "processOperationOverrides", "activePlanRun", "lastAutomaticPlan", "planRunSequence", "planNeedsRecalculation",
    "orders", "customerDemand", "customerOrderOverrides", "orderImport", "orderImportGrossOrders",
}


def merge_production_refresh(source: dict[str, Any], local: dict[str, Any] | None,
                             baseline: dict[str, Any] | None) -> dict[str, Any]:
    if local is None:
        return reconcile_turning_seed(deepcopy(source))
    # On the first pull there is no evidence that local work is disposable.
    base = baseline or {}
    missing = object()
    operational_changed = any(local.get(k, missing) != base.get(k, missing) for k in OPERATIONS)
    merged = {}
    for key in source.keys() | local.keys() | base.keys():
        changed = local.get(key, missing) != base.get(key, missing)
        keep_local = operational_changed if key in OPERATIONS else changed
        value = local.get(key, missing) if keep_local else source.get(key, missing)
        if value is not missing:
            merged[key] = deepcopy(value)
    return reconcile_turning_seed(merged)


# --- Reviewed refresh (T16) -------------------------------------------------
# Related facts move together in groups. The planner sees a comparison and
# chooses per group; nothing inside a group is merged field by field.

import hashlib
import json

REFRESH_GROUPS: dict[str, dict[str, Any]] = {
    "physical": {
        "label": "Üretim kayıtları ve plan",
        "fields": ("machines", "productionHistory", "wipLots", "wipMovements", "productionInterruptions",
                   "productionCancellations", "processCurrentJobs", "manualBatches", "savedBatches",
                   "processOperationOverrides", "activePlanRun", "lastAutomaticPlan", "planRunSequence",
                   "planNeedsRecalculation", "scenarioProvenance"),
        "choices": ("keep-local", "use-source"),
    },
    "orders": {
        "label": "Siparişler",
        "fields": ("orders", "customerDemand", "customerOrderOverrides", "orderImport", "orderImportGrossOrders"),
        "choices": ("keep-local", "use-source"),
    },
    "annotations": {
        "label": "Plan olayları ve şarj notları",
        "fields": ("planningEvents", "chargeJourneyNotes"),
        "choices": ("keep-local", "use-source", "combine"),
    },
}
GROUPED_FIELDS = {field for group in REFRESH_GROUPS.values() for field in group["fields"]}
_MISSING = object()


def seed_digest(seed: dict[str, Any] | None) -> str | None:
    if seed is None:
        return None
    return hashlib.sha256(json.dumps(seed, sort_keys=True, ensure_ascii=False, separators=(",", ":")).encode()).hexdigest()


def _group_values(seed: dict[str, Any] | None, fields: tuple[str, ...]) -> dict[str, Any]:
    seed = seed or {}
    return {field: seed[field] for field in fields if field in seed}


def _collection_summary(local: Any, source: Any) -> dict[str, int]:
    def by_id(rows: Any) -> dict[str, str]:
        if not isinstance(rows, list):
            return {}
        return {str(row.get("id")): json.dumps(row, sort_keys=True, ensure_ascii=False) for row in rows if isinstance(row, dict) and row.get("id") is not None}
    left, right = by_id(local), by_id(source)
    return {
        "onlyLocal": len(left.keys() - right.keys()),
        "onlySource": len(right.keys() - left.keys()),
        "different": sum(1 for key in left.keys() & right.keys() if left[key] != right[key]),
    }


def _group_summary(group_id: str, local: dict[str, Any], source: dict[str, Any]) -> dict[str, Any]:
    fields = REFRESH_GROUPS[group_id]["fields"]
    collections = {}
    for field in fields:
        left, right = local.get(field), source.get(field)
        if isinstance(left, list) or isinstance(right, list):
            if left != right:
                collections[field] = _collection_summary(left, right)
        elif left != right:
            collections[field] = {"changed": True}
    summary: dict[str, Any] = {"collections": collections}
    if group_id == "physical":
        local_jobs = {m.get("id"): m.get("currentJob") for m in local.get("machines") or [] if isinstance(m, dict)}
        source_jobs = {m.get("id"): m.get("currentJob") for m in source.get("machines") or [] if isinstance(m, dict)}
        summary["currentJobMachines"] = sorted(str(key) for key in local_jobs.keys() | source_jobs.keys() if local_jobs.get(key) != source_jobs.get(key))
    return summary


def refresh_groups(source: dict[str, Any], local: dict[str, Any] | None, baseline: dict[str, Any] | None) -> list[dict[str, Any]]:
    """Per-group comparison of the local staging state with the production source."""
    rows = []
    for group_id, group in REFRESH_GROUPS.items():
        fields = group["fields"]
        source_values = _group_values(source, fields)
        local_values = _group_values(local, fields) if local is not None else source_values
        base_values = _group_values(baseline, fields) if baseline is not None else None
        if local_values == source_values:
            status, default = "same", "use-source"
        elif base_values is None:
            status, default = "no-baseline", None
        elif local_values == base_values:
            status, default = "source-changed", "use-source"
        elif source_values == base_values:
            status, default = "local-changed", "keep-local"
        else:
            status, default = "both-changed", None
        rows.append({"id": group_id, "label": group["label"], "status": status, "defaultChoice": default,
                     "allowedChoices": list(group["choices"]), "requiresChoice": default is None,
                     "summary": _group_summary(group_id, local_values, source_values)})
    return rows


def settings_key_differences(source: dict[str, Any], local: dict[str, Any] | None, baseline: dict[str, Any] | None) -> dict[str, list[str]]:
    """Ungrouped (parameter/setting) keys: a locally changed key stays local, as before."""
    local = local or {}
    base = baseline or {}
    keys = sorted((source.keys() | local.keys()) - GROUPED_FIELDS)
    local_changed = [key for key in keys if local.get(key, _MISSING) != base.get(key, _MISSING)]
    source_changed = [key for key in keys if source.get(key, _MISSING) != base.get(key, _MISSING)]
    return {
        "keptLocal": [key for key in local_changed if local.get(key, _MISSING) != source.get(key, _MISSING)],
        "fromSource": [key for key in source_changed if key not in local_changed],
        "bothChanged": [key for key in local_changed if key in source_changed and local.get(key, _MISSING) != source.get(key, _MISSING)],
    }


def _combine_by_id(local_rows: Any, source_rows: Any) -> list[Any]:
    """Union of append-only logs by id; the local version wins for the same id."""
    result: list[Any] = []
    seen: set[str] = set()
    for rows in (local_rows if isinstance(local_rows, list) else [], source_rows if isinstance(source_rows, list) else []):
        for row in rows:
            key = str(row.get("id")) if isinstance(row, dict) and row.get("id") is not None else json.dumps(row, sort_keys=True, ensure_ascii=False)
            if key not in seen:
                seen.add(key)
                result.append(deepcopy(row))
    return result


def resolve_refresh_choices(groups: list[dict[str, Any]], choices: dict[str, str] | None) -> dict[str, str]:
    """Explicit choices for required groups; defaults elsewhere. Raises ValueError on a missing or invalid choice."""
    choices = choices or {}
    unknown = set(choices) - set(REFRESH_GROUPS)
    if unknown:
        raise ValueError(f"Bilinmeyen yenileme grubu: {', '.join(sorted(unknown))}.")
    resolved: dict[str, str] = {}
    for group in groups:
        choice = choices.get(group["id"], group["defaultChoice"])
        if choice is None:
            raise ValueError(f"{group['label']} için yerel çalışmayı koru veya üretim verisini kullan seçimi gerekli.")
        if choice not in group["allowedChoices"]:
            raise ValueError(f"{group['label']} için geçersiz seçim: {choice}.")
        resolved[group["id"]] = choice
    return resolved


def merge_production_refresh_reviewed(source: dict[str, Any], local: dict[str, Any] | None,
                                      baseline: dict[str, Any] | None, choices: dict[str, str]) -> dict[str, Any]:
    """Apply resolved group choices. Ungrouped keys keep the existing per-key rule."""
    if local is None:
        return reconcile_turning_seed(deepcopy(source))
    base = baseline or {}
    merged: dict[str, Any] = {}
    for key in (source.keys() | local.keys() | base.keys()) - GROUPED_FIELDS:
        changed = local.get(key, _MISSING) != base.get(key, _MISSING) if baseline is not None else local.get(key, _MISSING) != source.get(key, _MISSING)
        value = local.get(key, _MISSING) if changed else source.get(key, _MISSING)
        if value is not _MISSING:
            merged[key] = deepcopy(value)
    sides = set()
    for group_id, group in REFRESH_GROUPS.items():
        choice = choices[group_id]
        for field in group["fields"]:
            if choice == "combine":
                value: Any = _combine_by_id(local.get(field), source.get(field)) if field in local or field in source else _MISSING
            else:
                value = (local if choice == "keep-local" else source).get(field, _MISSING)
            if value is not _MISSING:
                merged[field] = deepcopy(value)
        if _group_values(local, group["fields"]) != _group_values(source, group["fields"]):
            sides.add(choice)
    # Groups taken from different sides were not calculated together.
    if len(sides) > 1 or ("use-source" in sides and choices.get("physical") == "keep-local"):
        merged["planNeedsRecalculation"] = True
    return reconcile_turning_seed(merged)

backend/app/production_sync.py.source:
from __future__ import annotations

import secrets
from typing import Any

import httpx
from fastapi import HTTPException

from .config import settings
from .database import RefreshPreviewStale, planning_state, production_refresh_inputs, production_sync_status, replace_planning_state_from_production, scenarios
from .production_merge import refresh_groups, seed_digest, settings_key_differences


SYNC_HEADER = "X-Staging-Pull-Token"


def _is_planning_seed(value: Any) -> bool:
    if not isinstance(value, dict):
        return False
    collections = ("machines", "products", "preferences", "orders")
    if not all(isinstance(value.get(key), list) for key in collections):
        return False
    if not all(isinstance(item, dict) for key in collections for item in value[key]):
        return False
    required_identity = {
        "machines": "id",
        "products": "product",
        "preferences": "key",
        "orders": "id",
    }
    return all(
        isinstance(item.get(identity), str) and bool(item[identity].strip())
        for collection, identity in required_identity.items()
        for item in value[collection]
    )


def _is_scenario_list(value: Any) -> bool:
    if not isinstance(value, list):
        return False
    return all(
        isinstance(item, dict)
        and all(isinstance(item.get(key), str) for key in ("id", "name", "createdAt", "notes"))
        and bool(item["id"].strip())
        and bool(item["name"].strip())
        and isinstance(item.get("seed"), dict)
        and isinstance(item.get("result"), dict)
        for item in value
    )


def production_snapshot(token: str | None) -> dict[str, Any]:
    if settings.app_env.lower() != "production":
        raise HTTPException(status_code=404, detail="Üretim anlık görüntüsü bu ortamda sunulmuyor.")
    if not settings.staging_pull_token:
        raise HTTPException(status_code=503, detail="Staging veri aktarımı üretimde yapılandırılmamış.")
    if not token or not secrets.compare_digest(token, settings.staging_pull_token):
        raise HTTPException(status_code=401, detail="Staging veri aktarım anahtarı geçersiz.")
    state = planning_state()
    if state is None or not _is_planning_seed(state.get("seed")):
        raise HTTPException(status_code=404, detail="Üretimde kopyalanacak planlama durumu bulunamadı.")
    return {"planningState": state, "scenarios": scenarios()}


def production_sync_status_payload() -> dict[str, Any]:
    enabled = (
        settings.app_env.lower() == "staging"
        and bool(settings.production_api_url)
        and bool(settings.production_sync_token)
    )
    return {
        "appEnv": settings.app_env.lower(),
        "enabled": enabled,
        "lastSync": production_sync_status(),
    }


def _fetch_production_source() -> tuple[dict[str, Any], str, list[dict[str, Any]]]:
    """Read the production snapshot. Staging only; production never pulls and there is no source write."""
    if settings.app_env.lower() != "staging":
        raise HTTPException(status_code=403, detail="Üretimden veri alma yalnızca staging ortamında kullanılabilir.")
    if not settings.production_api_url or not settings.production_sync_token:
        raise HTTPException(status_code=503, detail="Staging için üretim veri kaynağı yapılandırılmamış.")

    url = f"{settings.production_api_url}/production-snapshot"
    try:
        response = httpx.get(
            url,
            headers={SYNC_HEADER: settings.production_sync_token},
            timeout=20.0,
            follow_redirects=False,
        )
    except httpx.RequestError as error:
        raise HTTPException(status_code=502, detail="Üretim ortamına bağlanılamadı; staging değiştirilmedi.") from error
    if response.status_code != 200:
        raise HTTPException(status_code=502, detail="Üretim verisi okunamadı; staging değiştirilmedi.")
    try:
        payload = response.json()
    except ValueError as error:
        raise HTTPException(status_code=502, detail="Üretim ortamı geçerli veri döndürmedi; staging değiştirilmedi.") from error

    record = payload.get("planningState") if isinstance(payload, dict) else None
    scenario_records = payload.get("scenarios") if isinstance(payload, dict) else None
    seed = record.get("seed") if isinstance(record, dict) else None
    source_updated_at = record.get("updatedAt") if isinstance(record, dict) else None
    if not _is_planning_seed(seed) or not isinstance(source_updated_at, str) or not source_updated_at or not _is_scenario_list(scenario_records):
        raise HTTPException(status_code=502, detail="Üretim planlama kaydı eksik; staging değiştirilmedi.")
    return seed, source_updated_at, scenario_records


def _source_digest(seed: dict[str, Any], source_updated_at: str, scenario_records: list[dict[str, Any]]) -> str:
    return seed_digest({"seed": seed, "updatedAt": source_updated_at, "scenarios": scenario_records}) or ""


def _preview(seed: dict[str, Any], source_updated_at: str, scenario_records: list[dict[str, Any]]) -> dict[str, Any]:
    local, local_updated_at, baseline = production_refresh_inputs()
    known = {item.get("id") for item in scenarios()}
    groups = refresh_groups(seed, local, baseline)
    return {
        "sourceUpdatedAt": source_updated_at,
        "sourceDigest": _source_digest(seed, source_updated_at, scenario_records),
        "localUpdatedAt": local_updated_at,
        "localDigest": seed_digest(local),
        "baselineDigest": seed_digest(baseline),
        "baselineMissing": baseline is None,
        "groups": groups,
        "requiresReview": any(group["requiresChoice"] for group in groups),
        "settingsKeys": settings_key_differences(seed, local, baseline),
        "scenarios": {"sourceCount": len(scenario_records), "newIds": [item["id"] for item in scenario_records if item["id"] not in known]},
    }


def preview_production_refresh() -> dict[str, Any]:
    """Read-only comparison of staging with the current production source."""
    return _preview(*_fetch_production_source())


def apply_production_refresh(expected: dict[str, Any], choices: dict[str, str] | None) -> dict[str, Any]:
    """Apply a reviewed preview. The source is read again; any change rejects the write."""
    seed, source_updated_at, scenario_records = _fetch_production_source()
    if expected.get("sourceDigest") != _source_digest(seed, source_updated_at, scenario_records):
        raise HTTPException(status_code=409, detail={"message": "Üretim kaynağı önizlemeden sonra değişti. Önizlemeyi yenileyip yeniden inceleyin.", "preview": _preview(seed, source_updated_at, scenario_records)})
    try:
        return replace_planning_state_from_production(seed, source_updated_at, settings.production_api_url, scenario_records, expected, choices)
    except RefreshPreviewStale as error:
        raise HTTPException(status_code=409, detail={"message": str(error), "preview": _preview(seed, source_updated_at, scenario_records)}) from error
    except ValueError as error:
        raise HTTPException(status_code=422, detail=str(error)) from error


def pull_production_state(action: str | None = None, expected: dict[str, Any] | None = None, choices: dict[str, str] | None = None) -> dict[str, Any]:
    """Route entry (Root wires the body). preview → comparison; apply → reviewed write.

    A body without an action (older client) applies only when no group needs a
    choice; otherwise it returns 409 with the preview. A missing baseline with
    local differences always needs review.
    """
    if action == "preview":
        return preview_production_refresh()
    if action == "apply":
        if not isinstance(expected, dict):
            raise HTTPException(status_code=422, detail="Önizleme bilgisi eksik; önce önizlemeyi açın.")
        return apply_production_refresh(expected, choices)
    if action is not None:
        raise HTTPException(status_code=422, detail="Geçersiz yenileme işlemi.")
    seed, source_updated_at, scenario_records = _fetch_production_source()
    preview = _preview(seed, source_updated_at, scenario_records)
    if preview["requiresReview"]:
        raise HTTPException(status_code=409, detail={"message": "Üretim verisi ile staging çalışması çakışıyor. Grupları inceleyip seçim yapın.", "preview": preview})
    expected = {key: preview[key] for key in ("sourceDigest", "localDigest", "localUpdatedAt", "baselineDigest")}
    try:
        return replace_planning_state_from_production(seed, source_updated_at, settings.production_api_url, scenario_records, expected, None)
    except RefreshPreviewStale as error:
        raise HTTPException(status_code=409, detail={"message": str(error), "preview": _preview(seed, source_updated_at, scenario_records)}) from error

