"""Physical Torna queue identity; kept in parity with the frontend restore guard."""
import copy


def reconcile_turning_queue(seed, batches):
    inspected = inspect_turning_queue(seed, batches)
    if inspected["conflicts"]:
        raise ValueError(inspected["conflicts"][0]["message"])
    return inspected["reconciledBatches"]


def _recovered_turning_batches(seed):
    original = seed.get("manualBatches", [])
    known = {item["chargeId"] for item in seed.get("productionInterruptions", []) if item.get("process") == "turning" and item.get("chargeId") and item.get("turningBatch")}
    batches = [batch for batch in original if batch.get("id") not in known]
    latest = {}
    for item in seed.get("productionInterruptions", []):
        if item.get("chargeId") in known and item.get("process") == "turning" and not item.get("completedAt"):
            latest[item["chargeId"]] = item
    for identity, item in latest.items():
        if any(m.get("currentJob", {}).get("batchId") == identity and m["currentJob"].get("quantity", 0) > 0 for m in seed.get("machines", [])):
            continue
        matching = next((b for b in original if b.get("id") == identity and b.get("interruptionId") == item["id"] and b.get("quantity") == item["remainingQuantity"]), None)
        batches.append(matching or item["turningBatch"])
    positions = {batch.get("id"): index for index, batch in enumerate(original)}
    batches.sort(key=lambda batch: positions.get(batch.get("id"), len(original)))
    return batches


def reconcile_turning_seed(seed):
    original = seed.get("manualBatches", [])
    batches = reconcile_turning_queue(seed, _recovered_turning_batches(seed))
    if batches == original:
        return seed
    result = copy.deepcopy(seed)
    result["manualBatches"] = batches
    result.pop("lastAutomaticPlan", None)
    result["planNeedsRecalculation"] = True
    return result


def _key(value):
    return str(value or "").strip().upper()


def inspect_turning_queue(seed, batches=None):
    """Expose all conflicting records without assigning unproven physical identity."""
    batches = seed.get("manualBatches", []) if batches is None else batches
    records = []
    for machine in seed.get("machines", []):
        job = machine.get("currentJob", {})
        if job.get("quantity", 0) > 0:
            records.append(dict(kind="current", id=machine["id"], chargeId=job.get("batchId"), machineId=machine["id"], product=job.get("product", ""), workOrder=job.get("workOrder", ""), quantity=job.get("originalQuantity", job.get("quantity"))))
    for row in seed.get("productionHistory", []):
        if (not row.get("process") or row.get("process") == "turning") and row.get("inventoryStatus") != "voided" and not row.get("interruptionIds"):
            records.append(dict(kind="history", id=row["id"], chargeId=None if row.get("sourceBatchId") == row.get("id") else row.get("sourceBatchId"), machineId=row.get("machineId", ""), product=row.get("product", ""), workOrder=row.get("workOrder", ""), quantity=row.get("originalQuantity"), status=row.get("inventoryStatus")))
    for lot in seed.get("wipLots", []):
        if lot.get("sourceBatchId") and lot.get("sourceBatchId") != lot.get("sourceHistoryEntryId") and not any(h.get("id") == lot.get("sourceHistoryEntryId") and h.get("inventoryStatus") == "voided" for h in seed.get("productionHistory", [])):
            records.append(dict(kind="wip", id=lot["id"], chargeId=lot["sourceBatchId"], machineId="", product=lot.get("product", ""), workOrder=lot.get("workOrder", ""), quantity=lot.get("originalQuantity"), status=lot.get("stage")))
    conflicts, kept = [], []
    for batch in batches:
        duplicates = [b for b in batches if b.get("id") == batch.get("id")]
        exact = [r for r in records if r.get("chargeId") and r["chargeId"] == batch.get("id")]
        legacy = [r for r in records if not r.get("chargeId") and _key(r.get("workOrder")) and _key(r.get("workOrder")) == _key(batch.get("workOrder")) and _key(r.get("product")) == _key(batch.get("product"))]
        reason, evidence = None, []
        if len(duplicates) > 1:
            reason = "duplicate-queue-id"
            evidence = [dict(kind="queue", id=b.get("id", ""), machineId=b.get("machineId", ""), product=b.get("product", ""), workOrder=b.get("workOrder", ""), quantity=b.get("quantity")) for b in duplicates]
        elif exact:
            if any(_key(r.get("product")) != _key(batch.get("product")) for r in exact):
                reason, evidence = "product-mismatch", exact
            else:
                continue
        elif not batch.get("interruptionId") and legacy:
            candidates = [b for b in batches if _key(b.get("workOrder")) == _key(batch.get("workOrder")) and _key(b.get("product")) == _key(batch.get("product"))]
            if len(legacy) != 1 or len(candidates) != 1 or legacy[0].get("quantity") != batch.get("quantity") or legacy[0].get("machineId") != batch.get("machineId"):
                reason, evidence = "legacy-ambiguous", legacy
            else:
                continue
        if reason and reason != "duplicate-queue-id":
            evidence = [*evidence, dict(kind="queue", id=batch.get("id", ""), machineId=batch.get("machineId", ""), product=batch.get("product", ""), workOrder=batch.get("workOrder", ""), quantity=batch.get("quantity"), status="locked" if batch.get("locked") else batch.get("status"))]
        if reason:
            public_records = [{k: v for k, v in r.items() if k != "chargeId" and (k != "status" or v)} for r in evidence]
            message = f'{batch.get("machineId", "")} · {batch.get("workOrder") or batch.get("product", "")}: mevcut üretim/arşiv ile kuyruktaki şarj kimliği belirsiz. İş emri ve şarj kayıtlarını kontrol edin; işlem uygulanmadı.'
            conflicts.append(dict(batchId=batch.get("id", ""), machineId=batch.get("machineId", ""), product=batch.get("product", ""), workOrder=batch.get("workOrder", ""), message=message, reason=reason, records=public_records))
        kept.append(batch)
    return dict(conflicts=conflicts, reconciledBatches=kept)


def turning_identity_scope(seed, batches=None):
    batches = seed.get("manualBatches", []) if batches is None else batches
    conflicts = inspect_turning_queue(seed, batches)["conflicts"]
    products = {_key(p) for c in conflicts for p in [c["product"], *[r["product"] for r in c["records"]]] if _key(p)}
    machines = {m for c in conflicts for m in [c["machineId"], *[r["machineId"] for r in c["records"]]] if m}
    batch_ids, lots, histories = {c["batchId"] for c in conflicts}, set(), set()
    def add(target, value):
        if value:
            target.add(value)
    def related(product):
        return _key(product) in products
    size = -1
    while size != len(machines) + len(batch_ids) + len(lots) + len(histories):
        size = len(machines) + len(batch_ids) + len(lots) + len(histories)
        for b in batches:
            if related(b.get("product")) or b.get("id") in batch_ids or b.get("machineId") in machines:
                add(machines, b.get("machineId")); add(batch_ids, b.get("id"))
        for m in seed.get("machines", []):
            job = m.get("currentJob", {})
            if related(job.get("product")) or job.get("batchId") in batch_ids or m.get("id") in machines:
                add(machines, m.get("id")); add(batch_ids, job.get("batchId")); add(batch_ids, f'current:{m.get("id")}')
        for h in seed.get("productionHistory", []):
            if related(h.get("product")) or h.get("id") in histories or h.get("sourceEntryId") in histories or h.get("sourceBatchId") in batch_ids or any(a.get("lotId") in lots for a in h.get("wipAllocations", [])):
                add(histories, h.get("id")); add(histories, h.get("sourceEntryId")); add(batch_ids, h.get("sourceBatchId"))
                for a in h.get("wipAllocations", []):
                    add(lots, a.get("lotId"))
        for lot in seed.get("wipLots", []):
            if related(lot.get("product")) or lot.get("id") in lots or lot.get("parentLotId") in lots or lot.get("sourceHistoryEntryId") in histories or lot.get("sourceBatchId") in batch_ids:
                add(lots, lot.get("id")); add(lots, lot.get("parentLotId")); add(histories, lot.get("sourceHistoryEntryId")); add(batch_ids, lot.get("sourceBatchId"))
        for job in seed.get("processCurrentJobs", []):
            if related(job.get("product")) or job.get("batchId") in batch_ids or job.get("wipLotId") in lots:
                add(batch_ids, job.get("batchId")); add(lots, job.get("wipLotId"))
        for item in seed.get("productionInterruptions", []):
            if related(item.get("product")) or item.get("chargeId") in batch_ids:
                add(batch_ids, item.get("chargeId"))
                if item.get("process") == "turning":
                    add(machines, item.get("resourceId"))
    return dict(products=sorted(products), machineIds=sorted(machines), batchIds=sorted(batch_ids), lotIds=sorted(lots), historyIds=sorted(histories))


_FROZEN_CONFIGURATION = ("products", "preferences", "restrictions", "holidays", "calendarEvents", "setupSettings", "processWaitSettings", "processMasterData", "savedBatches", "activePlanningScope", "customerDemand", "openingStock", "demandTargets", "orderImport", "orderImportGrossOrders", "customerOrderOverrides")


def _protected_identity_snapshot(seed, scope):
    def p(value):
        return _key(value) in scope["products"]
    def b(value):
        return bool(value and value in scope["batchIds"])
    def l(value):
        return bool(value and value in scope["lotIds"])
    def h(value):
        return bool(value and value in scope["historyIds"])
    return dict(
        configuration={k: seed.get(k) for k in _FROZEN_CONFIGURATION},
        machines=[m for m in seed.get("machines", []) if m.get("id") in scope["machineIds"] or p(m.get("currentJob", {}).get("product")) or b(m.get("currentJob", {}).get("batchId"))],
        manualBatches=[r for r in seed.get("manualBatches", []) if p(r.get("product")) or b(r.get("id")) or r.get("machineId") in scope["machineIds"]],
        productionHistory=[r for r in seed.get("productionHistory", []) if p(r.get("product")) or h(r.get("id")) or h(r.get("sourceEntryId")) or b(r.get("sourceBatchId")) or any(l(a.get("lotId")) for a in r.get("wipAllocations", []))],
        wipLots=[r for r in seed.get("wipLots", []) if p(r.get("product")) or l(r.get("id")) or l(r.get("parentLotId")) or h(r.get("sourceHistoryEntryId")) or b(r.get("sourceBatchId"))],
        wipMovements=[r for r in seed.get("wipMovements", []) if l(r.get("lotId"))],
        productionInterruptions=[r for r in seed.get("productionInterruptions", []) if p(r.get("product")) or b(r.get("chargeId")) or r.get("process") == "turning" and r.get("resourceId") in scope["machineIds"]],
        processCurrentJobs=[r for r in seed.get("processCurrentJobs", []) if p(r.get("product")) or b(r.get("batchId")) or l(r.get("wipLotId"))],
        processOperationOverrides=[r for r in seed.get("processOperationOverrides", []) if b(r.get("batchId")) or l(r.get("batchId"))],
        orders=[r for r in seed.get("orders", []) if p(r.get("product"))],
    )


def assert_turning_identity_transition(before, next_seed):
    previous = inspect_turning_queue(before)["conflicts"]
    if not previous:
        checked = reconcile_turning_seed(next_seed)
        if checked.get("manualBatches", []) != next_seed.get("manualBatches", []):
            raise ValueError("Mevcut veya tamamlanmış şarj kuyrukta tekrar bulunuyor. Ortak veriyi yükleyin.")
        return
    scope = turning_identity_scope(before)
    if _protected_identity_snapshot(before, scope) != _protected_identity_snapshot(next_seed, scope):
        raise ValueError("Bu işlem inceleme bekleyen şarjı veya bağlı kayıtlarını değiştiriyor. Önce İncele ve düzelt ile şarj kaydını doğrulayın.")
    if _recovered_turning_batches(next_seed) != next_seed.get("manualBatches", []):
        raise ValueError("Yarım kalan şarjın kuyruk kaydı korunmalıdır. Ortak veriyi yükleyin.")
    inspected = inspect_turning_queue(next_seed)
    if previous != inspected["conflicts"]:
        raise ValueError("İşlem yeni bir şarj kimliği çakışması oluşturuyor. İncele ve düzelt ile kayıtları doğrulayın.")
    if len(inspected["reconciledBatches"]) != len(next_seed.get("manualBatches", [])):
        raise ValueError("Mevcut veya tamamlanmış şarj kuyrukta tekrar bulunuyor. Ortak veriyi yükleyin.")


def repair_turning_identity(seed, request):
    reason = request.get("reason", "")
    if not isinstance(reason, str) or not reason.strip() or len(reason.strip()) > 2000:
        raise ValueError("Düzeltme nedeni zorunludur ve en fazla 2000 karakter olabilir.")
    rows = [b for b in seed.get("manualBatches", []) if b.get("id") == request.get("batchId")]
    before = inspect_turning_queue(seed)
    target = next((c for c in before["conflicts"] if c["batchId"] == request.get("batchId")), None)
    if len(rows) != 1 or not target or target["reason"] == "duplicate-queue-id":
        raise ValueError("Şarj tek bir kuyruk kaydı olarak doğrulanamıyor. Kayıtları sistem yöneticisiyle inceleyin.")
    row = rows[0]
    if (row.get("interruptionId") or any(i.get("chargeId") == row["id"] for i in seed.get("productionInterruptions", []))
        or any(m.get("currentJob", {}).get("batchId") == row["id"] and m.get("currentJob", {}).get("quantity", 0) > 0 for m in seed.get("machines", []))
        or any(l.get("sourceBatchId") == row["id"] for l in seed.get("wipLots", []))
        or any(j.get("batchId") == row["id"] for j in seed.get("processCurrentJobs", []))
        or any(o.get("batchId") == row["id"] for o in seed.get("processOperationOverrides", []))
        or any(h.get("sourceBatchId") == row["id"] and h.get("sourceBatchId") != h.get("id") for h in seed.get("productionHistory", []))):
        raise ValueError("Başlamış, yarım kalmış veya başka proseslere bağlı şarj bu pencereden düzeltilemez.")
    result = copy.deepcopy(seed)
    if request.get("action") == "work-order":
        work_order = request.get("workOrder", "")
        if not isinstance(work_order, str) or not work_order.strip() or len(work_order.strip()) > 100 or _key(work_order) == _key(row.get("workOrder")):
            raise ValueError("Farklı ve geçerli bir iş emri girin.")
        next(b for b in result["manualBatches"] if b["id"] == row["id"])["workOrder"] = work_order.strip()
    elif request.get("action") == "remove-duplicate":
        if request.get("confirmedDuplicate") is not True or not any(r["kind"] in ("current", "history") and _key(r["product"]) == _key(row.get("product")) and _key(r["workOrder"]) == _key(row.get("workOrder")) for r in target["records"]):
            raise ValueError("Mevcut üretim/arşiv kaydıyla aynı fiziksel iş olduğunu doğrulayın.")
        result["manualBatches"] = [b for b in result["manualBatches"] if b["id"] != row["id"]]
    else:
        raise ValueError("Geçersiz şarj düzeltmesi.")
    after = inspect_turning_queue(result)
    remaining = [c for c in before["conflicts"] if c["batchId"] != row["id"]]
    if after["conflicts"] != remaining or len(after["reconciledBatches"]) != len(result.get("manualBatches", [])):
        raise ValueError("Bu düzeltme çakışmayı güvenle çözmüyor veya başka şarjı etkiliyor. Kayıtları yeniden inceleyin.")
    result["planNeedsRecalculation"] = True
    result.pop("lastAutomaticPlan", None)
    return result

frontend/app/globals.css.source:
:root { --ink:#18201d; --muted:#6c756f; --line:#dde2dc; --paper:#f6f7f3; --white:#fff; --accent:#e85d2a; --accent-soft:#fff0e9; --green:#1e7b57; --red:#c84c43; --font-sans:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; --font-display:Manrope,Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; }
* { box-sizing:border-box; }
html, body { margin:0; min-height:100%; background:var(--paper); color:var(--ink); font-family:var(--font-sans), sans-serif; }
button, input, select { font:inherit; }
button { color:inherit; }
.app-shell { min-width:1100px; }
.topbar { height:62px; padding:0 28px; display:flex; align-items:center; border-bottom:1px solid var(--line); background:rgba(255,255,255,.9); position:sticky; top:0; z-index:20; backdrop-filter:blur(14px); }
.brand { width:188px; flex:0 0 auto; display:flex; align-items:center; gap:10px; font:700 17px var(--font-display),sans-serif; letter-spacing:-.02em; border:0; background:none; cursor:pointer; padding:0; }
.brand-mark { display:grid; place-items:center; width:28px; height:28px; border-radius:8px; background:var(--ink); color:#fff; font-size:14px; }
.selsa-logo-frame,.selsa-login-logo { display:grid; place-items:center; overflow:hidden; background:#526f73; }
.selsa-logo-frame { width:66px; height:29px; border-radius:5px; }
.selsa-logo-frame img { width:60px; height:auto; display:block; }
nav { display:flex; align-self:stretch; gap:1px; }
.nav-item { position:relative; padding:0 11px; display:flex; align-items:center; gap:6px; border:0; border-bottom:2px solid transparent; background:none; color:var(--muted); font-size:12px; white-space:nowrap; cursor:pointer; }
.nav-item.active { color:var(--ink); border-color:var(--accent); font-weight:650; }
.nav-count { min-width:17px; height:17px; padding:0 4px; display:grid; place-items:center; border-radius:9px; background:#c84c43; color:#fff; font-size:8px; font-weight:800; }
.top-actions { margin-left:auto; display:flex; align-items:center; gap:10px; }
.account-control { min-width:0; display:flex; align-items:center; gap:8px; }
.account-copy { max-width:110px; display:flex; flex-direction:column; align-items:flex-end; gap:1px; }
.account-copy strong,.account-copy small { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.account-copy strong { max-width:100%; color:#39443f; font-size:8px; }
.account-copy small { color:var(--muted); font-size:6px; font-weight:700; letter-spacing:.05em; text-transform:uppercase; }
.notice-state { max-width:150px; overflow:hidden; color:var(--muted); font-size:8px; text-overflow:ellipsis; white-space:nowrap; }
.sync-action { min-height:35px; padding:4px 9px; display:flex; align-items:center; gap:7px; border:1px solid #cfe1d8; border-radius:8px; background:#f6fbf8; color:#1e6f51; cursor:pointer; }
.sync-action > span { display:flex; flex-direction:column; align-items:flex-start; gap:1px; font-size:8px; font-weight:800; white-space:nowrap; }.sync-action small { color:var(--muted); font-size:6px; font-weight:550; }.sync-action.saving svg,.sync-action.pulling svg { animation:sync-spin .9s linear infinite; }.sync-action.offline,.sync-action.error { border-color:#e6c3b5; background:#fff7f2; color:#a55236; }.sync-action.conflict { border-color:#e1b79e; background:#fff1e7; color:#a34c29; }.sync-action:disabled { cursor:not-allowed; opacity:.72; }.sync-action.pulling:disabled { cursor:wait; }
@keyframes sync-spin { to { transform:rotate(360deg); } }
@media (max-width:1400px) {
  .topbar { padding-inline:20px; }
  .brand { width:170px; }
  .nav-item { padding-inline:9px; }
  .top-actions { gap:7px; }
  .notice-state { display:none; }
}
.tour-launch { min-height:30px; padding:0 9px; display:flex; align-items:center; gap:5px; border:1px solid var(--line); border-radius:7px; background:#fff; color:var(--muted); font-size:9px; font-weight:700; cursor:pointer; }
.sync-state { color:var(--muted); font-size:11px; display:flex; align-items:center; gap:7px; }
.sync-state i { width:7px; height:7px; border-radius:50%; background:#43a579; box-shadow:0 0 0 3px #e6f4ed; }
.icon-button,.avatar { border:1px solid var(--line); background:white; display:grid; place-items:center; cursor:pointer; }
.icon-button { width:34px; height:34px; border-radius:9px; }
.avatar { width:34px; height:34px; border-radius:50%; background:#26312d; color:white; font-size:11px; font-weight:700; }
.updates-launch { position:relative; width:34px; height:34px; flex:0 0 34px; display:grid; place-items:center; border:1px solid var(--line); border-radius:9px; background:#fff; color:#657069; cursor:pointer; transition:border-color .16s ease,background .16s ease,color .16s ease,transform .16s ease; }
.updates-launch:hover { border-color:#d5bc71; background:#fffaf0; color:#7d6112; transform:translateY(-1px); }
.updates-launch.active { border-color:#d9b84f; background:#fff8dc; color:#7d6112; animation:update-bell-arrive .42s ease-out; }
.updates-launch b { position:absolute; top:-6px; right:-6px; min-width:18px; height:18px; padding:0 4px; display:grid; place-items:center; border:2px solid #fff; border-radius:10px; background:#c84c43; color:#fff; font-size:7px; font-weight:850; line-height:1; }
.feedback-header-slot { width:34px; height:34px; flex:0 0 34px; display:block; }
.feedback-header-slot:empty { display:none; }
.feedback-header-launch { width:34px; height:34px; display:grid; place-items:center; border:1px solid var(--line); border-radius:9px; background:#fff; color:#087a78; cursor:pointer; transition:border-color .16s ease,background .16s ease,color .16s ease,transform .16s ease; }
.feedback-header-launch:hover,.feedback-header-launch:focus-visible { border-color:#7ab4ac; background:#edf8f6; color:#066967; outline:none; transform:translateY(-1px); }
@keyframes update-bell-arrive { 0% { transform:scale(.88) rotate(-8deg); } 60% { transform:scale(1.05) rotate(4deg); } 100% { transform:none; } }
.updates-backdrop { position:fixed; inset:62px 0 0; z-index:48; display:flex; justify-content:flex-end; background:rgba(24,32,29,.28); backdrop-filter:blur(2px); animation:updates-fade-in .16s ease-out; }
.updates-drawer { width:440px; height:100%; display:flex; flex-direction:column; overflow:hidden; border-left:1px solid var(--line); background:#fbfcfa; box-shadow:-18px 0 45px rgba(24,32,29,.14); animation:updates-slide-in .2s cubic-bezier(.2,.8,.2,1); }
@keyframes updates-fade-in { from { opacity:0; } }
@keyframes updates-slide-in { from { transform:translateX(24px); opacity:.5; } }
.updates-head { min-height:104px; padding:20px 20px 18px; display:grid; grid-template-columns:38px minmax(0,1fr) 30px; gap:11px; align-items:start; border-bottom:1px solid var(--line); background:#fff; }
.updates-head-icon { width:36px; height:36px; display:grid; place-items:center; border-radius:50%; background:#fff3cd; color:#866715; }
.updates-head > div > span { color:#866715; font-size:7px; font-weight:850; letter-spacing:.12em; }
.updates-head h2 { margin:4px 0 3px; font:700 19px var(--font-display); letter-spacing:-.02em; }
.updates-head p { margin:0; color:var(--muted); font-size:8px; }
.updates-head > button,.update-composer-title > button { width:30px; height:30px; display:grid; place-items:center; border:0; border-radius:7px; background:transparent; color:var(--muted); cursor:pointer; }
.updates-head > button:hover,.update-composer-title > button:hover { background:#f2f4f1; color:var(--ink); }
.update-compose-launch { min-height:38px; margin:14px 18px 4px; display:flex; flex:0 0 auto; align-items:center; justify-content:center; gap:7px; border:1px solid #d0ad42; border-radius:8px; background:#fffaf0; color:#765a0e; font-size:9px; font-weight:800; cursor:pointer; }
.update-compose-launch:hover { border-color:#b99529; background:#fff5d7; color:#614906; }
.update-composer { max-height:calc(100vh - 190px); margin:14px 18px 4px; padding:14px; display:grid; flex:0 0 auto; gap:10px; overflow:auto; border-top:3px solid #d0ad42; background:#fff; box-shadow:0 8px 24px rgba(24,32,29,.07); }
.update-composer-title { display:flex; align-items:center; justify-content:space-between; }
.update-composer-title > span { display:flex; align-items:center; gap:7px; color:#765a0e; font-size:10px; }
.update-composer label { display:grid; gap:5px; color:var(--muted); font-size:8px; font-weight:700; }
.update-composer input,.update-composer textarea { width:100%; padding:9px 10px; border:1px solid #d9ded9; border-radius:7px; background:#fff; color:var(--ink); font:9px/1.45 var(--font-sans); outline:none; }
.update-composer textarea { min-height:80px; resize:vertical; }
.update-composer input:focus,.update-composer textarea:focus { border-color:#b99529; box-shadow:0 0 0 3px rgba(208,173,66,.12); }
.update-composer-foot { display:flex; align-items:center; justify-content:space-between; }
.update-composer-foot > span { color:var(--muted); font-size:7px; }
.update-composer-foot > button { min-height:30px; padding:0 12px; border:0; border-radius:7px; background:#765a0e; color:#fff; font-size:8px; font-weight:800; cursor:pointer; }
.update-composer-foot > button:disabled { opacity:.42; cursor:default; }
.update-composer > p,.updates-error { margin:0; color:var(--red); font-size:8px; line-height:1.4; }
.updates-controls { min-height:44px; padding:8px 18px; display:flex; flex:0 0 auto; align-items:center; justify-content:space-between; gap:12px; border-bottom:1px solid var(--line); }
.updates-controls > button { min-height:28px; padding:0 9px; display:flex; align-items:center; gap:6px; border:1px solid var(--line); border-radius:7px; background:#fff; color:#657069; font-size:8px; font-weight:750; cursor:pointer; }
.updates-controls > button b { min-width:17px; height:17px; padding:0 4px; display:grid; place-items:center; border-radius:9px; background:#eef1ee; font-size:7px; }
.updates-controls > button.active { border-color:#b9d2c6; background:#edf7f2; color:#236b50; }
.updates-controls > span { color:var(--muted); font-size:7px; white-space:nowrap; }
.updates-error { margin:9px 18px 0; padding:8px 10px; background:#fff0ee; }
.updates-list { min-height:0; padding:10px 18px 28px; flex:1 1 auto; overflow:auto; }
.updates-list article { position:relative; padding:18px 2px 16px 17px; border-bottom:1px solid #e4e8e4; transition:opacity .18s ease,background .18s ease; }
.updates-list article:before { content:""; position:absolute; top:21px; left:1px; width:6px; height:6px; border-radius:50%; background:#d0ad42; box-shadow:0 0 0 4px #fff5d8; }
.updates-list article.seen { opacity:.64; }
.updates-list article.seen:before { background:#a9b2ac; box-shadow:none; }
.update-meta { display:flex; align-items:center; justify-content:space-between; gap:12px; }
.update-meta > span { color:#8a6810; font-size:7px; font-weight:850; letter-spacing:.1em; }
.seen .update-meta > span { color:#7e8982; }
.update-meta time { color:#8a948e; font-size:7px; }
.updates-list h3 { margin:6px 0 8px; font:700 13px/1.3 var(--font-display); }
.updates-list ul { margin:0; padding:0; display:grid; gap:6px; list-style:none; }
.updates-list li { position:relative; padding-left:12px; color:#4f5b55; font-size:9px; line-height:1.48; }
.updates-list li:before { content:""; position:absolute; left:0; top:5px; width:4px; height:4px; border-radius:50%; background:#8e9992; }
.updates-list footer { min-height:30px; margin-top:12px; display:flex; align-items:center; justify-content:flex-end; }
.updates-list footer button { min-height:30px; padding:0 10px; display:flex; align-items:center; gap:6px; border:1px solid #b9d2c6; border-radius:7px; background:#f2f8f5; color:#236b50; font-size:8px; font-weight:800; cursor:pointer; }
.updates-list footer button:hover { border-color:#73aa8f; background:#e7f4ed; }
.updates-list footer > span { display:flex; align-items:center; gap:5px; color:#718078; font-size:7px; }
.updates-empty { min-height:230px; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:7px; color:#87918b; text-align:center; }
.updates-empty strong { color:#4d5953; font-size:11px; }
.updates-empty span { max-width:260px; font-size:8px; line-height:1.45; }
@media (max-width:720px) { .updates-drawer { width:100%; }.updates-backdrop { inset:62px 0 0; } }
.page-head { padding:15px 30px 12px; display:flex; align-items:flex-end; justify-content:space-between; gap:28px; }
.eyebrow { color:var(--muted); font-size:9px; margin-bottom:4px; }
h1 { margin:0; font:700 24px/1.1 var(--font-display),sans-serif; letter-spacing:-.04em; }
.page-summary { max-width:610px; margin:4px 0 0; color:var(--muted); font-size:9px; line-height:1.4; }
.page-actions { position:relative; display:flex; align-items:center; justify-content:flex-end; gap:7px; }
.page-help { color:#087a78; }
.page-more-actions { position:relative; z-index:16; }
.page-more-actions > summary { min-height:39px; padding:0 11px; display:flex; align-items:center; gap:7px; border:1px solid var(--line); border-radius:9px; background:#fff; color:#56625c; font-size:10px; font-weight:700; cursor:pointer; list-style:none; }
.page-more-actions > summary::-webkit-details-marker { display:none; }
.page-more-actions > summary svg { transition:transform .16s ease; }
.page-more-actions[open] > summary { border-color:#b9c8c1; background:#f9fbf8; }
.page-more-actions[open] > summary svg { transform:rotate(180deg); }
.page-more-actions > div { position:absolute; top:calc(100% + 7px); right:0; width:218px; padding:6px; display:grid; gap:3px; border:1px solid #d8ded9; border-radius:9px; background:#fff; box-shadow:0 14px 35px rgba(24,32,29,.15); }
.page-more-actions > div > button,.page-more-history > button { min-height:34px; padding:0 9px; display:flex; align-items:center; gap:7px; border:0; border-radius:6px; background:transparent; color:#47534d; font-size:9px; font-weight:700; text-align:left; cursor:pointer; }
.page-more-actions > div > button:hover,.page-more-history > button:hover:not(:disabled) { background:#f0f5f2; color:#087a78; }
.page-more-history { display:grid; grid-template-columns:1fr 1fr; gap:3px; padding-bottom:4px; border-bottom:1px solid #e8ece8; }
.page-more-history > button { justify-content:center; }
.page-more-history > button:disabled { opacity:.38; cursor:default; }
.page-guide-panel { margin:-6px 30px 22px; min-height:86px; padding:16px 18px; display:grid; grid-template-columns:310px minmax(0,1fr) 30px; gap:24px; align-items:center; border-top:1px solid #b8d9d8; border-bottom:1px solid #b8d9d8; background:#f5fbfa; animation:guide-reveal .17s ease-out; }
.page-guide-panel > div { display:flex; align-items:flex-start; gap:10px; color:#087a78; }.page-guide-panel > div > span { display:flex; flex-direction:column; gap:4px; }.page-guide-panel strong { color:var(--ink); font:700 12px var(--font-display); }.page-guide-panel small { color:var(--muted); font-size:9px; line-height:1.4; }
.page-guide-panel ul { margin:0; padding:0; display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:14px; list-style:none; }.page-guide-panel li { position:relative; padding-left:14px; color:#53605a; font-size:9px; line-height:1.45; }.page-guide-panel li:before { content:""; position:absolute; left:0; top:5px; width:5px; height:5px; border-radius:50%; background:#087a78; }
.page-guide-panel > button { width:30px; height:30px; display:grid; place-items:center; border:0; border-radius:7px; background:transparent; color:var(--muted); cursor:pointer; }
.primary,.secondary,.wide-secondary { border-radius:9px; padding:10px 15px; border:1px solid var(--line); font-size:12px; font-weight:650; cursor:pointer; }
.strategy-select { border-radius:9px; padding:0 11px; border:1px solid var(--line); background:#fff; color:var(--ink); font-size:12px; font-weight:650; cursor:pointer; }
.primary { background:var(--accent); border-color:var(--accent); color:white; box-shadow:0 4px 12px rgba(232,93,42,.18); }
.primary:disabled { opacity:.45; cursor:not-allowed; box-shadow:none; }
.secondary,.wide-secondary { background:white; display:flex; align-items:center; gap:8px; }
.metrics { display:grid; grid-template-columns:repeat(5,1fr); padding:0 30px 12px; }
.metric { min-height:58px; padding:2px 18px; border-right:1px solid var(--line); display:flex; flex-direction:column; justify-content:center; }
.metric:first-child { padding-left:0; }.metric:last-child { border-right:0; }
.metric > span { color:var(--muted); font-size:9px; }
.metric strong { font:700 19px/1.25 var(--font-display),sans-serif; letter-spacing:-.03em; }
.metric small { color:var(--muted); font-size:8px; }.metric.good strong,.metric.good small { color:var(--green); }.metric.warning strong,.metric.warning small { color:#a36b25; }.metric.danger strong,.metric.danger small { color:var(--red); }
.number-with-help { max-width:100%; display:inline-flex; align-items:center; gap:4px; vertical-align:middle; }
.number-with-help > span:first-child { min-width:0; }
.number-help-trigger { position:relative; width:14px; height:14px; flex:0 0 14px; display:inline-grid; place-items:center; border-radius:50%; background:#edf1ee; color:#7a8780; cursor:help; outline:none; }
.number-help-trigger:hover,.number-help-trigger:focus-visible { background:#dceee7; color:#176a54; box-shadow:0 0 0 2px rgba(23,106,84,.12); }
.number-help-trigger [role="tooltip"] { position:absolute; z-index:60; left:50%; bottom:calc(100% + 7px); width:220px; padding:8px 9px; visibility:hidden; border-radius:6px; background:#26352f; color:#fff; box-shadow:0 8px 24px rgba(24,32,29,.2); font:500 8px/1.45 var(--font-body),sans-serif; letter-spacing:0; text-align:left; white-space:normal; opacity:0; pointer-events:none; transform:translate(-50%,3px); transition:opacity .14s ease,transform .14s ease,visibility .14s; }
.number-help-trigger [role="tooltip"]:after { content:""; position:absolute; top:100%; left:50%; border:5px solid transparent; border-top-color:#26352f; transform:translateX(-50%); }
.number-help-trigger:hover [role="tooltip"],.number-help-trigger:focus-visible [role="tooltip"] { visibility:visible; opacity:1; transform:translate(-50%,0); }
.metric:first-child .number-help-trigger [role="tooltip"] { left:0; transform:translate(0,3px); }
