.feedback-attachments figure.document { grid-column:1 / -1; }.feedback-document-file { min-height:72px; padding:12px; display:flex; align-items:center; gap:10px; background:#f3f7fc; color:#315c9b; text-decoration:none; }.feedback-document-file[aria-disabled="true"] { opacity:.55; pointer-events:none; }.feedback-document-file > span { min-width:0; display:flex; flex-direction:column; gap:3px; }.feedback-document-file strong { overflow:hidden; color:var(--ink); font-size:9px; text-overflow:ellipsis; white-space:nowrap; }.feedback-document-file small { color:#58719a; font-size:8px; }
