.feedback-page { width:min(1280px,calc(100% - 80px)); }.feedback-toolbar { min-height:58px; padding:10px 4px; display:flex; align-items:center; gap:10px; border-bottom:1px solid var(--line); }.feedback-status-filters { display:flex; align-items:center; gap:4px; }.feedback-status-filters button { min-height:31px; padding:0 9px; display:flex; align-items:center; gap:6px; border:1px solid transparent; border-radius:7px; background:transparent; color:var(--muted); font-size:8px; font-weight:750; cursor:pointer; }.feedback-status-filters button span { min-width:18px; height:18px; display:grid; place-items:center; border-radius:9px; background:#edf0ec; color:#65706a; font-size:7px; }.feedback-status-filters button:hover { background:#f5f7f4; }.feedback-status-filters button.selected { border-color:#bfd4d0; background:#edf7f5; color:#087a78; }.feedback-status-filters button.selected span { background:#087a78; color:#fff; }.feedback-search { min-width:170px; min-height:32px; margin-left:auto; padding:0 8px; display:flex; align-items:center; gap:6px; border:1px solid var(--line); border-radius:7px; background:#fff; color:var(--muted); }.feedback-search input { width:100%; border:0; outline:0; background:transparent; font-size:8px; }.feedback-toolbar > select { min-height:32px; padding:0 25px 0 8px; border:1px solid var(--line); border-radius:7px; background:#fff; color:#59635e; font-size:8px; }.feedback-board { padding-top:18px; display:grid; grid-template-columns:minmax(0,1fr) minmax(0,1fr); gap:16px; align-items:start; }.feedback-board.single { grid-template-columns:minmax(0,760px); }.feedback-lane { min-width:0; overflow:hidden; border:1px solid #e1e6e1; border-radius:10px; background:#fff; }.feedback-lane-head { min-height:65px; padding:13px 15px; display:flex; align-items:center; justify-content:space-between; border-bottom:1px solid #e6eae6; }.feedback-lane-head > div { display:flex; flex-direction:column; gap:3px; }.feedback-lane-head span { color:#7a837e; font-size:7px; font-weight:850; letter-spacing:.11em; }.feedback-lane-head h3 { margin:0; font:700 13px var(--font-display); }.feedback-lane-head > strong { width:27px; height:27px; display:grid; place-items:center; border-radius:50%; background:#eef1ed; color:#66716b; font-size:8px; }.feedback-resolved-lane { border-color:#cfe1d4; background:#f1f8f3; }.feedback-resolved-lane .feedback-lane-head { border-color:#d7e7dc; }.feedback-resolved-lane .feedback-lane-head span,.feedback-resolved-lane .feedback-lane-head h3 { color:#347151; }.feedback-resolved-lane .feedback-lane-head > strong { background:#d9ebdf; color:#2f6a4a; }.feedback-canceled-lane { background:#fafaf8; }.feedback-lane .feedback-block { margin:0 12px; }.feedback-lane .feedback-block-main { min-height:0; padding:15px 2px; display:grid; grid-template-columns:1fr; gap:10px; }.feedback-lane .feedback-block-main:hover { background:transparent; }.feedback-lane .feedback-block-main > p { margin:0; font-size:12px; line-height:1.6; }.feedback-lane .feedback-block-actions { min-width:0; justify-content:flex-start; opacity:1; }.feedback-lane .feedback-block-actions button:first-child { padding-left:0; }.feedback-lane .feedback-thread { margin:0 2px 15px 36px; }.feedback-resolved-lane .feedback-block.resolved { opacity:1; }.feedback-resolved-lane .feedback-block-main:hover { background:rgba(255,255,255,.35); }.feedback-author { flex-wrap:wrap; }.feedback-status { margin-left:auto; padding:3px 6px; display:inline-flex; align-items:center; gap:3px; border-radius:10px; color:#6c756f; background:#eef0ed; font-size:6px; font-weight:850; font-style:normal; letter-spacing:.04em; text-transform:uppercase; }.feedback-status.resolved { color:#2f6a4a; background:#dcece1; }.feedback-status.canceled { color:#8a6964; background:#f2e8e5; }.feedback-lane-empty { min-height:145px; margin:0; display:grid; place-items:center; color:var(--muted); font-size:8px; }.feedback-empty.filtered { min-height:220px; }.feedback-board + .feedback-history { margin-top:16px; }

/* Batch 1: sipariş filtreleri, teslimat hedefleri ve Excel dışa aktarımı */
