.delivery-milestone-row .delete-button { margin-bottom:2px; }
/* Verified delivery export: bounded dialog, readable fields and report states. */
.delivery-export-backdrop { padding:20px; }
.delivery-export-dialog { width:min(680px,100%); max-height:calc(100dvh - 40px); display:flex; flex-direction:column; overflow:hidden; border:1px solid #d4e1da; border-top:4px solid #287052; border-radius:12px; background:#fff; box-shadow:0 24px 70px rgba(24,32,29,.22); font-size:13px; line-height:1.5; }
.delivery-export-head { flex-shrink:0; padding:24px; display:grid; grid-template-columns:44px minmax(0,1fr) 30px; align-items:start; gap:14px; border-bottom:1px solid var(--line); }
