.delivery-export-dialog input:disabled { background:#f5f7f4; color:var(--muted); }
.delivery-export-section-head { display:flex; flex-wrap:wrap; align-items:center; justify-content:space-between; gap:8px; margin-bottom:12px; }
.delivery-export-verified { display:inline-flex; gap:5px; align-items:center; color:#287052; font-size:11px; font-weight:650; }
.delivery-export-placeholder { margin:0; padding:18px; border:1px dashed #cfd9d2; border-radius:8px; background:#fafcf9; color:var(--muted); font-size:12px; line-height:1.7; }
