.delivery-export-notice.warning { background:#fff6e6; color:#805d23; }
.delivery-export-preview > .delivery-export-notice + .delivery-export-notice { margin-top:10px; }
.delivery-export-blockers { margin-top:14px; padding:14px; border:1px solid #ebd5b0; border-radius:8px; background:#fffbf3; color:#805d23; font-size:12px; }
