.advice-machine-picker-head { margin-bottom:8px; display:flex; align-items:flex-start; justify-content:space-between; gap:10px; }.advice-machine-picker-head > span { display:flex; flex-direction:column; gap:2px; }.advice-machine-picker-head strong { font-size:8px; }.advice-machine-picker-head small { color:var(--muted); font-size:7px; }.advice-machine-picker-head > b { padding:3px 6px; border-radius:10px; background:#e5efeb; color:#476259; font-size:6px; white-space:nowrap; }
.advice-machine-options { display:grid; grid-template-columns:1fr 1fr; gap:5px; }.advice-machine-options > button { min-width:0; min-height:58px; padding:7px 8px; display:grid; grid-template-columns:minmax(0,1fr) auto; grid-template-rows:auto auto; gap:4px 6px; border:1px solid #dce3df; border-radius:7px; background:#fff; color:var(--ink); text-align:left; cursor:pointer; transition:border-color .14s,background .14s,box-shadow .14s; }.advice-machine-options > button:hover { border-color:#8db9ad; background:#f6fbf9; }.advice-machine-options > button.selected { border-color:#087a78; background:#edf8f6; box-shadow:inset 3px 0 #087a78; }.advice-machine-options > button > span:first-child { min-width:0; display:flex; flex-direction:column; gap:1px; }.advice-machine-options > button > span:first-child strong { font-size:9px; }.advice-machine-options > button > span:first-child small { overflow:hidden; color:var(--muted); font-size:6.5px; text-overflow:ellipsis; white-space:nowrap; }.advice-machine-options > button em { align-self:start; color:#78837d; font-size:6px; font-style:normal; font-weight:750; white-space:nowrap; }.advice-machine-options .queue-match,.advice-machine-options .queue-empty { grid-column:1 / -1; display:flex; align-items:center; gap:3px; color:#287052; }.advice-machine-options .queue-empty { color:#8a938e; }.advice-machine-options .queue-match small,.advice-machine-options .queue-empty small { font-size:6.5px; font-weight:700; }
.advice-position-picker { min-height:45px; margin-top:7px; padding:6px 7px 6px 9px; display:flex; align-items:center; gap:10px; border-left:3px solid #087a78; background:#fff; }.advice-position-picker > span { margin-right:auto; display:flex; flex-direction:column; gap:2px; }.advice-position-picker small { color:var(--muted); font-size:6px; }.advice-position-picker strong { font-size:8px; }.advice-position-picker select { width:min(205px,55%); min-height:31px; padding:4px 7px; border:1px solid #bfd2cc; border-radius:6px; background:#fff; color:#34433c; font-size:7px; font-weight:700; outline:0; cursor:pointer; }
