/* General dashboard */
.dashboard-layout { margin:0 30px 38px; display:grid; gap:16px; }
.dashboard-overview { padding:18px 22px; display:grid; gap:14px; border:1px solid #cfd9d5; background:#fff; }
.dashboard-overview-header { display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:10px 18px; }.dashboard-overview-header h2 { margin:0; font:700 15px/1.3 var(--font-display); letter-spacing:-.02em; }
