.capacity-body { padding:18px 24px 30px; display:grid; grid-template-columns:minmax(480px,1.08fr) minmax(390px,.92fr); gap:16px; }.capacity-ranking,.capacity-detail { min-width:0; border:1px solid var(--line); background:#fff; }.capacity-section-head { min-height:58px; padding:11px 13px; display:flex; align-items:center; justify-content:space-between; gap:12px; border-bottom:1px solid var(--line); }.capacity-section-head > div:first-child { display:flex; flex-direction:column; gap:3px; }.capacity-section-head strong { font:700 12px var(--font-display); }.capacity-section-head span { color:var(--muted); font-size:7px; }.capacity-legend { display:flex; align-items:center; gap:5px; color:var(--muted); font-size:7px; }.capacity-legend i { width:12px; height:6px; display:block; }.capacity-legend i.normal { background:#315c79; }.capacity-legend i.overtime { margin-left:6px; background:#d36b22; }
