.journey-job-list em.journey-status-running { background:#e8f4ef; color:#23755d; }
.journey-job-list em.journey-status-finishing { background:#eaf1f7; color:#315a7a; }
.journey-job-list em.journey-status-delivered { background:#dff2e7; color:#17664f; }
.journey-job-list em.journey-status-attention { background:#fff2f0; color:#94463f; }
.journey-canvas { min-width:0; padding:18px; overflow:auto; background:#fff; }
.journey-heading { min-width:760px; padding-bottom:16px; display:flex; align-items:flex-end; justify-content:space-between; gap:24px; border-bottom:1px solid var(--line); }
