.journey-heading-actions { display:flex; align-items:stretch; gap:9px; }.journey-heading-actions > .journey-complete-action { min-width:155px; margin:0; align-self:stretch; }.journey-heading-actions > .journey-complete-hint { max-width:150px; margin:0; align-self:center; }
