.flow-settings-fields td input:not([type="number"]):not([type="checkbox"]) { width: 220px; }
.flow-settings-fields td { padding: 12px; vertical-align: middle; }
.flow-settings-fields td small { display: block; color: var(--muted); font-size: 10px; margin-top: 5px; }
.flow-settings-fields table { min-width: 1040px; font-size: 12px; }
.flow-settings-fields .settings-disclosure table { min-width: 640px; }
.flow-settings-fields th { font-size: 10px; letter-spacing: .045em; }
.flow-activation-status { display: flex; flex-wrap: wrap; align-items: baseline; gap: 8px 20px; margin-bottom: 20px; padding: 16px 18px; border: 1px solid #cfe1d9; border-left: 3px solid #087a78; border-radius: 8px; background: #f3f9f6; font-size: 12px; line-height: 1.6; }
.flow-activation-status strong { font-size: 13px; color: #075f5c; }
.flow-activation-status span:last-child { flex-basis: 100%; color: var(--muted); }
.settings-disclosure { border: 1px solid var(--line); border-radius: 8px; margin: 18px 0; overflow: hidden; }
.settings-disclosure > summary { padding: 14px 16px; background: #f7f9f6; cursor: pointer; font-size: 13px; font-weight: 650; }
.settings-disclosure > .settings-help { margin: 16px 20px 0; }
.settings-toggle { display: flex; align-items: center; gap: 10px; margin: 24px 0 12px; font-size: 13px; font-weight: 650; }
.settings-field { display: grid; width: min(320px, 100%); gap: 8px; font-size: 12px; font-weight: 650; }
.flow-calendar-row { display: flex; gap: 10px; flex-wrap: wrap; margin: 12px 0; }
.flow-setup-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 18px; margin: 22px 0 26px; }
.flow-setup-grid label { display: grid; align-content: start; gap: 8px; font-size: 12px; font-weight: 600; }
.flow-setup-grid small { color: var(--muted); font-size: 10px; font-weight: 400; }
.settings-save-actions { padding-top: 20px; margin-top: 24px; border-top: 1px solid var(--line); justify-content: flex-end; }
.flow-review { padding: 18px 20px; border: 1px solid #cfe1d9; border-radius: 8px; margin-top: 20px; background: #f5faf7; }
.flow-review h3 { margin: 0 0 10px; font-size: 15px; }
.settings-message { padding: 12px 16px; border-radius: 7px; background: #f3f8f5; font-size: 13px; line-height: 1.6; }
.settings-message.error { background: #fff1ed; color: #9e3524; }
.settings-fallback { margin: 20px 0; background: #fff; }
.piston-settings-page .process-wait-settings { padding: 20px; border: 0; box-shadow: none; margin: 0; border-radius: 0; }
.piston-settings-page .process-wait-settings h3 { margin: 0 0 10px; font-size: 16px; }
.piston-settings-page .process-wait-settings p { font-size: 13px; color: var(--muted); line-height: 1.65; }
.piston-settings-page .process-wait-settings th, .piston-settings-page .process-wait-settings td { padding: 13px 16px; }
.piston-settings-page .process-wait-settings table { min-width: 520px; font-size: 12px; margin: 18px 0; }
.piston-settings-page .process-wait-settings .table-scroll { overflow-x: auto; }
@media (max-width: 760px) {
  .flow-settings-panel { padding: 16px; }
  .flow-settings-panel .settings-panel-heading { flex-direction: column; gap: 16px; }
  .flow-setup-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .settings-save-actions { flex-wrap: wrap; }
  .settings-save-actions button { flex: 1; }
  .piston-settings-page .settings-tabs > button { padding: 12px; }
}
@media (prefers-reduced-motion: reduce) { .flow-settings-panel button, .piston-settings-page .process-wait-settings button { transition: none; } }
.planning-save-status { margin:12px 0; padding:12px 16px; display:flex; flex-wrap:wrap; align-items:center; justify-content:space-between; gap:12px; border:1px solid var(--line); border-radius:8px; background:#f4f7f5; }
.planning-save-status > div:first-child { display:grid; gap:4px; }
.planning-save-status strong { font-size:12px; }
.planning-save-status small, .planning-save-status p { margin:0; font-size:11px; line-height:1.5; }
.planning-save-status.offline, .planning-save-status.conflict { background:#fff4e8; border-color:#b8732e; }
.planning-save-status.saving { background:#eff6ff; border-color:#7e9dbc; }
.planning-save-actions { display:flex; flex-wrap:wrap; gap:8px; }

/* Plan scope and save status stay in the navigation, above the working canvas. */
.plan-nav-card { position:relative; display:flex; align-items:center; gap:4px; flex-shrink:0; border:1px solid #dce5df; border-radius:10px; padding:3px; background:#f7faf8; color:#24382c; }
.plan-nav-toggle { display:flex; align-items:center; gap:12px; padding:4px 8px; background:transparent; border:0; text-align:left; color:inherit; cursor:pointer; }
.plan-nav-copy { display:grid; gap:3px; }
.plan-nav-copy strong { font-size:12px; line-height:1.2; }
.plan-nav-status { display:flex; align-items:center; gap:5px; font-size:10px; line-height:1.2; color:#52665a; white-space:nowrap; }
.plan-nav-status i { width:5px; height:5px; border-radius:50%; background:#34835a; }
.plan-nav-status i.warning { background:#b67420; }
.plan-nav-status i.saving { background:#487da8; }
.plan-nav-chevron { font-size:16px; color:#77877c; }
.plan-nav-new { padding:8px 10px; border:1px solid #dce5df; border-radius:6px; background:white; color:#294e38; font-size:11px; font-weight:600; cursor:pointer; white-space:nowrap; }
.plan-nav-card.has-error { background:#fff8ef; border-color:#d7ae77; }
.plan-nav-panel { position:absolute; top:calc(100% + 10px); right:0; width:340px; max-width:calc(100vw - 24px); padding:16px; display:grid; gap:14px; border:1px solid var(--line); border-radius:12px; background:white; box-shadow:0 12px 36px #18332424; color:var(--ink); z-index:30; max-height:calc(100dvh - 100px); overflow:auto; }
.plan-nav-panel strong { font-size:13px; overflow-wrap:anywhere; }
.plan-nav-panel p { margin:5px 0 0; font-size:12px; line-height:1.5; }
.plan-nav-description p, .plan-nav-connection { color:#65736a; }
.plan-nav-connection { font-size:10px; line-height:1.5; }
.plan-nav-options { display:grid; gap:5px; }
.plan-nav-options > button, .plan-nav-more > button { text-align:left; padding:9px 10px; border:1px solid var(--line); border-radius:6px; background:#f7faf8; color:#294e38; font-size:12px; cursor:pointer; }
.plan-nav-options > button.primary { background:#294e38; color:white; }
.plan-nav-recovery { padding:12px; border:1px solid #e4c39b; border-radius:8px; background:#fff8ef; }
.plan-nav-recovery-actions { display:flex; gap:8px; margin-top:12px; }
.plan-nav-recovery-actions button, .plan-nav-retain button { font-size:11px; padding:8px 10px; }
.plan-nav-error-detail { color:#775632; overflow-wrap:anywhere; }
.plan-nav-retain { margin-top:12px; }
.plan-nav-retain summary, .plan-nav-more summary { font-size:12px; cursor:pointer; }
.plan-nav-retain button, .plan-nav-more > button { margin-top:10px; }
.plan-nav-card button:disabled { opacity:.5; cursor:not-allowed; }
.plan-nav-card button:focus-visible, .plan-nav-card summary:focus-visible { outline:2px solid #43805b; outline-offset:3px; }
@media (max-width:700px) { .plan-nav-panel { position:fixed; top:112px; right:12px; left:12px; width:auto; max-width:none; max-height:calc(100dvh - 124px); } }
.plan-nav-approval { padding:10px 12px; background:#f5f8f6; border:1px solid #e2e9e4; border-radius:8px; }
.plan-nav-approval > strong { font-size:11px; color:#65736a; }
.plan-nav-approval .plan-nav-approver { font-weight:600; }
.plan-nav-approval small { display:block; margin-top:4px; font-size:11px; line-height:1.5; color:#65736a; }
.plan-nav-guide { border-top:1px solid var(--line); padding-top:12px; }
.plan-nav-guide summary { cursor:pointer; font-size:12px; font-weight:600; color:#294e38; }
.plan-nav-guide .plan-guide-steps { list-style:none; margin:14px 0; padding:0; display:grid; gap:14px; }
.plan-guide-steps li { display:flex; align-items:flex-start; gap:10px; }
.plan-guide-number { width:24px; height:24px; flex-shrink:0; display:grid; place-items:center; border-radius:50%; background:#edf3ef; color:#456452; font-size:11px; font-weight:600; }
.plan-guide-steps li > div { display:grid; gap:4px; min-width:0; }
.plan-guide-steps li > div > span { color:#65736a; font-size:11px; line-height:1.5; }
.plan-guide-steps em { margin-left:4px; padding:2px 5px; border-radius:4px; background:#f0f2f1; color:#667169; font-size:9px; font-style:normal; font-weight:500; }
.plan-nav-guide .plan-guide-note { padding:8px 10px; border-left:2px solid #81a18d; background:#f5f8f6; font-size:11px; color:#456452; }
.plan-guide-notes { margin-top:12px; }
.plan-nav-guide .plan-guide-notes summary { font-size:11px; font-weight:400; color:#65736a; }
.plan-guide-notes ul { padding-left:16px; margin:10px 0 0; display:grid; gap:9px; font-size:11px; line-height:1.5; color:#65736a; }
.plan-nav-guide li strong, .plan-nav-guide p strong { font-size:12px; }
.plan-nav-guide button { margin-top:12px; font-size:12px; }

.sync-conflict-error { margin:0 24px 18px; padding:12px; border-left:3px solid var(--red); background:#fff0ee; color:#7d302b; font-size:12px; line-height:1.5; }

