"use client";

import type { ReactNode } from "react";
import { CheckCircle } from "@phosphor-icons/react";
import { Field } from "@/features/planning/shared/controls";
import { formatInteger as formatNumber } from "@/lib/number-format";

export type DeliveryAllocationDraft = {
  actualQuantity: number;
  completedDate: string;
  deliveredQuantity: number;
  deliveryDate: string;
  remainderAction: "keep" | "scrap";
};

export function DeliveryAllocationForm({ product, draft, onChange, error, onClose, onSave, children }: {
  product: string; draft: DeliveryAllocationDraft; onChange: (draft: DeliveryAllocationDraft) => void;
  error: string; onClose: () => void; onSave: () => void; children?: ReactNode;
}) {
  const remainder = Math.max(0, draft.actualQuantity - draft.deliveredQuantity);
  return <section className="completion-dialog archive-action-dialog archive-allocation-dialog" role="dialog" aria-modal="true" aria-label={`${product} teslimat ve ıskarta ayrımı`}>
    <CheckCircle size={24} />
    <span>FİİLİ ÜRETİM VE TESLİMAT</span>
    <h2>{product}</h2>
    <p>Gerçek tamamlanan adedi girin. Teslim edilen kısmı ayırın; kalan miktarı yarı mamulde tutun veya ıskartaya çevirin.</p>
    <div className="archive-allocation-grid">
      <Field label="Fiili tamamlanan adet">
        <input type="number" min="1" step="1" value={draft.actualQuantity || ""} onChange={(event) => onChange({ ...draft, actualQuantity: Number(event.target.value), deliveredQuantity: Math.min(draft.deliveredQuantity, Number(event.target.value)) })} />
      </Field>
      <Field label="Gerçek tamamlanma tarihi">
        <input type="date" value={draft.completedDate} onChange={(event) => onChange({ ...draft, completedDate: event.target.value })} />
      </Field>
      <Field label="Teslim edilen adet">
        <input type="number" min="0" max={draft.actualQuantity} step="1" value={draft.deliveredQuantity} onChange={(event) => onChange({ ...draft, deliveredQuantity: Number(event.target.value) })} />
      </Field>
      <Field label="Teslim tarihi ve saati">
        <input type="datetime-local" disabled={draft.deliveredQuantity === 0} value={draft.deliveryDate} onChange={(event) => onChange({ ...draft, deliveryDate: event.target.value })} />
      </Field>
    </div>
    {children}
    <div className="archive-remainder">
      <span><small>Kalan miktar</small><strong>{formatNumber(remainder)} adet</strong></span>
      {remainder > 0 && <div role="radiogroup" aria-label="Kalan miktar işlemi">
        <label>
          <input type="radio" name="remainder-action" checked={draft.remainderAction === "keep"} onChange={() => onChange({ ...draft, remainderAction: "keep" })} />
          <span><strong>Yarı mamulde bırak</strong><small>Sonraki teslimatta kullanılabilir</small></span>
        </label>
        <label className="scrap-choice">
          <input type="radio" name="remainder-action" checked={draft.remainderAction === "scrap"} onChange={() => onChange({ ...draft, remainderAction: "scrap" })} />
          <span><strong>Iskartaya ayır</strong><small>Iskartalar listesinde izlenir</small></span>
        </label>
      </div>}
    </div>
    {error && <p className="archive-export-error" role="alert">{error}</p>}
    <div className="drawer-actions">
      <button className="secondary" onClick={onClose}>Vazgeç</button>
      <button className="primary" disabled={!draft.actualQuantity || !draft.completedDate || draft.deliveredQuantity > draft.actualQuantity || (draft.deliveredQuantity > 0 && !draft.deliveryDate)} onClick={onSave}>
        <CheckCircle size={15} /> Teslimat ayrımını kaydet
      </button>
    </div>
  </section>;
}

frontend/components/FeedbackFeature.tsx.source:
"use client";

import { useRaviScreenContext } from "@/features/ravi/context";

import { useCallback, useEffect, useRef, useState, type ClipboardEvent } from "react";
import { createPortal } from "react-dom";
import { CaretLeft, CaretRight, Check, ChatCenteredText, FileText, ImageSquare, MagnifyingGlass, Microphone, PaperPlaneTilt, PencilSimple, Trash, X } from "@phosphor-icons/react";
import { useApiFetch, type ApiFetch } from "@/lib/api";
import { compareFeedbackPriority, feedbackPriority, hiddenFeedbackCommentCount, isFeedbackDocumentName, visibleFeedbackComments, type FeedbackPriority } from "@/lib/feedback";
import { formatInteger } from "@/lib/number-format";

type FeedbackStatus = "active" | "resolved" | "canceled";
type FeedbackComment = { id: string; author_name: string; body: string; created_at: string; updated_at: string };
type FeedbackAttachment = { id: string; kind: "image" | "voice" | "document"; original_name: string; content_type: string; size: number; url: string };
type FeedbackItem = {
  id: string; author_name: string; body: string; status: FeedbackStatus; priority?: FeedbackPriority; created_at: string; updated_at: string;
  comments: FeedbackComment[]; attachments: FeedbackAttachment[];
};

const PRIORITY_LABELS: Record<FeedbackPriority, string> = { 1: "Yüksek", 2: "Normal", 3: "Düşük" };
function isDocument(file: File): boolean {
  return isFeedbackDocumentName(file.name);
}

export function FeedbackFeature({ pagePath, workspace }: { pagePath: string; workspace: boolean }) {
  const apiFetch = useApiFetch();
  const [items, setItems] = useState<FeedbackItem[]>([]);
  const [composerOpen, setComposerOpen] = useState(false);
  const [composerCollapsed, setComposerCollapsed] = useState(false);
  const [composerPagePath, setComposerPagePath] = useState(pagePath);
  const [loading, setLoading] = useState(true);
  useRaviScreenContext("feedback-panel", { workspace, composerOpen, composerPagePath });
  const [headerPortalReady, setHeaderPortalReady] = useState(false);

  function openComposer() {
    setComposerPagePath(pagePath);
    setComposerCollapsed(false);
    setComposerOpen(true);
  }

  const reload = useCallback(async () => {
    const response = await apiFetch("/feedbacks");
    if (!response.ok) throw new Error("Geri bildirimler yüklenemedi");
    setItems(await response.json() as FeedbackItem[]);
    setLoading(false);
  }, [apiFetch]);

  const updateItem = useCallback((updated: FeedbackItem) => {
    setItems((current) => current.map((item) => item.id === updated.id ? updated : item));
  }, []);

  useEffect(() => { void reload().catch(() => setLoading(false)); }, [reload]);
  useEffect(() => setHeaderPortalReady(true), []);

  const headerActionTarget = headerPortalReady ? document.getElementById("feedback-header-action") : null;

  return <>
    {workspace && <FeedbackWorkspace items={items} loading={loading} apiFetch={apiFetch} reload={reload} onItemUpdated={updateItem} onCompose={openComposer} />}
    {!composerOpen && headerActionTarget && createPortal(<button className="feedback-header-launch" onClick={openComposer} aria-label="Geri bildirim paylaş" title="Geri bildirim paylaş"><ChatCenteredText size={17} weight="fill" /></button>, headerActionTarget)}
    {composerOpen && <FeedbackComposer pagePath={composerPagePath} apiFetch={apiFetch} collapsed={composerCollapsed} onCollapse={() => setComposerCollapsed(true)} onExpand={() => setComposerCollapsed(false)} onClose={() => { setComposerOpen(false); setComposerCollapsed(false); }} onCreated={async () => { await reload(); setComposerOpen(false); setComposerCollapsed(false); }} />}
  </>;
}

function FeedbackComposer({ pagePath, apiFetch, collapsed, onCollapse, onExpand, onClose, onCreated }: { pagePath: string; apiFetch: ApiFetch; collapsed: boolean; onCollapse: () => void; onExpand: () => void; onClose: () => void; onCreated: () => Promise<void> }) {
  const [body, setBody] = useState("");
  const [priority, setPriority] = useState<FeedbackPriority>(2);
  const [files, setFiles] = useState<File[]>([]);
  const [voice, setVoice] = useState<File | null>(null);
  const [recording, setRecording] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const recorder = useRef<MediaRecorder | null>(null);
  const chunks = useRef<Blob[]>([]);

  useEffect(() => {
    const closeOnEscape = (event: KeyboardEvent) => { if (event.key === "Escape") onClose(); };
    window.addEventListener("keydown", closeOnEscape);
    return () => window.removeEventListener("keydown", closeOnEscape);
  }, [onClose]);

  function addFiles(nextFiles: File[]) {
    const supported = nextFiles.filter((file) => file.type.startsWith("image/") || isDocument(file));
    if (!supported.length) {
      setError("Görsel, Excel, Word, PDF, RTF, ODT veya metin belgesi seçin.");
      return;
    }
    setFiles((current) => [...current, ...supported].filter((file, index, all) => all.findIndex((item) => item.name === file.name && item.size === file.size && item.lastModified === file.lastModified) === index));
    setError("");
  }

  function pasteImages(event: ClipboardEvent<HTMLTextAreaElement>) {
    const images = Array.from(event.clipboardData.items)
      .filter((item) => item.type.startsWith("image/"))
      .map((item, index) => {
        const image = item.getAsFile();
        return image ? new File([image], `ekran-goruntusu-${Date.now()}-${index + 1}.${image.type.split("/")[1] || "png"}`, { type: image.type }) : null;
      })
      .filter((file): file is File => file !== null);
    if (images.length) { event.preventDefault(); addFiles(images); }
  }

  async function toggleRecording() {
    if (recording && recorder.current) { recorder.current.stop(); return; }
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const nextRecorder = new MediaRecorder(stream);
      chunks.current = [];
      nextRecorder.ondataavailable = (event) => { if (event.data.size) chunks.current.push(event.data); };
      nextRecorder.onstop = () => {
        const blob = new Blob(chunks.current, { type: nextRecorder.mimeType || "audio/webm" });
        setVoice(new File([blob], `sesli-not-${Date.now()}.webm`, { type: blob.type }));
        stream.getTracks().forEach((track) => track.stop());
        setRecording(false);
      };
      recorder.current = nextRecorder;
      nextRecorder.start();
      setRecording(true);
    } catch { setError("Mikrofon açılamadı. Tarayıcı mikrofon iznini kontrol edin."); }
  }

  async function submit() {
    if (!body.trim() && !voice && files.length === 0) { setError("Bir not yazın, görsel veya belge ekleyin ya da sesli not kaydedin."); return; }
    setSaving(true); setError("");
    try {
      const fallbackBody = voice ? "Sesli geri bildirim" : files.some(isDocument) ? "Belgeli geri bildirim" : "Görsel geri bildirim";
      const createdResponse = await apiFetch("/feedbacks", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ body: body.trim() || fallbackBody, page_path: pagePath, priority }) });
      if (!createdResponse.ok) throw new Error("Geri bildirim kaydedilemedi");
      const created = await createdResponse.json() as FeedbackItem;
      const uploads = [...files, ...(voice ? [voice] : [])];
      if (uploads.length) {
        const form = new FormData();
        uploads.forEach((file) => form.append("files", file));
        const uploadResponse = await apiFetch(`/feedbacks/${created.id}/attachments`, { method: "POST", body: form });
        if (!uploadResponse.ok) throw new Error("Not kaydedildi ancak ekler yüklenemedi");
      }
      await onCreated();
    } catch (caught) { setError(caught instanceof Error ? caught.message : "Geri bildirim kaydedilemedi"); }
    finally { setSaving(false); }
  }

  if (collapsed) {
    const attachmentCount = files.length + (voice ? 1 : 0);
    return <div className="feedback-composer-collapsed" role="region" aria-label="Daraltılmış geri bildirim taslağı"><button className="feedback-draft-expand" onClick={onExpand}><CaretLeft size={15} weight="bold" /><ChatCenteredText size={18} weight="fill" /><span><strong>Geri bildirim taslağı</strong><small>{body.trim() ? `${body.trim().slice(0, 42)}${body.trim().length > 42 ? "…" : ""}` : attachmentCount ? `${attachmentCount} ek hazır` : `${pagePath} · yazmaya devam et`}</small></span></button><button className="feedback-draft-close" onClick={onClose} aria-label="Geri bildirim taslağını kapat"><X size={14} /></button></div>;
  }

  return <div className="feedback-overlay" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><aside className="feedback-composer" role="dialog" aria-modal="true" aria-label="Geri bildirim paylaş"><div className="feedback-composer-head"><div><span>SELSA PLANLAMA İÇİN</span><h2>Planlamayı birlikte geliştirelim</h2><p>Düşüncelerinizi paylaşın, özellik isteyin, hata bildirin veya iyileştirme fikrinizi iletin.</p></div><div className="feedback-composer-head-actions"><button aria-label="Geri bildirim penceresini daralt" title="Daralt ve uygulamada gezin" onClick={onCollapse}><CaretRight size={18} /></button><button aria-label="Geri bildirim penceresini kapat" onClick={onClose}><X size={18} /></button></div></div><textarea autoFocus value={body} onPaste={pasteImages} onChange={(event) => setBody(event.target.value)} placeholder="Notunuzu yazın. Ekran görüntüsünü buraya yapıştırabilir; görsel, Excel, belge veya ses ekleyebilirsiniz." /><div className="feedback-priority-picker" role="radiogroup" aria-label="Geri bildirim önceliği"><span>Öncelik</span>{([1, 2, 3] as const).map((value) => <button key={value} type="button" className={`priority-option p${value} ${priority === value ? "selected" : ""}`} aria-pressed={priority === value} onClick={() => setPriority(value)}>{PRIORITY_LABELS[value]}</button>)}</div><div className="pending-attachments">{files.map((file) => isDocument(file) ? <PendingDocument key={`${file.name}-${file.size}-${file.lastModified}`} file={file} onRemove={() => setFiles((current) => current.filter((item) => item !== file))} /> : <PendingImage key={`${file.name}-${file.size}-${file.lastModified}`} file={file} onRemove={() => setFiles((current) => current.filter((item) => item !== file))} />)}{voice && <span><Microphone size={14} />Sesli not hazır<button aria-label="Sesli notu kaldır" onClick={() => setVoice(null)}><X size={12} /></button></span>}</div>{error && <p className="feedback-error">{error}</p>}<div className="composer-actions"><label><ImageSquare size={17} /> Görsel ekle<input type="file" accept="image/*" multiple onChange={(event) => { addFiles(Array.from(event.target.files ?? [])); event.currentTarget.value = ""; }} /></label><label><FileText size={17} /> Belge / Excel ekle<input type="file" accept=".doc,.docx,.pdf,.rtf,.txt,.odt,.xls,.xlsx,.xlsm,.xlsb,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/pdf,text/plain,application/rtf,application/vnd.oasis.opendocument.text,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel.sheet.macroEnabled.12,application/vnd.ms-excel.sheet.binary.macroEnabled.12" multiple onChange={(event) => { addFiles(Array.from(event.target.files ?? [])); event.currentTarget.value = ""; }} /></label><button className={recording ? "recording" : ""} onClick={toggleRecording}><Microphone size={17} weight={recording ? "fill" : "regular"} />{recording ? "Kaydı bitir" : "Sesli not"}</button><button className="send-feedback" disabled={saving} onClick={submit}><PaperPlaneTilt size={17} weight="fill" />{saving ? "Kaydediliyor…" : "Gönder"}</button></div></aside></div>;
}

function PendingImage({ file, onRemove }: { file: File; onRemove: () => void }) {
  const [preview, setPreview] = useState("");
  useEffect(() => { const url = URL.createObjectURL(file); setPreview(url); return () => URL.revokeObjectURL(url); }, [file]);
  return <span className="pending-image">{preview && <img src={preview} alt="Eklenecek görsel önizlemesi" />}<span><ImageSquare size={14} />{file.name}</span><button aria-label={`${file.name} ekini kaldır`} onClick={onRemove}><X size={12} /></button></span>;
}

function PendingDocument({ file, onRemove }: { file: File; onRemove: () => void }) {
  return <span className="pending-document"><FileText size={18} /><span><strong>{file.name}</strong><small>{formatFileSize(file.size)}</small></span><button aria-label={`${file.name} ekini kaldır`} onClick={onRemove}><X size={12} /></button></span>;
}

function FeedbackWorkspace({ items, loading, apiFetch, reload, onItemUpdated, onCompose }: { items: FeedbackItem[]; loading: boolean; apiFetch: ApiFetch; reload: () => Promise<void>; onItemUpdated: (item: FeedbackItem) => void; onCompose: () => void }) {
  const [filter, setFilter] = useState<"all" | FeedbackStatus>("all");
  const [sort, setSort] = useState<"priority" | "updated-desc" | "created-desc" | "created-asc" | "comments-desc">("priority");
  const [query, setQuery] = useState("");
  const normalizedQuery = query.trim().toLocaleLowerCase("tr-TR");
  const filtered = items.filter((item) => (filter === "all" || item.status === filter) && (!normalizedQuery || `${item.author_name} ${item.body} ${item.comments.map((comment) => comment.body).join(" ")}`.toLocaleLowerCase("tr-TR").includes(normalizedQuery)));
  const sorted = [...filtered].sort((left, right) => {
    if (sort === "priority") return compareFeedbackPriority(left, right);
    if (sort === "created-asc") return new Date(left.created_at).getTime() - new Date(right.created_at).getTime();
    if (sort === "created-desc") return new Date(right.created_at).getTime() - new Date(left.created_at).getTime();
    if (sort === "comments-desc") return right.comments.length - left.comments.length || new Date(right.updated_at).getTime() - new Date(left.updated_at).getTime();
    return new Date(right.updated_at).getTime() - new Date(left.updated_at).getTime();
  });
  const active = sorted.filter((item) => item.status === "active");
  const resolved = sorted.filter((item) => item.status === "resolved");
  const canceled = sorted.filter((item) => item.status === "canceled");
  const counts = { active: items.filter((item) => item.status === "active").length, resolved: items.filter((item) => item.status === "resolved").length, canceled: items.filter((item) => item.status === "canceled").length };
  const showActive = filter === "all" || filter === "active";
  const showResolved = filter === "all" || filter === "resolved";
  const showCanceled = filter === "canceled";
  const renderBlocks = (values: FeedbackItem[]) => values.map((item) => <FeedbackBlock key={item.id} item={item} apiFetch={apiFetch} reload={reload} onItemUpdated={onItemUpdated} />);
  return <section className="feedback-page"><header><div><span>ORTAK NOTLAR</span><h2>Geri Bildirimler</h2><p>Açık işler ve çözülenler yan yana; aradığınızı filtreleyip sıralayabilirsiniz.</p></div><button className="primary" onClick={onCompose}><ChatCenteredText size={16} /> Yeni geri bildirim</button></header>{loading ? <p className="feedback-empty">Yükleniyor…</p> : items.length === 0 ? <div className="feedback-empty"><strong>Henüz geri bildirim yok.</strong><span>İlk notu herhangi bir sayfadaki geri bildirim düğmesinden bırakabilirsiniz.</span></div> : <><div className="feedback-toolbar"><div className="feedback-status-filters">{(["all", "active", "resolved", "canceled"] as const).map((status) => <button key={status} className={filter === status ? "selected" : ""} onClick={() => setFilter(status)}>{status === "all" ? "Tümü" : status === "active" ? "Açık" : status === "resolved" ? "Çözüldü" : "İptal"}<span>{formatInteger(status === "all" ? items.length : counts[status])}</span></button>)}</div><label className="feedback-search"><MagnifyingGlass size={14} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Notlarda ara" /></label><select value={sort} onChange={(event) => setSort(event.target.value as typeof sort)} aria-label="Geri bildirimleri sırala"><option value="priority">Önceliğe göre</option><option value="updated-desc">Son güncellenen</option><option value="created-desc">En yeni</option><option value="created-asc">En eski</option><option value="comments-desc">En çok yorumlanan</option></select></div>{sorted.length === 0 ? <div className="feedback-empty filtered"><strong>Bu filtrede kayıt yok.</strong><span>Aramayı veya durum filtresini değiştirebilirsiniz.</span></div> : <><div className={`feedback-board ${filter !== "all" ? "single" : ""}`}>{showActive && <section className="feedback-lane feedback-active-lane"><div className="feedback-lane-head"><div><span>AÇIK</span><h3>Üzerinde çalışılanlar</h3></div><strong>{formatInteger(active.length)}</strong></div><div className="feedback-document">{active.length ? renderBlocks(active) : <p className="feedback-lane-empty">Açık geri bildirim yok.</p>}</div></section>}{showResolved && <section className="feedback-lane feedback-resolved-lane"><div className="feedback-lane-head"><div><span>ÇÖZÜLDÜ</span><h3>Tamamlanan iyileştirmeler</h3></div><strong>{formatInteger(resolved.length)}</strong></div><div className="feedback-document">{resolved.length ? renderBlocks(resolved) : <p className="feedback-lane-empty">Henüz çözülen geri bildirim yok.</p>}</div></section>}{showCanceled && <section className="feedback-lane feedback-canceled-lane"><div className="feedback-lane-head"><div><span>İPTAL</span><h3>İptal edilen kayıtlar</h3></div><strong>{formatInteger(canceled.length)}</strong></div><div className="feedback-document">{renderBlocks(canceled)}</div></section>}</div>{filter === "all" && canceled.length > 0 && <details className="feedback-history"><summary>İptal edilen kayıtlar · {formatInteger(canceled.length)}</summary><div className="feedback-document closed">{renderBlocks(canceled)}</div></details>}</>}</>}</section>;
}

function FeedbackBlock({ item, apiFetch, reload, onItemUpdated }: { item: FeedbackItem; apiFetch: ApiFetch; reload: () => Promise<void>; onItemUpdated: (item: FeedbackItem) => void }) {
  const [expanded, setExpanded] = useState(false);
  const [editing, setEditing] = useState(false);
  const [body, setBody] = useState(item.body);
  const [comment, setComment] = useState("");
  const [savingPriority, setSavingPriority] = useState(false);
  const [actionError, setActionError] = useState("");

  async function patch(payload: object) {
    setActionError("");
    const response = await apiFetch(`/feedbacks/${item.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) });
    if (!response.ok) throw new Error("Değişiklik kaydedilemedi. Lütfen tekrar deneyin.");
    const updated = await response.json() as FeedbackItem;
    onItemUpdated(updated);
    return updated;
  }
  async function changePriority(value: FeedbackPriority) {
    if (value === feedbackPriority(item) || savingPriority) return;
    setSavingPriority(true);
    try { await patch({ priority: value }); }
    catch (error) { setActionError(error instanceof Error ? error.message : "Öncelik kaydedilemedi."); }
    finally { setSavingPriority(false); }
  }
  async function addComment() { if (!comment.trim()) return; await apiFetch(`/feedbacks/${item.id}/comments`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ body: comment.trim() }) }); setComment(""); await reload(); }

  const currentPriority = feedbackPriority(item);
  const visibleComments = visibleFeedbackComments(item.comments, expanded);
  const hiddenCommentCount = hiddenFeedbackCommentCount(item.comments, expanded);
  return <article className={`feedback-block ${item.status}`}><div className="feedback-block-main" onClick={() => setExpanded((value) => !value)}><div className="feedback-author"><span>{initials(item.author_name)}</span><div><strong>{item.author_name}</strong><small>{formatDate(item.updated_at)}</small></div><em className={`feedback-priority p${currentPriority}`}>{PRIORITY_LABELS[currentPriority]}</em><em className={`feedback-status ${item.status}`}>{item.status === "active" ? "Açık" : item.status === "resolved" ? <><Check size={10} /> Çözüldü</> : "İptal"}</em></div>{editing ? <textarea value={body} onClick={(event) => event.stopPropagation()} onChange={(event) => setBody(event.target.value)} /> : <p>{item.body}</p>}<div className="feedback-block-actions" onClick={(event) => event.stopPropagation()}><select className="feedback-priority-select" value={currentPriority} disabled={savingPriority} onChange={(event) => void changePriority(Number(event.target.value) as FeedbackPriority)} aria-label="Önceliği değiştir" aria-busy={savingPriority}>{([1, 2, 3] as const).map((value) => <option key={value} value={value}>{PRIORITY_LABELS[value]} öncelik</option>)}</select>{savingPriority && <span className="feedback-priority-saving">Kaydediliyor…</span>}{editing ?<><button onClick={async () => { try { await patch({ body }); setEditing(false); } catch (error) { setActionError(error instanceof Error ? error.message : "Değişiklik kaydedilemedi."); } }}><Check size={15} /> Kaydet</button><button onClick={() => { setBody(item.body); setEditing(false); }}><X size={15} /> Vazgeç</button></> : <><button onClick={() => setEditing(true)}><PencilSimple size={15} /> Düzenle</button>{item.status === "active" ? <><button onClick={() => void patch({ status: "resolved" }).catch((error) => setActionError(error instanceof Error ? error.message : "Değişiklik kaydedilemedi."))}><Check size={15} /> Çöz</button><button onClick={() => void patch({ status: "canceled" }).catch((error) => setActionError(error instanceof Error ? error.message : "Değişiklik kaydedilemedi."))}><X size={15} /> İptal et</button></> : <button onClick={() => void patch({ status: "active" }).catch((error) => setActionError(error instanceof Error ? error.message : "Değişiklik kaydedilemedi."))}>Yeniden aç</button>}</>}</div>{actionError && <p className="feedback-action-error" role="alert">{actionError}</p>}</div>{(expanded || visibleComments.length > 0) && <div className={`feedback-thread ${expanded ? "expanded" : "preview"}`}>{expanded && <AttachmentList item={item} apiFetch={apiFetch} reload={reload} />}{visibleComments.map((entry) => <CommentRow key={entry.id} comment={entry} apiFetch={apiFetch} reload={reload} />)}{hiddenCommentCount > 0 && <button className="feedback-more-comments" onClick={() => setExpanded(true)}>+{hiddenCommentCount} yorum daha göster</button>}{expanded && <div className="comment-composer"><textarea value={comment} onChange={(event) => setComment(event.target.value)} placeholder="Yorum yazın…" /><button aria-label="Yorumu gönder" onClick={addComment}><PaperPlaneTilt size={16} weight="fill" /></button></div>}</div>}</article>;
}

function CommentRow({ comment, apiFetch, reload }: { comment: FeedbackComment; apiFetch: ApiFetch; reload: () => Promise<void> }) {
  const [editing, setEditing] = useState(false);
  const [body, setBody] = useState(comment.body);
  async function save() { await apiFetch(`/comments/${comment.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ body }) }); setEditing(false); await reload(); }
  return <div className="comment-row"><span className="comment-avatar">{initials(comment.author_name)}</span><div><div><strong>{comment.author_name}</strong><small>{formatDate(comment.updated_at)}</small></div>{editing ? <textarea value={body} onChange={(event) => setBody(event.target.value)} /> : <p>{comment.body}</p>}</div><button aria-label="Yorumu düzenle" onClick={() => editing ? void save() : setEditing(true)}>{editing ? <Check size={14} /> : <PencilSimple size={14} />}</button></div>;
}

function AttachmentList({ item, apiFetch, reload }: { item: FeedbackItem; apiFetch: ApiFetch; reload: () => Promise<void> }) {
  if (!item.attachments.length) return null;
  return <div className="feedback-attachments">{item.attachments.map((attachment) => <Attachment key={attachment.id} value={attachment} apiFetch={apiFetch} onDelete={async () => { await apiFetch(`/attachments/${attachment.id}`, { method: "DELETE" }); await reload(); }} />)}</div>;
}

function Attachment({ value, apiFetch, onDelete }: { value: FeedbackAttachment; apiFetch: ApiFetch; onDelete: () => Promise<void> }) {
  const [url, setUrl] = useState("");
  const [error, setError] = useState("");
  const [attempt, setAttempt] = useState(0);
  const [preview, setPreview] = useState(false);
  const previewRef = useRef<HTMLDialogElement>(null);
  useRaviScreenContext(`feedback-attachment-${value.id}`, { attachmentName: value.original_name, previewOpen: preview, error });
  useEffect(() => {
    let active = true; let objectUrl = "";
    setUrl(""); setError("");
    void apiFetch(value.url).then((response) => {
      if (!response.ok) throw new Error("Ek yüklenemedi. Tekrar deneyin.");
      return response.blob();
    }).then((blob) => {
      objectUrl = URL.createObjectURL(blob);
      if (active) setUrl(objectUrl); else URL.revokeObjectURL(objectUrl);
    }).catch(() => { if (active) setError("Ek yüklenemedi. Tekrar deneyin."); });
    return () => { active = false; if (objectUrl) URL.revokeObjectURL(objectUrl); };
  }, [apiFetch, value.url, attempt]);
  useEffect(() => { if (preview) previewRef.current?.showModal(); else previewRef.current?.close(); }, [preview]);
  return <figure className={value.kind === "document" ? "document" : ""}>
    {error ? <button onClick={() => setAttempt((n) => n + 1)}>{error}</button> : !url ? <span>Ek yükleniyor…</span> : value.kind === "image" ? <button className="feedback-image-open" onClick={() => setPreview(true)} aria-label={`${value.original_name} görselini büyüt`}><img src={url} alt={value.original_name} onError={() => setError("Görsel açılamadı. Tekrar deneyin.")} /><span>Görseli büyüt</span></button> : value.kind === "voice" ? <audio controls src={url} /> : <a className="feedback-document-file" href={url} download={value.original_name}><FileText size={25} weight="duotone" /><span><strong>{value.original_name}</strong><small>{formatFileSize(value.size)} · İndir</small></span></a>}
    <figcaption><span>{value.original_name}</span><button aria-label={`${value.original_name} ekini sil`} onClick={onDelete}><Trash size={13} /></button></figcaption>
    <dialog ref={previewRef} className="feedback-image-dialog" onCancel={() => setPreview(false)} onClose={() => setPreview(false)} aria-label={`${value.original_name} görsel önizleme`}><div><strong>{value.original_name}</strong><a href={url} download={value.original_name}>İndir</a><button onClick={() => setPreview(false)} autoFocus aria-label="Görsel önizlemeyi kapat"><X size={20} /></button></div>{url && <img src={url} alt={value.original_name} />}</dialog>
  </figure>;
}

function initials(name: string) { return name.split(/\s+/).slice(0, 2).map((part) => part[0]?.toUpperCase()).join("") || "K"; }
function formatDate(value: string) { return new Intl.DateTimeFormat("tr-TR", { dateStyle: "medium", timeStyle: "short" }).format(new Date(value)); }
function formatFileSize(value: number) { return value >= 1024 * 1024 ? `${new Intl.NumberFormat("tr-TR", { maximumFractionDigits: 1 }).format(value / (1024 * 1024))} MB` : `${formatInteger(Math.max(1, Math.round(value / 1024)))} KB`; }

frontend/components/PlanControl.tsx.source:
"use client";
import { usePlanningDerivedPlan } from "@/features/planning/shared/PlanningDerivedContext";

import { useRaviScreenContext } from "@/features/ravi/context";

import { ProcessIcon } from "@/components/ProcessIcon";

import { useMemo, useState } from "react";
import { ArrowRight, CalendarBlank, CheckCircle, FileXls, Info, MagnifyingGlass, Warning, WarningCircle, X } from "@phosphor-icons/react";
import { useApiFetch } from "@/lib/api";
import { buildDashboardModel, type MachineDashboard } from "@/lib/dashboard";
import { buildGeneralOverviewExportPayload, type GeneralOverviewExportPayload, type GeneralPlanProcess } from "@/lib/general-overview";
import { buildMachineDiagnostics, type MachineDiagnostic } from "@/lib/machine-diagnostics";
import { buildPlanAudit, type AuditFinding, type AuditTarget } from "@/lib/plan-audit";
import { formatExcelDate, type PlanningSeed, type ScenarioResult } from "@/lib/planning";
import { factoryDateAfterDays, factoryDateInput } from "@/lib/factory-time";
import { formatInteger } from "@/lib/number-format";

type MachineFilter = "all" | "active" | "planned";
type OperationPlan = GeneralOverviewExportPayload["operationPlans"][number];
type OperationResource = OperationPlan["resources"][number];

const OPERATION_TABS: Array<{ process: GeneralPlanProcess; label: string }> = [
  { process: "turning", label: "Torna" },
  { process: "drilling", label: "Delme" },
  { process: "deburring", label: "Çapak Alma" },
  { process: "gkm", label: "GKM" },
];

export function PlanControl({ seed, result, dirty, onNavigate }: { seed: PlanningSeed; result: ScenarioResult; dirty: boolean; onNavigate: (target: AuditTarget) => void }) {
  const apiFetch = useApiFetch();
  const processPlan = usePlanningDerivedPlan(seed, result)!;
  const dashboard = useMemo(() => buildDashboardModel(seed, result), [result, seed]);
  const audit = useMemo(() => buildPlanAudit(seed, result, { dirty }), [dirty, result, seed]);
  const diagnostics = useMemo(() => buildMachineDiagnostics(seed, result, { dirty }), [dirty, result, seed]);
  const overview = useMemo(() => buildGeneralOverviewExportPayload(seed, result, dirty, undefined, undefined, undefined, processPlan), [dirty, result, seed, processPlan]);
  const [activeProcess, setActiveProcess] = useState<GeneralPlanProcess>("turning");
  const [query, setQuery] = useState("");
  const [filter, setFilter] = useState<MachineFilter>("all");
  const [exporting, setExporting] = useState(false);
  const [exportError, setExportError] = useState("");
  const [exportDialogOpen, setExportDialogOpen] = useState(false);
  const [exportStart, setExportStart] = useState(factoryDateInput());
  const exportEnd = exportStart ? factoryDateAfterDays(14, `${exportStart}T12:00:00`) : "";
  useRaviScreenContext("control", { activeProcess, query, filter, exportDialogOpen, exportStart, exportEnd,
    audit, calculationSource: "buildDashboardModel / buildPlanAudit / buildGeneralOverviewExportPayload" });
  const hasPlan = result.state === "planned";
  const activePlan = overview.operationPlans.find((plan) => plan.process === activeProcess) ?? overview.operationPlans[0];
  const normalizedQuery = query.trim().toLocaleLowerCase("tr-TR");
  const visibleMachines = dashboard.machines.filter((board) => {
    if (filter === "active" && !board.machine.active) return false;
    if (filter === "planned" && board.plannedCount === 0) return false;
    if (!normalizedQuery) return true;
    return `${board.machine.id} ${board.machine.name} ${board.queue.flatMap((item) => [item.product, item.workOrder]).join(" ")}`.toLocaleLowerCase("tr-TR").includes(normalizedQuery);
  });
  const visibleResources = (activePlan?.resources ?? []).filter((resource) => {
    if (filter === "planned" && resource.rows.length === 0) return false;
    if (!normalizedQuery) return true;
    return `${resource.id} ${resource.name} ${resource.rows.flatMap((item) => [item.product, item.workOrder]).join(" ")}`.toLocaleLowerCase("tr-TR").includes(normalizedQuery);
  });

  async function exportOverview() {
    setExporting(true);
    setExportError("");
    try {
      const dayCount = Math.floor((Date.parse(`${exportEnd}T00:00:00Z`) - Date.parse(`${exportStart}T00:00:00Z`)) / 86_400_000) + 1;
      if (activeProcess !== "turning" && (!exportStart || !exportEnd || dayCount !== 15)) throw new Error("Saha planı tarih aralığı 15 gün olmalıdır.");
      const payload = buildGeneralOverviewExportPayload(seed, result, dirty, new Date().toISOString(), activeProcess, activeProcess === "turning" ? { nextJobsOnly: true } : { startDate: exportStart, endDate: exportEnd });
      const response = await apiFetch("/general-overview/export", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) });
      if (!response.ok) {
        const body = await response.json().catch(() => ({})) as { detail?: string };
        throw new Error(body.detail || "Genel Bakış Excel’i oluşturulamadı.");
      }
      const blob = await response.blob();
      const disposition = response.headers.get("Content-Disposition") ?? "";
      const filename = disposition.match(/filename="([^"]+)"/)?.[1] ?? (activeProcess === "turning" ? "Torna_Saha_Plani_Siradaki_10_Is.xlsx" : `${activePlan?.label ?? "Operasyon"}_Saha_Plani_${exportStart}_${exportEnd}.xlsx`);
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement("a");
      anchor.href = url;
      anchor.download = filename;
      anchor.click();
      URL.revokeObjectURL(url);
      setExportDialogOpen(false);
    } catch (reason) {
      setExportError(reason instanceof Error ? reason.message : "Genel Bakış Excel’i oluşturulamadı.");
    } finally {
      setExporting(false);
    }
  }

  return (
    <section className="dashboard-layout">
      <div className="dashboard-overview">
        <div className="dashboard-overview-header">
          <h2>Plan özeti</h2>
          <div className={`dashboard-plan-state ${dirty ? "stale" : hasPlan ? "ready" : "empty"}`}>
            {dirty ? <Warning size={15} weight="fill" /> : hasPlan ? <CheckCircle size={15} weight="fill" /> : <Info size={15} />}
            {dirty ? "Girdiler değişti · planı yeniden çalıştırın" : hasPlan ? `Son plan: ${formatTimestamp(result.createdAt)}` : "Plan henüz çalıştırılmadı"}
          </div>
        </div>
        <div className="dashboard-kpis">
          <DashboardMetric label="Sipariş talebi" value={number(result.summary.demand)} detail="adet" />
          <DashboardMetric label="Karşılanan" value={hasPlan ? number(result.summary.planned) : "—"} detail={hasPlan ? `${percent(dashboard.coverage)} karşılama` : "hesaplanmadı"} tone="good" />
          <DashboardMetric label="Planlı şarj" value={hasPlan ? number(result.summary.plannedBatchCount) : "—"} detail={`${number(dashboard.plannedMachineCount)} tezgaha dağıtıldı`} />
          <DashboardMetric label="Aktif tezgah" value={`${number(dashboard.activeMachineCount)} / ${number(seed.machines.length)}`} detail={`${number(dashboard.machinesWithWorkCount)} tezgah iş gösteriyor`} />
        </div>
      </div>

      <div className="dashboard-board">
        <div className="dashboard-operation-tabs" role="tablist" aria-label="Genel plan operasyonu">
          {OPERATION_TABS.map((tab) => {
            const plan = overview.operationPlans.find((item) => item.process === tab.process);
            return <button key={tab.process} role="tab" aria-selected={activeProcess === tab.process} className={activeProcess === tab.process ? "active" : ""} onClick={() => { setActiveProcess(tab.process); setQuery(""); setFilter("all"); }}><span><ProcessIcon process={tab.process} /> {tab.label}</span><small>{number(plan?.totalJobCount ?? 0)} iş</small><b>{number(plan?.totalQuantity ?? 0)} adet</b></button>;
          })}
        </div>
        <div className="dashboard-toolbar">
          <div><strong><ProcessIcon process={activeProcess} /> {activePlan?.label ?? "Operasyon"} genel planı</strong><span>{activeProcess === "turning" ? `${number(visibleMachines.length)} tezgah` : `${number(visibleResources.length)} istasyon`} · {number(activePlan?.totalJobCount ?? 0)} iş · {number(activePlan?.totalQuantity ?? 0)} adet</span></div>
          <div className="dashboard-tools">
            <button className="dashboard-export" disabled={exporting} onClick={() => { setExportError(""); setExportDialogOpen(true); }} title={activeProcess === "turning" ? "Her torna tezgâhındaki sıradaki 10 işi yazdır" : `Yalnızca ${activePlan?.label ?? "seçili operasyon"} için 15 günlük yazdırılabilir saha planı hazırla`}><FileXls size={15} />{exporting ? "Hazırlanıyor…" : `${activePlan?.label ?? "Operasyon"} saha planı`}</button>
            <label className="dashboard-search"><MagnifyingGlass size={15} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="İstasyon, ürün veya şarj no ara" /></label>
            <div className="dashboard-filters" aria-label="Plan filtresi">
              <FilterButton active={filter === "all"} onClick={() => setFilter("all")}>Tümü</FilterButton>
              {activeProcess === "turning" && <FilterButton active={filter === "active"} onClick={() => setFilter("active")}>Aktif</FilterButton>}
              <FilterButton active={filter === "planned"} onClick={() => setFilter("planned")}>Planı olan</FilterButton>
            </div>
          </div>
        </div>
        {exportError && <div className="dashboard-export-error" role="alert"><Warning size={14} weight="fill" /><span>{exportError}</span><button onClick={() => setExportError("")}>Kapat</button></div>}
        {activeProcess === "turning"
          ? visibleMachines.length ? <div className="machine-dashboard-grid">{visibleMachines.map((board) => <MachinePanel key={board.machine.id} board={board} diagnostic={diagnostics[board.machine.id]} onOpen={() => onNavigate({ view: "machines", machineId: board.machine.id })} />)}</div> : <DashboardNoResults label="tezgah" />
          : visibleResources.length ? <div className="machine-dashboard-grid operation-resource-grid">{visibleResources.map((resource) => <ProcessResourcePanel key={resource.id} resource={resource} process={activeProcess} />)}</div> : <DashboardNoResults label="istasyon" />}
      </div>

      <details className="dashboard-audit">
        <summary>
          <span><WarningCircle size={18} weight="fill" /><strong>Plan kontrolü</strong><small>Miktar, termin, veri ve tezgah kuralları</small></span>
          <span className="dashboard-audit-counts"><b>{number(audit.criticalCount)} kritik</b><i>{number(audit.warningCount)} uyarı</i><em>{number(audit.infoCount)} bilgi</em></span>
        </summary>
        <div className="dashboard-audit-body">
          <p>Bu bölüm yönetici kararının yerine geçmez. Planı yayınlamadan önce incelenmesi gereken kayıtları ilgili ekrana bağlar.</p>
          <div className="dashboard-finding-list">{audit.findings.length ? audit.findings.map((finding) => <AuditRow key={finding.id} finding={finding} onNavigate={onNavigate} />) : <div className="dashboard-audit-clear"><CheckCircle size={20} weight="fill" /> Temel kontrollerde sorun bulunmadı.</div>}</div>
        </div>
      </details>
      {exportDialogOpen && <ShopFloorExportDialog process={activeProcess} label={activePlan?.label ?? "Operasyon"} start={exportStart} end={exportEnd} omittedJobCount={buildGeneralOverviewExportPayload(seed, result, dirty, new Date().toISOString(), activeProcess, activeProcess === "turning" ? { nextJobsOnly: true } : { startDate: exportStart, endDate: exportEnd }).operationPlans[0]?.omittedJobCount ?? 0} exporting={exporting} error={exportError} onChangeStart={setExportStart} onClose={() => { if (!exporting) setExportDialogOpen(false); }} onExport={() => void exportOverview()} />}
    </section>
  );
}

function ShopFloorExportDialog({ process, label, start, end, omittedJobCount, exporting, error, onChangeStart, onClose, onExport }: { process: GeneralPlanProcess; label: string; start: string; end: string; omittedJobCount: number; exporting: boolean; error: string; onChangeStart: (value: string) => void; onClose: () => void; onExport: () => void }) {
  const dayCount = start && end ? Math.floor((Date.parse(`${end}T00:00:00Z`) - Date.parse(`${start}T00:00:00Z`)) / 86_400_000) + 1 : 0;
  const valid = process === "turning" || dayCount === 15;
  const layout = process === "turning"
    ? "Sayfa başına 8 tezgâh · tezgâh başına en fazla 10 iş · toplam 2 sayfa"
    : "Seçilen başlangıçtan itibaren 15 takvim günü · tüm işler · gerektiği kadar sayfa";
  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog shop-floor-export-dialog" role="dialog" aria-modal="true" aria-label={`${label} saha planını hazırla`}><div className="operational-dialog-head"><span className="dialog-icon shift"><FileXls size={20} /></span><div><span>YAZDIRILABİLİR SAHA PLANI</span><h2>{process === "turning" ? `${label} · sıradaki 10 iş` : `${label} · 15 günlük revizyon`}</h2><p>{process === "turning" ? "Her tezgâh için tarihten bağımsız olarak sıradaki en fazla 10 işi hazırlar." : "Başlangıç günü dahil 15 takvim gününe denk gelen tüm işleri içerir. Bitiş tarihi otomatik belirlenir."}</p></div><button className="delete-button" onClick={onClose} disabled={exporting} aria-label="Saha planı penceresini kapat"><X size={16} /></button></div><div className="operational-dialog-form">{process !== "turning" && <div className="dialog-date-range"><label className="field"><span>Başlangıç</span><input type="date" value={start} onChange={(event) => onChangeStart(event.target.value)} /></label><label className="field"><span>Bitiş</span><input type="date" value={end} readOnly /></label></div>}<div className={`shop-floor-range-summary ${valid ? "valid" : "invalid"}`}><CalendarBlank size={18} /><div><strong>{process === "turning" ? "Tarih sınırı yok · sıradaki işler" : valid ? `${dayCount} günlük saha planı` : "Geçerli bir başlangıç tarihi seçin"}</strong><span>{layout}</span></div></div>{process === "turning" && omittedJobCount > 0 && <div className="calendar-impact-note maintenance"><strong>{omittedJobCount} iş yazdırma sınırının dışında</strong><span>Bu işler kaybolmaz; ekranda ve ana planda kalır. Sonraki revizyonda sıraya girer.</span></div>}{error && <p className="form-error" role="alert">{error}</p>}<div className="drawer-actions"><button className="secondary" onClick={onClose} disabled={exporting}>Vazgeç</button><button className="primary" onClick={onExport} disabled={!valid || exporting}><FileXls size={15} /> {exporting ? "Hazırlanıyor…" : "Excel saha planını indir"}</button></div></div></section></div>;
}

function DashboardNoResults({ label }: { label: string }) {
  return <div className="dashboard-no-results"><MagnifyingGlass size={24} /><strong>Eşleşen {label} bulunamadı</strong><span>Arama metnini veya filtreyi değiştirin.</span></div>;
}

function ProcessResourcePanel({ resource, process }: { resource: OperationResource; process: GeneralPlanProcess }) {
  const quantity = resource.rows.reduce((sum, row) => sum + row.quantity, 0);
  return (
    <article className={`machine-dashboard-card operation-resource-card ${process}`}>
      <header><div><span><b>{resource.id}</b><strong>{resource.name || resource.id}</strong></span><em>{resource.rows.length ? "Planlı" : "Boş"}</em></div></header>
      {resource.rows.length ? <div className="machine-dashboard-table"><div className="machine-dashboard-row operation head"><span>Sıra</span><span>Ürün</span><span>Şarj / iş emri</span><span>Adet</span><span>Başlangıç</span><span>Bitiş</span></div>{resource.rows.map((item) => <div key={`${resource.id}-${item.position}-${item.product}-${item.workOrder}`} className={`machine-dashboard-row operation ${item.status}`}><span>{item.status === "current" ? <i>Üretimde</i> : item.position}</span><strong>{item.product}</strong><span className={item.workOrder ? "trace-ready" : ""}>{item.workOrder || "—"}</span><span>{number(item.quantity)}</span><span>{formatPlanDate(item.startDate)}</span><span>{formatPlanDate(item.endDate)}</span></div>)}</div> : <div className="operation-resource-empty"><strong>Planlı iş yok</strong><span>Bu istasyon seçili planda boş.</span></div>}
      <footer><span>{number(resource.rows.length)} iş</span><strong>{number(quantity)} adet</strong></footer>
    </article>
  );
}

function DashboardMetric({ label, value, detail, tone = "" }: { label: string; value: string; detail: string; tone?: string }) {
  return <div className={`dashboard-kpi ${tone}`}><span>{label}</span><strong>{value}</strong><small>{detail}</small></div>;
}

function FilterButton({ active, onClick, children }: { active: boolean; onClick: () => void; children: React.ReactNode }) {
  return <button className={active ? "active" : ""} onClick={onClick}>{children}</button>;
}

function MachinePanel({ board, diagnostic, onOpen }: { board: MachineDashboard; diagnostic: MachineDiagnostic; onOpen: () => void }) {
  const { machine } = board;
  return (
    <article className={`machine-dashboard-card ${machine.active ? "" : "passive"}`}>
      <header>
        <button onClick={onOpen}><span><b>{machine.id}</b><strong>{machine.name}</strong></span><span className={machine.active ? "active" : "passive"}>{machine.active ? "Aktif" : "Pasif"}<ArrowRight size={13} /></span></button>
      </header>
      {board.queue.length ? <div className="machine-dashboard-table">
        <div className="machine-dashboard-row head"><span>Sıra</span><span>Ürün</span><span>Çap</span><span>Adet</span><span>Bitiş</span><span>İş emri</span></div>
        {board.queue.map((item) => <div key={item.id} className={`machine-dashboard-row ${item.kind}`}>
          <span>{item.kind === "current" ? <i>Üretimde</i> : item.position}</span>
          <strong>{item.product}</strong>
          <span>{formatDiameter(item.diameter)}</span>
          <span>{number(item.quantity)}</span>
          <span>{formatExcelDate(item.end, { day: "2-digit", month: "2-digit" })}</span>
          <span className={item.workOrder ? "trace-ready" : ""} title={item.workOrder || "İş emri yok"}>{item.workOrder || "—"}</span>
        </div>)}
      </div> : <button className={`machine-dashboard-empty ${diagnostic.tone}`} onClick={onOpen}><span>{diagnostic.title}</span><small>{diagnostic.detail}</small><ArrowRight size={14} /></button>}
      {board.queue.length > 0 && board.plannedCount === 0 && <button className={`machine-dashboard-diagnostic ${diagnostic.tone}`} onClick={onOpen}><span><strong>{diagnostic.title}</strong><small>{diagnostic.detail}</small></span><ArrowRight size={14} /></button>}
      <footer><span>{number(board.plannedCount)} planlı şarj</span><strong>{number(board.plannedQuantity)} adet</strong></footer>
    </article>
  );
}

function AuditRow({ finding, onNavigate }: { finding: AuditFinding; onNavigate: (target: AuditTarget) => void }) {
  const Icon = finding.severity === "critical" ? WarningCircle : finding.severity === "warning" ? Warning : Info;
  return <article className={`dashboard-finding ${finding.severity}`}><Icon size={17} weight={finding.severity === "info" ? "regular" : "fill"} /><div><strong>{finding.title}</strong><p>{finding.detail}</p></div>{finding.target && <button onClick={() => onNavigate(finding.target!)}>Kaydı aç<ArrowRight size={13} /></button>}</article>;
}

function formatDiameter(value: string): string {
  if (!value || value === "0") return "—";
  return value.includes("Ø") ? value : `Ø ${value}`;
}

function number(value: number): string {
  return formatInteger(value);
}

function percent(value: number): string {
  return new Intl.NumberFormat("tr-TR", { style: "percent", minimumFractionDigits: 1, maximumFractionDigits: 1 }).format(value);
}

function formatTimestamp(value: string): string {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "—";
  return new Intl.DateTimeFormat("tr-TR", { dateStyle: "short", timeStyle: "short" }).format(date);
}

function formatPlanDate(value: string): string {
  if (!value) return "—";
  const date = new Date(`${value}T00:00:00`);
  if (Number.isNaN(date.getTime())) return value;
  return new Intl.DateTimeFormat("tr-TR", { day: "2-digit", month: "2-digit", year: "numeric" }).format(date);
}

