export function ProcessCompletionTimeField({ value, readyAt, onChange, plannedReadyAt, confirmedBuffer, onConfirmBuffer }: { value: string; readyAt: number; plannedReadyAt?: number; confirmedBuffer?: boolean; onConfirmBuffer?: (value: boolean) => void; onChange: (value: string) => void }) {
  return <div className="process-completion-time">
    <label className="field"><span>Gerçek tamamlanma tarihi ve saati</span>
      <input type="datetime-local" required step={60} min={processCompletionTimeInput(Math.ceil(readyAt * 1440 - 1e-6) / 1440)} max={factoryDateTimeInput()} value={value} onChange={(event) => onChange(event.target.value)} />
