const WIP_STAGE_OPTIONS: Array<{ id: WipStage; label: string }> = [
  { id: "unclassified", label: "Konumu doğrulanmalı" },
  { id: "quality-hold", label: "Kalite bekliyor" },
  { id: "drilling-queue", label: "Delme bekliyor" },
  { id: "deburring-queue", label: "Çapak alma bekliyor" },
  { id: "washing-buffer", label: "Yıkama tamponunda" },
  { id: "gkm-buffer", label: "GKM öncesi bekliyor" },
  { id: "gkm-queue", label: "GKM bekliyor" },
  { id: "delivery-ready", label: "Teslimata hazır" },
  { id: "on-hold", label: "Blokeli" },
];

function formatHours(value: number): string {
  return `${new Intl.NumberFormat("tr-TR", { maximumFractionDigits: 1 }).format(value)} sa`;
}

function serialToInputDate(serial: number): string {
  return serial ? excelSerialToDate(Math.floor(serial)).toISOString().slice(0, 10) : "";
}

function inputDateToSerial(value: string): number {
  return value ? (Date.parse(`${value}T00:00:00Z`) - Date.UTC(1899, 11, 30)) / 86_400_000 : 0;
}

function journeyDateTooltip(label: string, start: number, end: number, ongoing = false): string {
  const date = (value: number) => formatExcelDate(value, { day: "2-digit", month: "long", year: "numeric", hour: "2-digit", minute: "2-digit" });
  return `${label}\nBaşlangıç: ${date(start)}\n${ongoing ? `Bitiş: Henüz tamamlanmadı\nPlanlanan bitiş: ${date(end)}` : `Bitiş: ${date(end)}`}`;
}

function familyLabel(family: "piston" | "center-pin"): string {
  return family === "piston" ? "Piston" : "Center Pin";
}

function journeySourceHeading(source: "current-turning" | "turning-plan" | "wip", delivered = false): string {
  return delivered ? "SEVK EDİLEN ŞARJ" : source === "wip" ? "SAHADAKİ ŞARJ" : source === "current-turning" ? "TORNADA ÇALIŞAN ŞARJ" : "PLANLANAN ŞARJ";
}

const rangePosition = journeyRangePosition;

function waitLabel(days: number): string {
  const minutes = Math.max(0, Math.round(days * 1440));
  if (days <= 0) return "Bekleme yok";
  if (minutes === 0) return "1 dk’dan kısa bekleme";
  const wholeDays = Math.floor(minutes / 1440);
  const hours = Math.floor(minutes % 1440 / 60);
  const remainingMinutes = minutes % 60;
  return [wholeDays ? `${wholeDays} gün` : "", hours ? `${hours} sa` : "", remainingMinutes ? `${remainingMinutes} dk` : ""].filter(Boolean).join(" ") + " bekleme";
}

function journeyChargeKey(job: RoutedProcessJob): string {
  return job.workOrder.trim() || job.batchId;
}

function delayLabel(days: number): string {
  const rounded = Math.max(1, Math.ceil(days));
  return `+${rounded} gün`;
}

export function ProcessPlanningView({ seed, result, dirty, focusJobId, onCompleteCurrentJob, onCompleteWipOperation, onCorrectWipStage, onReleaseWip, onSaveJourneyNote, onDeliverWip, onCompleteBuffer, onOpenArchive }: { onOpenArchive: (focus: ArchiveFocus) => void; seed: PlanningSeed; result: ScenarioResult; dirty: boolean; focusJobId?: string; onCompleteCurrentJob: (machineId: string, completedAt: number, completedQuantity: number, remainderAction?: "keep" | "scrap") => void; onCompleteWipOperation: (input: WipOperationInput) => boolean; onCorrectWipStage: (lotId: string, stage: WipStage, occurredAt: number) => void; onReleaseWip: (lotId: string, occurredAt: number) => void; onSaveJourneyNote: (input: ChargeJourneyNoteInput) => void; onDeliverWip: (input: WipDeliveryActionInput) => void; onCompleteBuffer: (input: WipManualActionInput) => void }) {
  const [manualAction, setManualAction] = useState<{ lot: WipLot; kind: "delivery" | "buffer" } | null>(null);
  const [mode, setMode] = useState<WorkspaceMode>("plan");
  const [journeyListMode, setJourneyListMode] = useState<JourneyListMode>("active");
  const [query, setQuery] = useState("");
  const [journeyProcessFilter, setJourneyProcessFilter] = useState("");
  const [journeyStateFilter, setJourneyStateFilter] = useState("");
  const [wipStageFilter, setWipStageFilter] = useState<WipStage | "">("");
  const [selectedJobId, setSelectedJobId] = useState("");
  const [selectedOperationId, setSelectedOperationId] = useState("");
  const journeyListRef = useRef<HTMLDivElement>(null);
  const [selectedWipId, setSelectedWipId] = useState("");
  const [completionQuantity, setCompletionQuantity] = useState(0);
  const [completionRemainderAction, setCompletionRemainderAction] = useState<ProcessRemainderAction | "">("");
  const [completionDate, setCompletionDate] = useState("");
  const [confirmedBuffer, setConfirmedBuffer] = useState(false);
  const [interruptionConfirmed,setInterruptionConfirmed]=useState(false);
  const [completionError, setCompletionError] = useState("");
  const [stageDraft, setStageDraft] = useState<WipStage>("unclassified");
  const [stageDate, setStageDate] = useState("");
  const [journeyCompletionOpen, setJourneyCompletionOpen] = useState(false);
  const [turningCompletionOpen, setTurningCompletionOpen] = useState(false);
  const [journeyCompletionQuantity, setJourneyCompletionQuantity] = useState(0);
  const [journeyRemainderAction, setJourneyRemainderAction] = useState<ProcessRemainderAction | "">("");
  const [journeyCompletionDate, setJourneyCompletionDate] = useState("");
  const [journeyCompletionResourceId, setJourneyCompletionResourceId] = useState("");
  const [journeyCompletionError, setJourneyCompletionError] = useState("");
  const [journeyNoteEditor, setJourneyNoteEditor] = useState<JourneyNoteEditor | null>(null);
  const [journeyNoteDraft, setJourneyNoteDraft] = useState("");
  const [journeyNoteReason, setJourneyNoteReason] = useState<ChargeJourneyReason | "">("");
  const plan = usePlanningDerivedPlan(seed, result)!;
  const journeyJobs = useMemo(() => [...plan.jobs, ...deliveredChargeJourneyJobs(seed)], [plan.jobs, seed]);
  const journeyStatusByJobId = useMemo(() => new Map(journeyJobs.map((job) => [job.batchId, chargeJourneyStatusForJob(job, seed)])), [journeyJobs, seed]);
  const [journeyNow, setJourneyNow] = useState(() => factoryNowSerial());
  useEffect(() => {
    const update = () => setJourneyNow(factoryNowSerial());
    const timer = window.setInterval(update, 60_000);
    window.addEventListener("focus", update);
    return () => { window.clearInterval(timer); window.removeEventListener("focus", update); };
  }, []);
  const todaySerial = Math.floor(journeyNow);
  const [journeyViewStart, setJourneyViewStart] = useState(todaySerial);
  const [journeyViewDays, setJourneyViewDays] = useState(28);
  const normalizedQuery = query.trim().toLocaleUpperCase("tr-TR");
  const archivedJobCount = journeyJobs.filter((job) => journeyStatusByJobId.get(job.batchId)?.tone === "delivered").length;
  const activeJobCount = journeyJobs.length - archivedJobCount;
  const visibleJobs = journeyJobs
    .filter((job) => journeyListMode === "archive" ? journeyStatusByJobId.get(job.batchId)?.tone === "delivered" : journeyStatusByJobId.get(job.batchId)?.tone !== "delivered")
    .filter((job) => !journeyProcessFilter || journeyCurrentProcess(job, seed) === journeyProcessFilter)
    .filter((job) => !journeyStateFilter || journeyStatusByJobId.get(job.batchId)?.tone === journeyStateFilter)
    .filter((job) => !normalizedQuery || `${job.product} ${job.workOrder} ${job.batchId}`.toLocaleUpperCase("tr-TR").includes(normalizedQuery))
    .sort((left, right) => compareChargeJourneyJobs(left, right, journeyListMode));
  const visibleTypes = new Set(visibleJobs.map((job) => job.product)).size;
  const visibleQuantity = visibleJobs.reduce((sum, job) => sum + journeyVisibleQuantity(job, seed), 0);
  const selectedJob = visibleJobs.find((job) => job.batchId === selectedJobId) ?? visibleJobs[0];
  const selectedOperation = selectedJob?.operations.find((operation) => operation.id === selectedOperationId) ?? (selectedJob ? defaultJourneyOperation(selectedJob, seed) : undefined);
  useRaviScreenContext("processes", { mode, journeyListMode, query, wipStageFilter, journeyProcessFilter, journeyStateFilter, visibleTypes, visibleQuantity,
    journeySortOrder: journeyListMode === "archive" ? "delivery-date-desc" : "process-start-asc",
    selectedJob, selectedOperation, selectedWipId, journeyViewStart, journeyViewDays,
    interruptionConfirmed, interruptions:selectedJob ? chargeJourneyInterruptions(selectedJob,seed) : [],
    completionDraft: mode === "wip" ? { completionDate, completionQuantity, completionRemainderAction, confirmedBuffer, completionError } : journeyCompletionOpen ? { journeyCompletionDate, journeyCompletionQuantity, journeyRemainderAction, journeyCompletionResourceId, confirmedBuffer, journeyCompletionError } : undefined,
    flowPlanScope: "remaining-operations", visibleJobCount: visibleJobs.length, dialogs: { manualAction: manualAction?.kind, journeyCompletionOpen, turningCompletionOpen, noteEditor: Boolean(journeyNoteEditor) },
    calculationSource: "buildDownstreamProcessPlan / chargeJourneyStatusForJob" });
  const selectedTurningMachine = selectedJob?.source === "current-turning"
    ? seed.machines.find((machine) => machine.id === selectedJob.turningMachineId && machine.currentJob.quantity > 0 && machine.currentJob.product.toUpperCase() === selectedJob.product.toUpperCase())
    : undefined;
  const nextTurningBatch = selectedTurningMachine ? result.batches.filter((batch) => batch.status === "planned" && batch.machineId === selectedTurningMachine.id).sort((a, b) => a.planColumn - b.planColumn)[0] : undefined;
  const selectedJobLot = selectedJob?.wipLotId ? (seed.wipLots ?? []).find((lot) => lot.id === selectedJob.wipLotId) : undefined;
  const selectedJobDelivered = Boolean(selectedJob?.archivedDelivery || selectedJobLot?.stage === "delivered");
  const selectedOpenInterruptions = selectedJob ? chargeJourneyInterruptions(selectedJob,seed).filter(item=>isProductionInterruption(item)&&!item.completedAt) : [];
  const selectedProductionInterrupted = selectedOpenInterruptions.length>0 && !interruptionsResumedOnTurning(selectedOpenInterruptions,seed);
  const selectedRouteIssue = selectedJob?.readinessIssues?.[0]?.message;
  const selectedRemainderQueued = Boolean(selectedJob && plan.queueEntries?.some(row=>row.batchId===selectedJob.batchId));
  const selectedDeliveryKnown = Boolean(selectedJob && Number.isFinite(selectedJob.deliveryReadyAt) && selectedJob.deliveryReadyAt > 0);
  const selectedChargeKey = selectedJob ? journeyChargeKey(selectedJob) : "";
  const selectedJourneyNotes = (seed.chargeJourneyNotes ?? []).filter((note) => note.chargeKey === selectedChargeKey);
  const selectedJourneyLot = selectedOperation?.wipLotId ? (seed.wipLots ?? []).find((lot) => lot.id === selectedOperation.wipLotId) : undefined;
  const selectedJourneyResources = selectedOperation && selectedOperation.process !== "turning"
    ? (() => {
        const product = seed.processMasterData?.products.find((item) => item.product.toUpperCase() === selectedOperation.product.toUpperCase());
        const parameter = product?.processes.find((item) => item.process === selectedOperation.process);
        return (seed.processMasterData?.resources ?? []).filter((resource) => resource.process === selectedOperation.process && parameter && activeProcessResourceIds(parameter).includes(resource.id));
      })()
    : [];
  const selectedJourneyRealReadyAt = selectedJourneyLot ? wipCompletionEarliestAt(seed, selectedJourneyLot) : 0;
  const selectedJourneyOperationCanComplete = Boolean(!selectedJobDelivered && selectedOperation && selectedOperation.process !== "turning" && !selectedOperation.actual && selectedJourneyLot?.nextProcess === selectedOperation.process && selectedJourneyLot.availableQuantity > 0 && selectedJourneyRealReadyAt <= journeyNow);
  const selectedJourneyCompletionHint = selectedOperation && selectedJourneyLot?.nextProcess === selectedOperation.process && selectedJourneyRealReadyAt > journeyNow
    ? `${processLabel(selectedOperation.process)} için yarı mamül ${formatExcelDate(selectedJourneyRealReadyAt)} tarihinde hazır olacak.`
    : selectedOperation ? `${processLabel(selectedOperation.process)} tamamlamak için önceki prosesin tamamlanması ve yarı mamülün hazır olması gerekir.` : "";
  const journeyMilestones = selectedJob ? (() => {
    const turning = selectedJob.operations.find((operation) => operation.process === "turning");
    const drilling = selectedJob.operations.find((operation) => operation.process === "drilling");
    const deburring = selectedJob.operations.find((operation) => operation.process === "deburring");
    const gkm = selectedJob.operations.find((operation) => operation.process === "gkm" && operation.recordedProcess !== "washing");
    const milestones = [
      turning ? { id: "turning", label: turning.actual ? "Torna bitti" : journeyOperationRunning(turning) ? "Torna üretimde" : "Torna planlandı", date: turning.end, detail: `${turning.resourceId} ${turning.actual ? "gerçek bitiş" : "tahmini bitiş"}`, wait: 0 } : null,
      drilling ? { id: "drilling", label: drilling.actual ? "Delme bitti" : journeyOperationRunning(drilling) ? "Delme üretimde" : "Delmeye hazır", date: drilling.actual ? drilling.end : drilling.readyAt, detail: drilling.actual ? `${drilling.resourceId} gerçek bitiş` : `Planlanan başlangıç ${formatExcelDate(drilling.start, { day: "2-digit", month: "short" })}`, wait: drilling.actual ? 0 : drilling.start - drilling.readyAt } : null,
      deburring ? { id: "deburring", label: deburring.actual ? "Çapak alma bitti" : journeyOperationRunning(deburring) ? "Çapak alma üretimde" : "Çapak almaya hazır", date: deburring.actual ? deburring.end : deburring.readyAt, detail: deburring.actual ? `${deburring.resourceId} gerçek bitiş` : `Planlanan başlangıç ${formatExcelDate(deburring.start, { day: "2-digit", month: "short" })}`, wait: deburring.actual ? 0 : deburring.start - deburring.readyAt } : selectedJob.historyIncomplete || selectedJob.family !== "center-pin" || selectedJob.routeSteps?.some(step => step.process === "deburring") ? null : { id: "deburring", label: "Çapak alma", date: 0, detail: seed.processMasterData?.products.find(item => item.product === selectedJob.product)?.route ? "Bu tipin rotasında pasif" : "Center Pin rotasında yok", wait: 0, skipped: true },
      gkm ? { id: "gkm", label: gkm.actual ? "GKM bitti" : journeyOperationRunning(gkm) ? "GKM üretimde" : "GKM'ye hazır", date: gkm.actual ? gkm.end : gkm.readyAt, detail: gkm.actual ? `${gkm.resourceId} gerçek bitiş` : `Planlanan başlangıç ${formatExcelDate(gkm.start, { day: "2-digit", month: "short" })}`, wait: gkm.actual ? 0 : gkm.start - gkm.readyAt } : null,
      selectedDeliveryKnown ? { id: "delivery", label: selectedJobDelivered ? "Sevk edildi" : "Teslimata hazır", date: selectedJob.deliveryReadyAt, detail: selectedJobDelivered ? "Üretim yolculuğu tamamlandı" : selectedJob.deliveryReadyAt > 0 ? "Son aktif proses sonrası paketleme ve final kontrol" : "Aktif üretim rotası henüz tamamlanamadı", wait: gkm ? selectedJob.deliveryReadyAt - gkm.end : 0 } : null,
    ].filter((milestone): milestone is { id: string; label: string; date: number; detail: string; wait: number; skipped?: boolean } => Boolean(milestone));
    const missing = (selectedJob.routeSteps??[]).filter(step=>!milestones.some(m=>m.id===step.process)).map(step=>({id:step.process,label:`${processLabel(step.process)}${step.state === 'running' ? ' üretimde' : ''}`,date:0,detail:step.reason??(step.state === 'running' ? 'Mevcut üretim kaydı korunuyor; bitiş tarihi doğrulanmalı.' : 'Tarih hesaplanmadı.'),wait:0,skipped:false}));
    const order = ['turning','drilling','deburring','gkm','delivery'];
    return [...milestones,...missing].sort((a,b)=>order.indexOf(a.id)-order.indexOf(b.id));
  })() : [];
  const journeyRows = selectedJob ? buildJourneyTimeline(selectedJob, journeyNow).map(row => ({ ...row,
    plannedTooltip: row.plannedRange ? journeyDateTooltip(`${journeyOperationLabel(row.operation)} · ${row.operation.resourceId} · Planlanan`, row.plannedStart, row.plannedEnd) : `${journeyOperationLabel(row.operation)} · Plan kaydı yok`,
    actualTooltip: journeyDateTooltip(`${journeyOperationLabel(row.operation)} · ${row.operation.resourceId} · Gerçekleşen`, row.actualStart, row.running ? row.operation.end : row.actualEnd, row.running),
  })) : [];
  const journeyIssues = journeyRows.flatMap(row => row.issues);
  useRaviScreenContext("journey-timeline", { selectedJobId: selectedJob?.batchId, asOf: journeyNow, dirty, issues: journeyIssues, routeSteps: selectedJob?.routeSteps, readinessIssues: selectedJob?.readinessIssues,
    rows: journeyRows.map(row => ({ id: row.operation.id, label: journeyOperationLabel(row.operation), status: row.status, actualStart: row.actualStart, actualEnd: row.actualEnd, waitStart: row.waitStart, waitEnd: row.waitEnd, remainingRange: row.remainingRange })) });
  const routeDates = journeyRows.flatMap(row => [row.plannedStart, row.plannedEnd, row.actualStart, row.actualEnd, row.waitStart, row.waitEnd, row.delayEnd]).filter(value => Number.isFinite(value) && value > 0);
  const routeStart = routeDates.length ? Math.floor(Math.min(...routeDates)) : todaySerial;
  const routeEnd = Math.ceil(Math.max(routeStart + 6, ...routeDates, Number.isFinite(selectedJob?.deliveryReadyAt) ? selectedJob!.deliveryReadyAt : routeStart, selectedJobDelivered ? 0 : todaySerial)) + 1;
  const horizonStart = Math.floor(journeyViewStart);
  const horizonDays = Math.max(7, Math.ceil(journeyViewDays));
  const horizonEnd = horizonStart + horizonDays;
  const journeyIntervalTicks = useMemo(() => Array.from({ length: 5 }, (_, index) => ({
    serial: Math.round(horizonStart + horizonDays * index / 4),
    position: (Math.round(horizonStart + horizonDays * index / 4) - horizonStart) / horizonDays * 100,
  })), [horizonDays, horizonStart]);
  const wipLots = (seed.wipLots ?? []).filter((lot) => lot.availableQuantity > 0 && lot.stage !== "delivered" && lot.stage !== "scrapped");
  const visibleWipLots = wipLots
    .filter((lot) => !wipStageFilter || lot.stage === wipStageFilter)
    .filter((lot) => !normalizedQuery || `${lot.product} ${lot.workOrder} ${lot.id}`.toLocaleUpperCase("tr-TR").includes(normalizedQuery))
    .sort((left, right) => left.readyAt - right.readyAt || left.createdAt.localeCompare(right.createdAt));
  const selectedWip = visibleWipLots.find((lot) => lot.id === selectedWipId) ?? visibleWipLots[0];
  useEffect(()=>setInterruptionConfirmed(false),[selectedWipId,selectedJobId,selectedOperationId]);
  const selectedWipOperation = selectedWip
    ? plan.operations.find((operation) => operation.wipLotId === selectedWip.id && !operation.actual && operation.process === selectedWip.nextProcess)
    : undefined;
  useEffect(() => {
    if (!focusJobId) return;
    const focusedJob = plan.jobs.find((job) => job.batchId === focusJobId);
    if (!focusedJob) return;
    setMode("plan");
    setQuery("");
    setSelectedJobId(focusedJob.batchId);
    setSelectedOperationId(defaultJourneyOperation(focusedJob, seed)?.id ?? "");
  }, [focusJobId, plan.jobs]);

  useEffect(() => {
    if (!selectedJob) return;
    setJourneyViewStart(routeStart);
    setJourneyViewDays(Math.max(7, routeEnd - routeStart));
  }, [selectedJob?.batchId, routeEnd, routeStart]);

  useEffect(() => {
    if (mode !== "plan" || !selectedJob) return;
    const frame = window.requestAnimationFrame(() => {
      const list = journeyListRef.current;
      const activeJob = list?.querySelector<HTMLButtonElement>("button.active");
      if (!list || !activeJob) return;
      const itemTop = activeJob.getBoundingClientRect().top - list.getBoundingClientRect().top + list.scrollTop;
      list.scrollTop = Math.max(0, itemTop - 4);
    });
    return () => window.cancelAnimationFrame(frame);
  }, [mode, selectedJob?.batchId]);

  useEffect(() => {
    if (!selectedWip) return;
    setSelectedWipId(selectedWip.id);
    setCompletionQuantity(selectedWip.availableQuantity);
    setConfirmedBuffer(false);
    setCompletionRemainderAction("");
    setCompletionDate(factoryDateTimeInput());
    setCompletionError("");
    setStageDraft(selectedWip.stage);
    setStageDate(serialToInputDate(selectedWip.readyAt));
  }, [selectedWip?.id, selectedWip?.availableQuantity, selectedWip?.stage, selectedWipOperation?.id]);

  function openJourneyCompletion() {
    setInterruptionConfirmed(false);
    if (!selectedOperation || !selectedJourneyLot) return;
    setJourneyCompletionQuantity(selectedJourneyLot.availableQuantity);
    setJourneyRemainderAction("");
    setJourneyCompletionDate(factoryDateTimeInput());
    setJourneyCompletionResourceId(selectedJourneyResources.some((resource) => resource.id === selectedOperation.resourceId) ? selectedOperation.resourceId : selectedJourneyResources[0]?.id ?? "");
    setJourneyCompletionError("");
    setConfirmedBuffer(false); setJourneyCompletionOpen(true);
  }

  function fitJourneyRoute() {
    setJourneyViewStart(routeStart);
    setJourneyViewDays(Math.max(7, routeEnd - routeStart));
  }

  function zoomJourney(direction: -1 | 1) {
    const levels = [7, 14, 28, 42, 70, 112];
    const nearest = levels.reduce((best, value, index) => Math.abs(value - journeyViewDays) < Math.abs(levels[best] - journeyViewDays) ? index : best, 0);
    setJourneyViewDays(levels[Math.max(0, Math.min(levels.length - 1, nearest + direction))]);
  }

  function journeyNote(segmentId: string): ChargeJourneyNote | undefined {
    return selectedJourneyNotes.find((note) => note.segmentId === segmentId);
  }

  function openJourneyNote(kind: "wait" | "delay", operation: ProcessOperation, start: number, end: number) {
    const segmentId = `${operation.recordedProcess ?? operation.process}:${kind}`;
    const existing = journeyNote(segmentId);
    setJourneyNoteEditor({
      chargeKey: selectedChargeKey,
      segmentId,
      kind,
      process: operation.recordedProcess ?? operation.process as ProductionProcess,
      start,
      end,
      label: `${journeyOperationLabel(operation)} ${kind === "delay" ? "gecikmesi" : "beklemesi"}`,
    });
    const reason = existing ? existing.reason ?? "other" : "";
    setJourneyNoteReason(reason);
    setJourneyNoteDraft(reason === "other" ? existing?.note ?? "" : "");
  }

  return <section className="process-workspace">
    <div className="process-workspace-head">
      <div className="process-mode-tabs" role="tablist" aria-label="Proses çalışma alanı">
        <button className={mode === "wip" ? "active" : ""} onClick={() => setMode("wip")}>Yarı mamül</button>
        <button className={mode === "plan" ? "active" : ""} onClick={() => setMode("plan")}>Şarj yolculuğu</button>
      </div>
    </div>

    {mode === "wip" ? <>
      <div className="process-summary-line">
        <span><b>{formatNumber(wipLots.length)}</b> açık yarı mamül</span>
        <span><b>{formatNumber(wipLots.reduce((sum, lot) => sum + lot.availableQuantity, 0))}</b> bekleyen adet</span>
