              </div>
              {journeyRows.map((row, index) => <div className="journey-gantt-row journey-comparison-row" key={row.operation.id}>
                <button title={[row.plannedTooltip, row.actualStart > 0 ? row.actualTooltip : ""].filter(Boolean).join("\n\n")} className={selectedOperation?.id === row.operation.id ? "active" : ""} onClick={() => setSelectedOperationId(row.operation.id)}><ProcessIcon process={row.operation.recordedProcess ?? row.operation.process} className={`journey-process-icon ${row.operation.process}`} /><span><strong>{index + 1}. {journeyOperationLabel(row.operation)}</strong><small>{row.operation.resourceId} · {row.operation.resourceName}</small></span><span className="journey-side-lanes"><em>PLANLANAN</em><em>GERÇEKLEŞEN</em></span></button>
                <div className="journey-track journey-two-lane-track">
                  {journeyNow >= horizonStart && journeyNow < horizonEnd && <i title="Şimdi" className="journey-today-line" style={{ left: `${ganttPercent(journeyNow, horizonStart, horizonDays)}%` }} />}
                  {!row.hasRecordedPlan && <span className="journey-missing-plan">Plan kaydı yok</span>}
                  {row.hasRecordedPlan && <button title={row.plannedTooltip} className={`journey-bar planned ${row.operation.process} ${selectedOperation?.id === row.operation.id ? "selected" : ""}`} style={rangePosition(row.plannedStart, row.plannedEnd, horizonStart, horizonDays)} onClick={() => setSelectedOperationId(row.operation.id)}><strong>{journeyOperationLabel(row.operation)}</strong><small>{formatExcelDate(row.plannedStart, { day: "2-digit", month: "short" })} – {formatExcelDate(row.plannedEnd, { day: "2-digit", month: "short" })}</small></button>}
                  {row.waitStart > 0 && <button className={`journey-wait-segment ${journeyNote(`${row.operation.recordedProcess ?? row.operation.process}:wait`) ? "has-note" : ""}`} style={rangePosition(row.waitStart, row.waitEnd, horizonStart, horizonDays)} onClick={() => openJourneyNote("wait", row.operation, row.waitStart, row.waitEnd)} title={journeyNote(`${row.operation.recordedProcess ?? row.operation.process}:wait`)?.note || "Bekleme nedeni ekle"}><strong>Bekleme</strong><small>{waitLabel(row.waitEnd - row.waitStart)}</small>{journeyNote(`${row.operation.recordedProcess ?? row.operation.process}:wait`) && <NotePencil size={12} weight="fill" />}</button>}
                  {row.actualStart > 0 && <button title={row.actualTooltip} className={`journey-bar actual ${row.operation.process} ${selectedOperation?.id === row.operation.id ? "selected" : ""}`} style={rangePosition(row.actualStart, row.actualEnd, horizonStart, horizonDays)} onClick={() => setSelectedOperationId(row.operation.id)}><strong>{journeyOperationLabel(row.operation)}</strong><small>{formatExcelDate(row.actualStart, { day: "2-digit", month: "short" })} – {row.running ? "devam ediyor" : formatExcelDate(row.actualEnd, { day: "2-digit", month: "short" })}</small></button>}
                  {row.delayStart > 0 && <button className={`journey-delay-segment ${journeyNote(`${row.operation.recordedProcess ?? row.operation.process}:delay`) ? "has-note" : ""}`} style={rangePosition(row.delayStart, row.delayEnd, horizonStart, horizonDays)} onClick={() => openJourneyNote("delay", row.operation, row.delayStart, row.delayEnd)} title={journeyNote(`${row.operation.recordedProcess ?? row.operation.process}:delay`)?.note || journeyDateTooltip("Gecikme · Neden eklemek için seçin", row.delayStart, row.delayEnd)}><strong>{delayLabel(row.delayEnd - row.delayStart)}</strong>{journeyNote(`${row.operation.recordedProcess ?? row.operation.process}:delay`) && <NotePencil size={12} weight="fill" />}</button>}
                </div>
              </div>)}
              <div className="journey-gantt-row journey-comparison-row buffer-row">
                <div className="journey-row-label"><i>{selectedJobDelivered ? "✓" : "+1"}</i><span><strong>{selectedJobDelivered ? "Paketleme & sevkiyat" : "Paketleme & Final Kontrol"}</strong><small>{selectedJobDelivered ? "Arşivde saklanan son aşama" : "1 iş günü"}</small></span><span className="journey-side-lanes"><em>PLANLANAN</em><em>GERÇEKLEŞEN</em></span></div>
                <div className="journey-track journey-two-lane-track">{journeyNow >= horizonStart && journeyNow < horizonEnd && <i title="Şimdi" className="journey-today-line" style={{ left: `${ganttPercent(journeyNow, horizonStart, horizonDays)}%` }} />}{!selectedDeliveryKnown && <span className="journey-missing-plan">{selectedRouteIssue ?? "Teslimat tarihi hesaplanamadı; rota ve kapasiteyi kontrol edin"}</span>}{!selectedJobDelivered && selectedDeliveryKnown && <div title={journeyDateTooltip("Paketleme & Final Kontrol · Planlanan", selectedJob.completion, selectedJob.deliveryReadyAt)} className="journey-buffer-bar planned" style={rangePosition(selectedJob.completion, selectedJob.deliveryReadyAt, horizonStart, horizonDays)}><strong>Teslimat</strong><small>{formatExcelDate(selectedJob.deliveryReadyAt, { day: "2-digit", month: "short" })}</small></div>}{selectedJobDelivered && <div title={journeyDateTooltip("Paketleme ve sevkiyat · Gerçekleşen", selectedJob.completion, selectedJob.deliveryReadyAt)} className="journey-buffer-bar actual" style={rangePosition(selectedJob.completion, selectedJob.deliveryReadyAt, horizonStart, horizonDays)}><strong>Sevk edildi</strong><small>{formatExcelDate(selectedJob.deliveryReadyAt, { day: "2-digit", month: "short" })}</small></div>}</div>
              </div>
            </div>
            {selectedOperation && <div className="journey-detail-panel">
              <div><span>SEÇİLİ ADIM</span><strong><ProcessIcon process={selectedOperation.recordedProcess ?? selectedOperation.process} /> {journeyOperationLabel(selectedOperation)} · {selectedOperation.resourceId}</strong><small>{selectedOperation.resourceName}</small></div>
              <dl className="process-operation-detail">
                <div><dt>Durum</dt><dd>{journeyRows.find(row => row.operation.id === selectedOperation.id)?.status ?? "Planlandı"}</dd></div>
                <div><dt>Planlanan başlangıç</dt><dd>{plannedJourneyRange(selectedOperation) ? formatExcelDate(plannedJourneyRange(selectedOperation)!.start) : "Plan kaydı yok"}</dd></div>
                <div><dt>Planlanan bitiş</dt><dd>{plannedJourneyRange(selectedOperation) ? formatExcelDate(plannedJourneyRange(selectedOperation)!.end) : "Plan kaydı yok"}</dd></div>
                <div><dt>Başlangıç</dt><dd>{formatExcelDate(selectedOperation.start, { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" })}</dd></div>
                <div><dt>{journeyOperationRunning(selectedOperation) ? "Gerçek bitiş" : selectedOperation.actual ? "Gerçek bitiş" : "Tahmini bitiş"}</dt><dd>{journeyOperationRunning(selectedOperation) ? "Henüz tamamlanmadı" : formatExcelDate(selectedOperation.end, { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" })}</dd></div>
                <div><dt>Vardiya kapasitesi</dt><dd>{selectedOperation.actual ? "Fiili kayıt" : selectedOperation.unitsPerShift > 0 ? `${formatNumber(selectedOperation.unitsPerShift)} adet` : "Torna planından"}</dd></div>
                <div><dt>Setup</dt><dd>{formatHours(selectedOperation.setupHours)}</dd></div>
                {selectedOperation.protectedSetupHoursAfter ? <div><dt>D-02 dönüş rezervi</dt><dd>{formatHours(selectedOperation.protectedSetupHoursAfter)}</dd></div> : null}
                <div><dt>Üretim yükü</dt><dd>{formatHours(selectedOperation.runHours)}</dd></div>
                <div><dt>Ön bekleme</dt><dd>{selectedOperation.waitWorkdaysBefore ? `${selectedOperation.waitWorkdaysBefore} iş günü` : "Bekleme yok"}</dd></div>
                {selectedOperation.transferBatchQuantity ? <div><dt>Akış partisi</dt><dd>{formatNumber(selectedOperation.transferBatchQuantity)} adet yarı mamül</dd></div> : null}
              </dl>
            </div>}
          </> : <div className="process-empty"><strong>Bir şarj seçin</strong><p>Aramadaki bir kaydı açarak üretim yolculuğunu görün.</p></div>}
        </section>
      </div> : <div className="process-empty"><strong>Henüz rotalı şarj yok</strong><p>Torna planı çalıştırıldığında şarj yolculukları burada oluşur.</p></div>}
    </>}
    {manualAction?.kind === "delivery" && <WipDeliveryAllocationDialog seed={seed} lot={manualAction.lot} onClose={() => setManualAction(null)} onConfirm={onDeliverWip} />}
    {manualAction?.kind === "buffer" && <WipManualActionDialog lot={manualAction.lot} kind="buffer" onClose={() => setManualAction(null)} onConfirm={onCompleteBuffer} />}
    {turningCompletionOpen && selectedTurningMachine && <CompleteJobDialog key={selectedJob?.batchId} machine={selectedTurningMachine} nextBatch={nextTurningBatch} onClose={() => setTurningCompletionOpen(false)} onConfirm={(completedAt, quantity, remainderAction) => { onCompleteCurrentJob(selectedTurningMachine.id, completedAt, quantity, remainderAction); setTurningCompletionOpen(false); }} />}
    {journeyNoteEditor && <div className="confirmation-backdrop" role="presentation"><section className="completion-dialog journey-note-dialog" role="dialog" aria-modal="true" aria-label={`${journeyNoteEditor.label} açıklaması`}><button className="delete-button journey-completion-close" onClick={() => setJourneyNoteEditor(null)} aria-label="Açıklama penceresini kapat"><X size={15} /></button><NotePencil size={25} weight="fill" /><span>{journeyNoteEditor.kind === "delay" ? "GECİKME NEDENİ" : "BEKLEME NEDENİ"}</span><h2>{journeyNoteEditor.label}</h2><p><b>{selectedJob?.workOrder || selectedJob?.product}</b> · {formatExcelDate(journeyNoteEditor.start, { day: "2-digit", month: "short" })} – {formatExcelDate(journeyNoteEditor.end, { day: "2-digit", month: "short" })}</p><fieldset className="journey-reason-options"><legend>{journeyNoteEditor.kind === "delay" ? "Gecikme nedeni" : "Bekleme nedeni"}</legend>{CHARGE_JOURNEY_REASONS.map((item) => <label key={item.value} className={journeyNoteReason === item.value ? "selected" : ""}><input type="radio" name="journey-note-reason" value={item.value} checked={journeyNoteReason === item.value} onChange={() => setJourneyNoteReason(item.value)} />{item.label}</label>)}</fieldset>{journeyNoteReason === "other" && <label className="field"><span>Açıklama</span><textarea autoFocus value={journeyNoteDraft} onChange={(event) => setJourneyNoteDraft(event.target.value)} placeholder={journeyNoteEditor.kind === "delay" ? "Örn. Müşteri çizim revizyonu bekleniyor" : "Örn. Kalite onayı beklendi"} /></label>}<small className="journey-note-help">Seçilen neden şarjın arşiv kaydında da korunur. Seçimi kaldırıp kaydederseniz mevcut neden silinir.</small><div className="drawer-actions">{journeyNoteReason && <button className="secondary" onClick={() => { setJourneyNoteReason(""); setJourneyNoteDraft(""); }}>Seçimi kaldır</button>}<button className="secondary" onClick={() => setJourneyNoteEditor(null)}>Vazgeç</button><button className="primary" disabled={journeyNoteReason === "other" && !journeyNoteDraft.trim()} onClick={() => { const { label: _label, ...input } = journeyNoteEditor; onSaveJourneyNote({ ...input, reason: journeyNoteReason || undefined, note: journeyNoteReason === "other" ? journeyNoteDraft : "" }); setJourneyNoteEditor(null); }}><NotePencil size={15} /> Nedeni kaydet</button></div></section></div>}
    {journeyCompletionOpen && selectedOperation && selectedJourneyLot && <div className="confirmation-backdrop" role="presentation"><section className="completion-dialog" role="dialog" aria-modal="true" aria-label={`${selectedOperation.workOrder || selectedOperation.product} prosesini bitir`}><button className="delete-button journey-completion-close" onClick={() => setJourneyCompletionOpen(false)} aria-label="İş bitir penceresini kapat"><X size={15} /></button><ProcessIcon process={selectedOperation.process} size={25} /><span>{processLabel(selectedOperation.process).toLocaleUpperCase("tr-TR")} TAMAMLAMA</span><h2>{selectedOperation.workOrder || selectedOperation.product}</h2><p>{selectedOperation.product} şarjının bu adımı seçtiğiniz gerçek tarih ve iş merkezinde tamamlanacak, ardından sıradaki prosese geçirilecek.</p><label className="field"><span>Fiili tamamlanan adet</span><input type="number" min={1} max={selectedJourneyLot.availableQuantity} step={1} value={journeyCompletionQuantity || ""} onChange={(event) => setJourneyCompletionQuantity(Number(event.target.value))} /></label><label className="field"><span>Fiili iş merkezi</span><select value={journeyCompletionResourceId} onChange={(event) => setJourneyCompletionResourceId(event.target.value)}>{selectedJourneyResources.map((resource) => <option key={resource.id} value={resource.id}>{resource.id} · {resource.name}</option>)}</select><small>Planlanan tezgahtan farklıysa sahada kullanılan iş merkezini seçin.</small></label><ProcessRemainderChoice available={selectedJourneyLot.availableQuantity} completed={journeyCompletionQuantity} action={journeyRemainderAction} onChange={setJourneyRemainderAction} name="journey-process-remainder" /><ProcessCompletionTimeField value={journeyCompletionDate} readyAt={selectedJourneyRealReadyAt} plannedReadyAt={wipOperationReadyAt(selectedJourneyLot)} confirmedBuffer={confirmedBuffer} onConfirmBuffer={setConfirmedBuffer} onChange={value => { setJourneyCompletionDate(value); setConfirmedBuffer(false); }} />{activeLotInterruptions(seed,selectedJourneyLot).length>0 && <InterruptionConsent checked={interruptionConfirmed} onChange={setInterruptionConfirmed}/>} {journeyCompletionError && <p className="form-error">{journeyCompletionError}</p>}<div className="drawer-actions"><button className="secondary" onClick={() => setJourneyCompletionOpen(false)}>Vazgeç</button><button className="primary" onClick={() => { try { if (!journeyCompletionDate) throw new Error("Tamamlanma tarihi zorunludur."); const actualResource = selectedJourneyResources.find((resource) => resource.id === journeyCompletionResourceId); if (!actualResource) throw new Error("Fiili iş merkezi seçilmelidir."); if (!Number.isInteger(journeyCompletionQuantity) || journeyCompletionQuantity <= 0 || journeyCompletionQuantity > selectedJourneyLot.availableQuantity) throw new Error("Fiili adet açık yarı mamül miktarını aşmayan pozitif tam sayı olmalıdır."); const remainderAction = requireProcessRemainderAction(selectedJourneyLot.availableQuantity, journeyCompletionQuantity, journeyRemainderAction); const completedAt = parseProcessCompletionTime(journeyCompletionDate, selectedJourneyRealReadyAt); const startedAt = Math.max(selectedJourneyRealReadyAt, Math.min(selectedOperation.start, completedAt)); const completed = onCompleteWipOperation({ lotId: selectedJourneyLot.id, confirmedInterruption:interruptionConfirmed, confirmedBuffer, process: selectedOperation.process as DownstreamProcess, resourceId: actualResource.id, resourceName: actualResource.name, quantity: journeyCompletionQuantity, remainderAction, startedAt, completedAt, plannedStart: selectedOperation.start, plannedEnd: selectedOperation.end }); if (completed === false) throw new Error("İş tamamlanamadı; ekrandaki uyarıyı kontrol edin."); setJourneyCompletionOpen(false); } catch (reason) { setJourneyCompletionError(reason instanceof Error ? reason.message : "Proses tamamlanamadı."); } }}><ProcessIcon process={selectedOperation.process} size={15} /> {processLabel(selectedOperation.process)} prosesini bitir</button></div></section></div>}
  </section>;
}

frontend/components/ProcessRemainderChoi.source:
"use client";

import { formatInteger as formatNumber } from "@/lib/number-format";

export type ProcessRemainderAction = "keep" | "scrap";

export function requireProcessRemainderAction(available: number, completed: number, action: ProcessRemainderAction | ""): ProcessRemainderAction | undefined {
  if (!Number.isInteger(completed) || completed <= 0 || completed > available) throw new Error("Fiili adet açık yarı mamül miktarını aşmayan pozitif tam sayı olmalıdır.");
  if (completed < available && !action) throw new Error("Kalan miktar için Yarı mamülde bırak veya Iskartaya ayır seçin.");
  return completed < available ? action as ProcessRemainderAction : undefined;
}

export function ProcessRemainderChoice({ available, completed, action, onChange, name, turning = false }: {
  available: number;
  completed: number;
  action: ProcessRemainderAction | "";
  onChange: (action: ProcessRemainderAction) => void;
  name: string;
  turning?: boolean;
}) {
  const remainder = available - completed;
  if (!Number.isInteger(remainder) || remainder <= 0) return null;
  return <div className="archive-remainder process-remainder">
    <span><small>Kalan miktar</small><strong>{formatNumber(remainder)} adet</strong></span>
    <div role="radiogroup" aria-label="Kalan miktar işlemi">
      <label><input type="radio" name={name} checked={action === "keep"} onChange={() => onChange("keep")} /><span><strong>{turning ? "Tornada devam et" : "Yarı mamülde bırak"}</strong><small>{turning ? "Kalan parçalar Torna işi olarak korunur" : "Bu proseste bekler; sonra işlenebilir"}</small></span></label>
      <label className="scrap-choice"><input type="radio" name={name} checked={action === "scrap"} onChange={() => onChange("scrap")} /><span><strong>Iskartaya ayır</strong><small>Üretim kaybı olarak kaydedilir</small></span></label>
    </div>
  </div>;
}

