"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { ArrowLeft, ArrowRight, Check, Info, X } from "@phosphor-icons/react";
import { useRaviScreenContext } from "@/features/ravi/context";

export type AppView = "planning" | "processes" | "control" | "orders" | "machines" | "parameters" | "settings" | "scenarios" | "feedback";

export const PAGE_GUIDES: Record<AppView, { label: string; summary: string; title: string; features: string[] }> = {
  planning: { label: "Planlama", title: "Üretim planını düzenleyin", summary: "Üretim takvimini ve tezgah kuyruklarını yönetin.", features: ["Tarihi değiştirin, yakınlaştırın veya tüm planı ekrana sığdırın", "Şarjları sürükleyerek tezgah veya kuyruk sırasını değiştirin", "Tatil veya Pazar bandından üretim vardiyalarını ayarlayın"] },
  processes: { label: "Şarj Yolculuğu", title: "Şarjın durumunu inceleyin", summary: "Şarjların proseslerini, beklemelerini ve teslimat durumunu takip edin.", features: ["İş emri, şarj veya ürünle arayın", "Planlanan ve gerçekleşen adımları zaman çizelgesinde karşılaştırın", "Yarı mamül hareketlerini ve sevk edilen şarjları inceleyin"] },
  control: { label: "Genel Bakış", title: "Üretimi gözden geçirin", summary: "Mevcut üretimi, tezgah kuyruklarını ve plan özetini izleyin.", features: ["Üretimdeki işi ve sıradaki şarjları tezgah bazında inceleyin", "Tezgah, ürün veya iş emri arayın", "Plan kontrolündeki bulgulardan ilgili kayda gidin"] },
  orders: { label: "Siparişler", title: "Siparişleri güncelleyin", summary: "Siparişleri, terminleri ve teslimat durumunu yönetin.", features: ["Sipariş ekleyin veya müşteri sipariş dosyasını yükleyin", "Teslimat planını inceleyin ve indirin", "Parçalı teslimatları ve müşteri revizyonlarını yönetin"] },
  machines: { label: "Tezgahlar", title: "Tezgah programını düzenleyin", summary: "Mevcut işleri, kuyrukları ve tezgah kapasitesini yönetin.", features: ["Tezgah bilgilerini ve mevcut üretimi güncelleyin", "Şarj ekleyin veya kuyruk sırasını değiştirin", "Vardiya ve bakım kayıtlarını yönetin"] },
  parameters: { label: "Parametreler", title: "Ürün bilgilerini tanımlayın", summary: "Ürün rotalarını, şarj büyüklüklerini ve üretim hızlarını tanımlayın.", features: ["Ürünün aktif proseslerini ve şarj büyüklüğünü belirleyin", "Tezgah önceliklerini ve vardiyalık üretim adetlerini düzenleyin", "Eksik parametreleri tamamlayın"] },
  settings: { label: "Ayarlar", title: "Fabrika ayarlarını düzenleyin", summary: "Akış ve bekleme kurallarını, hazırlık sürelerini, üretim takvimini ve hammadde bilgilerini yönetin.", features: ["Piston ve Center Pin için Akış ve bekleme içinde saat kurallarını ve iş günü yedek kurallarını inceleyin", "Hazırlık sürelerini ve üretim takvimini düzenleyin", "Hammadde Bilgileri içinde ürün ağırlıklarını ve tüketimi inceleyin"] },
  scenarios: { label: "Senaryolar", title: "Planları karşılaştırın", summary: "Kayıtlı planları inceleyin ve sonuçlarını karşılaştırın.", features: ["Bir senaryo seçerek özetini ve sipariş atamalarını inceleyin", "İkinci senaryoyu seçerek sonuçları karşılaştırın", "Seçili senaryoları indirin"] },
  feedback: { label: "Geri Bildirimler", title: "Geri bildirimleri takip edin", summary: "Hata bildirimlerini, önerileri ve çözüm durumlarını takip edin.", features: ["Açık ve çözülen kayıtları inceleyin", "Duruma göre filtreleyin, arayın ve sıralayın", "Görsel, ekran görüntüsü veya sesli not ekleyin"] },
};

export function PageGuidePanel({ view, onClose }: { view: AppView; onClose: () => void }) {
  const guide = PAGE_GUIDES[view];
  return <section className="page-guide-panel"><div><Info size={18} weight="fill" /><span><strong>{guide.title}</strong><small>{guide.summary}</small></span></div><ul>{guide.features.map((feature) => <li key={feature}>{feature}</li>)}</ul><button onClick={onClose} aria-label="Sayfa rehberini kapat"><X size={16} /></button></section>;
}

const TOUR_STEPS: Array<{ view: AppView; eyebrow: string; title: string; body: string }> = [
  { view: "planning", eyebrow: "HOŞ GELDİNİZ", title: "Selsa Planlama", body: "Siparişten teslimata üretiminizi yönetin. Bu kısa tur ana çalışma alanlarını tanıtır." },
  { view: "orders", eyebrow: "1 · SİPARİŞLER", title: "Siparişlerinizi yönetin", body: "Sipariş adedi ve termin girin veya müşteri sipariş dosyasını yükleyin. Teslimat durumunu aynı ekranda takip edin." },
  { view: "planning", eyebrow: "2 · PLANLAMA", title: "Tezgah zaman çizelgesini okuyun", body: "Şarjları taşıyın; tatil veya Pazar bandına tıklayarak seçili tezgah ya da tüm aktif tezgahlar için vardiya açın." },
  { view: "machines", eyebrow: "3 · TEZGAHLAR", title: "Kapasiteyi ve kuyrukları yönetin", body: "Mevcut işleri, tezgah kuyruklarını ve vardiyaları düzenleyin; gerektiğinde manuel şarj ekleyin." },
  { view: "settings", eyebrow: "4 · ÜRETİM TAKVİMİ", title: "Üretim ayarlarını yönetin", body: "Piston ve Center Pin için Akış ve bekleme, Setup, Mesai ve vardiya ve Hammadde Bilgileri sekmelerini kullanın. Değişiklikleri incele ile kayda girecek tüm bölümleri görün. Ayarları kaydet bu bölümleri birlikte kaydeder. Güncel ayarları yükle, değişmiş taslağı silmeden önce onay ister." },
  { view: "control", eyebrow: "5 · GENEL BAKIŞ", title: "Üretimi gözden geçirin", body: "Her tezgahın mevcut işini ve kuyruğunu inceleyin. Plan kontrolündeki bulgulardan ilgili kayda gidin." },
  { view: "scenarios", eyebrow: "6 · SENARYOLAR", title: "Alternatifleri yan yana değerlendirin", body: "Kaydettiğiniz iki planı talep karşılama, bitiş tarihi, toplam setup saati, tezgah kullanımı ve değişen atamalar açısından karşılaştırın." },
  { view: "feedback", eyebrow: "7 · GERİ BİLDİRİM", title: "Geliştirme sürecine doğrudan katılın", body: "Hata, özellik talebi veya fikir paylaşın. Ekran görüntüsünü metin alanına yapıştırabilir, görsel ya da sesli not ekleyebilirsiniz." },
];

export function ProductTour({ open, onClose, onNavigate, canManageSettings = true }: { open: boolean; onClose: () => void; onNavigate: (view: AppView) => void; canManageSettings?: boolean }) {
  const [index, setIndex] = useState(0);
  const steps = useMemo(() => canManageSettings ? TOUR_STEPS : TOUR_STEPS.filter((step) => step.view !== "settings"), [canManageSettings]);
  const visited = useRef<{ index: number; view: AppView } | null>(null);
  useEffect(() => { if (index >= steps.length) setIndex(Math.max(steps.length - 1, 0)); }, [index, steps.length]);
  useEffect(() => {
    if (!open) { visited.current = null; setIndex(0); return; }
    const step = steps[index];
    if (!step || (visited.current?.index === index && visited.current.view === step.view)) return;
    // A parent render or a manual tab change must not replay the tour step.
    visited.current = { index, view: step.view };
    onNavigate(step.view);
  }, [index, onNavigate, open, steps]);
  useRaviScreenContext("product-tour", { open, step: index + 1, title: steps[index]?.title, targetView: steps[index]?.view }, open);
  if (!open) return null;
  const step = steps[index];
  const finish = () => { window.localStorage.setItem("selsa-planlama-tour-seen", "1"); onClose(); };
  return <div className="tour-overlay" role="presentation"><section className="tour-card" role="dialog" aria-modal="false" aria-label="Selsa Planlama ürün turu"><div className="tour-progress">{steps.map((_, stepIndex) => <i key={stepIndex} className={stepIndex <= index ? "active" : ""} />)}</div><span>{step.eyebrow}</span><h2>{step.title}</h2><p>{step.body}</p><div className="tour-actions"><button className="tour-skip" onClick={finish}>Turu geç</button>{index > 0 && <button className="tour-back" onClick={() => setIndex((current) => current - 1)}><ArrowLeft size={15} /> Geri</button>}<button className="tour-next" onClick={() => index === steps.length - 1 ? finish() : setIndex((current) => current + 1)}>{index === steps.length - 1 ? <><Check size={15} /> Bitir</> : <>Sonraki <ArrowRight size={15} /></>}</button></div></section></div>;
}

