"use client";

import { useEffect, useState } from "react";
import { DeliveryAllocationForm, type DeliveryAllocationDraft } from "./DeliveryAllocationForm";
import { useRaviScreenContext } from "@/features/ravi/context";
import { archiveEntrySignature } from "@/lib/archive-corrections";
import { factoryDateTimeInput, factoryDateTimeToIso, factoryNowSerial } from "@/lib/factory-time";
import { formatExcelDate, type PlanningSeed, type WipLot } from "@/lib/planning";
import { inputDateToSerial, serialToInputDate } from "@/features/planning/shared/format";
import { wipOperationReadyAt } from "@/lib/wip-ledger";
import { wipActionSignature, type WipDeliveryActionInput } from "@/lib/wip-manual-actions";

export function WipDeliveryAllocationDialog({ seed, lot, onClose, onConfirm }: {
  seed: PlanningSeed; lot: WipLot; onClose: () => void; onConfirm: (input: WipDeliveryActionInput) => void;
}) {
  const [history] = useState(() => {
    const entry = seed.productionHistory?.find(item => item.id === lot.sourceHistoryEntryId && item.inventoryStatus === "semi-finished");
    return entry ? structuredClone(entry) : undefined;
  });
  const [draft, setDraft] = useState<DeliveryAllocationDraft>(() => ({ actualQuantity: lot.availableQuantity,
    completedDate: history ? serialToInputDate(history.completedAt) : "", deliveredQuantity: lot.availableQuantity,
    deliveryDate: factoryDateTimeInput(), remainderAction: "keep" }));
  const [confirmed, setConfirmed] = useState(false);
  const [error, setError] = useState("");
  const deliveryIso = factoryDateTimeToIso(draft.deliveryDate);
  const deliveredAt = deliveryIso ? factoryNowSerial(deliveryIso) : Number.NaN;
  const early = draft.deliveredQuantity > 0 && Number.isFinite(deliveredAt) && deliveredAt < wipOperationReadyAt(lot);
  useRaviScreenContext("journey-delivery-allocation", { lotId: lot.id, workOrder: lot.workOrder, product: lot.product,
    historyId: history?.id, scope: "selected-open-lot", availableQuantity: lot.availableQuantity, draft, early, confirmed,
    readyAt: wipOperationReadyAt(lot), error });
  useEffect(() => {
    const escape = (event: KeyboardEvent) => { if (event.key === "Escape") onClose(); };
    window.addEventListener("keydown", escape);
    return () => window.removeEventListener("keydown", escape);
  }, [onClose]);
  return <div className="confirmation-backdrop" role="presentation"><DeliveryAllocationForm product={lot.product} draft={draft}
    onChange={next => { setDraft(next); setError(""); setConfirmed(false); }} error={error || (!history ? "Şarjın açık üretim arşivi kaydı bulunamadı. Arşiv eşleşmesini kontrol edin." : "")}
    onClose={onClose} onSave={() => {
      try {
        if (!history) throw new Error("Şarjın açık üretim arşivi kaydı bulunamadı.");
        if (early && !confirmed) throw new Error("Erken teslimat için proses kontrol ve paketlemenin tamamlandığını onaylayın.");
        onConfirm({ lotId: lot.id, expectedLot: wipActionSignature(lot), expectedHistory: archiveEntrySignature(history),
          quantity: draft.deliveredQuantity, confirmed: !early || confirmed,
          allocation: { actualQuantity: draft.actualQuantity, completedAt: inputDateToSerial(draft.completedDate),
            deliveredQuantity: draft.deliveredQuantity, deliveryDate: draft.deliveryDate, remainderAction: draft.remainderAction } });
        onClose();
      } catch (reason) { setError(reason instanceof Error ? reason.message : "Teslimat kaydedilemedi."); }
    }}>
    <p className="journey-allocation-scope">İş emri {lot.workOrder || "yok"} · Yalnız seçili şarjın kalan miktarı. Önceki teslimatlar ve diğer parçalar korunur.</p>
    {early && <div className="journey-early-delivery"><p>Paketleme beklemesi {formatExcelDate(wipOperationReadyAt(lot), { day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" })} tarihinde doluyor. Onay yalnız teslim edilen miktar için bu beklemeyi kaldırır.</p>
      <label><input type="checkbox" checked={confirmed} onChange={event => { setConfirmed(event.target.checked); setError(""); }} /> Proses kontrol ve paketleme tamamlandı.</label></div>}
  </DeliveryAllocationForm></div>;
}

frontend/components/WipManualActionDialo.source:
"use client";

import { useEffect, useState } from "react";
import { CheckCircle, X } from "@phosphor-icons/react";
import { useRaviScreenContext } from "@/features/ravi/context";
import { factoryDateInput, factoryNowSerial } from "@/lib/factory-time";
import { formatExcelDate, type WipLot } from "@/lib/planning";
import { wipActionSignature, wipBufferQuestion, type WipManualActionInput } from "@/lib/wip-manual-actions";
import { wipOperationReadyAt } from "@/lib/wip-ledger";

export function WipManualActionDialog({ lot, kind, onClose, onConfirm }: {
  lot: WipLot; kind: "delivery" | "buffer"; onClose: () => void; onConfirm: (input: WipManualActionInput) => void;
}) {
  const [quantity, setQuantity] = useState(lot.availableQuantity);
  const [error, setError] = useState("");
  const waiting = wipOperationReadyAt(lot) > factoryNowSerial();
  const delivery = kind === "delivery";
  const question = wipBufferQuestion(lot) ?? "Proses kontrol tamamlandı mı?";
  useRaviScreenContext("wip-manual-action", { kind, lotId: lot.id, product: lot.product, workOrder: lot.workOrder, stage: lot.stage,
    quantity, availableQuantity: lot.availableQuantity, plannedReadyAt: wipOperationReadyAt(lot), waiting, question, error });
  useEffect(() => {
    const escape = (event: KeyboardEvent) => { if (event.key === "Escape") onClose(); };
    window.addEventListener("keydown", escape);
    return () => window.removeEventListener("keydown", escape);
  }, [onClose]);
  return <div className="confirmation-backdrop" role="presentation"><section className="completion-dialog" role="dialog" aria-modal="true" aria-label={delivery ? "Teslimatı tamamla" : "Beklemeyi tamamla"}>
    <button className="delete-button journey-completion-close" onClick={onClose} aria-label="Onayı kapat"><X size={15} /></button>
    <CheckCircle size={26} weight="fill" /><span>{delivery ? "TESLİMAT ONAYI" : "BEKLEME ONAYI"}</span>
    <h2>{lot.product}</h2><p>{lot.workOrder} · {lot.availableQuantity.toLocaleString("tr-TR")} adet</p>
    <p><strong>{question}</strong></p>
    {waiting && <div className="process-inline-notice"><span>Planlanan hazır olma: <b>{formatExcelDate(wipOperationReadyAt(lot))}</b>. Onayınızla bu işlem için bekleme süresi kaldırılacak.</span></div>}
    {delivery ? <label className="field"><span>Teslim edilecek adet</span><input autoFocus type="number" min={1} max={lot.availableQuantity} step={1} value={quantity || ""} onChange={(event) => { setQuantity(Number(event.target.value)); setError(""); }} /><small>Teslim tarihi: {factoryDateInput()}. Kalan adet mevcut aşamada kalır.</small></label>
      : <p>Bu şarjın beklemesi şimdi tamamlanmış olarak kaydedilecek. Sonraki operasyon otomatik tamamlanmaz.</p>}
    {error && <p className="form-error" role="alert">{error}</p>}
    <div className="drawer-actions"><button className="secondary" onClick={onClose}>Hayır, vazgeç</button><button className="primary" onClick={() => {
      try {
        if (delivery && (!Number.isInteger(quantity) || quantity <= 0 || quantity > lot.availableQuantity)) throw new Error("Teslim adedi kalan miktarı aşmayan pozitif tam sayı olmalıdır.");
        onConfirm({ lotId: lot.id, expectedLot: wipActionSignature(lot), quantity, confirmed: true });
        onClose();
      } catch (reason) { setError(reason instanceof Error ? reason.message : "İşlem tamamlanamadı."); }
    }}><CheckCircle size={15} />{delivery ? "Evet, teslimatı tamamla" : "Evet, beklemeyi tamamla"}</button></div>
  </section></div>;
}

