  function acceptCollaborationWrite(value: Record<string, unknown>) {
    if (value.scenario) {
      const saved = value.scenario as StoredScenario;
      if (!isPlanningSeed(saved.seed) || !saved.revision) throw new Error("Taslak onayı geçersiz.");
      setPersonalDraft(saved);
      const next = sharedWorldRef.current ? mergeScenarioWithLiveOperations(saved.seed, sharedWorldRef.current.seed) : saved.seed;
      next.planNeedsRecalculation = Boolean(saved.seed.planNeedsRecalculation || saved.worldRevision !== sharedWorldRef.current?.updatedAt);
      // Preserve display references only when the complete acknowledged value is
      // identical. A real server correction still replaces the visible plan.
      if (!sameSeedContent(next, latestSeedRef.current, true)) {
        setSeed(next); latestSeedRef.current = next;
        setResult(restoreManualResult(next) ?? createEmptyResult(next));
      }
      setDirty(planRequiresRecalculation(next));
      setCollaborationMessage("Taslak kaydedildi");
    } else if (value.current) {
      if (value.publicationId) { setPersonalDraft(null); setPublicationPreview(null); setActivePublication(value.activePublication as SharedPlanPublication | null | undefined); }
      const world = value.current as PlanningStateRecord;
      if (!isPlanningSeed(world.seed)) throw new Error("Üretim onayı geçersiz. Yerel isteği koruyun.");
      applySharedWorld(world);
      refreshRevisions();
      setCollaborationMessage(value.publicationId ? "Plan yayınlandı" : "Üretim kaydı onaylandı");
