      if (!world || collaborationBusy.current || getCollaborationWriter().pending()) throw new Error("Önce taslak kaydını tamamlayın.");
      const [machineId, completedAt, quantity, remainderAction] = command.args as [string, number, number | undefined, "keep" | "scrap" | undefined];
