  async function preservePendingRequest() {
    if (collaborationBusy.current || getCollaborationWriter().busy) throw new Error("Kayıt onayı bekleniyor.");
    const writer = getCollaborationWriter(), pending = writer.pending();
    if (!pending) return;
    collaborationBusy.current = true;
    try {
      const body = JSON.parse(pending.body) as { requestId?: string; previewId?: string };
      const kind = pending.method === "PATCH" ? "draft" : body.previewId ? "publication" : "production";
      const response = await apiFetch(`/collaboration/requests/${encodeURIComponent(body.requestId ?? body.previewId ?? "")}?kind=${kind}`, { cache: "no-store" });
      if (!response.ok) throw new Error("İstek sonucu kontrol edilemedi. Yerel isteği koruyun.");
      const status = await response.json();
      if (status.committed) { acceptCollaborationWrite(status); return; }
      if (status.committed !== false) throw new Error("İstek sonucu geçersiz. Yerel isteği koruyun.");
      window.localStorage.setItem(`${writer.key}:retained:${crypto.randomUUID()}`, JSON.stringify(pending));
      writer.acknowledge();
      setPublicationPreview(null);
      setCollaborationMessage("İşlem bu tarayıcıda yedeklendi ve bekleyen işlemlerden çıkarıldı. Taslak için Yeni taslak kullanın; üretim işlemini güncel kayıtla yeniden inceleyin.");
