      cursor.setUTCMonth(cursor.getUTCMonth() + 1);
    }
    return months;
  }, [customerDemand]);
  const visibleMonthId = serialToInputDate(horizonStart).slice(0, 7);
  const holidaySerials = useMemo(() => new Set(seed.holidays.map((holiday) => Math.floor(holiday.serial))), [seed.holidays]);
  const dayWidth = horizon <= 14 ? 44 : horizon <= 28 ? 30 : horizon <= 42 ? 24 : horizon <= 70 ? 18 : 16;
  const timelineStyle = { "--gantt-days": horizon, "--gantt-min-width": `${Math.max(680, horizon * dayWidth)}px` } as React.CSSProperties;
  const dropPreview = useMemo(() => {
