  const evaluatedDownstreamPlan = useMemo(() => evaluatedResult === result ? downstreamPlan : buildDownstreamProcessPlan(seed, evaluatedResult), [downstreamPlan, evaluatedResult, result, seed]);
  const evaluatedReadinessEvents = useMemo(() => evaluatedResult === result && readinessEvents ? readinessEvents : buildDeliveryReadinessEvents(seed, evaluatedResult, evaluatedDownstreamPlan), [evaluatedDownstreamPlan, evaluatedResult, readinessEvents, result, seed]);
