          {selectedPullForwardAdvice && <button className="machine-pull-forward-action" onClick={() => onApplyAdvice(selectedPullForwardAdvice)}><Lightbulb size={13} weight="fill" /> {selectedPullForwardAdvice.actionLabel}</button>}
          {selectedMachineAdvice.length > 1 && <button className="machine-all-advice-action" onClick={() => onOpenMachineAdvice(selectedDiagnosticMachine.id)}>{selectedMachineAdvice.length} tavsiyenin tümü</button>}
          {!selectedPullForwardAdvice && selectedDiagnostic.suggestion && selectedDiagnostic.suggestion.improvementDays > 0 && <><span>{selectedDiagnostic.suggestion.product}</span><small>{selectedDiagnostic.suggestion.fromMachineId} → {selectedDiagnostic.suggestion.toMachineId}</small><button onClick={() => { onMoveBatch(selectedDiagnostic.suggestion!.batchId, selectedDiagnostic.suggestion!.toMachineId, 0); setDiagnosticMachineId(null); }}>Bu alternatifi uygula</button></>}
          <button className="machine-info-action" onClick={() => setJobEditorMachineId(selectedDiagnosticMachine.id)}><PencilSimple size={13} /> Mevcut işi düzenle</button><button className="machine-info-action complete" disabled={!selectedDiagnosticMachine.currentJob.product} onClick={() => setCompleteMachineId(selectedDiagnosticMachine.id)}><ProcessIcon process="turning" size={14} /> Torna prosesini bitir</button>
        </div>
        <button className="gantt-diagnostic-close" onClick={() => setDiagnosticMachineId(null)} aria-label="Tezgah bilgisini kapat">×</button>
      </div>}
      {ganttProcess !== "turning" && <div className="process-gantt-summary">
        <span><small>Görünen iş</small><strong>{downstreamOperations.length}</strong></span>
        <span><small>Görünen istasyon</small><strong>{processResources.length}</strong></span>
        <span><small>Proses bitişi</small><strong>{downstreamOperations.length ? formatExcelDate(Math.max(...downstreamOperations.map((operation) => operation.end))) : "—"}</strong></span>
        <span><small>Rota + tampon bitişi</small><strong>{downstreamPlan.deliveryCompletion ? formatExcelDate(downstreamPlan.deliveryCompletion) : "—"}</strong></span>
        {selectedProcessOperation && selectedProcessJob ? <div className="process-gantt-selection"><button onClick={() => onSelectProcessOperation("")} aria-label="Seçili proses işini kapat"><X size={13} /></button><p><b>{selectedProcessOperation.product}</b><span>{selectedProcessOperation.workOrder || selectedProcessOperation.batchId} · {formatNumber(selectedProcessOperation.quantity)} adet</span></p><p><b><ProcessIcon process={selectedProcessOperation.process} size={14} /> {processLabel(selectedProcessOperation.process)} seçildi{selectedProcessOperation.manualOverride ? " · manuel yerleşim" : ""}</b><span>Rota sağ panelde açıldı · {selectedProcessOperation.resourceId}</span></p><p><b>Teslimata hazır</b><span>{formatExcelDate(selectedProcessJob.deliveryReadyAt)} · GKM sonrası +1 iş günü</span></p>{selectedProcessOperation.manualOverride && <button className="process-auto-placement" onClick={() => onReviewRoute({ kind: "edit", batchId: selectedProcessOperation.batchId, process: selectedProcessOperation.process })}><ArrowCounterClockwise size={12} /> Üretim akışını düzenle</button>}</div> : <p className="process-gantt-hint">Bir işe tıklayın; şarjın tam rotası sağ panelde açılır.</p>}
      </div>}
      <div className={`timeline ${ganttProcess === "turning" ? "turning-timeline" : ""} ${recentMovedBatchId || recentMovedProcessOperationId ? "layout-animated" : ""}`} style={timelineStyle}>
        <div className="timeline-head">
          <div className="machine-title">{ganttProcess === "turning" ? "TEZGAH" : "İSTASYON"}</div>
          {ganttProcess === "turning" && <div className="machine-lock-title" title="Tezgah kuyruğunun tamamını kilitle veya aç"><Lock size={12} /></div>}
          <div className="calendar-scale" aria-label={`${formatExcelDate(horizonStart)} ile ${formatExcelDate(horizonEnd - 1)} arasındaki Gantt takvimi`}>
            <div className="month-scale">
              {ganttCalendar.months.map((month) => <span key={month.key} title={month.fullLabel} style={{ gridColumn: `${month.startIndex + 1} / span ${month.dayCount}` }}>{month.label}</span>)}
            </div>
            <div className="week-scale">
              {ganttCalendar.weeks.map((week) => <span key={week.key} title={week.fullLabel} style={{ gridColumn: `${week.startIndex + 1} / span ${week.dayCount}` }}>{week.label}</span>)}
            </div>
            <div className="day-scale">
              {ganttCalendar.days.map((day) => <span key={day.serial} className={`${day.isSunday ? "sunday" : ""} ${holidaySerials.has(day.serial) ? "holiday" : ""} ${day.serial === todaySerial ? "today" : ""}`} title={day.fullLabel}>{day.dayOfMonth}</span>)}
            </div>
          </div>
        </div>
        {ganttProcess === "turning" ? visibleMachines.map((machine) => {
          const machineBatches = machineBatchesById.get(machine.id) ?? [];
          const calendarDays = calendarBandsByMachine.get(machine.id) ?? [];
          const machineAdviceCount = adviceByMachine.get(machine.id)?.length ?? 0;
          const lockedBatchCount = machineBatches.filter((batch) => batch.locked).length;
          const hasLockedBatches = lockedBatchCount > 0;
          const lastMachineBatch = [...machineBatches].sort((left, right) => left.planColumn - right.planColumn || left.start - right.start).at(-1);
          const queueLockLabel = !machineBatches.length
            ? `${machine.id} tezgahında kilitlenecek planlı iş yok`
            : hasLockedBatches
              ? `${machine.id} tezgahındaki ${lockedBatchCount} planlı işin kilidini kaldır`
              : `${machine.id} tezgahındaki ${machineBatches.length} planlı işin tamamını kilitle`;
          return (
            <div className={`machine-row ${compatibleDropMachineIds.has(machine.id) ? "drag-compatible" : ""}`} key={machine.id}>
              <button className={`machine-label ${diagnosticMachineId === machine.id ? "selected" : ""} ${machineAdviceCount ? "has-advice" : ""}`} onClick={() => setDiagnosticMachineId(machine.id)} aria-label={`${machine.id} tezgah bilgisini göster${machineAdviceCount ? ` · ${machineAdviceCount} tavsiye` : ""}`}><span className="status on" /><strong>{machine.id}</strong><small>{machine.name}</small>{machineAdviceCount > 0 ? <span className="machine-advice-marker" aria-label={`${machineAdviceCount} tezgah tavsiyesi`}><Lightbulb size={12} weight="fill" /><b>{machineAdviceCount}</b></span> : overtimeMachineIds.has(machine.id) ? <Clock className="machine-overtime-marker" size={13} weight="fill" aria-label="Görünür tarihlerde mesai var" /> : !machineBatches.length && <Warning className="machine-empty-warning" size={13} weight="fill" aria-label={diagnostics[machine.id].title} />}</button>
              <button type="button" className={`machine-queue-lock ${hasLockedBatches ? "locked" : ""}`} disabled={!lastMachineBatch} aria-pressed={hasLockedBatches} aria-label={queueLockLabel} title={queueLockLabel} onClick={() => { if (!lastMachineBatch) return; if (hasLockedBatches) onUnlockQueue(machine.id); else onLockThrough(lastMachineBatch); }}>{hasLockedBatches ? <Lock size={14} weight="fill" /> : <LockOpen size={14} />}</button>
              <div data-machine-id={machine.id} className={`track ${compatibleDropMachineIds.has(machine.id) ? "drag-compatible" : ""} ${dropTarget?.machineId === machine.id ? dropPreview?.valid ? "drop-valid" : "drop-invalid" : ""}`}>
                <div className="grid-lines" />
                {calendarDays.map(({ serial, capacity }) => {
                  const editable = capacity.kind === "sunday" || capacity.kind === "holiday" || capacity.kind === "shift";
                  const overtime = overtimeEntryKeys.has(`${machine.id}-${serial}`);
                  return <button type="button" key={`${machine.id}-${serial}`} className={`calendar-band ${capacity.kind} ${capacity.shifts > 0 ? "working" : "shutdown"} ${overtime ? "overtime" : ""} ${editable ? "editable" : ""}`} style={{ left: `${ganttPercent(serial, horizonStart, horizon)}%`, width: `${100 / horizon}%` }} title={`${formatExcelDate(serial)} · ${capacity.label}${overtime ? " · mesai kapasitesi" : ""}${editable ? " · vardiyayı değiştirmek için tıklayın" : ""}`} aria-label={`${machine.id} ${formatExcelDate(serial)} ${capacity.label}${overtime ? " mesai" : ""}${editable ? " üretim ayarı" : ""}`} disabled={!editable} onClick={() => editable && setCalendarSelection({ resourceId: machine.id, process: "turning", serial })} />;
                })}
                {todaySerial >= horizonStart && todaySerial < horizonEnd && <i className="today-line" style={{ left: `${ganttPercent(todaySerial, horizonStart, horizon)}%` }} aria-label="Bugün" />}
                {machine.currentJob.product && machine.currentJob.end > machine.currentJob.start && <button key={`${machine.id}-current-job`} className={`batch running-batch ${machine.currentJob.rolledForwardFrom ? "carried-over" : ""} ${selectedCurrentMachineId === machine.id ? "selected" : ""}`} style={position(machine.currentJob.start, machine.currentJob.end, horizonStart, horizon)} title={`Mevcut üretim · Ürün: ${machine.currentJob.product} · Aile: ${productSetupFamilyLabel(productSetupFamily(seed, machine.currentJob.product))} · Şarj / iş emri: ${machine.currentJob.workOrder || "yok"} · Kalan adet: ${formatNumber(machine.currentJob.remainingQuantity ?? machine.currentJob.quantity)} · Tahmini bitiş: ${formatExcelDate(machine.currentJob.end)}${machine.currentJob.rolledForwardFrom ? ` · Geçmişten devretti: eski bitiş ${formatExcelDate(machine.currentJob.rolledForwardFrom)}` : ""}`} onClick={() => { setDiagnosticMachineId(null); onSelectCurrentJob(machine.id); }}><span><Play size={9} weight="fill" />{machine.currentJob.product}</span><small className="running-work-order">{machine.currentJob.rolledForwardFrom ? "GEÇMİŞTEN DEVREDEN · " : ""}{machine.currentJob.workOrder || "Şarj no yok"}</small></button>}
                {machineBatches.map((batch) => {
                  const demandOrigin = plannedBatchDemandOrigin(seed, batch);
                  const demandLabel = demandOrigin?.label ?? "Talep haftası bağlı değil";
                  return <button key={batch.id} className={`batch ${selectedBatch?.id === batch.id ? "selected" : ""} ${batch.locked ? "locked" : ""} ${batch.manuallyPlaced ? "manual" : ""} ${batch.rolledForwardFrom ? "delayed-plan" : ""} ${batch.pullForward ? "pulled-forward" : ""} ${draggedBatchId === batch.id ? "dragging" : ""} ${recentMovedBatchId === batch.id ? "just-moved" : ""}`} style={{ ...position(batch.start, batch.end, horizonStart, horizon), ...diameterStyle(batch.diameter, diameterHues) }} title={`${batch.product} · ${productSetupFamilyLabel(productSetupFamily(seed, batch.product))} · ${batch.diameter} · Setup ${formatHours(batch.setupHours)} · ${formatExcelDate(batch.start)}–${formatExcelDate(batch.end)}${batch.rolledForwardFrom ? ` · üretime başlanmamış eski plan tarihi ${formatExcelDate(batch.rolledForwardFrom)}; güncel kuyruğa yeniden tarihlendi` : ""} · Talep kaynağı: ${demandLabel}${batch.pullForward ? ` · ${batch.pullForward.sourceWeekLabel} talebinden öne çekildi` : ""}`} onClick={() => { if (suppressBatchClickRef.current) { suppressBatchClickRef.current = false; return; } onSelectBatch(batch.id); }} onPointerDown={(event) => beginPointerMove(event, batch)} onPointerMove={continuePointerMove} onPointerUp={endPointerMove} onPointerCancel={endPointerMove}><span>{batch.pullForward ? <Lightbulb size={10} weight="fill" /> : batch.locked ? <Lock size={10} weight="fill" /> : <DotsSixVertical size={10} />}{batch.product}</span><small>{batch.rolledForwardFrom ? "GECİKMİŞ PLAN · " : batch.pullForward ? `${batch.pullForward.sourceWeekLabel}’den · ` : ""}{demandOrigin ? `${demandOrigin.weekLabel} · ${demandOrigin.shortDateLabel} · ` : "HEDEF HAFTA YOK · "}{batch.diameter} · {formatNumber(batch.quantity)} · {queuePosition(batch.planColumn)}. sıra</small></button>;
                })}
              </div>
            </div>
          );
        }) : processResources.map(({ resource, operations, gaps }) => {
          const calendarDays = processCalendarBandsByResource.get(resource.id) ?? [];
          return <div className="machine-row process-resource-row" key={resource.id}>
            <div className="machine-label process-resource-gantt-label"><span className={`status ${resource.defaultShifts > 0 ? "on" : "off"}`} /><strong>{resource.id}</strong><small>{resource.name}</small><em>{operations.length} iş{gaps.length ? ` · ${gaps.length} açıklama` : ""}</em></div>
            <div className={`track process-resource-track ${processDropTarget?.resourceId === resource.id ? processDropPreview?.valid ? "drop-valid" : "drop-invalid" : ""}`} data-process-resource-id={resource.id}>
              <div className="grid-lines" />
              {calendarDays.map(({ serial, capacity }) => {
                const editable = capacity.kind === "sunday" || capacity.kind === "holiday" || capacity.kind === "shift";
                return <button type="button" key={`${resource.id}-${serial}`} className={`calendar-band ${capacity.kind} ${capacity.shifts > 0 ? "working" : "shutdown"} ${editable ? "editable" : ""}`} style={{ left: `${ganttPercent(serial, horizonStart, horizon)}%`, width: `${100 / horizon}%` }} title={`${formatExcelDate(serial)} · ${capacity.label}${editable ? " · vardiyayı değiştirmek için tıklayın" : ""}`} aria-label={`${resource.id} ${formatExcelDate(serial)} ${capacity.label}${editable ? " üretim ayarı" : ""}`} disabled={!editable} onClick={() => editable && setCalendarSelection({ resourceId: resource.id, process: ganttProcess, serial })} />;
              })}
              {todaySerial >= horizonStart && todaySerial < horizonEnd && <i className="today-line" style={{ left: `${ganttPercent(todaySerial, horizonStart, horizon)}%` }} aria-label="Bugün" />}
              {processDropTarget?.resourceId === resource.id && <>
                <i className="process-drop-request" style={{ left: `${ganttPercent(processDropTarget.requestedStart, horizonStart, horizon)}%` }} />
                {processDropPreview?.valid && <div className="process-drop-placement" style={position(processDropPreview.operation.start, processDropPreview.operation.end, horizonStart, horizon)}><span>{processDropPreview.preview.insertionIndex + 1}. sıra · {placementDate(processDropPreview.operation.start)}</span></div>}
              </>}
              {gaps.map((gap) => <span key={gap.id} className={`process-gap ${gap.code}`} style={position(gap.start, gap.end, horizonStart, horizon)} tabIndex={0} aria-label={`${resource.id} boşluk açıklaması: ${gap.message}`}><Warning size={9} weight="fill" /><span className="process-gap-tooltip" role="tooltip"><strong>{resource.id} · Plan boşluğu</strong><small>{gap.message}</small></span></span>)}
              {operations.map((operation) => <button ref={operation.id === recentMovedProcessOperationId ? movedElementRef : undefined} key={operation.id} className={`batch process-gantt-batch ${operation.process} ${operation.process === "drilling" && !operation.setupKey.trim() ? "missing-setup" : ""} ${operation.actual ? "actual" : "planned"} ${operation.manualOverride ? "manual" : ""} ${draggedProcessOperationId === operation.id ? "dragging" : ""} ${recentMovedProcessOperationId === operation.id ? "just-moved" : ""} ${selectedProcessOperation?.id === operation.id ? "selected" : ""}`} style={{ ...position(operation.start, operation.end, horizonStart, horizon), ...processOperationStyle(operation, processSetupHues), ...(draggedProcessOperationId === operation.id ? { "--process-drag-x": `${processDragOffset.x}px`, "--process-drag-y": `${processDragOffset.y}px` } as React.CSSProperties : {}) }} title={`${operation.product} · ${operation.workOrder || operation.batchId} · ${formatNumber(operation.quantity)} adet${operation.process === "drilling" ? ` · Matkap ${operation.setupKey || "EKSİK"}` : ""} · Setup ${formatHours(operation.setupHours)}${operation.manualOverride ? " · Manuel Gantt yerleşimi" : ""}${operation.protectedSetupHoursAfter ? ` · D-02 Center Pin dönüş rezervi ${formatHours(operation.protectedSetupHoursAfter)}` : ""} · ${formatExcelDate(operation.start)}–${formatExcelDate(operation.end)}`} onClick={() => { if (suppressProcessClickRef.current) { suppressProcessClickRef.current = false; return; } onSelectProcessOperation(operation.id); }} onPointerDown={(event) => beginProcessPointerMove(event, operation)} onPointerMove={continueProcessPointerMove} onPointerUp={endProcessPointerMove} onPointerCancel={cancelProcessPointerMove} onLostPointerCapture={cancelProcessPointerMove}><span>{operation.actual ? <CheckCircle size={10} weight="fill" /> : operation.manualOverride ? <DotsSixVertical size={10} /> : <Clock size={10} />}{operation.product}</span><small>{operation.process === "drilling" ? operation.setupKey ? `${operation.setupKey} · ` : "MATKAP EKSİK · " : ""}{operation.workOrder || `${formatNumber(operation.quantity)} adet`}</small></button>)}
              {!operations.length && <span className="process-resource-empty">{resource.defaultShifts <= 0 ? "0 vardiya · kapasite kapalı" : resource.eligibleProductGroups?.length === 0 ? "Uygun ürün grubu tanımlı değil" : downstreamOperations.length === 0 ? "Prosese hazır WIP yok" : "Bu istasyona uygun ürün / hız yok"}</span>}
            </div>
          </div>;
        })}
      </div>
      {ganttProcess === "turning" && jobEditorMachineId && <CurrentJobEditor seed={seed} result={result} machine={seed.machines.find((machine) => machine.id === jobEditorMachineId)!} onClose={() => setJobEditorMachineId(null)} onSave={(input, remainingAsOf) => { onSaveCurrentJob(jobEditorMachineId, input, remainingAsOf); setJobEditorMachineId(null); setDiagnosticMachineId(jobEditorMachineId); }} />}
      {ganttProcess === "turning" && completeMachineId && <CompleteJobDialog machine={seed.machines.find((machine) => machine.id === completeMachineId)!} nextBatch={plannedBatches.filter((batch) => batch.machineId === completeMachineId).sort((left, right) => left.planColumn - right.planColumn)[0]} onClose={() => setCompleteMachineId(null)} onConfirm={(completedAt, completedQuantity, remainderAction) => { onCompleteCurrentJob(completeMachineId, completedAt, completedQuantity, remainderAction); setCompleteMachineId(null); setDiagnosticMachineId(completeMachineId); }} />}
      {calendarSelection && calendarCapacityTarget && <GanttCapacityDialog seed={seed} machine={calendarCapacityTarget} serial={calendarSelection.serial} resourceKind={calendarSelection.process === "turning" ? "tezgah" : "istasyon"} allScopeLabel={calendarSelection.process === "turning" ? "Tüm aktif tezgahlar" : `Tüm aktif ${processLabel(calendarSelection.process)} istasyonları`} onClose={() => setCalendarSelection(null)} onSave={(scope, name, start, end, shifts, editingId) => { updateSeed((draft) => { if (editingId) { const existing = (draft.calendarEvents ?? []).find((event) => event.id === editingId); if (existing) removeMachineShiftOverrides(draft, [existing.machineId], existing.start, existing.end); } const resourceIds = scope === "all"
        ? calendarSelection.process === "turning"
          ? draft.machines.filter((machine) => machine.active).map((machine) => machine.id)
          : (draft.processMasterData?.resources ?? []).filter((resource) => resource.active && resource.process === calendarSelection.process).map((resource) => resource.id)
        : [calendarSelection.resourceId];
        replaceMachineShiftOverrides(draft, resourceIds, start, end, shifts, name); }); setCalendarSelection(null); }} onDelete={(eventId) => { updateSeed((draft) => { const existing = (draft.calendarEvents ?? []).find((event) => event.id === eventId); if (existing) removeMachineShiftOverrides(draft, [existing.machineId], existing.start, existing.end); }); setCalendarSelection(null); }} />}
    </div>
  );
}

function GanttCapacityDialog({ seed, machine, serial, resourceKind, allScopeLabel, onClose, onSave, onDelete }: { seed: PlanningSeed; machine: Pick<Machine, "id" | "shiftFactor">; serial: number; resourceKind: "tezgah" | "istasyon"; allScopeLabel: string; onClose: () => void; onSave: (scope: "machine" | "all", name: string, start: number, end: number, shifts: ShiftCount, editingId?: string) => void; onDelete: (eventId: string) => void }) {
  const capacity = machineDayCapacity(seed, machine, serial);
  const existingShift = [...(seed.calendarEvents ?? [])].reverse().find((event) => event.machineId === machine.id && event.kind === "shift" && serial >= Math.floor(event.start) && serial <= Math.floor(event.end));
  const [scope, setScope] = useState<"machine" | "all">("machine");
  const [draft, setDraft] = useState<{ name: string; start: string; end: string; shifts: ShiftCount }>({ name: existingShift?.name ?? `${formatExcelDate(serial)} Gantt vardiya ayarı`, start: serialToInputDate(existingShift?.start ?? serial), end: serialToInputDate(existingShift?.end ?? serial), shifts: capacity.kind === "shift" ? capacity.shifts : capacity.shifts || clampShiftCount(machine.shiftFactor) || 1 });
  const start = inputDateToSerial(draft.start);
  const end = inputDateToSerial(draft.end);
  const valid = Boolean(draft.name.trim() && start && end && end >= start);
  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog capacity-dialog" role="dialog" aria-modal="true" aria-label={`${formatExcelDate(serial)} üretim ayarı`}><div className="operational-dialog-head"><span className={`dialog-icon ${capacity.kind}`}><CalendarBlank size={20} /></span><div><span>GANTT KAPASİTE AYARI</span><h2>{existingShift ? "Vardiya kaydını düzenle" : formatExcelDate(serial)}</h2><p>{capacity.label} · {machine.id} {resourceKind} kapasitesi {capacity.shifts} vardiya.</p></div><button className="delete-button" onClick={onClose} aria-label="Kapasite ayarını kapat"><X size={16} /></button></div><div className="operational-dialog-form"><Field label={`Uygulanacak ${resourceKind}lar`}><select value={scope} onChange={(event) => setScope(event.target.value as "machine" | "all")}><option value="machine">Yalnızca {machine.id}</option><option value="all">{allScopeLabel}</option></select></Field><Field label="Açıklama"><input value={draft.name} onChange={(event) => setDraft({ ...draft, name: event.target.value })} /></Field><div className="dialog-date-range"><Field label="Başlangıç"><input type="date" value={draft.start} onChange={(event) => setDraft({ ...draft, start: event.target.value, end: event.target.value > draft.end ? event.target.value : draft.end })} /></Field><Field label="Bitiş"><input type="date" min={draft.start} value={draft.end} onChange={(event) => setDraft({ ...draft, end: event.target.value })} /></Field></div><Field label="Çalışılacak vardiya"><select value={draft.shifts} onChange={(event) => setDraft({ ...draft, shifts: clampShiftCount(Number(event.target.value)) })}><ShiftOptions /></select></Field><div className="calendar-impact-note"><strong>{draft.shifts === 0 ? "Üretim yapılmayacak" : `${draft.shifts} vardiya üretim açılacak`}</strong><span>Kaydettiğinizde mevcut kuyruk korunur ve bütün başlangıç/bitiş tarihleri hemen yeniden hesaplanır.</span></div><div className="drawer-actions">{existingShift && <button className="danger-outline" onClick={() => onDelete(existingShift.id)}><Trash size={14} /> Kaydı kaldır</button>}<button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={!valid} onClick={() => onSave(scope, draft.name.trim(), start, end, draft.shifts, existingShift?.id)}>{existingShift ? "Değişikliği kaydet" : "Uygula ve hesapla"}</button></div></div></section></div>;
}

function position(start: number, end: number, horizonStart: number, horizon: number): React.CSSProperties {
  const horizonEnd = horizonStart + horizon;
  if (end <= horizonStart || start >= horizonEnd) return { display: "none" };
  const visibleStart = Math.max(start, horizonStart);
  const visibleEnd = Math.min(end, horizonEnd);
  return { left: `${ganttPercent(visibleStart, horizonStart, horizon)}%`, width: `${Math.max(0.8, ganttPercent(visibleEnd, visibleStart, horizon))}%` };
}

const DIAMETER_HUE_WHEEL = [24, 205, 130, 275, 46, 340, 178, 90, 240, 0, 310, 160];

function buildDiameterHues(seed: PlanningSeed, result: ScenarioResult): Map<number, number> {
  const values = new Set<number>();
  for (const product of seed.products) {
    const numeric = diameterNumeric(product.diameter);
    if (numeric > 0) values.add(numeric);
  }
  for (const batch of result.batches) {
    const numeric = diameterNumeric(batch.diameter);
    if (numeric > 0) values.add(numeric);
  }
  return new Map([...values].sort((left, right) => left - right).map((value, index) => [value, DIAMETER_HUE_WHEEL[index % DIAMETER_HUE_WHEEL.length]]));
}

function diameterStyle(rawDiameter: string, hues: Map<number, number>): React.CSSProperties {
  const diameter = diameterNumeric(rawDiameter) || 20;
  const ratio = Math.max(0, Math.min(1, (diameter - 14) / 19));
  const height = Math.round(30 + ratio * 16);
  const hue = hues.get(diameter) ?? 24;
  return {
    "--batch-height": `${height}px`,
    "--batch-bg": `hsl(${hue} 82% 93%)`,
    "--batch-border": `hsl(${hue} 48% 50%)`,
    "--batch-ink": `hsl(${hue} 65% 24%)`,
  } as React.CSSProperties;
}

function buildProcessSetupHues(operations: ProcessOperation[]): Map<string, number> {
  const setupKeys = [...new Set(operations
    .filter((operation) => operation.process === "drilling" && operation.setupKey.trim())
    .map((operation) => operation.setupKey.trim()))]
    .sort((left, right) => left.localeCompare(right, "tr", { numeric: true }));
  return new Map(setupKeys.map((setupKey, index) => [setupKey, DIAMETER_HUE_WHEEL[index % DIAMETER_HUE_WHEEL.length]]));
}

function processOperationStyle(operation: ProcessOperation, hues: Map<string, number>): React.CSSProperties {
  if (operation.process !== "drilling" || !operation.setupKey.trim()) return {};
  const hue = hues.get(operation.setupKey.trim()) ?? DIAMETER_HUE_WHEEL[0];
  return {
    "--batch-bg": `hsl(${hue} 82% 93%)`,
    "--batch-border": `hsl(${hue} 48% 50%)`,
    "--batch-ink": `hsl(${hue} 65% 24%)`,
  } as React.CSSProperties;
}

