import type { PlanningSeed } from "../../../lib/planning";
import type { DeactivationTarget } from "../../../lib/parameter-deactivation";
import { applyCompletePackage, dataPackageSummary } from "../../../lib/data-packages";
import type { SaveParameterDraft } from "./ParameterDeactivationDialog";

export function canUseCompletePackage(seed: PlanningSeed, isAdmin: boolean): boolean {
  return seed.productionArea !== "cubuk-filtre" && isAdmin;
}

export async function importCompletePackageWithReview(seed: PlanningSeed, raw: unknown, save?: SaveParameterDraft): Promise<boolean> {
  if (!save) throw new Error("Tam yedek incelemesi kullanılamıyor. Ekranı yeniden yükleyin.");
  const targets = completePackageReviewTargets(seed, raw);
  return save(draft => applyCompletePackage(draft, raw), targets);
}

/** Collect review targets only. The package applier remains the validator. */
export function completePackageReviewTargets(seed: PlanningSeed, raw: unknown): DeactivationTarget[] {
  dataPackageSummary("complete", raw);
  return parameterPackageReviewTargets(seed, (raw as { parameters: unknown }).parameters);
}

export function parameterPackageReviewTargets(seed: PlanningSeed, raw: unknown): DeactivationTarget[] {
  dataPackageSummary("parameters", raw);
  const value = raw as { products: PlanningSeed["products"]; processMasterData?: PlanningSeed["processMasterData"] };
  const targets: DeactivationTarget[] = [];
  for (const product of value.products) {
    const before = seed.products.find(item => item.product === product.product);
    for (const resourceId of product.inactiveMachineIds ?? []) {
      if (!before?.inactiveMachineIds?.includes(resourceId)) targets.push({ process: "turning", product: product.product, resourceId });
    }
  }
  for (const product of value.processMasterData?.products ?? []) {
    const before = seed.processMasterData?.products.find(item => item.product === product.product);
    for (const parameter of product.processes) {
      const previous = before?.processes.find(item => item.process === parameter.process);
      for (const resourceId of parameter.inactiveResourceIds ?? []) {
        if (!previous?.inactiveResourceIds?.includes(resourceId)) targets.push({ process: parameter.process, product: product.product, resourceId });
      }
    }
  }
  return [...new Map(targets.map(target => [`${target.process}:${target.product}:${target.resourceId}`, target])).values()];
}

