export type ProductionSyncChoice = "keep-local" | "use-source" | "combine";
export type ProductionSyncGroup = {
  id: string; label: string; status: string;
  defaultChoice: ProductionSyncChoice | null;
  allowedChoices: ProductionSyncChoice[];
  summary: unknown;
};
export type ProductionSyncPreview = {
  previewId?: string; sourceUpdatedAt: string; sourceDigest: string;
  localUpdatedAt: string; localDigest: string; baselineDigest: string | null;
  groups: ProductionSyncGroup[];
  settingsKeys: { keptLocal: string[]; fromSource: string[]; bothChanged: string[] };
  scenarios: { sourceCount: number; newIds: (string | number)[] };
};
const choices: ProductionSyncChoice[] = ["keep-local", "use-source", "combine"];
const record = (value: unknown): value is Record<string, unknown> => Boolean(value) && typeof value === "object" && !Array.isArray(value);
const strings = (value: unknown): value is string[] => Array.isArray(value) && value.every(item => typeof item === "string");
function validSummary(value: unknown): boolean {
  if (!record(value) || !record(value.collections)) return false;
  if (value.currentJobMachines !== undefined && !strings(value.currentJobMachines)) return false;
  return Object.values(value.collections).every(counts => record(counts) && (
    counts.changed === true || ["onlyLocal", "onlySource", "different"].every(key => Number.isInteger(counts[key]) && Number(counts[key]) >= 0)
  ));
}

export function isProductionSyncPreview(value: unknown): value is ProductionSyncPreview {
  if (!record(value) || !["sourceUpdatedAt", "sourceDigest", "localUpdatedAt", "localDigest"].every(key => typeof value[key] === "string" && value[key])) return false;
  if (value.baselineDigest !== null && typeof value.baselineDigest !== "string") return false;
  if (!Array.isArray(value.groups) || value.groups.length !== 3) return false;
  const ids = new Set<string>();
  for (const group of value.groups) {
    if (!record(group) || typeof group.id !== "string" || !["physical", "orders", "annotations"].includes(group.id) || ids.has(group.id) || typeof group.label !== "string" || typeof group.status !== "string" || !["same", "source-changed", "local-changed", "both-changed", "no-baseline"].includes(String(group.status)) || !validSummary(group.summary)) return false;
    ids.add(group.id);
    if (!Array.isArray(group.allowedChoices) || !group.allowedChoices.length || !group.allowedChoices.every(choice => choices.includes(choice))) return false;
    if (group.id !== "annotations" && group.allowedChoices.includes("combine")) return false;
    if (group.defaultChoice !== null && !group.allowedChoices.includes(group.defaultChoice)) return false;
    if (["both-changed", "no-baseline"].includes(group.status) && group.defaultChoice !== null) return false;
  }
  const settings = value.settingsKeys;
  if (!record(settings) || !["keptLocal", "fromSource", "bothChanged"].every(key => strings(settings[key]))) return false;
  return record(value.scenarios) && Number.isInteger(value.scenarios.sourceCount) && Number(value.scenarios.sourceCount) >= 0 && Array.isArray(value.scenarios.newIds) && value.scenarios.newIds.every(id => typeof id === "string" || typeof id === "number");
}

export function buildProductionSyncApply(preview: ProductionSyncPreview, selected: Record<string, string>) {
  if (!isProductionSyncPreview(preview)) throw new Error("Üretim önizlemesi eksik. Yeniden inceleyin.");
  const selectedChoices: Record<string, ProductionSyncChoice> = {};
  for (const group of preview.groups) {
    const choice = selected[group.id] ?? group.defaultChoice;
    if (!choice || !group.allowedChoices.includes(choice as ProductionSyncChoice)) throw new Error(`${group.label}: hangi kayıtların kullanılacağını seçin.`);
    selectedChoices[group.id] = choice as ProductionSyncChoice;
  }
  return { action: "apply" as const, expected: {
    sourceDigest: preview.sourceDigest, localUpdatedAt: preview.localUpdatedAt,
    localDigest: preview.localDigest, baselineDigest: preview.baselineDigest,
  }, choices: selectedChoices };
}

