"use client";
import { useEffect, useRef, useState, useSyncExternalStore } from "react";
import { useRaviScreenContext } from "@/features/ravi/context";
import { formatFactoryDateTime } from "@/features/planning/shared/format";
import type { PlanningSyncStatus } from "@/lib/planning-persistence";

import type { CollaborationClock } from "../shared/collaboration-clock";

export type SharedPlanPublication = { id: string; scope: string; scenarioId: string; scenarioRevision: number; scenarioName: string | null; approvedBy: { id: string; name: string | null }; approvedAt: string };

export function CollaborationBar({ cacheWarning = false, publication, onScenarios, name, revision, status, pending, failed, sharedStatus, connected, lastChecked: initialLastChecked, clock, onNew, onShared, onPublish, onRefreshInputs, onRetry, onPreserve, onReview, onDownload, canPublish }: {
  cacheWarning?: boolean; publication?: SharedPlanPublication | null; onScenarios: () => void;
  name?: string; revision?: number; status: string; pending: boolean; failed: boolean; sharedStatus: PlanningSyncStatus; connected: boolean; lastChecked: string; clock?: CollaborationClock;
  onNew: () => void; onShared: () => void; onPublish: () => void; onRefreshInputs: () => void; onRetry: () => void; onPreserve: () => void; onReview: () => void; onDownload: () => void; canPublish: boolean;
}) {
  const lastChecked = useSyncExternalStore(clock?.subscribe ?? noClockSubscription, clock?.getSnapshot ?? (() => initialLastChecked), () => initialLastChecked);
  const sharedFailure = !name && !pending && (sharedStatus === "offline" || sharedStatus === "conflict");
  const needsRecovery = (pending && failed) || sharedFailure;
  const saving = (pending && !failed) || (!name && !pending && sharedStatus === "saving");
  const [open, setOpen] = useState(needsRecovery || cacheWarning);
  const [guideOpen, setGuideOpen] = useState(false);
  const [guideNotesOpen, setGuideNotesOpen] = useState(false);
  const card = useRef<HTMLDivElement>(null);
  useEffect(() => { if (needsRecovery || cacheWarning) setOpen(true); }, [needsRecovery, cacheWarning]);
  useEffect(() => {
    if (!open) return;
    const close = (event: PointerEvent) => { if (!card.current?.contains(event.target as Node)) setOpen(false); };
    document.addEventListener("pointerdown", close);
    return () => document.removeEventListener("pointerdown", close);
  }, [open]);
  const saveLabel = needsRecovery ? "Kayıt onaylanmadı" : saving ? "Kaydediliyor…" : !name && sharedStatus === "loading" ? "Kayıt kontrol ediliyor…" : !connected ? "Bağlantı kesildi" : cacheWarning ? "Yerel yedek alınamadı" : name ? "Taslak kaydedildi" : "Kaydedildi";
  const recoveryAction = needsRecovery ? pending ? "Yeniden dene" : "Güncel kaydı kontrol et" : null;
  useRaviScreenContext("collaboration", { mode: name ? "personal-draft" : "shared-production", name, revision, status, saveLabel, saving, recoveryAction, pending, failed, sharedStatus, connected, lastChecked, canPublish, controlsOpen: open, guideOpen, guideNotesOpen, publication, needsRecovery, cacheWarning });
  const act = (action: () => void) => { setOpen(false); action(); };
  return <div id="planning-workspace" ref={card} className={`plan-nav-card${needsRecovery || cacheWarning ? " has-error" : ""}`} role="region" aria-label="Plan çalışma alanı" onKeyDown={event => { if (event.key === "Escape") { setOpen(false); card.current?.querySelector<HTMLButtonElement>(".plan-nav-toggle")?.focus(); } }}>
    <button className="plan-nav-toggle" aria-expanded={open} aria-controls="plan-nav-panel" onClick={() => setOpen(!open)}>
      <span className="plan-nav-copy"><strong title={name}>{name ? "Kişisel taslak" : "Ortak plan"}</strong><span className="plan-nav-status" role="status"><i aria-hidden="true" className={needsRecovery || cacheWarning || !connected ? "warning" : saving ? "saving" : ""} />{saveLabel}</span></span>
      <span aria-hidden="true" className="plan-nav-chevron">⌄</span>
    </button>
    {!name && <button className="plan-nav-new" disabled={pending || sharedStatus !== "synced"} onClick={onNew}>Yeni taslak</button>}
    {open && <div id="plan-nav-panel" className="plan-nav-panel">
      <div className="plan-nav-description"><strong>{name ?? "Ortak plan"}</strong><p>{name ? `Kişisel çalışma alanınız · Sürüm ${revision}. Taslak değişiklikleri ortak üretimi değiştirmez.` : "Üretim ve teslimatlar herkes için ortak."}</p></div>
      <section className="plan-nav-approval" aria-label="Ortak plan onayı">
        <strong>Ortak planı onaylayan</strong>
        {publication === undefined ? <p>Onay bilgisi yükleniyor…</p> : publication === null ? <p>Henüz onaylanmış bir yayın yok. Mevcut üretim kayıtları ortak kullanılmaya devam eder.</p> : <>
          <p className="plan-nav-approver">{publication.approvedBy.name || `Kullanıcı: ${publication.approvedBy.id}`}</p>
          {!publication.approvedBy.name && <small>Eski kayıt: kişinin adı kaydedilmemiş.</small>}
          <p>{formatFactoryDateTime(publication.approvedAt)} · Türkiye saati</p>
          <small>{publication.scenarioName || "Kayıtlı plan"} · Sürüm {publication.scenarioRevision}</small>
        </>}
        {!connected && <small>Bağlantı yok; son doğrulanan bilgi gösteriliyor.</small>}
      </section>
      <details className="plan-nav-guide" open={guideOpen} onToggle={event => setGuideOpen(event.currentTarget.open)}>
        <summary>Nasıl kullanılır ve paylaşılır?</summary>
        <ol className="plan-guide-steps">
          <li><span className="plan-guide-number">1</span><div><strong>Taslağı hazırla <em>Operatör</em></strong><span>Yeni taslak → Planı Çalıştır</span><span>Kaydın tamamlanmasını bekle.</span></div></li>
          <li><span className="plan-guide-number">2</span><div><strong>Yöneticiyle paylaş <em>Operatör</em></strong><span>Senaryolar → Planlarım → Paylaş</span><span>Planın adını yöneticiye bildir.</span></div></li>
          <li><span className="plan-guide-number">3</span><div><strong>Planı aç ve hesapla <em>Yönetici</em></strong><span>Senaryolar → Paylaşılan Planlar → Bana kopyala → Planı Çalıştır</span></div></li>
          <li><span className="plan-guide-number">4</span><div><strong>Ortak plana al <em>Yönetici</em></strong><span>Üst çubuk: Kişisel taslak → Planı yayınla</span><span>Önizlemeyi kontrol et → İncelenen planı yayınla</span></div></li>
        </ol>
        <p className="plan-guide-note">Paylaşmak, ortak planı değiştirmez. Ortak planı yalnız yönetici yayınlar.</p>
        <details className="plan-guide-notes" open={guideNotesOpen} onToggle={event => setGuideNotesOpen(event.currentTarget.open)}>
          <summary>Dikkat edilmesi gerekenler</summary>
          <ul>
            <li>Kopyadaki değişiklikler kaynak planı değiştirmez. Paylaşımı kapat, alınmış kopyaları silmez.</li>
            <li>Paylaşılan plan görünmüyorsa Listeyi yenile kullanın.</li>
            <li>Yönetici kendi taslağını Senaryolar → Planlarım → Yükle ile açar. Yönetici, taslağı güncel verilerle hesaplar. İncelenen planı yayınla ile ortak planı onaylar. Başkasının planını önce kişisel kopya olarak açar.</li>
            <li>Üretim arşivi, teslimatlar ve çalışan işler ortaktır. Taslak kaydı bunları değiştirmez.</li>
            <li>Güncel verileri taslağa al, sipariş ve parametre varsayımlarını ortak değerlerle değiştirir. Kuyruk korunur; plan yeniden hesaplanmalıdır.</li>
            <li>Kayıt onaylanmadı: önce Yedek indir, sonra uyarıdaki Güncel kaydı kontrol et veya Yeniden dene düğmesini kullanın.</li>
          </ul>
        </details>
        <button className="secondary" onClick={() => act(onScenarios)}>Planları ve paylaşımları aç</button>
      </details>
      {cacheWarning && <div className="plan-nav-recovery" role="alert">
        <strong>Tarayıcı yedeği güncellenemedi</strong>
        <p>Sunucu kaydı doğrulandı. Yerel depolama dolu veya kapalı. Eski kopyalar silinmedi. Yenilemede tekrar inceleme gerekebilir.</p>
        <button className="secondary" onClick={onDownload}>Yedek indir</button>
      </div>}
      {needsRecovery && <div className="plan-nav-recovery" role="alert">
        <strong>{sharedFailure && sharedStatus === "conflict" ? "Ortak veriler değişti" : "Kayıt onaylanmadı"}</strong>
        <p>{pending ? "İşleminiz bekliyor. Yeniden deneyebilir veya yedeğini indirebilirsiniz." : "Bu cihazdaki değişiklikleri koruyun. Devam etmeden önce sunucudaki kaydı kontrol edin."}</p>
        {pending && status && <p className="plan-nav-error-detail">{status}</p>}
        <div className="plan-nav-recovery-actions"><button className="primary" onClick={pending ? onRetry : onReview}>{recoveryAction}</button><button className="secondary" onClick={onDownload}>Yedek indir</button></div>
        {pending && <details className="plan-nav-retain"><summary>Bu işlemi daha sonra incele</summary><p>Önce sunucudaki sonuç kontrol edilir. Kaydedilmemiş işlem bu tarayıcıda yedeklenir ve bekleyen işlemlerden çıkarılır. Bu seçenek işlemi sunucuya kaydetmez.</p><button className="secondary" onClick={onPreserve}>Yedekle ve beklemeden çıkar</button></details>}
      </div>}
      {name && <div className="plan-nav-options"><button disabled={pending} onClick={() => act(onShared)}>Ortak plana dön</button><button disabled={pending} onClick={() => act(onRefreshInputs)}>Güncel verileri taslağa al</button><button disabled={pending} onClick={() => act(onNew)}>Yeni taslak oluştur</button>{canPublish && <button className="primary" disabled={pending} onClick={() => act(onPublish)}>Planı yayınla</button>}</div>}
      <details className="plan-nav-more"><summary>Diğer işlemler</summary><button onClick={onDownload}>Yedek indir</button></details>
      <small className="plan-nav-connection">{connected ? "Sunucu bağlantısı açık" : "Sunucuya ulaşılamıyor"}{lastChecked ? ` · Son kontrol: ${lastChecked}` : ""}</small>
    </div>}
  </div>;
}

const noClockSubscription = () => () => {};

