"use client";
import type { PlannedBatch } from "@/lib/planning";
import { useRaviScreenContext } from "@/features/ravi/context";
import { formatExcelDate } from "@/lib/planning";
export type PublicationPreview = { previewId: string; scenarioId: string; revision: number; name: string; worldRevision: string; previousId: string | null; batchCount: number; quantity: number; changes: { id: string; before?: PlannedBatch; after?: PlannedBatch }[] };
export function PublicationDialog({ preview, busy, error, onConfirm, onClose }: { preview: PublicationPreview; busy: boolean; error: string; onConfirm: () => void; onClose: () => void }) {
  useRaviScreenContext("plan-publication", { name: preview.name, revision: preview.revision, worldRevision: preview.worldRevision, batchCount: preview.batchCount, quantity: preview.quantity, changedCount: preview.changes.length, busy, error });
  return <div className="modal-backdrop"><section className="modal" role="dialog" aria-modal="true" aria-label="Plan yayınlama önizlemesi">
    <h2>Plan yayınlama önizlemesi</h2><p>{preview.name} · Sürüm {preview.revision}</p>
    <p>{preview.batchCount} şarj · {preview.quantity} adet. Bu onay planı tüm kullanıcılar için yürürlüğe alır. Gerçek üretim ve teslimat kayıtları korunur.</p>
    <div style={{ maxHeight: "50vh", overflow: "auto" }}><table><thead><tr><th>İş emri</th><th>Tezgah</th><th>Adet: önce → sonra</th><th>Bitiş: önce → sonra</th></tr></thead><tbody>{preview.changes.map(change => <tr key={change.id}><td>{change.after?.workOrder || change.before?.workOrder || change.id}</td><td>{change.before?.machineId || "—"} → {change.after?.machineId || "—"}</td><td>{change.before?.quantity ?? 0} → {change.after?.quantity ?? 0}</td><td>{change.before ? formatExcelDate(change.before.end) : "—"} → {change.after ? formatExcelDate(change.after.end) : "—"}</td></tr>)}</tbody></table></div>
