        </div>}
      </div>
      {editingScenario && <ScenarioEditDialog scenario={editingScenario} onClose={() => setEditingScenario(null)} onSave={async (updated) => { await onUpdate(updated); setEditingScenario(null); }} />}
    </section>
  );
}

export function ScenarioSaveDialog({ sequence, onClose, onSave }: { sequence: number; onClose: () => void; onSave: (name: string, notes: string) => Promise<void> }) {
  const [name, setName] = useState(`Senaryo ${sequence}`);
  const [notes, setNotes] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  async function submit() {
    if (!name.trim()) return;
    setSaving(true);
    setError("");
    try { await onSave(name, notes); }
    catch (caught) { setError(caught instanceof Error ? caught.message : "Senaryo kaydedilemedi."); setSaving(false); }
  }
  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog scenario-edit-dialog" role="dialog" aria-modal="true" aria-label="Senaryoyu kaydet"><div className="operational-dialog-head"><span className="dialog-icon shift"><FloppyDisk size={20} /></span><div><span>SENARYO KAYDI</span><h2>Planı anlamlı bir adla saklayın</h2><p>Karşılaştırma ekranında bu ad ve açıklama gösterilecek.</p></div><button className="delete-button" onClick={onClose} aria-label="Senaryo kaydını kapat"><X size={16} /></button></div><div className="operational-dialog-form"><Field label="Senaryo adı"><input autoFocus value={name} onChange={(event) => setName(event.target.value)} placeholder={`Senaryo ${sequence}`} /></Field><Field label="Açıklama"><textarea value={notes} onChange={(event) => setNotes(event.target.value)} placeholder="Örn. Ağustos planı · 2 vardiya · bakım dahil" /></Field>{error && <p className="form-error">{error}</p>}<div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={!name.trim() || saving} onClick={() => void submit()}>{saving ? "Kaydediliyor…" : "Senaryoyu kaydet"}</button></div></div></section></div>;
}

export function ScenarioLoadReportDialog({ report, onClose }: { report: ScenarioLoadReport; onClose: () => void }) {
  const visible = report.overflows.slice(0, 12);
  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog scenario-load-report-dialog" role="dialog" aria-modal="true" aria-label={`${report.scenarioName} plan penceresi uyarısı`}><div className="operational-dialog-head"><span className="dialog-icon maintenance"><Warning size={20} weight="fill" /></span><div><span>SENARYO GÜNCEL DURUMA UYARLANDI</span><h2>Plan yüklendi; bazı işler hedef tarihi aşıyor</h2><p>Canlı üretim korunarak kayıtlı tezgah ve kuyruk sırası yeniden hesaplandı. Kilitler korundu ve yüklemeyi engellemedi.</p></div><button className="delete-button" onClick={onClose} aria-label="Senaryo yükleme raporunu kapat"><X size={16} /></button></div><div className="scenario-load-report-summary"><strong>{report.overflows.length} iş</strong><span>kayıtlı plan penceresinin dışında tamamlanıyor</span></div><div className="scenario-load-overflow-list">{visible.map((item) => <article key={item.batchId}><div><strong>{item.machineId} · {item.product}</strong><span>{item.workOrder || item.batchId} · {item.queuePosition}. sıra</span></div><em className={item.locked ? "locked" : "unlocked"}>{item.locked ? <Lock size={11} weight="fill" /> : null}{item.locked ? "Kilitli" : "Kilitli değil"}</em><p><span>Hesaplanan</span><b>{formatExcelDate(item.start)} – {formatExcelDate(item.end)}</b><span>Plan penceresi</span><b>{formatExcelDate(item.windowStart)} – {formatExcelDate(item.windowEnd)}</b></p></article>)}</div>{report.overflows.length > visible.length && <p className="scenario-load-report-more">Ayrıca {report.overflows.length - visible.length} iş daha plan penceresini aşıyor.</p>}<div className="scenario-load-report-note"><strong>Bu bir yükleme hatası değildir.</strong><span>Planın kayıtlı hedef tarihe sığması gerekiyorsa kapasiteyi, kuyruk sırasını veya kilitli işleri gözden geçirin.</span></div><div className="drawer-actions"><button className="primary" onClick={onClose}>Planı görüntüle</button></div></section></div>;
}

function ScenarioEditDialog({ scenario, onClose, onSave }: { scenario: StoredScenario; onClose: () => void; onSave: (scenario: StoredScenario) => Promise<void> }) {
  const [name, setName] = useState(scenario.name);
  const [notes, setNotes] = useState(scenario.notes ?? "");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  async function submit() {
    if (!name.trim()) return;
    setSaving(true);
    setError("");
    try { await onSave({ ...scenario, name: name.trim(), notes: notes.trim() }); }
    catch (caught) { setError(caught instanceof Error ? caught.message : "Senaryo bilgileri kaydedilemedi."); setSaving(false); }
  }
  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog scenario-edit-dialog" role="dialog" aria-modal="true" aria-label={`${scenario.name} bilgilerini düzenle`}><div className="operational-dialog-head"><span className="dialog-icon shift"><PencilSimple size={20} /></span><div><span>SENARYO BİLGİSİ</span><h2>Ad ve açıklamayı düzenle</h2><p>Plan verileri değişmez; yalnızca senaryonun tanımı güncellenir.</p></div><button className="delete-button" onClick={onClose} aria-label="Senaryo düzenlemeyi kapat"><X size={16} /></button></div><div className="operational-dialog-form"><Field label="Senaryo adı"><input autoFocus value={name} onChange={(event) => setName(event.target.value)} /></Field><Field label="Açıklama"><textarea value={notes} onChange={(event) => setNotes(event.target.value)} placeholder="Örn. Ağustos planı" /></Field>{error && <p className="form-error">{error}</p>}<div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={!name.trim() || saving} onClick={() => void submit()}>{saving ? "Kaydediliyor…" : "Değişikliği kaydet"}</button></div></div></section></div>;
}

export function nextScenarioNumber(scenarios: Array<Pick<StoredScenario, "name">>): number {
  return Math.max(0, ...scenarios.map((scenario) => Number(scenario.name.match(/senaryo\s+(\d+)/i)?.[1] ?? 0))) + 1;
}

