import type { PlanningSyncStatus } from "../../../lib/planning-persistence";

export const planningSaveLabels: Record<PlanningSyncStatus, string> = {
  loading: "Ortak kayıt kontrol ediliyor",
  saving: "Kaydediliyor · sunucu onayı bekleniyor",
  synced: "Bu cihazdaki son kayıt sunucu tarafından onaylandı",
  offline: "Kayıt onayı alınamadı · bu cihazdaki kopyayı koruyun",
  conflict: "Ortak veri değişti · bu cihazdaki değişiklikler henüz uzlaştırılmadı",
};

export function PlanningSaveStatus({ status, lastSaved, onReview, onDownload }: {
  status: PlanningSyncStatus; lastSaved: string; onReview: () => void; onDownload: () => void;
}) {
  const needsReview = status === "offline" || status === "conflict";
  return <aside className={`planning-save-status ${status}`} role="status" aria-live="polite">
    <div><strong>{planningSaveLabels[status]}</strong>
      {lastSaved && <small>Son doğrulanan ortak sürüm: {lastSaved}</small>}
      {needsReview && <p>Diğer kullanıcıların bu değişiklikleri gördüğünü varsaymayın. Ortak kaydı kontrol edin; yerel kopyayı indirmek mevcut veriyi değiştirmez.</p>}
    </div>
    <div className="planning-save-actions">{needsReview && <button className="secondary" onClick={onReview}>Ortak kaydı kontrol et</button>}<button className="secondary" onClick={onDownload}>Yerel kopyayı indir</button></div>
  </aside>;
}

"use client";

import { Warning, X } from "@phosphor-icons/react";
import type { PlanningSeed } from "@/lib/planning";
import type { PlanningStateRecord } from "@/lib/planning-persistence";
import { describeOperationalDelta, operationalDelta } from "@/lib/planning-recovery";
import { formatFactoryDateTime } from "../shared/format";
import { planningStateUpdatedAtKey } from "./planning-state";

type Props = {
  seed: PlanningSeed;
  planningSyncConflict: PlanningStateRecord;
  syncRecovery: {
    reason: "save-failed" | "remote-changed" | "missing-base" | "write-conflict";
    baseUpdatedAt: string;
    confirmedRequestRevision?: string;
  } | null;
  recoveryBusy: boolean;
  recoveryError: string;
  onClose: () => void;
  onDownload: () => Promise<void>;
  onAcceptRemote: () => Promise<void>;
  onRetryLocal: () => Promise<void>;
  onPublishLocal: () => Promise<void>;
};

/** Displays recovery choices. The coordinator owns their storage and save guards. */
export function PlanningSyncConflictDialog({
  seed, planningSyncConflict, syncRecovery, recoveryBusy, recoveryError,
  onClose, onDownload, onAcceptRemote, onRetryLocal, onPublishLocal,
}: Props) {
  const delta = operationalDelta(seed, planningSyncConflict.seed);
  const missing = describeOperationalDelta(delta);
  const reason = syncRecovery?.reason ?? "write-conflict";
  const unsaved = reason === "save-failed";
  const title = unsaved ? "Kaydedilmemiş yerel değişiklik bulundu" : reason === "missing-base" ? "Yerel kopyanın dayandığı ortak sürüm bilinmiyor" : "Ortak veri başka bir oturumda değişti";
  const intro = unsaved ? "Son kayıt ortak veritabanına ulaşmadı. Ortak veri o zamandan beri değişmedi. Yerel değişiklik kaydedilene kadar diğer kayıtlar durduruldu."
    : reason === "missing-base" ? "Bu kopya eski bir uygulama sürümünden kalmış. Otomatik birleştirme yapılmadı; hangi sürümle devam edeceğinizi seçin."
      : "Daha yeni ortak kayıt sessizce ezilmedi. Yerel kopya birleştirilmedi; hangi sürümle devam edeceğinizi açıkça seçin.";
  return <div className="confirmation-backdrop sync-conflict-backdrop" role="presentation">
    <section className="operational-dialog sync-conflict-dialog" role="dialog" aria-modal="true" aria-label="Planlama verisi çakışması">
      <div className="operational-dialog-head">
        <span className="dialog-icon maintenance">
          <Warning size={20} weight="fill" />
        </span>
        <div>
          <span>{unsaved ? "KAYDEDİLMEMİŞ DEĞİŞİKLİK" : "SENKRONİZASYON ÇAKIŞMASI"}</span>
          <h2>{title}</h2>
          <p>{intro}</p>
        </div>
        <button className="delete-button" disabled={recoveryBusy} onClick={onClose} aria-label="Senkronizasyon uyarısını kapat">
          <X size={16} />
        </button>
      </div>
      <div className="sync-conflict-versions">
        <span>
          <small>Bu cihazdaki son değişiklik</small>
          <strong>{formatFactoryDateTime(window.localStorage.getItem(planningStateUpdatedAtKey) ?? "")}</strong>
        </span>
        <span>
          <small>Yerel kopyanın dayandığı ortak sürüm</small>
          <strong>{syncRecovery?.baseUpdatedAt ? formatFactoryDateTime(syncRecovery.baseUpdatedAt) : "Bilinmiyor"}</strong>
        </span>
        <span>
          <small>Ortak veritabanındaki sürüm</small>
          <strong>{formatFactoryDateTime(planningSyncConflict.updatedAt)}</strong>
        </span>
      </div>{syncRecovery?.confirmedRequestRevision && <div className="sync-conflict-note" role="status">
        <strong>Bekleyen istek sunucuda kayıtlı</strong>
        <span>İstek {formatFactoryDateTime(syncRecovery.confirmedRequestRevision)} sürümünde kaydedildi. Bu onay, daha sonra bu cihazda yapılan değişiklikleri kapsamaz. Güncel ortak sürümü ve yerel kopyayı inceleyin.</span>
      </div>}{missing.length > 0 && <div className="sync-conflict-note" role="status">
        <strong>Ortak sürümde olmayan yerel üretim işlemleri</strong>
        <span>{missing.join(" · ")}</span>
        <span>{unsaved ? "Yerel değişikliği kaydet bu işlemleri aynı ortak sürüme karşı bir kez kaydeder; ortak veri değiştiyse kayıt reddedilir ve hiçbir işlem iki kez yazılmaz." : "Bu işlemler yayınlamayla aktarılamaz. Ortak veriyi yükle seçilirse yerel kopya kurtarma için saklanır; işlemleri güncel ortak veriye yeniden girin."}</span>
      </div>}<div className="sync-conflict-note">
        <strong>Ortak veriyi yükle</strong>
        <span>Bu cihazdaki kaydedilmemiş değişikliklerin yerine ortak sürüm gelir. Yerel çalışmanız önce bu cihazdaki kurtarma arşivine otomatik kaydedilir. Kopya indirmeniz veya silmeniz gerekmez. İsterseniz Yerel kopyayı indir ile arşivinizi ve mevcut çalışmanızı alabilirsiniz.</span>{unsaved ? <>
          <strong>Yerel değişikliği kaydet</strong>
          <span>Kaydedilmemiş yerel kopyayı dayandığı ortak sürüme karşı kaydeder.</span>
        </> : <>
          <strong>Bu cihazı yayınla</strong>
          <span>Ortak sürümün planlama girdilerinin üzerine bu ekrandaki planlama yazılır. Ortak üretim kayıtları sunucuda korunur; yerel üretim işlemleri yayınlanmaz.</span>
        </>}</div>{recoveryError && <p className="sync-conflict-error" role="alert">{recoveryError}</p>}<div className="drawer-actions">
        <button className="secondary" disabled={recoveryBusy} onClick={onClose}>Şimdilik kapat</button>
        <button className="secondary" onClick={() => void onDownload()}>Yerel kopyayı indir</button>
        <button className="secondary" disabled={recoveryBusy} onClick={() => void onAcceptRemote()}>{recoveryBusy ? "Yerel çalışma korunuyor…" : "Ortak veriyi yükle"}</button>{unsaved ? <button className="primary" disabled={recoveryBusy} onClick={() => void onRetryLocal()}>Yerel değişikliği kaydet</button> : <button className="primary" disabled={recoveryBusy || missing.length > 0} title={missing.length > 0 ? "Yerel üretim işlemleri yayınlamayla aktarılamaz" : undefined} onClick={() => void onPublishLocal()}>Bu cihazı yeni sürüm olarak yayınla</button>}</div>
    </section>
  </div>;
}

