import type { PlanningSeed } from "@/lib/planning";
import { cloneSeed, isPlanningSeed } from "./planning-state";

/** Normalize planning inputs, but never roll the displayed production facts forward. */
export function sharedProductionView(seed: PlanningSeed): PlanningSeed {
  const view = cloneSeed(seed);
  for (const field of ["productionHistory", "wipLots", "wipMovements", "processCurrentJobs", "productionInterruptions", "productionCancellations", "chargeJourneyNotes", "planningEvents"] as const) {
    if (Object.hasOwn(seed, field)) (view as unknown as Record<string, unknown>)[field] = structuredClone(seed[field]);
    else delete view[field];
  }
  for (const machine of view.machines) {
    const actual = seed.machines.find(row => row.id === machine.id);
    if (!actual) continue;
    machine.currentJob = structuredClone(actual.currentJob);
    if (Object.hasOwn(actual, "operationalAvailableStart")) machine.operationalAvailableStart = actual.operationalAvailableStart;
    else delete machine.operationalAvailableStart;
  }
  return view;
}


/** Reuse a complete snapshot only after a fresh authenticated revision check.
 * This is for opening workspaces, never for reconciling an uncertain write. */
export async function readSharedProductionWorld(
  fetch: (path: string, init?: RequestInit) => Promise<Response>,
  cached: import("@/lib/planning-persistence").PlanningStateRecord | null,
): Promise<import("@/lib/planning-persistence").PlanningStateRecord> {
  const statusResponse = await fetch("/collaboration/status", { cache: "no-store" });
  if (!statusResponse.ok) throw new Error("Ortak üretim kaydı okunamadı.");
  const status = await statusResponse.json() as { worldRevision?: string };
  if (cached?.updatedAt && status.worldRevision === cached.updatedAt) return cached;
  const response = await fetch("/planning-state", { cache: "no-store" });
  if (!response.ok) throw new Error("Ortak üretim kaydı okunamadı.");
  const world = await response.json() as import("@/lib/planning-persistence").PlanningStateRecord;
  if (!isPlanningSeed(world?.seed) || !world.updatedAt) throw new Error("Ortak üretim kaydı geçersiz.");
  return world;
}

