"use client";

import { useEffect, useState } from "react";
import type { ApiFetch } from "@/lib/api";
import type { OrderRevisionSummary } from "@/lib/planning";
import type { PlanningHistorySummary, PlanningStateRevision } from "../shared/types";

/** Owns history list reads and display updates. Callers retain all write decisions. */
export function usePlanningHistory(apiFetch: ApiFetch) {
  const [historyStatus, setHistoryStatus] = useState("Geçmiş yükleniyor…");
  const [revisionStatus, setRevisionStatus] = useState("Sipariş geçmişi yükleniyor…");
  const [planningHistory, setPlanningHistory] = useState<PlanningHistorySummary[]>([]);
  const [revisions, setRevisions] = useState<OrderRevisionSummary[]>([]);

  useEffect(() => {
    let stopped = false;
    async function loadSummaries(path: string, accept: (value: never[]) => void, status: (value: string) => void) {
      try {
        const response = await apiFetch(path, { cache: "no-store" });
        if (!response.ok) throw Error();
        const value = await response.json();
        if (!Array.isArray(value)) throw Error();
        if (!stopped) { accept(value as never[]); status(""); }
      } catch { if (!stopped) status("Geçmiş yüklenemedi. Sayfayı yenileyip tekrar deneyin."); }
    }
    void loadSummaries("/planning-state/history?summary=true", setPlanningHistory, setHistoryStatus);
    void loadSummaries("/revisions?summary=true", setRevisions, setRevisionStatus);
    return () => { stopped = true; };
  }, [apiFetch]);

  // Preserve the existing best-effort refresh after a shared write acknowledgement.
  // It does not change startup status or confirm a planning save.
  function refreshRevisions() {
    void apiFetch("/revisions?summary=true").then(response => response.ok ? response.json() : null).then(values => { if (values) setRevisions(values); }).catch(() => {});
  }

  // Import responses already carry their history row. Keep that row unchanged.
  function prependHistoryEntry(entry: PlanningHistorySummary) {
    setPlanningHistory(current => [entry, ...current.filter(item => item.id !== entry.id)].slice(0, 20));
  }

  function recordSavedRevision(entry: PlanningStateRevision) {
    prependHistoryEntry({
      id: entry.id,
      createdAt: entry.createdAt,
      createdBy: entry.createdBy,
      openWipCount: (entry.seed.wipLots ?? []).filter(lot => lot.availableQuantity > 0 && lot.stage !== "delivered" && lot.stage !== "scrapped").length,
    });
  }

  return {
    historyStatus, revisionStatus, planningHistory, revisions,
    refreshRevisions, recordSavedRevision, prependHistoryEntry,
  };
}

