"use client";

import { useEffect, useState } from "react";
import { useRaviScreenContext } from "@/features/ravi/context";
import type { PlanningSeed } from "@/lib/planning";
import { validateProductWeights, type ProductWeight } from "@/lib/product-weights";
import { initialRawMaterialSettings, validateRawMaterialSettings } from "@/lib/raw-material-settings";

export function ProductWeights({ seed, updateSeed, readOnly = false, productCodes }: { readOnly?: boolean; productCodes?: Set<string>; seed: PlanningSeed; updateSeed: (mutator: (seed: PlanningSeed) => void) => void }) {
  const [query, setQuery] = useState("");
  const [editing, setEditing] = useState<ProductWeight | null>(null);
  const [originalCode, setOriginalCode] = useState<string | null>(null);
  const [amount, setAmount] = useState("");
  const [error, setError] = useState("");
  const settings = seed.rawMaterialSettings ?? initialRawMaterialSettings();
  const [scrap, setScrap] = useState(String(settings.scrapPercent).replace(".", ","));
  const [scrapError, setScrapError] = useState("");
  useEffect(() => setScrap(String(settings.scrapPercent).replace(".", ",")), [settings.scrapPercent]);
  const rows = seed.productWeights ?? [];
  const visible = rows.filter((row) => `${row.product} ${row.productName} ${row.materialCode} ${row.materialName}`.toLocaleLowerCase("tr-TR").includes(query.toLocaleLowerCase("tr-TR")));
  useRaviScreenContext("product-weights", { query, visibleCount: visible.length, totalCount: rows.length, visibleWeights: visible.slice(0, 12), selectedProduct: editing?.product, draftProduct: editing, draftGrams: amount, scrapPercent: settings.scrapPercent, draftScrapPercent: scrap, unit: "g", sourceSheet: "ÜRÜN AĞIRLIKLARI" });
  function save() {
    if (!editing || readOnly) return;
    try {
      const grams = amount.trim() ? Number(amount.trim().replace(",", ".")) : null;
      const updated = { ...editing, product: editing.product.trim().toUpperCase(), grams };
      if (originalCode === null && rows.some((row) => row.product === updated.product)) throw new Error("Bu ürün zaten var; mevcut satırdaki Düzenle düğmesini kullanın.");
      const next = rows.some((row) => row.product === updated.product) ? rows.map((row) => row.product === updated.product ? updated : row) : [...rows, updated];
      validateProductWeights(next);
      updateSeed((draft) => { draft.productWeights = next; });
      setEditing(null); setError("");
    } catch (reason) { setError(reason instanceof Error ? reason.message : "Ağırlık kaydedilemedi."); }
  }
  return <section className="calendar-section product-weights-section">
    <div className="calendar-section-title"><div><h3>Ürün Ağırlıkları</h3><p>Excel’deki hammadde miktarları, gram cinsinden. Kaynak: ÜRÜN AĞIRLIKLARI → Miktar / Hm. Birim.</p><p>İlk aktarım bir kez yapılır; burada kaydettiğiniz değerler korunur. Ağırlığı bilinmeyen ürünü boş bırakabilirsiniz.</p></div>
      <form className="material-scrap-form" onSubmit={(event) => {
        event.preventDefault();
        if (readOnly) return;
        try {
          if (!scrap.trim()) throw new Error("Iskarta oranını girin.");
          const next = validateRawMaterialSettings({ ...settings, scrapPercent: Number(scrap.replace(",", ".")) });
          updateSeed((draft) => { draft.rawMaterialSettings = next; }); setScrapError("");
        } catch (reason) { setScrapError(reason instanceof Error ? reason.message : "Oran kaydedilemedi."); }
      }}><label className="field"><span>Iskarta Oranı (%)</span><input aria-label="Iskarta Oranı (%)" inputMode="decimal" value={scrap} onChange={(event) => setScrap(event.target.value)} /></label><button className="secondary" type="submit">Oranı kaydet</button><p>Günlük üretim adedine bu oranda ilave hammadde eklenir.</p>{scrapError && <p role="alert" className="form-error">{scrapError}</p>}</form>
    </div>
    <div className="product-weights-toolbar"><input aria-label="Ürün ağırlıklarında ara" placeholder="Tip no veya hammadde ara…" value={query} onChange={(event) => setQuery(event.target.value)} /><span>{visible.length} / {rows.length} ürün</span><button disabled={readOnly || !!productCodes} className="primary" onClick={() => { setOriginalCode(null); setEditing({ product: "", productName: "", materialCode: "", materialName: "", grams: null }); setAmount(""); setError(""); }}>Ürün ekle</button></div>
    {editing && <form className="product-weight-editor" onSubmit={(event) => { event.preventDefault(); save(); }}>
      <label className="field"><span>Tip no</span><input required value={editing.product} readOnly={originalCode !== null} onChange={(event) => setEditing({ ...editing, product: event.target.value })} /></label>
      <label className="field"><span>Ürün adı</span><input value={editing.productName} onChange={(event) => setEditing({ ...editing, productName: event.target.value })} /></label>
      <label className="field"><span>Hammadde kodu</span><input value={editing.materialCode} onChange={(event) => setEditing({ ...editing, materialCode: event.target.value })} /></label>
      <label className="field"><span>Hammadde ağırlığı (g)</span><input inputMode="decimal" placeholder="Örn. 181 veya 75,13" value={amount} onChange={(event) => setAmount(event.target.value)} /></label>
      <label className="field weight-description"><span>Hammadde açıklaması</span><input value={editing.materialName} onChange={(event) => setEditing({ ...editing, materialName: event.target.value })} /></label>
      <div className="drawer-actions"><button type="button" className="secondary" onClick={() => setEditing(null)}>Vazgeç</button><button type="submit" className="primary">Kaydet</button></div>
      {error && <p role="alert" className="form-error">{error}</p>}
    </form>}
    <div className="product-weights-scroll"><table className="product-weights-table"><thead><tr><th>Tip no</th><th>Ürün adı</th><th>Hammadde kodu</th><th>Hammadde açıklaması</th><th>Ağırlık (g)</th><th>İşlem</th></tr></thead><tbody>{visible.map((row) => <tr key={row.product}><td><strong>{row.product}</strong></td><td>{row.productName || "—"}</td><td>{row.materialCode || "—"}</td><td>{row.materialName || "—"}</td><td>{row.grams === null ? "—" : row.grams.toLocaleString("tr-TR", { maximumFractionDigits: 6 })}</td><td><button disabled={readOnly} className="secondary" aria-label={`${row.product} ağırlığını düzenle`} onClick={() => { setOriginalCode(row.product); setEditing({ ...row }); setAmount(row.grams?.toString().replace(".", ",") ?? ""); setError(""); }}>Düzenle</button></td></tr>)}</tbody></table></div>
    {!visible.length && <p>Aramanızla eşleşen ürün yok.</p>}
  </section>;
}

frontend/features/planning/settings/RawM.source:
"use client";

import { Fragment, useEffect, useMemo, useState } from "react";
import { useRaviScreenContext } from "@/features/ravi/context";
import { factoryDateInput } from "@/lib/factory-time";
import { formatExcelDate, type PlanningSeed, type ScenarioResult } from "@/lib/planning";
import { buildRawMaterialConsumption, rawMaterialCatalog } from "@/lib/raw-material-consumption";
import { initialRawMaterialSettings, validateRawMaterialSettings } from "@/lib/raw-material-settings";
import { inputDateToSerial } from "@/features/planning/shared/format";

const kg = (value: number) => value.toLocaleString("tr-TR", { minimumFractionDigits: 2, maximumFractionDigits: 3 });

export function RawMaterialConsumption({ seed, result, dirty, updateSeed }: {
  seed: PlanningSeed; result: ScenarioResult; dirty: boolean; updateSeed: (mutator: (seed: PlanningSeed) => void) => void;
}) {
  const settings = useMemo(() => seed.rawMaterialSettings ?? initialRawMaterialSettings(), [seed.rawMaterialSettings]);
  const catalog = useMemo(() => rawMaterialCatalog(seed), [seed]);
  const [stockDate, setStockDate] = useState(settings.stockDate || factoryDateInput());
  const [stocks, setStocks] = useState<Record<string, string>>({});
  const [query, setQuery] = useState("");
  const [days, setDays] = useState(90);
  const [error, setError] = useState("");
  const [editing, setEditing] = useState(!settings.stockDate);
  const [today, setToday] = useState(factoryDateInput);
  useEffect(() => { const timer = window.setInterval(() => setToday(factoryDateInput()), 60000); return () => clearInterval(timer); }, []);
  useEffect(() => {
    setStockDate(settings.stockDate || factoryDateInput());
    setStocks(Object.fromEntries(settings.stocks.map((row) => [row.materialCode, row.kg === null ? "" : String(row.kg).replace(".", ",")])));
  }, [settings.stockDate, settings.stocks]);
  const report = useMemo(() => settings.stockDate ? buildRawMaterialConsumption(seed, result, inputDateToSerial(settings.stockDate), days, inputDateToSerial(today)) : null,
    [seed, result, settings.stockDate, days, today]);
  const visible = report?.materials.filter((row) => `${row.materialCode} ${row.materialName}`.toLocaleLowerCase("tr-TR").includes(query.toLocaleLowerCase("tr-TR"))) ?? [];
  const dates = report?.materials[0]?.days ?? [];
  useRaviScreenContext("raw-material-consumption", {
    query, days, stockDate: settings.stockDate, scrapPercent: settings.scrapPercent, dirty, planState: result.state,
    source: "current-browser", unit: "kg", editing, draftStockDate: stockDate,
    draftStocks: editing ? Object.entries(stocks).slice(0, 12) : undefined,
    issues: report?.issues.slice(0, 12), unplannedCount: report?.unplannedCount,
    visibleCount: visible.length, materials: visible.slice(0, 12).map((row) => ({ materialCode: row.materialCode, stockKg: row.stockKg,
      exhaustedOn: row.exhaustedOn, shortageOn: row.shortageOn, days: row.days.slice(0, 7) })),
  });
  function save() {
    try {
      if (!stockDate) throw new Error("CPM stoklarının güncelleme tarihini girin.");
      const next = validateRawMaterialSettings({ ...settings, stockDate, stocks: catalog.map((row) => ({ materialCode: row.materialCode,
        kg: stocks[row.materialCode]?.trim() ? Number(stocks[row.materialCode].trim().replace(",", ".")) : null })) });
      updateSeed((draft) => { draft.rawMaterialSettings = next; }); setError(""); setEditing(false);
    } catch (reason) { setError(reason instanceof Error ? reason.message : "Stoklar kaydedilemedi."); }
  }
  return <section className="calendar-section material-consumption-section">
    <div className="calendar-section-title"><div><h3>Hammadde Tüketim Tablosu</h3><p>Torna planına göre günlük çelik ihtiyacı ve kalan ambar stoğu.</p></div>
      <button className="secondary" onClick={() => { setEditing(!editing); setError(""); }}>{editing ? "Girişi kapat" : "Stokları güncelle"}</button></div>
    {editing && <form className="material-stock-editor" onSubmit={(event) => { event.preventDefault(); save(); }}>
      <div className="material-stock-heading"><label className="field"><span>Güncelleme Tarihi</span><input className="material-manual" type="date" required value={stockDate} onChange={(event) => setStockDate(event.target.value)} /></label>
        <p>Sarı alanlara CPM’den aldığınız stokları kg olarak girin. Tarih, bu stokların gün başı bakiyesini belirtir. Boş alan bilinmiyor, 0 ise stok yok demektir.</p></div>
      <div className="material-stock-grid">{catalog.map((row) => <label className="field" key={row.materialCode}><span>{row.materialCode} · {row.diameter}</span><input className="material-manual" aria-label={`${row.materialCode} Ambar stoğu (kg)`} inputMode="decimal" placeholder="Ambar stoğu (kg)" value={stocks[row.materialCode] ?? ""} onChange={(event) => setStocks({ ...stocks, [row.materialCode]: event.target.value })} /></label>)}</div>
      {error && <p className="form-error" role="alert">{error}</p>}<button type="submit" className="primary">Stokları kaydet</button>
    </form>}
    {(dirty || result.state !== "planned") && <p role="status" className="material-warning">{dirty ? "Plan güncel değil. Tüketim mevcut tarihlere göre ön izlemedir; planı yeniden çalıştırın." : "Henüz plan çalıştırılmadı. Yalnız mevcut Torna işlerinin kalan miktarı gösterilir."}</p>}
    {settings.stockDate && settings.stockDate < today && <p className="material-warning">Güncelleme tarihi geçmişte. Tamamlanmış üretimin fiili tüketimi bu tahminde yer almaz; kalan stoğu doğrulamak için CPM bakiyesini güncelleyin.</p>}
    {report && report.unplannedCount > 0 && <p className="material-warning">{report.unplannedCount} planlanamayan şarjın tarihi yok; ihtiyaca dahil edilmedi.</p>}
    {!!report?.issues.length && <div className="material-warning" role="alert"><strong>Hesap eksik</strong><ul>{report.issues.map((issue) => <li key={issue}>{issue}</li>)}</ul></div>}
    <div className="product-weights-toolbar"><input aria-label="Hammadde tüketiminde ara" placeholder="Hammadde kodu veya açıklama ara…" value={query} onChange={(event) => setQuery(event.target.value)} />
      <label className="field"><span>Gösterilen dönem</span><select value={days} onChange={(event) => setDays(Number(event.target.value))}>{[30, 90, 180, 366].map((count) => <option key={count} value={count}>{count} gün</option>)}</select></label>
      <span>Iskarta Oranı: %{settings.scrapPercent.toLocaleString("tr-TR", { minimumFractionDigits: 2 })}</span></div>
    {!settings.stockDate ? <p>Tabloyu görmek için güncelleme tarihini ve ambar stoklarını kaydedin.</p> : <>
      <p className="material-formula">Günlük ihtiyaç (kg) = Torna günlük üretim adedi × (1 + ıskarta oranı / 100) × ağırlık (g) / 1000. Kalan = önceki günün kalanı − günlük ihtiyaç.</p>
      <p className="material-legend"><span>Yeşil: ihtiyaç karşılanıyor</span><span>Kırmızı: stok tükendi veya yetersiz</span><span>—: stok ya da hesap bilgisi eksik</span></p>
      <div className="material-table-scroll" tabIndex={0} aria-label="Günlük hammadde tüketimi, yatay kaydırılabilir"><table className="material-table"><thead>
        <tr><th rowSpan={2}>Ambar stoğu (kg)</th><th rowSpan={2}>Hammadde Kodu / Çap</th><th rowSpan={2}>Stok durumu</th><th rowSpan={2}>Tarih</th>{dates.map((day) => <th key={day.day}>{formatExcelDate(day.day)}</th>)}</tr>
        <tr>{dates.map((day) => <th key={day.day}>{new Date(Date.UTC(1899, 11, 30) + day.day * 86400000).toLocaleDateString("tr-TR", { weekday: "short", timeZone: "UTC" })}</th>)}</tr>
      </thead><tbody>{visible.map((row) => <Fragment key={row.materialCode}>
        <tr><td rowSpan={2}>{row.stockKg === null ? "—" : kg(row.stockKg)}</td><th rowSpan={2} title={row.materialName}>{row.materialCode}<small>{row.diameter}</small></th>
          <td rowSpan={2} className="material-coverage">{row.days.some((day) => day.incomplete) ? "Hesap eksik" : row.stockKg === null ? "Stok girilmedi" : row.exhaustedOn !== null ? <><strong>{formatExcelDate(row.exhaustedOn)}</strong><small>Stok tükeniyor{row.shortageOn !== null ? ` · İlk eksik: ${formatExcelDate(row.shortageOn)}` : " · O günün ihtiyacı karşılanıyor"}</small></> : "Dönem boyunca yeterli"}</td>
          <th>İhtiyaç</th>{row.days.map((day) => <td key={day.day} title={`${day.quantity.toLocaleString("tr-TR")} adet · ${day.incomplete ? "Bilinen ihtiyaç; hesap eksik" : "Iskarta dahil kg"}`}>{day.incomplete ? `${kg(day.requiredKg)}*` : kg(day.requiredKg)}</td>)}</tr>
        <tr><th>Kalan</th>{row.days.map((day) => <td key={day.day} className={day.remainingKg === null ? "" : day.remainingKg <= 0 ? "material-empty" : "material-covered"}>{day.remainingKg === null ? "—" : kg(day.remainingKg)}</td>)}</tr>
      </Fragment>)}</tbody></table></div>
      {!visible.length && <p>Aramanızla eşleşen hammadde yok.</p>}
      <p className="material-footnote">Güncelleme: {settings.stockDate} · Tüm Torna tezgâhları ve tarihli planlı şarjlar. Mevcut işlerde kalan adet kullanılır. Hazırlık süresi, tamamlanan işler ve diğer prosesler tüketilmez. Hesap bir stok tahminidir; CPM’ye kayıt yazmaz. * Bilinen ihtiyaç, eksikler hariç.</p>
    </>}
  </section>;
}

frontend/features/planning/settings/Sett.source:
"use client";

import { useRaviScreenContext } from "@/features/ravi/context";

import { ProcessIcon } from "@/components/ProcessIcon";

import { useState } from "react";
import { CaretLeft, CaretRight, CalendarBlank, PencilSimple } from "@phosphor-icons/react";
import { settingsMonthDays, settingsEntriesOnDate, shiftCalendarMonth, calendarSerialDate, type SettingsCalendarEntry } from "@/lib/settings-calendar";

const LABELS = { holiday: "Resmi tatil", maintenance: "Bakım", overtime: "Mesai", "shift-change": "Vardiya" };
const PROCESS_LABELS: Record<string, string> = { turning: "Torna", drilling: "Delme", deburring: "Çapak Alma", gkm: "GKM", all: "Tüm prosesler" };
const entryProcess = (entry: SettingsCalendarEntry) => entry.kind === "holiday" ? "all" : entry.process ?? "unknown";
const entryProcessLabel = (entry: SettingsCalendarEntry) => PROCESS_LABELS[entryProcess(entry)] ?? "İş merkezi";

const dateLabel = (date: string) => new Intl.DateTimeFormat("tr-TR", { dateStyle: "long", timeZone: "UTC" }).format(new Date(`${date}T00:00:00Z`));

export function SettingsCalendar({ entries, today, onEdit }: { entries: SettingsCalendarEntry[]; today: string; onEdit: (entry: SettingsCalendarEntry) => void }) {
  const [month, setMonth] = useState(today.slice(0, 7));
  const [selectedDate, setSelectedDate] = useState(today);
  const [kind, setKind] = useState("all");
  const [process, setProcess] = useState("all");
  const [status, setStatus] = useState("all");
  const filtered = entries.filter((entry) => (kind === "all" || entry.kind === kind)
    && (process === "all" || entry.kind === "holiday" || entry.process === process)
    && (status === "all" || (status === "completed" ? entry.completed : !entry.completed)));
  const days = settingsMonthDays(month);
  const selected = settingsEntriesOnDate(filtered, selectedDate);
  useRaviScreenContext("settings-calendar", { month, selectedDate, kind, process, status, selected });
  const monthCount = filtered.filter((entry) => calendarSerialDate(entry.start).slice(0, 7) <= month && calendarSerialDate(entry.end).slice(0, 7) >= month).length;
  function changeMonth(offset: number) {
    const next = shiftCalendarMonth(month, offset);
    setMonth(next);
    setSelectedDate(`${next}-01`);
  }
  return <section className="settings-month-calendar" aria-label="Üretim takvimi">
    <div className="settings-month-heading"><div><span>ÜRETİM TAKVİMİ</span><h3>{new Intl.DateTimeFormat("tr-TR", { month: "long", year: "numeric", timeZone: "UTC" }).format(new Date(`${month}-01T00:00:00Z`))}</h3><p>{monthCount} kayıt · Ayrıntılar için bir gün seçin.</p></div>
      <div className="settings-month-navigation"><button className="secondary" aria-label="Önceki ay" onClick={() => changeMonth(-1)}><CaretLeft size={16} /></button><input type="month" value={month} aria-label="Takvim ayı" onChange={(event) => { if (event.target.value) { setMonth(event.target.value); setSelectedDate(`${event.target.value}-01`); } }} /><button className="secondary" aria-label="Sonraki ay" onClick={() => changeMonth(1)}><CaretRight size={16} /></button><button className="secondary" onClick={() => { setMonth(today.slice(0, 7)); setSelectedDate(today); }}>Bugün</button></div>
    </div>
    <div className="settings-month-filters"><label>Tür<select aria-label="Takvim kayıt türü" value={kind} onChange={(event) => setKind(event.target.value)}><option value="all">Tüm kayıtlar</option>{Object.entries(LABELS).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></label><label>Proses<select aria-label="Takvim prosesi" value={process} onChange={(event) => setProcess(event.target.value)}><option value="all">Tüm prosesler</option><option value="turning">Torna</option><option value="drilling">Delme</option><option value="deburring">Çapak Alma</option><option value="gkm">GKM</option></select></label><label>Durum<select aria-label="Takvim kayıt durumu" value={status} onChange={(event) => setStatus(event.target.value)}><option value="all">Aktif + geçmiş</option><option value="active">Aktif kayıtlar</option><option value="completed">Geçmiş</option></select></label><p>Resmi tatiller tüm proseslerde gösterilir. Pazar kapasitesi vardiya ayarlarına bağlıdır.</p></div>
    <div className="settings-calendar-legend" aria-label="Takvim renk ve simge açıklamaları"><div className="settings-legend-group"><strong>Kayıt türü</strong>{Object.entries(LABELS).map(([key, label]) => <span key={key} className={`settings-calendar-kind ${key}`}>{label}</span>)}</div><div className="settings-legend-group"><strong>Proses</strong>{Object.entries(PROCESS_LABELS).map(([key, label]) => <span className="settings-process-key" key={key}><ProcessIcon process={key} />{label}</span>)}</div><small>Soluk kayıtlar geçmişe aittir.</small></div>
    <div className="settings-month-layout"><div className="settings-month-scroll"><div className="settings-month-grid" role="group" aria-label="Aylık takvim">
      {["Pzt", "Sal", "Çar", "Per", "Cum", "Cmt", "Paz"].map((day) => <div className="settings-weekday" key={day}>{day}</div>)}
      {days.map((date, index) => {
        const events = settingsEntriesOnDate(filtered, date);
        return <button key={date} type="button" aria-label={`${dateLabel(date)}, ${events.length} kayıt`} aria-pressed={date === selectedDate} onClick={() => setSelectedDate(date)} className={`settings-day ${date.startsWith(month) ? "" : "outside"} ${index % 7 === 6 ? "sunday" : ""} ${date === selectedDate ? "selected" : ""}`}>
          <span className={`settings-day-number ${date === today ? "today" : ""}`}>{Number(date.slice(-2))}{date === today && <small>Bugün</small>}</span>
          {events.slice(0, 3).map((entry) => <span key={entry.id} className={`settings-calendar-chip ${entry.kind} ${entry.completed ? "completed" : ""}`} title={`${LABELS[entry.kind]} · ${entryProcessLabel(entry)} · ${entry.resource ? `${entry.resource} · ` : ""}${entry.title}`}><ProcessIcon process={entryProcess(entry)} /><span className="settings-chip-copy"><b>{LABELS[entry.kind]}{entry.resource ? ` · ${entry.resource}` : ""}</b><span>{entry.title}</span></span></span>)}
          {events.length > 3 && <span className="settings-day-more">+{events.length - 3} kayıt daha</span>}
        </button>;
      })}
    </div></div>
    <aside className="settings-day-details" aria-label="Seçili günün kayıtları"><CalendarBlank size={21} /><h4>{dateLabel(selectedDate)}</h4><p>{selected.length} kayıt</p>
      {selected.map((entry) => <article key={entry.id} className={entry.kind}><div><span className={`settings-calendar-kind ${entry.kind}`}>{LABELS[entry.kind]}</span>{entry.completed && <small>Geçmiş</small>}</div><strong>{entry.title}</strong><span className="settings-entry-process"><ProcessIcon process={entryProcess(entry)} />{entryProcessLabel(entry)}</span><span>{entry.resource || "Tüm iş merkezleri"} · {entry.kind === "maintenance" ? "Üretim durur" : `${entry.shifts} vardiya`}</span><small>{dateLabel(calendarSerialDate(entry.start))}{Math.floor(entry.end) !== Math.floor(entry.start) ? ` – ${dateLabel(calendarSerialDate(entry.end))}` : ""}</small>{!entry.completed && <button className="secondary" onClick={() => onEdit(entry)}><PencilSimple size={13} /> Düzenle</button>}</article>)}
      {!selected.length && <div className="settings-day-empty">Bu gün için seçili filtrelerde kayıt yok.<br />Yeni kayıtları ilgili ayar sekmesinden ekleyebilirsiniz.</div>}
    </aside></div>

  </section>;
}

"use client";

import { useRaviScreenContext } from "@/features/ravi/context";

import { ProcessIcon } from "@/components/ProcessIcon";

import { effectiveWaitSources, legacyWashingRules } from "@/lib/flow-settings";
import { FlowSettingsPanel } from "../parameters/FlowSettingsPanel";
import { ProcessWaitSettingsPanel } from "./ProcessWaitSettingsPanel";
import { ProductWeights } from "./ProductWeights";
import { RawMaterialConsumption } from "./RawMaterialConsumption";
import { SettingsCalendar } from "./SettingsCalendar";
import type { SettingsCalendarEntry } from "@/lib/settings-calendar";
import { MachineMaintenanceDialog, MachineShiftDialog, ShiftOptions } from "@/features/planning/machines/CalendarDialogs";
import { DataPackageActions } from "@/features/planning/shared/DataPackageActions";
import { Field } from "@/features/planning/shared/controls";
import { dateAfterDays, inputDateToSerial, serialToInputDate } from "@/features/planning/shared/format";
import { clampShiftCount } from "@/features/planning/shared/production";
import { useApiFetch } from "@/lib/api";
import { calendarEventStatus } from "@/lib/calendar-event-status";
import { applySettingsPackage, settingsPackage } from "@/lib/data-packages";
import { factoryDateInput } from "@/lib/factory-time";
import {
  formatExcelDate,
  getSetupSettings,
  removeMachineShiftOverrides,
  replaceMachineShiftOverrides,
  type Machine,
  type MachineCalendarEvent,
  type PlanningSeed,
  type ScenarioResult,
  type ShiftCount,
} from "@/lib/planning";
import { processLabel, type ProcessKind } from "@/lib/process-master-data";
import {
  ArrowsLeftRight,
  CalendarBlank,
  CheckCircle,
  Clock,
  FileXls,
  PencilSimple,
  Plus,
  Trash,
  Warning,
  Wrench,
} from "@phosphor-icons/react";
import { useEffect, useState, type ReactNode } from "react";

type CalendarDetailType = "maintenance" | "overtime" | "shift-change";
type SettingsSection = "waits" | "weights" | "calendar" | "setup" | "holidays" | "maintenance" | "shifts";
const SETTINGS_SECTIONS: Array<{ id: SettingsSection; label: string }> = [
  { id: "calendar", label: "Takvim" }, { id: "waits", label: "Proses bekleme süreleri" }, { id: "setup", label: "Setup" }, { id: "holidays", label: "Resmi tatiller" },
  { id: "maintenance", label: "Bakımlar" }, { id: "shifts", label: "Mesai ve vardiya" }, { id: "weights", label: "Hammadde Bilgileri" },
];

function settingsCalendarMachine(seed: PlanningSeed, resourceId: string): Machine | undefined {
  const machine = seed.machines.find((item) => item.id === resourceId);
  if (machine) return machine;
  const resource = seed.processMasterData?.resources.find((item) => item.id === resourceId)
    ?? (resourceId === "B-01" ? seed.processMasterData?.resources.find((item) => item.process === "deburring") : undefined);
  if (!resource) return undefined;
  const start = resource.availableStart ?? inputDateToSerial(factoryDateInput());
  return {
    id: resourceId,
    name: resourceId === "B-01" ? "Ortak Çapak Alma" : resource.name,
    active: resource.active,
    availableStart: start,
    operationalAvailableStart: start,
    planEnd: resource.planEnd ?? start + 365,
    note: processLabel(resource.process),
    shiftFactor: resource.defaultShifts,
    capacityFactor: 1,
    finishOffset: 0,
    rates: {},
    currentJob: { workOrder: "", product: "", quantity: 0, originalQuantity: 0, remainingQuantity: 0, start, end: start, dailyRate: 0, diameter: "" },
  };
}

export function SettingsView({ seed, result, dirty, updateMaterials, updateSeed, updatePlanningInputs }: { seed: PlanningSeed; result: ScenarioResult; dirty: boolean; updateMaterials: (mutator: (seed: PlanningSeed) => void) => void; updateSeed: (mutator: (seed: PlanningSeed) => void) => void; updatePlanningInputs: (mutator: (seed: PlanningSeed) => void) => void }) {
  const apiFetch = useApiFetch();
  const pistonSettings = seed.productionArea !== "cubuk-filtre";
  const [section, setSection] = useState<SettingsSection>("calendar");
  const [materialSection, setMaterialSection] = useState<"weights" | "consumption">("weights");
  const [holidayDraft, setHolidayDraft] = useState({ name: "", date: dateAfterDays(7), workingShifts: 0 as ShiftCount });
  const initialEventDraft = { machineId: seed.machines[0]?.id ?? "", kind: "maintenance" as MachineCalendarEvent["kind"], name: "", start: dateAfterDays(1), end: dateAfterDays(1), shiftCount: 1 as ShiftCount };
  const [eventDrafts, setEventDrafts] = useState({ maintenance: initialEventDraft, shifts: { ...initialEventDraft, kind: "shift" as MachineCalendarEvent["kind"] } });
  const draftSection = section === "shifts" ? "shifts" : "maintenance";
  const eventDraft = eventDrafts[draftSection];
  const setEventDraft = (value: typeof eventDraft | ((current: typeof eventDraft) => typeof eventDraft)) => setEventDrafts((current) => ({ ...current, [draftSection]: typeof value === "function" ? value(current[draftSection]) : value }));
  const [editingHoliday, setEditingHoliday] = useState<{ original: number; name: string; date: string; shifts: ShiftCount } | null>(null);
  const [holidayEditError, setHolidayEditError] = useState("");
  const [editingShiftId, setEditingShiftId] = useState<string | null>(null);
  const [editingMaintenanceId, setEditingMaintenanceId] = useState<string | null>(null);
  const [calendarTypeFilter, setCalendarTypeFilter] = useState<CalendarDetailType | "all">("all");
  const [calendarProcessFilter, setCalendarProcessFilter] = useState<ProcessKind | "all">("all");
  const [calendarStatusFilter, setCalendarStatusFilter] = useState<"active" | "completed" | "all">("active");
  const [calendarFilterStart, setCalendarFilterStart] = useState("");
  const [calendarFilterEnd, setCalendarFilterEnd] = useState("");
  const [calendarExporting, setCalendarExporting] = useState(false);
  const [calendarExportError, setCalendarExportError] = useState("");
  const [calendarToday, setCalendarToday] = useState(factoryDateInput);
  const [setupDraft, setSetupDraft] = useState(() => getSetupSettings(seed));
  const setup = getSetupSettings(seed);
  useRaviScreenContext("settings", { effectiveWaitSources: section === "waits" ? effectiveWaitSources(seed) : undefined, hasLegacyWashing: section === "waits" && seed.productionArea !== "cubuk-filtre" ? legacyWashingRules(seed.flowSettings).length > 0 : undefined, section, materialSection: section === "weights" ? materialSection : undefined, calendarTypeFilter, calendarProcessFilter, calendarStatusFilter, calendarFilterStart, calendarFilterEnd, setup, setupDraft, eventDraft, editingShiftId, editingMaintenanceId });
  const setupChanged = Object.keys(setup).some((key) => setup[key as keyof typeof setup] !== setupDraft[key as keyof typeof setupDraft]);

  useEffect(() => setSetupDraft(getSetupSettings(seed)), [setup.shiftHours, setup.sameDiameterHours, setup.sameFamilyDifferentDiameterHours, setup.crossFamilyHours, setup.differentDiameterHours]);
  useEffect(() => {
    const refreshFactoryDay = () => setCalendarToday(factoryDateInput());
    const interval = window.setInterval(refreshFactoryDay, 60_000);
    return () => window.clearInterval(interval);
  }, []);

  function saveSetupSettings() {
    const normalized = getSetupSettings({ setupSettings: setupDraft });
    updatePlanningInputs((draft) => { draft.setupSettings = normalized; });
    setSetupDraft(normalized);
  }

  function addHoliday() {
    const serial = inputDateToSerial(holidayDraft.date);
    if (!holidayDraft.name.trim() || !serial) return;
    updateSeed((draft) => {
      const existing = draft.holidays.find((holiday) => Math.floor(holiday.serial) === serial);
      if (existing) Object.assign(existing, { name: holidayDraft.name.trim(), workingShifts: holidayDraft.workingShifts });
      else draft.holidays.push({ name: holidayDraft.name.trim(), serial, workingShifts: holidayDraft.workingShifts });
    });
    setHolidayDraft({ name: "", date: dateAfterDays(7), workingShifts: 0 });
  }

  function addCalendarEvent() {
    const start = inputDateToSerial(eventDraft.start);
    const end = inputDateToSerial(eventDraft.end);
    if (!eventDraft.machineId || !start || !end || end < start) return;
    updateSeed((draft) => {
      if (eventDraft.kind === "shift") {
        replaceMachineShiftOverrides(draft, [eventDraft.machineId], start, end, eventDraft.shiftCount, eventDraft.name.trim() || "Vardiya değişikliği");
        return;
      }
      draft.calendarEvents = [...(draft.calendarEvents ?? []), {
        id: `takvim-${Date.now()}`,
        machineId: eventDraft.machineId,
        kind: eventDraft.kind,
        name: eventDraft.name.trim() || (eventDraft.kind === "maintenance" ? "Planlı bakım" : "Vardiya değişikliği"),
        start,
        end,
        shiftCount: eventDraft.kind === "maintenance" ? 0 : eventDraft.shiftCount,
      }];
    });
    setEventDraft((current) => ({ ...current, name: "" }));
  }

  const sortedHolidays = [...seed.holidays].sort((left, right) => left.serial - right.serial);
  const calendarResources = [
    ...seed.machines.map((machine) => ({ id: machine.id, name: machine.name, process: "turning" as ProcessKind, defaultShifts: machine.shiftFactor })),
    ...(seed.processMasterData?.resources ?? []).filter((resource) => resource.process !== "turning").map((resource) => ({ id: resource.id, name: resource.name, process: resource.process, defaultShifts: resource.defaultShifts })),
  ];
  const calendarResourceMap = new Map(calendarResources.map((resource) => [resource.id, resource]));
  const calendarTodaySerial = inputDateToSerial(calendarToday);
  const sortedEvents = [...(seed.calendarEvents ?? [])].sort((left, right) => left.start - right.start || left.machineId.localeCompare(right.machineId));
  const calendarEventDetails = sortedEvents.map((event) => {
    const fallbackProcess: ProcessKind = event.machineId.startsWith("D-") ? "drilling" : event.machineId.startsWith("B-") ? "deburring" : event.machineId.startsWith("V-") ? "gkm" : "turning";
    const resource = calendarResourceMap.get(event.machineId) ?? { id: event.machineId, name: event.machineId === "B-01" ? "Ortak Çapak Alma" : "Tanımsız iş merkezi", process: fallbackProcess, defaultShifts: 3 as ShiftCount };
    const namedOvertime = event.name.toLocaleUpperCase("tr-TR").includes("MESAİ");
    const type: CalendarDetailType = event.kind === "maintenance" ? "maintenance" : namedOvertime || event.shiftCount > resource.defaultShifts ? "overtime" : "shift-change";
    return { event, resource, type, ...calendarEventStatus(event, calendarTodaySerial) };
  });
  const calendarEntries: SettingsCalendarEntry[] = [
    ...sortedHolidays.map((holiday) => ({ id: `holiday:${holiday.serial}`, title: holiday.name, kind: "holiday" as const, start: holiday.serial, end: holiday.serial, shifts: holiday.workingShifts ?? 0, completed: Math.floor(holiday.serial) < calendarTodaySerial })),
    ...calendarEventDetails.map(({ event, resource, type, status }) => ({ id: event.id, title: event.name, kind: type, start: event.start, end: event.end, shifts: event.shiftCount, resource: event.machineId, process: resource.process, completed: status === "completed" })),
  ];
  function editCalendarEntry(entry: SettingsCalendarEntry) {
    if (entry.kind === "holiday") {
      setHolidayEditError("");
      setEditingHoliday({ original: entry.start, name: entry.title, date: serialToInputDate(entry.start), shifts: clampShiftCount(entry.shifts) });
    } else if (entry.kind === "maintenance") setEditingMaintenanceId(entry.id);
    else setEditingShiftId(entry.id);
  }
  const filterStartSerial = inputDateToSerial(calendarFilterStart);
  const filterEndSerial = inputDateToSerial(calendarFilterEnd);
  const filteredCalendarEvents = calendarEventDetails.filter(({ event, resource, type, status }) =>
    (section === "maintenance" ? type === "maintenance" : type !== "maintenance")
    && (section === "maintenance" || calendarTypeFilter === "all" || type === calendarTypeFilter)
    && (calendarProcessFilter === "all" || resource.process === calendarProcessFilter)
    && (calendarStatusFilter === "all" || status === calendarStatusFilter)
    && (!filterStartSerial || event.end >= filterStartSerial)
    && (!filterEndSerial || event.start <= filterEndSerial));
  const editingShift = sortedEvents.find((event) => event.id === editingShiftId && event.kind === "shift");
  const editingShiftMachine = editingShift ? settingsCalendarMachine(seed, editingShift.machineId) : undefined;
  const editingMaintenance = sortedEvents.find((event) => event.id === editingMaintenanceId && event.kind === "maintenance");
  const editingMaintenanceMachine = editingMaintenance ? settingsCalendarMachine(seed, editingMaintenance.machineId) : undefined;

  async function exportCalendarEvents() {
    setCalendarExporting(true);
    setCalendarExportError("");
    try {
      const response = await apiFetch("/calendar-events/export", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          generatedAt: new Date().toISOString(),
          rows: filteredCalendarEvents.map(({ event, resource, type, status, automaticallyCompleted }) => ({
            eventType: type,
            process: resource.process,
            workCenterId: event.machineId,
            workCenterName: resource.name,
            name: event.name,
            startDate: serialToInputDate(event.start),
            endDate: serialToInputDate(event.end),
            shiftCount: event.shiftCount,
            status,
            completedAt: event.completedAt ?? (automaticallyCompleted ? serialToInputDate(event.end) : ""),
          })),
        }),
      });
      if (!response.ok) {
        const body = await response.json().catch(() => ({ detail: "Bakım ve mesai Excel’i oluşturulamadı." }));
        throw new Error(body.detail || "Bakım ve mesai Excel’i oluşturulamadı.");
      }
      const blob = await response.blob();
      const disposition = response.headers.get("Content-Disposition") ?? "";
      const filename = disposition.match(/filename="([^"]+)"/)?.[1] ?? `Bakim_Mesai_Vardiya_Detayi_${factoryDateInput()}.xlsx`;
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement("a");
      anchor.href = url;
      anchor.download = filename;
      anchor.click();
      URL.revokeObjectURL(url);
    } catch (reason) {
      setCalendarExportError(reason instanceof Error ? reason.message : "Bakım ve mesai Excel’i oluşturulamadı.");
    } finally {
      setCalendarExporting(false);
    }
  }
  return (
    <><section className={`settings-page ${pistonSettings ? "piston-settings-page" : ""}`}>
      <div className="calendar-heading"><div><span>{pistonSettings ? "AYARLAR" : section === "weights" ? "HAMMADDE BİLGİLERİ" : "ÜRETİM TAKVİMİ"}</span><h2>{pistonSettings ? "Üretim ayarları" : section === "weights" ? "Çelik ihtiyacını ve stok yeterliliğini izleyin" : "Kapasiteyi tarihe göre yönetin"}</h2><p>{pistonSettings ? "Piston ve Center Pin için akış, hazırlık, takvim ve hammadde ayarları." : section === "weights" ? "Ürün ağırlıklarını ve ıskarta oranını güncel tutun; Torna planına göre ambar stoğunuzun hangi güne kadar yettiğini görün." : "Pazar günleri ve vardiya verilmemiş resmi tatiller üretim dışıdır. Değişiklikler mevcut kuyruk korunarak başlangıç ve bitiş tarihlerine hemen yansır."}</p></div><div className="calendar-heading-tools"><div className="calendar-summary" hidden={pistonSettings || section === "weights"}><span><b>{seed.holidays.length}</b> tatil</span><span><b>{calendarEventDetails.filter(({ type, status }) => type === "maintenance" && status === "active").length}</b> açık bakım</span><span><b>{calendarEventDetails.filter(({ status }) => status === "completed").length}</b> geçmiş kayıt</span></div><DataPackageActions scope="settings" data={settingsPackage(seed)} onImport={(data) => updatePlanningInputs((draft) => applySettingsPackage(draft, data))} /></div></div>
      <nav className="settings-tabs" role="tablist" aria-label="Ayar kategorileri">{SETTINGS_SECTIONS.map((tab) => <button type="button" key={tab.id} id={tab.id === "weights" ? "settings-tab-materials" : tab.id === "waits" ? "settings-tab-waits" : `settings-tab-${tab.id}`} role="tab" aria-selected={section === tab.id} aria-controls={pistonSettings && ["waits", "setup", "shifts"].includes(tab.id) ? "settings-parameter-controls" : tab.id === "maintenance" || tab.id === "shifts" ? "settings-events" : `settings-${tab.id}`} className={section === tab.id ? "active" : ""} onClick={() => setSection(tab.id)}>{pistonSettings && tab.id === "waits" ? "Akış ve bekleme" : tab.label}</button>)}</nav>
      {pistonSettings && <div id="settings-parameter-controls" role="tabpanel" aria-labelledby={`settings-tab-${["waits", "setup", "shifts"].includes(section) ? section : "waits"}`} hidden={!["waits", "setup", "shifts"].includes(section)}>
        <FlowSettingsPanel seed={seed} result={result} updateSeed={updatePlanningInputs} canEdit={true} section={section === "setup" ? "SETUP Süreleri" : section === "shifts" ? "Vardiya ve Mesai Bilgileri" : "Akış Ayarı"} active={["waits", "setup", "shifts"].includes(section)} />
        <div hidden={section !== "waits"}><details className="settings-disclosure settings-fallback"><summary>İş günü varsayılanları (yedek kurallar)</summary><p className="settings-help">Yalnızca etkin saat kuralı bulunmayan geçişlerde kullanılır. Yukarıdaki kayıtlı kurallar geçerli kaynağı gösterir.</p><ProcessWaitSettingsPanel seed={seed} updatePlanningInputs={updatePlanningInputs} active={section === "waits"} /></details></div>
      </div>}
      {!pistonSettings && <section id="settings-waits" role="tabpanel" aria-labelledby="settings-tab-waits" hidden={section !== "waits"}>{section === "waits" && <ProcessWaitSettingsPanel seed={seed} updatePlanningInputs={updatePlanningInputs} />}</section>}
      <section id="settings-weights" role="tabpanel" aria-labelledby="settings-tab-materials" hidden={section !== "weights"}>
        <nav className="settings-tabs material-subtabs" role="tablist" aria-label="Hammadde Bilgileri">
          <button id="settings-tab-weights" role="tab" aria-selected={materialSection === "weights"} aria-controls="material-weights-panel" className={materialSection === "weights" ? "active" : ""} onClick={() => { setSection("weights"); setMaterialSection("weights"); }}>Ürün Ağırlıkları</button>
          <button id="settings-tab-consumption" role="tab" aria-selected={materialSection === "consumption"} aria-controls="material-consumption-panel" className={materialSection === "consumption" ? "active" : ""} onClick={() => { setSection("weights"); setMaterialSection("consumption"); }}>Hammadde Tüketim Tablosu</button>
        </nav>
        <div id="material-weights-panel" role="tabpanel" aria-labelledby="settings-tab-weights" hidden={materialSection !== "weights"}>{section === "weights" && materialSection === "weights" && <ProductWeights seed={seed} updateSeed={updateMaterials} />}</div>
        <div id="material-consumption-panel" role="tabpanel" aria-labelledby="settings-tab-consumption" hidden={materialSection !== "consumption"}>{section === "weights" && materialSection === "consumption" && <RawMaterialConsumption seed={seed} result={result} dirty={dirty} updateSeed={updateMaterials} />}</div>
      </section>
      <section id="settings-calendar" role="tabpanel" aria-labelledby="settings-tab-calendar" hidden={section !== "calendar"}><SettingsCalendar entries={calendarEntries} today={calendarToday} onEdit={editCalendarEntry} /></section>
      {!pistonSettings && <section id="settings-setup" role="tabpanel" aria-labelledby="settings-tab-setup" hidden={section !== "setup"} className="setup-settings"><div className="setup-settings-heading"><span className="dialog-icon shift"><ArrowsLeftRight size={19} /></span><div><span>SETUP VE ÜRÜN AİLESİ</span><h3>Ürün, çap ve aile geçişlerini üretim saatine dahil edin</h3><p>Aynı ürün 0 saattir. Farklı ürün aynı çapta 1 saat, aynı ailede çap değişirse 2 saat, piston ile Center Pin arasında 5 saat uygulanır. Başlangıç ve ailesi tanımsız ürünler mevcut ayrı süreyi kullanır.</p></div></div><div className="setup-settings-grid"><Field label="Vardiya süresi"><span className="number-with-unit"><input type="number" min="1" max="24" step="0.5" value={setupDraft.shiftHours} onChange={(event) => setSetupDraft({ ...setupDraft, shiftHours: Number(event.target.value) })} /><em>saat</em></span></Field><Field label="Farklı ürün · aynı çap"><span className="number-with-unit"><input type="number" min="0" step="0.5" value={setupDraft.sameDiameterHours} onChange={(event) => setSetupDraft({ ...setupDraft, sameDiameterHours: Number(event.target.value) })} /><em>saat</em></span></Field><Field label="Aynı aile · farklı çap"><span className="number-with-unit"><input type="number" min="0" step="0.5" value={setupDraft.sameFamilyDifferentDiameterHours} onChange={(event) => setSetupDraft({ ...setupDraft, sameFamilyDifferentDiameterHours: Number(event.target.value) })} /><em>saat</em></span></Field><Field label="Piston ↔ Center Pin"><span className="number-with-unit"><input type="number" min="0" step="0.5" value={setupDraft.crossFamilyHours} onChange={(event) => setSetupDraft({ ...setupDraft, crossFamilyHours: Number(event.target.value) })} /><em>saat</em></span></Field><Field label="Başlangıç / tanımsız"><span className="number-with-unit"><input type="number" min="0" step="0.5" value={setupDraft.differentDiameterHours} onChange={(event) => setSetupDraft({ ...setupDraft, differentDiameterHours: Number(event.target.value) })} /><em>saat</em></span></Field><button className="primary" disabled={!setupChanged} onClick={saveSetupSettings}>{setupChanged ? "Ayarları kaydet" : "Güncel"}</button></div></section>}
      <div className="settings-canonical-note" hidden={section !== "maintenance" && section !== "shifts"}><Wrench size={17} /><div><strong>Tüm iş merkezlerinin takvim geçmişi tek yerde</strong><span>Torna, Delme, Çapak Alma ve GKM bakım, mesai ve vardiya değişikliklerini seçili kategoride filtreleyebilir; tamamlanan bakımları kaydı silmeden geçmişe taşıyabilirsiniz.</span></div></div>
      <SettingsCalendarWorkspace section={section}>
        <section id="settings-holidays" role="tabpanel" aria-labelledby="settings-tab-holidays" hidden={section !== "holidays"} className="calendar-section holiday-section">
          <div className="calendar-section-title"><CalendarBlank size={19} /><div><h3>Resmi tatiller</h3><p>0 vardiya üretimi durdurur; 1–3 vardiya tatilde üretime izin verir.</p></div></div>
          <div className="calendar-add-row holiday-add"><input value={holidayDraft.name} onChange={(event) => setHolidayDraft({ ...holidayDraft, name: event.target.value })} placeholder="Tatil adı" aria-label="Yeni tatil adı" /><input type="date" value={holidayDraft.date} onChange={(event) => setHolidayDraft({ ...holidayDraft, date: event.target.value })} aria-label="Yeni tatil tarihi" /><select value={holidayDraft.workingShifts} onChange={(event) => setHolidayDraft({ ...holidayDraft, workingShifts: clampShiftCount(Number(event.target.value)) })} aria-label="Tatilde vardiya"><ShiftOptions /></select><button className="primary" onClick={addHoliday}><Plus size={14} /> Ekle</button></div>
          <div className="calendar-table-head holiday-grid"><span>Tatil</span><span>Tarih</span><span>Üretim</span><span /></div>
          <div className="calendar-list">{sortedHolidays.map((holiday) => <div className="calendar-row holiday-grid" key={`${holiday.name}-${holiday.serial}`}><input value={holiday.name} onChange={(event) => updateSeed((draft) => { const target = draft.holidays.find((item) => item.serial === holiday.serial); if (target) target.name = event.target.value; })} aria-label={`${holiday.name} adı`} /><input type="date" value={serialToInputDate(holiday.serial)} onChange={(event) => updateSeed((draft) => { const target = draft.holidays.find((item) => item.serial === holiday.serial); if (target) target.serial = inputDateToSerial(event.target.value); })} aria-label={`${holiday.name} tarihi`} /><select value={holiday.workingShifts ?? 0} onChange={(event) => updateSeed((draft) => { const target = draft.holidays.find((item) => item.serial === holiday.serial); if (target) target.workingShifts = clampShiftCount(Number(event.target.value)); })} aria-label={`${holiday.name} vardiyası`}><ShiftOptions /></select><button className="delete-button" onClick={() => updateSeed((draft) => { draft.holidays = draft.holidays.filter((item) => item.serial !== holiday.serial); })} aria-label={`${holiday.name} tatilini sil`}><Trash size={15} /></button></div>)}</div>
        </section>
        <section id="settings-events" role="tabpanel" aria-labelledby={`settings-tab-${section}`} hidden={section === "holidays"} className="calendar-section exception-section">
          <div className="calendar-section-title"><Wrench size={19} /><div><h3>{section === "maintenance" ? "Planlı bakımlar" : "Mesai ve vardiya değişiklikleri"}</h3><p>Tüm iş merkezlerinde planlı bakım, ek mesai ve vardiya değişikliklerini yönetin; aktif kayıtları ve geçmişi aynı yerden izleyin.</p></div></div>
          <div className="calendar-event-form"><Field label="İş merkezi"><select value={eventDraft.machineId} onChange={(event) => setEventDraft({ ...eventDraft, machineId: event.target.value })}>{calendarResources.map((resource) => <option key={resource.id} value={resource.id}>{processLabel(resource.process)} · {resource.id}</option>)}</select></Field><Field label="Başlangıç"><input type="date" value={eventDraft.start} onChange={(event) => setEventDraft({ ...eventDraft, start: event.target.value, end: event.target.value > eventDraft.end ? event.target.value : eventDraft.end })} /></Field><Field label="Bitiş"><input type="date" min={eventDraft.start} value={eventDraft.end} onChange={(event) => setEventDraft({ ...eventDraft, end: event.target.value })} /></Field><Field label="Açıklama"><input value={eventDraft.name} onChange={(event) => setEventDraft({ ...eventDraft, name: event.target.value })} placeholder={eventDraft.kind === "maintenance" ? "Yıllık bakım" : "Hafta sonu mesaisi"} /></Field>{eventDraft.kind === "shift" && <Field label="Vardiya"><select value={eventDraft.shiftCount} onChange={(event) => setEventDraft({ ...eventDraft, shiftCount: clampShiftCount(Number(event.target.value)) })}><ShiftOptions /></select></Field>}<button className="primary calendar-event-add" onClick={addCalendarEvent}><Plus size={14} /> Takvime ekle</button></div>
          <div className="calendar-detail-toolbar">{section === "shifts" && <label><span>Tür</span><select value={calendarTypeFilter} onChange={(event) => setCalendarTypeFilter(event.target.value as CalendarDetailType | "all")}><option value="all">Tüm kayıtlar</option><option value="overtime">Mesai</option><option value="shift-change">Vardiya değişikliği</option></select></label>}<label><span>Proses</span><select value={calendarProcessFilter} onChange={(event) => setCalendarProcessFilter(event.target.value as ProcessKind | "all")}><option value="all">Tüm prosesler</option><option value="turning">Torna</option><option value="drilling">Delme</option><option value="deburring">Çapak Alma</option><option value="gkm">GKM</option></select></label><label><span>Durum</span><select value={calendarStatusFilter} onChange={(event) => setCalendarStatusFilter(event.target.value as "active" | "completed" | "all")}><option value="active">Aktif kayıtlar</option><option value="completed">Geçmiş</option><option value="all">Aktif + geçmiş</option></select></label><label><span>Başlangıç</span><input type="date" value={calendarFilterStart} onChange={(event) => setCalendarFilterStart(event.target.value)} /></label><label><span>Bitiş</span><input type="date" min={calendarFilterStart || undefined} value={calendarFilterEnd} onChange={(event) => setCalendarFilterEnd(event.target.value)} /></label><button className="calendar-excel-export" disabled={calendarExporting} onClick={() => void exportCalendarEvents()}><FileXls size={15} /> {calendarExporting ? "Hazırlanıyor…" : "Excel indir"}</button></div>
          <div className="calendar-detail-summary"><span><strong>{filteredCalendarEvents.length}</strong> kayıt gösteriliyor</span><span>{calendarEventDetails.filter(({ status }) => status === "active").length} aktif</span><span>{calendarEventDetails.filter(({ status }) => status === "completed").length} geçmiş</span></div>
          {calendarExportError && <div className="dashboard-export-error" role="alert"><Warning size={14} weight="fill" /><span>{calendarExportError}</span><button onClick={() => setCalendarExportError("")}>Kapat</button></div>}
          <div className="calendar-event-list detail-list">{filteredCalendarEvents.length ? filteredCalendarEvents.map(({ event, resource, type, status, automaticallyCompleted }) => (
            <article key={event.id} className={`${event.kind} ${status}`}>
              <span className="calendar-event-icon">{event.kind === "maintenance" ? <Wrench size={14} /> : <Clock size={14} />}</span>
              <div><strong>{event.machineId} · {event.name}</strong><small><ProcessIcon process={resource.process} size={13} /> {processLabel(resource.process)} · {resource.name} · {formatExcelDate(event.start)}{event.end !== event.start ? ` – ${formatExcelDate(event.end)}` : ""}{event.completedAt ? ` · tamamlandı ${new Intl.DateTimeFormat("tr-TR", { dateStyle: "short", timeStyle: "short", timeZone: "Europe/Istanbul" }).format(new Date(event.completedAt))}` : automaticallyCompleted ? " · süresi tamamlandı" : ""}</small></div>
              <em>{type === "maintenance" ? "Planlı bakım" : type === "overtime" ? "Mesai" : "Vardiya değişikliği"}</em>
              <div className="calendar-event-actions">
                {event.kind === "maintenance" && <label className="maintenance-complete-toggle"><input type="checkbox" checked={status === "completed"} onChange={(changeEvent) => updateSeed((draft) => { const target = (draft.calendarEvents ?? []).find((item) => item.id === event.id); if (target) target.completedAt = changeEvent.target.checked ? new Date().toISOString() : undefined; })} /><span>Tamamlandı</span></label>}
                {automaticallyCompleted && <span className="calendar-auto-complete"><CheckCircle size={13} weight="fill" /> Tamamlandı</span>}
                {status === "active" && <button className="edit-button" onClick={() => event.kind === "shift" ? setEditingShiftId(event.id) : setEditingMaintenanceId(event.id)} aria-label={`${event.name} ${event.kind === "shift" ? "vardiya" : "bakım"} kaydını düzenle`}><PencilSimple size={14} /></button>}
                <button className="delete-button" onClick={() => updateSeed((draft) => { if (event.kind === "shift") removeMachineShiftOverrides(draft, [event.machineId], event.start, event.end); else draft.calendarEvents = (draft.calendarEvents ?? []).filter((item) => item.id !== event.id); })} aria-label={`${event.name} kaydını sil`}><Trash size={15} /></button>
              </div>
            </article>
          )) : <p className="calendar-empty">Seçili filtrelerle eşleşen bakım, mesai veya vardiya kaydı yok.</p>}</div>
        </section>
      </SettingsCalendarWorkspace>
    </section>{editingHoliday && <div className="confirmation-backdrop" role="presentation"><section className="completion-dialog" role="dialog" aria-modal="true" aria-label="Resmi tatili düzenle"><CalendarBlank size={24} /><h2>Resmi tatili düzenle</h2><Field label="Tatil adı"><input value={editingHoliday.name} onChange={(event) => setEditingHoliday({ ...editingHoliday, name: event.target.value })} /></Field><Field label="Tatil tarihi"><input type="date" value={editingHoliday.date} onChange={(event) => setEditingHoliday({ ...editingHoliday, date: event.target.value })} /></Field><Field label="Tatilde vardiya"><select value={editingHoliday.shifts} onChange={(event) => setEditingHoliday({ ...editingHoliday, shifts: clampShiftCount(Number(event.target.value)) })}><ShiftOptions /></select></Field>{holidayEditError && <p className="form-error">{holidayEditError}</p>}<div className="drawer-actions"><button className="secondary" onClick={() => setEditingHoliday(null)}>Vazgeç</button><button className="primary" onClick={() => {
      const serial = inputDateToSerial(editingHoliday.date);
      if (!editingHoliday.name.trim() || !serial) { setHolidayEditError("Tatil adı ve tarihi zorunludur."); return; }
      if (seed.holidays.some((holiday) => holiday.serial !== editingHoliday.original && Math.floor(holiday.serial) === serial)) { setHolidayEditError("Bu tarihte zaten bir resmi tatil var."); return; }
      updateSeed((draft) => { const holiday = draft.holidays.find((item) => item.serial === editingHoliday.original); if (holiday) Object.assign(holiday, { name: editingHoliday.name.trim(), serial, workingShifts: editingHoliday.shifts }); });
      setEditingHoliday(null);
    }}>Kaydet</button></div></section></div>}{editingShift && editingShiftMachine && <MachineShiftDialog key={editingShift.id} machine={editingShiftMachine} events={sortedEvents.filter((event) => event.machineId === editingShift.machineId && event.kind === "shift")} initialEvent={editingShift} onClose={() => setEditingShiftId(null)} onSave={(name, start, end, shifts, editingId) => { updateSeed((draft) => { if (editingId) { const existing = (draft.calendarEvents ?? []).find((event) => event.id === editingId); if (existing) removeMachineShiftOverrides(draft, [existing.machineId], existing.start, existing.end); } replaceMachineShiftOverrides(draft, [editingShift.machineId], start, end, shifts, name); }); setEditingShiftId(null); }} onDelete={(eventId) => { updateSeed((draft) => { const existing = (draft.calendarEvents ?? []).find((event) => event.id === eventId); if (existing) removeMachineShiftOverrides(draft, [existing.machineId], existing.start, existing.end); }); if (eventId === editingShiftId) setEditingShiftId(null); }} />}{editingMaintenance && editingMaintenanceMachine && <MachineMaintenanceDialog key={editingMaintenance.id} machine={editingMaintenanceMachine} events={sortedEvents.filter((event) => event.machineId === editingMaintenance.machineId && event.kind === "maintenance")} initialEvent={editingMaintenance} onClose={() => setEditingMaintenanceId(null)} onSave={(name, start, end, editingId) => { updateSeed((draft) => { const existing = (draft.calendarEvents ?? []).find((event) => event.id === editingId); if (existing) Object.assign(existing, { name, start, end, shiftCount: 0 }); }); setEditingMaintenanceId(null); }} onDelete={(eventId) => { updateSeed((draft) => { draft.calendarEvents = (draft.calendarEvents ?? []).filter((event) => event.id !== eventId); }); if (eventId === editingMaintenanceId) setEditingMaintenanceId(null); }} />}</>
  );
}


export function SettingsCalendarWorkspace({ section, children }: { section: string; children: ReactNode }) {
  if (!["holidays", "maintenance", "shifts"].includes(section)) return null;
  return <div className="calendar-workspace settings-tab-workspace">{children}</div>;
}

frontend/features/planning/shared/DataPa.source:
"use client";

import { useRaviScreenContext } from "../../ravi/context";
import { useApiFetch } from "@/lib/api";
import { type DataPackageScope, dataPackageSummary } from "@/lib/data-packages";
import { FileXls, UploadSimple, X } from "@phosphor-icons/react";
import { useState } from "react";

export function DataPackageActions({ scope, data, onImport, exportDisabled = false, exportLabel = "Excel indir", importLabel = "Excel yükle" }: { scope: DataPackageScope; data: unknown; onImport: (data: unknown) => void | boolean | Promise<void | boolean>; exportDisabled?: boolean; exportLabel?: string; importLabel?: string }) {
  const apiFetch = useApiFetch();
  const [busy, setBusy] = useState<"export" | "import" | "apply" | null>(null);
  const [pending, setPending] = useState<{ fileName: string; data: unknown; summary: string } | null>(null);
  const [error, setError] = useState("");
  const label = scope === "parameters" ? "Parametreler" : scope === "settings" ? "Ayarlar" : scope === "complete" ? "Parametreler ve Ayarlar" : "Senaryolar";

  useRaviScreenContext(`data-package-${scope}`, { scope, busy, fileName: pending?.fileName, summary: pending?.summary, error });

  async function exportPackage() {
    setBusy("export");
    setError("");
    try {
      const response = await apiFetch("/data-packages/export", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ scope, data }) });
      if (!response.ok) throw new Error(`${label} Excel dosyası hazırlanamadı.`);
      const blob = await response.blob();
      const disposition = response.headers.get("Content-Disposition") ?? "";
      const filename = disposition.match(/filename="([^"]+)"/)?.[1] ?? `Selsa_${label}.xlsx`;
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement("a");
      anchor.href = url;
      anchor.download = filename;
      anchor.click();
      URL.revokeObjectURL(url);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Excel dosyası hazırlanamadı.");
    } finally {
      setBusy(null);
    }
  }

  async function readPackage(file: File) {
    setBusy("import");
    setError("");
    try {
      const form = new FormData();
      form.append("file", file);
      const response = await apiFetch(`/data-packages/${scope}/import`, { method: "POST", body: form });
      const payload = await response.json() as { fileName?: string; data?: unknown; detail?: string };
      if (!response.ok) throw new Error(payload.detail || "Excel veri paketi okunamadı.");
      setPending({ fileName: payload.fileName || file.name, data: payload.data, summary: dataPackageSummary(scope, payload.data) });
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Excel veri paketi okunamadı.");
    } finally {
      setBusy(null);
    }
  }

  async function applyImport() {
    if (!pending) return;
    setBusy("apply");
    setError("");
    try {
      if (await onImport(pending.data) !== false) setPending(null);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Excel verisi uygulanamadı.");
    } finally {
      setBusy(null);
    }
  }

  return <><div className="data-package-actions"><button className="secondary" disabled={Boolean(busy) || exportDisabled} onClick={() => void exportPackage()}><FileXls size={14} /> {busy === "export" ? "Hazırlanıyor…" : exportLabel}</button><label className={`secondary ${busy === "import" ? "loading" : ""}`}><UploadSimple size={14} /> {busy === "import" ? "Okunuyor…" : importLabel}<input type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" disabled={Boolean(busy)} onChange={(event) => { const file = event.target.files?.[0]; if (file) void readPackage(file); event.currentTarget.value = ""; }} /></label>{error && !pending && <span className="data-package-error" role="alert">{error}</span>}</div>{pending && <div className="confirmation-backdrop data-package-backdrop" role="presentation"><section className="operational-dialog data-package-dialog" role="dialog" aria-modal="true" aria-label={`${label} Excel içe aktarma onayı`}><div className="operational-dialog-head"><span className="dialog-icon shift"><FileXls size={20} /></span><div><span>EXCEL İÇE AKTARMA</span><h2>{label} verisini güncelle</h2><p>{pending.fileName}</p></div><button className="delete-button" disabled={busy === "apply"} onClick={() => { setPending(null); setError(""); }} aria-label="Excel içe aktarmayı kapat"><X size={16} /></button></div><div className="data-package-preview"><span>Dosyada bulunan</span><strong>{pending.summary}</strong><p>{scope === "complete" ? "Parametreler ve ayarlar birlikte uygulanır. Siparişler ve çalışan işler korunur. Pasif atamadaki bekleyen işler için karar gerekir. Görünür Excel sayfaları bilgi içindir; içe aktarma dosyanın saklı yedek verisini okur." : scope === "scenarios" ? "Aynı kimliğe sahip senaryolar güncellenir; diğer kayıtlar korunur." : "Bu alandaki mevcut değerler Excel paketindeki yedekle değiştirilecek. Siparişler ve geri bildirimler etkilenmez."}</p>{error && <p className="form-error" role="alert">{error}</p>}</div><div className="drawer-actions"><button className="secondary" disabled={busy === "apply"} onClick={() => { setPending(null); setError(""); }}>Vazgeç</button><button className="primary" disabled={busy === "apply"} onClick={() => void applyImport()}>{busy === "apply" ? "Uygulanıyor…" : "İçe aktar ve uygula"}</button></div></section></div>}</>;
}

