import { factoryDateAfterDays } from "@/lib/factory-time";
import { formatSignedInteger } from "@/lib/number-format";
import { excelSerialToDate } from "@/lib/planning";

export function formatPlanningWeek(week: number, year: number) { return `W${String(week).padStart(2, "0")}.${year}`; }

export function formatHours(value: number | undefined) { return value == null ? "—" : `${new Intl.NumberFormat("tr-TR", { maximumFractionDigits: 1 }).format(value)} sa`; }

export function formatPercent(value: number) { return new Intl.NumberFormat("tr-TR", { style: "percent", minimumFractionDigits: 1, maximumFractionDigits: 1 }).format(value); }

export function signedNumber(value: number) { return formatSignedInteger(value); }

export function serialToInputDate(serial: number) { return serial ? excelSerialToDate(Math.floor(serial)).toISOString().slice(0, 10) : ""; }

export function inputDateToSerial(value: string) { return value ? (Date.parse(`${value}T00:00:00Z`) - Date.UTC(1899, 11, 30)) / 86_400_000 : 0; }

export function dateAfterDays(days: number) { return factoryDateAfterDays(days); }

export function formatInputDate(value: string) { return value ? new Intl.DateTimeFormat("tr-TR", { day: "2-digit", month: "short", year: "numeric" }).format(new Date(`${value}T00:00:00Z`)) : "—"; }

export function formatFactoryDateTime(value: string) { return value && Number.isFinite(Date.parse(value)) ? new Intl.DateTimeFormat("tr-TR", { dateStyle: "medium", timeStyle: "short", timeZone: "Europe/Istanbul" }).format(new Date(value)) : "—"; }

