import { type PlanningSeed, type ShiftCount } from "@/lib/planning";
import { activeProcessResourceIds, type DownstreamProcess, type ProcessResource } from "@/lib/process-master-data";
import type { ProductionHistoryEntry } from "@/lib/planning";

export function actualProcessResources(seed: PlanningSeed, process: DownstreamProcess, product: string): ProcessResource[] {
  const masterProduct = seed.processMasterData?.products.find((item) => item.product.toUpperCase() === product.toUpperCase());
  const parameter = masterProduct?.processes.find((item) => item.process === process);
  if (!parameter) return [];
  return (seed.processMasterData?.resources ?? []).filter((resource) => resource.process === process && activeProcessResourceIds(parameter).includes(resource.id));
}

export function normalizeMachineId(value: string) { const match = value.trim().toUpperCase().match(/^C-?(\d{1,3})$/); return match ? `C-${String(Number(match[1])).padStart(2, "0")}` : ""; }

export function clampShiftCount(value: number | undefined): ShiftCount { return Math.max(0, Math.min(3, Math.trunc(Number(value) || 0))) as ShiftCount; }

export function queuePosition(column: number) { return column >= 13 ? column - 12 : 0; }
export function productionProcessLabel(process: ProductionHistoryEntry["process"]): string {
  return process === "drilling" ? "Delme" : process === "deburring" ? "Çapak alma" : process === "washing" ? "Yıkama" : process === "gkm" ? "GKM" : "Torna";
}

