"use client";

import { useEffect, useLayoutEffect, useRef, useState } from "react";
import type { View } from "../shared/types";

export function usePlanningNavigation(isAdmin: boolean, setNotice: (message: string) => void) {
  const [view, setView] = useState<View>("planning");
  const [entryPoint, setEntryPoint] = useState<{ view: View; source: "url" | "restored-view" | "default" | "access-fallback" } | null>(null);
  const viewRestoredRef = useRef(false);

  useEffect(() => {
    if (!viewRestoredRef.current) {
      viewRestoredRef.current = true;
      const validViews = ["planning", "processes", "control", "orders", "machines", "parameters", "settings", "scenarios", "feedback"];
      const requestedView = new URLSearchParams(window.location.search).get("view") as View | null;
      const storedView = window.localStorage.getItem("selsa-planlama-view") as View | null;
      const requestedTarget = requestedView && validViews.includes(requestedView) ? requestedView : storedView && validViews.includes(storedView) ? storedView as View : null;
      const target = requestedTarget === "settings" && !isAdmin ? "planning" : requestedTarget;
      setEntryPoint({ view: target ?? view, source: requestedTarget === "settings" && !isAdmin ? "access-fallback"
        : requestedView && validViews.includes(requestedView) ? "url"
        : storedView && validViews.includes(storedView) ? "restored-view" : "default" });
      if (target && target !== view) {
        setView(target);
        return;
      }
    }
    window.localStorage.setItem("selsa-planlama-view", view);
    const url = new URL(window.location.href);
    if (url.searchParams.get("view") !== view) {
      url.searchParams.set("view", view);
      window.history.replaceState(null, "", url);
    }
  }, [isAdmin, view]);

  function changeView(next: View) {
    if (next === "settings" && !isAdmin) {
      setNotice("Ayarlar yalnızca yönetici hesapları tarafından değiştirilebilir");
      setView("planning");
      return;
    }
    setView(next);
  }

  useLayoutEffect(() => {
    window.scrollTo(0, 0);
  }, [view]);

  return { view, setView, changeView, entryPoint };
}

