"use client";

import { ArrowLeft, ArrowUp, ArrowUpRight, ClockCounterClockwise, Plus, Trash, X } from "@phosphor-icons/react";
import { useEffect, useRef, useState } from "react";
import { useApiFetch, useCurrentUser } from "@/lib/api";
import { useRaviContext, useRaviScreenContext } from "./context";
import { RavenLogo } from "./RavenLogo";
import { RaviMarkdown } from "./RaviMarkdown";
import { raviHistory, raviTarget, RAVI_TARGETS } from "./protocol";
import { readRaviStream } from "./stream";
import { conversationTitle, MAX_CONVERSATIONS } from "./conversations";
import { useRaviConversations } from "./useRaviConversations";
import "./ravi.css";

type ChatProps = { view: string; onNavigate: (target: string) => void };

export function RaviChat(props: ChatProps) {
  const user = useCurrentUser();
  return <RaviChatSession key={user.id} {...props} />;
}

function RaviChatSession({ view, onNavigate }: ChatProps) {
  const apiFetch = useApiFetch();
  const user = useCurrentUser();
  const readContext = useRaviContext();
  const [open, setOpen] = useState(false);
  const chats = useRaviConversations(user.id);
  const { active, ready, storageError, setDraft } = chats;
  const entries = active?.entries ?? [];
  const draft = active?.draft ?? "";
  const [showHistory, setShowHistory] = useState(false);
  const [busy, setBusy] = useState(false);
  const [partialAnswer, setPartialAnswer] = useState("");
  const [progress, setProgress] = useState("");
  const [error, setError] = useState("");
  const [configured, setConfigured] = useState<boolean | null>(null);
  const [statusError, setStatusError] = useState("");
  const request = useRef<AbortController | null>(null);
  const input = useRef<HTMLTextAreaElement>(null);
  const launcher = useRef<HTMLButtonElement>(null);
  const bottom = useRef<HTMLDivElement>(null);
  useRaviScreenContext("ravi", { open, panel: showHistory ? "conversations" : "chat", activeConversationId: active?.id ?? null, messageCount: entries.length, persistence: "browser", storageAvailable: !storageError });

  useEffect(() => () => { request.current?.abort(); request.current = null; }, []);
  useEffect(() => {
    if (!open) return;
    const controller = new AbortController();
    setStatusError("");
    void apiFetch("/ravi/status", { signal: controller.signal }).then(async (response) => {
      if (!response.ok) throw new Error("Ravi bağlantısı kontrol edilemedi.");
      const data = await response.json();
      if (!controller.signal.aborted) setConfigured(data.configured === true);
    }).catch((reason) => { if (!controller.signal.aborted) setStatusError(reason instanceof Error ? reason.message : "Ravi'ye bağlanılamadı."); });
    input.current?.focus();
    return () => controller.abort();
  }, [open, apiFetch, user.id]);
  useEffect(() => { if (open && !showHistory) bottom.current?.scrollIntoView({ block: "nearest" }); }, [entries, busy, open, showHistory, partialAnswer]);
  useEffect(() => {
    if (!busy || partialAnswer) return;
    const timer = window.setTimeout(() => setProgress("Biraz daha sürüyor, buradayım…"), 12000);
    return () => window.clearTimeout(timer);
  }, [busy, partialAnswer, progress]);
  useEffect(() => { if (open && !showHistory && ready && !busy && configured !== false) input.current?.focus(); }, [open, showHistory, ready, busy, configured, active?.id]);

  function close() { setOpen(false); launcher.current?.focus(); }

  function newConversation() {
    if (busy || !ready) return;
    chats.startConversation(); setShowHistory(false); setError("");
  }

  async function send(text = draft) {
    const message = text.trim();
    if (!message || !ready || request.current || configured === false) return;
    const controller = new AbortController();
    request.current = controller;
    const before = entries;
    const conversationId = active?.id ?? chats.startConversation();
    chats.setEntries(conversationId, [...before, { id: crypto.randomUUID(), role: "user", content: message }]);
    setDraft("", conversationId); setError(""); setBusy(true); setPartialAnswer(""); setProgress("Bir bakalım…");
    const timeout = window.setTimeout(() => controller.abort(), 110000);
    try {
      const context = readContext();
      // Protect the endpoint from unusually large feature-specific context.
      if (JSON.stringify(context.screens).length > 39000) context.screens = { omitted: true, reason: "Ekran ayrıntısı çok büyük; sunucu araçlarını kullan ve tarayıcı değerini tahmin etme." };
      const response = await apiFetch("/ravi/chat/stream", { method: "POST", signal: controller.signal,
        headers: { "Content-Type": "application/json" }, body: JSON.stringify({ message, history: raviHistory(before), context }) });
      const result = await readRaviStream(response, (event) => {
        if (request.current !== controller) return;
        if (event.type === "delta") setPartialAnswer((current) => current + event.text);
        else if (event.type === "answer_reset") setPartialAnswer("");
        else setProgress(event.text);
      });
      if (request.current === controller) chats.setEntries(conversationId, (current) => [...current, { id: crypto.randomUUID(), role: "assistant", content: result.answer, actions: result.actions }]);
    } catch (reason) {
      if (request.current === controller) {
        chats.setEntries(conversationId, before); setDraft(message, conversationId);
        setError(controller.signal.aborted ? "Yanıt bekleme süresi doldu. Mesajınız korunuyor; tekrar gönderebilirsiniz." : reason instanceof Error ? reason.message : "Mesaj gönderilemedi.");
      }
    } finally {
      window.clearTimeout(timeout);
      if (request.current === controller) { request.current = null; setBusy(false); setPartialAnswer(""); setProgress(""); input.current?.focus(); }
    }
  }

  return <div data-ravi-chat="true" className="ravi-root">
    <button ref={launcher} className={`ravi-launcher ${open ? "is-open" : ""}`} onClick={() => setOpen((value) => !value)} aria-expanded={open} aria-controls="ravi-chat" aria-label="Ravi ile konuş"><RavenLogo size={30} thinking={busy} className="ravi-launcher-mark" /><span>Ravi</span></button>
    {open && <section id="ravi-chat" className="ravi-panel" role="dialog" aria-modal="false" aria-label="Ravi planlama asistanı" onKeyDown={(event) => { if (event.key === "Escape") { event.stopPropagation(); close(); } }}>
      <header className="ravi-header"><div className="ravi-avatar"><RavenLogo size={40} thinking={busy} /></div><div><strong>Ravi</strong><span>Planlama asistanınız</span></div><button disabled={busy || !ready} onClick={() => setShowHistory((value) => !value)} title="Konuşmalar" aria-label="Konuşmalar" aria-pressed={showHistory}><ClockCounterClockwise size={18} /></button><button disabled={busy || !ready || (!entries.length && !draft && !showHistory)} onClick={newConversation} title="Yeni konuşma" aria-label="Yeni konuşma"><Plus size={18} /></button><button onClick={close} aria-label="Ravi'yi kapat"><X size={18} /></button></header>
      <div className="ravi-location"><i />{RAVI_TARGETS[view]?.label ?? view}<span>Bu ekranın bağlamıyla yanıtlar</span></div>
      {storageError && <p className="ravi-storage-error ravi-error" role="status">{storageError}</p>}
      {showHistory ? <div className="ravi-history">
        <div className="ravi-history-heading"><h2>Konuşmalar</h2><button onClick={() => setShowHistory(false)} aria-label="Sohbete dön"><ArrowLeft size={16} />Sohbete dön</button></div>
        <p>Bu tarayıcıda saklanır · Son {MAX_CONVERSATIONS} konuşma</p>
        {!chats.conversations.length && <div className="ravi-history-empty">Henüz bir konuşma yok.</div>}
        <ul>{chats.conversations.map((conversation) => <li key={conversation.id} className={conversation.id === active?.id ? "is-active" : ""}>
          <button className="ravi-history-select" aria-current={conversation.id === active?.id ? "true" : undefined} onClick={() => { chats.selectConversation(conversation.id); setShowHistory(false); setError(""); }}>
            <strong>{conversationTitle(conversation)}</strong><small>{new Date(conversation.updatedAt).toLocaleDateString("tr-TR", { day: "numeric", month: "short" })}{conversation.draft.trim() ? " · Taslak" : ""}</small>
          </button>
          <button className="ravi-history-delete" onClick={() => { chats.deleteConversation(conversation.id); setError(""); }} aria-label={`${conversationTitle(conversation)} konuşmasını sil`} title="Konuşmayı sil"><Trash size={16} /></button>
        </li>)}</ul>
      </div> : <>
      <div className="ravi-messages" role="log" aria-label="Ravi konuşması" aria-live="polite" aria-busy={busy}>
        {active?.trimmed && <p className="ravi-history-notice">Bu konuşmanın yalnızca son mesajları saklanıyor.</p>}
        {!entries.length && <div className="ravi-welcome"><RavenLogo size={64} className="ravi-welcome-mark" /><span>Merhaba, ben Ravi.</span><h2>Birlikte bakalım.</h2><p>Aradığınız yeri bulabilir, plandaki sayıların nasıl hesaplandığını açıklayabilirim.</p><div className="ravi-suggestions">{["Teslimat planını nereden indiriyorduk?", "Termin siparişleri nasıl hesaplanıyor?"].map((question) => <button key={question} disabled={!ready || busy || configured === false} onClick={() => void send(question)}>{question}<ArrowUpRight size={15} /></button>)}</div></div>}
        {entries.map((entry) => <article key={entry.id} className={`ravi-message ${entry.role}`}><small>{entry.role === "assistant" ? "Ravi" : "Siz"}</small><div className="ravi-answer">{entry.role === "assistant" ? <RaviMarkdown>{entry.content}</RaviMarkdown> : entry.content}</div>{entry.actions && <>
          <div className="ravi-navigation">{entry.actions.map((action) => { const target = raviTarget(action.id, user.role === "admin"); return target ? <button key={action.id} onClick={() => { onNavigate(action.id); setOpen(false); }}>{target.label}<ArrowUpRight size={14} /></button> : null; })}</div>
        </>}</article>)}
        {busy && partialAnswer && <article className="ravi-message assistant ravi-streaming"><small>Ravi</small><div className="ravi-answer"><RaviMarkdown>{partialAnswer}</RaviMarkdown></div></article>}
        {busy && <div className="ravi-thinking" role="status"><RavenLogo size={28} thinking /><span>{partialAnswer ? "Yazıyorum…" : progress}</span></div>}
        <div ref={bottom} />
      </div>
      <footer className="ravi-composer">
        {configured === false && <p className="ravi-error" role="status">Ravi henüz hazır değil. Yöneticinizin sunucuya DeepSeek anahtarını eklemesi gerekiyor.</p>}
        {(error || statusError) && <p className="ravi-error" role="alert">{error || statusError}</p>}
        <form onSubmit={(event) => { event.preventDefault(); void send(); }}><textarea ref={input} value={draft} maxLength={4000} disabled={!ready || busy || configured === false} onChange={(event) => setDraft(event.target.value)} placeholder="Ravi'ye sorun…" aria-label="Ravi'ye mesaj" rows={2} onKeyDown={(event) => { if (event.key === "Enter" && !event.shiftKey && !event.nativeEvent.isComposing) { event.preventDefault(); void send(); } }} /><button type="submit" disabled={!ready || busy || !draft.trim() || configured === false} aria-label="Mesajı gönder"><ArrowUp size={19} weight="bold" /></button></form>
        <small>Yanıtlar mevcut ekran ve yüklenen verilere dayanır.</small>
      </footer>
      </>}
    </section>}
  </div>;
}

