import { parseRaviResponse, type RaviResponse } from "./protocol";

export type RaviStreamUpdate = { type: "status" | "delta"; text: string } | { type: "answer_reset" };

/** Fetch-based SSE keeps Clerk authorization and POST context; tolerate split UTF-8 and frames. */
export async function readRaviStream(response: Response, onUpdate: (event: RaviStreamUpdate) => void): Promise<RaviResponse> {
  if (!response.ok) {
    const data = await response.json().catch(() => ({}));
    throw new Error(typeof data.detail === "string" ? data.detail : "Mesaj gönderilemedi. Tekrar deneyin.");
  }
  if (!response.headers.get("content-type")?.includes("text/event-stream") || !response.body) throw new Error("Ravi bağlantısı kurulamadı. Tekrar deneyin.");
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "", answerLength = 0, total = 0;
  try {
    while (true) {
      const { done, value } = await reader.read();
      buffer += decoder.decode(value, { stream: !done });
      buffer = buffer.replace(/\r\n/g, "\n");
      if (buffer.length > 100000) throw new Error("Ravi yanıtı çok uzun.");
      let boundary: number;
      while ((boundary = buffer.indexOf("\n\n")) >= 0) {
        const frame = buffer.slice(0, boundary);
        buffer = buffer.slice(boundary + 2);
        const data = frame.split("\n").filter((line) => line.startsWith("data:")).map((line) => line.slice(5).trimStart()).join("\n");
        if (!data) continue;
        total += data.length;
        if (total > 200000) throw new Error("Ravi yanıtı çok uzun.");
        const event = JSON.parse(data);
        if (event.type === "done") return parseRaviResponse(event.response);
        if (event.type === "error") throw new Error(typeof event.message === "string" ? event.message : "Yanıt tamamlanamadı.");
        if (event.type === "answer_reset") { answerLength = 0; onUpdate({ type: "answer_reset" }); }
        else if ((event.type === "delta" || event.type === "status") && typeof event.text === "string") {
          if (event.type === "delta") { answerLength += event.text.length; if (answerLength > 12000) throw new Error("Ravi yanıtı çok uzun."); }
          onUpdate({ type: event.type, text: event.text.slice(0, event.type === "status" ? 200 : 12000) });
        }
      }
      if (done) throw new Error("Yanıt tamamlanmadan bağlantı kesildi. Mesajınız korunuyor; tekrar deneyebilirsiniz.");
    }
  } finally {
    await reader.cancel().catch(() => {});
    reader.releaseLock();
  }
}

frontend/features/ravi/useRaviConversati.source:
"use client";

import { useEffect, useState, type SetStateAction } from "react";
import { conversationStorageKey, emptyConversations, MAX_CONVERSATIONS, parseConversations, updateConversation, type RaviConversations, type RaviEntry } from "./conversations";

/** Mount under a user-ID key so account changes never render another user's history. */
export function useRaviConversations(userId: string) {
  const [store, setStore] = useState<RaviConversations>(emptyConversations);
  const [ready, setReady] = useState(false);
  const [storageError, setStorageError] = useState("");
  const key = conversationStorageKey(userId);
  useEffect(() => {
    try { setStore(parseConversations(window.localStorage.getItem(key))); }
    catch { setStorageError("Kaydedilmiş konuşmalar okunamadı. Bu oturumda sohbet etmeye devam edebilirsiniz."); }
    setReady(true);
  }, [key]);
  useEffect(() => {
    if (!ready) return;
    try { window.localStorage.setItem(key, JSON.stringify(store)); }
    catch { setStorageError("Konuşmalar bu tarayıcıya kaydedilemiyor. Sayfayı kapatırsanız yeni mesajlar kaybolabilir."); }
  }, [key, ready, store]);

  const active = store.conversations.find((conversation) => conversation.id === store.activeId);
  function startConversation() {
    const id = crypto.randomUUID();
    setStore((current) => ({ version: 1, activeId: id, conversations: [
      { id, updatedAt: new Date().toISOString(), entries: [], draft: "" },
      ...current.conversations.filter((item) => item.entries.length || item.draft.trim()),
    ].slice(0, MAX_CONVERSATIONS) }));
    return id;
  }
  function setEntries(id: string, entries: SetStateAction<RaviEntry[]>) {
    setStore((current) => {
      const next = updateConversation(current, id, (conversation) => ({ ...conversation,
        entries: typeof entries === "function" ? entries(conversation.entries) : entries, updatedAt: new Date().toISOString() }));
      return { ...next, conversations: [...next.conversations].sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)) };
    });
  }
  function setDraft(draft: string, conversationId = active?.id) {
    const id = conversationId ?? startConversation();
    setStore((current) => updateConversation(current, id, (conversation) => ({ ...conversation, draft })));
  }
  function selectConversation(id: string) {
    setStore((current) => current.conversations.some((conversation) => conversation.id === id) ? { ...current, activeId: id } : current);
  }
  function deleteConversation(id: string) {
    setStore((current) => {
      const conversations = current.conversations.filter((conversation) => conversation.id !== id);
      return { ...current, conversations, activeId: current.activeId === id ? conversations[0]?.id ?? null : current.activeId };
    });
  }
  return { active, conversations: store.conversations, ready, storageError, startConversation, setEntries, setDraft, selectConversation, deleteConversation };
}

