"use client";

import { UserButton, useAuth } from "@clerk/nextjs";
import { createContext, useCallback, useContext, useEffect, useState, type ReactNode } from "react";

export type ApiFetch = (path: string, init?: RequestInit) => Promise<Response>;
export type AppRole = "admin" | "user";
export type CurrentAppUser = { id: string; name: string; email: string; role: AppRole };
type ApiSession = { apiFetch: ApiFetch; currentUser: CurrentAppUser };

const ApiContext = createContext<ApiSession | null>(null);
const DEFAULT_API_BASE = "http://127.0.0.1:8000/api";
const API_BASE = normalizeApiBase(process.env.NEXT_PUBLIC_API_URL ?? DEFAULT_API_BASE);

export function normalizeApiBase(rawBase: string): string {
  const base = rawBase.replace(/\/$/, "");
  try {
    const url = new URL(base);
    if (url.pathname === "" || url.pathname === "/") url.pathname = "/api";
    return url.toString().replace(/\/$/, "");
  } catch {
    return base === "" || base === "/" ? "/api" : base;
  }
}

function targetUrl(path: string): string {
  if (/^https?:\/\//.test(path)) return path;
  if (path.startsWith("/api/")) return `${API_BASE}${path.slice(4)}`;
  return `${API_BASE}${path.startsWith("/") ? path : `/${path}`}`;
}

export function ClerkApiProvider({ children }: { children: ReactNode }) {
  const { getToken, isLoaded, isSignedIn, signOut } = useAuth();
  const [currentUser, setCurrentUser] = useState<CurrentAppUser | null>(null);
  const [sessionError, setSessionError] = useState("");

  const apiFetch = useCallback<ApiFetch>(async (path, init = {}) => {
    const token = await getToken();
    const headers = new Headers(init.headers);
    if (token) headers.set("Authorization", `Bearer ${token}`);
    const response = await fetch(targetUrl(path), { ...init, headers });
    if (response.status === 401) void signOut({ redirectUrl: "/sign-in" });
    return response;
  }, [getToken, signOut]);

  useEffect(() => {
    if (!isLoaded || !isSignedIn) return;
    let active = true;
    setSessionError("");
    void apiFetch("/me")
      .then(async (response) => {
        if (!response.ok) throw new Error("Kullanıcı yetkileri alınamadı.");
        const user = await response.json() as CurrentAppUser;
        if (active) setCurrentUser(user);
      })
      .catch((reason) => {
        if (active) setSessionError(reason instanceof Error ? reason.message : "Oturum hazırlanamadı.");
      });
    return () => { active = false; };
  }, [apiFetch, isLoaded, isSignedIn]);

  if (!isLoaded || (isSignedIn && !currentUser && !sessionError)) return <div className="auth-screen">Oturum hazırlanıyor…</div>;
  if (sessionError) return <main className="auth-screen"><div><h1>Oturum açılamadı</h1><p>{sessionError}</p><button className="primary" onClick={() => void signOut({ redirectUrl: "/sign-in" })}>Tekrar giriş yap</button></div></main>;
  // Middleware keeps private routes protected. Signed-out visitors still need
  // the public sign-in page to render inside ClerkProvider.
  if (!isSignedIn) return <>{children}</>;
  if (!currentUser) return null;
  return <ApiContext.Provider value={{ apiFetch, currentUser }}>{children}</ApiContext.Provider>;
}

export function useApiFetch(): ApiFetch {
  const value = useContext(ApiContext);
  if (!value) throw new Error("API provider bulunamadı");
  return value.apiFetch;
}

export function useCurrentUser(): CurrentAppUser {
  const value = useContext(ApiContext);
  if (!value) throw new Error("Kullanıcı oturumu bulunamadı");
  return value.currentUser;
}

export function AuthAvatar() {
  const currentUser = useCurrentUser();
  return <span className="account-control"><span className="account-copy"><strong>{currentUser.name}</strong><small>{currentUser.role === "admin" ? "Yönetici" : "Kullanıcı"}</small></span><UserButton showName={false} /></span>;
}

