export type AppUpdate = {
  id: string;
  title: string;
  bullets: string[];
  created_at: string;
  seen_at: string | null;
};

export function normalizeUpdateBullets(value: string): string[] {
  return value
    .split(/\r?\n/)
    .map((line) => line.replace(/^\s*(?:[-*•]|\d+[.)])\s*/, "").trim())
    .filter(Boolean);
}

export function unreadUpdateCount(updates: AppUpdate[]): number {
  return updates.filter((update) => !update.seen_at).length;
}

export function visibleAppUpdates(updates: AppUpdate[], hideSeen: boolean): AppUpdate[] {
  return hideSeen ? updates.filter((update) => !update.seen_at) : updates;
}

frontend/lib/archive-corrections.ts.source:
import { factoryDateTimeInput, factoryDateTimeToIso, factoryNowSerial } from "./factory-time";
import { type PlanningSeed, type ProductionHistoryEntry, type ScenarioResult, type WipLot, updateProductionHistoryEntry } from "./planning";
import { productionHistoryLots } from "./production-archive";
import { updateProcessCurrentJob } from "./process-planning";
import { deliverWipQuantity, syncWipWithHistoryEdit, wipOperationReadyAt } from "./wip-ledger";

export function archiveEntrySignature(entry: ProductionHistoryEntry): string { return JSON.stringify(entry); }
export function assertArchiveEntry(seed: PlanningSeed, entryId: string, expected?: string) {
  const entry = seed.productionHistory?.find(item => item.id === entryId);
  if (!entry || (expected && archiveEntrySignature(entry) !== expected)) throw new Error("Arşiv kaydı değişti. Güncel bilgileri yeniden açın.");
  return entry;
}

/** Pin legacy shipment balances before changing them, without guessing missing process dates. */
function shipmentAllocations(seed: PlanningSeed, entry: ProductionHistoryEntry) {
  if (entry.wipAllocations) {
    if (entry.wipAllocations.reduce((sum, item) => sum + item.quantity, 0) !== entry.completedQuantity) throw new Error("Teslimat ile şarj bakiyesi eşleşmiyor.");
    for (const item of entry.wipAllocations) if (!(item.quantity > 0) || (seed.wipLots?.find(lot => lot.id === item.lotId)?.deliveredQuantity ?? 0) < item.quantity) throw new Error("Teslim edilen şarj bakiyesi yetersiz.");
    return structuredClone(entry.wipAllocations);
  }
  let remaining = entry.completedQuantity;
  const allocations: Array<{ lotId: string; quantity: number }> = [];
  for (const lot of productionHistoryLots(seed, entry)) {
    const reserved = (seed.productionHistory ?? []).filter(other => other.id !== entry.id && other.inventoryStatus === "delivered").flatMap(other => other.wipAllocations ?? []).filter(item => item.lotId === lot.id).reduce((sum, item) => sum + item.quantity, 0);
    const quantity = Math.min(remaining, Math.max(0, lot.deliveredQuantity - reserved));
    if (quantity) allocations.push({ lotId: lot.id, quantity });
    remaining -= quantity;
  }
  if (remaining) throw new Error("Bu eski teslimatın doğrulanmış şarj bakiyesi bulunamadı. Arşiv ve yarı mamül eşleşmesini kontrol edin.");
  return allocations;
}
function clearDelivery(entry: ProductionHistoryEntry) {
  entry.inventoryStatus = "semi-finished";
  delete entry.deliveredAt; delete entry.deliveredAtTime; delete entry.wipAllocations;
  entry.statusChangedAt = new Date().toISOString();
}
function restorePieces(seed: PlanningSeed, allocations: Array<{ lotId: string; quantity: number }>, quantity: number, restoredEntry: ProductionHistoryEntry, reason: string) {
  let left = quantity;
  const recordedAt = new Date().toISOString();
  const now = factoryNowSerial(recordedAt);
  for (const allocation of allocations) {
    const amount = Math.min(left, allocation.quantity);
    if (!amount) continue;
    const lot = seed.wipLots!.find(item => item.id === allocation.lotId)!;
    lot.deliveredQuantity -= amount;
    lot.originalQuantity -= amount;
    lot.updatedAt = recordedAt;
    allocation.quantity -= amount;
    const restored: WipLot = { ...structuredClone(lot), id: `restored-${crypto.randomUUID()}`, sourceHistoryEntryId: restoredEntry.id, parentLotId: lot.id,
      originalQuantity: amount, availableQuantity: amount, deliveredQuantity: 0, scrappedQuantity: 0,
      stage: "delivery-ready", nextProcess: undefined, readyAt: now, rolledForwardAt: undefined, rolledForwardFrom: undefined,
      createdAt: recordedAt, updatedAt: recordedAt };
    seed.wipLots!.push(restored);
    seed.wipMovements = [...(seed.wipMovements ?? []), { id: `restore-${crypto.randomUUID()}`, lotId: restored.id, kind: "restored", quantity: amount, fromStage: "delivered", toStage: "delivery-ready", occurredAt: now, recordedAt, note: reason }];
    left -= amount;
  }
  if (left) throw new Error("Geri alınacak teslimat bakiyesi yetersiz.");
}
export function restoreArchiveDelivery(seed: PlanningSeed, result: ScenarioResult, entryId: string, reason: string, expected?: string) {
  assertArchiveEntry(seed, entryId, expected);
  if (!reason.trim()) throw new Error("Geri alma nedenini yazın.");
  const next = structuredClone(seed);
  const entry = assertArchiveEntry(next, entryId);
  if (entry.inventoryStatus !== "delivered") throw new Error("Yalnızca teslim edilmiş kayıt geri alınabilir.");
  const allocations = shipmentAllocations(next, entry);
  restorePieces(next, allocations, entry.completedQuantity, entry, reason.trim());
  clearDelivery(entry);
  entry.statusChangeReason = reason.trim();
  next.lastAutomaticPlan = undefined; next.planRunSequence = undefined;
  return { seed: next, result };
}

export function correctArchiveRecord(seed: PlanningSeed, result: ScenarioResult, entryId: string, quantity: number, completedAt: number, deliveryDate?: string, expected?: string, correctionLotId?: string) {
  const source = assertArchiveEntry(seed, entryId, expected);
  const sameDay = Math.floor(completedAt) === Math.floor(source.completedAt);
  const actualAt = sameDay ? source.completedAt : completedAt;
  if (source.inventoryStatus === "delivered" && !sameDay) throw new Error("Teslim edilmiş şarjın Torna tarihi değiştirilemez; teslim adedi ve tarihi düzeltilebilir.");
  // A timestamp correction changes no pieces and must not require reconstructing
  // legacy shipment allocations or rescheduling the recorded production queue.
  const dateOnly = source.inventoryStatus === "delivered" && quantity === source.completedQuantity;
  if (dateOnly && (!Number.isInteger(quantity) || quantity <= 0 || !Number.isFinite(actualAt))) throw new Error("Arşiv kaydının adedi ve tamamlanma tarihi geçerli olmalıdır.");
  const copied = dateOnly ? structuredClone(seed) : undefined;
  const next = copied
    ? { seed: copied, result, entry: copied.productionHistory!.find(item => item.id === entryId)! }
    : updateProductionHistoryEntry(seed, result, entryId, quantity, actualAt);
  if (source.inventoryStatus === "delivered") {
    const deliveryIso = deliveryDate ? factoryDateTimeToIso(deliveryDate) : source.deliveredAtTime || factoryDateTimeToIso(`${source.deliveredAt}T00:00`);
    const deliveryAt = deliveryIso ? factoryNowSerial(deliveryIso) : Number.NaN;
    if (!deliveryIso || !Number.isFinite(deliveryAt) || (deliveryDate && factoryDateTimeInput(deliveryIso) !== deliveryDate)) throw new Error("Geçerli bir teslim tarihi ve saati seçin.");
    if (Date.parse(deliveryIso) > Date.now()) throw new Error("Teslim tarihi ve saati şu andan sonra olamaz.");
    if (deliveryAt < actualAt || productionHistoryLots(seed, source).some(lot => lot.completedSteps.some(step => step.end > deliveryAt))) throw new Error("Teslim tarihi tamamlanan proseslerden önce olamaz.");
    const difference = quantity - source.completedQuantity;
    const allocations = dateOnly ? undefined : shipmentAllocations(next.seed, source);
    if (difference < 0) {
      const returned: ProductionHistoryEntry = { ...source, id: `return-${crypto.randomUUID()}`, originalQuantity: -difference, completedQuantity: -difference, sourceEntryId: source.id };
      clearDelivery(returned);
      restorePieces(next.seed, allocations!, -difference, returned, "Teslim edilen adet düzeltildi; fark Paketleme / Final Kontrol’e alındı.");
      next.seed.productionHistory!.push(returned);
    } else if (difference > 0) {
      // Only consume open records in this shipment's history lineage, never an unrelated work order.
      const ids = new Set([source.id, source.sourceEntryId].filter(Boolean));
      let changed = true;
      while (changed) { changed = false; for (const entry of next.seed.productionHistory ?? []) if (entry.sourceEntryId && ids.has(entry.sourceEntryId) && !ids.has(entry.id)) { ids.add(entry.id); changed = true; } }
      const lots = (next.seed.wipLots ?? []).filter(lot => ids.has(lot.sourceHistoryEntryId) && lot.product === source.product && lot.workOrder === source.workOrder && lot.availableQuantity > 0 && lot.stage === "delivery-ready" && wipOperationReadyAt(lot) <= deliveryAt);
      if (lots.reduce((sum, lot) => sum + lot.availableQuantity, 0) < difference) throw new Error("Artış için seçilen tarihte yeterli teslimata hazır miktar yok. Bekleyen şarjı Teslimatı tamamla ile onaylayın.");
      let left = difference;
      for (const lot of lots) {
        const amount = Math.min(left, lot.availableQuantity);
        const history = next.seed.productionHistory!.find(entry => entry.id === lot.sourceHistoryEntryId && entry.inventoryStatus === "semi-finished");
        if (!history || history.completedQuantity < amount) throw new Error("Açık arşiv bakiyesi eşleşmiyor.");
        deliverWipQuantity(next.seed, lot.id, amount, deliveryAt, new Date().toISOString());
        const existing = allocations!.find(item => item.lotId === lot.id);
        if (existing) existing.quantity += amount; else allocations!.push({ lotId: lot.id, quantity: amount });
        history.completedQuantity -= amount; history.originalQuantity = history.completedQuantity;
        if (!history.completedQuantity) history.inventoryStatus = "voided";
        left -= amount;
        if (!left) break;
      }
    }
    if (allocations) {
      next.entry.wipAllocations = allocations.filter(item => item.quantity > 0);
      next.entry.originalQuantity = quantity;
    }
    next.entry.deliveredAt = deliveryDate?.slice(0, 10) || source.deliveredAt;
    next.entry.deliveredAtTime = deliveryIso;
    next.entry.statusChangedAt = new Date().toISOString();
    next.entry.statusChangeReason = `Teslimat düzeltmesi: ${source.completedQuantity} → ${quantity} adet; ${source.deliveredAtTime || source.deliveredAt} → ${deliveryIso}`;
  } else {
    syncWipWithHistoryEdit(next.seed, source, quantity, actualAt, undefined, correctionLotId);
    const delta = quantity - source.completedQuantity;
    if (delta) {
      const ids = new Set(productionHistoryLots(next.seed, next.entry).filter(lot => lot.availableQuantity > 0 && lot.availableQuantity !== seed.wipLots?.find(item => item.id === lot.id)?.availableQuantity).map(lot => lot.id));
      for (const job of next.seed.processCurrentJobs ?? []) if (ids.has(job.wipLotId)) updateProcessCurrentJob(next.seed, job.resourceId, { originalQuantity: job.originalQuantity + delta, remainingQuantity: job.remainingQuantity + delta, remainingAsOf: job.remainingAsOf ?? job.start });
    }
  }
  next.seed.lastAutomaticPlan = undefined; next.seed.planRunSequence = undefined;
  next.seed.planNeedsRecalculation = true;
  return next;
}

