import { buildDeliveryReadinessEvents } from "./delivery-readiness";
import type { DeliveryReadinessEvent } from "./delivery-readiness";
import {
  orderProductionBreakdown,
  type AutomaticPlanSnapshot,
  type Order,
  type PlanningSeed,
  type ScenarioResult,
} from "./planning";

export type PlanOutcomeMetrics = {
  demand: number;
  readyByDue: number;
  shortage: number;
  lateQuantity: number;
  firstReadyAt: number | null;
  lastReadyAt: number | null;
  dueDeltaDays: number | null;
  planCompletion: number | null;
  setupHours: number;
};

export type OrderPlanOutcome = {
  orderId: string;
  product: string;
  dueDate: string;
  quantity: number;
  automatic: PlanOutcomeMetrics;
  manual: PlanOutcomeMetrics;
  changed: boolean;
};

export type AutomaticPlanComparison = {
  automatic: PlanOutcomeMetrics;
  manual: PlanOutcomeMetrics;
  orders: OrderPlanOutcome[];
  changedOrderCount: number;
};

type ReadyEvent = { quantity: number; readyAt: number };

function clone<T>(value: T): T {
  return JSON.parse(JSON.stringify(value)) as T;
}

function inputDateSerial(value: string): number {
  return value
    ? (Date.parse(`${value}T00:00:00Z`) - Date.UTC(1899, 11, 30)) / 86_400_000
    : 0;
}

function readyTimeline(seed: PlanningSeed, readinessEvents: DeliveryReadinessEvent[], product: string): { openingQuantity: number; events: ReadyEvent[] } {
  const code = product.trim().toUpperCase();
  const openingQuantity = seed.customerDemand ? 0 : Math.max(0, seed.openingStock?.[code] ?? 0);
  const events: ReadyEvent[] = readinessEvents
    .filter((event) => event.product === code)
    .map((event) => ({ quantity: event.quantity, readyAt: event.readyAt }));
  return { openingQuantity, events };
}

function orderMetrics(seed: PlanningSeed, result: ScenarioResult, order: Order, readinessEvents: DeliveryReadinessEvent[]): PlanOutcomeMetrics {
  const breakdown = orderProductionBreakdown(seed, result.batches, order);
  const eventualReady = Math.max(0, breakdown.existingProduction + breakdown.newlyPlanned);
  const timeline = readyTimeline(seed, readinessEvents, order.product);
  const dueSerial = inputDateSerial(order.dueDate);
  const routedReadyByDue = dueSerial
    ? timeline.openingQuantity + timeline.events.filter((event) => Math.floor(event.readyAt) <= Math.floor(dueSerial)).reduce((sum, event) => sum + event.quantity, 0)
    : eventualReady;
  const readyByDue = Math.min(order.quantity, Math.max(0, routedReadyByDue));
  const coveredQuantity = Math.min(order.quantity, eventualReady);
  const shortage = Math.max(0, order.quantity - eventualReady);
  const lateQuantity = Math.max(0, coveredQuantity - readyByDue);
  const firstReadyAt = timeline.events[0]?.readyAt ?? null;
  const lastReadyAt = timeline.events.at(-1)?.readyAt ?? null;
  let cumulative = timeline.openingQuantity;
  let fullyReadyAt: number | null = null;
  for (const event of timeline.events) {
    cumulative += event.quantity;
    if (cumulative >= order.quantity) {
      fullyReadyAt = event.readyAt;
      break;
    }
  }
  const dueDeltaDays = shortage === 0 && fullyReadyAt !== null && dueSerial
    ? Math.floor(fullyReadyAt) - Math.floor(dueSerial)
    : null;
  return {
    demand: order.quantity,
    readyByDue,
    shortage,
    lateQuantity,
    firstReadyAt,
    lastReadyAt,
    dueDeltaDays,
    planCompletion: result.summary.completion || null,
    setupHours: result.summary.totalSetupHours ?? 0,
  };
}

function aggregateMetrics(result: ScenarioResult, orders: PlanOutcomeMetrics[]): PlanOutcomeMetrics {
  const firstDates = orders.map((order) => order.firstReadyAt).filter((value): value is number => value !== null);
  const lastDates = orders.map((order) => order.lastReadyAt).filter((value): value is number => value !== null);
  const dueDeltas = orders.map((order) => order.dueDeltaDays).filter((value): value is number => value !== null);
  return {
    demand: orders.reduce((sum, order) => sum + order.demand, 0),
    readyByDue: orders.reduce((sum, order) => sum + order.readyByDue, 0),
    shortage: orders.reduce((sum, order) => sum + order.shortage, 0),
    lateQuantity: orders.reduce((sum, order) => sum + order.lateQuantity, 0),
    firstReadyAt: firstDates.length ? Math.min(...firstDates) : null,
    lastReadyAt: lastDates.length ? Math.max(...lastDates) : null,
    dueDeltaDays: dueDeltas.length ? Math.max(...dueDeltas) : null,
    planCompletion: result.summary.completion || null,
    setupHours: result.summary.totalSetupHours ?? 0,
  };
}

function numberChanged(left: number | null, right: number | null): boolean {
  if (left === null || right === null) return left !== right;
  return Math.abs(left - right) > 0.000001;
}

function metricsChanged(left: PlanOutcomeMetrics, right: PlanOutcomeMetrics): boolean {
  return numberChanged(left.readyByDue, right.readyByDue)
    || numberChanged(left.shortage, right.shortage)
    || numberChanged(left.lateQuantity, right.lateQuantity)
    || numberChanged(left.firstReadyAt, right.firstReadyAt)
    || numberChanged(left.lastReadyAt, right.lastReadyAt)
    || numberChanged(left.dueDeltaDays, right.dueDeltaDays);
}

function comparableBatchSignature(result: ScenarioResult): string[] {
  return result.batches.map((batch) => [
    batch.id,
    batch.status,
    batch.product.trim().toUpperCase(),
    batch.machineId,
    batch.quantity,
    batch.planColumn,
    Math.round(batch.start * 1_000_000),
    Math.round(batch.end * 1_000_000),
    Math.round((batch.setupHours ?? 0) * 1_000_000),
  ].join("|")).sort();
}

export function createAutomaticPlanSnapshot(result: ScenarioResult): AutomaticPlanSnapshot {
  return { createdAt: result.createdAt, result: clone(result) };
}

export function hasManualPlanChanges(snapshot: AutomaticPlanSnapshot | undefined, current: ScenarioResult): boolean {
  if (!snapshot || snapshot.result.state !== "planned" || current.state !== "planned") return false;
  const automatic = comparableBatchSignature(snapshot.result);
  const manual = comparableBatchSignature(current);
  return automatic.length !== manual.length || automatic.some((signature, index) => signature !== manual[index]);
}

export function compareWithAutomaticPlan(seed: PlanningSeed, snapshot: AutomaticPlanSnapshot, manualResult: ScenarioResult): AutomaticPlanComparison {
  const automaticResult = snapshot.result;
  const automaticReadiness = buildDeliveryReadinessEvents(seed, automaticResult);
  const manualReadiness = buildDeliveryReadinessEvents(seed, manualResult);
  const orders = seed.orders.map((order) => {
    const automatic = orderMetrics(seed, automaticResult, order, automaticReadiness);
    const manual = orderMetrics(seed, manualResult, order, manualReadiness);
    return {
      orderId: order.id,
      product: order.product,
      dueDate: order.dueDate,
      quantity: order.quantity,
      automatic,
      manual,
      changed: metricsChanged(automatic, manual),
    };
  }).sort((left, right) => Number(right.changed) - Number(left.changed)
    || left.dueDate.localeCompare(right.dueDate)
    || left.product.localeCompare(right.product));
  return {
    automatic: aggregateMetrics(automaticResult, orders.map((order) => order.automatic)),
    manual: aggregateMetrics(manualResult, orders.map((order) => order.manual)),
    orders,
    changedOrderCount: orders.filter((order) => order.changed).length,
  };
}

export function automaticPlanResult(snapshot: AutomaticPlanSnapshot): ScenarioResult {
  return clone(snapshot.result);
}

frontend/lib/calendar-event-status.ts.source:
import type { MachineCalendarEvent } from "./planning";

export type CalendarEventStatus = {
  status: "active" | "completed";
  automaticallyCompleted: boolean;
};

export function calendarEventStatus(event: MachineCalendarEvent, todaySerial: number): CalendarEventStatus {
  const automaticallyCompleted = event.kind === "shift"
    && !event.completedAt
    && Math.floor(event.end) < Math.floor(todaySerial);
  return {
    status: event.completedAt || automaticallyCompleted ? "completed" : "active",
    automaticallyCompleted,
  };
}

