import type { ChargeJourneyNote, ChargeJourneyReason, PlanningSeed } from "./planning";

export type ChargeJourneyNoteInput = Omit<ChargeJourneyNote, "id" | "updatedAt">;

export const CHARGE_JOURNEY_REASONS: { value: ChargeJourneyReason; label: string }[] = [
  { value: "machine-breakdown", label: "Makine arızası" },
  { value: "tooling", label: "Takım problemi" },
  { value: "raw-material", label: "Hammadde gecikmesi" },
  { value: "quality", label: "Kalite problemi" },
  { value: "staffing", label: "Personel eksikliği" },
  { value: "setup-overrun", label: "Setup uzaması" },
  { value: "cycle-time", label: "Çevrim süresi sapması" },
  { value: "previous-operation", label: "Önceki operasyon gecikmesi" },
  { value: "external-process", label: "Dış proses gecikmesi" },
  { value: "unplanned-priority", label: "Plansız öncelikli iş" },
  { value: "other", label: "Diğer" },
];

export function chargeJourneyReasonLabel(reason: ChargeJourneyReason): string {
  return CHARGE_JOURNEY_REASONS.find((item) => item.value === reason)?.label ?? "Diğer";
}

function noteId(input: Pick<ChargeJourneyNoteInput, "chargeKey" | "segmentId">): string {
  const safeCharge = input.chargeKey.trim().replace(/[^a-zA-Z0-9_-]+/g, "-");
  const safeSegment = input.segmentId.trim().replace(/[^a-zA-Z0-9_-]+/g, "-");
  return `journey-note-${safeCharge}-${safeSegment}`;
}

/**
 * A listed reason stores its label as the note; "other" (and legacy notes without a
 * reason) keeps the planner's free text. No reason and no text clears the segment.
 */
export function saveChargeJourneyNote(seed: PlanningSeed, input: ChargeJourneyNoteInput, updatedAt = new Date().toISOString()): ChargeJourneyNote | undefined {
  const chargeKey = input.chargeKey.trim();
  const segmentId = input.segmentId.trim();
  if (!chargeKey || !segmentId) throw new Error("Açıklamanın bağlı olduğu şarj veya zaman aralığı bulunamadı.");
  if (!Number.isFinite(input.start) || !Number.isFinite(input.end) || input.end < input.start) throw new Error("Açıklama tarih aralığı geçersiz.");
  const notes = seed.chargeJourneyNotes ?? [];
  const retained = notes.filter((note) => !(note.chargeKey === chargeKey && note.segmentId === segmentId));
  const listed = input.reason && input.reason !== "other" ? input.reason : undefined;
  const note = listed ? chargeJourneyReasonLabel(listed) : input.note.trim();
  if (!note) {
    if (input.reason === "other") throw new Error("Diğer seçildiğinde açıklama yazılmalıdır.");
    seed.chargeJourneyNotes = retained;
    return undefined;
  }
  const saved: ChargeJourneyNote = {
    ...input,
    id: notes.find((item) => item.chargeKey === chargeKey && item.segmentId === segmentId)?.id ?? noteId({ chargeKey, segmentId }),
    chargeKey,
    segmentId,
    reason: listed ?? (input.reason ? "other" : undefined),
    note,
    updatedAt,
  };
  if (!saved.reason) delete saved.reason;
  seed.chargeJourneyNotes = [...retained, saved];
  return saved;
}

