import { isProductionInterruption, type ProductionInterruption } from "./production-interruptions";
import { productionHistoryLots } from "./production-archive";
import { effectiveDeliveryTimestamp } from "./delivery-deduction";
import { factoryNowSerial } from "./factory-time";
import type { PlanningSeed, WipStage, WipLot } from "./planning";
import { processMasterDataForProduct, type DownstreamProcess } from "./process-master-data";
import { actualWipOperations, type ProcessOperation, type RoutedProcessJob } from "./process-planning";

export type ChargeJourneyStatusTone = "planned" | "waiting" | "running" | "finishing" | "delivered" | "attention";

export type ChargeJourneyStatus = {
  label: string;
  tone: ChargeJourneyStatusTone;
};

type ChargeJourneyStatusInput = {
  source: RoutedProcessJob["source"];
  stage?: WipStage;
  nextProcess?: DownstreamProcess;
  currentProcess?: DownstreamProcess;
};

const waitingStatus: Record<DownstreamProcess, ChargeJourneyStatus> = {
  drilling: { label: "Delme Bekliyor.", tone: "waiting" },
  deburring: { label: "Çapak Alma Bekliyor.", tone: "waiting" },
  gkm: { label: "GKM Bekliyor.", tone: "waiting" },
};

const runningStatus: Record<DownstreamProcess, ChargeJourneyStatus> = {
  drilling: { label: "Delme'de Üretiliyor.", tone: "running" },
  deburring: { label: "Çapak Alma'da Üretiliyor.", tone: "running" },
  gkm: { label: "GKM'de kontrol ediliyor.", tone: "running" },
};

/** Returns the shop-floor status shown at the right edge of a charge journey row. */
export function chargeJourneyStatus(input: ChargeJourneyStatusInput): ChargeJourneyStatus {
  if (input.source === "turning-plan") return { label: "Torna Planında", tone: "planned" };
  if (input.source === "current-turning") return { label: "Torna'da Üretiliyor.", tone: "running" };
  if (input.stage === "delivered") return { label: "SEVK EDİLDİ", tone: "delivered" };
  if (input.stage === "delivery-ready") return { label: "Paketleme & Final Kontrol yapılıyor.", tone: "finishing" };
  if (input.currentProcess) return runningStatus[input.currentProcess];
  if (input.stage === "on-hold") return { label: "Blokeli", tone: "attention" };
  if (input.stage === "unclassified") return { label: "Konumu Doğrulanmalı", tone: "attention" };

  const stageProcess = ({
    "quality-hold": "drilling",
    "drilling-queue": "drilling",
    "deburring-queue": "deburring",
    "washing-buffer": "gkm",
    "gkm-buffer": "gkm",
    "gkm-queue": "gkm",
  } as Partial<Record<WipStage, DownstreamProcess>>)[input.stage ?? "unclassified"];
  const process = stageProcess ?? input.nextProcess;
  return process ? waitingStatus[process] : { label: "Konumu Doğrulanmalı", tone: "attention" };
}

export function chargeJourneyInterruptions(job: RoutedProcessJob, seed: PlanningSeed): ProductionInterruption[] {
  const lot = seed.wipLots?.find(item => item.id === job.wipLotId);
  const chargeId = job.source === 'current-turning' ? seed.machines.find(machine => machine.id === job.turningMachineId)?.currentJob.batchId : job.batchId;
  return (seed.productionInterruptions ?? []).filter(item => item.producedQuantity !== 0 && (item.chargeId === chargeId || lot?.interruptionIds?.includes(item.id)));
}

/** A paused Torna charge whose remainder is again some machine's current job is no longer paused, only split. */
export function interruptionsResumedOnTurning(open: ProductionInterruption[], seed: PlanningSeed): boolean {
  return open.every(item => item.process === "turning"
    && seed.machines.some(machine => machine.currentJob.batchId === item.chargeId && machine.currentJob.quantity > 0));
}

export function chargeJourneyStatusForJob(job: RoutedProcessJob, seed: PlanningSeed): ChargeJourneyStatus {
  if (job.archivedDelivery) return { label: "SEVK EDİLDİ", tone: "delivered" };
  const lot = (seed.wipLots ?? []).find((item) => item.id === (job.wipLotId ?? job.batchId));
  const currentProcess = (seed.processCurrentJobs ?? []).find((item) => item.wipLotId === lot?.id)?.process
    ?? job.operations.find((operation) => operation.current && operation.process !== "turning")?.process as DownstreamProcess | undefined;
  const open = chargeJourneyInterruptions(job, seed).filter(item => isProductionInterruption(item) && !item.completedAt);
  if (!currentProcess && job.source !== "current-turning" && open.length) return interruptionsResumedOnTurning(open, seed)
    ? { label: "Kalanı Torna'da Üretiliyor.", tone: "waiting" }
    : { label: "Üretime ara verildi.", tone: "attention" };
  return chargeJourneyStatus({ source: job.source, stage: lot?.stage, nextProcess: lot?.nextProcess, currentProcess });
}

/** Open the real current step rather than a projected downstream operation. */
export function defaultJourneyOperation(job: RoutedProcessJob, seed: PlanningSeed): ProcessOperation | undefined {
  if (job.source === "current-turning" || job.source === "turning-plan") return job.operations.find((operation) => operation.process === "turning") ?? job.operations[0];
  const lot = seed.wipLots?.find((item) => item.id === job.wipLotId);
  return job.operations.find((operation) => operation.current)
    ?? job.operations.find((operation) => !operation.actual && operation.process === lot?.nextProcess)
    ?? job.operations.at(-1);
}

export function journeyCurrentProcess(job: RoutedProcessJob, seed: PlanningSeed): string {
  if (job.archivedDelivery) return "delivery";
  if (job.source !== "wip") return "turning";
  const lot = seed.wipLots?.find((item) => item.id === job.wipLotId);
  if (lot?.stage === "delivery-ready") return "delivery";
  if (lot?.stage === "on-hold" || lot?.stage === "unclassified") return "attention";
  return seed.processCurrentJobs?.find((item) => item.wipLotId === lot?.id)?.process
    ?? lot?.nextProcess ?? "attention";
}

export function journeyVisibleQuantity(job: RoutedProcessJob, seed: PlanningSeed): number {
  if (job.archivedDelivery) return job.quantity;
  if (job.source === "wip") return seed.wipLots?.find((lot) => lot.id === job.wipLotId)?.availableQuantity ?? job.quantity;
  if (job.source === "current-turning") {
    const current = seed.machines.find((machine) => machine.id === job.turningMachineId)?.currentJob;
    return current?.remainingQuantity ?? current?.quantity ?? job.quantity;
  }
  return job.quantity;
}

/** Archive projections carry their displayed shipment date in deliveryReadyAt. */
export function compareChargeJourneyJobs(left: RoutedProcessJob, right: RoutedProcessJob, mode: "active" | "archive"): number {
  const dateOrder = mode === "archive"
    ? right.deliveryReadyAt - left.deliveryReadyAt
    : (left.operations[0]?.start ?? 0) - (right.operations[0]?.start ?? 0);
  return dateOrder || left.batchId.localeCompare(right.batchId);
}

/** Completed work can only be compared against a recorded plan. */
export function plannedJourneyRange(operation: ProcessOperation): { start: number; end: number } | null {
  if (operation.actual && (operation.plannedStart == null || operation.plannedEnd == null)) return null;
  return { start: operation.plannedStart ?? operation.start, end: operation.plannedEnd ?? operation.end };
}

/** The overview follows the remaining schedule; completed-step baselines belong in the comparison rows. */
export function remainingJourneyRange(operation: ProcessOperation): { start: number; end: number } | null {
  return operation.actual ? null : { start: operation.start, end: operation.end };
}

/** Keeps completed, shipped charges searchable in the journey without feeding them back into capacity planning. */
export function deliveredChargeJourneyJobs(seed: PlanningSeed): RoutedProcessJob[] {
  const jobs: RoutedProcessJob[] = (seed.wipLots ?? [])
    .filter((lot) => lot.deliveredQuantity > 0)
    .map((lot) => {
      const operations = actualWipOperations(lot, processMasterDataForProduct(seed.processMasterData, lot.product))
        .sort((left, right) => left.sequence - right.sequence || left.start - right.start);
      const historyDates = (seed.productionHistory ?? []).filter(entry => entry.inventoryStatus === "delivered" && productionHistoryLots(seed, entry).some(item => item.id === lot.id))
        .map(entry => effectiveDeliveryTimestamp(entry)).filter((date): date is string => Boolean(date)).map(date => factoryNowSerial(date)).filter(Number.isFinite);
      const deliveredAt = historyDates.length ? Math.max(...historyDates) : (seed.wipMovements ?? [])
        .filter((movement) => movement.lotId === lot.id && movement.kind === "delivered")
        .reduce((latest, movement) => Math.max(latest, movement.occurredAt), 0);
      const completion = Math.max(0, ...operations.map((operation) => operation.end));
      return {
        archivedDelivery: true,
        historyIncomplete: !lot.completedSteps.length,
        batchId: lot.stage === "delivered" ? lot.id : `delivered:${lot.id}`,
        source: "wip" as const,
        workOrder: lot.workOrder,
        wipLotId: lot.id,
        product: lot.product,
        family: lot.family,
        quantity: lot.deliveredQuantity,
        turningMachineId: operations.find((operation) => operation.process === "turning")?.resourceId ?? "",
        operations,
        completion,
        deliveryReadyAt: deliveredAt || Math.max(lot.readyAt, completion),
      };
    });
  const seen = new Set<string>();
  for (const entry of seed.productionHistory ?? []) {
    if (entry.inventoryStatus !== "delivered" || entry.completedQuantity <= 0 || seen.has(entry.id)) continue;
    seen.add(entry.id);
    if (productionHistoryLots(seed, entry).some(lot => lot.deliveredQuantity > 0)) continue;
    const batchId = `history:${entry.id}`;
    // Legacy entries can prove their recorded operation, not the missing downstream route.
    const lot = { id: batchId, product: entry.product, workOrder: entry.workOrder, family: processMasterDataForProduct(seed.processMasterData, entry.product)?.family ?? "piston",
      completedSteps: entry.start > 0 && entry.completedAt >= entry.start ? [{ process: entry.process,
        resourceId: entry.machineId, resourceName: entry.machineName, start: entry.start, end: entry.completedAt,
        quantity: entry.completedQuantity, recordedAt: entry.archivedAt }] : [] } as unknown as WipLot;
    const operations = actualWipOperations(lot, processMasterDataForProduct(seed.processMasterData, entry.product));
    const date = effectiveDeliveryTimestamp(entry) || entry.archivedAt;
    const serial = date && Number.isFinite(Date.parse(date)) ? factoryNowSerial(date) : 0;
    jobs.push({ batchId, source: "wip", archivedDelivery: true, historyIncomplete: true,
      workOrder: entry.workOrder, product: entry.product, family: lot.family,
      quantity: entry.completedQuantity, turningMachineId: entry.machineId, operations,
      completion: entry.completedAt, deliveryReadyAt: Number.isFinite(serial) && serial > 0 ? serial : entry.completedAt });
  }
  return jobs;
}

