import { plannedJourneyRange } from "./charge-journey-status";
import { processLabel } from "./process-master-data";
import type { ProcessOperation, RoutedProcessJob } from "./process-planning";

const validRange = (start: number, end: number) => Number.isFinite(start) && Number.isFinite(end) && start > 0 && end >= start;
export function journeyOperationLabel(operation: ProcessOperation): string {
  return operation.recordedProcess === "washing" ? "Yıkama" : processLabel(operation.process);
}
export function journeyOperationRunning(operation: ProcessOperation): boolean {
  return !operation.actual && Boolean(operation.current || (operation.source === "current-turning" && operation.process === "turning"));
}

/** Read-only display projection. Never turn a projected start/end into an actual event. */
export function buildJourneyTimeline(job: RoutedProcessJob, now: number) {
  return job.operations.map((operation, index, operations) => {
    const candidate = plannedJourneyRange(operation);
    const plannedRange = candidate && validRange(candidate.start, candidate.end) ? candidate : null;
    const running = journeyOperationRunning(operation);
    const actualValid = validRange(operation.start, operation.end);
    const actualStart = operation.actual && actualValid ? operation.start : running && validRange(operation.start, now) ? operation.start : 0;
    const actualEnd = operation.actual && actualValid ? operation.end : actualStart && running ? now : 0;
    const remainingStart = running ? Math.max(now, operation.start) : operation.start;
    const remainingRange = !operation.actual && validRange(remainingStart, operation.end) && operation.end > remainingStart ? { start: remainingStart, end: operation.end } : null;
    const previous = operations[index - 1];
    const previousEnd = previous?.actual && validRange(previous.start, previous.end) ? previous.end : 0;
    // Unstarted work keeps waiting until now even if its old scheduled start has passed.
    const waitingEnd = ((operation.actual && actualValid) || (running && actualStart)) ? operation.start : job.source === "wip" && previousEnd > 0 ? now : 0;
    const waitStart = previousEnd > 0 && waitingEnd > previousEnd ? previousEnd : 0;
    const plannedStart = plannedRange?.start ?? operation.start;
    const plannedEnd = plannedRange?.end ?? operation.end;
    const delayedUntil = operation.actual && actualValid ? operation.end : running || waitStart ? now : 0;
    const delayStart = plannedRange && delayedUntil > plannedEnd + 1/1440 ? plannedEnd : 0;
    const status = operation.actual ? "Tamamlandı" : running ? "Üretimde" : waitStart ? "Bekliyor" : "Planlandı";
    const issues: string[] = [];
    if (!actualValid) issues.push(`${journeyOperationLabel(operation)}: tarih kaydı eksik veya geçersiz.`);
    if (running && operation.start > now) issues.push(`${journeyOperationLabel(operation)}: mevcut işin başlangıcı gelecekte kayıtlı; tarihi doğrulayın.`);
    if (operation.actual && operation.end > now) issues.push(`${journeyOperationLabel(operation)}: gerçekleşen bitiş gelecekte kayıtlı; tarihi doğrulayın.`);
    if (operation.actual && previousEnd > operation.start) issues.push(`${journeyOperationLabel(operation)}: başlangıç önceki operasyon bitişinden önce kayıtlı; tarihleri doğrulayın.`);
    if (!operation.actual && operation.end < now) issues.push(`${journeyOperationLabel(operation)}: planlanan bitiş geçti, tamamlanma kaydı yok.`);
    return { operation, running, status, issues, plannedRange, remainingRange, hasRecordedPlan: plannedRange !== null, plannedStart, plannedEnd, actualStart, actualEnd, waitStart, waitEnd: waitStart ? waitingEnd : 0, delayStart, delayEnd: delayStart ? delayedUntil : 0 };
  });
}

/** A point is a recorded instant, not an invented hour of production. */
export function journeyRangePosition(start: number, end: number, horizonStart: number, days: number): { left?: string; width?: string; display?: string } {
  if (!validRange(start,end) || !Number.isFinite(horizonStart) || !Number.isFinite(days) || days <= 0 || end < horizonStart || start >= horizonStart + days || (end === horizonStart && start < end)) return { display: "none" };
  const left = Math.max(start,horizonStart);
  const right = Math.min(end,horizonStart+days);
  return { left: `${(left-horizonStart)/days*100}%`, width: `${(right-left)/days*100}%` };
}

