import { hasActiveProductionInterruption } from "./production-interruptions";
import type { DeliveryReadinessEvent, UndatedDelivery } from "./delivery-readiness";
import type { PlanningSeed, ScenarioResult } from "./planning";

/** Temporary export estimate. It does not set route or physical delivery readiness. */
export function buildCncDeliveryReadiness(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">) {
  const events: DeliveryReadinessEvent[] = [];
  const undated: UndatedDelivery[] = [];
  function add(id: string, product: string, quantity: number, workOrder: string, source: UndatedDelivery["source"], end: number | undefined, blocked = false, wipLotId?: string) {
    if (!Number.isSafeInteger(quantity) || quantity < 0) throw Error(`${product}: CNC rapor adedi geçersiz.`);
    if (!quantity) return;
    if (blocked || !Number.isFinite(end) || (end ?? 0) <= 0) {
      undated.push({ id, product, quantity, workOrder, source, reasons: [{ code: "missing-cnc-end", message: "CNC bitişi doğrulanamadı veya şarj blokeli. CNC + 3 gün tarihi hesaplanamadı." }] });
    } else {
      events.push({ id: `cnc:${id}`, product: product.toUpperCase(), quantity, readyAt: end! + 3, source: "cnc-plus-three", routeSource: source, wipLotId });
    }
  }
  const lots = seed.wipLots ?? [];
  for (const lot of lots.filter(item => item.stage !== "delivered" && item.stage !== "scrapped")) {
    const cnc = lot.completedSteps.find(step => step.process === "turning");
    add(lot.id, lot.product, lot.availableQuantity, lot.workOrder, "wip", cnc?.end, lot.stage === "on-hold" || lot.stage === "unclassified", lot.id);
  }
  for (const machine of seed.machines.filter(item => item.currentJob.product && item.currentJob.quantity > 0)) {
    add(`current:${machine.id}`, machine.currentJob.product, machine.currentJob.quantity, machine.currentJob.workOrder, "current-turning", machine.currentJob.end,
      hasActiveProductionInterruption(seed, `current:${machine.id}`, machine.currentJob.interruptionId));
  }
  for (const batch of result.batches.filter(item => item.status === "planned")) {
    if (!batch.interruptionId && lots.some(lot => lot.sourceBatchId === batch.id)) continue;
    add(batch.id, batch.product, batch.quantity, batch.workOrder ?? "", "turning-plan", batch.end, hasActiveProductionInterruption(seed, batch.id, batch.interruptionId));
  }
  // A legacy open archive record is included once, with no invented CNC date.
  for (const entry of (seed.productionHistory ?? []).filter(item => item.inventoryStatus === "semi-finished")) {
    if (lots.some(lot => lot.sourceHistoryEntryId === entry.id)) continue;
    add(`history:${entry.id}`, entry.product, entry.completedQuantity, entry.workOrder, "wip", entry.process === "turning" ? entry.completedAt : undefined);
  }
  events.sort((left, right) => left.readyAt - right.readyAt || left.id.localeCompare(right.id));
  return { events, undated, undatedQuantity: undated.reduce((sum, row) => sum + row.quantity, 0) };
}

frontend/lib/collaboration-client.ts.source:
import type { ApiFetch } from "./api";
import type { PlanningSeed, StoredScenario } from "./planning";
import { applyPlanningDelta, buildPlanningDelta, planningContentHash, type PlanningDelta } from "./planning-delta";
import { planningSaveRequestBody } from "./planning-persistence";
import { scenarioPlanningSeed } from "./scenario-safety";
import { productionCommandBasis, type ProductionCommand } from "./production-command";

type Store = Pick<Storage, "getItem" | "setItem" | "removeItem"> & Partial<Pick<Storage, "key" | "length">>;
export type PendingCollaborationWrite = { path: string; method: "POST" | "PATCH"; body: string; draft?: StoredScenario };

/** One durable in-flight request per user and browser tab. Never replay on a timer. */
export class CollaborationWriter {
  readonly key: string;
  busy = false;
  private volatilePending: PendingCollaborationWrite | null = null;
  constructor(private fetch: ApiFetch, private store: Store, readonly userId: string, sessionId: string, private onPending: (pending: boolean) => void = () => {}) {
    this.key = `selsa-collaboration-v1:${encodeURIComponent(userId)}:${encodeURIComponent(sessionId)}`;
  }
  pending(): PendingCollaborationWrite | null {
    if (this.volatilePending) return this.volatilePending;
    const raw = this.store.getItem(this.key);
    if (!raw) {
      const keys = Array.from({ length: this.store.length ?? 0 }, (_, index) => this.store.key?.(index)).filter((key): key is string => Boolean(key?.startsWith(`${this.key}:request:`)));
      if (keys.length > 1) throw Error("Birden fazla onaysız istek bulundu. Yedek indir ile tüm istekleri koruyun.");
      return keys.length ? JSON.parse(this.store.getItem(keys[0])!) as PendingCollaborationWrite : null;
    }
    const index = JSON.parse(raw) as PendingCollaborationWrite & { requestKey?: string };
    if (!index.requestKey) return index;
    const request = this.store.getItem(index.requestKey);
    if (!request) throw Error("Bekleyen isteğin kopyası bulunamadı. Yedek indirin.");
    return JSON.parse(request) as PendingCollaborationWrite;
  }
  async send(request: PendingCollaborationWrite) {
    if (this.busy || this.pending()) throw Error("Bekleyen kayıt var. Yedek indir ile kopyayı saklayın ve Yeniden dene ile sonucu kontrol edin.");
    // A storage error must occur before the network call.
    this.volatilePending = request;
    this.onPending(true);
    this.storeRequest(request);
    return this.retry();
  }
  async retry(): Promise<Record<string, unknown>> {
    if (this.busy) throw Error("Kayıt onayı bekleniyor.");
    const pending = this.pending();
    if (!pending) throw Error("Bekleyen kayıt yok.");
    this.busy = true;
    this.onPending(true);
    try {
      this.storeRequest(pending);
      planningSaveRequestBody(JSON.parse(pending.body) as Record<string, unknown>);
      const response = await this.fetch(pending.path, { method: pending.method, headers: { "Content-Type": "application/json" }, body: pending.body });
      const value = await response.json().catch(() => ({}));
      if (!response.ok) throw Error(typeof value.detail === "string" ? value.detail : "Kayıt onayı alınamadı. Yerel kopyayı koruyun.");
      const sent = JSON.parse(pending.body) as { requestId?: string; previewId?: string };
      if (sent.requestId && (value.requestId !== sent.requestId || !value.appliedRevision)) throw Error("Kayıt makbuzu eksik. Yerel isteği koruyun.");
      if (sent.previewId && value.publicationId !== sent.previewId) throw Error("Yayınlama makbuzu eksik. Yerel isteği koruyun.");
      if (value.scenarioSeedCorrection !== undefined) {
        const correction = value.scenarioSeedCorrection;
        const scenario = value.scenario;
        if (!pending.draft || !scenario || scenario.seed !== undefined || value.replayed !== false
          || scenario.id !== pending.draft.id || scenario.revision !== value.appliedRevision
          || !Number.isInteger(value.appliedRevision) || value.appliedRevision !== (pending.draft.revision ?? 0) + 1
          || !correction || typeof correction !== "object"
          || !/^[a-f0-9]{64}$/.test(correction.baseHash) || !/^[a-f0-9]{64}$/.test(correction.stateHash)
          || await planningContentHash(pending.draft.seed) !== correction.baseHash) {
          throw Error("Taslak kayıt yanıtı doğrulanamadı. Yerel isteği koruyun.");
        }
        const seed = applyPlanningDelta(pending.draft.seed as unknown as Record<string, unknown>, correction.delta as PlanningDelta);
        if (await planningContentHash(seed) !== correction.stateHash) throw Error("Taslak kayıt özeti uyuşmuyor. Yerel isteği koruyun.");
        value.scenario = { ...scenario, seed };
      } else if (pending.draft && (!value.scenario?.seed || value.scenario.id !== pending.draft.id)) {
        throw Error("Taslak kayıt yanıtı eksik. Yerel isteği koruyun.");
      }
      if (value.scenarioResultCorrection !== undefined) {
        const correction = value.scenarioResultCorrection;
        if (!pending.draft || value.replayed !== false || !value.scenarioSeedCorrection || value.scenario?.result !== undefined
          || !correction || typeof correction !== "object" || !/^[a-f0-9]{64}$/.test(correction.baseHash)
          || !/^[a-f0-9]{64}$/.test(correction.stateHash) || await planningContentHash(pending.draft.result) !== correction.baseHash) {
          throw Error("Taslak sonuç yanıtı doğrulanamadı. Yerel isteği koruyun.");
        }
        const result = applyPlanningDelta(pending.draft.result as unknown as Record<string, unknown>, correction.delta as PlanningDelta);
        if (await planningContentHash(result) !== correction.stateHash) throw Error("Taslak sonuç özeti uyuşmuyor. Yerel isteği koruyun.");
        value.scenario = { ...value.scenario, result };
      }
      if (pending.draft && (!value.scenario?.result || typeof value.scenario.result !== "object"
        || !Array.isArray(value.scenario.result.batches) || !value.scenario.result.summary)) {
        throw Error("Taslak sonuç kaydı eksik. Yerel isteği koruyun.");
      }
      // Keep the request until the coordinator applies the acknowledgement.
      return value;
    } finally { this.busy = false; }
  }
  private requestKey(request: PendingCollaborationWrite) {
    const body = JSON.parse(request.body) as { requestId?: string; previewId?: string };
    return `${this.key}:request:${encodeURIComponent(body.requestId ?? body.previewId ?? "unknown")}`;
  }
  private storeRequest(request: PendingCollaborationWrite) {
    const requestKey = this.requestKey(request);
    // A copied browser tab can share a session ID. Unique receipt keys ensure
    // that its request can never erase this tab's recovery body.
    this.store.setItem(requestKey, JSON.stringify(request));
    this.store.setItem(this.key, JSON.stringify({ requestKey }));
  }
  acknowledge() {
    const pending = this.pending();
    if (!pending) return;
    const requestKey = this.requestKey(pending);
    const raw = this.store.getItem(this.key);
    if (raw) {
      const index = JSON.parse(raw) as { requestKey?: string; body?: string };
      if (index.requestKey === requestKey || index.body === pending.body) this.store.removeItem(this.key);
    }
    this.store.removeItem(requestKey);
    this.volatilePending = null;
    this.onPending(false);
  }
  async saveDraft(base: StoredScenario, seed: PlanningSeed, worldRevision: string) {
    const draft = scenarioPlanningSeed(seed);
    const body = JSON.stringify({ requestId: crypto.randomUUID(), revision: base.revision, worldRevision, responseMode: "compact-v1",
      delta: buildPlanningDelta(base.seed as unknown as Record<string, unknown>, draft as unknown as Record<string, unknown>) });
    return this.send({ path: `/scenarios/${encodeURIComponent(base.id)}`, method: "PATCH", body, draft: { ...base, seed: draft } });
  }
  async createDraft(world: { seed: PlanningSeed; updatedAt: string }, draft: StoredScenario) {
    const proposal = scenarioPlanningSeed(draft.seed);
    const base = scenarioPlanningSeed(world.seed);
    const body = JSON.stringify({ id: draft.id, name: draft.name, requestId: crypto.randomUUID(), worldRevision: world.updatedAt,
      delta: buildPlanningDelta(base as unknown as Record<string, unknown>, proposal as unknown as Record<string, unknown>) });
    return this.send({ path: "/scenarios/from-world", method: "POST", body, draft: { ...draft, seed: proposal } });
  }
  async command(seed: PlanningSeed, command: ProductionCommand) {
    const expectedBasis = await planningContentHash(productionCommandBasis(seed, command));
    const body = JSON.stringify({ requestId: crypto.randomUUID(), expectedBasis, command, responseMode: "compact-v1" });
    return this.send({ path: "/production/commands", method: "POST", body });
  }
}

