import { applyPlanningDelta } from "./planning-delta";
import { applyParameterDeactivation, parameterDeactivationImpact, assertParameterTransitionDecided, type DeactivationTarget, type DeactivationDecision } from "./parameter-deactivation";
import { readFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { cloneSeed } from "../features/planning/session/planning-state";
import { createProductionActions } from "../features/planning/session/production-actions";
import { productionCommandBasis, productionCommandNames, type ProductionCommand } from "./production-command";
import { cancelRemainingProduction, reviewProductionCancellation } from "./production-cancellation";
import { previewOrderRevision, scenarioResultFromBatches, type PlanningSeed, type ScenarioResult } from "./planning";
import { mergeScenarioWithLiveOperations, rebaseScenarioPlan, scenarioPlanningSeed } from "./scenario-safety";
import { assertTurningIdentityTransition } from "./turning-queue-identity";

function stable(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(stable);
  if (value && typeof value === "object") return Object.fromEntries(Object.entries(value).sort(([a],[b]) => a < b ? -1 : a > b ? 1 : 0).map(([k,v]) => [k,stable(v)]));
  return value;
}
const hash = (value: unknown) => createHash("sha256").update(JSON.stringify(stable(value))).digest("hex");
try {
  const request = JSON.parse(readFileSync(0, "utf8"));
  const seed = request.seed as PlanningSeed;
  let response: unknown;
  if (request.action === "draft") {
    const clean = scenarioPlanningSeed(seed);
    const display = request.world ? mergeScenarioWithLiveOperations(clean, request.world) : clean;
    response = { seed: clean, result: scenarioResultFromBatches(display, display.manualBatches ?? []) };
  } else if (request.action === "compose") {
    const composed = mergeScenarioWithLiveOperations(request.draft, seed);
    response = { seed: composed, result: scenarioResultFromBatches(composed, composed.manualBatches ?? []) };
  } else if (request.action === "publish") {
    // Only proposal fields can be published. Official inputs and facts come from
    // the current server state. Hypothetical orders or rates need separate review.
    const fields = ["manualBatches", "savedBatches", "processOperationOverrides", "activePlanningScope", "demandTargets", "activePlanRun", "planRunSequence", "lastAutomaticPlan", "planNeedsRecalculation"] as const;
    const draft = request.draft as PlanningSeed;
    if (draft.productionArea && draft.productionArea !== (seed.productionArea ?? "torna")) throw Error("Plan başka bir üretim alanına ait.");
    if (draft.planNeedsRecalculation) throw Error("Taslak güncel değil. Ortak üretimle planı yeniden inceleyip çalıştırın.");
    const official = scenarioPlanningSeed(cloneSeed(seed));
    const candidate = scenarioPlanningSeed(cloneSeed(draft));
    for (const field of ["orders", "products", "preferences", "restrictions", "machines", "holidays", "calendarEvents", "setupSettings", "processMasterData", "processWaitSettings", "flowSettings", "productWeights", "rawMaterialSettings", "customerDemand", "openingStock"] as const) {
      if (hash(candidate[field] ?? null) !== hash(official[field] ?? null)) throw Error("Taslak sipariş veya parametreleri ortak kayıtla farklı. Önce ortak girdilerle planı yeniden inceleyin.");
    }
    const next = structuredClone(seed);
    for (const field of fields) {
      if (Object.hasOwn(draft, field)) (next as unknown as Record<string, unknown>)[field] = structuredClone(draft[field]);
      else delete next[field];
    }
    for (const batch of seed.manualBatches ?? []) {
      if ((batch.locked || batch.routeCommitted) && hash(next.manualBatches?.find(row => row.id === batch.id) ?? null) !== hash(batch)) throw Error("Yayınlama kilitli işi değiştiremez. Yürürlükteki planı inceleyin.");
    }
    const merged = mergeScenarioWithLiveOperations(next, seed);
    const rebased = rebaseScenarioPlan(merged, scenarioResultFromBatches(merged, merged.manualBatches ?? []));
    if (rebased.overflows.length) throw Error("Plan penceresini aşan işler var. Yayınlamadan önce planı inceleyin.");
    merged.manualBatches = rebased.result.batches;
    assertTurningIdentityTransition(seed, merged);
    merged.planNeedsRecalculation = false;
    response = { seed: merged, result: rebased.result };
  } else if (request.action === "command") {
    const command = request.command as ProductionCommand;
    if (!productionCommandNames.includes(command.kind) || !Array.isArray(command.args) || command.args.length > 8) throw Error("Üretim komutu geçersiz.");
    if (hash(productionCommandBasis(seed, command)) !== request.expectedBasis) {
      process.stdout.write(JSON.stringify({ error: "İlgili üretim kaydı değişti. Güncel kayıtla işlemi yeniden inceleyin.", conflict: true }));
      process.exit(0);
    }
    const result = scenarioResultFromBatches(seed, seed.manualBatches ?? []);
    let orderReview: unknown;
    let accepted: { seed: PlanningSeed; result: ScenarioResult; message: string } | undefined;
    const actions = createProductionActions({ seed, result, setDirty: () => {}, setOperationAlert: alert => { throw Error(alert.message); },
      commitOperationalChange: (nextSeed, nextResult, message, event) => {
        nextSeed.manualBatches = nextResult.batches;
        nextSeed.planNeedsRecalculation = true;
        if (event) nextSeed.planningEvents = [{ ...event, id: crypto.randomUUID(), createdAt: new Date().toISOString() }, ...(nextSeed.planningEvents ?? [])].slice(0, 200);
        accepted = { seed: nextSeed, result: nextResult, message };
      } });
    if (command.kind === "deactivateParameters") {
      const input = command.args[0] as { targets: { target: DeactivationTarget; signature: string }[]; decisions: DeactivationDecision[]; delta: Parameters<typeof applyPlanningDelta>[1] };
      let next = { seed: structuredClone(seed), result };
      for (const reviewed of input.targets) {
        const impact = parameterDeactivationImpact(next.seed, next.result, reviewed.target);
        if (impact.signature !== reviewed.signature) throw Error("Pasif atama incelemesi değişti. Yeniden inceleyin.");
        const keys = new Set(impact.queued.map(job => job.key));
        next = applyParameterDeactivation(next.seed, next.result, reviewed.target, input.decisions.filter(decision => keys.has(decision.key)), impact.signature);
      }
      next.seed = applyPlanningDelta(next.seed as unknown as Record<string, unknown>, input.delta) as unknown as PlanningSeed;
      assertParameterTransitionDecided(seed, next.seed, next.result.batches);
      next.seed.manualBatches = next.result.batches;
      next.seed.planNeedsRecalculation = true;
      accepted = { ...next, message: "Pasif atama kararları kaydedildi" };
    } else if (command.kind === "reviseOfficialOrder") {
      const preview = previewOrderRevision(seed, result, command.args[0] as Parameters<typeof previewOrderRevision>[2], "optimized");
      const next = structuredClone(seed);
      next.orders = preview.seed.orders;
      orderReview = { requested: command.args[0], impact: preview.impact };
      next.planNeedsRecalculation = true;
      accepted = { seed: next, result: scenarioResultFromBatches(next, next.manualBatches ?? []), message: "Resmi sipariş revizyonu onaylandı · planı yeniden inceleyin" };
    } else if (command.kind === "cancelRemainingProduction") {
      const next = cancelRemainingProduction(seed, result, command.args[0] as Parameters<typeof cancelRemainingProduction>[2]);
      accepted = { ...next, message: "Kalan üretim iptal edildi" };
    } else if (command.kind === "reviewProductionCancellation") {
      const next = reviewProductionCancellation(seed, command.args[0] as string, command.args[1] as Parameters<typeof reviewProductionCancellation>[2]);
      accepted = { seed: next, result, message: "İptal sonrası inceleme kaydedildi" };
    } else {
      (actions[command.kind] as (...args: unknown[]) => unknown)(...command.args);
    }
    if (!accepted) throw Error("Üretim işlemi tamamlanmadı.");
    assertTurningIdentityTransition(seed, accepted.seed);
    if (["reviseOfficialOrder", "deactivateParameters", "cancelRemainingProduction", "reviewProductionCancellation"].includes(command.kind)) {
      accepted.seed.planningEvents = [{ id: crypto.randomUUID(), createdAt: new Date().toISOString(), type: "wip" as const, message: accepted.message }, ...(accepted.seed.planningEvents ?? [])].slice(0, 200);
    }
    response = { ...accepted, orderReview };
  } else throw Error("İşlem geçersiz.");
  process.stdout.write(JSON.stringify(response));
} catch (error) {
  process.stdout.write(JSON.stringify({ error: error instanceof Error ? error.message : "İşlem doğrulanamadı." }));
}

frontend/lib/customer-order-overrides.ts.source:
import type { CustomerOrderOverride, Order } from "./planning";
import { sortOrdersByCatalog } from "./order-entry";

export type CustomerOrderInput = {
  product: string;
  quantity: number;
  dueDate: string;
};

function normalizedProduct(value: string): string {
  return value.trim().toUpperCase();
}

function validDate(value: string): boolean {
  return /^\d{4}-\d{2}-\d{2}$/.test(value)
    && Number.isFinite(Date.parse(`${value}T00:00:00Z`));
}

export function validateCustomerOrderInput(
  input: CustomerOrderInput,
  options: { requireR90?: boolean; allowZero?: boolean } = {},
): string[] {
  const product = normalizedProduct(input.product);
  const quantity = Number(input.quantity);
  const errors: string[] = [];

  if (!product) errors.push("Tip numarası zorunludur.");
  else if (!/^[A-Z0-9][A-Z0-9._/-]{1,63}$/.test(product)) errors.push("Tip numarası geçerli değil.");
  else if (options.requireR90 && !product.startsWith("R90")) errors.push("Yeni tip numarası R90 ile başlamalıdır.");
  if (!Number.isInteger(quantity) || quantity < 0 || (!options.allowZero && quantity === 0)) {
    errors.push(options.allowZero ? "Sipariş adedi sıfır veya pozitif tam sayı olmalıdır." : "Sipariş adedi pozitif tam sayı olmalıdır.");
  }
  if (quantity > 0 && !validDate(input.dueDate)) errors.push("Geçerli bir termin tarihi seçin.");
  return errors;
}

export function upsertCustomerOrderOverride(
  overrides: CustomerOrderOverride[] = [],
  input: CustomerOrderInput,
  updatedAt = new Date().toISOString(),
): CustomerOrderOverride[] {
  const errors = validateCustomerOrderInput(input, { allowZero: true });
  if (errors.length) throw new Error(errors[0]);
  const product = normalizedProduct(input.product);
  const next: CustomerOrderOverride = {
    product,
    quantity: Math.trunc(input.quantity),
    dueDate: input.quantity > 0 ? input.dueDate : "",
    updatedAt,
  };
  return [...overrides.filter((item) => normalizedProduct(item.product) !== product), next];
}

export function removeCustomerOrderOverride(
  overrides: CustomerOrderOverride[] = [],
  product: string,
): CustomerOrderOverride[] {
  const normalized = normalizedProduct(product);
  return overrides.filter((item) => normalizedProduct(item.product) !== normalized);
}

function overrideOrder(
  override: CustomerOrderOverride,
  existing: Order | undefined,
  sourceRow: number,
): Order {
  return {
    id: existing?.id ?? `customer-override-${override.product}`,
    sourceRow,
    product: override.product,
    periodId: override.dueDate ? override.dueDate.slice(0, 7) : existing?.periodId,
    quantity: override.quantity,
    savedPlanned: existing?.savedPlanned ?? 0,
    savedDifference: existing?.savedDifference ?? 0,
    savedMachines: existing?.savedMachines ?? [],
    dueDate: override.dueDate,
    allowPartial: false,
    partialDeliveryQuantity: 0,
    partialDeliveryDate: "",
    deliveryMilestones: [],
  };
}

export function applyCustomerOrderOverrides(
  baseOrders: Order[],
  overrides: CustomerOrderOverride[] = [],
  catalog: string[],
  existingOrders: Order[] = [],
): Order[] {
  const normalizedCatalog = [...new Set([
    ...catalog.map(normalizedProduct),
    ...overrides.map((item) => normalizedProduct(item.product)),
  ].filter(Boolean))];
  const overrideByProduct = new Map(overrides.map((item) => [normalizedProduct(item.product), item]));
  const existingByProduct = new Map(existingOrders.map((order) => [normalizedProduct(order.product), order]));
  const baseByProduct = new Map(baseOrders.map((order) => [normalizedProduct(order.product), order]));
  const next: Order[] = [];

  for (const product of normalizedCatalog) {
    const override = overrideByProduct.get(product);
    const base = baseByProduct.get(product);
    if (!override) {
      if (base) next.push(base);
      continue;
    }
    if (override.quantity <= 0) continue;
    const sourceRow = normalizedCatalog.indexOf(product) + 2;
    next.push(overrideOrder(override, base ?? existingByProduct.get(product), sourceRow));
  }
  return sortOrdersByCatalog(next, normalizedCatalog);
}

export function customerOrderOverrideFor(
  overrides: CustomerOrderOverride[] | undefined,
  product: string,
): CustomerOrderOverride | undefined {
  const normalized = normalizedProduct(product);
  return overrides?.find((item) => normalizedProduct(item.product) === normalized);
}

