import { processWaitWorkdays } from "./process-waits";
import { flowRule, addDepartmentWorkMinutes } from "./flow-settings";
import type { ProductFamily, ProcessKind } from "./process-master-data";
import type { PlanningSeed } from "./planning";

const EXCEL_EPOCH = Date.UTC(1899, 11, 30);
const DAY_MS = 86_400_000;

export const TURNING_DELIVERY_LEAD_WORKDAYS = 4;
export const ROUTED_DELIVERY_BUFFER_WORKDAYS = 1;

type FactoryCalendar = Pick<PlanningSeed, "calendarEvents" | "holidays" | "processWaitSettings" | "productionArea" | "flowSettings" | "setupSettings">;

function dayOfWeek(serial: number): number {
  return new Date(EXCEL_EPOCH + Math.floor(serial) * DAY_MS).getUTCDay();
}

export function addDeliveryWorkdays(completionSerial: number, workdays: number): number {
  if (!Number.isFinite(completionSerial) || completionSerial <= 0) return completionSerial;
  const fraction = completionSerial - Math.floor(completionSerial);
  let serial = Math.floor(completionSerial);
  let remaining = Math.max(0, Math.trunc(workdays));
  while (remaining > 0) {
    serial += 1;
    if (dayOfWeek(serial) !== 0) remaining -= 1;
  }
  return serial + fraction;
}

export function isFactoryWorkday(seed: FactoryCalendar, serialValue: number): boolean {
  const serial = Math.floor(serialValue);
  const addedShift = (seed.calendarEvents ?? []).some((event) =>
    event.kind === "shift"
    && event.shiftCount > 0
    && serial >= Math.floor(event.start)
    && serial <= Math.floor(event.end),
  );
  if (addedShift) return true;
  const holiday = seed.holidays.find((item) => Math.floor(item.serial) === serial);
  if (holiday) return (holiday.workingShifts ?? 0) > 0;
  return dayOfWeek(serial) !== 0;
}

export function addFactoryWorkdays(seed: FactoryCalendar, startValue: number, workdaysValue: number): number {
  if (!Number.isFinite(startValue) || startValue <= 0) return startValue;
  const workdays = Math.max(0, Math.trunc(workdaysValue));
  if (!workdays) return startValue;
  let serial = Math.floor(startValue);
  let remaining = workdays;
  while (remaining > 0) {
    serial += 1;
    if (isFactoryWorkday(seed, serial)) remaining -= 1;
  }
  return serial;
}

export function turningDeliveryReadyAt(completionSerial: number): number {
  return addDeliveryWorkdays(completionSerial, TURNING_DELIVERY_LEAD_WORKDAYS);
}

/**
 * Delme, çapak alma ve GKM süreleri artık rota üzerinde hesaplanır. Bu sabit
 * tampon yalnızca sistemde kapasitesi modellenmeyen son prosesi temsil eder.
 */
export function routedDeliveryReadyAt(seed: FactoryCalendar, routeCompletionSerial: number, family?: ProductFamily, lastProcess: ProcessKind = "gkm"): number {
  const rule = family ? flowRule(seed, family, lastProcess, "delivery") : undefined;
  if (rule?.mode === "static") return addDepartmentWorkMinutes(seed, routeCompletionSerial, rule.minutes);
  return addFactoryWorkdays(seed, routeCompletionSerial, processWaitWorkdays(seed, lastProcess));
}

