import type { DeliveryDeductionPreview } from "./delivery-deduction";
import { committedProductionQuantities, newProductionBudgetCommitments, productionTargetForShortage, retainRouteCommitments, shortageExtraChargePolicyForSeed, type PlannedBatch, type PlanningSeed, type ShortageExtraChargePolicy } from "./planning";
import { withInterruptedBatches } from "./production-interruptions";
import { factoryDateTimeInput, factoryDateTimeToIso } from "./factory-time";

export type DeliveryCoverageReview = {
  key: string;
  items: DeliveryDeductionPreview["excludedItems"];
  products: Array<{ product: string; excludedQuantity: number; existingQuantity: number; selectedNewQuantity: number; inclusiveNewQuantity: number }>;
};

/** Same quantity sources and saved shortage policy as Torna; never schedules or mutates. */
export function reviewDeliveryCoverage(seed: PlanningSeed, preview: DeliveryDeductionPreview | null | undefined, fixed: PlannedBatch[], shortagePolicy: ShortageExtraChargePolicy = shortageExtraChargePolicyForSeed(seed)): DeliveryCoverageReview | null {
  if (!preview?.excludedItems.length) return null;
  const commitments = withInterruptedBatches(seed, retainRouteCommitments(seed, fixed)).filter(batch => batch.status === "planned");
  const committed = newProductionBudgetCommitments(seed, commitments);
  const products = preview.products.flatMap(row => {
    const inclusive = preview.includingExcludedProducts.find(item => item.product === row.product);
    const parameters = seed.products.find(item => item.product.toUpperCase() === row.product);
    if (!inclusive || !parameters || inclusive.plannedDemand >= row.plannedDemand) return [];
    const existingQuantity = committed.get(row.product) ?? 0;
    const selectedNewQuantity = productionTargetForShortage(Math.max(0, row.plannedDemand - existingQuantity), parameters.batchSize, shortagePolicy);
    const inclusiveNewQuantity = productionTargetForShortage(Math.max(0, inclusive.plannedDemand - existingQuantity), parameters.batchSize, shortagePolicy);
    return selectedNewQuantity > inclusiveNewQuantity ? [{ product: row.product,
      excludedQuantity: row.plannedDemand - inclusive.plannedDemand,
      existingQuantity, selectedNewQuantity, inclusiveNewQuantity }] : [];
  }).sort((left, right) => left.product.localeCompare(right.product));
  if (!products.length) return null;
  const items = preview.excludedItems.filter(item => products.some(row => row.product === item.product));
  // Wall-clock passage alone does not invalidate review; any changed figures or records do.
  const { endAt: _endAt, ...filter } = preview.snapshot.filter;
  const key = JSON.stringify({ import: preview.snapshot.import, filter, products, items });
  return { key, products, items };
}

export function assertDeliveryCoverageReviewed(review: DeliveryCoverageReview | null, reviewedKey?: string): void {
  if (review && review.key !== reviewedKey) {
    throw new Error(`Teslimat kapsamını kontrol edin: ${review.products.map(row => row.product).join(", ")} için dışarıda kalan teslimatlar ek şarj açılmasına neden olabilir. Planı Çalıştır penceresinde teslimat başlangıcını düzeltin veya gösterilen kayıtların Excel ihtiyacına zaten yansıtıldığını doğrulayın. Devam planında filtre değişecekse yeni plan başlatın.`);
  }
}

/** A minute-resolution control must not silently truncate an untouched saved instant. */
export function deliveryCutoffFromInput(value: string, originalIso?: string): string {
  if (originalIso && value === factoryDateTimeInput(originalIso)) return originalIso;
  return factoryDateTimeToIso(value);
}

frontend/lib/delivery-deduction.ts.source:
import { factoryDateInput } from "./factory-time";
import {
  orderDeliveryMilestones,
  type DeliveryDeductionFilter,
  type DeliveryDeductionItem,
  type DeliveryDeductionSnapshot,
  type Order,
  type OrderImportMetadata,
  type PlanningSeed,
  type ProductionHistoryEntry,
} from "./planning";

export type DeliveryDeductionProductRow = {
  product: string;
  orderIds: string[];
  grossDemand: number;
  deductedQuantity: number;
  plannedDemand: number;
  excessDeliveryQuantity: number;
};

export type DeliveryDeductionPreview = {
  adjustedOrders: Order[];
  snapshot: DeliveryDeductionSnapshot;
  products: DeliveryDeductionProductRow[];
  unmatchedItems: DeliveryDeductionItem[];
  excludedItems: DeliveryDeductionItem[];
  includingExcludedProducts: DeliveryDeductionProductRow[];
};

function stablePart(value: string): string {
  return value.replace(/[^a-zA-Z0-9_-]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 70);
}

export function createOrderImportMetadata(sourceFile: string, importedAt = new Date().toISOString()): OrderImportMetadata {
  return {
    id: `orders-${stablePart(importedAt)}-${stablePart(sourceFile)}`,
    sourceFile,
    importedAt,
  };
}

export function orderImportMetadataForSeed(seed: Pick<PlanningSeed, "orderImport" | "customerDemand">): OrderImportMetadata | null {
  if (seed.orderImport?.id && seed.orderImport.sourceFile && seed.orderImport.importedAt) return { ...seed.orderImport };
  const demand = seed.customerDemand;
  if (!demand?.sourceFile || !demand.importedAt) return null;
  return {
    id: `demand-${stablePart(demand.snapshotDate)}-${stablePart(demand.importedAt)}-${stablePart(demand.sourceFile)}`,
    sourceFile: demand.sourceFile,
    importedAt: demand.importedAt,
  };
}

export function effectiveDeliveryTimestamp(entry: ProductionHistoryEntry): string {
  if (entry.deliveredAtTime && Number.isFinite(Date.parse(entry.deliveredAtTime))) return new Date(entry.deliveredAtTime).toISOString();
  const deliveryDate = entry.deliveredAt?.slice(0, 10) ?? "";
  if (deliveryDate && entry.statusChangedAt && factoryDateInput(entry.statusChangedAt) === deliveryDate) {
    return new Date(entry.statusChangedAt).toISOString();
  }
  if (deliveryDate) return new Date(`${deliveryDate}T00:00:00+03:00`).toISOString();
  return entry.statusChangedAt && Number.isFinite(Date.parse(entry.statusChangedAt))
    ? new Date(entry.statusChangedAt).toISOString()
    : "";
}

function isInsideFilter(timestamp: string, filter: DeliveryDeductionFilter): boolean {
  const value = Date.parse(timestamp);
  const start = Date.parse(filter.startAt);
  const end = Date.parse(filter.endAt);
  if (![value, start, end].every(Number.isFinite)) return false;
  return (filter.includeStart ? value >= start : value > start) && value <= end;
}

function validateFilter(filter: DeliveryDeductionFilter): void {
  const start = Date.parse(filter.startAt);
  const end = Date.parse(filter.endAt);
  if (!Number.isFinite(start) || !Number.isFinite(end)) throw new Error("Teslimat başlangıç veya plan çalışma zamanı geçersiz.");
  if (start > end) throw new Error("Teslimat başlangıç zamanı planın çalışma zamanından sonra olamaz.");
}

type DeliveryDeductionInput = {
  orders: Order[];
  productionHistory?: ProductionHistoryEntry[];
  orderImport: OrderImportMetadata;
  importProducts: Iterable<string>;
  filter: DeliveryDeductionFilter;
};

function deductDeliveries(input: DeliveryDeductionInput): Omit<DeliveryDeductionPreview, "excludedItems" | "includingExcludedProducts"> {
  validateFilter(input.filter);
  const orders = input.orders.map((order) => ({ ...order, deliveryMilestones: order.deliveryMilestones?.map((milestone) => ({ ...milestone })) }));
  const grossDemand = orders.reduce((sum, order) => sum + Math.max(0, order.quantity), 0);
  const importedProducts = new Set([...input.importProducts].map((product) => product.trim().toUpperCase()).filter(Boolean));
  const orderIndexesByProduct = new Map<string, number[]>();
  orders.forEach((order, index) => {
    const code = order.product.trim().toUpperCase();
    orderIndexesByProduct.set(code, [...(orderIndexesByProduct.get(code) ?? []), index]);
  });
  for (const indexes of orderIndexesByProduct.values()) {
    indexes.sort((left, right) => orders[left].dueDate.localeCompare(orders[right].dueDate) || orders[left].sourceRow - orders[right].sourceRow);
  }

  const remainingByOrder = orders.map((order) => Math.max(0, order.quantity));
  const deductedByOrder = orders.map(() => 0);
  const seenIds = new Set<string>();
  const candidates = input.filter.enabled
    ? (input.productionHistory ?? [])
      .filter((entry) => entry.inventoryStatus === "delivered" && entry.completedQuantity > 0 && !seenIds.has(entry.id) && seenIds.add(entry.id))
      .map((entry) => ({ entry, deliveredAt: effectiveDeliveryTimestamp(entry) }))
      .filter(({ deliveredAt }) => deliveredAt && isInsideFilter(deliveredAt, input.filter))
      .sort((left, right) => left.deliveredAt.localeCompare(right.deliveredAt) || left.entry.id.localeCompare(right.entry.id))
    : [];

  const items: DeliveryDeductionItem[] = [];
  for (const { entry, deliveredAt } of candidates) {
    const product = entry.product.trim().toUpperCase();
    const indexes = orderIndexesByProduct.get(product) ?? [];
    if (!importedProducts.has(product)) {
      items.push({ entryId: entry.id, sourceEntryId: entry.sourceEntryId, product, workOrder: entry.workOrder, deliveredAt, quantity: entry.completedQuantity, deductedQuantity: 0, excessQuantity: 0, matchedOrderIds: [], status: "unmatched" });
      continue;
    }
    if (!indexes.length) {
      items.push({ entryId: entry.id, sourceEntryId: entry.sourceEntryId, product, workOrder: entry.workOrder, deliveredAt, quantity: entry.completedQuantity, deductedQuantity: 0, excessQuantity: 0, matchedOrderIds: [], status: "outside-scope" });
      continue;
    }
    let remainingDelivery = entry.completedQuantity;
    let deductedQuantity = 0;
    const matchedOrderIds: string[] = [];
    for (const index of indexes) {
      if (remainingDelivery <= 0) break;
      const deducted = Math.min(remainingDelivery, remainingByOrder[index]);
      if (deducted <= 0) continue;
      remainingByOrder[index] -= deducted;
      deductedByOrder[index] += deducted;
      remainingDelivery -= deducted;
      deductedQuantity += deducted;
      matchedOrderIds.push(orders[index].id);
    }
    items.push({
      entryId: entry.id,
      sourceEntryId: entry.sourceEntryId,
      product,
      workOrder: entry.workOrder,
      deliveredAt,
      quantity: entry.completedQuantity,
      deductedQuantity,
      excessQuantity: remainingDelivery,
      matchedOrderIds,
      status: remainingDelivery > 0 ? "excess" : "matched",
    });
  }

  const adjustedOrders = orders.flatMap((order, index) => {
    const deduction = deductedByOrder[index];
    const quantity = Math.max(0, order.quantity - deduction);
    if (quantity <= 0) return [];
    const milestones = orderDeliveryMilestones(order)
      .map((milestone) => ({ ...milestone, quantity: Math.max(0, milestone.quantity - deduction) }))
      .filter((milestone) => milestone.quantity > 0 && milestone.quantity < quantity);
    return [{
      ...order,
      quantity,
      allowPartial: milestones.length > 0,
      partialDeliveryQuantity: milestones[0]?.quantity ?? 0,
      partialDeliveryDate: milestones[0]?.date ?? "",
      deliveryMilestones: milestones,
    }];
  });
  const deductedQuantity = deductedByOrder.reduce((sum, quantity) => sum + quantity, 0);
  const excessDeliveryQuantity = items.reduce((sum, item) => sum + item.excessQuantity, 0);
  const snapshot: DeliveryDeductionSnapshot = {
    import: { ...input.orderImport },
    filter: { ...input.filter },
    grossDemand,
    deductedQuantity,
    plannedDemand: Math.max(0, grossDemand - deductedQuantity),
    excessDeliveryQuantity,
    items,
  };
  const products = [...new Set(orders.map((order) => order.product.trim().toUpperCase()))].map((product) => {
    const indexes = orderIndexesByProduct.get(product) ?? [];
    const productGross = indexes.reduce((sum, index) => sum + orders[index].quantity, 0);
    const productDeducted = indexes.reduce((sum, index) => sum + deductedByOrder[index], 0);
    return {
      product,
      orderIds: indexes.map((index) => orders[index].id),
      grossDemand: productGross,
      deductedQuantity: productDeducted,
      plannedDemand: Math.max(0, productGross - productDeducted),
      excessDeliveryQuantity: items.filter((item) => item.product === product).reduce((sum, item) => sum + item.excessQuantity, 0),
    };
  });
  return {
    adjustedOrders,
    snapshot,
    products,
    unmatchedItems: items.filter((item) => item.status === "unmatched"),
  };
}

/** Compare the selected window with the same calculator including post-import deliveries. */
export function calculateDeliveryDeduction(input: DeliveryDeductionInput): DeliveryDeductionPreview {
  const importProducts = [...input.importProducts];
  const selected = deductDeliveries({ ...input, importProducts });
  const importedAt = Date.parse(input.orderImport.importedAt);
  if (!Number.isFinite(importedAt)) throw new Error("Excel yükleme zamanı geçersiz; teslimat kapsamı doğrulanamadı.");
  // Keep intentionally included older deliveries; only add omitted post-import records.
  const earlierStart = input.filter.enabled && Date.parse(input.filter.startAt) < importedAt;
  const inclusive = deductDeliveries({ ...input, importProducts, filter: {
    ...input.filter, enabled: true,
    startAt: earlierStart ? input.filter.startAt : input.orderImport.importedAt,
    includeStart: earlierStart ? input.filter.includeStart : true,
  } });
  const selectedIds = new Set(selected.snapshot.items.map(item => item.entryId));
  return {
    ...selected,
    excludedItems: inclusive.snapshot.items.filter(item => !selectedIds.has(item.entryId) && item.matchedOrderIds.length > 0),
    includingExcludedProducts: inclusive.products,
  };
}

