import { hasActiveProductionInterruption } from "./production-interruptions";
import { turningDeliveryReadyAt } from "./delivery-calendar";
import { buildDownstreamProcessPlan } from "./process-planning";
import { processMasterDataForProduct } from "./process-master-data";
import { orderProductionBreakdown, type Order, type PlanningSeed, type ScenarioResult } from "./planning";

export type DeliveryReadinessEvent = {
  id: string;
  product: string;
  quantity: number;
  readyAt: number;
  source: "routed" | "turning-fallback" | "wip-fallback" | "cnc-plus-three";
  routeSource?: "current-turning" | "turning-plan" | "wip";
  wipLotId?: string;
};

function datedEvents(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">, processPlan: ReturnType<typeof buildDownstreamProcessPlan>): DeliveryReadinessEvent[] {
  const representedBatchIds = new Set([
    ...processPlan.jobs.filter((job) => job.source === "turning-plan" && Boolean(seed.processMasterData)).map((job) => job.batchId),
    ...(seed.wipLots ?? []).map((lot) => lot.sourceBatchId).filter(Boolean),
  ]);
  const representedLotIds = new Set(processPlan.jobs.filter((job) => job.source === "wip" && job.deliveryReadyAt > 0).map((job) => job.batchId));

  const routed: DeliveryReadinessEvent[] = processPlan.jobs
    .filter((job) => {
      const lot = seed.wipLots?.find((item) => item.id === job.wipLotId);
      return !lot || (lot.stage !== "on-hold" && lot.stage !== "unclassified");
    })
    .filter((job) => job.quantity > 0 && job.deliveryReadyAt > 0 && (
      Boolean(processMasterDataForProduct(seed.processMasterData, job.product)?.route)
      || job.operations.some((operation) => operation.process === "gkm")
      || (seed.wipLots ?? []).some((lot) => lot.id === job.wipLotId && lot.stage === "delivery-ready")
    ))
    .map((job) => ({ id: `route:${job.batchId}`, product: job.product.toUpperCase(), quantity: job.quantity, readyAt: job.deliveryReadyAt, source: "routed", routeSource: job.source, wipLotId: job.wipLotId }));
  const fallbackBatches: DeliveryReadinessEvent[] = result.batches
    .filter((batch) => !seed.processMasterData && batch.status === "planned" && !hasActiveProductionInterruption(seed, batch.id, batch.interruptionId) && batch.quantity > 0 && batch.end > 0 && !representedBatchIds.has(batch.id))
    .map((batch) => ({ id: `batch:${batch.id}`, product: batch.product.toUpperCase(), quantity: batch.quantity, readyAt: turningDeliveryReadyAt(batch.end), source: "turning-fallback" }));
  const fallbackReadyWip: DeliveryReadinessEvent[] = (seed.wipLots ?? [])
    .filter((lot) => !seed.processMasterData && lot.stage === "delivery-ready" && lot.availableQuantity > 0 && lot.readyAt > 0 && !representedLotIds.has(lot.id))
    .map((lot) => ({ id: `wip:${lot.id}`, product: lot.product.toUpperCase(), quantity: lot.availableQuantity, readyAt: lot.readyAt, source: "wip-fallback" }));

  return [...routed, ...fallbackBatches, ...fallbackReadyWip]
    .filter((event) => Number.isFinite(event.readyAt) && event.readyAt > 0)
    .sort((left, right) => left.readyAt - right.readyAt || left.id.localeCompare(right.id));
}

export function buildDeliveryReadinessEvents(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">, plan = buildDownstreamProcessPlan(seed, result)): DeliveryReadinessEvent[] {
  return datedEvents(seed, result, plan);
}

export type UndatedDelivery = {
  id: string; product: string; quantity: number; workOrder: string;
  source: "current-turning" | "turning-plan" | "wip";
  reasons: Array<{ code: string; message: string; process?: string }>;
};

/** Quantity inventory precedes scheduling: no date is never interpreted as no material. */
export function buildDeliveryReadinessProjection(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">) {
  const plan = buildDownstreamProcessPlan(seed, result);
  const events = datedEvents(seed, result, plan);
  const subjects = new Map<string, Omit<UndatedDelivery, "reasons">>();
  const put = (subject: Omit<UndatedDelivery, "reasons">) => {
    if (!Number.isSafeInteger(subject.quantity) || subject.quantity < 0) throw new Error(`${subject.product} için teslimat miktarı geçersiz.`);
    if (subject.quantity > 0) subjects.set(subject.id, subject);
  };
  for (const job of plan.jobs) put({ id: job.batchId, product: job.product, quantity: job.quantity, workOrder: job.workOrder, source: job.source });
  const lots = seed.wipLots ?? [];
  for (const lot of lots.filter(lot => lot.availableQuantity > 0 && lot.stage !== "delivered" && lot.stage !== "scrapped")) {
    put({ id: lot.id, product: lot.product, quantity: lot.availableQuantity, workOrder: lot.workOrder ?? "", source: "wip" });
  }
  for (const machine of seed.machines.filter(m => m.currentJob.product && m.currentJob.quantity > 0)) {
    put({ id: `current:${machine.id}`, product: machine.currentJob.product, quantity: machine.currentJob.quantity, workOrder: machine.currentJob.workOrder ?? "", source: "current-turning" });
  }
  for (const batch of result.batches.filter(b => b.status === "planned" && b.quantity > 0)) {
    if (!batch.interruptionId && lots.some(lot => lot.sourceBatchId === batch.id)) continue;
    put({ id: batch.id, product: batch.product, quantity: batch.quantity, workOrder: batch.workOrder ?? "", source: "turning-plan" });
  }
  const datedIds = new Set(events.map(e => e.id.replace(/^(route|batch|wip):/, "")));
  const undated: UndatedDelivery[] = [...subjects.values()].filter(s => !datedIds.has(s.id)).map(subject => {
    const job = plan.jobs.find(j => j.batchId === subject.id) as (typeof plan.jobs[number] & { readinessIssues?: UndatedDelivery["reasons"] }) | undefined;
    const warnings = plan.warnings.filter(w => w.batchId === subject.id || !w.batchId && w.product === subject.product);
    const reasons = job?.readinessIssues?.length ? job.readinessIssues : warnings.length ? warnings.map(w => ({ code: w.code, message: w.message }))
      : [{ code: "missing-schedule", message: "Rota tamamlanmadı; proses, kabul veya kapasite bekleniyor." }];
    return { ...subject, product: subject.product.trim().toUpperCase(), reasons };
  });
  return { events, undated, undatedQuantity: undated.reduce((sum, row) => sum + row.quantity, 0) };
}

export function deliveryReadyQuantityByDate(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">, product: string, serial: number): number {
  return deliveryReadyQuantityFromEvents(seed, buildDeliveryReadinessEvents(seed, result), product, serial);
}

export function deliveryReadyQuantityFromEvents(seed: PlanningSeed, events: DeliveryReadinessEvent[], product: string, serial: number): number {
  const code = product.trim().toUpperCase();
  const dueDay = Math.floor(serial);
  const openingStock = seed.customerDemand ? 0 : Math.max(0, seed.openingStock?.[code] ?? 0);
  return openingStock + events
    .filter((event) => event.product === code && Math.floor(event.readyAt) <= dueDay)
    .reduce((sum, event) => sum + event.quantity, 0);
}

export function orderRoutedOnTimeQuantity(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">, order: Pick<Order, "product" | "dueDate">): number | null {
  if (!order.dueDate) return null;
  const due = (Date.parse(`${order.dueDate}T00:00:00Z`) - Date.UTC(1899, 11, 30)) / 86_400_000;
  return deliveryReadyQuantityByDate(seed, result, order.product, due);
}

/** Reporting uses final delivery readiness even when the optimizer targets turning capacity. */
export function buildOrderDeliveryResults(seed: PlanningSeed, result: ScenarioResult, events = buildDeliveryReadinessEvents(seed, result)): ScenarioResult["orders"] {
  const pools = new Map<string, Array<{ readyAt: number; remaining: number }>>();
  for (const event of events) {
    const code = event.product.trim().toUpperCase();
    const pool = pools.get(code) ?? [];
    pool.push({ readyAt: event.readyAt, remaining: event.quantity });
    pools.set(code, pool);
  }
  if (!seed.customerDemand) for (const [product, quantity] of Object.entries(seed.openingStock ?? {})) {
    const code = product.trim().toUpperCase();
    pools.set(code, [{ readyAt: 0, remaining: Math.max(0, quantity) }, ...(pools.get(code) ?? [])]);
  }
  const ordered = [...result.orders].sort((a, b) => (a.dueDate || "9999").localeCompare(b.dueDate || "9999") || a.id.localeCompare(b.id));
  const remainingOrders = new Map<string, number>();
  ordered.forEach((order) => {
    const code = order.product.trim().toUpperCase();
    remainingOrders.set(code, (remainingOrders.get(code) ?? 0) + 1);
  });
  const calculated = new Map<string, ScenarioResult["orders"][number]>();
  for (const order of ordered) {
    const code = order.product.trim().toUpperCase();
    const lastOrder = remainingOrders.get(code) === 1;
    remainingOrders.set(code, remainingOrders.get(code)! - 1);
    const due = order.dueDate ? (Date.parse(`${order.dueDate}T00:00:00Z`) - Date.UTC(1899, 11, 30)) / 86_400_000 : Number.NaN;
    let needed = Math.max(0, order.quantity);
    let onTime = 0;
    for (const source of pools.get(code) ?? []) {
      // Allocate each unit once; surplus belongs to the final order for this product.
      const quantity = lastOrder ? source.remaining : Math.min(needed, source.remaining);
      if (Math.floor(source.readyAt) <= due) onTime += quantity;
      source.remaining -= quantity;
      needed = Math.max(0, needed - quantity);
    }
    calculated.set(order.id, { ...order, ...orderProductionBreakdown(seed, result.batches, order),
      onTimePlanned: Number.isFinite(due) ? onTime : null,
      onTimeDifference: Number.isFinite(due) ? onTime - order.quantity : null });
  }
  return result.orders.map((order) => calculated.get(order.id)!);
}

