export type FeedbackPriority = 1 | 2 | 3;
export const DEFAULT_VISIBLE_FEEDBACK_COMMENTS = 3;
export const FEEDBACK_DOCUMENT_EXTENSIONS = [".doc", ".docx", ".pdf", ".rtf", ".txt", ".odt", ".xls", ".xlsx", ".xlsm", ".xlsb"];

export type PrioritizedFeedback = {
  priority?: FeedbackPriority;
  created_at: string;
};

export function feedbackPriority(item: Pick<PrioritizedFeedback, "priority">): FeedbackPriority {
  return item.priority === 1 || item.priority === 3 ? item.priority : 2;
}

export function compareFeedbackPriority(left: PrioritizedFeedback, right: PrioritizedFeedback): number {
  return feedbackPriority(left) - feedbackPriority(right)
    || new Date(right.created_at).getTime() - new Date(left.created_at).getTime();
}

export function visibleFeedbackComments<T>(comments: T[], expanded: boolean): T[] {
  return expanded ? comments : comments.slice(0, DEFAULT_VISIBLE_FEEDBACK_COMMENTS);
}

export function hiddenFeedbackCommentCount(comments: unknown[], expanded: boolean): number {
  return Math.max(0, comments.length - visibleFeedbackComments(comments, expanded).length);
}

export function isFeedbackDocumentName(name: string): boolean {
  const normalized = name.toLocaleLowerCase("tr-TR");
  return FEEDBACK_DOCUMENT_EXTENSIONS.some((extension) => normalized.endsWith(extension));
}

