import type { PlanningSeed } from "./planning";
import type { DownstreamProcess, ProcessKind, ProductFamily } from "./process-master-data";

export type FlowRule = {
  id: string;
  family: ProductFamily;
  from: ProcessKind;
  to: DownstreamProcess | "delivery";
  mode: "dynamic" | "static";
  minutes: number;
  description: string;
  active: boolean;
};
export type FlowSetup = { first: number; sameProduct: number; sameKey: number; differentKey: number; differentFamily: number };
export type FlowSettings = {
  version: 1;
  enabled: boolean;
  department: "piston";
  defaultShifts: number;
  shiftOverrides: Array<{ date: number; shifts: number }>;
  rules: FlowRule[];
  setupMinutes: Record<"drilling" | "deburring" | "gkm", FlowSetup>;
};

/** User decision 2026-10-17: eight working hours for both Piston washing transitions. */
export const WASHING_WAIT_MINUTES = 480;
/** Earlier shipped default; a saved value equal to it was never chosen by the planner. */
export const LEGACY_WASHING_WAIT_MINUTES = 720;
const WASHING_RULE_IDS = ["piston-washing", "center-washing"];

export function defaultFlowSettings(): FlowSettings {
  const rule = (id: string, family: ProductFamily, from: ProcessKind, to: FlowRule["to"], mode: FlowRule["mode"], minutes: number, description: string): FlowRule => ({ id, family, from, to, mode, minutes, description, active: true });
  return { version: 1, enabled: false, department: "piston", defaultShifts: 2, shiftOverrides: [], rules: [
    rule("piston-turning", "piston", "turning", "drilling", "dynamic", 120, "Torna → Delme bitiş farkı hedefi"),
    rule("center-turning", "center-pin", "turning", "drilling", "dynamic", 120, "Torna → Delme bitiş farkı hedefi"),
    rule("piston-drilling", "piston", "drilling", "deburring", "dynamic", 120, "Delme → Çapak Alma bitiş farkı hedefi"),
    rule("piston-washing", "piston", "deburring", "gkm", "static", WASHING_WAIT_MINUTES, "Yıkama / Fosfat"),
    rule("center-washing", "center-pin", "drilling", "gkm", "static", WASHING_WAIT_MINUTES, "Yıkama / Fosfat"),
    rule("piston-delivery", "piston", "gkm", "delivery", "static", 480, "Paketleme / Final Kontrol"),
    rule("center-delivery", "center-pin", "gkm", "delivery", "static", 480, "Paketleme / Final Kontrol"),
  ], setupMinutes: {
    drilling: { first: 180, sameProduct: 0, sameKey: 60, differentKey: 180, differentFamily: 300 },
    deburring: { first: 60, sameProduct: 0, sameKey: 60, differentKey: 60, differentFamily: 60 },
    gkm: { first: 0, sameProduct: 0, sameKey: 0, differentKey: 0, differentFamily: 0 },
  } };
}

export function validateFlowSettings(value: unknown): FlowSettings {
  const fail = (): never => { throw new Error("Akış ayarları geçersiz. Süreler 0–10080 dakika, vardiyalar 0–3 olmalı; aynı geçiş için yalnızca bir etkin kural kullanılabilir."); };
  if (!value || typeof value !== "object") return fail();
  const v = value as FlowSettings;
  const shifts = (n: number) => Number.isInteger(n) && n >= 0 && n <= 3;
  const minutes = (n: number) => typeof n === "number" && Number.isFinite(n) && n >= 0 && n <= 10080;
  if (v.version !== 1 || v.department !== "piston" || typeof v.enabled !== "boolean" || !shifts(v.defaultShifts) || !Array.isArray(v.rules) || v.rules.length > 100 || !Array.isArray(v.shiftOverrides) || v.shiftOverrides.length > 3660) return fail();
  const dates = new Set<number>();
  for (const item of v.shiftOverrides) {
    if (!item || !Number.isInteger(item.date) || item.date <= 0 || item.date > 2958465 || !shifts(item.shifts) || dates.has(item.date)) return fail();
    dates.add(item.date);
  }
  const ids = new Set<string>(), transitions = new Set<string>();
  const order = ["turning", "drilling", "deburring", "gkm", "delivery"];
  for (const rule of v.rules) {
    if (!rule || typeof rule.id !== "string" || !rule.id.trim() || ids.has(rule.id) || !["piston", "center-pin"].includes(rule.family) || !["dynamic", "static"].includes(rule.mode) || typeof rule.active !== "boolean" || typeof rule.description !== "string" || rule.description.length > 500 || !minutes(rule.minutes) || order.indexOf(rule.from) < 0 || order.indexOf(rule.from) >= 4 || order.indexOf(rule.to) <= order.indexOf(rule.from) || rule.to === "delivery" && rule.mode !== "static") return fail();
    ids.add(rule.id);
    const key = `${rule.family}:${rule.from}:${rule.to}`;
    if (rule.active && transitions.has(key)) return fail();
    if (rule.active) transitions.add(key);
  }
  for (const process of ["drilling", "deburring", "gkm"] as const) {
    const setup = v.setupMinutes?.[process];
    if (!setup || !["first", "sameProduct", "sameKey", "differentKey", "differentFamily"].every(key => minutes(setup[key as keyof FlowSetup]))) return fail();
  }
  return structuredClone(v);
}

/**
 * Authoritative Piston transition rule. When Akış Ayarı is enabled, an active
 * matching rule decides the wait for that transition (working hours or finish
 * gap). Only a transition without such a rule uses Proses bekleme süreleri
 * (whole workdays). One transition never receives both waits.
 */
export function flowRule(seed: Pick<PlanningSeed, "flowSettings" | "productionArea">, family: ProductFamily, from: ProcessKind, to: FlowRule["to"]): FlowRule | undefined {
  return seed.productionArea !== "cubuk-filtre" && seed.flowSettings?.enabled ? seed.flowSettings.rules.find(rule => rule.active && rule.family === family && rule.from === from && rule.to === to) : undefined;
}

/** Saved washing rules that still hold the old 720-minute default (twelve working hours). */
export function legacyWashingRules(settings: FlowSettings | undefined): FlowRule[] {
  return (settings?.rules ?? []).filter(rule => WASHING_RULE_IDS.includes(rule.id) && rule.mode === "static" && rule.minutes === LEGACY_WASHING_WAIT_MINUTES);
}

/**
 * Explicit planner action: adopt eight working hours for washing rules that
 * still hold the old default. Other values are planner choices and stay.
 * Never runs on load; saving marks the plan stale like any settings edit.
 */
export function adoptEightHourWashing(settings: FlowSettings): { settings: FlowSettings; changedRuleIds: string[] } {
  const next = validateFlowSettings(settings);
  const changed = legacyWashingRules(next).map(rule => rule.id);
  next.rules = next.rules.map(rule => changed.includes(rule.id) ? { ...rule, minutes: WASHING_WAIT_MINUTES } : rule);
  return { settings: next, changedRuleIds: changed };
}

export type EffectiveWaitSource = {
  family: "piston" | "center-pin";
  from: ProcessKind;
  to: DownstreamProcess | "delivery";
  source: "Akış Ayarı" | "Proses bekleme süreleri" | "Bekleme yok";
  mode: "dynamic" | "static" | "workdays" | "none";
  minutes?: number;
  workdays?: number;
  label: string;
};

/** One row per Piston route transition: which saved setting is in force and its unit. */
export function effectiveWaitSources(seed: Pick<PlanningSeed, "flowSettings" | "productionArea" | "processWaitSettings">): EffectiveWaitSource[] {
  if (seed.productionArea === "cubuk-filtre") return [];
  const transitions: Array<[EffectiveWaitSource["family"], ProcessKind, EffectiveWaitSource["to"]]> = [
    ["piston", "turning", "drilling"], ["piston", "drilling", "deburring"], ["piston", "deburring", "gkm"], ["piston", "gkm", "delivery"],
    ["center-pin", "turning", "drilling"], ["center-pin", "drilling", "gkm"], ["center-pin", "gkm", "delivery"],
  ];
  return transitions.map(([family, from, to]) => {
    const rule = flowRule(seed, family, from, to);
    if (rule) return { family, from, to, source: "Akış Ayarı", mode: rule.mode, minutes: rule.minutes,
      label: rule.mode === "dynamic" ? `Bitiş farkı hedefi ${rule.minutes / 60} saat` : `${rule.minutes / 60} çalışma saati` };
    const item = seed.processWaitSettings?.[from as keyof NonNullable<PlanningSeed["processWaitSettings"]>];
    if (item?.enabled && item.workdays > 0) return { family, from, to, source: "Proses bekleme süreleri", mode: "workdays", workdays: item.workdays, label: `${item.workdays} iş günü` };
    return { family, from, to, source: "Bekleme yok", mode: "none", label: "Önceki proses bitişi" };
  });
}

/** Department waiting capacity is independent of an individual machine's maintenance. */
export function addDepartmentWorkMinutes(seed: Pick<PlanningSeed, "flowSettings" | "setupSettings" | "holidays">, start: number, minutes: number): number {
  if (!minutes) return start;
  const settings = seed.flowSettings!;
  const shiftHours = Math.max(1, Math.min(24, seed.setupSettings?.shiftHours ?? 8));
  let cursor = start, remaining = minutes;
  for (let guard = 0; guard < 36600; guard += 1) {
    const day = Math.floor(cursor);
    const sunday = new Date(Date.UTC(1899, 11, 30) + day * 86400000).getUTCDay() === 0;
    const holiday = seed.holidays.find(item => Math.floor(item.serial) === day);
    const override = settings.shiftOverrides.find(item => item.date === day);
    const shifts = override?.shifts ?? (holiday ? holiday.workingShifts ?? 0 : sunday ? 0 : settings.defaultShifts);
    const end = day + Math.min(24, shifts * shiftHours) / 24;
    const available = Math.max(0, end - cursor) * 1440;
    if (available + 1e-7 >= remaining) return cursor + remaining / 1440;
    remaining -= available;
    cursor = day + 1;
  }
  throw new Error("Piston bölümü için çalışılabilir bekleme saati bulunamadı. Vardiya ve Mesai Bilgileri’ni kontrol edin.");
}

