import { formatExcelDate, isMachineEligibleForProduct, moveBatchManually, type PlannedBatch, type PlanningSeed, type ScenarioResult } from "./planning";

export type MachineDiagnosticCode = "scheduled" | "inactive" | "stale" | "empty-plan" | "zero-capacity" | "invalid-window" | "no-compatible-order" | "missing-speed" | "parallel-opportunity" | "assigned-by-priority" | "window-limit" | "demand-covered";
export type MachineMoveSuggestion = {
  batchId: string;
  product: string;
  fromMachineId: string;
  toMachineId: string;
  originalCompletion: number;
  alternativeCompletion: number;
  alternativeBatchEnd: number;
  improvementDays: number;
};
export type MachineDiagnostic = {
  code: MachineDiagnosticCode;
  tone: "good" | "neutral" | "warning" | "critical";
  title: string;
  detail: string;
  products: string[];
  suggestion?: MachineMoveSuggestion;
};

export function buildMachineDiagnostics(seed: PlanningSeed, result: ScenarioResult, options: { dirty?: boolean } = {}): Record<string, MachineDiagnostic> {
  const diagnostics: Record<string, MachineDiagnostic> = {};
  const orderedProductCodes = [...new Set(seed.orders.filter((order) => order.quantity > 0).map((order) => order.product.toUpperCase()))];

  for (const machine of seed.machines) {
    const planned = result.batches.filter((batch) => batch.status === "planned" && batch.machineId === machine.id);
    if (!machine.active) {
      diagnostics[machine.id] = diagnostic("inactive", "neutral", "Planlama dışında", "Tezgah pasif olduğu için motor bu tezgaha yeni iş atamadı.");
      continue;
    }
    if (options.dirty) {
      diagnostics[machine.id] = diagnostic("stale", "warning", "Plan yeniden çalıştırılmalı", "Girdiler değiştiği için ekrandaki kuyruk artık güncel planı temsil etmiyor.");
      continue;
    }
    if (planned.length) {
      diagnostics[machine.id] = diagnostic("scheduled", "good", `${planned.length} planlı şarj`, `${planned[0].product} ile başlayan kuyruk ${formatExcelDate(planned.at(-1)?.end ?? 0)} tarihinde tamamlanıyor.`, [...new Set(planned.map((batch) => batch.product))]);
      continue;
    }
    if (result.state === "empty") {
      diagnostics[machine.id] = diagnostic("empty-plan", "neutral", "Plan henüz çalıştırılmadı", "Bu tezgah için uygunluk ve kapasite değerlendirmesi henüz yapılmadı.");
      continue;
    }
    if (machine.shiftFactor <= 0 || machine.capacityFactor <= 0) {
      diagnostics[machine.id] = diagnostic("zero-capacity", "critical", "Kullanılabilir kapasite yok", `Vardiya sayısı ${machine.shiftFactor}, kapasite katsayısı ${machine.capacityFactor}. Bu değerlerle günlük üretim sıfırdır.`);
      continue;
    }
    if (machine.availableStart >= machine.planEnd || machine.currentJob.end >= machine.planEnd) {
      diagnostics[machine.id] = diagnostic("invalid-window", "critical", "Planlama penceresi kapalı", `Tezgahın mevcut iş bitişi veya müsait başlangıcı, ${formatExcelDate(machine.planEnd)} plan bitişine ulaşıyor.`);
      continue;
    }

    const compatible = orderedProductCodes.filter((code) => isMachineEligibleForProduct(seed, machine.id, code));
    if (!compatible.length) {
      diagnostics[machine.id] = diagnostic("no-compatible-order", "warning", "Uygun açık sipariş yok", "Mevcut ürün–tezgah kurallarına göre bu tezgaha atanabilecek sipariş bulunamadı.");
      continue;
    }
    const rated = compatible.filter((code) => (machine.rates[code] ?? 0) > 0);
    if (!rated.length) {
      diagnostics[machine.id] = diagnostic("missing-speed", "critical", "Üretim hızı eksik", `${summarizeProducts(compatible)} bu tezgaha uygun; ancak ürün × tezgah üretim hızı tanımlı değil. Parametreler ekranında ürünün tezgah satırındaki “Değiştir” ile günlük üretimi girip kaydedin, ardından planı yeniden çalıştırın.`, compatible);
      continue;
    }

    const feasibleMoves = result.batches
      .filter((batch) => batch.status === "planned" && batch.machineId !== machine.id && rated.includes(batch.product.toUpperCase()))
      .map((batch) => simulateMove(seed, result, batch, machine.id))
      .filter((suggestion): suggestion is MachineMoveSuggestion => suggestion !== null)
      .sort((left, right) => right.improvementDays - left.improvementDays || left.alternativeCompletion - right.alternativeCompletion);
    const bestMove = feasibleMoves[0];
    if (bestMove?.improvementDays > 0) {
      const preference = seed.preferences.find((rule) => rule.key.toUpperCase() === bestMove.product.toUpperCase());
      const priorityExplanation = preference
        ? `${bestMove.fromMachineId}, tercih sırasında ${machine.id} tezgahından önce geldiği için motor ilk uygun atamada durdu.`
        : "Motor ilk uygun atamada durduğu için alternatif bitiş tarihlerini karşılaştırmadı.";
      diagnostics[machine.id] = {
        ...diagnostic("parallel-opportunity", "warning", "Daha erken bitiş fırsatı var", `${bestMove.product} şarjı ${bestMove.fromMachineId} yerine ${machine.id} tezgahına alınabilir. Ürünün tamamlanması ${formatExcelDate(bestMove.originalCompletion)} yerine ${formatExcelDate(bestMove.alternativeCompletion)} olur (${bestMove.improvementDays} takvim günü erken). ${priorityExplanation}`, [bestMove.product]),
        suggestion: bestMove,
      };
      continue;
    }
    if (bestMove) {
      diagnostics[machine.id] = {
        ...diagnostic("assigned-by-priority", "neutral", "Öncelik sırası başka tezgahı seçti", `${bestMove.product} şarjı teknik olarak ${machine.id} tezgahına sığıyor; ancak tam ürün bitişi ${formatExcelDate(bestMove.originalCompletion)} tarihinden daha erkene gelmiyor. Motor bu nedenle değil, sabit aday sırasındaki ilk uygun tezgahı seçti.`, [bestMove.product]),
        suggestion: bestMove,
      };
      continue;
    }

    const unmet = rated.filter((code) => result.orders.some((order) => order.product.toUpperCase() === code && order.difference < 0)
      || result.batches.some((batch) => batch.status === "unplanned" && batch.product.toUpperCase() === code));
    if (unmet.length) {
      diagnostics[machine.id] = diagnostic("window-limit", "warning", "Uygun iş pencereye sığmadı", `${summarizeProducts(unmet)} üretilebilir; ancak vardiya, mevcut iş bitişi veya plan sonu nedeniyle yeni şarj yerleşmedi.`, unmet);
      continue;
    }

    diagnostics[machine.id] = diagnostic("demand-covered", "neutral", "Talep diğer kuyruklarda karşılandı", `${summarizeProducts(rated)} üretilebilir; mevcut motor talebi diğer uygun tezgahlarda karşıladı. Paralel kullanımın termin kazancı henüz karşılaştırılmıyor.`, rated);
  }
  return diagnostics;
}

function diagnostic(code: MachineDiagnosticCode, tone: MachineDiagnostic["tone"], title: string, detail: string, products: string[] = []): MachineDiagnostic {
  return { code, tone, title, detail, products };
}

function summarizeProducts(products: string[]): string {
  const visible = products.slice(0, 3).join(", ");
  return products.length > 3 ? `${visible} ve ${products.length - 3} ürün daha` : visible;
}

function simulateMove(seed: PlanningSeed, result: ScenarioResult, batch: PlannedBatch, targetMachineId: string): MachineMoveSuggestion | null {
  try {
    const alternative = moveBatchManually(seed, result, batch.id, targetMachineId, 0);
    const originalCompletion = productCompletion(seed, result, batch.product);
    const alternativeCompletion = productCompletion(seed, alternative, batch.product);
    const moved = alternative.batches.find((item) => item.id === batch.id);
    if (!moved) return null;
    return {
      batchId: batch.id,
      product: batch.product,
      fromMachineId: batch.machineId,
      toMachineId: targetMachineId,
      originalCompletion,
      alternativeCompletion,
      alternativeBatchEnd: moved.end,
      improvementDays: Math.max(0, Math.round(originalCompletion - alternativeCompletion)),
    };
  } catch {
    return null;
  }
}

function productCompletion(seed: PlanningSeed, result: ScenarioResult, product: string): number {
  const code = product.toUpperCase();
  return Math.max(
    0,
    ...seed.machines.filter((machine) => machine.currentJob.product.toUpperCase() === code).map((machine) => machine.currentJob.end),
    ...result.batches.filter((batch) => batch.status === "planned" && batch.product.toUpperCase() === code).map((batch) => batch.end),
  );
}

