import { addProductType, validateNewProductTypeDraft, type NewProductTypeDraft } from "./parameters";
import type { PlanningSeed } from "./planning";
import { PRODUCT_PROCESS_ORDER, processLabel, resourceSupportsProcessProduct, type DownstreamProcess, type ProcessKind, type ProcessProduct } from "./process-master-data";
import { validateProductWeights, type ProductWeight } from "./product-weights";

export type NewProcessDraft = { active: boolean; setupKey: string; waitWorkdaysBefore: string; resources: string[]; unitsPerShift: Record<string, string> };
export type NewTypeWizardDraft = NewProductTypeDraft & {
  turningEnabled: boolean;
  processes: Record<DownstreamProcess, NewProcessDraft>;
  materialCode: string; materialName: string; productName: string; grams: string;
};
export const NEW_TYPE_STEPS = ["Torna parametresi", "Delme parametresi", "Çapak Alma parametresi", "GKM parametresi", "Hammadde bilgileri"];

export function initialNewTypeWizardDraft(): NewTypeWizardDraft {
  const process = (wait: string): NewProcessDraft => ({ active: true, setupKey: "", waitWorkdaysBefore: wait, resources: [], unitsPerShift: {} });
  return { product: "", setupFamily: "", turningEnabled: true, machines: [], machineShiftRates: {}, batchSize: "", diameter: "",
    processes: { drilling: process("0"), deburring: process("0"), gkm: process("0") }, materialCode: "", materialName: "", productName: "", grams: "" };
}

export function validateNewTypeWizard(seed: PlanningSeed, draft: NewTypeWizardDraft) {
  const turning = validateNewProductTypeDraft(seed, draft);
  const errorsByStep: string[][] = [turning.errors.filter(error => !error.includes("hammadde çapı")), [], [], [], turning.errors.filter(error => error.includes("hammadde çapı"))];
  const route = PRODUCT_PROCESS_ORDER.filter(process => process === "turning" ? draft.turningEnabled : draft.processes[process].active);
  if (!route.length) errorsByStep[3].push("En az bir prosesi Aktif seçin.");
  const processProduct: ProcessProduct = { product: turning.product, family: turning.setupFamily ?? "piston", productGroup: turning.setupFamily ?? "piston", route, processes: [] };
  if (!seed.processMasterData) errorsByStep[0].push("Proses ana verisi bulunamadı; verileri yeniden yükleyin.");
  if (seed.processMasterData?.products.some(item => item.product.toUpperCase() === turning.product)) errorsByStep[0].push(`${turning.product} için proses kaydı zaten var.`);
  for (const [index, process] of (["drilling", "deburring", "gkm"] as DownstreamProcess[]).entries()) {
    const input = draft.processes[process];
    if (!input.active) continue;
    const errors = errorsByStep[index + 1];
    const wait = Number(input.waitWorkdaysBefore);
    if (!input.setupKey.trim()) errors.push(process === "drilling" ? "Matkap çapı / setup anahtarı girin." : "Setup anahtarı girin.");
    if (!input.waitWorkdaysBefore.trim() || !Number.isSafeInteger(wait) || wait < 0 || wait > 365) errors.push("Önceki prosesten sonra bekleme 0–365 iş günü olmalıdır.");
    if (!input.resources.length) errors.push("En az bir uygun aktif iş merkezi seçin.");
    if (new Set(input.resources).size !== input.resources.length) errors.push("İş merkezi yalnız bir kez seçilebilir.");
    for (const id of input.resources) {
      const resource = seed.processMasterData?.resources.find(item => item.id === id);
      if (!resource || resource.process !== process || !resource.active || resource.defaultShifts <= 0 || !resourceSupportsProcessProduct(resource, processProduct)) errors.push(`${id} seçilen ürün ailesi için uygun aktif bir iş merkezi değil.`);
      const rate = Number(input.unitsPerShift[id]);
      if (!Number.isSafeInteger(rate) || rate <= 0) errors.push(`${id} için Adet / vardiya pozitif tam sayı olmalıdır.`);
    }
    processProduct.processes.push({ process, sequence: index + 1, setupKey: input.setupKey.trim(), waitWorkdaysBefore: wait,
      resourcePriority: [...input.resources], unitsPerShift: Object.fromEntries(input.resources.map(id => [id, Number(input.unitsPerShift[id])])) });
  }
  if (draft.turningEnabled) for (const id of turning.machines) {
    if (!seed.machines.find(machine => machine.id === id)?.active) errorsByStep[0].push(`${id} aktif bir Torna tezgahı değil.`);
  }
  const weight: ProductWeight = { product: turning.product, productName: draft.productName.trim(), materialCode: draft.materialCode.trim().toUpperCase(), materialName: draft.materialName.trim(), grams: draft.grams.trim() ? Number(draft.grams.replace(",", ".")) : null };
  if (!weight.materialCode) errorsByStep[4].push("Hammadde kodu girin.");
  if (!weight.materialName) errorsByStep[4].push("Hammadde açıklaması girin.");
  if (weight.grams === null || !Number.isFinite(weight.grams) || weight.grams <= 0) errorsByStep[4].push("Hammadde ağırlığı (g) sıfırdan büyük olmalıdır.");
  if (seed.productWeights?.some(item => item.product === turning.product)) errorsByStep[4].push(`${turning.product} için hammadde kaydı zaten var; mevcut kaydı kontrol edin.`);
  return { turning, processProduct, weight, route, errorsByStep, errors: errorsByStep.flat() };
}

/** Validate against the latest seed, then publish all five steps together. */
export function createProductTypeFromWizard(seed: PlanningSeed, draft: NewTypeWizardDraft): string {
  const validation = validateNewTypeWizard(seed, draft);
  if (validation.errors.length) throw new Error(validation.errors[0]);
  const next = structuredClone(seed);
  addProductType(next, validation.turning);
  next.processMasterData!.products.push(validation.processProduct);
  next.productWeights = validateProductWeights([...(next.productWeights ?? []), validation.weight]);
  seed.products = next.products;
  seed.preferences = next.preferences;
  seed.machines = next.machines;
  seed.orderCatalog = next.orderCatalog;
  seed.processMasterData = next.processMasterData;
  seed.productWeights = next.productWeights;
  return validation.turning.product;
}

export function newTypeRouteLabel(route: ProcessKind[]): string {
  return route.map(processLabel).join(" → ");
}

