const integerFormatter = new Intl.NumberFormat("tr-TR", { maximumFractionDigits: 0 });

export function formatInteger(value: number): string {
  return integerFormatter.format(value);
}

export function formatDecimal(value: number, maximumFractionDigits = 2): string {
  return new Intl.NumberFormat("tr-TR", { maximumFractionDigits }).format(value);
}

export function formatSignedInteger(value: number): string {
  return `${value > 0 ? "+" : ""}${formatInteger(value)}`;
}

