import { assertParameterTransitionDecided } from "./parameter-deactivation";
import { diameterNumeric, type PlanningSeed, type Product } from "./planning";
import { turningEnabled } from "./process-master-data";
import { normalizeProductSetupFamily, resolvedProductSetupFamily, type ProductSetupFamily } from "./setup-families";

type BaseProductParameterDraft = {
  turningEnabled?: boolean;
  machines: string[];
  inactiveMachineIds?: string[];
  machineShiftRates: Record<string, string>;
  batchSize: string;
  diameter: string;
  setupFamily?: ProductSetupFamily | "";
};

export type ProductParameterDraft = BaseProductParameterDraft & {
  defaultShiftRate: string;
};

export type NewProductTypeDraft = BaseProductParameterDraft & {
  product: string;
};

export type ProductParameterValidation = {
  machines: string[];
  inactiveMachineIds: string[];
  machineShiftRates: Record<string, number>;
  defaultShiftRate: number;
  batchSize: number;
  diameter: string;
  setupFamily?: ProductSetupFamily;
  errors: string[];
  warnings: string[];
};

export type NewProductTypeValidation = ProductParameterValidation & {
  product: string;
};

export const STANDARD_DAILY_SHIFTS = 3;

export type ParameterDiameterOption = {
  value: string;
  label: string;
  productCount: number;
};

export type ParameterFamilyOption = {
  value: ProductSetupFamily;
  label: string;
  productCount: number;
};

export function parameterDiameterOptions(products: Array<Pick<Product, "diameter">>): ParameterDiameterOption[] {
  const counts = new Map<number, number>();
  for (const product of products) {
    const diameter = diameterNumeric(product.diameter);
    if (diameter > 0) counts.set(diameter, (counts.get(diameter) ?? 0) + 1);
  }
  return [...counts.entries()]
    .sort(([left], [right]) => left - right)
    .map(([diameter, productCount]) => ({
      value: String(diameter),
      label: `Ø ${new Intl.NumberFormat("tr-TR", { maximumFractionDigits: 3 }).format(diameter)}`,
      productCount,
    }));
}

export function parameterFamilyOptions(products: Array<Pick<Product, "product" | "setupFamily">>): ParameterFamilyOption[] {
  const counts = new Map<ProductSetupFamily, number>([["piston", 0], ["center-pin", 0]]);
  for (const product of products) {
    const family = resolvedProductSetupFamily(product.product, product.setupFamily);
    if (family) counts.set(family, (counts.get(family) ?? 0) + 1);
  }
  return [
    { value: "piston", label: "Piston", productCount: counts.get("piston") ?? 0 },
    { value: "center-pin", label: "Center Pin", productCount: counts.get("center-pin") ?? 0 },
  ];
}

export function productMatchesParameterFilters(product: Pick<Product, "product" | "diameter" | "setupFamily">, query: string, diameterFilter: string, familyFilter: ProductSetupFamily | "" = ""): boolean {
  const matchesQuery = product.product.toLocaleLowerCase("tr-TR").includes(query.trim().toLocaleLowerCase("tr-TR"));
  const matchesDiameter = !diameterFilter || diameterNumeric(product.diameter) === Number(diameterFilter);
  const matchesFamily = !familyFilter || resolvedProductSetupFamily(product.product, product.setupFamily) === familyFilter;
  return matchesQuery && matchesDiameter && matchesFamily;
}

export function parseMachineTokens(value: string): { machines: string[]; invalid: string[] } {
  const machines: string[] = [];
  const invalid: string[] = [];
  for (const raw of value.split(/[,;\n]/).map((part) => part.trim()).filter(Boolean)) {
    const match = raw.toUpperCase().match(/^C-?(\d{1,2})$/);
    if (!match) {
      invalid.push(raw);
      continue;
    }
    const machine = `C-${String(Number(match[1])).padStart(2, "0")}`;
    if (!machines.includes(machine)) machines.push(machine);
  }
  return { machines, invalid };
}

export function effectiveProductMachines(seed: PlanningSeed, product: Product): string[] {
  return seed.preferences.find((rule) => rule.key.toUpperCase() === product.product.toUpperCase())?.machines
    ?? product.eligibleMachines
    ?? product.alternativeMachines;
}

export function productParameterDraft(seed: PlanningSeed, product: Product): ProductParameterDraft {
  const machines = [...effectiveProductMachines(seed, product)];
  return {
    turningEnabled: turningEnabled(seed.processMasterData, product.product),
    machines,
    inactiveMachineIds: machines.filter((machineId) => product.inactiveMachineIds?.includes(machineId)),
    machineShiftRates: Object.fromEntries(machines.map((machineId) => {
      const machine = seed.machines.find((item) => item.id === machineId);
      const shiftRate = machine?.rates[product.product.toUpperCase()] ?? product.shiftRate;
      return [machineId, String(shiftRate > 0 ? shiftRate : product.dailyRate / STANDARD_DAILY_SHIFTS)];
    })),
    defaultShiftRate: String(product.dailyRate / STANDARD_DAILY_SHIFTS),
    batchSize: String(product.batchSize),
    diameter: product.diameter,
    setupFamily: resolvedProductSetupFamily(product.product, product.setupFamily) ?? "",
  };
}

export function missingTurningParameterProducts(seed: PlanningSeed): Product[] {
  const configured = new Set(seed.products.map((item) => item.product.toUpperCase()));
  return (seed.processMasterData?.products ?? [])
    .filter((item) => !configured.has(item.product.toUpperCase()) && turningEnabled(seed.processMasterData, item.product))
    .map((item) => ({
      product: item.product,
      setupFamily: resolvedProductSetupFamily(item.product, item.family),
      generalMachine: "",
      eligibleMachines: [],
      alternativeMachines: [],
      batchSize: 0,
      dailyRate: 0,
      shiftRate: 0,
      parameterDailyRate: 0,
      diameter: "",
      moq: 0,
      source: "Torna parametresi bekliyor",
    }));
}

export function addTurningParametersForExistingProcessProduct(seed: PlanningSeed, productCode: string, validation: ProductParameterValidation): Product {
  const code = productCode.trim().toUpperCase();
  const processProduct = seed.processMasterData?.products.find((item) => item.product.toUpperCase() === code);
  if (!processProduct) throw new Error(`${code} için proses kaydı bulunamadı.`);
  if (!turningEnabled(seed.processMasterData, code)) throw new Error(`${code} için Torna prosesi Pasif.`);
  if (seed.products.some((item) => item.product.toUpperCase() === code)) throw new Error(`${code} için Torna parametresi zaten var.`);
  if (validation.setupFamily !== processProduct.family) throw new Error("Ürün ailesi mevcut proses kaydıyla eşleşmelidir.");
  if (validation.errors.length) throw new Error(validation.errors[0]);
  return addProductType(seed, { ...validation, product: code });
}

export function productParametersReady(seed: PlanningSeed, productCode: string): boolean {
  const product = seed.products.find((item) => item.product.toUpperCase() === productCode.trim().toUpperCase());
  if (!product || !resolvedProductSetupFamily(product.product, product.setupFamily)) return false;
  if (!Number.isInteger(product.batchSize) || product.batchSize <= 0 || diameterNumeric(product.diameter) <= 0) return false;
  if (!turningEnabled(seed.processMasterData, productCode)) return true;
  const machines = effectiveProductMachines(seed, product);
  return machines.some((machineId) => {
    if (product.inactiveMachineIds?.includes(machineId)) return false;
    const machine = seed.machines.find((item) => item.id === machineId);
    return Boolean(machine && (machine.rates[product.product.toUpperCase()] ?? 0) > 0);
  });
}

export function validateProductParameterDraft(seed: PlanningSeed, product: Product, draft: BaseProductParameterDraft & { defaultShiftRate?: string }): ProductParameterValidation {
  const turning = draft.turningEnabled !== false;
  const machines = turning ? [...new Set(draft.machines.map((machine) => machine.toUpperCase()))] : [];
  const inactiveMachineIds = machines.filter((machineId) => draft.inactiveMachineIds?.includes(machineId));
  const knownMachines = new Set(seed.machines.map((machine) => machine.id));
  const unknown = machines.filter((machine) => !knownMachines.has(machine));
  const batchSize = Number(draft.batchSize);
  const diameter = draft.diameter.trim();
  const setupFamily = normalizeProductSetupFamily(draft.setupFamily) ?? resolvedProductSetupFamily(product.product, product.setupFamily);
  const machineShiftRates = Object.fromEntries(machines.map((machineId) => [machineId, Number(draft.machineShiftRates[machineId])]));
  const defaultShiftRate = turning ? Number(draft.defaultShiftRate ?? (product.dailyRate > 0 ? product.dailyRate / STANDARD_DAILY_SHIFTS : draft.machineShiftRates[machines[0]])) : 0;
  const errors: string[] = [];
  const warnings: string[] = [];

  if (unknown.length) errors.push(`Tanımsız tezgah: ${unknown.join(", ")}`);
  if (turning && !machines.length) errors.push("En az bir planlanabilir tezgah seçin.");
  const invalidRates = machines.filter((machineId) => !Number.isFinite(machineShiftRates[machineId] * STANDARD_DAILY_SHIFTS) || machineShiftRates[machineId] <= 0);
  if (invalidRates.length) errors.push(`${invalidRates.join(", ")} için vardiyalık üretim adedi pozitif ve sonlu olmalıdır.`);
  if (turning && (!Number.isFinite(defaultShiftRate * STANDARD_DAILY_SHIFTS) || defaultShiftRate <= 0)) errors.push("Varsayılan vardiyalık üretim adedi pozitif ve sonlu olmalıdır.");
  if (!Number.isInteger(batchSize) || batchSize <= 0) errors.push("Şarj büyüklüğü pozitif bir tam sayı olmalıdır.");
  if (diameterNumeric(diameter) <= 0) errors.push("Geçerli bir hammadde çapı girin.");
  if (!setupFamily) errors.push("Ürün ailesini piston veya Center Pin olarak seçin.");

  return { machines, inactiveMachineIds, machineShiftRates, defaultShiftRate, batchSize, diameter, setupFamily, errors, warnings };
}

export function applyProductParameterDraft(seed: PlanningSeed, productCode: string, validation: ProductParameterValidation): void {
  if (validation.errors.length) throw new Error(validation.errors[0]);
  // Work on a copy so a rejected transition leaves the caller's seed byte-identical.
  const candidate = JSON.parse(JSON.stringify(seed)) as PlanningSeed;
  applyProductParameterDraftUnchecked(candidate, productCode, validation);
  assertParameterTransitionDecided(seed, candidate);
  // Checked on a copy first; the caller's objects are then updated in place.
  applyProductParameterDraftUnchecked(seed, productCode, validation);
}

function applyProductParameterDraftUnchecked(seed: PlanningSeed, productCode: string, validation: ProductParameterValidation): void {
  if (!validation.setupFamily) throw new Error("Ürün ailesini seçin.");
  const product = seed.products.find((item) => item.product.toUpperCase() === productCode.toUpperCase());
  if (!product) throw new Error(`${productCode} ürünü bulunamadı.`);

  product.eligibleMachines = [...validation.machines];
  product.inactiveMachineIds = [...validation.inactiveMachineIds];
  product.alternativeMachines = [...validation.machines];
  product.generalMachine = validation.machines[0] ?? "";
  product.batchSize = validation.batchSize;
  // Persisted daily fields keep their three-shift units for existing plans/backups.
  product.dailyRate = validation.defaultShiftRate * STANDARD_DAILY_SHIFTS;
  product.shiftRate = validation.defaultShiftRate;
  product.parameterDailyRate = product.dailyRate;
  product.diameter = validation.diameter;
  product.setupFamily = validation.setupFamily;
  for (const machineId of validation.machines) {
    const machine = seed.machines.find((item) => item.id === machineId);
    if (machine) machine.rates[product.product.toUpperCase()] = validation.machineShiftRates[machineId];
  }

  const preference = seed.preferences.find((rule) => rule.key.toUpperCase() === product.product.toUpperCase());
  if (preference) {
    preference.machines = [...validation.machines];
    preference.ruleType = "Ürün parametresi";
    preference.description = "Parametreler ekranındaki planlanabilir tezgah sırası";
    preference.source = "Web Parametreleri";
  } else {
    seed.preferences.push({
      key: product.product,
      machines: [...validation.machines],
      ruleType: "Ürün parametresi",
      description: "Parametreler ekranındaki planlanabilir tezgah sırası",
      source: "Web Parametreleri",
    });
  }
}

export function validateNewProductTypeDraft(seed: PlanningSeed, draft: NewProductTypeDraft): NewProductTypeValidation {
  const product = draft.product.trim().toUpperCase();
  const placeholder: Product = {
    product: product || "YENI-TIP",
    setupFamily: normalizeProductSetupFamily(draft.setupFamily),
    generalMachine: "",
    eligibleMachines: [],
    batchSize: 0,
    dailyRate: 0,
    shiftRate: 0,
    parameterDailyRate: 0,
    diameter: "",
    alternativeMachines: [],
    moq: 0,
    source: "Web Parametreleri",
  };
  const validation = validateProductParameterDraft(seed, placeholder, draft);
  const errors = [...validation.errors];

  if (!product) errors.unshift("Tip numarası zorunludur.");
  else if (product.length > 48) errors.unshift("Tip numarası en fazla 48 karakter olabilir.");
  else if (!/^[A-Z0-9._/-]+$/.test(product)) errors.unshift("Tip numarasında yalnızca harf, rakam, nokta, tire, alt çizgi ve / kullanılabilir.");
  if (seed.products.some((item) => item.product.toUpperCase() === product)) errors.unshift(`${product} zaten parametrelerde tanımlı.`);

  return { ...validation, product, errors };
}

export function addProductType(seed: PlanningSeed, validation: NewProductTypeValidation): Product {
  if (validation.errors.length) throw new Error(validation.errors[0]);
  const primaryShiftRate = validation.machineShiftRates[validation.machines[0]] ?? 0;
  const currentCatalog = seed.orderCatalog?.length ? seed.orderCatalog : seed.products.map((item) => item.product);
  const product: Product = {
    product: validation.product,
    setupFamily: validation.setupFamily,
    generalMachine: validation.machines[0] ?? "",
    eligibleMachines: [...validation.machines],
    batchSize: validation.batchSize,
    dailyRate: primaryShiftRate * STANDARD_DAILY_SHIFTS,
    shiftRate: primaryShiftRate,
    parameterDailyRate: primaryShiftRate * STANDARD_DAILY_SHIFTS,
    diameter: validation.diameter,
    alternativeMachines: [...validation.machines],
    moq: validation.batchSize,
    source: "Web Parametreleri",
  };

  seed.products.push(product);
  applyProductParameterDraft(seed, product.product, validation);
  seed.orderCatalog = [...new Set([...currentCatalog, product.product])];
  return product;
}

export function addUnconfiguredProductType(seed: PlanningSeed, productCode: string, setupFamily: ProductSetupFamily): Product {
  const product = productCode.trim().toUpperCase();
  const existing = seed.products.find((item) => item.product.toUpperCase() === product);
  if (existing) {
    existing.setupFamily = setupFamily;
    return existing;
  }
  const created: Product = {
    product,
    setupFamily,
    generalMachine: "",
    eligibleMachines: [],
    batchSize: 0,
    dailyRate: 0,
    shiftRate: 0,
    parameterDailyRate: 0,
    diameter: "",
    alternativeMachines: [],
    moq: 0,
    source: "Siparişler · parametre bekliyor",
  };
  seed.products.push(created);
  return created;
}

