import { withInterruptedBatches } from "./production-interruptions";
import {
  excelSerialToDate,
  isMachineEligibleForProduct,
  runOptimizedScenario,
  retainRouteCommitments,
  type OptimizationGoal,
  type PlannedBatch,
  type PlanningSeed,
  type PlanRunMetadata,
  type PlanRunRange,
  type PlanRunSequence,
  type ScenarioResult,
  type ShortageExtraChargePolicy,
  type DeliveryDeductionFilter,
  type DeliveryDeductionSnapshot,
  normalizeShortageExtraChargePolicy,
} from "./planning";
import { calculateDeliveryDeduction, orderImportMetadataForSeed, type DeliveryDeductionPreview } from "./delivery-deduction";
import { assertDeliveryCoverageReviewed, reviewDeliveryCoverage } from "./delivery-coverage-review";
import { buildCapacityReport } from "./capacity-analytics";
import { assertPlanInputs, assertPlanResult } from "./plan-integrity";
import {
  buildWeeklyPlanningState,
  previewFromDataset,
  resolvePlanningWeekRanges,
  weekScopeForPlanningMonthRange,
  type PlanningMonthRange,
  type PlanningWeekRange,
} from "./weekly-demand";

export type PlanRunRequest = {
  optimizationGoal: OptimizationGoal;
  appendToExistingPlan?: boolean;
  includePriorBacklog?: boolean;
  allowProductionBeforeScope?: boolean;
  weekRanges?: PlanningWeekRange[];
  monthRange?: PlanningMonthRange;
  productionStartDate?: string;
  productionEndDate?: string;
  shortageExtraCharge?: ShortageExtraChargePolicy;
  deliveryDeduction?: Omit<DeliveryDeductionFilter, "endAt">;
  reviewedDeliveryCoverageKey?: string;
};

export type PreparedPlanRun = {
  seed: PlanningSeed;
  stages: PlanningSeed[];
  metadata: PlanRunMetadata;
  scopeLabel: string;
  sequence?: PlanRunSequence;
  deliveryPreview?: DeliveryDeductionPreview;
};

export type PlanStageExecution = {
  seed: PlanningSeed;
  result: ScenarioResult;
  sequence: PlanRunSequence;
  completedRange: PlanRunRange;
  nextRange?: PlanRunRange;
};

export type PlanComparisonRow = {
  goal: OptimizationGoal;
  result: ScenarioResult;
  onTimeShortage: number;
  loadSpread: number;
  recommended: boolean;
};

type CustomerPlanPolicy = {
  includePriorBacklog: boolean;
  allowProductionBeforeScope: boolean;
  shortageExtraCharge: ShortageExtraChargePolicy;
  deliveryDeductionFilter?: DeliveryDeductionFilter;
};

export const PLAN_ENGINE_VERSION = 6;
export function planRequiresRecalculation(seed: PlanningSeed): boolean {
  return Boolean(seed.planNeedsRecalculation
    || (seed.activePlanRun && seed.activePlanRun.engineVersion !== PLAN_ENGINE_VERSION)
    || (seed.manualBatches?.length && !seed.activePlanRun));
}
const GOALS: OptimizationGoal[] = ["earliest-finish", "minimum-setup", "balanced"];

function clone<T>(value: T): T {
  return JSON.parse(JSON.stringify(value)) as T;
}

function inputDateToSerial(value: string): number {
  if (!value) return 0;
  const timestamp = Date.parse(`${value}T00:00:00Z`);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value) || !Number.isFinite(timestamp) || new Date(timestamp).toISOString().slice(0, 10) !== value) return Number.NaN;
  return (timestamp - Date.UTC(1899, 11, 30)) / 86_400_000;
}

function formatDate(value: string): string {
  if (!value) return "—";
  return new Intl.DateTimeFormat("tr-TR", { day: "2-digit", month: "short", year: "numeric", timeZone: "UTC" })
    .format(new Date(`${value}T00:00:00Z`));
}

export function optimizationGoalLabel(value: OptimizationGoal): string {
  return value === "all-compatible"
    ? "Tüm uygun tezgahlar"
    : value === "coarse"
      ? "Standart planlama"
    : value === "balanced"
      ? "Dengeli planlama"
    : value === "minimum-setup"
      ? "Minimum setup"
      : "En erken bitiş";
}

function metadataForCompletedRanges(
  optimizationGoal: OptimizationGoal,
  ranges: PlanRunRange[],
  policy: CustomerPlanPolicy,
  planId: string,
  version: number,
  createdAt: string,
  deliveryDeduction?: DeliveryDeductionSnapshot,
): PlanRunMetadata {
  const first = ranges[0];
  const last = ranges.at(-1);
  if (!first || !last) throw new Error("Planlama için tamamlanmış hafta aralığı bulunamadı.");
  return {
    planId,
    version,
    engineVersion: PLAN_ENGINE_VERSION,
    optimizationGoal,
    includePriorBacklog: policy.includePriorBacklog,
    allowProductionBeforeScope: policy.allowProductionBeforeScope,
    shortageExtraCharge: { ...policy.shortageExtraCharge },
    deliveryDeduction,
    scope: {
      kind: "customer-weeks",
      startDate: first.startDate,
      endDate: last.endDate,
      label: ranges.map((range, index) => `${index + 1}. ${range.label}`).join(" · "),
      startWeekId: first.startWeekId,
      endWeekId: last.endWeekId,
      ranges: ranges.map((range) => ({ ...range })),
    },
    createdAt,
  };
}

function customerStageSeed(
  seed: PlanningSeed,
  allRanges: PlanRunRange[],
  completedRangeCount: number,
  optimizationGoal: OptimizationGoal,
  policy: CustomerPlanPolicy,
  sequenceCreatedAt: string,
  updatedAt: string,
): { seed: PlanningSeed; metadata: PlanRunMetadata; sequence?: PlanRunSequence; deliveryPreview?: DeliveryDeductionPreview } {
  if (!seed.customerDemand) throw new Error("Aşamalı planlama için müşteri hafta verisi bulunamadı.");
  if (completedRangeCount < 1 || completedRangeCount > allRanges.length) throw new Error("Planlama aralığı sırası geçersiz.");
  const completedRanges = allRanges.slice(0, completedRangeCount);
  const first = completedRanges[0];
  const last = completedRanges.at(-1)!;
  const stageSeed = clone(seed);
  const state = buildWeeklyPlanningState(
    previewFromDataset(seed.customerDemand),
    seed.orders,
    { startWeekId: first.startWeekId, endWeekId: last.endWeekId },
    seed.customerOrderOverrides,
    { includePriorBacklog: policy.includePriorBacklog },
  );
  state.dataset.importedAt = seed.customerDemand.importedAt;
  const orderImport = orderImportMetadataForSeed(stageSeed);
  const deduction = policy.deliveryDeductionFilter && orderImport
    ? calculateDeliveryDeduction({
        orders: state.orders,
        productionHistory: stageSeed.productionHistory,
        orderImport,
        importProducts: seed.customerDemand.products.map((product) => product.product),
        filter: policy.deliveryDeductionFilter,
      })
    : null;
  if (deduction) state.orders = deduction.adjustedOrders;
  if (optimizationGoal === "coarse") {
    state.orders = state.orders.map((order) => ({
      ...order,
      dueDate: last.endDate,
      allowPartial: false,
      partialDeliveryQuantity: 0,
      partialDeliveryDate: "",
      deliveryMilestones: [],
    }));
  }
  const metadata = metadataForCompletedRanges(optimizationGoal, completedRanges, policy, sequenceCreatedAt, completedRangeCount, updatedAt, deduction?.snapshot);
  const sequence = allRanges.length > 1 ? {
    planId: sequenceCreatedAt,
    engineVersion: PLAN_ENGINE_VERSION,
    optimizationGoal,
    includePriorBacklog: policy.includePriorBacklog,
    allowProductionBeforeScope: policy.allowProductionBeforeScope,
    shortageExtraCharge: { ...policy.shortageExtraCharge },
    deliveryDeductionFilter: policy.deliveryDeductionFilter,
    ranges: allRanges.map((range) => ({ ...range })),
    completedRangeCount,
    createdAt: sequenceCreatedAt,
    updatedAt,
  } satisfies PlanRunSequence : undefined;
  const planEnd = inputDateToSerial(optimizationGoal === "coarse" ? last.endDate : state.planEndDate);
  stageSeed.orders = state.orders;
  stageSeed.customerDemand = state.dataset;
  stageSeed.openingStock = {};
  stageSeed.orderCatalog = state.orderCatalog;
  stageSeed.demandTargets = undefined;
  stageSeed.activePlanRun = metadata;
  stageSeed.planNeedsRecalculation = false;
  stageSeed.planRunSequence = sequence;
  // Later stages add demand to the already verified queue. Their production
  // window must keep the first range's start; otherwise every stage is forced
  // to wait for its own Monday even when the machine queue finished earlier.
  const productionStart = inputDateToSerial(first.startDate);
  for (const machine of stageSeed.machines) {
    const operationalStart = machine.operationalAvailableStart ?? machine.availableStart;
    machine.operationalAvailableStart = operationalStart;
    machine.availableStart = optimizationGoal === "coarse" || !policy.allowProductionBeforeScope
      ? Math.max(operationalStart, productionStart)
      : operationalStart;
    // A fresh weekly run owns its own planning window. Keeping a wider end
    // date from an older run lets work silently drift weeks or months forward.
    machine.planEnd = planEnd;
  }
  return { seed: stageSeed, metadata, sequence, deliveryPreview: deduction ?? undefined };
}

export function preparePlanRun(seed: PlanningSeed, request: PlanRunRequest, createdAt = new Date().toISOString()): PreparedPlanRun {
  if (seed.customerDemand) {
    const weeks = seed.customerDemand.weeks;
    const requestedRanges = request.weekRanges?.length
      ? request.weekRanges
      : request.monthRange
        ? [weekScopeForPlanningMonthRange(weeks, request.monthRange)]
        : [];
    const completedRanges = request.appendToExistingPlan ? completedCustomerPlanRanges(seed) : [];
    const existingGoal = seed.planRunSequence?.optimizationGoal ?? seed.activePlanRun?.optimizationGoal;
    if (request.appendToExistingPlan && existingGoal && request.optimizationGoal !== existingGoal) {
      throw new Error("Planın devamı, mevcut planla aynı optimizasyon hedefini kullanmalıdır.");
    }
    const resolvedRanges = resolvePlanningWeekRanges(weeks, [...completedRanges, ...requestedRanges]);
    const allRanges: PlanRunRange[] = resolvedRanges.map((range) => ({
      startWeekId: range.startWeekId,
      endWeekId: range.endWeekId,
      startDate: range.startDate,
      endDate: range.endDate,
      label: range.label,
    }));
    const completedRangeCount = completedRanges.length;
    const sequenceCreatedAt = request.appendToExistingPlan
      ? seed.planRunSequence?.planId ?? seed.planRunSequence?.createdAt ?? seed.activePlanRun?.planId ?? seed.activePlanRun?.createdAt ?? createdAt
      : createdAt;
    const orderImport = orderImportMetadataForSeed(seed);
    const requestedDeliveryFilter = orderImport
      ? { enabled: request.deliveryDeduction?.enabled ?? true, startAt: request.deliveryDeduction?.startAt ?? orderImport.importedAt, includeStart: request.deliveryDeduction?.includeStart ?? true, endAt: createdAt }
      : undefined;
    const requestedShortageExtraCharge = normalizeShortageExtraChargePolicy(request.shortageExtraCharge ?? { enabled: false, thresholdPercent: 50 });
    const policy: CustomerPlanPolicy = request.appendToExistingPlan
      ? {
          includePriorBacklog: seed.planRunSequence?.includePriorBacklog ?? seed.activePlanRun?.includePriorBacklog ?? true,
          allowProductionBeforeScope: seed.planRunSequence?.allowProductionBeforeScope ?? seed.activePlanRun?.allowProductionBeforeScope ?? true,
          shortageExtraCharge: normalizeShortageExtraChargePolicy(seed.planRunSequence?.shortageExtraCharge ?? seed.activePlanRun?.shortageExtraCharge),
          deliveryDeductionFilter: seed.planRunSequence?.deliveryDeductionFilter ?? seed.activePlanRun?.deliveryDeduction?.filter ?? requestedDeliveryFilter,
        }
      : {
          includePriorBacklog: request.includePriorBacklog ?? false,
          allowProductionBeforeScope: request.allowProductionBeforeScope ?? false,
          shortageExtraCharge: requestedShortageExtraCharge,
          deliveryDeductionFilter: requestedDeliveryFilter,
        };
    if (request.optimizationGoal === "coarse") policy.allowProductionBeforeScope = false;
    const preparedStages = allRanges.slice(completedRangeCount).map((_, index) =>
      customerStageSeed(seed, allRanges, completedRangeCount + index + 1, request.optimizationGoal, policy, sequenceCreatedAt, createdAt));
    const first = preparedStages[0];
    if (!first) throw new Error("Planlama için çalıştırılacak hafta aralığı bulunamadı.");
    return {
      seed: first.seed,
      stages: preparedStages.map((stage) => stage.seed),
      metadata: first.metadata,
      scopeLabel: allRanges[completedRangeCount].label,
      sequence: first.sequence,
      deliveryPreview: first.deliveryPreview,
    };
  } else {
    const planningSeed = clone(seed);
    const startDate = request.productionStartDate ?? "";
    const endDate = request.productionEndDate ?? "";
    const start = inputDateToSerial(startDate);
    const end = inputDateToSerial(endDate);
    if (!start || !end || start > end) throw new Error("Planlama başlangıç ve bitiş tarihini kontrol edin.");
    for (const machine of planningSeed.machines) {
      const operationalStart = machine.operationalAvailableStart ?? machine.availableStart;
      machine.operationalAvailableStart = operationalStart;
      machine.availableStart = Math.max(operationalStart, start);
      machine.planEnd = end;
    }
    const orderImport = orderImportMetadataForSeed(planningSeed);
    const deliveryFilter: DeliveryDeductionFilter | undefined = orderImport
      ? { enabled: request.deliveryDeduction?.enabled ?? true, startAt: request.deliveryDeduction?.startAt ?? orderImport.importedAt, includeStart: request.deliveryDeduction?.includeStart ?? true, endAt: createdAt }
      : undefined;
    const deduction = orderImport && deliveryFilter
      ? calculateDeliveryDeduction({
          orders: planningSeed.orderImportGrossOrders ?? planningSeed.orders,
          productionHistory: planningSeed.productionHistory,
          orderImport,
          importProducts: planningSeed.orderCatalog ?? planningSeed.orders.map((order) => order.product),
          filter: deliveryFilter,
        })
      : null;
    if (deduction) planningSeed.orders = deduction.adjustedOrders;
    const metadata: PlanRunMetadata = {
      planId: createdAt,
      version: 1,
      engineVersion: PLAN_ENGINE_VERSION,
      optimizationGoal: request.optimizationGoal,
      shortageExtraCharge: normalizeShortageExtraChargePolicy(request.shortageExtraCharge ?? { enabled: false, thresholdPercent: 50 }),
      deliveryDeduction: deduction?.snapshot,
      scope: {
        kind: "production-dates",
        startDate,
        endDate,
        label: `${formatDate(startDate)}–${formatDate(endDate)}`,
      },
      createdAt,
    };
    planningSeed.activePlanRun = metadata;
    planningSeed.planNeedsRecalculation = false;
    planningSeed.planRunSequence = undefined;
    return { seed: planningSeed, stages: [planningSeed], metadata, scopeLabel: metadata.scope.label, deliveryPreview: deduction ?? undefined };
  }
}

function completedCustomerPlanRanges(seed: PlanningSeed): PlanningWeekRange[] {
  if (!seed.customerDemand || seed.activePlanRun?.scope.kind !== "customer-weeks") {
    throw new Error("Devamına aralık eklenecek tamamlanmış bir müşteri planı bulunamadı.");
  }
  const sequence = seed.planRunSequence;
  if (sequence && sequence.completedRangeCount < sequence.ranges.length) {
    throw new Error("Önce bekleyen sıradaki planlama aralığını tamamlayın.");
  }
  const metadataRanges = seed.activePlanRun.scope.ranges;
  const ranges = metadataRanges?.length
    ? metadataRanges.map((range) => ({ startWeekId: range.startWeekId, endWeekId: range.endWeekId }))
    : [{
        startWeekId: seed.activePlanRun.scope.startWeekId ?? seed.customerDemand.activeScope.startWeekId,
        endWeekId: seed.activePlanRun.scope.endWeekId ?? seed.customerDemand.activeScope.endWeekId,
      }];
  if (!ranges[0]?.startWeekId || !ranges.at(-1)?.endWeekId) {
    throw new Error("Mevcut planın ISO hafta kapsamı bulunamadı.");
  }
  return ranges;
}

export function executePlanRun(
  seed: PlanningSeed,
  fixedBatches: PlannedBatch[],
  request: PlanRunRequest,
  /** Optional fixed run time (offline replay); the app uses the current time. */
  createdAt?: string,
): { prepared: PreparedPlanRun; result: ScenarioResult } {
  const prepared = createdAt === undefined ? preparePlanRun(seed, request) : preparePlanRun(seed, request, createdAt);
  fixedBatches = withInterruptedBatches(prepared.seed, retainRouteCommitments(prepared.seed, fixedBatches));
  assertPlanInputs(prepared.seed, fixedBatches);
  const deliveryReview = reviewDeliveryCoverage(prepared.seed, prepared.deliveryPreview, fixedBatches);
  assertDeliveryCoverageReviewed(deliveryReview, request.reviewedDeliveryCoverageKey);
  const result = runOptimizedScenario(
    prepared.seed,
    fixedBatches.map((batch) => ({ ...batch })),
    request.optimizationGoal,
  );
  assertPlanResult(prepared.seed, fixedBatches, result);
  if (deliveryReview) prepared.metadata.deliveryCoverageReview = { reviewedAt: prepared.metadata.createdAt, key: deliveryReview.key };
  return { prepared, result: { ...result, planRun: prepared.metadata } };
}

export function executeNextPlanStage(
  seed: PlanningSeed,
  fixedBatches: PlannedBatch[],
  createdAt = new Date().toISOString(),
): PlanStageExecution {
  const sequence = seed.planRunSequence;
  if (!seed.customerDemand || !sequence) throw new Error("Devam ettirilecek aşamalı planlama bulunamadı.");
  if (sequence.completedRangeCount >= sequence.ranges.length) throw new Error("Seçilen tüm planlama aralıkları tamamlandı.");
  const completedRangeCount = sequence.completedRangeCount + 1;
  const prepared = customerStageSeed(
    seed,
    sequence.ranges,
    completedRangeCount,
    sequence.optimizationGoal,
    {
      includePriorBacklog: sequence.includePriorBacklog ?? true,
      allowProductionBeforeScope: sequence.allowProductionBeforeScope ?? true,
      shortageExtraCharge: normalizeShortageExtraChargePolicy(sequence.shortageExtraCharge),
      deliveryDeductionFilter: sequence.deliveryDeductionFilter,
    },
    sequence.createdAt,
    createdAt,
  );
  if (!prepared.sequence) throw new Error("Aşamalı planlama sırası oluşturulamadı.");
  fixedBatches = withInterruptedBatches(prepared.seed, retainRouteCommitments(prepared.seed, fixedBatches));
  assertPlanInputs(prepared.seed, fixedBatches);
  assertDeliveryCoverageReviewed(reviewDeliveryCoverage(prepared.seed, prepared.deliveryPreview, fixedBatches));
  const result = runOptimizedScenario(
    prepared.seed,
    fixedBatches.map((batch) => ({ ...batch })),
    sequence.optimizationGoal,
  );
  assertPlanResult(prepared.seed, fixedBatches, result);
  return {
    seed: prepared.seed,
    result: { ...result, planRun: prepared.metadata },
    sequence: prepared.sequence,
    completedRange: prepared.sequence.ranges[completedRangeCount - 1],
    nextRange: prepared.sequence.ranges[completedRangeCount],
  };
}

function comparisonRank(row: PlanComparisonRow): number[] {
  return [
    row.result.summary.shortage,
    row.onTimeShortage,
    row.result.summary.unplannedBatchCount,
    row.loadSpread,
    row.result.summary.totalSetupHours,
    row.result.summary.completion,
    GOALS.indexOf(row.goal),
  ];
}

function planLoadSpread(seed: PlanningSeed, result: ScenarioResult): number {
  const activeMachines = seed.machines.filter((machine) => machine.active);
  if (!activeMachines.length) return 0;
  const start = Math.floor(Math.min(...activeMachines.map((machine) => machine.availableStart)));
  const end = Math.floor(Math.max(...activeMachines.map((machine) => machine.planEnd)));
  const relevantMachineIds = new Set(activeMachines
    .filter((machine) => seed.orders.some((order) =>
      order.quantity > 0
      && isMachineEligibleForProduct(seed, machine.id, order.product)
      && (machine.rates[order.product.toUpperCase()] ?? 0) * machine.shiftFactor * (machine.capacityFactor ?? 1) > 0))
    .map((machine) => machine.id));
  const utilizations = buildCapacityReport(seed, result, start, end).machines
    .filter((machine) => relevantMachineIds.has(machine.machineId) && machine.availableHours > 0)
    .map((machine) => machine.utilization);
  return utilizations.length > 1 ? Math.max(...utilizations) - Math.min(...utilizations) : 0;
}

function compareRank(left: PlanComparisonRow, right: PlanComparisonRow): number {
  const a = comparisonRank(left);
  const b = comparisonRank(right);
  for (let index = 0; index < a.length; index += 1) {
    if (a[index] !== b[index]) return a[index] - b[index];
  }
  return 0;
}

export function comparePlanRuns(seed: PlanningSeed, fixedBatches: PlannedBatch[], request: PlanRunRequest): PlanComparisonRow[] {
  const rows = GOALS.map((goal) => {
    const { prepared, result } = executePlanRun(seed, fixedBatches, { ...request, optimizationGoal: goal });
    return {
      goal,
      result,
      onTimeShortage: result.orders.reduce((sum, order) => sum + Math.max(0, -(order.onTimeDifference ?? 0)), 0),
      loadSpread: planLoadSpread(prepared.seed, result),
      recommended: false,
    };
  });
  const recommended = [...rows].sort(compareRank)[0];
  return rows.map((row) => ({ ...row, recommended: row.goal === recommended.goal }));
}

export function planRunMetadataLabel(metadata: PlanRunMetadata | undefined): string {
  if (!metadata) return "Kapsam bilgisi yok";
  return `${optimizationGoalLabel(metadata.optimizationGoal)} · ${metadata.scope.label}`;
}

export function planRunDateRange(metadata: PlanRunMetadata | undefined): { startDate: string; endDate: string } | null {
  if (!metadata?.scope.startDate || !metadata.scope.endDate) return null;
  return { startDate: metadata.scope.startDate, endDate: metadata.scope.endDate };
}

export function planRunCompletionDate(result: ScenarioResult): string {
  return result.summary.completion ? excelSerialToDate(result.summary.completion).toISOString().slice(0, 10) : "";
}

