import { isProductionInterruption } from "./production-interruptions";
import { processLabel } from "./process-master-data";
import { buildMachineDiagnostics } from "./machine-diagnostics";
import {
  addBatchManually,
  calculateSetup,
  formatExcelDate,
  getSetupSettings,
  setupTypeRank,
  isMachineEligibleForProduct,
  machineDayCapacity,
  recalculateManualScenario,
  replaceMachineShiftOverrides,
  runOptimizedScenario,
  scenarioResultFromBatches,
  type Machine,
  type PlannedBatch,
  type PlanningSeed,
  type ScenarioResult,
  type ShiftCount,
} from "./planning";
import { regularMachineShifts } from "./capacity-analytics";
import { buildWeeklyPlanningState, previewFromDataset } from "./weekly-demand";
import { factoryDateInput } from "./factory-time";
import { formatInteger } from "./number-format";

export type PullForwardAdviceAction = {
  type: "pull-forward";
  futureLotId: string;
  sourceLotOrdinal: number;
  machineId: string;
  product: string;
  quantity: number;
  orderQuantity: number;
  position: number;
  expectedTailBatchId?: string;
  expectedTailEnd: number;
  start: number;
  end: number;
  setupHours: number;
  setupType: PlannedBatch["setupType"];
  runHours: number;
  sourceWeekId: string;
  sourceWeekLabel: string;
  sourceRangeLabel: string;
  sourceDueDate: string;
  sourceCheckpointId?: string;
  pulledIntoRangeLabel: string;
  currentRangeEnd: string;
};

export type AddChargeMachineOption = {
  machineId: string;
  machineName: string;
  queueLength: number;
  lockedCount: number;
  matchingPositions: number[];
  queue: Array<{ product: string; locked: boolean }>;
};

export type PlanningAdvice = {
  id: string;
  kind: "interrupted" | "move" | "add-charge" | "overtime" | "pull-forward";
  orderId?: string;
  machineId?: string;
  product: string;
  title: string;
  detail: string;
  benefit: string;
  actionLabel: string;
  action:
    | { type: "inspect-interruption"; chargeId: string; process: string }
    | { type: "move"; batchId: string; fromMachineId: string; toMachineId: string; position: number }
    | { type: "add-charge"; machineId: string; quantity: number; position: number; machineOptions: AddChargeMachineOption[] }
    | { type: "overtime"; machineId: string; start: number; end: number; shiftCount: ShiftCount }
    | PullForwardAdviceAction;
};

export function buildPlanningAdvice(seed: PlanningSeed, result: ScenarioResult, options: { dirty?: boolean } = {}): PlanningAdvice[] {
  const latest = new Map<string, NonNullable<PlanningSeed["productionInterruptions"]>[number]>();
  for (const pause of seed.productionInterruptions ?? []) if (isProductionInterruption(pause) && !pause.completedAt) latest.set(`${pause.chargeId}:${pause.process}`, pause);
  const advice: PlanningAdvice[] = [...latest.values()].map(pause => ({
    id:`interrupted:${pause.chargeId}:${pause.process}`, kind:"interrupted", machineId:pause.resourceId, product:pause.product,
    title:`${pause.workOrder || pause.product} · Üretime ara verildi.`,
    detail:`${processLabel(pause.process === 'washing' ? 'gkm' : pause.process)} · ${pause.resourceId} · ${formatInteger(pause.producedQuantity)} adet üretildi, ${formatInteger(pause.remainingQuantity)} adet kalan. ${pause.reason || 'Üretim yapılmadan iş değiştirildi.'}`,
    benefit:pause.resumedAt ? 'İşe yeniden başlandı; tamamlanana kadar hatırlatılır.' : 'Kalan işi tamamlayın. Üretilen yarı mamül sonraki proseslere yalnız manuel eklenir.',
    actionLabel:'Şarjı incele', action:{type:'inspect-interruption',chargeId:pause.chargeId,process:pause.process},
  }));
  if (options.dirty || result.state !== "planned") return advice;

  advice.push(...buildPullForwardAdvice(seed, result));

  for (const diagnostic of Object.values(buildMachineDiagnostics(seed, result))) {
    const suggestion = diagnostic.suggestion;
    if (!suggestion || suggestion.improvementDays <= 0) continue;
    const order = seed.orders.find((item) => item.product.toUpperCase() === suggestion.product.toUpperCase());
    advice.push({
      id: `move:${suggestion.batchId}:${suggestion.toMachineId}`,
      kind: "move",
      orderId: order?.id,
      machineId: suggestion.toMachineId,
      product: suggestion.product,
      title: `${suggestion.product} daha erken bitebilir`,
      detail: `${suggestion.fromMachineId} kuyruğundaki şarjı ${suggestion.toMachineId} tezgahının başına taşıyın.`,
      benefit: `${suggestion.improvementDays} gün kazanç · yeni bitiş ${formatExcelDate(suggestion.alternativeCompletion)}`,
      actionLabel: "Taşımayı uygula",
      action: { type: "move", batchId: suggestion.batchId, fromMachineId: suggestion.fromMachineId, toMachineId: suggestion.toMachineId, position: 0 },
    });
  }

  for (const calculated of result.orders) {
    const shortage = calculated.difference < 0;
    const dueRisk = calculated.onTimeDifference != null && calculated.onTimeDifference < 0;
    if (!shortage && !dueRisk) continue;
    const product = seed.products.find((item) => item.product.toUpperCase() === calculated.product.toUpperCase());
    if (!product || product.batchSize <= 0) continue;

    const addition = bestChargeAddition(seed, result, calculated.id, product.product, product.batchSize, shortage, dueRisk);
    if (addition) {
      const shortageBefore = Math.max(0, -calculated.difference);
      const shortageAfter = Math.max(0, -addition.order.difference);
      const dueBefore = Math.max(0, -(calculated.onTimeDifference ?? 0));
      const dueAfter = Math.max(0, -(addition.order.onTimeDifference ?? 0));
      const benefit = dueRisk
        ? `Termin eksiği ${formatQuantity(dueBefore)} → ${formatQuantity(dueAfter)} adet`
        : `Toplam eksik ${formatQuantity(shortageBefore)} → ${formatQuantity(shortageAfter)} adet`;
      const queuedMachineIds = addition.machineOptions
        .filter((option) => option.matchingPositions.length > 0)
        .map((option) => option.machineId);
      const queueDetail = queuedMachineIds.length
        ? ` Bu iş şu anda ${formatMachineList(queuedMachineIds)} ${queuedMachineIds.length === 1 ? "tezgahının" : "tezgahlarının"} iş kuyruğunda mevcut.`
        : "";
      advice.push({
        id: `add:${calculated.id}:${addition.machineId}:${product.batchSize}`,
        kind: "add-charge",
        orderId: calculated.id,
        machineId: addition.machineId,
        product: product.product,
        title: `${product.product} için 1 şarj ekleyin`,
        detail: `${addition.machineId} kuyruğuna ${formatQuantity(product.batchSize)} adetlik standart şarj eklenebilir; tahmini bitiş ${formatExcelDate(addition.batchEnd)}.${queueDetail}`,
        benefit,
        actionLabel: "Şarjı ekle",
        action: { type: "add-charge", machineId: addition.machineId, quantity: product.batchSize, position: addition.position, machineOptions: addition.machineOptions },
      });
    }

    if (dueRisk) {
      const overtime = bestOvertimeOption(seed, result, calculated.id, product.product);
      if (overtime) {
        const before = Math.max(0, -(calculated.onTimeDifference ?? 0));
        const after = Math.max(0, -(overtime.order.onTimeDifference ?? 0));
        advice.push({
          id: `overtime:${calculated.id}:${overtime.machineId}:${overtime.start}:${overtime.end}:${overtime.shiftCount}`,
          kind: "overtime",
          orderId: calculated.id,
          machineId: overtime.machineId,
          product: product.product,
          title: `${overtime.machineId} için mesai planlayın`,
          detail: `${formatExcelDate(overtime.start)}–${formatExcelDate(overtime.end)} arasında ${overtime.shiftCount} vardiya uygulanırsa ${product.product} termin açığı azalıyor.`,
          benefit: `Termin eksiği ${formatQuantity(before)} → ${formatQuantity(after)} adet`,
          actionLabel: "Mesaiyi uygula",
          action: { type: "overtime", machineId: overtime.machineId, start: overtime.start, end: overtime.end, shiftCount: overtime.shiftCount },
        });
      }
    }
  }

  return advice.sort((left, right) => advicePriority(left.kind) - advicePriority(right.kind) || left.product.localeCompare(right.product, "tr"));
}

function bestChargeAddition(seed: PlanningSeed, result: ScenarioResult, orderId: string, product: string, quantity: number, shortage: boolean, dueRisk: boolean) {
  const original = result.orders.find((order) => order.id === orderId);
  if (!original) return null;
  const candidates = seed.machines
    .filter((machine) => machine.active && (machine.rates[product.toUpperCase()] ?? 0) > 0 && isMachineEligibleForProduct(seed, machine.id, product))
    .map((machine) => {
      const queue = result.batches
        .filter((batch) => batch.status === "planned" && batch.machineId === machine.id)
        .sort((left, right) => left.planColumn - right.planColumn);
      const firstUnlocked = queue.findIndex((batch) => !batch.locked);
      return {
        machine,
        position: queue.length,
        option: {
          machineId: machine.id,
          machineName: machine.name,
          queueLength: queue.length,
          lockedCount: firstUnlocked === -1 ? queue.filter((batch) => batch.locked).length : firstUnlocked,
          matchingPositions: queue.flatMap((batch, index) => batch.product.toUpperCase() === product.toUpperCase() ? [index] : []),
          queue: queue.map((batch) => ({ product: batch.product, locked: Boolean(batch.locked) })),
        } satisfies AddChargeMachineOption,
      };
    })
    .filter(({ position }) => position < 14);
  const machineOptions = candidates.map(({ option }) => option);
  const simulated = candidates.flatMap(({ machine, position }) => {
    try {
      const next = addBatchManually(seed, result, product, machine.id, quantity, position);
      const order = next.orders.find((item) => item.id === orderId);
      const added = next.batches.find((batch) => batch.status === "planned" && !result.batches.some((current) => current.id === batch.id));
      if (!order || !added) return [];
      const improvesShortage = shortage && order.difference > original.difference;
      const improvesDue = dueRisk && (order.onTimeDifference ?? -Infinity) > (original.onTimeDifference ?? -Infinity);
      return improvesShortage || improvesDue ? [{ machineId: machine.id, position, order, batchEnd: added.end, machineOptions }] : [];
    } catch {
      return [];
    }
  });
  return simulated.sort((left, right) => {
    if (dueRisk) return (right.order.onTimeDifference ?? -Infinity) - (left.order.onTimeDifference ?? -Infinity) || left.batchEnd - right.batchEnd;
    return right.order.difference - left.order.difference || left.batchEnd - right.batchEnd;
  })[0] ?? null;
}

function formatMachineList(machineIds: string[]): string {
  if (machineIds.length < 2) return machineIds[0] ?? "";
  return `${machineIds.slice(0, -1).join(", ")} ve ${machineIds.at(-1)}`;
}

function bestOvertimeOption(seed: PlanningSeed, result: ScenarioResult, orderId: string, product: string) {
  const original = result.orders.find((order) => order.id === orderId);
  const order = seed.orders.find((item) => item.id === orderId);
  const due = inputDateSerial(order?.dueDate ?? "");
  if (!original || !due) return null;
  const today = inputDateSerial(factoryDateInput());
  const candidates = result.batches
    .filter((batch) => batch.status === "planned" && batch.product.toUpperCase() === product.toUpperCase() && batch.start <= due && batch.end > today)
    .flatMap((batch) => {
      const machine = seed.machines.find((item) => item.id === batch.machineId);
      if (!machine || machine.shiftFactor >= 3) return [];
      const start = Math.max(today, Math.floor(batch.start));
      const end = Math.max(start, Math.floor(Math.min(batch.end, due)));
      const shiftCount = Math.min(3, Math.max(1, Math.trunc(machine.shiftFactor) + 1)) as ShiftCount;
      try {
        const draft = cloneSeed(seed);
        replaceMachineShiftOverrides(draft, [machine.id], start, end, shiftCount, `${product} termin önerisi`);
        const next = recalculateManualScenario(draft, result.batches, { allowPlanEndOverflow: true });
        const nextOrder = next.orders.find((item) => item.id === orderId);
        if (!nextOrder || (nextOrder.onTimeDifference ?? -Infinity) <= (original.onTimeDifference ?? -Infinity)) return [];
        return [{ machineId: machine.id, start, end, shiftCount, order: nextOrder }];
      } catch {
        return [];
      }
    });
  return candidates.sort((left, right) => (right.order.onTimeDifference ?? -Infinity) - (left.order.onTimeDifference ?? -Infinity) || left.start - right.start)[0] ?? null;
}

function inputDateSerial(value: string): number {
  return value ? (Date.parse(`${value}T00:00:00Z`) - Date.UTC(1899, 11, 30)) / 86_400_000 : 0;
}

function cloneSeed(seed: PlanningSeed): PlanningSeed {
  return JSON.parse(JSON.stringify(seed)) as PlanningSeed;
}

function advicePriority(kind: PlanningAdvice["kind"]): number {
  return kind === "interrupted" ? -1 : kind === "add-charge" ? 0 : kind === "overtime" ? 1 : kind === "pull-forward" ? 2 : 3;
}

function formatQuantity(value: number): string {
  return formatInteger(value);
}

type FuturePlanningWindow = {
  currentRangeLabel: string;
  currentEndDate: string;
  sourceStartWeekId: string;
  sourceEndWeekId: string;
  sourceRangeLabel: string;
  sourceEndDate: string;
};

type FutureLot = {
  id: string;
  sourceLotOrdinal: number;
  product: string;
  quantity: number;
  orderQuantity: number;
  dueDate: string;
  checkpointId?: string;
  sourceWeekId: string;
  sourceWeekLabel: string;
};

type PullForwardPlacement = {
  lot: FutureLot;
  machine: Machine;
  position: number;
  expectedTailBatchId?: string;
  expectedTailEnd: number;
  start: number;
  end: number;
  setupHours: number;
  setupType: PlannedBatch["setupType"];
  runHours: number;
  remainingQuantity: number;
  availableNormalHours: number;
};

function futurePlanningWindow(seed: PlanningSeed): FuturePlanningWindow | null {
  const demand = seed.customerDemand;
  if (!demand?.weeks.length) return null;
  const active = demand.activeScope;
  const currentStartIndex = demand.weeks.findIndex((week) => week.id === active.startWeekId);
  const currentEndIndex = demand.weeks.findIndex((week) => week.id === active.endWeekId);
  if (currentStartIndex < 0 || currentEndIndex < currentStartIndex) return null;

  const sequence = seed.planRunSequence;
  const pendingRange = sequence && sequence.completedRangeCount < sequence.ranges.length
    ? sequence.ranges[sequence.completedRangeCount]
    : undefined;
  const sourceStartIndex = pendingRange
    ? demand.weeks.findIndex((week) => week.id === pendingRange.startWeekId)
    : currentEndIndex + 1;
  const sourceEndIndex = pendingRange
    ? demand.weeks.findIndex((week) => week.id === pendingRange.endWeekId)
    : Math.min(demand.weeks.length - 1, sourceStartIndex + 3);
  if (sourceStartIndex <= currentEndIndex || sourceEndIndex < sourceStartIndex) return null;

  const currentStart = demand.weeks[currentStartIndex];
  const currentEnd = demand.weeks[currentEndIndex];
  const sourceStart = demand.weeks[sourceStartIndex];
  const sourceEnd = demand.weeks[sourceEndIndex];
  if (!currentStart || !currentEnd || !sourceStart || !sourceEnd) return null;
  return {
    currentRangeLabel: `${weekLabel(currentStart)}–${weekLabel(currentEnd)}`,
    currentEndDate: currentEnd.weekEnd,
    sourceStartWeekId: sourceStart.id,
    sourceEndWeekId: sourceEnd.id,
    sourceRangeLabel: `${weekLabel(sourceStart)}–${weekLabel(sourceEnd)}`,
    sourceEndDate: sourceEnd.weekEnd,
  };
}

function expandedFutureResult(seed: PlanningSeed, result: ScenarioResult, window: FuturePlanningWindow): ScenarioResult {
  const demand = seed.customerDemand!;
  const state = buildWeeklyPlanningState(
    previewFromDataset(demand),
    seed.orders,
    { startWeekId: demand.activeScope.startWeekId, endWeekId: window.sourceEndWeekId },
    seed.customerOrderOverrides,
    { includePriorBacklog: seed.activePlanRun?.includePriorBacklog ?? true },
  );
  const expanded = cloneSeed(seed);
  expanded.orders = state.orders;
  expanded.customerDemand = state.dataset;
  expanded.orderCatalog = state.orderCatalog;
  expanded.openingStock = {};
  const extendedPlanEnd = inputDateSerial(state.planEndDate);
  for (const machine of expanded.machines) machine.planEnd = Math.max(machine.planEnd, extendedPlanEnd);
  return runOptimizedScenario(
    expanded,
    result.batches.filter((batch) => batch.status === "planned").map((batch) => ({ ...batch })),
    seed.planRunSequence?.optimizationGoal ?? seed.activePlanRun?.optimizationGoal ?? "earliest-finish",
  );
}

function futureLots(seed: PlanningSeed, current: ScenarioResult, expanded: ScenarioResult, window: FuturePlanningWindow): FutureLot[] {
  const existingIds = new Set(current.batches.filter((batch) => batch.status === "planned").map((batch) => batch.id));
  const weeks = seed.customerDemand!.weeks;
  const candidates = expanded.batches
    .filter((batch) => !existingIds.has(batch.id))
    .filter((batch) => Boolean(batch.demandDueDate && batch.demandDueDate > window.currentEndDate && batch.demandDueDate <= window.sourceEndDate))
    .map((batch) => {
      const sourceWeek = weeks.find((week) => week.weekEnd === batch.demandDueDate)
        ?? weeks.find((week) => week.id === window.sourceEndWeekId)!;
      return {
        product: batch.product,
        quantity: batch.status === "planned" && batch.quantity > 0 ? batch.quantity : batch.batchSize,
        orderQuantity: batch.orderQuantity,
        dueDate: batch.demandDueDate!,
        checkpointId: batch.demandCheckpointId,
        sourceWeekId: sourceWeek.id,
        sourceWeekLabel: weekLabel(sourceWeek),
      };
    })
    .filter((lot) => lot.quantity > 0)
    .sort((left, right) => left.dueDate.localeCompare(right.dueDate) || left.product.localeCompare(right.product, "tr"));

  const occupiedOrdinals = new Map<string, Set<number>>();
  for (const batch of current.batches) {
    const source = batch.pullForward;
    if (!source?.sourceLotOrdinal || source.sourceLotOrdinal < 1) continue;
    const key = futureLotGroupKey(batch.product, source.sourceWeekId);
    const occupied = occupiedOrdinals.get(key) ?? new Set<number>();
    occupied.add(source.sourceLotOrdinal);
    occupiedOrdinals.set(key, occupied);
  }

  return candidates.map((lot): FutureLot => {
    const key = futureLotGroupKey(lot.product, lot.sourceWeekId);
    const occupied = occupiedOrdinals.get(key) ?? new Set<number>();
    let sourceLotOrdinal = 1;
    while (occupied.has(sourceLotOrdinal)) sourceLotOrdinal += 1;
    occupied.add(sourceLotOrdinal);
    occupiedOrdinals.set(key, occupied);
    return {
      ...lot,
      id: futureLotStableId(lot.product, lot.sourceWeekId, sourceLotOrdinal),
      sourceLotOrdinal,
    };
  });
}

function futureLotGroupKey(product: string, sourceWeekId: string): string {
  return `${product.trim().toUpperCase()}|${sourceWeekId}`;
}

function futureLotStableId(product: string, sourceWeekId: string, sourceLotOrdinal: number): string {
  return `future:${product.trim().toUpperCase()}:${sourceWeekId}:${sourceLotOrdinal}`;
}

function regularCapacityTimeline(
  seed: PlanningSeed,
  machine: Machine,
  startValue: number,
  hoursValue: number,
): { start: number; end: number } {
  let cursor = Math.max(machine.availableStart, startValue);
  let remaining = Math.max(0, hoursValue);
  let actualStart = 0;
  let guard = 0;
  const shiftHours = getSetupSettings(seed).shiftHours;
  while (remaining > 1e-8 || !actualStart) {
    const day = Math.floor(cursor);
    const actualShifts = machineDayCapacity(seed, machine, day).shifts;
    const shifts = Math.min(actualShifts, regularMachineShifts(seed, machine, day));
    const capacityHours = shifts * shiftHours;
    const windowEnd = day + capacityHours / 24;
    if (capacityHours <= 0 || cursor >= windowEnd - 1e-8) {
      cursor = day + 1;
      guard += 1;
      if (guard > 3_660) throw new Error(`${machine.id} için normal çalışma kapasitesi bulunamadı.`);
      continue;
    }
    cursor = Math.max(cursor, day);
    if (!actualStart) actualStart = cursor;
    const consumed = Math.min(remaining, Math.max(0, (windowEnd - cursor) * 24));
    cursor += consumed / 24;
    remaining -= consumed;
    if (remaining > 1e-8) cursor = day + 1;
    guard += 1;
  }
  return { start: actualStart, end: cursor + (Number.isFinite(machine.finishOffset) ? machine.finishOffset : 0) };
}

function regularHoursBetween(seed: PlanningSeed, machine: Machine, startValue: number, endExclusive: number): number {
  let total = 0;
  const shiftHours = getSetupSettings(seed).shiftHours;
  for (let day = Math.floor(startValue); day < Math.ceil(endExclusive); day += 1) {
    const shifts = Math.min(machineDayCapacity(seed, machine, day).shifts, regularMachineShifts(seed, machine, day));
    const windowStart = day;
    const windowEnd = day + shifts * shiftHours / 24;
    total += Math.max(0, Math.min(endExclusive, windowEnd) - Math.max(startValue, windowStart)) * 24;
  }
  return total;
}

function buildPullForwardAdvice(seed: PlanningSeed, result: ScenarioResult): PlanningAdvice[] {
  const window = futurePlanningWindow(seed);
  if (!window) return [];
  let expanded: ScenarioResult;
  try {
    expanded = expandedFutureResult(seed, result, window);
  } catch {
    return [];
  }
  const lots = futureLots(seed, result, expanded, window);
  if (!lots.length) return [];
  const totalByProduct = new Map<string, number>();
  for (const lot of lots) totalByProduct.set(lot.product, (totalByProduct.get(lot.product) ?? 0) + lot.quantity);
  const currentEndExclusive = inputDateSerial(window.currentEndDate) + 1;
  const planned = result.batches.filter((batch) => batch.status === "planned");
  const placements: PullForwardPlacement[] = [];

  for (const machine of seed.machines.filter((item) => item.active)) {
    const queue = planned.filter((batch) => batch.machineId === machine.id).sort((left, right) => left.planColumn - right.planColumn || left.sequence - right.sequence);
    const tail = queue.at(-1);
    const tailEnd = Math.max(machine.availableStart, tail?.end ?? machine.currentJob.end);
    if (tailEnd >= currentEndExclusive - 1e-8) continue;
    const previousProduct = tail?.product ?? machine.currentJob.product;
    const previousDiameter = tail?.diameter ?? machine.currentJob.diameter;
    const availableNormalHours = regularHoursBetween(seed, machine, tailEnd, currentEndExclusive);
    if (availableNormalHours <= 0) continue;

    for (const lot of lots.slice(0, 48)) {
      const product = seed.products.find((item) => item.product.toUpperCase() === lot.product.toUpperCase());
      if (!product || !isMachineEligibleForProduct(seed, machine.id, lot.product)) continue;
      const shiftRate = machine.rates[lot.product.toUpperCase()] ?? 0;
      const hourlyRate = (shiftRate / getSetupSettings(seed).shiftHours) * (Number.isFinite(machine.capacityFactor) ? machine.capacityFactor : 1);
      if (hourlyRate <= 0) continue;
      const setup = calculateSetup(seed, previousProduct, previousDiameter, lot.product, product.diameter);
      const runHours = lot.quantity / hourlyRate;
      let timeline: { start: number; end: number };
      try {
        timeline = regularCapacityTimeline(seed, machine, tailEnd, setup.hours + runHours);
      } catch {
        continue;
      }
      if (timeline.end > currentEndExclusive + 1e-8) continue;
      placements.push({
        lot,
        machine,
        position: queue.length,
        expectedTailBatchId: tail?.id,
        expectedTailEnd: tailEnd,
        start: timeline.start,
        end: timeline.end,
        setupHours: setup.hours,
        setupType: setup.type,
        runHours,
        remainingQuantity: Math.max(0, (totalByProduct.get(lot.product) ?? lot.quantity) - lot.quantity),
        availableNormalHours,
      });
    }
  }

  placements.sort((left, right) =>
    setupTypeRank(left.setupType) - setupTypeRank(right.setupType)
    || left.lot.dueDate.localeCompare(right.lot.dueDate)
    || left.end - right.end
    || left.machine.id.localeCompare(right.machine.id, "tr", { numeric: true }));
  const selected: PullForwardPlacement[] = [];
  const usedMachines = new Set<string>();
  const usedLots = new Set<string>();
  for (const placement of placements) {
    if (usedMachines.has(placement.machine.id) || usedLots.has(placement.lot.id)) continue;
    selected.push(placement);
    usedMachines.add(placement.machine.id);
    usedLots.add(placement.lot.id);
    if (selected.length >= 12) break;
  }

  return selected.map((placement): PlanningAdvice => {
    const action: PullForwardAdviceAction = {
      type: "pull-forward",
      futureLotId: placement.lot.id,
      sourceLotOrdinal: placement.lot.sourceLotOrdinal,
      machineId: placement.machine.id,
      product: placement.lot.product,
      quantity: placement.lot.quantity,
      orderQuantity: placement.lot.orderQuantity,
      position: placement.position,
      expectedTailBatchId: placement.expectedTailBatchId,
      expectedTailEnd: placement.expectedTailEnd,
      start: placement.start,
      end: placement.end,
      setupHours: placement.setupHours,
      setupType: placement.setupType,
      runHours: placement.runHours,
      sourceWeekId: placement.lot.sourceWeekId,
      sourceWeekLabel: placement.lot.sourceWeekLabel,
      sourceRangeLabel: window.sourceRangeLabel,
      sourceDueDate: placement.lot.dueDate,
      sourceCheckpointId: placement.lot.checkpointId,
      pulledIntoRangeLabel: window.currentRangeLabel,
      currentRangeEnd: window.currentEndDate,
    };
    return {
      id: `pull:${placement.machine.id}:${placement.lot.id}`,
      kind: "pull-forward",
      machineId: placement.machine.id,
      product: placement.lot.product,
      title: `${placement.machine.id} boşluğuna ${placement.lot.product} alınabilir`,
      detail: `${placement.lot.sourceWeekLabel} talebinden ${formatQuantity(placement.lot.quantity)} adet, ${window.currentRangeLabel} kapasitesine öne çekilebilir. Tahmini bitiş ${formatExcelDate(placement.end)}; setup ${formatHours(placement.setupHours)}.`,
      benefit: `${formatHours(placement.setupHours + placement.runHours)} normal kapasite kullanılır · ${placement.lot.product} için kaynak aralıkta ${formatQuantity(placement.remainingQuantity)} adet kalır`,
      actionLabel: "Öne çek",
      action,
    };
  });
}

export function applyPullForwardAdvice(seed: PlanningSeed, result: ScenarioResult, action: PullForwardAdviceAction): ScenarioResult {
  const machine = seed.machines.find((item) => item.id === action.machineId && item.active);
  const product = seed.products.find((item) => item.product.toUpperCase() === action.product.toUpperCase());
  if (!machine || !product) throw new Error("Öne çekme için tezgah veya ürün parametresi artık geçerli değil.");
  if (!isMachineEligibleForProduct(seed, machine.id, product.product)) throw new Error(`${product.product}, ${machine.id} tezgahında üretilemez.`);
  if (result.batches.some((batch) => batch.pullForward?.futureLotId === action.futureLotId)) throw new Error("Bu gelecek hafta şarjı zaten öne çekilmiş.");

  const planned = result.batches.filter((batch) => batch.status === "planned");
  const unplanned = result.batches.filter((batch) => batch.status === "unplanned");
  const queue = planned.filter((batch) => batch.machineId === machine.id).sort((left, right) => left.planColumn - right.planColumn || left.sequence - right.sequence);
  const tail = queue.at(-1);
  const tailEnd = Math.max(machine.availableStart, tail?.end ?? machine.currentJob.end);
  if ((tail?.id ?? undefined) !== action.expectedTailBatchId || Math.abs(tailEnd - action.expectedTailEnd) > 1e-6) {
    throw new Error(`${machine.id} kuyruğu öneri hesaplandıktan sonra değişti. Tavsiyeleri yeniden açın.`);
  }

  const previousProduct = tail?.product ?? machine.currentJob.product;
  const previousDiameter = tail?.diameter ?? machine.currentJob.diameter;
  const setup = calculateSetup(seed, previousProduct, previousDiameter, product.product, product.diameter);
  const shiftRate = machine.rates[product.product.toUpperCase()] ?? 0;
  const capacityFactor = Number.isFinite(machine.capacityFactor) ? machine.capacityFactor : 1;
  const hourlyRate = (shiftRate / getSetupSettings(seed).shiftHours) * capacityFactor;
  if (hourlyRate <= 0) throw new Error(`${product.product} × ${machine.id} üretim hızı tanımlı değil.`);
  const runHours = action.quantity / hourlyRate;
  const timeline = regularCapacityTimeline(seed, machine, tailEnd, setup.hours + runHours);
  const rangeEndExclusive = inputDateSerial(action.currentRangeEnd) + 1;
  if (timeline.end > rangeEndExclusive + 1e-8) throw new Error("Şarj artık kontrol edilen aralığın normal kapasitesine sığmıyor.");

  const sequence = Math.max(0, ...result.batches.map((batch) => batch.sequence)) + 1;
  const batch: PlannedBatch = {
    id: `one-cek-${Date.now()}-${sequence}`,
    sequence,
    product: product.product,
    orderQuantity: action.orderQuantity,
    quantity: action.quantity,
    machineId: machine.id,
    diameter: product.diameter,
    batchSize: product.batchSize,
    dailyRate: shiftRate * machine.shiftFactor * capacityFactor,
    availableStart: machine.availableStart,
    planEnd: machine.planEnd,
    reason: `${action.sourceWeekLabel} talebi erken üretime alındı`,
    explanation: `${action.sourceWeekLabel} talebi ${action.pulledIntoRangeLabel} içindeki boş normal kapasiteye öne çekildi. ${setup.label}: ${formatHours(setup.hours)}; üretim: ${formatHours(runHours)}.`,
    planColumn: 13 + queue.length,
    existingQuantity: 0,
    start: timeline.start,
    end: timeline.end,
    status: "planned",
    setupHours: setup.hours,
    setupType: setup.type,
    runHours,
    demandDueDate: action.sourceDueDate,
    demandCheckpointId: action.sourceCheckpointId,
    manuallyPlaced: true,
    pullForward: {
      futureLotId: action.futureLotId,
      sourceLotOrdinal: action.sourceLotOrdinal,
      sourceWeekId: action.sourceWeekId,
      sourceWeekLabel: action.sourceWeekLabel,
      sourceRangeLabel: action.sourceRangeLabel,
      sourceDueDate: action.sourceDueDate,
      pulledIntoRangeLabel: action.pulledIntoRangeLabel,
      appliedAt: new Date().toISOString(),
    },
  };
  return scenarioResultFromBatches(seed, [...planned, batch, ...unplanned].sort((left, right) => left.sequence - right.sequence));
}


function weekLabel(week: { isoWeek: number; isoYear: number }): string {
  return `W${week.isoWeek}.${week.isoYear}`;
}

function formatHours(value: number): string {
  return `${new Intl.NumberFormat("tr-TR", { maximumFractionDigits: 1 }).format(value)} sa`;
}

