import type { PlanningSeed } from "./planning";
import { planningSaveError, planningSaveRequestBody, type PlanningStateRecord } from "./planning-persistence";

type JsonRecord = Record<string, unknown>;
export type PlanningDelta = { set: JsonRecord; remove: string[]; arrays: Record<string, { upsert: JsonRecord[]; remove: string[]; order?: string[] }> };
type PatchPayload = { version: 1; transactionId: string; expectedUpdatedAt: string; baseHash: string; delta: PlanningDelta;
  mode: "planning" | "operational"; force: boolean; flowSettingsVersion: 1; routePlacementVersion: 1; productionSplitVersion: 1; processWaitSettingsVersion: 1 };
type PendingWrite = { version: 1; userId: string; desiredHash: string; payload: PatchPayload };
type Store = Pick<Storage, "getItem" | "setItem" | "removeItem"> & Partial<Pick<Storage, "key" | "length">>;
type Fetch = (path: string, init?: RequestInit) => Promise<Response>;
export type PlanningDeltaResult = PlanningStateRecord & { transactionId: string; appliedRevision: string; replayed: boolean };

function stable(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(stable);
  if (value && typeof value === "object") return Object.fromEntries(Object.entries(value).sort(([a], [b]) => a < b ? -1 : a > b ? 1 : 0).map(([key, item]) => [key, stable(item)]));
  return value;
}

export async function planningContentHash(value: unknown): Promise<string> {
  const bytes = new TextEncoder().encode(JSON.stringify(stable(value)));
  return Array.from(new Uint8Array(await crypto.subtle.digest("SHA-256", bytes)), byte => byte.toString(16).padStart(2, "0")).join("");
}

function records(value: unknown): Map<string, JsonRecord> | null {
  if (!Array.isArray(value)) return null;
  const result = new Map<string, JsonRecord>();
  for (const item of value) {
    if (!item || typeof item !== "object" || typeof item.id !== "string" || !item.id || result.has(item.id)) return null;
    result.set(item.id, item);
  }
  return result;
}

/** Stable IDs select records. A work order or product never supplies identity. */
export function buildPlanningDelta(before: JsonRecord, after: JsonRecord): PlanningDelta {
  const source = JSON.parse(JSON.stringify(before)) as JsonRecord;
  const target = JSON.parse(JSON.stringify(after)) as JsonRecord;
  const delta: PlanningDelta = { set: {}, remove: [], arrays: {} };
  for (const key of Object.keys(source)) if (!Object.hasOwn(target, key)) delta.remove.push(key);
  for (const [key, value] of Object.entries(target)) {
    if (JSON.stringify(stable(source[key])) === JSON.stringify(stable(value))) continue;
    const oldRows = records(source[key]), newRows = records(value);
    if (!oldRows || !newRows) { Object.defineProperty(delta.set, key, { value, enumerable: true }); continue; }
    const remove = [...oldRows.keys()].filter(id => !newRows.has(id));
    const upsert = [...newRows].filter(([id, row]) => JSON.stringify(stable(oldRows.get(id))) !== JSON.stringify(stable(row))).map(([, row]) => row);
    const natural = [...oldRows.keys()].filter(id => newRows.has(id)).concat([...newRows.keys()].filter(id => !oldRows.has(id)));
    const desired = [...newRows.keys()];
    const change = { upsert, remove, ...(JSON.stringify(natural) === JSON.stringify(desired) ? {} : { order: desired }) };
    Object.defineProperty(delta.arrays, key, { value: change, enumerable: true });
  }
  return delta;
}

/** Decode transport corrections only. Domain rules run on the server. */
export function applyPlanningDelta(base: JsonRecord, delta: PlanningDelta): JsonRecord {
  const result = structuredClone(base);
  const object = (value: unknown): value is JsonRecord => Boolean(value && typeof value === "object" && !Array.isArray(value));
  const invalid = () => new Error("Kayıt yanıtındaki fark geçersiz. Yerel kopyayı koruyun.");
  if (!object(delta) || Object.keys(delta).sort().join() !== "arrays,remove,set" || !object(delta.set) || !Array.isArray(delta.remove) || !object(delta.arrays)) throw invalid();
  const names = [...Object.keys(delta.set), ...delta.remove, ...Object.keys(delta.arrays)];
  if (new Set(names).size !== names.length || names.some(key => typeof key !== "string" || !/^[A-Za-z][A-Za-z0-9_]{0,99}$/.test(key) || ["constructor", "prototype"].includes(key))) throw invalid();
  for (const key of delta.remove) { if (!Object.hasOwn(result, key)) throw invalid(); delete result[key]; }
  for (const [key, value] of Object.entries(delta.set)) Object.defineProperty(result, key, { value, enumerable: true, writable: true, configurable: true });
  for (const [key, change] of Object.entries(delta.arrays)) {
    const rows = records(result[key]);
    if (!object(change) || Object.keys(change).some(key => !["upsert", "remove", "order"].includes(key))) throw invalid();
    const upsert = records(change.upsert);
    if (!rows || !upsert || !Array.isArray(change.remove) || new Set(change.remove).size !== change.remove.length
      || change.remove.some(id => typeof id !== "string" || !rows.has(id) || upsert.has(id))) throw invalid();
    for (const id of change.remove) rows.delete(id);
    for (const [id, row] of upsert) rows.set(id, structuredClone(row));
    const order = change.order ?? [...rows.keys()];
    if (!Array.isArray(order) || new Set(order).size !== rows.size || order.length !== rows.size || order.some(id => !rows.has(id))) throw invalid();
    result[key] = order.map(id => rows.get(id));
  }
  return result;
}

export class PlanningDeltaConflict extends Error {
  constructor(public current: PlanningStateRecord | null) { super("Ortak kayıt değişti. Yerel kopyayı koruyarak güncel sürümü inceleyin."); }
}

function isRecord(value: unknown): value is PlanningStateRecord & Record<string, unknown> {
  const record = value as PlanningStateRecord | null;
  return Boolean(record?.seed && typeof record.seed === "object" && typeof record.updatedAt === "string"
    && record.updatedAt && record.patchVersion === 1 && /^[a-f0-9]{64}$/.test(record.stateHash ?? ""));
}

/** One in-flight request survives reload in browser storage. No timer retries it. */
export class PlanningDeltaWriter {
  readonly storageKey: string;
  private storagePrefix: string;
  private base: PlanningStateRecord | null = null;
  private initialized = false;
  constructor(private fetch: Fetch, private store: Store, readonly userId: string, area = "torna", private sessionId = crypto.randomUUID()) {
    this.storagePrefix = `selsa-planlama-write-v1:${encodeURIComponent(userId)}:${area}:`;
    this.storageKey = `${this.storagePrefix}${sessionId}`;
  }

  setBase(record: PlanningStateRecord | null): void { this.base = record ? structuredClone(record) : null; this.initialized = true; }
  exportPending(): string | null { return this.store.getItem(this.storageKey); }
  exportPendingCopies(): string[] {
    const copies = new Set<string>();
    const current = this.exportPending(); if (current) copies.add(current);
    if (this.store.key) for (let i = 0; i < (this.store.length ?? 0); i++) {
      const key = this.store.key(i);
      if (key?.startsWith(this.storagePrefix)) { const raw = this.store.getItem(key); if (raw) copies.add(raw); }
    }
    return [...copies];
  }
  discardPending(): void { this.store.removeItem(this.storageKey); }

  async checkPending(): Promise<{ current: PlanningStateRecord; appliedRevision: string } | null> {
    const pending = this.pending();
    if (!pending) return null;
    const response = await this.fetch(`/planning-state/transactions/${encodeURIComponent(pending.payload.transactionId)}`, { cache: "no-store" });
    const body = await response.json().catch(() => ({}));
    if (!response.ok || !isRecord(body.current) || typeof body.committed !== "boolean"
      || (body.committed && (typeof body.appliedRevision !== "string" || !body.appliedRevision))) {
      throw new Error("Bekleyen isteğin sonucu okunamadı. Yerel kopyayı indirin ve bağlantıyı tekrar kontrol edin.");
    }
    return { current: body.current, appliedRevision: body.committed ? body.appliedRevision : "" };
  }

  private pending(): PendingWrite | null {
    const raw = this.exportPending();
    if (!raw) return null;
    let value: PendingWrite;
    try { value = JSON.parse(raw) as PendingWrite; }
    catch { throw new Error("Bekleyen kayıt bilgisi okunamadı. Yerel kopyayı indirin; kayıt bilgisi silinmedi."); }
    if (!value || typeof value !== "object" || value.version !== 1 || value.userId !== this.userId || value.payload?.version !== 1
      || !/^[A-Za-z0-9_.:-]{1,128}$/.test(value.payload.transactionId) || !/^[a-f0-9]{64}$/.test(value.desiredHash)) {
      throw new Error("Bekleyen kayıt bilgisi geçersiz. Yerel kopyayı indirin; kayıt bilgisi silinmedi.");
    }
    return value;
  }

  private async send(pending: PendingWrite): Promise<PlanningDeltaResult> {
    const submitted = (this.base?.updatedAt ?? "") === pending.payload.expectedUpdatedAt
      ? applyPlanningDelta((this.base?.seed ?? {}) as JsonRecord, pending.payload.delta) : null;
    const response = await this.fetch("/planning-state", { method: "PATCH",
      headers: { "Content-Type": "application/json", "X-Planning-Request-Id": pending.payload.transactionId, "X-Planning-Session-Id": this.sessionId },
      body: planningSaveRequestBody(pending.payload) });
    const body = await response.json().catch(() => ({}));
    if (response.status === 409) throw new PlanningDeltaConflict(isRecord(body.detail?.current) ? body.detail.current : null);
    if (!response.ok) throw new Error(response.status === 404 || response.status === 405
      ? "Sunucu küçük kayıt güncellemelerini desteklemiyor. Yerel kopyayı koruyun ve sistem yöneticisine bildirin."
      : planningSaveError(response.status, body.detail));
    if (!body.seed && submitted && body.correction) {
      body.seed = applyPlanningDelta(submitted, body.correction);
      if (body.historyEntry) body.historyEntry.seed = body.seed;
    }
    if (!isRecord(body) || body.transactionId !== pending.payload.transactionId || typeof body.appliedRevision !== "string" || !body.appliedRevision
      || typeof body.replayed !== "boolean" || (!body.replayed && body.appliedRevision !== body.updatedAt)) {
      throw new Error("Sunucu kayıt onayı eksik veya geçersiz. Yerel kopya ve bekleyen istek korundu; ortak kaydı kontrol edin.");
    }
    this.base = structuredClone(body);
    return body as PlanningDeltaResult;
  }

  async write(next: PlanningSeed, options: { expectedUpdatedAt?: string; mode: "planning" | "operational"; force?: boolean;
    base?: PlanningStateRecord; assertCurrent: () => void; projectConfirmed?: (seed: PlanningSeed) => PlanningSeed }): Promise<PlanningDeltaResult> {
    if (!this.initialized) throw new Error("Ortak kayıt henüz yüklenmedi. Yerel kopyayı koruyun ve ortak kaydı kontrol edin.");
    options.assertCurrent();
    const desiredHash = await planningContentHash(next);
    options.assertCurrent();
    const pending = this.pending();
    if (pending) {
      const saved = await this.send(pending);
      options.assertCurrent();
      if (pending.desiredHash === desiredHash) return saved;
      if (await planningContentHash(saved.seed) !== pending.desiredHash) throw new PlanningDeltaConflict(saved);
      if (options.projectConfirmed && await planningContentHash(options.projectConfirmed(saved.seed)) === desiredHash) return saved;
      // Only the exact acknowledged predecessor permits a newer local delta.
      this.discardPending();
      options = { ...options, expectedUpdatedAt: saved.updatedAt, base: saved };
    }
    const base = options.base ?? this.base;
    if (base && !isRecord(base)) throw new Error("Sunucu kayıt sürümü eksik. Yerel kopyayı koruyun ve uygulama sürümünü kontrol edin.");
    if (options.expectedUpdatedAt !== undefined && options.expectedUpdatedAt !== (base?.updatedAt ?? "")) throw new PlanningDeltaConflict(base);
    const payload: PatchPayload = { version: 1, transactionId: crypto.randomUUID(), expectedUpdatedAt: base?.updatedAt ?? "",
      baseHash: base?.stateHash ?? "", delta: buildPlanningDelta((base?.seed ?? {}) as JsonRecord, next as JsonRecord),
      mode: options.mode, force: options.force ?? false, flowSettingsVersion: 1, routePlacementVersion: 1, productionSplitVersion: 1, processWaitSettingsVersion: 1 };
    planningSaveRequestBody(payload); // Validate size before writing the outbox or sending.
    const entry: PendingWrite = { version: 1, userId: this.userId, desiredHash, payload };
    options.assertCurrent();
    try { this.store.setItem(this.storageKey, JSON.stringify(entry)); }
    catch { throw new Error("Tarayıcı bekleyen isteği saklayamadı. İstek gönderilmedi; yerel kopyayı indirin."); }
    return this.send(entry);
  }
}

