import type { PlanningSeed, ScenarioResult } from "./planning";
import { buildDownstreamProcessPlan, type DownstreamProcessPlan } from "./process-planning";

/** One mounted workspace owns this cache. Callers supply immutable display inputs.
 * Domain mutation/review paths must call the scheduler directly. */
export function createPlanningDerivedCache(build = buildDownstreamProcessPlan) {
  let seedRef: PlanningSeed | undefined;
  let queueRef: ScenarioResult["batches"] | undefined;
  let normal: DownstreamProcessPlan | undefined;
  let candidates: DownstreamProcessPlan | undefined;
  return {
    get(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">, includeCandidates = false) {
      if (seedRef !== seed || queueRef !== result.batches) {
        seedRef = seed; queueRef = result.batches; normal = undefined; candidates = undefined;
      }
      if (includeCandidates) return candidates ??= build(seed, result, true);
      return normal ??= build(seed, result);
    },
  };
}

