import type { PlanningSeed } from "./planning";

export type PlanningSyncStatus = "loading" | "saving" | "synced" | "offline" | "conflict";

/** Match the reviewed production proxy limit. Never trim records to fit it. */
export const MAX_PLANNING_SAVE_BYTES = 6 * 1024 * 1024;

export function planningSaveRequestBody(payload: Record<string, unknown>): string {
  const body = JSON.stringify(payload);
  const bytes = new TextEncoder().encode(body).byteLength;
  if (bytes > MAX_PLANNING_SAVE_BYTES) {
    throw new Error(`Kayıt boyutu ${Math.ceil(bytes / 1024)} KiB; ortak kayıt sınırı 6144 KiB. Kayıt gönderilmedi. Yerel kopyayı indir ile veriyi koruyun ve sistem yöneticisine bildirin. Kayıtları silerek boyutu küçültmeyin.`);
  }
  return body;
}

export function planningSaveError(status: number, detail?: unknown): string {
  if (status === 413) return "Sunucu kayıt boyutu sınırı nedeniyle kaydı reddetti (413). Bu değişiklik ortak veritabanına kaydedilmedi. Yerel kopyayı indir ile veriyi koruyun ve sistem yöneticisine bildirin. Kayıtları silerek boyutu küçültmeyin.";
  return typeof detail === "string" ? detail : "Planlama durumu ortak veritabanına kaydedilemedi.";
}

/** A response confirms only the submitted snapshot, not subsequent queued edits. */
export function statusAfterPlanningSave(hasNewerLocal: boolean, mergedByServer: boolean): PlanningSyncStatus {
  return hasNewerLocal ? (mergedByServer ? "conflict" : "saving") : "synced";
}

export type PlanningStateRecord = {
  seed: PlanningSeed;
  updatedAt: string;
  stateHash?: string;
  patchVersion?: number;
};

function timestamp(value: string | undefined): number {
  const parsed = value ? Date.parse(value) : Number.NaN;
  return Number.isFinite(parsed) ? parsed : 0;
}

export function newestPlanningState(
  local: PlanningStateRecord | null,
  remote: PlanningStateRecord | null,
): PlanningStateRecord | null {
  if (!local) return remote;
  if (!remote) return local;
  return timestamp(local.updatedAt) > timestamp(remote.updatedAt) ? local : remote;
}

/** A reconciled server response retires writes prepared against older operations. */
export class PlanningWriteGuard {
  private generation = 0;
  private failure = "";
  blocked = false;

  capture(): number { return this.generation; }

  assertCurrent(ticket = this.generation, force = false): void {
    if (this.failure && (ticket !== this.generation || this.blocked && !force)) throw new Error(this.failure);
    if (ticket !== this.generation) throw new Error("Ortak üretim değişti. Bekleyen eski yazılar durduruldu; ortak veriyi yükleyin.");
    if (this.blocked && !force) throw new Error("Ortak üretim değişti. Önce ortak veriyi yükleyin veya çakışmayı çözün.");
  }

  retire(hasNewerLocal: boolean): void {
    this.generation += 1;
    this.blocked = hasNewerLocal;
    this.failure = "";
  }

  stopFailedSave(message: string): void { this.generation += 1; this.blocked = true; this.failure = message; }
}

/** Stop queued/new writes before reading a recovery candidate. A later recovery
 * decision retires this read too, so an old GET cannot reopen a stale conflict. */
export async function readPlanningStateForReview(guard: PlanningWriteGuard, writes: Promise<void>, read: () => Promise<PlanningStateRecord>): Promise<PlanningStateRecord> {
  await writes;
  guard.retire(true);
  const ticket = guard.capture();
  const remote = await read();
  guard.assertCurrent(ticket, true);
  return remote;
}

