import type { PlanningSeed } from "./planning";
import { areaStorageKey, type ProductionArea } from "./production-area";

export type RecoveryCopy = { version: 1; savedAt: string; reason: string; localUpdatedAt: string; baseUpdatedAt: string; remoteUpdatedAt: string; seed: PlanningSeed };
export type RecoveryArchive = { copies: RecoveryCopy[]; legacyArchives: string[] };
const DATABASE = "selsa-planning-recovery-v1";
const LEGACY_KEY = "selsa-planlama-recovery-v1";
const TIMEOUT_MS = 15_000;

async function digest(value: string): Promise<string> {
  const bytes = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value));
  return Array.from(new Uint8Array(bytes), byte => byte.toString(16).padStart(2, "0")).join("");
}

function legacyCopies(raw: string | null): RecoveryCopy[] {
  if (!raw) return [];
  try {
    const value = JSON.parse(raw);
    const copies = value?.version === 2 && Array.isArray(value.copies) ? value.copies : value?.version === 1 ? [value] : [];
    return copies.filter((copy: RecoveryCopy) => copy?.version === 1 && copy.seed &&
      [copy.seed.orders, copy.seed.products, copy.seed.machines, copy.seed.preferences].every(Array.isArray));
  } catch { return []; } // The exact raw text is archived even when parsing fails.
}

/** Local recovery only. No server write, retention cap, eviction or planning calculation. */
export class PlanningRecoveryStore {
  constructor(private factory: IDBFactory, private storage: Pick<Storage, "getItem" | "removeItem">) {}

  private open(): Promise<IDBDatabase> {
    return new Promise((resolve, reject) => {
      let finished = false;
      const fail = () => { if (!finished) { finished = true; clearTimeout(timer); reject(new Error("Kurtarma deposu açılamadı.")); } };
      const timer = setTimeout(fail, TIMEOUT_MS);
      let request: IDBOpenDBRequest;
      try { request = this.factory.open(DATABASE, 1); } catch { fail(); return; }
      request.onupgradeneeded = () => {
        if (finished) { request.transaction?.abort(); return; }
        for (const name of ["copies", "legacy"]) {
          const store = request.result.createObjectStore(name, { keyPath: ["scope", "hash"] });
          store.createIndex("scope", "scope");
        }
      };
      request.onerror = fail;
      request.onblocked = fail;
      request.onsuccess = () => {
        if (finished) { request.result.close(); return; }
        finished = true; clearTimeout(timer);
        request.result.onversionchange = () => request.result.close();
        resolve(request.result);
      };
    });
  }

  private scope(userId: string, area: ProductionArea): string {
    if (!userId) throw new Error("Kurtarma için kullanıcı bilgisi gerekli.");
    return JSON.stringify([userId, area]);
  }

  private transaction<T>(db: IDBDatabase, mode: IDBTransactionMode, run: (tx: IDBTransaction, result: (value: T) => void) => void): Promise<T> {
    return new Promise((resolve, reject) => {
      const tx = db.transaction(["copies", "legacy"], mode, { durability: "strict" });
      let value: T;
      const timer = setTimeout(() => { try { tx.abort(); } catch { /* Already finished. */ } }, TIMEOUT_MS);
      tx.oncomplete = () => { clearTimeout(timer); resolve(value); };
      tx.onabort = () => { clearTimeout(timer); reject(tx.error ?? new Error("Kurtarma kaydı tamamlanamadı.")); };
      // Request errors abort the transaction. Only oncomplete confirms the write.
      try { run(tx, next => { value = next; }); }
      catch (error) { clearTimeout(timer); tx.abort(); reject(error); }
    });
  }

  /** Commit legacy text and each distinct seed before releasing any localStorage space. */
  async retain(userId: string, area: ProductionArea, copy?: RecoveryCopy): Promise<{ count: number }> {
    const scope = this.scope(userId, area), key = areaStorageKey(LEGACY_KEY, area);
    const raw = this.storage.getItem(key);
    // Capture caller-owned objects before the first await.
    const batch = structuredClone([...legacyCopies(raw), ...(copy ? [copy] : [])]);
    const rows = await Promise.all(batch.map(async item => ({ scope, hash: await digest(JSON.stringify(item.seed)), copy: item })));
    const legacyHash = raw === null ? null : await digest(raw);
    const db = await this.open();
    try {
      await this.transaction<void>(db, "readwrite", tx => {
        const store = tx.objectStore("copies");
        for (const row of rows) {
          const existing = store.get([scope, row.hash]);
          existing.onsuccess = () => { if (!existing.result) store.put(row); };
        }
        if (raw !== null) tx.objectStore("legacy").put({ scope, hash: legacyHash, raw });
      });
      // Read back the exact archived text after commit. A failed verification never clears it.
      const verified = await this.transaction<{ count: number; raw?: string }>(db, "readonly", (tx, done) => {
        const result: { count: number; raw?: string } = { count: 0 };
        const count = tx.objectStore("copies").index("scope").count(scope);
        count.onsuccess = () => { result.count = count.result; };
        if (raw !== null) {
          const archive = tx.objectStore("legacy").get([scope, legacyHash!]);
          archive.onsuccess = () => { result.raw = archive.result?.raw; };
        }
        done(result);
      });
      if (raw !== null && verified.raw === raw) {
        // No await between comparison and cleanup. A changed legacy value stays for the next migration.
        try { if (this.storage.getItem(key) === raw) this.storage.removeItem(key); } catch { /* Durable archive exists; retry cleanup on the next use. */ }
      }
      return { count: verified.count };
    } finally { db.close(); }
  }

  async export(userId: string, area: ProductionArea): Promise<RecoveryArchive> {
    await this.retain(userId, area);
    const scope = this.scope(userId, area), db = await this.open();
    try {
      return await this.transaction<RecoveryArchive>(db, "readonly", (tx, done) => {
        const result: RecoveryArchive = { copies: [], legacyArchives: [] };
        const copies = tx.objectStore("copies").index("scope").getAll(scope);
        copies.onsuccess = () => { result.copies = copies.result.map(row => row.copy).sort((a, b) => a.savedAt.localeCompare(b.savedAt)); };
        const legacy = tx.objectStore("legacy").index("scope").getAll(scope);
        legacy.onsuccess = () => { result.legacyArchives = legacy.result.map(row => row.raw); };
        done(result);
      });
    } finally { db.close(); }
  }
}

export function browserRecoveryStore(): PlanningRecoveryStore {
  return new PlanningRecoveryStore(window.indexedDB, window.localStorage);
}

