import type { PlanningSeed } from "./planning";
import type { PlanningStateRecord } from "./planning-persistence";

/**
 * Startup and conflict recovery for the browser copy of the shared plan.
 *
 * The browser keeps the last plan in localStorage. A save can fail before the
 * server commits it, or the response can be lost after the commit. Another
 * session can also save in the meantime. This module decides, without any
 * write, whether the local copy can be shown and saved again, must be reviewed
 * against the server, or is already represented on the server.
 *
 * Rules: the server revision check stays authoritative. Nothing here merges
 * local operations into remote operations, and nothing overwrites newer
 * remote work. Physical records are compared by identity, never summed.
 */

/** Stored beside the local seed. Absent on drafts written by older clients. */
export type LocalDraftMeta = {
  version: 1;
  /** Server revision (updatedAt) this local copy was derived from or last confirmed against. */
  baseUpdatedAt: string;
  /** True from the local write until the server confirms the same copy. */
  pending: boolean;
  /** Write mode of the pending save; operational changes cannot be force-published. */
  pendingMode?: "planning" | "operational";
  changedAt: string;
};

export type OperationalDelta = {
  /** Local records absent on the server copy, or present with different content. */
  history: string[];
  wipLots: string[];
  wipMovements: string[];
  interruptions: string[];
  cancellations: string[];
  /** Machines/resources whose recorded current job differs. */
  currentJobs: string[];
};

export type StartupDecision =
  /** Use the server copy. `keepRecovery` = store the local copy before replacing it. */
  | { kind: "use-remote"; reason: "no-local" | "confirmed" | "identical" | "already-committed" | "legacy-older"; keepRecovery: boolean; delta: OperationalDelta }
  /** Server unchanged since the draft's base: show the local copy, saving is allowed with the base revision. */
  | { kind: "local-unsaved"; reason: "save-failed"; delta: OperationalDelta }
  /** The planner must choose. Saving is blocked until then. */
  | { kind: "review"; reason: "remote-changed" | "missing-base"; delta: OperationalDelta }
  /** No server copy at all (offline or empty database). */
  | { kind: "use-local"; reason: "no-remote"; delta: OperationalDelta };


function canonical(value: unknown, includeScenarioProvenance = false): unknown {
  if (Array.isArray(value)) return value.map(item => canonical(item, includeScenarioProvenance));
  if (value && typeof value === "object") return Object.fromEntries(Object.entries(value)
    .filter(([key, item]) => item !== undefined && (includeScenarioProvenance || key !== "scenarioProvenance"))
    .sort(([a], [b]) => a.localeCompare(b)).map(([key, item]) => [key, canonical(item, includeScenarioProvenance)]));
  return value;
}

export function sameSeedContent(left: PlanningSeed, right: PlanningSeed, includeScenarioProvenance = false): boolean {
  return JSON.stringify(canonical(left, includeScenarioProvenance)) === JSON.stringify(canonical(right, includeScenarioProvenance));
}

/** Fields the server stamps from the authenticated user; never local facts. */
const SERVER_STAMPS = new Set(["recordedBy", "recordedById", "reviewedAt", "reviewedBy", "reviewedById"]);
function factContent(value: unknown): string {
  const strip = (item: unknown): unknown => {
    if (Array.isArray(item)) return item.map(strip);
    if (item && typeof item === "object") return Object.fromEntries(Object.entries(item).filter(([key]) => !SERVER_STAMPS.has(key)).map(([key, inner]) => [key, strip(inner)]));
    return item;
  };
  return JSON.stringify(canonical(strip(value)));
}

/**
 * Local operational facts that the server copy does not hold: a record whose
 * identity is absent, or whose content differs (for example a review decision
 * or a changed balance). Only authenticated server stamps are ignored.
 */
export function operationalDelta(local: PlanningSeed, remote: PlanningSeed): OperationalDelta {
  const missing = <T,>(localItems: T[] | undefined, remoteItems: T[] | undefined, key: (item: T) => string | undefined) => {
    const present = new Map((remoteItems ?? []).map(item => [key(item), factContent(item)] as const));
    return [...new Map((localItems ?? []).map(item => [key(item), item] as const))]
      .filter(([id, item]) => id && present.get(id) !== factContent(item)).map(([id]) => id!);
  };
  const remoteMachines = new Map(remote.machines.map(machine => [machine.id, machine]));
  const remoteProcess = new Map((remote.processCurrentJobs ?? []).map(job => [job.resourceId, job]));
  const currentJobs = [
    // A machine missing on the server still counts when it holds local current work.
    ...local.machines.filter(machine => {
      const other = remoteMachines.get(machine.id);
      return other ? factContent(machine.currentJob) !== factContent(other.currentJob) : (machine.currentJob?.quantity ?? 0) > 0;
    }).map(machine => machine.id),
    ...(local.processCurrentJobs ?? []).filter(job => factContent(job) !== factContent(remoteProcess.get(job.resourceId))).map(job => job.resourceId),
  ];
  return {
    history: missing(local.productionHistory, remote.productionHistory, item => item.id),
    wipLots: missing(local.wipLots, remote.wipLots, item => item.id),
    wipMovements: missing(local.wipMovements, remote.wipMovements, item => item.id),
    interruptions: missing(local.productionInterruptions, remote.productionInterruptions, item => item.id),
    cancellations: missing(local.productionCancellations, remote.productionCancellations, item => item.id),
    currentJobs: [...new Set(currentJobs)],
  };
}

export function hasOperationalDelta(delta: OperationalDelta): boolean {
  return Object.values(delta).some(items => items.length > 0);
}

const emptyDelta = (): OperationalDelta => ({ history: [], wipLots: [], wipMovements: [], interruptions: [], cancellations: [], currentJobs: [] });

/**
 * Decide the startup state. Pure: callers perform the visible action.
 *
 * - No base revision (older client draft): never merged automatically. If the
 *   server copy contains everything and is newer, the server is used and the
 *   local copy is kept for recovery; otherwise the planner reviews.
 * - Pending draft whose base equals the server revision: the save failed
 *   before commit. Show the local copy; saving again uses that base, so the
 *   server still rejects it if anything changed in between.
 * - Pending draft, server changed: the response was lost after commit only if
 *   the server copy has the same facts in both directions and the same other
 *   content apart from server stamps; then use the server. Otherwise review;
 *   never overwrite.
 */
export function classifyStartup(
  local: (PlanningStateRecord & { meta?: LocalDraftMeta | null }) | null,
  remote: PlanningStateRecord | null,
  projectConfirmedRemote?: (seed: PlanningSeed) => PlanningSeed,
): StartupDecision {
  if (!local) return { kind: "use-remote", reason: "no-local", keepRecovery: false, delta: emptyDelta() };
  if (!remote) return { kind: "use-local", reason: "no-remote", delta: emptyDelta() };
  const delta = operationalDelta(local.seed, remote.seed);
  if (sameSeedContent(local.seed, remote.seed)) return { kind: "use-remote", reason: "identical", keepRecovery: false, delta };
  const meta = local.meta;
  // The UI stores the daily forecast clone after a confirmed server response.
  // That clone can move unfinished WIP readiness to today. It is not an unsaved
  // physical action. Confirm only the same server revision and the entire exact
  // projection from that revision. Never normalize the local copy or ignore a
  // readiness field: a real edit must still require recovery.
  if (meta && !meta.pending && meta.baseUpdatedAt && meta.baseUpdatedAt === remote.updatedAt && projectConfirmedRemote) {
    try {
      if (sameSeedContent(local.seed, projectConfirmedRemote(remote.seed))) {
        return { kind: "use-remote", reason: "confirmed", keepRecovery: false, delta: emptyDelta() };
      }
    } catch {
      // A projection error cannot prove confirmation. Keep the normal guards.
    }
  }
  if (!meta || !meta.baseUpdatedAt) {
    const localTime = Date.parse(local.updatedAt), remoteTime = Date.parse(remote.updatedAt);
    if (!hasOperationalDelta(delta) && Number.isFinite(remoteTime) && (!Number.isFinite(localTime) || localTime <= remoteTime)) {
      return { kind: "use-remote", reason: "legacy-older", keepRecovery: true, delta };
    }
    return { kind: "review", reason: "missing-base", delta };
  }
  // A confirmed copy is replaced by the server copy; any local operation that
  // the server does not hold is still kept as a recovery copy, never dropped.
  if (!meta.pending) return { kind: "use-remote", reason: "confirmed", keepRecovery: hasOperationalDelta(delta), delta };
  if (meta.baseUpdatedAt === remote.updatedAt) return { kind: "local-unsaved", reason: "save-failed", delta };
  // Confirmation needs equal facts in both directions: a local deletion or a
  // changed or extra server fact is reviewed instead of being called committed.
  if (!hasOperationalDelta(delta) && !hasOperationalDelta(operationalDelta(remote.seed, local.seed)) && samePlanningInputs(local.seed, remote.seed)) {
    return { kind: "use-remote", reason: "already-committed", keepRecovery: true, delta };
  }
  return { kind: "review", reason: "remote-changed", delta };
}

/**
 * Everything except the facts that operationalDelta compares (history, WIP,
 * movements, interruptions, cancellations, current jobs). Planning events,
 * journey notes and machine operational availability stay compared: they can
 * be unsaved user changes. Only authenticated server stamps are ignored.
 */
const DELTA_FIELDS = new Set(["productionHistory", "wipLots", "wipMovements", "productionInterruptions", "productionCancellations", "processCurrentJobs"]);
function samePlanningInputs(left: PlanningSeed, right: PlanningSeed): boolean {
  const strip = (seed: PlanningSeed) => Object.fromEntries(Object.entries(seed).filter(([key]) => !DELTA_FIELDS.has(key)).map(([key, value]) => [key,
    key === "machines" && Array.isArray(value) ? value.map(machine => Object.fromEntries(Object.entries(machine as object).filter(([field]) => field !== "currentJob"))) : value]));
  return factContent(strip(left)) === factContent(strip(right));
}

/** Short Turkish list for the conflict dialog; counts only, bounded. */
export function describeOperationalDelta(delta: OperationalDelta): string[] {
  const rows: string[] = [];
  if (delta.cancellations.length) rows.push(`${delta.cancellations.length} üretim iptali / inceleme kaydı`);
  if (delta.history.length) rows.push(`${delta.history.length} üretim arşivi kaydı`);
  if (delta.wipLots.length) rows.push(`${delta.wipLots.length} yarı mamul kaydı`);
  if (delta.wipMovements.length) rows.push(`${delta.wipMovements.length} yarı mamul hareketi`);
  if (delta.interruptions.length) rows.push(`${delta.interruptions.length} ara verme / kısmi üretim kaydı`);
  if (delta.currentJobs.length) rows.push(`Mevcut iş farkı: ${delta.currentJobs.slice(0, 8).join(", ")}${delta.currentJobs.length > 8 ? " …" : ""}`);
  return rows;
}

