import type { FlowSettings } from "./flow-settings";
import { assertTurningIdentityTransition, turningIdentityScope, reconcileTurningQueue, reconcileTurningSeed } from "./turning-queue-identity";
import { finishProductionInterruptions, hasActiveProductionInterruption, hasProtectedProductionRemainder, withInterruptedBatches, type ProductionInterruption } from "./production-interruptions";
import type { ProductWeight } from "./product-weights";
import type { RawMaterialSettings } from "./raw-material-settings";
import type { ProcessWaitSettings } from "./process-waits";
import { turningDeliveryReadyAt } from "./delivery-calendar";
import { factoryDateInput, factoryDateTimeToIso } from "./factory-time";
import { resolvedProductSetupFamily, type ProductSetupFamily } from "./setup-families";
import { turningEnabled, type DownstreamProcess, type ProcessMasterData } from "./process-master-data";

export type DeliveryMilestone = {
  id: string;
  quantity: number;
  date: string;
};

export type PeriodId = string;

export type PlanningScope = {
  startPeriod: PeriodId;
  endPeriod: PeriodId;
};

export type CumulativeDemandTarget = {
  id: string;
  product: string;
  periodId: PeriodId;
  cumulativeQuantity: number;
  dueDate?: string;
};

export type IsoWeekPeriod = {
  id: string;
  isoYear: number;
  isoWeek: number;
  label: string;
  weekStart: string;
  weekEnd: string;
  quantity: number;
};

export type WeeklyDemandPoint = {
  weekId: string;
  isoYear: number;
  isoWeek: number;
  label: string;
  weekStart: string;
  weekEnd: string;
  quantity: number;
  cumulativeQuantity: number;
  requiredQuantity?: number;
  balance: number;
};

export type ConfirmedDemandProduct = {
  product: string;
  family: string;
  unit: string;
  availableQuantity: number;
  baselineBalance: number;
  priorDemand: number;
  baselineDueDate: string;
  weeklyDemands: WeeklyDemandPoint[];
  totalDemand: number;
};

export type WeeklyDemandScope = {
  startWeekId: string;
  endWeekId: string;
};

export type CustomerDemandDataset = {
  format: "confirmed-overview";
  calculationModel?: "net-shortage-v1";
  sourceFile: string;
  sheetName: "3. Overview (confirmed)";
  snapshotDate: string;
  baselineLabel: string;
  baselineDueDate: string;
  weeks: IsoWeekPeriod[];
  products: ConfirmedDemandProduct[];
  activeScope: WeeklyDemandScope;
  importedAt: string;
};

export type CustomerOrderOverride = {
  product: string;
  quantity: number;
  dueDate: string;
  updatedAt: string;
};

export type Order = {
  id: string;
  sourceRow: number;
  product: string;
  periodId?: PeriodId;
  quantity: number;
  savedPlanned: number;
  savedDifference: number;
  savedMachines: string[];
  dueDate: string;
  allowPartial: boolean;
  partialDeliveryQuantity: number;
  partialDeliveryDate: string;
  deliveryMilestones?: DeliveryMilestone[];
};

export type Product = {
  product: string;
  setupFamily?: ProductSetupFamily;
  generalMachine: string;
  eligibleMachines: string[];
  /** Assigned Torna machines temporarily excluded for this product. */
  inactiveMachineIds?: string[];
  batchSize: number;
  dailyRate: number;
  shiftRate: number;
  parameterDailyRate: number;
  diameter: string;
  alternativeMachines: string[];
  moq: number;
  source: string;
};

export type Machine = {
  id: string;
  name: string;
  active: boolean;
  /**
   * Operator-owned availability before a plan-run scope is applied.
   * `availableStart` may be raised temporarily by a weekly plan, while this
   * value must survive so a later fresh plan can move back to an earlier week.
   */
  operationalAvailableStart?: number;
  availableStart: number;
  planEnd: number;
  note: string;
  shiftFactor: number;
  capacityFactor: number;
  finishOffset: number;
  rates: Record<string, number>;
  currentJob: {
    batchId?: string;
    interruptionId?: string;
    workOrder: string;
    product: string;
    quantity: number;
    originalQuantity?: number;
    remainingQuantity?: number;
    /** Factory serial when the remaining count was observed. */
    remainingAsOf?: number;
    start: number;
    end: number;
    dailyRate: number;
    diameter: string;
    rolledForwardFrom?: number;
    rolledForwardAt?: string;
  };
};

export type PreferenceRule = {
  key: string;
  machines: string[];
  ruleType: string;
  description: string;
  source: string;
};

export type Restriction = { machineId: string; product: string };
export type ShiftCount = 0 | 1 | 2 | 3;
export type Holiday = { name: string; serial: number; workingShifts?: ShiftCount };

export type MachineCalendarEvent = {
  id: string;
  machineId: string;
  kind: "maintenance" | "shift";
  name: string;
  start: number;
  end: number;
  shiftCount: ShiftCount;
  /** Kept as history after the operator confirms that a maintenance was performed. */
  completedAt?: string;
};

export type MachineDayCapacity = {
  shifts: ShiftCount;
  kind: "normal" | "sunday" | "holiday" | "maintenance" | "shift";
  label: string;
};

export type SetupSettings = {
  model?: "diameter-only" | "product-family";
  shiftHours: number;
  sameDiameterHours: number;
  differentDiameterHours: number;
  sameFamilyDifferentDiameterHours?: number;
  crossFamilyHours?: number;
};

export type NormalizedSetupSettings = Required<SetupSettings>;

export type SetupType = "same-product" | "same-diameter" | "same-family" | "cross-family" | "different-diameter";

export type OptimizationGoal = "earliest-finish" | "all-compatible" | "minimum-setup" | "balanced" | "coarse";

export type ShortageExtraChargePolicy = {
  enabled: boolean;
  thresholdPercent: number;
};

export type PlanRunRange = {
  startWeekId: string;
  endWeekId: string;
  startDate: string;
  endDate: string;
  label: string;
};

export type PlanRunScope = {
  kind: "customer-weeks" | "production-dates";
  startDate: string;
  endDate: string;
  label: string;
  startWeekId?: string;
  endWeekId?: string;
  ranges?: PlanRunRange[];
};

export type OrderImportMetadata = {
  id: string;
  sourceFile: string;
  importedAt: string;
};

export type DeliveryDeductionFilter = {
  enabled: boolean;
  startAt: string;
  includeStart: boolean;
  endAt: string;
};

export type DeliveryDeductionItem = {
  entryId: string;
  sourceEntryId?: string;
  product: string;
  workOrder: string;
  deliveredAt: string;
  quantity: number;
  deductedQuantity: number;
  excessQuantity: number;
  matchedOrderIds: string[];
  status: "matched" | "excess" | "outside-scope" | "unmatched";
};

export type DeliveryDeductionSnapshot = {
  import: OrderImportMetadata;
  filter: DeliveryDeductionFilter;
  grossDemand: number;
  deductedQuantity: number;
  plannedDemand: number;
  excessDeliveryQuantity: number;
  items: DeliveryDeductionItem[];
};

export type PlanRunMetadata = {
  planId?: string;
  version?: number;
  engineVersion?: number;
  optimizationGoal: OptimizationGoal;
  scope: PlanRunScope;
  includePriorBacklog?: boolean;
  allowProductionBeforeScope?: boolean;
  shortageExtraCharge?: ShortageExtraChargePolicy;
  deliveryDeduction?: DeliveryDeductionSnapshot;
  deliveryCoverageReview?: { reviewedAt: string; key: string };
  createdAt: string;
};

export type PlanRunSequence = {
  planId?: string;
  engineVersion?: number;
  optimizationGoal: OptimizationGoal;
  ranges: PlanRunRange[];
  completedRangeCount: number;
  includePriorBacklog?: boolean;
  allowProductionBeforeScope?: boolean;
  shortageExtraCharge?: ShortageExtraChargePolicy;
  deliveryDeductionFilter?: DeliveryDeductionFilter;
  createdAt: string;
  updatedAt: string;
};

export type PullForwardSource = {
  futureLotId: string;
  sourceLotOrdinal?: number;
  sourceWeekId: string;
  sourceWeekLabel: string;
  sourceRangeLabel: string;
  sourceDueDate: string;
  pulledIntoRangeLabel: string;
  appliedAt: string;
};

export type PlannedBatch = {
  /** Retain this reviewed route's Torna charge when regenerating a plan. */
  routeCommitted?: boolean;
  routeTargetDate?: string;
  interruptionId?: string;
  id: string;
  sequence: number;
  product: string;
  orderQuantity: number;
  quantity: number;
  machineId: string;
  diameter: string;
  batchSize: number;
  dailyRate: number;
  availableStart: number;
  planEnd: number;
  reason: string;
  explanation: string;
  planColumn: number;
  existingQuantity: number;
  start: number;
  end: number;
  status: "planned" | "unplanned";
  setupHours?: number;
  setupType?: SetupType;
  runHours?: number;
  demandDueDate?: string;
  demandCheckpointId?: string;
  locked?: boolean;
  manuallyPlaced?: boolean;
  workOrder?: string;
  pullForward?: PullForwardSource;
  rolledForwardFrom?: number;
  rolledForwardAt?: string;
};

export type SavedBatch = Omit<PlannedBatch, "explanation" | "start" | "end" | "status">;

export type ProcessOperationOverride = {
  /** Reviewed queue order; readiness still bounds actual start. */
  queueOrder?: number;
  routeMode?: "priority" | "keep" | "manual" | "automatic";
  preservedStart?: number;
  preservedEnd?: number;
  routeTargetDate?: string;
  sourceProduct?: string;
  sourceCurrentJobKey?: string;
  resumeAfterCurrent?: boolean;
  batchId: string;
  process: DownstreamProcess;
  resourceId: string;
  requestedStart: number;
  updatedAt: string;
};

/**
