export function roundToBatchByFraction(quantity: number, batchSize: number): number {
  return productionTargetForShortage(quantity, batchSize, { enabled: true, thresholdPercent: 50 });
}

/**
 * Convert a positive residual into standard charges. Missing policy metadata is
 * interpreted as the historical half-charge rule so old saved plans remain
 * readable; every new plan run stores an explicit policy.
 */
export function shortageExtraChargePolicyForSeed(seed: PlanningSeed): ShortageExtraChargePolicy {
  return normalizeShortageExtraChargePolicy(seed.activePlanRun?.shortageExtraCharge);
}

export function normalizeShortageExtraChargePolicy(policy?: ShortageExtraChargePolicy): ShortageExtraChargePolicy {
  const normalized = policy ?? { enabled: true, thresholdPercent: 50 };
  if (!Number.isFinite(normalized.thresholdPercent) || normalized.thresholdPercent < 0 || normalized.thresholdPercent > 100) {
    throw new Error("Eksik şarj eşiği 0 ile 100 arasında olmalıdır.");
  }
  return { enabled: Boolean(normalized.enabled), thresholdPercent: normalized.thresholdPercent };
}

export function productionTargetForShortage(quantity: number, batchSize: number, policy?: ShortageExtraChargePolicy): number {
  if (batchSize <= 0) return quantity;
  const safeQuantity = Math.max(0, quantity);
  const wholeLots = Math.floor(safeQuantity / batchSize);
  const residual = safeQuantity - wholeLots * batchSize;
  const normalized = normalizeShortageExtraChargePolicy(policy);
  const reachesThreshold = residual > 1e-7 && residual / batchSize * 100 + 1e-7 >= normalized.thresholdPercent;
  return (wholeLots + (normalized.enabled && reachesThreshold ? 1 : 0)) * batchSize;
}

export function diameterNumeric(value: string): number {
  const match = value.replace(",", ".").match(/\d+(?:\.\d+)?/);
  return match ? Number(match[0]) : 0;
}

export function excelSerialToDate(serial: number): Date {
  return new Date(Date.UTC(1899, 11, 30) + serial * 86_400_000);
}

export function formatExcelDate(serial: number, options?: Intl.DateTimeFormatOptions): string {
  if (!serial || !Number.isFinite(serial)) return "—";
  return new Intl.DateTimeFormat("tr-TR", { ...(options ?? { day: "2-digit", month: "short", year: "numeric" }), timeZone: "UTC" }).format(excelSerialToDate(serial));
}

function addWorkdays(startSerial: number, daysValue: number, holidays: Set<number>, offset: number): number {
  let serial = Math.floor(startSerial);
  let remaining = Math.max(0, Math.trunc(daysValue));
  while (remaining > 0) {
    serial += 1;
    const day = excelSerialToDate(serial).getUTCDay();
    if (day !== 0 && !holidays.has(serial)) remaining -= 1;
  }
  return serial + offset;
}

function shiftCount(value: number | undefined): ShiftCount {
  if (!Number.isFinite(value)) return 0;
  return Math.max(0, Math.min(3, Math.trunc(value!))) as ShiftCount;
}

export function machineDayCapacity(seed: PlanningSeed, machine: Pick<Machine, "id" | "shiftFactor">, serialValue: number): MachineDayCapacity {
  const serial = Math.floor(serialValue);
  const events = (seed.calendarEvents ?? []).filter((event) => event.machineId === machine.id && serial >= Math.floor(event.start) && serial <= Math.floor(event.end));
  const maintenance = events.find((event) => event.kind === "maintenance");
  if (maintenance) return { shifts: 0, kind: "maintenance", label: maintenance.name || "Planlı bakım" };
  const shiftOverride = [...events].reverse().find((event) => event.kind === "shift");
  if (shiftOverride) return { shifts: shiftCount(shiftOverride.shiftCount), kind: "shift", label: shiftOverride.name || "Vardiya değişikliği" };
  const holiday = seed.holidays.find((item) => Math.floor(item.serial) === serial);
  if (holiday) {
    const shifts = shiftCount(holiday.workingShifts);
    return { shifts, kind: "holiday", label: shifts ? `${holiday.name} · ${shifts} vardiya` : holiday.name };
  }
  if (excelSerialToDate(serial).getUTCDay() === 0) return { shifts: 0, kind: "sunday", label: "Pazar · üretim yok" };
  return { shifts: shiftCount(machine.shiftFactor), kind: "normal", label: `${shiftCount(machine.shiftFactor)} vardiya` };
}

export function removeMachineShiftOverrides(seed: PlanningSeed, machineIds: string[], startValue: number, endValue: number): void {
  const targets = new Set(machineIds);
  const start = Math.floor(Math.min(startValue, endValue));
  const end = Math.floor(Math.max(startValue, endValue));
  const nextEvents: MachineCalendarEvent[] = [];
  for (const event of seed.calendarEvents ?? []) {
    const overlaps = event.kind === "shift" && targets.has(event.machineId) && Math.floor(event.start) <= end && Math.floor(event.end) >= start;
    if (!overlaps) {
      nextEvents.push(event);
      continue;
    }
    if (Math.floor(event.start) < start) nextEvents.push({ ...event, id: `${event.id}-sol-${start}`, end: start - 1 });
    if (Math.floor(event.end) > end) nextEvents.push({ ...event, id: `${event.id}-sag-${end}`, start: end + 1 });
  }
  seed.calendarEvents = nextEvents;
}

export function replaceMachineShiftOverrides(seed: PlanningSeed, machineIds: string[], startValue: number, endValue: number, shiftsValue: number, name = "Vardiya değişikliği"): void {
  const start = Math.floor(Math.min(startValue, endValue));
  const end = Math.floor(Math.max(startValue, endValue));
  removeMachineShiftOverrides(seed, machineIds, start, end);
  const shifts = shiftCount(shiftsValue);
  const stamp = Date.now();
  seed.calendarEvents = [...(seed.calendarEvents ?? []), ...machineIds.map((machineId, index) => ({ id: `vardiya-${stamp}-${index}`, machineId, kind: "shift" as const, name, start, end, shiftCount: shifts }))];
}

function addMachineWorkdays(seed: PlanningSeed, machine: Pick<Machine, "id" | "shiftFactor">, startSerial: number, daysValue: number, offset: number): number {
  const defaultShifts = shiftCount(machine.shiftFactor);
  if (defaultShifts <= 0) return addWorkdays(startSerial, daysValue, new Set(seed.holidays.map((holiday) => Math.floor(holiday.serial))), offset);
  let serial = Math.floor(startSerial);
  let remainingShiftUnits = Math.max(0, Math.trunc(daysValue)) * defaultShifts;
  let guard = 0;
  while (remainingShiftUnits > 0) {
    serial += 1;
    remainingShiftUnits -= machineDayCapacity(seed, machine, serial).shifts;
    guard += 1;
    if (guard > 36_600) throw new Error(`${machine.id} için çalışılabilir takvim günü bulunamadı.`);
  }
  return serial + offset;
}

function normalizedDiameter(value: string): string {
  return value.toUpperCase().replace("Ø", "").replace(/MM/g, "").replace(/\s/g, "").replace(".", ",");
}

function isProductCode(value: string): boolean {
  return /^R.{7,}$/i.test(value.trim());
}

function unique<T>(values: T[]): T[] {
  return [...new Set(values)];
}

function machineCapacityFactor(machine: Pick<Machine, "capacityFactor">): number {
  return Number.isFinite(machine.capacityFactor) ? machine.capacityFactor : 1;
}

export const DEFAULT_SETUP_SETTINGS: NormalizedSetupSettings = {
  model: "product-family",
  shiftHours: 8,
  sameDiameterHours: 1,
  differentDiameterHours: 3,
  sameFamilyDifferentDiameterHours: 2,
  crossFamilyHours: 5,
};

export function getSetupSettings(seed: Pick<PlanningSeed, "setupSettings">): NormalizedSetupSettings {
  const source = seed.setupSettings ?? DEFAULT_SETUP_SETTINGS;
  const model = source.model === "diameter-only" ? "diameter-only" : "product-family";
  const nonNegative = (value: number | undefined, fallback: number) => Number.isFinite(value) ? Math.max(0, Number(value)) : fallback;
  return {
    model,
    shiftHours: Math.max(1, Math.min(24, nonNegative(source.shiftHours, DEFAULT_SETUP_SETTINGS.shiftHours))),
    sameDiameterHours: nonNegative(source.sameDiameterHours, DEFAULT_SETUP_SETTINGS.sameDiameterHours),
    differentDiameterHours: nonNegative(source.differentDiameterHours, DEFAULT_SETUP_SETTINGS.differentDiameterHours),
    sameFamilyDifferentDiameterHours: nonNegative(source.sameFamilyDifferentDiameterHours, DEFAULT_SETUP_SETTINGS.sameFamilyDifferentDiameterHours),
    crossFamilyHours: nonNegative(source.crossFamilyHours, DEFAULT_SETUP_SETTINGS.crossFamilyHours),
  };
}

export function productSetupFamily(seed: Pick<PlanningSeed, "products">, productCode: string): ProductSetupFamily | undefined {
  const code = productCode.trim().toUpperCase();
  const storedFamily = seed.products.find((product) => product.product.trim().toUpperCase() === code)?.setupFamily;
  return resolvedProductSetupFamily(code, storedFamily);
}

export function setupTypeRank(type: SetupType | undefined): number {
  if (type === "same-product") return 0;
  if (type === "same-diameter") return 1;
  if (type === "same-family") return 2;
  if (type === "different-diameter") return 3;
  if (type === "cross-family") return 4;
  return 5;
}

export function calculateSetup(seed: Pick<PlanningSeed, "setupSettings" | "products">, previousProduct: string, previousDiameter: string, nextProduct: string, nextDiameter: string): { hours: number; type: SetupType; label: string } {
  const settings = getSetupSettings(seed);
  const previousCode = previousProduct.trim().toUpperCase();
  const nextCode = nextProduct.trim().toUpperCase();
  const previous = normalizedDiameter(previousDiameter);
  const next = normalizedDiameter(nextDiameter);
  if (previousCode && nextCode && previousCode === nextCode) return { hours: 0, type: "same-product", label: "Aynı ürün · setup yok" };
  if (settings.model === "product-family" && previousCode && nextCode) {
    const previousFamily = productSetupFamily(seed, previousCode);
    const nextFamily = productSetupFamily(seed, nextCode);
    if (previousFamily && nextFamily && previousFamily !== nextFamily) {
      return { hours: settings.crossFamilyHours, type: "cross-family", label: "Center Pin ↔ piston geçişi" };
    }
    if (previous && next && previous === next) return { hours: settings.sameDiameterHours, type: "same-diameter", label: "Farklı ürün · aynı çap" };
    if (previousFamily && nextFamily && previousFamily === nextFamily) {
      return { hours: settings.sameFamilyDifferentDiameterHours, type: "same-family", label: "Aynı aile · farklı çap" };
    }
  }
  if (previous && next && previous === next) return { hours: settings.sameDiameterHours, type: "same-diameter", label: "Aynı çap setup" };
  return { hours: settings.differentDiameterHours, type: "different-diameter", label: "Farklı çap / başlangıç setup" };
}

function machineRunHours(seed: Pick<PlanningSeed, "setupSettings">, machine: Pick<Machine, "rates" | "capacityFactor">, productCode: string, quantity: number): number {
  const shiftRate = machine.rates[productCode.toUpperCase()] ?? 0;
  const hourlyRate = (shiftRate / getSetupSettings(seed).shiftHours) * machineCapacityFactor(machine);
  return hourlyRate > 0 ? quantity / hourlyRate : Number.POSITIVE_INFINITY;
}

export function addMachineCapacityHours(seed: PlanningSeed, machine: Pick<Machine, "id" | "shiftFactor" | "finishOffset">, startValue: number, hoursValue: number): { start: number; end: number } {
  let cursor = Math.max(0, startValue);
  let remaining = Math.max(0, hoursValue);
  let actualStart = 0;
  let guard = 0;
  const shiftHours = getSetupSettings(seed).shiftHours;
  while (remaining > 0 || !actualStart) {
    const day = Math.floor(cursor);
    const capacityHours = machineDayCapacity(seed, machine, day).shifts * shiftHours;
    const windowStart = day;
    const windowEnd = day + capacityHours / 24;
    if (capacityHours <= 0 || cursor >= windowEnd - 1e-8) {
      cursor = day + 1;
      guard += 1;
      if (guard > 36_600) throw new Error(`${machine.id} için çalışılabilir takvim saati bulunamadı.`);
      continue;
    }
    cursor = Math.max(cursor, windowStart);
    if (!actualStart) actualStart = cursor;
    if (remaining <= 0) break;
    const availableHours = Math.max(0, (windowEnd - cursor) * 24);
    const consumed = Math.min(remaining, availableHours);
    cursor += consumed / 24;
    remaining -= consumed;
    if (remaining > 1e-8) cursor = day + 1;
    guard += 1;
    if (guard > 36_600) throw new Error(`${machine.id} için çalışılabilir takvim saati bulunamadı.`);
  }
  return { start: actualStart, end: Math.round((cursor + machine.finishOffset) * 1_000_000) / 1_000_000 };
}

export function machineCapacityHoursBetween(
  seed: PlanningSeed,
  machine: Pick<Machine, "id" | "shiftFactor">,
  startValue: number,
  endValue: number,
): number {
  const start = Math.max(0, startValue);
  const end = Math.max(start, endValue);
  const shiftHours = getSetupSettings(seed).shiftHours;
  let total = 0;
  for (let day = Math.floor(start); day <= Math.floor(end); day += 1) {
    const capacityHours = machineDayCapacity(seed, machine, day).shifts * shiftHours;
    if (capacityHours <= 0) continue;
    const windowStart = day;
    const windowEnd = day + capacityHours / 24;
    total += Math.max(0, Math.min(end, windowEnd) - Math.max(start, windowStart)) * 24;
  }
  return total;
}

const BALANCED_UTILIZATION_TOLERANCE = 0.12;

const RESTRICTED_MACHINE_IDS = new Set(["C-03", "C-04", "C-11", "C-12", "C-15", "C-16", "C-17"]);
const LARGE_DIAMETER_BLOCKED = new Set(["C-01", "C-02", "C-04", "C-05"]);

export function isMachineEligibleForProduct(seed: PlanningSeed, machineId: string, productCode: string): boolean {
  if (!turningEnabled(seed.processMasterData, productCode)) return false;
  const code = productCode.toUpperCase();
  const product = seed.products.find((item) => item.product.toUpperCase() === code);
  if (!product) return false;
  if (product.inactiveMachineIds?.includes(machineId)) return false;
  const preference = seed.preferences.find((rule) => rule.key.toUpperCase() === code);
  if (preference) return preference.machines.includes(machineId);
  // A saved preference is authoritative. Products without one keep the legacy
  // workbook fallbacks below so the V51 baseline remains unchanged.
  if (diameterNumeric(product.diameter) >= 25.5 && LARGE_DIAMETER_BLOCKED.has(machineId)) return false;
  if (!RESTRICTED_MACHINE_IDS.has(machineId)) return true;
  return seed.restrictions.some((rule) => rule.machineId === machineId && rule.product.toUpperCase() === code);
}

export type ScenarioStrategy = "v51" | "optimized";

export function runV51Scenario(seed: PlanningSeed, fixedBatches: PlannedBatch[] = []): ScenarioResult {
