import { processWaitWorkdays } from "./process-waits";
import { flowRule, addDepartmentWorkMinutes, type FlowSettings } from "./flow-settings";
import { dynamicFlowTiming } from "./process-flow";
import { factoryNowSerial } from "./factory-time";
import { turningIdentityScope } from "./turning-queue-identity";
import { actualProcessStartEligibility } from './process-eligibility';
import { describeProcessRoute, processQueueEntries, type ProcessRouteStep, type ProcessReadinessIssue, type ProcessQueueEntry } from './process-route-state';
import { assertProductionSwitchSnapshot, isProductionInterruption, hasActiveProductionInterruption, activeLotInterruptions, validateProductionInterruption, type ProductionInterruptionInput } from "./production-interruptions";
import {
  addMachineCapacityHours,
  currentJobRouteIdentity,
  excelSerialToDate,
  getSetupSettings,
  machineDayCapacity,
  type Machine,
  type PlannedBatch,
  type ProcessCurrentJob,
  type PlanningSeed,
  type ScenarioResult,
  type WipLot,
} from "./planning";
import {
  activeProcessResourceIds,
  processMasterDataForProduct,
  productProcessRoute,
  PRODUCT_PROCESS_ORDER,
  resourceSupportsProcessProduct,
  type DownstreamProcess,
  type ProcessKind,
  type ProcessMasterData,
  type ProcessProduct,
  type ProcessResource,
  type ProductFamily,
  type ProductProcessParameter,
} from "./process-master-data";
import { addFactoryWorkdays, routedDeliveryReadyAt } from "./delivery-calendar";
import { completeWipOperation, wipOperationReadyAt, wipCompletionEarliestAt } from "./wip-ledger";

export type ProcessPlanWarning = {
  code: "missing-product" | "missing-parameter" | "missing-resource" | "invalid-capacity" | "duplicate-definition" | "invalid-route" | "placement-conflict" | "flow-target";
  message: string;
  product?: string;
  batchId?: string;
};

export type ProcessGapDiagnostic = {
  id: string;
  process: DownstreamProcess;
  resourceId: string;
  start: number;
  end: number;
  code: "upstream-not-ready" | "route-wait" | "maintenance" | "zero-shift" | "closed-day" | "daily-capacity" | "no-eligible-wip";
  message: string;
};

export type ProcessOperation = {
  flowTargetEnd?: number;
  flowReason?: string;
  requiresInterruptionConfirmation?: boolean;
  manualCandidate?: boolean;
  id: string;
  batchId: string;
  product: string;
  family: ProductFamily;
  quantity: number;
  process: ProcessKind;
  /** Original historical process identity; washing is not a completed GKM. */
  recordedProcess?: "turning" | "drilling" | "deburring" | "washing" | "gkm";
  sequence: number;
  resourceId: string;
  resourceName: string;
  setupKey: string;
  unitsPerShift: number;
  setupHours: number;
  /** Capacity kept free to restore setup for the next reserved operation. */
  protectedSetupHoursAfter?: number;
  runHours: number;
  waitWorkdaysBefore: number;
  /** First upstream quantity that makes a pipelined operation eligible to start. */
  transferBatchQuantity?: number;
  readyAt: number;
  start: number;
  end: number;
  plannedStart?: number;
  plannedEnd?: number;
  predecessorOperationId?: string;
  source: "current-turning" | "turning-plan" | "wip";
  actual: boolean;
  current?: boolean;
  workOrder: string;
  wipLotId?: string;
  manualOverride?: boolean;
  /**
   * Display only: the wait that produced readyAt. Planned work names the rule
   * scheduleStage actually used; recorded work names its recorded readiness.
   * Never an input to scheduling.
   */
  waitRuleLabel?: string;
};

export type RoutedProcessJob = {
  familyKnown?: boolean;
  routeSteps?: ProcessRouteStep[];
  readinessIssues?: ProcessReadinessIssue[];
  /** Display-only archive projection; never fed into scheduling. */
  archivedDelivery?: boolean;
  historyIncomplete?: boolean;
  batchId: string;
  source: "current-turning" | "turning-plan" | "wip";
  workOrder: string;
  wipLotId?: string;
  product: string;
  family: ProductFamily;
  quantity: number;
  turningMachineId: string;
  operations: ProcessOperation[];
  completion: number;
  deliveryReadyAt: number;
};

export type DownstreamProcessPlan = {
  queueEntries?: ProcessQueueEntry[];
  state: "empty" | "planned";
  operations: ProcessOperation[];
  jobs: RoutedProcessJob[];
  warnings: ProcessPlanWarning[];
  gaps: ProcessGapDiagnostic[];
  completion: number;
  deliveryCompletion: number;
};

type QueueState = {
  tail: number;
  product: string;
  family: ProductFamily;
  setupKey: string;
};

type JobSource = {
  id: string;
  source: "current-turning" | "turning-plan" | "wip";
  product: string;
  quantity: number;
  workOrder: string;
  releaseAt: number;
  nextProcess: DownstreamProcess | undefined;
  batch?: PlannedBatch;
  machine?: Machine;
  lot?: WipLot;
  masterProduct: ProcessProduct;
};

type SetupSource = Pick<QueueState, "product" | "family" | "setupKey">;



export function calculateDownstreamSetup(
  process: DownstreamProcess,
  previous: SetupSource | undefined,
  next: SetupSource,
  settings?: FlowSettings,
): { hours: number; label: string } {
  if (settings?.enabled && (process === "drilling" || process === "deburring" || process === "gkm")) {
    const values = settings.setupMinutes[process];
    const key = !previous ? "first" : previous.product === next.product ? "sameProduct" : previous.family !== next.family ? "differentFamily" : previous.setupKey === next.setupKey ? "sameKey" : "differentKey";
    return { hours: values[key] / 60, label: "SETUP Süreleri" };
  }
  if (process === "gkm") return { hours: 0, label: "GKM geçişi · setup yok" };
  if (!previous) return process === "drilling"
    ? { hours: 3, label: "İlk delme hazırlığı" }
    : { hours: 1, label: "İlk çapak alma hazırlığı" };
  if (previous.product === next.product) return { hours: 0, label: "Aynı ürün · setup yok" };
  if (process === "deburring") return { hours: 1, label: "Ürün değişimi" };
  if (previous.family !== next.family) return { hours: 5, label: "Piston ↔ Center Pin geçişi" };
  if (previous.setupKey === next.setupKey) return { hours: 1, label: "Aynı delik çapı" };
  return { hours: 3, label: "Farklı delik çapı" };
}

export function addProcessWaitWorkdays(seed: PlanningSeed, startValue: number, workdaysValue: number): number {
  return addFactoryWorkdays(seed, startValue, workdaysValue);
}

export function validateProcessMasterData(master: ProcessMasterData): ProcessPlanWarning[] {
  const warnings: ProcessPlanWarning[] = [];
  const resources = new Map<string, ProcessResource>();
  for (const resource of master.resources) {
    if (resources.has(resource.id)) warnings.push({ code: "duplicate-definition", message: `${resource.id} iş merkezi birden fazla tanımlanmış.` });
    resources.set(resource.id, resource);
  }
  const products = new Set<string>();
  for (const product of master.products) {
    if (products.has(product.product)) warnings.push({ code: "duplicate-definition", product: product.product, message: `${product.product} ürün rotası birden fazla tanımlanmış.` });
    products.add(product.product);
    const expected = product.route ? product.route.filter(process => process !== "turning") : product.family === "piston" ? ["drilling", "deburring", "gkm"] : ["drilling", "gkm"];
    if (product.route && (!product.route.length || product.route.join("|") !== PRODUCT_PROCESS_ORDER.filter(process => product.route!.includes(process)).join("|"))) warnings.push({ code: "invalid-route", product: product.product, message: `${product.product} aktif proses sırası geçersiz.` });
    const actual = product.processes.slice().sort((left, right) => left.sequence - right.sequence).map((item) => item.process);
    if (actual.join("|") !== expected.join("|")) warnings.push({ code: "invalid-route", product: product.product, message: `${product.product} rotası beklenen proses sırasıyla uyuşmuyor.` });
    const processKeys = new Set<string>();
    for (const parameter of product.processes) {
      if (processKeys.has(parameter.process)) warnings.push({ code: "duplicate-definition", product: product.product, message: `${product.product} için ${parameter.process} prosesi birden fazla tanımlanmış.` });
      processKeys.add(parameter.process);
      if (parameter.process === "drilling" && !parameter.setupKey.trim()) warnings.push({ code: "missing-parameter", product: product.product, message: `${product.product} için matkap çapı tanımlı değil.` });
      for (const resourceId of parameter.resourcePriority) {
        const resource = resources.get(resourceId);
        if (!resource || resource.process !== parameter.process) {
          warnings.push({ code: "missing-resource", product: product.product, message: `${product.product} · ${parameter.process} için ${resourceId} iş merkezi bulunamadı.` });
        }
        const capacity = parameter.unitsPerShift[resourceId];
        if (!Number.isFinite(capacity) || capacity <= 0) warnings.push({ code: "invalid-capacity", product: product.product, message: `${product.product} · ${resourceId} vardiya kapasitesi geçersiz.` });
      }
    }
  }
  return warnings;
}

function turningOperation(seed: PlanningSeed, source: JobSource): ProcessOperation {
  const { batch, masterProduct } = source;
  const machine = source.machine ?? seed.machines.find((item) => item.id === batch?.machineId);
  if (!machine) throw new Error("Torna kaynağı bulunamadı.");
  const current = source.source === "current-turning" ? machine.currentJob : undefined;
  const start = current?.start ?? batch?.start ?? 0;
  const end = current?.end ?? batch?.end ?? 0;
  const quantity = current?.quantity ?? batch?.quantity ?? source.quantity;
  const product = current?.product ?? batch?.product ?? source.product;
  const diameter = current?.diameter ?? batch?.diameter ?? "";
  return {
    id: `${source.id}:turning`,
    batchId: source.id,
    product,
    family: masterProduct.family,
    quantity,
    process: "turning",
    sequence: 0,
    resourceId: machine.id,
    resourceName: machine.name,
    setupKey: diameter,
    unitsPerShift: machine.rates[product.toUpperCase()] ?? 0,
    setupHours: batch?.setupHours ?? 0,
    runHours: batch?.runHours ?? Math.max(0, (end - start) * 24),
    waitWorkdaysBefore: 0,
    readyAt: start,
    start,
    end,
    source: source.source,
    actual: false,
    workOrder: source.workOrder,
  };
}

export function actualWipOperations(lot: WipLot | undefined, masterProduct?: ProcessProduct): ProcessOperation[] {
  if (!lot) return [];
  return (lot.completedSteps ?? []).map((step, index) => ({
    id: `${lot.id}:${step.process}:actual:${index}`,
    batchId: lot.id,
    product: lot.product,
    family: masterProduct?.family ?? lot.family,
    quantity: step.quantity,
    process: step.process === "washing" ? "gkm" : step.process,
    recordedProcess: step.process,
    sequence: step.process === "turning" ? 0 : (masterProduct?.processes.find((item) => item.process === step.process)?.sequence ?? index + 1),
    resourceId: step.resourceId,
    resourceName: step.resourceName,
    setupKey: "actual",
    unitsPerShift: 0,
    setupHours: 0,
    runHours: Math.max(0, (step.end - step.start) * 24),
    waitWorkdaysBefore: 0,
    waitRuleLabel: "Fiili kayıt · kayıtlı başlangıç ve bitiş",
    readyAt: step.start,
    start: step.start,
    end: step.end,
    plannedStart: step.plannedStart,
    plannedEnd: step.plannedEnd,
    source: "wip",
    actual: true,
    workOrder: lot.workOrder,
    wipLotId: lot.id,
  }));
}

function processCalendarSeed(seed: PlanningSeed, resourceId: string): PlanningSeed {
  if (!resourceId.startsWith("B-01-S")) return seed;
  const shared = (seed.calendarEvents ?? []).filter((event) => event.machineId === "B-01");
  if (!shared.length) return seed;
  return {
    ...seed,
    calendarEvents: [
      ...(seed.calendarEvents ?? []),
      ...shared.map((event) => ({ ...event, id: `${event.id}-${resourceId}`, machineId: resourceId })),
    ],
  };
}

function processResource(master: ProcessMasterData, resourceId: string): ProcessResource | undefined {
  return master.resources.find((resource) => resource.id === resourceId);
}

function setupSourceForOperation(operation: ProcessOperation): SetupSource {
  return {
    product: operation.product,
    family: operation.family,
    setupKey: operation.setupKey,
  };
}

/** Resolve a saved placement through recorded lineage, with current-job reuse protection. */
export function processPlacementOverride(seed: PlanningSeed, batchId: string, product: string, process: DownstreamProcess, allowInheritance = true) {
  const identities = [batchId];
  const sourceBatchIds = new Set<string>();
  let lot = seed.wipLots?.find(item => item.id === batchId);
  const machine = seed.machines?.find(item => `current:${item.id}` === batchId);
  const visited = new Set<string>();
  while (allowInheritance && lot && !visited.has(lot.id)) {
    visited.add(lot.id);
    if (lot.sourceBatchId) sourceBatchIds.add(lot.sourceBatchId);
    if (lot.parentLotId) identities.push(lot.parentLotId);
    lot = seed.wipLots?.find(item => item.id === lot!.parentLotId);
  }
  identities.push(...sourceBatchIds);
  if (allowInheritance && machine?.currentJob.batchId) identities.push(machine.currentJob.batchId);
  return identities.flatMap(id => seed.processOperationOverrides?.filter(item => item.batchId === id && item.process === process && (!item.sourceProduct || item.sourceProduct === product) && (!item.sourceCurrentJobKey || machine && currentJobRouteIdentity(machine) === item.sourceCurrentJobKey)) ?? [])[0];
}

const inputDateSerial = (value: string): number => value ? (Date.parse(`${value}T00:00:00Z`) - Date.UTC(1899, 11, 30)) / 86_400_000 : 0;

/** Delivery date that the charge serves: its demand checkpoint, else the earliest open order of the product. */
function sourceDueSerial(seed: PlanningSeed, source: JobSource): number | undefined {
  const own = source.batch?.demandDueDate ? inputDateSerial(source.batch.demandDueDate) : 0;
  if (own > 0) return own;
  const dates = seed.orders.filter(order => order.product.toUpperCase() === source.product.toUpperCase() && order.quantity > 0 && order.dueDate)
    .map(order => inputDateSerial(order.dueDate)).filter(value => value > 0);
  return dates.length ? Math.min(...dates) : undefined;
}

function scheduleStage(
  seed: PlanningSeed,
  master: ProcessMasterData,
  process: DownstreamProcess,
  sources: JobSource[],
  operationsByKey: Map<string, ProcessOperation>,
  warnings: ProcessPlanWarning[],
  includeInterruptedCandidates = false,
  continuationControl: { enabled: boolean; used: boolean } = { enabled: false, used: false },
): ProcessOperation[] {
  const queueByResource = new Map<string, QueueState>();
  const usableResources = (source: JobSource, parameter: ProductProcessParameter) => activeProcessResourceIds(parameter).filter(id => {
    const resource = processResource(master, id);
    return resource?.active && resource.process === process && resource.defaultShifts > 0 && resourceSupportsProcessProduct(resource, source.masterProduct) && parameter.unitsPerShift[id] > 0;
  });
  const strategy = master.planningStrategies?.[process] ?? (process === "drilling" ? "campaign" : "earliest-ready");
  const candidates = sources.flatMap((source) => {
    if (!source.nextProcess) return [];
    const parameter = source.masterProduct.processes.find((item) => item.process === process);
    if (!parameter) return [];
    if (source.masterProduct.route && !source.masterProduct.route.includes(process)) return [];
    const orderedRoute = productProcessRoute(source.masterProduct).filter(item => item !== "turning").map(process => ({ process }));
    const routeIndex = orderedRoute.findIndex((item) => item.process === process);
    const nextRouteIndex = orderedRoute.findIndex((item) => item.process === source.nextProcess);
    if (nextRouteIndex < 0) return [];
    if (routeIndex < nextRouteIndex) return [];
    const predecessorProcess = routeIndex > 0 ? orderedRoute[routeIndex - 1].process : "turning";
    const predecessor = operationsByKey.get(`${source.id}:${predecessorProcess}`);
    const firstRemaining = process === source.nextProcess;
    const interrupted = activeLotInterruptions(seed, source.lot).length > 0;
    const explicitPlacement = seed.processOperationOverrides?.some(item => item.batchId === source.id && item.process === process);
    const running = seed.processCurrentJobs?.some(item => item.batchId === source.id && item.process === process);
    if (seed.productionInterruptions?.some(item => isProductionInterruption(item) && !item.completedAt && item.chargeId === source.id && item.process === source.nextProcess) && !firstRemaining) return [];
    if (interrupted && !running && !explicitPlacement && !(includeInterruptedCandidates && firstRemaining)) return [];
    if (!predecessor && !firstRemaining) {
      warnings.push({ code: "missing-parameter", product: source.product, batchId: source.id, message: `${source.product} · ${process} için önceki rota adımı bulunamadı.` });
      return [];
    }
    const effectiveWaitWorkdays = firstRemaining && source.source === "wip"
      ? 0 : processWaitWorkdays(seed, predecessorProcess);
    // A planned downstream operation represents the source's full quantity.
    // Releasing that aggregate operation when only the first transfer batch is
    // ready would allow the full charge to finish before turning is complete.
    const rule = flowRule(seed, source.masterProduct.family, predecessorProcess, process);
    const legacyReadyAt = firstRemaining && source.source === "wip" ? source.releaseAt
      : addProcessWaitWorkdays(seed, predecessor?.end ?? source.releaseAt, effectiveWaitWorkdays);
    const usesRule = rule && !(firstRemaining && source.source === "wip");
    const readyAt = usesRule ? rule.mode === "static"
      ? addDepartmentWorkMinutes(seed, predecessor?.end ?? source.releaseAt, rule.minutes)
      : predecessor?.start ?? source.releaseAt : legacyReadyAt;
    const storedOverride = processPlacementOverride(seed, source.id, source.product, process, !interrupted);
    const override = storedOverride?.routeMode === "automatic" ? undefined : storedOverride?.routeMode === "priority" ? { ...storedOverride, requestedStart: readyAt } : storedOverride;
    const currentJob = seed.processCurrentJobs?.find((item) => item.batchId === source.id && item.process === process);

    const hours = (minutes: number) => String(Math.round(minutes / 60 * 100) / 100).replace(".", ",");
    const waitRuleLabel = currentJob ? "Çalışan iş · kayıtlı başlangıç"
      : firstRemaining && source.source === "wip" ? "Kayıtlı hazır olma (yarı mamul)"
      : usesRule ? rule.mode === "dynamic" ? `Bitiş farkı hedefi ${hours(rule.minutes)} takvim saati` : `${hours(rule.minutes)} çalışma saati`
      : effectiveWaitWorkdays > 0 ? `${effectiveWaitWorkdays} iş günü` : "Bekleme yok";
    return [{ source, parameter, predecessor, readyAt, override, currentJob, effectiveWaitWorkdays, waitRuleLabel, rule: usesRule ? rule : undefined }];
  }).sort((left, right) => {
    if (Boolean(left.currentJob) !== Boolean(right.currentJob)) return left.currentJob ? -1 : 1;
    // A deliberately interrupted current job resumes before the automatic campaign.
    if (Boolean(left.override?.resumeAfterCurrent) !== Boolean(right.override?.resumeAfterCurrent)) return left.override?.resumeAfterCurrent ? -1 : 1;
    // Reserve constrained products using configured eligibility, never a machine name.
    if (process === "drilling") {
      const difference = usableResources(left.source, left.parameter).length - usableResources(right.source, right.parameter).length;
      if (difference) return difference;
    }
    // Delme: readiness is a feasibility limit. Work that is ready before any
    // eligible machine is free competes from that machine-free time, so an
    // older-ready flexible job cannot push an urgent job back (T11).
    // Every area keeps the availableStart clamp. Piston also counts a recorded
    // current job, which occupies its machine until its recorded end.
    const currentEnds = (id: string, item: typeof left) => seed.productionArea === "cubuk-filtre" ? []
      : (seed.processCurrentJobs ?? []).filter(job => job.resourceId === id && job.batchId !== item.source.id).map(job => job.end);
    const machineFree = (item: typeof left) => process === "drilling"
      ? Math.min(...usableResources(item.source, item.parameter).map(id => Math.max(processResource(master, id)?.availableStart ?? 0, ...currentEnds(id, item))), Number.POSITIVE_INFINITY)
      : 0;
    const leftScheduleAt = Math.max(left.readyAt, left.override?.requestedStart ?? left.readyAt, Number.isFinite(machineFree(left)) ? machineFree(left) : 0);
    const rightScheduleAt = Math.max(right.readyAt, right.override?.requestedStart ?? right.readyAt, Number.isFinite(machineFree(right)) ? machineFree(right) : 0);
    const leftOrder = left.override?.queueOrder ?? Number.MAX_SAFE_INTEGER;
    const rightOrder = right.override?.queueOrder ?? Number.MAX_SAFE_INTEGER;
    if (leftOrder !== rightOrder) return leftOrder - rightOrder;
    if (Math.abs(leftScheduleAt - rightScheduleAt) > 1e-8) return leftScheduleAt - rightScheduleAt;
    const rank = (source: JobSource["source"]) => source === "wip" ? 0 : source === "current-turning" ? 1 : 2;
    // Delme: delivery date, downstream supply and saved placement come before
    // the source class (T11); other processes keep the source class here.
    if (process !== "drilling" && left.source.source !== right.source.source) return rank(left.source.source) - rank(right.source.source);
    if (process === "drilling") {
      // A saved manual placement is a planner commitment; place it before
      // automatic work with the same readiness so continuation sees it.
      if (Boolean(left.override) !== Boolean(right.override)) return left.override ? -1 : 1;
      // T11 priority after readiness: earlier delivery date, then work that
      // feeds Çapak Alma (Piston), then setup grouping.
      const leftDue = sourceDueSerial(seed, left.source) ?? Number.MAX_SAFE_INTEGER;
      const rightDue = sourceDueSerial(seed, right.source) ?? Number.MAX_SAFE_INTEGER;
      if (leftDue !== rightDue) return leftDue - rightDue;
      const feeds = (item: typeof left) => productProcessRoute(item.source.masterProduct).includes("deburring") ? 0 : 1;
      if (feeds(left) !== feeds(right)) return feeds(left) - feeds(right);
      if (left.source.source !== right.source.source) return rank(left.source.source) - rank(right.source.source);
    }
    if (strategy === "campaign") {
      const setupOrder = left.parameter.setupKey.localeCompare(right.parameter.setupKey, "tr", { numeric: true });
      if (setupOrder) return setupOrder;
      const productOrder = left.source.product.localeCompare(right.source.product, "tr", { numeric: true });
      if (productOrder) return productOrder;
    }
    return left.readyAt - right.readyAt || left.source.releaseAt - right.source.releaseAt || left.source.id.localeCompare(right.source.id);
  });

  // Resources that the planner pinned for a product (saved manual placement)
  // count as already set for that type in the T12 continuation check.
  const pinnedProducts = new Map<string, Set<string>>();
  for (const item of candidates) if (item.override && !item.currentJob) {
    const set = pinnedProducts.get(item.override.resourceId) ?? new Set<string>();
    set.add(item.source.product);
    pinnedProducts.set(item.override.resourceId, set);
  }
  const scheduled: ProcessOperation[] = [];
  for (const item of candidates) {
    const { source, parameter, predecessor, readyAt, override, currentJob, effectiveWaitWorkdays, waitRuleLabel, rule } = item;
    const nextSetup: SetupSource = { product: source.product, family: source.masterProduct.family, setupKey: parameter.setupKey };
    const activeResources = activeProcessResourceIds(parameter);
    const resourceCandidates = currentJob ? [currentJob.resourceId] : override ? activeResources.filter((id) => id === override.resourceId) : activeResources;
    const evaluated = resourceCandidates.flatMap((resourceId, priority) => {
      const resource = processResource(master, resourceId);
      const unitsPerShift = parameter.unitsPerShift[resourceId];
      if (!resource || resource.process !== process || !resource.active || resource.defaultShifts <= 0 || !resourceSupportsProcessProduct(resource, source.masterProduct) || !Number.isFinite(unitsPerShift) || unitsPerShift <= 0) return [];
      const queue = queueByResource.get(resourceId);
      const setup = calculateDownstreamSetup(process, queue, nextSetup, seed.flowSettings);
      if (!Number.isFinite(setup.hours)) return [];
      const runHours = currentJob
        ? Math.max(0, (currentJob.end - currentJob.start) * 24 - currentJob.setupHours)
        : source.quantity / unitsPerShift * getSetupSettings(seed).shiftHours;
      const requestedStart = Math.max(readyAt, queue?.tail ?? readyAt, override?.requestedStart ?? readyAt, currentJob ? readyAt : resource.availableStart ?? readyAt);
      const timeline = currentJob
        ? { start: currentJob.start, end: currentJob.end }
        : rule?.mode === "dynamic" && predecessor
          ? dynamicFlowTiming(seed, processCalendarSeed(seed, resource.id), resource, predecessor, requestedStart, setup.hours, runHours, source.quantity, rule.minutes)
          : addMachineCapacityHours(
            processCalendarSeed(seed, resource.id),
            { id: resource.id, shiftFactor: resource.defaultShifts, finishOffset: 0 },
            requestedStart,
            setup.hours + runHours,
          );
      // An infeasible tail must not hide an earlier feasible idle window.
      const options = [{ resource, unitsPerShift, setupHours: setup.hours, protectedSetupHoursAfter: 0, runHours, priority, gapIndex: -1, previousOperation: undefined as ProcessOperation | undefined, ...timeline }]
        .filter(option => currentJob || !resource.planEnd || option.end <= Math.floor(resource.planEnd) + 1 + 1e-8);

      if (!currentJob && process === "drilling") {
        // Rebuild from placed intervals on every evaluation; never reuse a stale gap.
        // Reviewed queues are consumed in their saved order and cannot jump backwards.
        const reservations = scheduled.filter(operation => operation.resourceId === resource.id)
          .sort((left, right) => left.start - right.start || left.end - right.end || left.id.localeCompare(right.id));
        const currentEnd = Math.max(0, ...reservations.filter(operation => operation.current).map(operation => operation.end));
        const gaps = reservations.map((nextReservation, index) => ({
          nextReservation,
          previousOperation: reservations[index - 1],
          cursor: Math.max(reservations[index - 1]?.end ?? 0, currentEnd),
          tail: reservations[index - 1] ? setupSourceForOperation(reservations[index - 1]) : undefined,
        }));

        const calendarSeed = processCalendarSeed(seed, resource.id);
        for (const [gapIndex, gap] of gaps.entries()) {
          // Manual gap insertion may precede a reservation only when its
          // reviewed order permits that position; never reverse saved queue order.
          const nextOverride = processPlacementOverride(seed, gap.nextReservation.batchId, gap.nextReservation.product, process);
          if (override?.queueOrder !== undefined && nextOverride?.queueOrder !== undefined && override.queueOrder > nextOverride.queueOrder) continue;
          const incomingSetup = calculateDownstreamSetup(process, gap.tail, nextSetup, seed.productionArea === "cubuk-filtre" ? undefined : seed.flowSettings);
          const gapStart = Math.max(readyAt, gap.cursor, override?.requestedStart ?? readyAt, resource.availableStart ?? readyAt);
          const gapTimeline = rule?.mode === "dynamic" && predecessor
            ? dynamicFlowTiming(seed, calendarSeed, resource, predecessor, gapStart, incomingSetup.hours, runHours, source.quantity, rule.minutes)
            : addMachineCapacityHours(calendarSeed,
            { id: resource.id, shiftFactor: resource.defaultShifts, finishOffset: 0 },
            gapStart, incomingSetup.hours + runHours);
          if (resource.planEnd && gapTimeline.end > Math.floor(resource.planEnd) + 1 + 1e-8) continue;
          const requiredReservedSetup = calculateDownstreamSetup(process, nextSetup, setupSourceForOperation(gap.nextReservation), seed.productionArea === "cubuk-filtre" ? undefined : seed.flowSettings).hours;
          const protectedSetupHoursAfter = Math.max(0, requiredReservedSetup - gap.nextReservation.setupHours);
          const restored = addMachineCapacityHours(
            calendarSeed,
            { id: resource.id, shiftFactor: resource.defaultShifts, finishOffset: 0 },
            gapTimeline.end,
            protectedSetupHoursAfter,
          );
          if (restored.end > gap.nextReservation.start + 1e-8) continue;
          options.push({
            resource,
            unitsPerShift,
            setupHours: incomingSetup.hours,
            protectedSetupHoursAfter,
            runHours,
            priority,
            gapIndex,
            previousOperation: gap.previousOperation,
            ...gapTimeline,
          });
        }
      }

      return options;
    }).sort((left, right) => left.end - right.end || left.priority - right.priority || left.resource.id.localeCompare(right.resource.id));
    const earliestFinish = evaluated[0];
    // Delme's Ana merkez is a real preference, not just a finish-time tie-break.
    // A free preferred machine must not lose the charge merely because another
    // machine saves a setup. Compare calendar-feasible starts after readiness,
    // existing queues and reservation checks, not raw resource availability.
    // When the preferred machine would start later, retain the earliest finish.
    const preferred = process === "drilling" && !currentJob && !override && earliestFinish
      ? evaluated.filter(option => option.start <= earliestFinish.start + 1e-8)
        .sort((left, right) => left.priority - right.priority || left.end - right.end || left.resource.id.localeCompare(right.resource.id))[0]
      : earliestFinish;
    // T12 (user decision 2026-10-17): keep the same type on one drilling
    // machine. A machine whose queue already ends with this product is used
    // when it still finishes before the delivery day; otherwise the earlier
    // option (possibly the second machine) protects the delivery date.
    const due = sourceDueSerial(seed, source);
    const continuation = continuationControl.enabled && process === "drilling" && !currentJob && !override && preferred && due !== undefined
      && queueByResource.get(preferred.resource.id)?.product !== source.product
      ? evaluated.filter(option => option.gapIndex < 0 && (queueByResource.get(option.resource.id)?.product === source.product || Boolean(pinnedProducts.get(option.resource.id)?.has(source.product))))
        .sort((left, right) => left.end - right.end || left.priority - right.priority)[0]
      : undefined;
    if (continuation && continuation !== preferred) continuationControl.used = true;
    const chosen = continuation ?? preferred;
    if (!chosen) {
      warnings.push({ code: "missing-resource", product: source.product, batchId: source.id, message: `${source.product} · ${process} için kullanılabilir iş merkezi veya vardiya kapasitesi yok.` });
      continue;
    }
    const operation: ProcessOperation = {
      flowTargetEnd: "targetEnd" in chosen ? chosen.targetEnd as number : undefined,
      flowReason: "reason" in chosen ? chosen.reason as string : undefined,
      id: `${source.id}:${process}`,
      batchId: source.id,
      product: source.product,
      family: source.masterProduct.family,
      quantity: currentJob?.remainingQuantity ?? source.quantity,
      process,
      sequence: parameter.sequence,
      resourceId: chosen.resource.id,
      resourceName: chosen.resource.name,
      setupKey: parameter.setupKey,
      unitsPerShift: chosen.unitsPerShift,
      setupHours: currentJob?.setupHours ?? chosen.setupHours,
      protectedSetupHoursAfter: chosen.protectedSetupHoursAfter || undefined,
      runHours: chosen.runHours,
      waitWorkdaysBefore: effectiveWaitWorkdays,
      waitRuleLabel,
      readyAt,
      start: chosen.start,
      end: chosen.end,
      predecessorOperationId: predecessor?.id,
      requiresInterruptionConfirmation: activeLotInterruptions(seed, source.lot).length > 0,
      manualCandidate: activeLotInterruptions(seed, source.lot).length > 0 && !override && !currentJob,
      source: source.source,
      actual: false,
      current: Boolean(currentJob),
      workOrder: currentJob?.workOrder ?? source.workOrder,
      wipLotId: source.lot?.id,
      manualOverride: Boolean(override),
    };
    if (operation.flowReason) warnings.push({ code: "flow-target", product: source.product, batchId: source.id, message: `${source.product} · ${processLabelForError(process)}: ${operation.flowReason}` });
    scheduled.push(operation);
    if (override?.routeMode === "keep" && !currentJob && (
      Math.abs(operation.start - (override.preservedStart ?? override.requestedStart)) > 1e-8
      || Math.abs(operation.end - (override.preservedEnd ?? operation.end)) > 1e-8
    )) warnings.push({ code: "placement-conflict", product: source.product, batchId: source.id, message: `${source.workOrder || source.product} · ${processLabelForError(process)} mevcut yerleşimi değişen girdilerle korunamıyor. Üretim akışını düzenle ile yeniden inceleyin.` });
    operationsByKey.set(`${source.id}:${process}`, operation);
    if (chosen.gapIndex >= 0) {
      // Replace the previous inserted charge's obsolete return preparation.
      // The new charge now carries the setup needed to restore the next reservation.
      if (chosen.previousOperation) chosen.previousOperation.protectedSetupHoursAfter = undefined;
    } else {
      queueByResource.set(chosen.resource.id, { tail: operation.end, ...nextSetup });
    }
  }
  return scheduled;
}

export type ProcessOperationReschedulePreview = {
  seed: PlanningSeed;
  plan: DownstreamProcessPlan;
  operation: ProcessOperation;
};

function assertProcessPlacementResource(seed: PlanningSeed, operation: ProcessOperation, resourceId: string): ProcessResource {
  const master = seed.processMasterData;
  const product = master ? processMasterDataForProduct(master, operation.product) : undefined;
  const resource = master?.resources.find((item) => item.id === resourceId);
  const parameter = product?.processes.find((item) => item.process === operation.process);
  if (!resource || resource.process !== operation.process) throw new Error(`${resourceId}, ${processLabelForError(operation.process as DownstreamProcess)} için geçerli bir iş merkezi değil.`);
  if (!resource.active) throw new Error(`${resourceId} pasif; önce iş merkezini planlamaya açın.`);
  if (resource.defaultShifts <= 0) throw new Error(`${resourceId} için vardiya 0; kapasite açılmadan iş taşınamaz.`);
  if (!product || !resourceSupportsProcessProduct(resource, product)) throw new Error(`${resourceId}, ${operation.product} ürün grubunu çalıştıramaz.`);
  if (!parameter || !activeProcessResourceIds(parameter).includes(resourceId) || !(parameter.unitsPerShift[resourceId] > 0)) throw new Error(`${operation.product} için ${resourceId} aktif iş merkezi ve vardiya hızı tanımlı değil.`);
  return resource;
}

export type ProcessGanttPlacementPreview = ProcessOperationReschedulePreview & {
  requestedStart: number;
  insertionIndex: number;
  adjustments: string[];
  affectedOperations: Array<{ before: ProcessOperation; after: ProcessOperation }>;
  /** Warning only (T10): jobs whose full-route delivery becomes later than the due day. */
  deliveryWarnings?: PlacementDeliveryWarning[];
};

export function processPlacementSignature(preview: ProcessGanttPlacementPreview): string {
  // Include the entire calculated route, not timestamps from newly created overrides.
  return JSON.stringify([preview.requestedStart, preview.operation.id, preview.plan.operations, preview.plan.jobs.map((job) => [job.batchId, job.deliveryReadyAt]), preview.affectedOperations]);
}

export function processPlacementBaseline(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">, operationId: string): DownstreamProcessPlan {
  const baseline = buildDownstreamProcessPlan(seed, result);
  if (baseline.operations.some(item => item.id === operationId)) return baseline;
  const candidate = buildDownstreamProcessPlan(seed, result, true).operations.find(item => item.id === operationId && item.manualCandidate);
  if (candidate) {
    baseline.operations.push(candidate);
    baseline.jobs = baseline.jobs.map(job => job.batchId === candidate.batchId ? {...job, operations:[...job.operations,candidate]} : job);
  }
  return baseline;
}

export function previewProcessOperationReschedule(
  seed: PlanningSeed,
  result: Pick<ScenarioResult, "batches">,
  operationId: string,
  resourceId: string,
  requestedStart: number,
): ProcessGanttPlacementPreview {
  const baseline = processPlacementBaseline(seed, result, operationId);
  const operation = baseline.operations.find((item) => item.id === operationId);
  if (!operation || operation.actual || operation.current || operation.process === "turning") throw new Error("Yalnızca kuyruktaki downstream operasyonları taşınabilir; çalışan ve tamamlanan işler sabittir.");
  if (!Number.isFinite(requestedStart) || requestedStart <= 0) throw new Error("Geçerli bir yeni başlangıç zamanı seçin.");
  if (requestedStart < operation.readyAt - 1e-8) {
    const predecessor = baseline.operations.find((item) => item.id === operation.predecessorOperationId);
    throw new Error(`Önceki proses tamamlanmadı: ${operation.product} için ${predecessor ? processLabelForError(predecessor.process) : "önceki proses"} ve zorunlu bekleme nedeniyle en erken başlangıç ${processStartDate(operation.readyAt)}. İstenen: ${processStartDate(requestedStart)}.`);
  }
  const resource = assertProcessPlacementResource(seed, operation, resourceId);
  if (resource.planEnd && requestedStart >= Math.floor(resource.planEnd) + 1) throw new Error(`${resourceId} plan penceresi ${processStartDate(resource.planEnd)} tarihinde bitiyor.`);

  // Insert before the queued job under the pointer (or the next job in a gap).
  // Pin existing resource assignments and queue anchors so readiness-based sorting
  // cannot silently append the dragged job behind the entire automatic queue.
  const process = operation.process;
  const queues = new Map<string, ProcessOperation[]>();
  for (const item of baseline.operations.filter((item) => item.process === process && !item.actual && !item.current && item.id !== operation.id)) {
    queues.set(item.resourceId, [...(queues.get(item.resourceId) ?? []), item]);
  }
  for (const queue of queues.values()) queue.sort((a, b) => a.start - b.start || a.id.localeCompare(b.id));
  const destination = queues.get(resourceId) ?? [];
  const nextIndex = destination.findIndex((item) => item.end > requestedStart + 1e-8);
  const insertionIndex = nextIndex < 0 ? destination.length : nextIndex;
  destination.splice(insertionIndex, 0, operation);
  queues.set(resourceId, destination);
  const nextSeed = JSON.parse(JSON.stringify(seed)) as PlanningSeed;
  const queuedIds = new Set([...queues.values()].flat().map((item) => item.batchId));
  const updatedAt = new Date().toISOString();
  nextSeed.processOperationOverrides = [
    ...(seed.processOperationOverrides ?? []).filter((item) => item.process !== process || !queuedIds.has(item.batchId)),
    ...[...queues].flatMap(([queueResourceId, queue]) => {
      let cursor = 0;
      return queue.map((item, queueOrder) => {
        const anchor = item.id === operation.id ? requestedStart : Math.max(item.start, cursor);
        cursor = anchor + 1 / 86_400;
        const previous = seed.processOperationOverrides?.find(value => value.batchId === item.batchId && value.process === process);
        const currentMachine = item.source === "current-turning" ? seed.machines.find(machine => `current:${machine.id}` === item.batchId) : undefined;
        return { ...previous, ...(item.id === operation.id ? { routeMode: "manual" as const, resumeAfterCurrent: false, preservedStart: undefined, preservedEnd: undefined } : {}), batchId: item.batchId, process, resourceId: queueResourceId, requestedStart: anchor, updatedAt, queueOrder, sourceProduct: item.product, sourceCurrentJobKey: currentMachine ? currentJobRouteIdentity(currentMachine) : undefined };
      });
    }),
  ];
  const plan = buildDownstreamProcessPlan(nextSeed, result);
  // A flexible charge may use a reservation's idle gap, but a queue review
  // cannot turn that into permission to delay work with only one usable center.
  if (process === "drilling") {
    const resourceCount = (product: string) => {
      const masterProduct = processMasterDataForProduct(seed.processMasterData!, product);
      const parameter = masterProduct?.processes.find(item => item.process === "drilling");
      return !masterProduct || !parameter ? 0 : activeProcessResourceIds(parameter).filter(id => {
        const candidate = processResource(seed.processMasterData!, id);
        return candidate?.active && candidate.defaultShifts > 0 && candidate.process === "drilling"
          && resourceSupportsProcessProduct(candidate, masterProduct) && Number.isFinite(parameter.unitsPerShift[id]) && parameter.unitsPerShift[id] > 0;
      }).length;
    };
    if (resourceCount(operation.product) > 1) for (const reserved of baseline.operations.filter(item => item.process === process && item.resourceId === resourceId && !item.actual && !item.current && item.id !== operation.id && resourceCount(item.product) === 1)) {
      const after = plan.operations.find(item => item.id === reserved.id);
      if (!after || after.start > reserved.start + 1e-8 || after.end > reserved.end + 1e-8)
        throw new Error(`${resourceId} kaynak rezervi ve setup dönüş süresi istenen sıraya izin vermiyor. Rezervasyonu geciktirmeyen bir boşluk veya uygun başka bir istasyon seçin.`);
    }
  }
  const moved = plan.operations.find((item) => item.id === operation.id);
  const placementConflict = plan.warnings.find(warning => warning.code === "placement-conflict");
  if (placementConflict) throw new Error(placementConflict.message);
  // Reject the whole move if any previously planned route step would disappear.
  for (const before of baseline.operations) {
    const after = plan.operations.find((item) => item.id === before.id);
    if (!after) {
      const limit = seed.processMasterData?.resources.find((item) => item.id === (before.id === operation.id ? resourceId : before.resourceId))?.planEnd;
      throw new Error(`${before.product} · ${processLabelForError(before.process)} adımı kapasiteye sığmıyor${limit ? `; plan penceresi ${processStartDate(limit)} tarihinde bitiyor` : "; iş merkezi kapasitesini ve rota parametrelerini kontrol edin"}. Taşıma uygulanmadı.`);
    }
    if ((before.current || before.actual) && (before.start !== after.start || before.end !== after.end || before.resourceId !== after.resourceId)) throw new Error("Taşıma çalışan veya tamamlanan bir işi değiştireceği için uygulanamadı.");
    if (before.process === process && before.id !== operation.id && before.resourceId !== after.resourceId) throw new Error(`${before.product} için mevcut iş merkezi korunamadı. Taşıma uygulanmadı.`);
  }
  if (!moved || moved.resourceId !== resourceId || moved.start < requestedStart - 1e-8) throw new Error("Seçilen yerleşim rota ve kapasite kurallarıyla oluşturulamadı.");
  const actualOrder = plan.operations.filter((item) => item.process === process && item.resourceId === resourceId && !item.actual && !item.current).sort((a, b) => a.start - b.start || a.id.localeCompare(b.id));
  if (actualOrder.some((item, index) => item.id !== destination[index]?.id)) throw new Error(`${resourceId} kaynak rezervi ve setup dönüş süresi istenen sıraya izin vermiyor. Hazır olma ve kapasite kurallarına uyan bir boşluk veya uygun başka bir istasyon seçin.`);
  const adjustments: string[] = [];
  if (moved.start > requestedStart + 1e-8) {
    if ((resource.availableStart ?? 0) > requestedStart) adjustments.push(`${resourceId} en erken ${processStartDate(resource.availableStart!)} tarihinde kullanılabilir.`);
    const blocking = plan.operations.filter((item) => item.resourceId === resourceId && item.id !== moved.id && item.end > requestedStart && item.end <= moved.start + 1e-8).sort((a, b) => b.end - a.end)[0];
    if (blocking) adjustments.push(`${blocking.workOrder || blocking.product} işi ${processStartDate(blocking.end)} tarihine kadar istasyonu kullanıyor.`);
    const calendarSeed = processCalendarSeed(seed, resourceId);
    const capacity = machineDayCapacity(calendarSeed, { id: resourceId, shiftFactor: resource.defaultShifts }, requestedStart);
    if (capacity.kind !== "normal" || !blocking) adjustments.push(`${capacity.label} · vardiya/tatil/bakım kapasitesine göre uygun başlangıç ${processStartDate(moved.start)}.`);
  }
  const affectedOperations = baseline.operations.flatMap((before) => {
    const after = plan.operations.find((item) => item.id === before.id)!;
    return before.id !== moved.id && (Math.abs(before.start - after.start) > 1e-8 || Math.abs(before.end - after.end) > 1e-8 || before.resourceId !== after.resourceId) ? [{ before, after }] : [];
  });
  return { seed: nextSeed, plan, operation: moved, requestedStart, insertionIndex, adjustments, affectedOperations, deliveryWarnings: placementDeliveryWarnings(seed, result, baseline, plan) };
}

export type PlacementDeliveryWarning = { batchId: string; product: string; workOrder: string; dueDate: string; beforeReadyAt: number; afterReadyAt: number; lateDays: number };

/**
 * T10: a feasible manual move from Delme onward may make delivery late. This
 * is a warning only. Physical readiness, capacity, current work and locks are
 * still checked by the preview itself. Lateness uses the full-route delivery
 * readiness, never the moved operation's end alone.
 */
export function placementDeliveryWarnings(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">, baseline: DownstreamProcessPlan, plan: DownstreamProcessPlan): PlacementDeliveryWarning[] {
  if (seed.productionArea === "cubuk-filtre") return []; // T10 scope: Piston Delme and later only.
  const before = new Map(baseline.jobs.map(job => [job.batchId, job]));
  return plan.jobs.flatMap(job => {
    const previous = before.get(job.batchId);
    const batch = result.batches.find(item => item.id === job.batchId);
    const dueDate = batch?.demandDueDate || seed.orders.filter(order => order.product.toUpperCase() === job.product.toUpperCase() && order.quantity > 0 && order.dueDate).map(order => order.dueDate).sort()[0];
    const due = dueDate ? inputDateSerial(dueDate) + 1 : 0; // end of the due day
    if (!previous || !due || !job.deliveryReadyAt || job.deliveryReadyAt <= due + 1e-8 || job.deliveryReadyAt <= (previous.deliveryReadyAt || 0) + 1e-8) return [];
    return [{ batchId: job.batchId, product: job.product, workOrder: job.workOrder, dueDate, beforeReadyAt: previous.deliveryReadyAt, afterReadyAt: job.deliveryReadyAt, lateDays: Math.ceil(job.deliveryReadyAt - due) }];
  });
}

export type ProcessQueuePlacementRequest = {
  operationId: string;
  resourceId: string;
  /** Zero-based index after removing the moved operation, or append. */
  position: number | "end";
};

/** Queue controls resolve a slot to a time, then use the Gantt's placement rules. */
export function previewProcessQueuePlacement(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">, request: ProcessQueuePlacementRequest): ProcessGanttPlacementPreview {
  const baseline = processPlacementBaseline(seed, result, request.operationId);
  const operation = baseline.operations.find((item) => item.id === request.operationId);
  if (!operation || operation.actual || operation.current || operation.process === "turning") throw new Error("Yalnızca kuyruktaki downstream operasyonları taşınabilir; çalışan ve tamamlanan işler sabittir.");
  const resource = assertProcessPlacementResource(seed, operation, request.resourceId);
  const ordered = baseline.operations.filter((item) => item.process === operation.process && item.resourceId === request.resourceId && !item.actual && !item.current && !item.manualCandidate).sort((a, b) => a.start - b.start || a.id.localeCompare(b.id));
  const currentIndex = ordered.findIndex((item) => item.id === operation.id);
  const queue = ordered.filter((item) => item.id !== operation.id);
  const position = request.position === "end" ? queue.length : request.position;
  if (!Number.isInteger(position) || position < 0 || position > queue.length) throw new Error(`Geçerli kuyruk sırası 1–${queue.length + 1} arasında olmalıdır. Kuyruk değiştiyse yerleşimi yeniden seçin.`);
  if (currentIndex === position) return { seed, plan: baseline, operation, requestedStart: operation.start, insertionIndex: position, adjustments: [], affectedOperations: [] };
  // A populated slot keeps its existing time. Never advance it to readyAt to
  // disguise a predecessor violation by pushing the rest of the queue later.
  // An empty queue has no displaced job/slot, so use its first feasible anchor.
  const requestedStart = queue[position]?.start ?? queue.at(-1)?.end ?? Math.max(operation.readyAt, resource.availableStart ?? 0,
    ...baseline.operations.filter((item) => item.resourceId === request.resourceId && (item.current || item.actual)).map((item) => item.end));
  return previewProcessOperationReschedule(seed, result, operation.id, request.resourceId, requestedStart);
}

export function previewProcessOperationQueueTransfer(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">, operationId: string, resourceId: string): ProcessGanttPlacementPreview {
  return previewProcessQueuePlacement(seed, result, { operationId, resourceId, position: "end" });
}

export function previewProcessResourceQueueReorder(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">, operationId: string, position: number): ProcessGanttPlacementPreview {
  const operation = buildDownstreamProcessPlan(seed, result).operations.find((item) => item.id === operationId);
  if (!operation) throw new Error("İş seçili iş merkezi kuyruğunda bulunamadı.");
  return previewProcessQueuePlacement(seed, result, { operationId, resourceId: operation.resourceId, position });
}

export type ProcessCurrentJobInput = {
  originalQuantity: number;
  remainingQuantity: number;
  /** Factory serial when the remaining count was observed. Absent means now. */
  remainingAsOf?: number;
};

export function processJobStartAvailability(seed: PlanningSeed, plan: DownstreamProcessPlan, resourceId: string, now: number): { operation?: ProcessOperation; reason: string; guidance?: string } {
  const resource = seed.processMasterData?.resources.find((item) => item.id === resourceId);
  if (!resource?.active) return { reason: "İş merkezi aktif değil.", guidance: "İş merkezi ayarlarında aktiflik durumunu kontrol edin." };
  if (seed.processCurrentJobs?.some((job) => job.resourceId === resourceId)) return { reason: "İş merkezinde çalışan bir iş var.", guidance: "Mevcut işi tamamlayın veya Mevcut işi değiştir ile başka bir hazır şarj seçin." };
  if ((resource.availableStart ?? 0) > now) return { reason: `İş merkezi ${processStartDate(resource.availableStart!)} tarihinde kullanılabilir.`, guidance: "Müsait başlangıç alanını kontrol edin; bu zaman gelmeden üretim başlatılamaz." };
  if (resource.planEnd && Math.floor(resource.planEnd) < Math.floor(now)) return { reason: "İş merkezinin plan penceresi sona erdi.", guidance: "Plan bitişi alanını kontrol edin." };
  const queue = plan.operations.filter((operation) => operation.resourceId === resourceId && !operation.actual && !operation.current)
    .sort((a, b) => a.start - b.start || a.id.localeCompare(b.id));
  const released = queue.filter((operation) => {
    const lot = seed.wipLots?.find((item) => item.id === operation.wipLotId);
    return operation.source === "wip" && lot && lot.availableQuantity > 0 && lot.nextProcess === operation.process
      && lot.stage !== "on-hold" && lot.stage !== "unclassified";
  });
  const operation = released.find((item) => item.readyAt <= now + 1e-8 && actualProcessStartEligibility(seed,item,now,true).ok);
  if (operation) return { operation, reason: "" };
  if (released.length) {
    const earliest = released.reduce((left, right) => left.readyAt <= right.readyAt ? left : right);
    return { reason: `Yarı mamül ${processStartDate(earliest.readyAt)} tarihinde hazır olacak.`, guidance: `${earliest.workOrder || earliest.product} · Şarj Yolculuğu’nda önceki prosesin gerçek tamamlanma tarihini ve saatini, varsa bekleme aşamasını kontrol edin. Saat Türkiye saatidir.` };
  }
  if (queue.length) return { reason: "Önceki proses henüz tamamlanmadı veya yarı mamül serbest bırakılmadı.", guidance: "Şarj Yolculuğu’nda önceki prosesi ve yarı mamülün konumunu kontrol edin. Kuyrukta planlı iş olması, malzemenin üretime hazır olduğu anlamına gelmez." };
  const held = seed.wipLots?.find((lot) => {
    const product = processMasterDataForProduct(seed.processMasterData, lot.product);
    const parameter = product?.processes.find((item) => item.process === resource.process);
    return lot.availableQuantity > 0 && (lot.stage === "on-hold" || lot.stage === "unclassified")
      && (lot.nextProcess === resource.process || lot.stage === "unclassified")
      && product && resourceSupportsProcessProduct(resource, product) && parameter && activeProcessResourceIds(parameter).includes(resourceId);
  });
  if (held) return { reason: held.stage === "on-hold" ? `${held.workOrder || held.product} şarjı blokeli.` : `${held.workOrder || held.product} şarjının konumu doğrulanmalı.`, guidance: "Bu iş merkezinde başlatılabilecek planlı iş yok. Yarı mamül ekranında şarjın blokajını veya gerçek konumunu kontrol edin." };
  return { reason: "Bu iş merkezinde üretime alınabilecek planlı iş yok. Ürün rotası ve kapasite ayarlarını kontrol edin.", guidance: "Kuyruğu, ürünün bu iş merkezine uygunluğunu ve vardiya hızını kontrol edin. Plan uyarıları ile Günlük vardiya / Planlı bakım kayıtları kapasite eksikliğini açıklayabilir." };
}

function processStartDate(serial: number): string {
  return new Intl.DateTimeFormat("tr-TR", { day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit", timeZone: "UTC" }).format(excelSerialToDate(serial));
}

/** Only reset queued placements for one process; running work and turning stay intact. */
export function resetDownstreamProcessPlan(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">, process: DownstreamProcess): { seed: PlanningSeed; plan: DownstreamProcessPlan } {
  if (!["drilling", "deburring", "gkm"].includes(process)) throw new Error("Yalnızca Delme, Çapak Alma veya GKM ayrı planlanabilir.");
  const nextSeed = JSON.parse(JSON.stringify(seed)) as PlanningSeed;
  nextSeed.processOperationOverrides = (nextSeed.processOperationOverrides ?? []).filter((override) => override.process !== process
    || nextSeed.processCurrentJobs?.some((job) => job.batchId === override.batchId && job.process === process)
    || nextSeed.productionInterruptions?.some(item => isProductionInterruption(item) && !item.completedAt && item.chargeId === override.batchId && item.process === process)
    || activeLotInterruptions(nextSeed, nextSeed.wipLots?.find(lot => lot.id === override.batchId)).length > 0);
  return { seed: nextSeed, plan: buildDownstreamProcessPlan(nextSeed, result) };
}

export function startProcessCurrentJob(
  seed: PlanningSeed,
  result: Pick<ScenarioResult, "batches">,
  operationId: string,
  requestedStart?: number,
  confirmedInterruption = false,
): ProcessCurrentJob {
  const plan = buildDownstreamProcessPlan(seed, result);
  const operation = plan.operations.find((item) => item.id === operationId);
  if (!operation || operation.actual || operation.current || operation.process === "turning") throw new Error("Mevcut işe alınacak downstream operasyonu bulunamadı.");
  if (operation.source !== "wip" || !operation.wipLotId) throw new Error("Bu iş henüz sahadaki yarı mamül değil; önce önceki operasyon tamamlanmalı.");
  const lot = seed.wipLots?.find((item) => item.id === operation.wipLotId);
  if (!lot || lot.nextProcess !== operation.process || lot.availableQuantity <= 0 || lot.stage === "on-hold" || lot.stage === "unclassified") throw new Error("Önceki proses henüz tamamlanmadı veya yarı mamül serbest bırakılmadı.");
  if (activeLotInterruptions(seed, lot).length && !confirmedInterruption) throw new Error("Üretim sonlanmadı, yine de üretime alayım mı? Devam etmek için onaylayın.");
  if ((seed.processCurrentJobs ?? []).some((item) => item.resourceId === operation.resourceId)) throw new Error(`${operation.resourceId} üzerinde zaten çalışan bir iş var.`);
  const resource = assertProcessPlacementResource(seed, operation, operation.resourceId);
  const start = Math.max(operation.readyAt, requestedStart ?? operation.start, resource.availableStart ?? operation.readyAt);
  const eligibility = actualProcessStartEligibility(seed,operation,start,confirmedInterruption);
  if (!eligibility.ok) throw new Error(eligibility.reason);
  if (requestedStart != null && requestedStart < operation.readyAt - 1e-8) throw new Error(`${operation.product}, önceki operasyon tamamlanmadan üretime alınamaz.`);
  const timeline = addMachineCapacityHours(
    processCalendarSeed(seed, resource.id),
    { id: resource.id, shiftFactor: resource.defaultShifts, finishOffset: 0 },
    start,
    operation.setupHours + operation.runHours,
  );
  if (resource.planEnd && timeline.end > Math.floor(resource.planEnd) + 1 + 1e-8) throw new Error(`${resource.id} plan penceresinde bu işi tamamlayacak süre yok.`);
  const updatedAt = new Date().toISOString();
  const current: ProcessCurrentJob = {
    resourceId: resource.id,
    resourceName: resource.name,
    process: operation.process as DownstreamProcess,
    batchId: operation.batchId,
    operationId: operation.id,
    wipLotId: operation.wipLotId,
    workOrder: operation.workOrder,
    product: operation.product,
    family: operation.family,
    originalQuantity: operation.quantity,
    remainingQuantity: operation.quantity,
    readyAt: operation.readyAt,
    start: timeline.start,
    end: timeline.end,
    setupKey: operation.setupKey,
    unitsPerShift: operation.unitsPerShift,
    setupHours: operation.setupHours,
    updatedAt,
  };
  for (const pause of seed.productionInterruptions ?? []) if (!pause.completedAt && pause.chargeId === current.batchId && pause.process === current.process) pause.resumedAt = current.start;
  seed.processCurrentJobs = [...(seed.processCurrentJobs ?? []), current];
  seed.processOperationOverrides = [
    ...(seed.processOperationOverrides ?? []).filter((item) => !(item.batchId === operation.batchId && item.process === operation.process)),
    { batchId: operation.batchId, process: operation.process as DownstreamProcess, resourceId: resource.id, requestedStart: timeline.start, updatedAt },
  ];
  return current;
}

export function updateProcessCurrentJob(seed: PlanningSeed, resourceId: string, input: ProcessCurrentJobInput): ProcessCurrentJob {
  const current = (seed.processCurrentJobs ?? []).find((item) => item.resourceId === resourceId);
  if (!current) throw new Error(`${resourceId} üzerinde düzenlenecek mevcut iş bulunamadı.`);
  const lot = (seed.wipLots ?? []).find((item) => item.id === current.wipLotId);
  if (!Number.isInteger(input.originalQuantity) || input.originalQuantity <= 0) throw new Error("Orijinal adet sıfırdan büyük tam sayı olmalıdır.");
  if (lot && input.originalQuantity > lot.availableQuantity) throw new Error("Orijinal adet yarı mamül bakiyesini aşamaz.");
  if (!Number.isInteger(input.remainingQuantity) || input.remainingQuantity <= 0 || input.remainingQuantity > input.originalQuantity) throw new Error("Kalan adet, orijinal adedi aşmayan pozitif tam sayı olmalıdır.");
  const resource = seed.processMasterData?.resources.find((item) => item.id === resourceId && item.process === current.process);
  if (!resource || !resource.active || resource.defaultShifts <= 0) throw new Error(`${resourceId} için aktif vardiya kapasitesi bulunamadı.`);
  if (input.remainingAsOf === undefined && seed.productionArea === "cubuk-filtre") {
    // Çubuk Filtre keeps its reviewed calculation until its editor sends an observation time.
    const runHours = input.remainingQuantity / current.unitsPerShift * getSetupSettings(seed).shiftHours;
    const timeline = addMachineCapacityHours(processCalendarSeed(seed, resource.id), { id: resource.id, shiftFactor: resource.defaultShifts, finishOffset: 0 }, current.start, current.setupHours + runHours);
    Object.assign(current, { originalQuantity: input.originalQuantity, remainingQuantity: input.remainingQuantity, start: timeline.start, end: timeline.end, updatedAt: new Date().toISOString() });
    seed.processOperationOverrides = [
      ...(seed.processOperationOverrides ?? []).filter((item) => !(item.batchId === current.batchId && item.process === current.process)),
      { batchId: current.batchId, process: current.process, resourceId, requestedStart: current.start, updatedAt: current.updatedAt },
    ];
    return current;
  }
  const remainingAsOf = input.remainingAsOf ?? factoryNowSerial();
  if (!Number.isFinite(remainingAsOf) || remainingAsOf <= 0) throw new Error("Kalan miktarın geçerli olduğu tarih ve saat geçersiz.");
  if (remainingAsOf < current.start - 1e-8) throw new Error("Kalan miktarın tarihi mevcut işin fiili başlangıcından önce olamaz.");
  if (input.remainingAsOf !== undefined && remainingAsOf > factoryNowSerial() + 1 / 1440) throw new Error("Kalan miktarın tarihi gelecekte olamaz.");
  const calendar = processCalendarSeed(seed, resource.id);
  const capacity = { id: resource.id, shiftFactor: resource.defaultShifts, finishOffset: 0 };
  const runHours = input.remainingQuantity / current.unitsPerShift * getSetupSettings(seed).shiftHours;
  // The actual start stays recorded. The remaining count is valid at its
  // observation time, so the forecast never assumes earlier capacity remains.
  const setupEnd = addMachineCapacityHours(calendar, capacity, current.start, current.setupHours).end;
  const end = addMachineCapacityHours(calendar, capacity, Math.max(setupEnd, remainingAsOf), runHours).end;
  Object.assign(current, {
    originalQuantity: input.originalQuantity,
    remainingQuantity: input.remainingQuantity,
    end,
    remainingAsOf,
    updatedAt: new Date().toISOString(),
  });
  seed.processOperationOverrides = [
    ...(seed.processOperationOverrides ?? []).filter((item) => !(item.batchId === current.batchId && item.process === current.process)),
    { batchId: current.batchId, process: current.process, resourceId, requestedStart: current.start, updatedAt: current.updatedAt },
  ];
  return current;
}

export function replaceProcessCurrentJob(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">, resourceId: string, operationId: string, requestedStart?: number, input?: ProductionInterruptionInput, confirmedInterruption = false): { current: ProcessCurrentJob; queued: ProcessOperation } {
  assertProductionSwitchSnapshot(seed, result.batches, input!);
  const next = structuredClone(seed);
  const outcome = replaceProcessCurrentJobInPlace(next, result, resourceId, operationId, requestedStart, input!, confirmedInterruption);
  Object.assign(seed, next);
  return outcome;
}

function replaceProcessCurrentJobInPlace(
  seed: PlanningSeed,
  result: Pick<ScenarioResult, "batches">,
  resourceId: string,
  operationId: string,
  requestedStart: number | undefined,
  input: ProductionInterruptionInput,
  confirmedInterruption: boolean,
): { current: ProcessCurrentJob; queued: ProcessOperation } {
  const previous = (seed.processCurrentJobs ?? []).find((item) => item.resourceId === resourceId);
  if (!previous) throw new Error(`${resourceId} üzerinde değiştirilecek mevcut iş bulunamadı.`);

  const plan = processPlacementBaseline(seed, result, operationId);
  const target = plan.operations.find((item) => item.id === operationId);
  if (!target || target.actual || target.current || target.process === "turning") throw new Error("Mevcut işe alınacak downstream operasyonu bulunamadı.");
  if (target.process !== previous.process) throw new Error(`Yalnızca ${processLabelForError(previous.process)} işleri mevcut üretime alınabilir.`);
  if (target.source !== "wip" || !target.wipLotId) throw new Error("Bu şarj henüz sahadaki yarı mamül değil; önce önceki operasyon tamamlanmalı.");
  assertProcessPlacementResource(seed, target, resourceId);
  const start = requestedStart ?? target.start;
  if (start < target.readyAt - 1e-8) throw new Error("Yeni şarjın önceki prosesi veya beklemesi henüz tamamlanmadı.");
  const produced = validateProductionInterruption(input, previous.originalQuantity, previous.start, start);
  const previousLot = seed.wipLots?.find(lot => lot.id === previous.wipLotId);
  if (!previousLot || previous.originalQuantity !== previousLot.availableQuantity) throw new Error("Mevcut işin adedi yarı mamül bakiyesiyle uyuşmuyor; kaydı kontrol edin.");
  if (produced > 0) {
    const pauseId = `pause-${crypto.randomUUID()}`;
    seed.productionInterruptions = [...(seed.productionInterruptions ?? []), { id:pauseId, chargeId:previous.batchId, process:previous.process, resourceId, product:previous.product, workOrder:previous.workOrder, producedQuantity:produced, remainingQuantity:previous.originalQuantity-produced, reason:input.produced ? input.reason!.trim() : '', occurredAt:start }];
    const split = completeWipOperation(seed, { lotId:previous.wipLotId, process:previous.process, resourceId, resourceName:previous.resourceName, quantity:produced, startedAt:previous.start, completedAt:start, plannedStart:previous.start, plannedEnd:previous.end, confirmedInterruption:true });
    split.completed.interruptionIds = [...(split.completed.interruptionIds ?? []),pauseId];
  }

  const updatedAt = new Date().toISOString();
  seed.processCurrentJobs = (seed.processCurrentJobs ?? []).filter((item) => item.resourceId !== resourceId);
  seed.processOperationOverrides = [
    ...(seed.processOperationOverrides ?? []).filter((item) => !(
      (item.batchId === previous.batchId && item.process === previous.process)
      || (item.batchId === target.batchId && item.process === target.process)
    )),
    { batchId: previous.batchId, process: previous.process, resourceId, requestedStart: start + 1 / 86_400, resumeAfterCurrent: true, updatedAt },
    { batchId: target.batchId, process: target.process as DownstreamProcess, resourceId, requestedStart: start, updatedAt },
  ];

  const current = startProcessCurrentJob(seed, result, operationId, start, confirmedInterruption);
  // Re-anchor only this resource's queue. The generic whole-process reorder can
  // reject a valid D-01/D-02 swap because an unrelated resource has a tightly
  // constrained queue. The interrupted job still has to be first locally.
  const swappedPlan = buildDownstreamProcessPlan(seed, result);
  const resourceQueue = swappedPlan.operations
    .filter((item) => !item.actual && !item.current && item.process === previous.process && item.resourceId === resourceId)
    .sort((left, right) => left.start - right.start || left.id.localeCompare(right.id));
  const interrupted = resourceQueue.find((item) => item.id === previous.operationId);
  if (!interrupted) throw new Error("Önceki mevcut iş tezgah kuyruğuna geri alınamadı.");
  const desiredQueue = [interrupted, ...resourceQueue.filter((item) => item.id !== interrupted.id)];
  const queueBatchIds = new Set(desiredQueue.map((item) => item.batchId));
  let cursor = current.end;
  const localQueueOverrides = desiredQueue.map((item) => {
    cursor = Math.max(cursor, item.readyAt);
    const requestedStart = cursor;
    cursor += 1 / 86_400;
    return { batchId: item.batchId, process: previous.process, resourceId, requestedStart, resumeAfterCurrent: item.id === previous.operationId, updatedAt };
  });
  seed.processOperationOverrides = [
    ...(seed.processOperationOverrides ?? []).filter((item) => !(item.process === previous.process && queueBatchIds.has(item.batchId))),
    ...localQueueOverrides,
  ];
  const finalPlan = buildDownstreamProcessPlan(seed, result);
  const finalQueue = finalPlan.operations
    .filter((item) => !item.actual && !item.current && item.process === previous.process && item.resourceId === resourceId)
    .sort((left, right) => left.start - right.start || left.id.localeCompare(right.id));
  const queued = finalQueue[0];
  if (!queued || queued.id !== previous.operationId) throw new Error("Önceki mevcut iş tezgah kuyruğunun ilk sırasına geri alınamadı.");
  return { current, queued };
}

/** Completion is atomic even when the optional successor cannot be started. */
export function completeProcessCurrentJob(seed: PlanningSeed, result: Pick<ScenarioResult,"batches">, resourceId: string, completedAt: number, completedQuantity?: number, actualResourceId = resourceId, remainderAction?: "keep" | "scrap", confirmedBuffer = false): {completedProduct:string;completedWorkOrder:string;completedResourceId:string;promoted?:ProcessCurrentJob} {
  const draft=structuredClone(seed);
  const outcome=completeProcessCurrentJobInPlace(draft,result,resourceId,completedAt,completedQuantity,actualResourceId,remainderAction,confirmedBuffer);
  Object.assign(seed,draft);
  return outcome;
}

function completeProcessCurrentJobInPlace(
  seed: PlanningSeed,
  result: Pick<ScenarioResult, "batches">,
  resourceId: string,
  completedAt: number,
  completedQuantity?: number,
  actualResourceId = resourceId,
  remainderAction?: "keep" | "scrap",
  confirmedBuffer = false,
): { completedProduct: string; completedWorkOrder: string; completedResourceId: string; promoted?: ProcessCurrentJob } {
  const scope = turningIdentityScope(seed, result.batches);
  const protectedIdentity = (product: string, batchId: string, lotId?: string) => scope.products.includes(product.trim().toUpperCase()) || scope.batchIds.includes(batchId) || scope.lotIds.includes(batchId) || Boolean(lotId && scope.lotIds.includes(lotId));
  const current = (seed.processCurrentJobs ?? []).find((item) => item.resourceId === resourceId);
  if (!current) throw new Error(`${resourceId} üzerinde tamamlanacak mevcut iş bulunamadı.`);
  if (protectedIdentity(current.product, current.batchId, current.wipLotId)) throw new Error("Bu mevcut iş inceleme bekleyen şarja bağlı. Önce İncele ve düzelt ile kayıtları doğrulayın.");
  const lot = (seed.wipLots ?? []).find((item) => item.id === current.wipLotId);
  if (!lot) throw new Error("Mevcut işe bağlı yarı mamül kaydı bulunamadı.");
  const actualResource = seed.processMasterData?.resources.find((item) => item.id === actualResourceId && item.process === current.process);
  if (!actualResource) throw new Error(`${actualResourceId}, ${processLabelForError(current.process)} için geçerli bir iş merkezi değil.`);
  const realReadyAt = wipCompletionEarliestAt(seed, lot);
  if (completedAt < wipOperationReadyAt(lot) && !confirmedBuffer) throw new Error("Planlanan beklemeden erken tamamlama için ilgili kontrol / yıkamanın tamamlandığını onaylayın.");
  if (!Number.isFinite(completedAt) || completedAt < realReadyAt) throw new Error("Tamamlanma tarihi şarjın gerçek hazır olma tarihinden önce olamaz.");
  const quantity = completedQuantity ?? current.originalQuantity;
  if (!Number.isInteger(quantity) || quantity <= 0 || quantity > lot.availableQuantity) throw new Error("Fiili tamamlanan adet, yarı mamül bakiyesini aşmayan pozitif tam sayı olmalıdır.");
  completeWipOperation(seed, {
    lotId: current.wipLotId,
    process: current.process,
    resourceId: actualResource.id,
    resourceName: actualResource.name,
    quantity,
    remainderAction,
    startedAt: Math.max(realReadyAt, Math.min(current.start, completedAt)),
    completedAt,
    plannedStart: current.start,
    plannedEnd: current.end,
    confirmedInterruption: true,
    confirmedBuffer,
  });
  seed.processCurrentJobs = (seed.processCurrentJobs ?? []).filter((item) => item.resourceId !== resourceId);
  seed.processOperationOverrides = (seed.processOperationOverrides ?? []).filter((item) => !(item.batchId === current.batchId && item.process === current.process));

  const nextPlan = buildDownstreamProcessPlan(seed, result);
  const candidates = nextPlan.operations
    .filter(item => !item.actual && !item.current && item.process === current.process && item.resourceId === resourceId)
    .sort((left, right) => left.start - right.start || left.id.localeCompare(right.id));
  let promoted: ProcessCurrentJob | undefined;
  const retainedQueue = (nextPlan.queueEntries ?? []).filter(row => row.resourceId === resourceId && row.process === current.process);
  for (const candidate of candidates) {
    const placement = retainedQueue.find(row => row.batchId === candidate.batchId);
    // A missing schedule must not erase an earlier reviewed queue commitment.
    const blockedHead = retainedQueue.some(row => !row.scheduled && (
      !placement
      || Number(row.resumeAfterCurrent) > Number(placement.resumeAfterCurrent)
      || row.resumeAfterCurrent === placement.resumeAfterCurrent && row.queueOrder <= placement.queueOrder
    ));
    if (blockedHead) break;
    // A quarantined successor must not roll back valid completion of an
    // unrelated job. Preserve reviewed head priority; automatic work can skip it.
    if (protectedIdentity(candidate.product, candidate.batchId, candidate.wipLotId)) {
      if (candidate.manualOverride) break;
      continue;
    }
    const eligibility = actualProcessStartEligibility(seed,candidate,completedAt);
    const resource = seed.processMasterData!.resources.find(r=>r.id===resourceId)!;
    const timeline = eligibility.ok ? addMachineCapacityHours(processCalendarSeed(seed,resourceId),{id:resourceId,shiftFactor:resource.defaultShifts,finishOffset:0},Math.max(completedAt,candidate.readyAt),candidate.setupHours+candidate.runHours) : undefined;
    const fits = timeline && (!resource.planEnd || timeline.end < Math.floor(resource.planEnd)+1+1e-8);
    if (eligibility.ok && fits && candidate.readyAt<=completedAt+1e-8) { promoted=startProcessCurrentJob(seed,result,candidate.id,completedAt); break; }
    // A reviewed manual head is a commitment, not permission to jump to another job.
    if (candidate.manualOverride) break;
  }
  return { completedProduct: current.product, completedWorkOrder: current.workOrder, completedResourceId: actualResource.id, promoted };
}

export function clearProcessOperationReschedule(seed: PlanningSeed, batchId: string, process: DownstreamProcess): void {
  seed.processOperationOverrides = (seed.processOperationOverrides ?? []).filter((item) => !(item.batchId === batchId && item.process === process));
}

function processLabelForError(process: ProcessKind): string {
  return process === "turning" ? "torna" : process === "drilling" ? "delme" : process === "deburring" ? "çapak alma" : "GKM";
}

function processGapDiagnostics(seed: PlanningSeed, master: ProcessMasterData, operations: ProcessOperation[]): ProcessGapDiagnostic[] {
  const gaps: ProcessGapDiagnostic[] = [];
  const shiftHours = getSetupSettings(seed).shiftHours;
  for (const resource of master.resources.filter((item) => item.process !== "turning")) {
    const queue = operations
      .filter((operation) => !operation.actual && operation.resourceId === resource.id)
      .sort((left, right) => left.start - right.start || left.id.localeCompare(right.id));
    for (let index = 1; index < queue.length; index += 1) {
      const previous = queue[index - 1];
      const next = queue[index];
      if (next.start <= previous.end + 1e-8) continue;
      let code: ProcessGapDiagnostic["code"] = "no-eligible-wip";
      let message = `Bu aralıkta ${resource.id} için uygun ve hazır yarı mamül yoktu; sıradaki iş ${next.product} oldu.`;
      if (next.readyAt > previous.end + 1e-8) {
        if (next.waitWorkdaysBefore > 0) {
          code = "route-wait";
          message = `${next.product}, rota gereği ${next.waitWorkdaysBefore} iş günü bekledikten sonra ${resource.id} için hazır oldu.`;
        } else {
          code = "upstream-not-ready";
          message = `${next.product} önceki operasyonu tamamlanmadığı için bu aralıkta ${resource.id} üzerinde başlatılamadı.`;
        }
      } else {
        const calendarSeed = processCalendarSeed(seed, resource.id);
        const startDay = Math.floor(previous.end);
        const endDay = Math.floor(next.start);
        const days = Array.from({ length: Math.max(1, endDay - startDay + 1) }, (_, offset) => startDay + offset);
        const closed = days.map((serial) => ({ serial, capacity: machineDayCapacity(calendarSeed, { id: resource.id, shiftFactor: resource.defaultShifts }, serial) })).find(({ capacity }) => capacity.shifts === 0);
        if (closed) {
          code = closed.capacity.kind === "maintenance" ? "maintenance" : closed.capacity.kind === "shift" ? "zero-shift" : "closed-day";
          message = `${closed.capacity.label} nedeniyle ${resource.id} kapasitesi kapalıydı; iş ilk çalışılabilir zamana taşındı.`;
        } else {
          const capacity = machineDayCapacity(calendarSeed, { id: resource.id, shiftFactor: resource.defaultShifts }, startDay);
          const windowEnd = startDay + capacity.shifts * shiftHours / 24;
          if (capacity.shifts > 0 && previous.end >= windowEnd - 1e-8) {
            code = "daily-capacity";
            message = `${resource.id} için günlük ${capacity.shifts} vardiyalık kapasite doldu; sıradaki iş bir sonraki çalışma penceresinde başladı.`;
          }
        }
      }
      gaps.push({ id: `${resource.id}:${previous.id}:${next.id}`, process: resource.process as DownstreamProcess, resourceId: resource.id, start: previous.end, end: next.start, code, message });
    }
  }
  return gaps;
}

/**
 * T12 (user decision 2026-10-17): keep one drilling machine per product type
 * unless that worsens delivery. The shared engine plans with same-type
 * continuation; when continuation changed a choice, the same engine plans once
 * more without it. The one-machine plan is kept unless it delivers fewer
 * pieces on time (or is later in total on the same count). Bounded to two
 * evaluations; no second scheduling engine.
 */
export function buildDownstreamProcessPlan(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">, includeInterruptedCandidates = false): DownstreamProcessPlan {
  const control = { enabled: seed.productionArea !== "cubuk-filtre", used: false };
  const consolidated = buildDownstreamProcessPlanWith(seed, result, includeInterruptedCandidates, control);
  if (!control.used) return consolidated;
  const spread = buildDownstreamProcessPlanWith(seed, result, includeInterruptedCandidates, { enabled: false, used: false });
  const a = onTimeScore(seed, result, consolidated), b = onTimeScore(seed, result, spread);
  return a.latePieces > b.latePieces || (a.latePieces === b.latePieces && a.lateDays > b.lateDays + 1e-8) ? spread : consolidated;
}

/** Late pieces and total late days against each job's delivery date (end of due day). */
function onTimeScore(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">, plan: DownstreamProcessPlan): { latePieces: number; lateDays: number } {
  let latePieces = 0, lateDays = 0;
  for (const job of plan.jobs) {
    const batch = result.batches.find(item => item.id === job.batchId);
    const dueDate = batch?.demandDueDate || seed.orders.filter(order => order.product.toUpperCase() === job.product.toUpperCase() && order.quantity > 0 && order.dueDate).map(order => order.dueDate).sort()[0];
    if (!dueDate) continue;
    const due = inputDateSerial(dueDate) + 1;
    const ready = job.deliveryReadyAt > 0 ? job.deliveryReadyAt : Number.POSITIVE_INFINITY;
    if (ready > due + 1e-8) { latePieces += job.quantity; lateDays += Number.isFinite(ready) ? ready - due : 3650; }
  }
  return { latePieces, lateDays };
}

function buildDownstreamProcessPlanWith(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">, includeInterruptedCandidates: boolean, continuationControl: { enabled: boolean; used: boolean }): DownstreamProcessPlan {
  const master = seed.processMasterData ?? { version: 0, source: { kind: "one-time-foundation" as const, files: [], calculatedOnce: "" }, machineCodeStandard: [], products: [], resources: [] };
  const warnings = validateProcessMasterData(master);
  const sources: JobSource[] = [];
  for (const lot of (seed.wipLots ?? []).filter((item) => item.availableQuantity > 0 && item.stage !== "delivered" && item.stage !== "scrapped")) {
    const masterProduct = processMasterDataForProduct(master, lot.product);
    if (!masterProduct) {
      warnings.push({ code: "missing-product", product: lot.product, batchId: lot.id, message: `${lot.product} yarı mamülü için downstream ürün rotası bulunamadı.` });
      continue;
    }
    sources.push({
      id: lot.id,
      source: "wip",
      product: lot.product,
      quantity: lot.availableQuantity,
      workOrder: lot.workOrder,
      releaseAt: lot.readyAt,
      nextProcess: lot.stage === "on-hold" || lot.stage === "unclassified" ? undefined : lot.nextProcess,
      lot,
      masterProduct,
    });
  }
  const representedBatchIds = new Set((seed.wipLots ?? []).map((lot) => lot.sourceBatchId).filter(Boolean));
  for (const machine of (seed.machines ?? []).filter((item) => item.currentJob.product && item.currentJob.quantity > 0 && item.currentJob.end > 0)) {
    const product = machine.currentJob.product.trim().toUpperCase();
    const masterProduct = processMasterDataForProduct(master, product);
    if (!masterProduct) {
      warnings.push({ code: "missing-product", product, batchId: `current:${machine.id}`, message: `${product} mevcut torna işi için downstream ürün rotası bulunamadı.` });
      continue;
    }
    sources.push({
      id: `current:${machine.id}`,
      source: "current-turning",
      product,
      quantity: machine.currentJob.quantity,
      workOrder: machine.currentJob.workOrder ?? "",
      releaseAt: machine.currentJob.end,
      nextProcess: hasActiveProductionInterruption(seed, machine.currentJob.batchId, machine.currentJob.interruptionId) ? undefined : productProcessRoute(masterProduct).find(process => process !== "turning") as DownstreamProcess | undefined,
      machine,
      masterProduct,
    });
  }
  for (const batch of result.batches.filter((item) => item.status === "planned" && item.quantity > 0 && item.end > 0)) {
    if (representedBatchIds.has(batch.id)) continue;
    const masterProduct = processMasterDataForProduct(master, batch.product);
    if (!masterProduct) {
      warnings.push({ code: "missing-product", product: batch.product, batchId: batch.id, message: `${batch.product} için downstream ürün rotası bulunamadı.` });
      continue;
    }
    sources.push({ id: batch.id, source: "turning-plan", product: batch.product, quantity: batch.quantity, workOrder: batch.workOrder ?? "", releaseAt: batch.end, nextProcess: hasActiveProductionInterruption(seed, batch.id, batch.interruptionId) ? undefined : productProcessRoute(masterProduct).find(process => process !== "turning") as DownstreamProcess | undefined, batch, masterProduct });
  }
  const sourceRank = (source: JobSource["source"]) => source === "wip" ? 0 : source === "current-turning" ? 1 : 2;
  sources.sort((left, right) => sourceRank(left.source) - sourceRank(right.source) || left.releaseAt - right.releaseAt || left.id.localeCompare(right.id));
  const operationsByKey = new Map<string, ProcessOperation>();
  const baseOperations = sources.flatMap((source) => source.source === "wip" ? actualWipOperations(source.lot, source.masterProduct) : [turningOperation(seed, source)]);
  for (const operation of baseOperations) operationsByKey.set(`${operation.batchId}:${operation.process}`, operation);
  const downstream = (["drilling", "deburring", "gkm"] as DownstreamProcess[]).flatMap((process) => scheduleStage(seed, master, process, sources, operationsByKey, warnings, includeInterruptedCandidates, continuationControl));
  const operations = [...baseOperations, ...downstream].sort((left, right) => left.start - right.start || left.sequence - right.sequence || Number(right.actual) - Number(left.actual) || left.id.localeCompare(right.id));
  const jobs: RoutedProcessJob[] = sources.map((source) => {
    const route = operations.filter((operation) => operation.batchId === source.id).sort((left, right) => left.sequence - right.sequence || Number(right.actual) - Number(left.actual));
    const completion = route.at(-1)?.end ?? source.releaseAt;
    const customRouteComplete = !source.masterProduct.route || (source.masterProduct.route.length > 0
      && !warnings.some(warning => warning.product === source.product && warning.code === "invalid-route")
      && source.masterProduct.route.every(process => route.some(operation => (operation.recordedProcess ?? operation.process) === process))
      && source.lot?.stage !== "on-hold" && source.lot?.stage !== "unclassified");
    const deliveryReadyAt = !customRouteComplete ? 0 : source.lot?.stage === "delivery-ready"
      ? source.lot.readyAt
      : source.masterProduct.route || route.some(operation => operation.process === "gkm") ? routedDeliveryReadyAt(seed, completion, source.masterProduct.family, route.at(-1)?.process) : 0;
    return {
      batchId: source.id,
      source: source.source,
      workOrder: source.workOrder,
      wipLotId: source.lot?.id,
      product: source.product,
      family: source.masterProduct.family,
      quantity: source.quantity,
      turningMachineId: route.find((operation) => operation.process === "turning")?.resourceId ?? source.batch?.machineId ?? source.machine?.id ?? "",
      operations: route,
      completion,
      deliveryReadyAt,
    };
  });
  // Enumerate unschedulable material too: a missing route/date is not zero stock.
  const represented = new Set(jobs.map(job => job.batchId));
  const addMissing = (job: RoutedProcessJob) => {
    if (represented.has(job.batchId)) return;
    jobs.push(job);
    represented.add(job.batchId);
    operations.push(...job.operations);
  };
  for (const lot of seed.wipLots ?? []) if (lot.availableQuantity > 0 && lot.stage !== "delivered" && lot.stage !== "scrapped") {
    addMissing({batchId:lot.id,source:"wip",workOrder:lot.workOrder,wipLotId:lot.id,product:lot.product,family:lot.family,quantity:lot.availableQuantity,turningMachineId:lot.completedSteps?.find(step=>step.process==='turning')?.resourceId??'',operations:actualWipOperations(lot,processMasterDataForProduct(master,lot.product)),completion:0,deliveryReadyAt:0});
  }
  for (const machine of seed.machines ?? []) if (machine.currentJob.product && machine.currentJob.quantity > 0) {
    addMissing({batchId:`current:${machine.id}`,source:"current-turning",workOrder:machine.currentJob.workOrder,product:machine.currentJob.product,family:processMasterDataForProduct(master,machine.currentJob.product)?.family??'piston',familyKnown:Boolean(processMasterDataForProduct(master,machine.currentJob.product)),quantity:machine.currentJob.quantity,turningMachineId:machine.id,operations:[],completion:0,deliveryReadyAt:0});
  }
  for (const batch of result.batches) if (batch.status === "planned" && batch.quantity > 0 && !representedBatchIds.has(batch.id)) {
    addMissing({batchId:batch.id,source:"turning-plan",workOrder:batch.workOrder??'',product:batch.product,family:processMasterDataForProduct(master,batch.product)?.family??'piston',familyKnown:Boolean(processMasterDataForProduct(master,batch.product)),quantity:batch.quantity,turningMachineId:batch.machineId,operations:[],completion:0,deliveryReadyAt:0});
  }
  for (const job of jobs) Object.assign(job, describeProcessRoute(seed,job,warnings));
  const queueEntries = processQueueEntries(seed,jobs,operations);
  const completion = Math.max(0, ...jobs.map((job) => job.completion));
  const deliveryCompletion = Math.max(0, ...jobs.map((job) => job.deliveryReadyAt));
  const gaps = processGapDiagnostics(seed, master, downstream);
  return { state: operations.length ? "planned" : "empty", operations, jobs, warnings, gaps, completion, deliveryCompletion, queueEntries };
}

export function parameterForProcess(product: ProcessProduct, process: DownstreamProcess): ProductProcessParameter | undefined {
  return product.processes.find((parameter) => parameter.process === process);
}

