import { factoryDateInput } from "./factory-time";
import type { PlanningSeed, ProductionHistoryEntry, ProductionInventoryStatus, ProductionProcess } from "./planning";
import type { DownstreamProcess } from "./process-master-data";

export type ArchiveFocus = { entryIds: string[]; action: "edit" | "restore" };

export type ProductionArchiveProcessSnapshot = {
  lotIds: string[];
  availableQuantity: number;
  deliveryReadyQuantity: number;
  latestCompletedProcess: ProductionProcess;
  currentAssignments: Array<{ process: DownstreamProcess; resourceId: string }>;
  currentProcesses: DownstreamProcess[];
  currentResourceIds: string[];
  nextProcesses: DownstreamProcess[];
};

export function productionArchiveProcessSnapshot(
  seed: Pick<PlanningSeed, "wipLots" | "processCurrentJobs">,
  entry: ProductionHistoryEntry,
  todaySerial = Number.POSITIVE_INFINITY,
): ProductionArchiveProcessSnapshot {
  const lots = productionHistoryLots(seed, entry);
  const lotIds = new Set(lots.map((lot) => lot.id));
  const currentJobs = (seed.processCurrentJobs ?? []).filter((job) => lotIds.has(job.wipLotId));
  const latestStep = lots
    .flatMap((lot) => lot.completedSteps)
    .sort((left, right) => right.end - left.end || right.recordedAt.localeCompare(left.recordedAt))[0];
  const unique = <T extends string>(values: T[]): T[] => [...new Set(values)];

  return {
    lotIds: [...lotIds],
    availableQuantity: lots.reduce((sum, lot) => sum + Math.max(0, lot.availableQuantity), 0),
    deliveryReadyQuantity: lots
      .filter((lot) => lot.stage === "delivery-ready" && lot.readyAt < todaySerial)
      .reduce((sum, lot) => sum + Math.max(0, lot.availableQuantity), 0),
    latestCompletedProcess: latestStep?.process ?? entry.process,
    currentAssignments: currentJobs.map((job) => ({ process: job.process, resourceId: job.resourceId })),
    currentProcesses: unique(currentJobs.map((job) => job.process)),
    currentResourceIds: unique(currentJobs.map((job) => job.resourceId)),
    nextProcesses: unique(lots.map((lot) => lot.nextProcess).filter((value): value is DownstreamProcess => Boolean(value))),
  };
}

function inputDateSerial(value: string): number {
  return value ? (Date.parse(`${value}T00:00:00Z`) - Date.UTC(1899, 11, 30)) / 86_400_000 : 0;
}

export function productionArchiveEventDate(
  entry: ProductionHistoryEntry,
  status: ProductionInventoryStatus = entry.inventoryStatus,
): string {
  if (status === "delivered") {
    if (entry.deliveredAtTime) return factoryDateInput(entry.deliveredAtTime);
    if (entry.deliveredAt) return entry.deliveredAt.slice(0, 10);
  }
  if (status === "scrapped") {
    if (entry.scrappedAt) return factoryDateInput(entry.scrappedAt);
    if (entry.statusChangedAt) return factoryDateInput(entry.statusChangedAt);
  }
  if (status === "voided") {
    if (entry.voidedAt) return factoryDateInput(entry.voidedAt);
    if (entry.statusChangedAt) return factoryDateInput(entry.statusChangedAt);
  }
  const date = new Date(Date.UTC(1899, 11, 30) + Math.floor(entry.completedAt) * 86_400_000);
  return Number.isFinite(date.getTime()) ? date.toISOString().slice(0, 10) : "";
}

export function productionArchiveEventSerial(
  entry: ProductionHistoryEntry,
  status: ProductionInventoryStatus = entry.inventoryStatus,
): number {
  return inputDateSerial(productionArchiveEventDate(entry, status));
}

export function productionArchiveDateLabel(status: ProductionInventoryStatus): string {
  return status === "delivered" ? "Teslim tarihi" : status === "scrapped" ? "Iskarta tarihi" : status === "voided" ? "İptal tarihi" : "Tamamlanma";
}

/** Prefer a record's own lots; split shipment records fall back to their source. */
export function productionHistoryLots(seed: Pick<PlanningSeed, "wipLots">, entry: ProductionHistoryEntry) {
  const matching = (seed.wipLots ?? []).filter(lot => lot.product === entry.product && lot.workOrder === entry.workOrder);
  if (entry.inventoryStatus === "delivered" && entry.wipAllocations) return matching.filter(lot => entry.wipAllocations!.some(item => item.lotId === lot.id));
  const direct = matching.filter(lot => lot.sourceHistoryEntryId === entry.id);
  return direct.length ? direct : matching.filter(lot => lot.sourceHistoryEntryId === entry.sourceEntryId);
}

export function journeyArchiveEntryIds(seed: PlanningSeed, batchId: string, lotId?: string): string[] {
  if (!lotId) return (seed.productionHistory ?? []).filter(entry => `history:${entry.id}` === batchId && entry.inventoryStatus === "delivered").map(entry => entry.id);
  return (seed.productionHistory ?? []).filter(entry => entry.inventoryStatus === "delivered" && productionHistoryLots(seed, entry).some(lot => lot.id === lotId)).map(entry => entry.id);
}

