import { assertOperationalMachineIdentity, addMachineCapacityHours, calculateSetup, getSetupSettings, isMachineEligibleForProduct, recalculateManualScenario, scenarioResultFromBatches, type PlanningSeed, type ScenarioResult, type PlannedBatch } from './planning';
import { registerTurningCompletion } from './wip-ledger';
import { assertProductionSwitchSnapshot, hasProtectedProductionRemainder, validateProductionInterruption, type ProductionInterruptionInput, type ProductionInterruption } from './production-interruptions';

export function replaceTurningCurrentJob(seed: PlanningSeed, result: ScenarioResult, machineId: string, targetBatchId: string, input: ProductionInterruptionInput, occurredAt: number): { seed: PlanningSeed; result: ScenarioResult } {
  assertProductionSwitchSnapshot(seed, result.batches, input);
  assertOperationalMachineIdentity(seed, result, machineId);
  const next = structuredClone(seed);
  const machine = next.machines.find(item => item.id === machineId);
  if (!machine?.currentJob.product || machine.currentJob.quantity <= 0) throw new Error('Değiştirilecek mevcut Torna işi bulunamadı.');
  const current = machine.currentJob;
  const produced = validateProductionInterruption(input, current.quantity, current.start, occurredAt);
  const target = result.batches.find(item => item.id === targetBatchId && item.status === 'planned');
  if (!target || target.machineId !== machineId) throw new Error('Aynı tezgahın kuyruğundan yeni bir şarj seçin.');
  if (result.batches.some(item => item.machineId === machineId && item.locked)) throw new Error('İş değişimi için tezgah kuyruğundaki kilitleri önce kaldırın.');
  if (!machine.active || !isMachineEligibleForProduct(next, machineId, target.product)) throw new Error('Yeni iş bu tezgahta üretime uygun değil.');
  const rate = machine.rates[target.product.toUpperCase()] ?? 0;
  if (rate <= 0 || machine.shiftFactor <= 0) throw new Error('Yeni iş için üretim hızı veya vardiya eksik.');
  const chargeId = current.batchId ?? `returned-${crypto.randomUUID()}`;
  const pause: ProductionInterruption | undefined = produced > 0 ? { id:`pause-${crypto.randomUUID()}`, kind:input.kind, chargeId, process:'turning', resourceId:machineId, product:current.product, workOrder:current.workOrder, producedQuantity:produced, remainingQuantity:current.quantity-produced, reason:input.reason!.trim(), occurredAt } : undefined;
  if (pause) {
    next.productionInterruptions = [...(next.productionInterruptions ?? []), pause];
    const id = pause.id;
    const archivedAt = new Date().toISOString();
    const history = { id:`history-${id}`, interruptionIds:[id], machineId, machineName:machine.name, workOrder:current.workOrder, product:current.product, originalQuantity:produced, completedQuantity:produced, start:current.start, plannedEnd:current.end, completedAt:occurredAt, archivedAt, process:'turning' as const, inventoryStatus:'semi-finished' as const, statusChangedAt:archivedAt, statusChangeReason:`${pause.kind === "partial-completion" ? "Kısmi üretim tamamlandı." : "Üretime ara verildi."} ${pause.reason}` };
    next.productionHistory = [history,...(next.productionHistory ?? [])];
    if (!registerTurningCompletion(next,history)) throw new Error('Üretilen adedin yarı mamül kaydı için ürün rotasını tamamlayın.');
  }
  const setup = calculateSetup(next,current.product,current.diameter,target.product,target.diameter);
  const hours = target.quantity / rate * getSetupSettings(next).shiftHours / (machine.capacityFactor ?? 1);
  const timeline = addMachineCapacityHours(next,machine,occurredAt,setup.hours+hours);
  machine.currentJob = { batchId:target.id, interruptionId:target.interruptionId, workOrder:target.workOrder ?? '', product:target.product, quantity:target.quantity, originalQuantity:target.quantity, remainingQuantity:target.quantity, start:timeline.start,end:timeline.end,dailyRate:rate*machine.shiftFactor*(machine.capacityFactor ?? 1),diameter:target.diameter };
  machine.availableStart = timeline.end; machine.operationalAvailableStart = timeline.end;
  const resumed = next.productionInterruptions?.find(item => item.id === target.interruptionId); if (resumed) resumed.resumedAt = occurredAt;
  const priorPause = (next.productionInterruptions ?? []).findLast(item => item.chargeId === chargeId && item.process === 'turning' && !item.completedAt && item.producedQuantity !== 0);
  const recovery = pause ?? priorPause;
  const remainder: PlannedBatch = { ...target, routeCommitted: undefined, routeTargetDate: undefined, id:chargeId, interruptionId:recovery?.id ?? (hasProtectedProductionRemainder(next, chargeId, current.interruptionId) ? current.interruptionId : undefined), product:current.product, workOrder:current.workOrder, quantity:current.quantity-produced, diameter:current.diameter, sequence:Math.max(0,...result.batches.map(item=>item.sequence))+1, locked:false, manuallyPlaced:true, planColumn:13, reason:recovery ? recovery.kind === 'partial-completion' ? 'Kısmi üretimin kalan işi.' : 'Üretime ara verildi.' : 'Üretim yapılmadan kuyruğa döndü.', explanation:recovery?.reason ?? '' };
  const localQueue = result.batches.filter(item=>item.id!==target.id && item.machineId===machineId && item.status==='planned')
    .sort((left,right)=>left.planColumn-right.planColumn || left.sequence-right.sequence).map((item,index)=>({...item,planColumn:14+index}));
  const local = recalculateManualScenario({...next,machines:[machine]},[remainder,...localQueue]);
  const unchanged = result.batches.filter(item=>item.machineId!==machineId || item.status!=='planned').map(item=>({...item}));
  const nextResult = scenarioResultFromBatches(next,[...local.batches,...unchanged]);
  if (recovery) recovery.turningBatch = {...nextResult.batches.find(item=>item.id===chargeId)!};
  next.manualBatches = nextResult.batches;
  next.lastAutomaticPlan = undefined; next.planRunSequence = undefined; next.planNeedsRecalculation = true;
  return {seed:next,result:nextResult};
}

export type TurningPartialRepairRequest = {
  interruptionId: string; workOrder: string; product: string; machineId: string;
  producedQuantity: number; remainingQuantity: number; reason: string;
};

/** Maintenance preview only. Caller must revalidate the saved revision before committing. */
export function previewTurningPartialRepair(seed: PlanningSeed, result: ScenarioResult, request: TurningPartialRepairRequest) {
  const original = seed.productionInterruptions?.find(item=>item.id===request.interruptionId);
  if (!Number.isSafeInteger(request.producedQuantity) || request.producedQuantity<=0 || !Number.isSafeInteger(request.remainingQuantity) || request.remainingQuantity<=0 || !request.reason?.trim() || !original || original.kind === 'partial-completion' || original.completedAt || original.resumedAt
    || original.process !== 'turning' || original.workOrder !== request.workOrder || original.product !== request.product
    || original.resourceId !== request.machineId || original.producedQuantity !== request.producedQuantity
    || original.remainingQuantity !== request.remainingQuantity) throw new Error('Kısmi üretim düzeltmesi güncel ara verme kaydıyla uyuşmuyor.');
  if (seed.productionInterruptions?.some(item=>item.id!==original.id && item.chargeId===original.chargeId && !item.completedAt)) throw new Error('Şarjın başka açık üretim kaydı var; ayrı inceleme gerekir.');
  assertOperationalMachineIdentity(seed,result,request.machineId);
  const histories=(seed.productionHistory??[]).filter(h=>h.interruptionIds?.includes(original.id));
  const lots=(seed.wipLots??[]).filter(l=>l.interruptionIds?.includes(original.id));
  const history=histories[0], lot=lots[0];
  if (histories.length!==1 || lots.length!==1 || !history || !lot || history.inventoryStatus!=='semi-finished'
    || history.machineId!==request.machineId || history.completedQuantity!==request.producedQuantity || history.product!==request.product || history.workOrder!==request.workOrder
    || lot.sourceHistoryEntryId!==history.id || lot.product!==request.product || lot.workOrder!==request.workOrder
    || lot.availableQuantity!==request.producedQuantity || lot.deliveredQuantity!==0 || lot.scrappedQuantity!==0
    || lot.interruptionIds?.length!==1 || lot.completedSteps.length!==1 || lot.completedSteps[0].quantity!==request.producedQuantity || lot.completedSteps[0].resourceId!==request.machineId || lot.completedSteps[0].process!=='turning' || lot.nextProcess!=='drilling'
    || !['quality-hold','drilling-queue'].includes(lot.stage)
    || seed.processCurrentJobs?.some(j=>j.wipLotId===lot.id)
    || seed.processOperationOverrides?.some(o=>o.batchId===lot.id)) throw new Error('Tamamlanan parçalar ilerlemiş veya değişmiş; kayıt bazında inceleyin.');
  const machine=seed.machines.find(m=>m.id===request.machineId);
  const matching=result.batches.filter(b=>b.id===original.chargeId);
  const remainder=matching[0];
  if (!machine || machine.currentJob.batchId===original.chargeId || matching.length!==1 || !remainder
    || remainder.status!=='planned' || remainder.machineId!==machine.id || remainder.quantity!==request.remainingQuantity
    || remainder.interruptionId!==original.id || remainder.product!==request.product || remainder.workOrder!==request.workOrder)
    throw new Error('Kalan üretim aynı tezgah kuyruğunda doğrulanamadı.');
  const next=structuredClone(seed);
  const queue=result.batches.filter(b=>b.machineId===machine.id&&b.status==='planned').sort((a,b)=>a.planColumn-b.planColumn||a.sequence-b.sequence);
  const reordered=[remainder,...queue.filter(b=>b.id!==remainder.id)].map((b,i)=>({...b,planColumn:13+i}));
  // This explicitly reviewed repair may move the affected locked queue; preserve the lock flags.
  const local=recalculateManualScenario({...next,machines:[next.machines.find(m=>m.id===machine.id)!]},reordered);
  const nextResult=scenarioResultFromBatches(next,[...local.batches,...result.batches.filter(b=>b.machineId!==machine.id||b.status!=='planned')]);
  const repaired=next.productionInterruptions!.find(item=>item.id===original.id)!;
  repaired.kind='partial-completion';
  repaired.turningBatch={...nextResult.batches.find(b=>b.id===remainder.id)!};
  next.manualBatches=nextResult.batches;
  next.planNeedsRecalculation=true;next.lastAutomaticPlan=undefined;next.planRunSequence=undefined;
  const summary={workOrder:request.workOrder,product:request.product,machineId:machine.id,producedQuantity:lot.availableQuantity,remainingQuantity:remainder.quantity,
    previousPosition:queue.findIndex(b=>b.id===remainder.id)+1,position:1,
    queueChanges:queue.map(before=>{const after=nextResult.batches.find(b=>b.id===before.id)!;return {id:before.id,workOrder:before.workOrder,quantity:before.quantity,locked:Boolean(before.locked),beforePosition:before.planColumn-12,afterPosition:after.planColumn-12,beforeStart:before.start,afterStart:after.start,beforeEnd:before.end,afterEnd:after.end};})};
  return {seed:next,result:nextResult,summary};
}

