export type RawMaterialSettings = {
  scrapPercent: number;
  stockDate: string;
  stocks: Array<{ materialCode: string; kg: number | null }>;
};

export function initialRawMaterialSettings(): RawMaterialSettings {
  return { scrapPercent: 2, stockDate: "", stocks: [] };
}

export function validateRawMaterialSettings(value: unknown): RawMaterialSettings {
  const settings = value as RawMaterialSettings | null;
  if (!settings || typeof settings.scrapPercent !== "number" || !Number.isFinite(settings.scrapPercent)
    || settings.scrapPercent < 0 || settings.scrapPercent > 100
    || typeof settings.stockDate !== "string"
    || (settings.stockDate !== "" && (!/^\d{4}-\d{2}-\d{2}$/.test(settings.stockDate)
      || !Number.isFinite(Date.parse(settings.stockDate)) || new Date(settings.stockDate).toISOString().slice(0, 10) !== settings.stockDate))
    || !Array.isArray(settings.stocks) || settings.stocks.length > 5000) {
    throw new Error("Iskarta oranı 0–100 arasında ve güncelleme tarihi geçerli olmalıdır.");
  }
  const codes = new Set<string>();
  for (const row of settings.stocks) {
    if (!row || typeof row.materialCode !== "string" || !row.materialCode.trim()
      || row.materialCode !== row.materialCode.trim().toUpperCase() || codes.has(row.materialCode)
      || (row.kg !== null && (typeof row.kg !== "number" || !Number.isFinite(row.kg) || row.kg < 0))) {
      throw new Error("Hammadde kodları benzersiz, stoklar sıfır veya pozitif kg olmalıdır. Bilinmeyen stoğu boş bırakın.");
    }
    codes.add(row.materialCode);
  }
  return structuredClone(settings);
}

frontend/lib/route-placement.ts.source:
import { activeLotInterruptions, hasActiveProductionInterruption } from "./production-interruptions";
import { buildOrderDeliveryResults } from "./delivery-readiness";
import { currentJobRouteIdentity, moveBatchManually, type PlanningSeed, type ScenarioResult } from "./planning";
import { activeProcessResourceIds, processLabel, type DownstreamProcess, type ProcessKind } from "./process-master-data";
import { processPlacementOverride, processPlacementBaseline, buildDownstreamProcessPlan, placementDeliveryWarnings, previewProcessOperationReschedule, previewProcessQueuePlacement, type ProcessOperation } from "./process-planning";

export type RoutePlacementRequest =
  | { kind: "turning"; batchId: string; resourceId: string; position: number }
  | { kind: "process"; operationId: string; resourceId: string; requestedStart: number }
  | { kind: "queue"; operationId: string; resourceId: string; position: number | "end" }
  | { kind: "edit"; batchId: string; process: ProcessKind };
export type RouteStageChoice = { mode: "priority" | "keep" | "manual"; resourceId?: string; requestedStart?: number };
export type RoutePlacementOptions = { propagate: boolean; targetDate: string; stages: Partial<Record<DownstreamProcess, RouteStageChoice>>; release?: boolean };
export const routeInputSignature = (seed: PlanningSeed, result: ScenarioResult) => JSON.stringify([seed, result]);
const changed = (a: ProcessOperation, b: ProcessOperation) => a.resourceId !== b.resourceId || Math.abs(a.start - b.start) > 1e-8 || Math.abs(a.end - b.end) > 1e-8;
const protectedOperation = (op: ProcessOperation) => op.actual || op.current || op.process === "turning" && op.source === "current-turning";

export function routePlacementSubject(seed: PlanningSeed, result: ScenarioResult, request: RoutePlacementRequest) {
  const plan = "operationId" in request ? processPlacementBaseline(seed, result, request.operationId) : buildDownstreamProcessPlan(seed, result);
  const operation = "operationId" in request ? plan.operations.find(op => op.id === request.operationId) : plan.operations.find(op => op.batchId === request.batchId && op.process === (request.kind === "turning" ? "turning" : request.process));
  if (!operation || protectedOperation(operation)) throw new Error("Yalnızca planlanan veya kuyruktaki bir prosesin akışı düzenlenebilir.");
  const job = plan.jobs.find(job => job.batchId === operation.batchId)!;
  const definition = seed.processMasterData?.products.find(item => item.product === job.product);
  const interrupted = activeLotInterruptions(seed, seed.wipLots?.find(lot => lot.id === job.wipLotId)).length > 0 || hasActiveProductionInterruption(seed, job.batchId);
  if (!definition || (!interrupted && (definition.processes.some(step => step.sequence >= operation.sequence && !job.operations.some(op => op.process === step.process)) || !job.deliveryReadyAt))) throw new Error("Rota tamamlanamıyor; eksik proses, parametre veya kapasiteyi kontrol edin.");
  return { plan, operation, job, interrupted };
}

export function defaultRoutePlacementOptions(seed: PlanningSeed, result: ScenarioResult, request: RoutePlacementRequest): RoutePlacementOptions {
  const { job, operation, interrupted } = routePlacementSubject(seed, result, request);
  const scopedOverrides = job.operations.filter(op => op.process !== "turning").flatMap(op => { const saved = processPlacementOverride(seed, op.batchId, op.product, op.process as DownstreamProcess, !interrupted); return saved ? [saved] : []; });
  const stages: RoutePlacementOptions["stages"] = {};
  for (const op of job.operations.filter(op => op.sequence >= operation.sequence && op.process !== "turning" && !protectedOperation(op))) {
    const saved = scopedOverrides.find(item => item.process === op.process);
    stages[op.process as DownstreamProcess] = { mode: saved?.routeMode === "automatic" ? "priority" : saved?.routeMode ?? (saved ? "manual" : "priority"), resourceId: op.resourceId, requestedStart: op.start };
  }
  if (interrupted) return {propagate:false,targetDate:"",stages};
  return { propagate: true, targetDate: result.batches.find(item => item.id === job.batchId)?.routeTargetDate ?? scopedOverrides.find(item => item.routeTargetDate)?.routeTargetDate ?? "", stages };
}

/** One draft, using the existing queue/calendar engine at every step. No persistence. */
export function previewRoutePlacement(seed: PlanningSeed, result: ScenarioResult, request: RoutePlacementRequest, options: RoutePlacementOptions) {
  const { plan: before, operation: origin, job: beforeJob, interrupted } = routePlacementSubject(seed, result, request);
  if ((request.kind === "turning" || request.kind === "queue") && request.position !== "end" && (!Number.isInteger(request.position) || request.position < 0)) throw new Error("Geçerli bir kuyruk sırası seçin.");
  if (interrupted && (options.propagate || options.release || options.targetDate)) throw new Error("Yarım üretimde yalnız seçili proses manuel yerleştirilebilir; sonraki prosesler ve teslim tarihi otomatik atanmaz.");
  if (options.targetDate && (!/^\d{4}-\d{2}-\d{2}$/.test(options.targetDate) || !Number.isFinite(Date.parse(options.targetDate)) || new Date(options.targetDate).toISOString().slice(0, 10) !== options.targetDate)) throw new Error("Geçerli bir hedef teslim tarihi seçin.");
  let nextSeed = structuredClone(seed);
  let nextResult = structuredClone(result);
  const currentMachine = beforeJob.source === "current-turning" ? seed.machines.find(machine => `current:${machine.id}` === origin.batchId) : undefined;
  const sourceCurrentJobKey = currentMachine ? currentJobRouteIdentity(currentMachine) : undefined;
  const adjustments: string[] = [];
  if (options.release) nextSeed.processOperationOverrides = [
    ...(nextSeed.processOperationOverrides ?? []).filter(item => item.batchId !== origin.batchId),
    ...beforeJob.operations.filter(op => op.process !== "turning" && !protectedOperation(op)).map(op => ({ batchId: op.batchId, process: op.process as DownstreamProcess, resourceId: op.resourceId, requestedStart: op.start, routeMode: "automatic" as const, sourceProduct: op.product, sourceCurrentJobKey, updatedAt: new Date().toISOString() })),
  ];
  // The selected route is edited as a unit: defer its old keep constraints until
  // every chosen stage has been placed. Other jobs' kept reservations stay active.
  if (!options.release) for (const op of beforeJob.operations.filter(op => op.process !== "turning" && !protectedOperation(op) && op.sequence >= origin.sequence && (options.propagate || op.id === origin.id))) {
    const existing = processPlacementOverride(nextSeed, op.batchId, op.product, op.process as DownstreamProcess, !interrupted);
    if (!existing) continue;
    nextSeed.processOperationOverrides = [...(nextSeed.processOperationOverrides ?? []).filter(item => item.batchId !== op.batchId || item.process !== op.process),
      { ...existing, batchId: op.batchId, routeMode: "manual", preservedStart: undefined, preservedEnd: undefined, sourceCurrentJobKey }];
  }
  if (!options.release && request.kind === "turning") nextResult = moveBatchManually(nextSeed, nextResult, request.batchId, request.resourceId, request.position);
  if (!options.release && (request.kind === "process" || request.kind === "queue")) {
    const preview = request.kind === "queue" ? previewProcessQueuePlacement(nextSeed, nextResult, request) : previewProcessOperationReschedule(nextSeed, nextResult, request.operationId, request.resourceId, request.requestedStart);
    nextSeed = preview.seed;
    adjustments.push(...preview.adjustments);
  }
  const editable = beforeJob.operations.filter(op => op.process !== "turning" && !protectedOperation(op) && (request.kind === "edit" ? op.sequence >= origin.sequence : op.sequence > origin.sequence));
  for (const original of editable) {
    if (options.release || !options.propagate && original.id !== origin.id) continue;
    const process = original.process as DownstreamProcess;
    const choice = options.stages[process] ?? { mode: "priority" };
    const operation = buildDownstreamProcessPlan(nextSeed, nextResult).operations.find(op => op.id === original.id);
    if (!operation) throw new Error(`${processLabel(process)} adımı hesaplanamadı; rota ve kapasiteyi kontrol edin.`);
    if (choice.mode === "keep") {
      const saved = processPlacementOverride(nextSeed, original.batchId, original.product, process, !interrupted);
      nextSeed.processOperationOverrides = [...(nextSeed.processOperationOverrides ?? []).filter(item => item.batchId !== original.batchId || item.process !== process),
        { ...saved, batchId: original.batchId, process, resourceId: original.resourceId, requestedStart: original.start, preservedStart: original.start, preservedEnd: original.end, routeMode: "keep", sourceProduct: original.product, sourceCurrentJobKey, updatedAt: new Date().toISOString() }];
    } else {
      const parameter = nextSeed.processMasterData?.products.find(product => product.product === operation.product)?.processes.find(item => item.process === process);
      const resources = parameter ? activeProcessResourceIds(parameter) : [];
      const currentPlan = buildDownstreamProcessPlan(nextSeed, nextResult);
      const candidates = (choice.mode === "manual" ? [choice.resourceId ?? operation.resourceId] : resources).flatMap(resourceId => {
        const anchors = choice.mode === "manual" ? [choice.requestedStart ?? operation.start] : [...new Set([operation.readyAt, ...currentPlan.operations.filter(op => op.resourceId === resourceId && op.id !== operation.id && op.end >= operation.readyAt).map(op => op.end)])].sort((a, b) => a - b);
        for (const requestedStart of anchors) {
          try { return [previewProcessOperationReschedule(nextSeed, nextResult, operation.id, resourceId, requestedStart)]; }
          catch (error) { if (choice.mode === "manual") throw error; }
        }
        return [];
      }).sort((a, b) => a.operation.end - b.operation.end || a.operation.resourceId.localeCompare(b.operation.resourceId));
      const selected = candidates[0];
      if (!selected) throw new Error(`${processLabel(process)} için önceki proses, korunmuş kuyruk ve kapasite kurallarına uyan yerleşim bulunamadı. Elle yerleştir veya Mevcut yerleşimi koru seçin.`);
      nextSeed = selected.seed;
      adjustments.push(...selected.adjustments);
      const saved = nextSeed.processOperationOverrides!.find(item => item.batchId === operation.batchId && item.process === process)!;
      saved.routeMode = choice.mode;
      delete saved.preservedEnd;
      delete saved.preservedStart;
    }
  }
  // Preserve charge identity through automatic planning, without locking its editor.
  const selectedBatch = nextResult.batches.find(batch => batch.id === origin.batchId);
  if (selectedBatch) { selectedBatch.routeCommitted = options.release ? undefined : true; selectedBatch.routeTargetDate = options.release ? undefined : options.targetDate || undefined; }
  for (const item of nextSeed.processOperationOverrides ?? []) if (item.batchId === origin.batchId) item.routeTargetDate = options.release ? undefined : options.targetDate || undefined;
  const plan = buildDownstreamProcessPlan(nextSeed, nextResult);
  const conflict = plan.warnings.find(warning => warning.code === "placement-conflict");
  if (conflict) throw new Error(conflict.message);
  for (const op of before.operations) {
    const after = plan.operations.find(item => item.id === op.id);
    if (!after || after.quantity !== op.quantity || after.product !== op.product) throw new Error(`${op.product} · ${processLabel(op.process)} kaybolduğu veya miktarı değiştiği için işlem uygulanamaz.`);
    if (protectedOperation(op) && changed(op, after)) throw new Error("Çalışan ve tamamlanan işler değiştirilemez.");
  }
  for (const batch of result.batches) {
    const after = nextResult.batches.find(item => item.id === batch.id);
    if (!after || after.quantity !== batch.quantity || after.product !== batch.product) throw new Error("Şarj kimliği ve miktarı korunamadı.");
    if (batch.locked && (after.start !== batch.start || after.end !== batch.end || after.machineId !== batch.machineId)) throw new Error("Kilitli Torna yerleşimi değiştirilemez.");
  }
  const afterJob = plan.jobs.find(job => job.batchId === origin.batchId)!;
  if (!interrupted && !afterJob.deliveryReadyAt) throw new Error("Teslimata hazır tarih hesaplanamadı; rota kapasitesini kontrol edin.");
  const affectedOperations = before.operations.flatMap(op => { const after = plan.operations.find(item => item.id === op.id)!; return changed(op, after) ? [{ before: op, after }] : []; });
  const beforeOrders = buildOrderDeliveryResults(seed, result);
  if (nextResult.batches.length !== result.batches.length || new Set(nextResult.batches.map(batch => batch.id)).size !== nextResult.batches.length) throw new Error("Şarj kimlikleri veya kayıt sayısı korunamadı.");
  nextSeed.manualBatches = nextResult.batches;
  const afterOrders = buildOrderDeliveryResults(nextSeed, nextResult);
  const affectedOrders = beforeOrders.flatMap(order => { const after = afterOrders.find(item => item.id === order.id)!; return order.onTimePlanned !== after.onTimePlanned ? [{ before: order, after }] : []; });
  const targetSerial = options.targetDate ? (Date.parse(`${options.targetDate}T00:00:00Z`) - Date.UTC(1899, 11, 30)) / 86400000 : null;
  // T10: warning only, from the final full-route plan. Torna-origin moves keep their existing rules.
  const turningOrigin = request.kind === "turning" || (request.kind === "edit" && request.process === "turning") || origin.process === "turning";
  const deliveryWarnings = turningOrigin ? [] : placementDeliveryWarnings(seed, result, before, plan);
  return { seed: nextSeed, result: nextResult, plan, beforeJob, afterJob, affectedOperations, affectedOrders, deliveryWarnings, adjustments: [...new Set(adjustments)], targetMet: targetSerial === null || !afterJob.deliveryReadyAt ? null : Math.floor(afterJob.deliveryReadyAt) <= targetSerial, request, options: structuredClone(options), inputSignature: routeInputSignature(seed, result) };
}
export type RoutePlacementPreview = ReturnType<typeof previewRoutePlacement>;

export function revalidateRoutePlacement(seed: PlanningSeed, result: ScenarioResult, preview: RoutePlacementPreview) {
  if (routeInputSignature(seed, result) !== preview.inputSignature) throw new Error("Plan veya girdiler değişti. Önizlemeyi yenileyin ve etkileri yeniden inceleyin.");
  return previewRoutePlacement(seed, result, preview.request, preview.options);
}

