import { buildOperationalMetrics } from "./operational-metrics";
import type { StoredScenario } from "./planning";

export type ScenarioMetric = {
  label: string;
  value: number;
  direction: "higher" | "lower" | "neutral";
};

/** Read the saved scenario, using the same metrics for inspection and comparison. */
export function buildScenarioInspection(scenario: StoredScenario) {
  const { summary, batches } = scenario.result;
  const operational = buildOperationalMetrics(scenario.seed, scenario.result);
  const metrics: ScenarioMetric[] = [
    { label: "Talep", value: summary.demand, direction: "neutral" },
    { label: "Planlanan", value: summary.planned, direction: "higher" },
    { label: "Net eksik", value: Math.max(0, summary.demand - summary.planned), direction: "lower" },
    { label: "Brüt eksik", value: summary.shortage, direction: "lower" },
    { label: "Fazla üretim", value: summary.overproduction, direction: "lower" },
    { label: "Yeni şarj", value: summary.plannedBatchCount, direction: "neutral" },
    { label: "Planlanamayan", value: summary.unplannedBatchCount, direction: "lower" },
    { label: "Setup saati", value: summary.totalSetupHours ?? 0, direction: "lower" },
    { label: "Kullanılan tezgah", value: summary.machinesUsed ?? 0, direction: "neutral" },
    { label: "Planlanan mesai saati", value: operational.plannedOvertimeHours, direction: "neutral" },
    { label: "Bakıma ayrılan saat", value: operational.maintenanceHours, direction: "neutral" },
    { label: "Fasona planlanan adet", value: operational.outsourcedQuantity, direction: "neutral" },
  ];
  const machines = scenario.seed.machines.map((machine) => {
    const planned = batches.filter((batch) => batch.status === "planned" && batch.machineId === machine.id);
    return { id: machine.id, count: planned.length, quantity: planned.reduce((sum, batch) => sum + batch.quantity, 0) };
  }).filter((machine) => machine.count > 0);
  return { metrics, machines, operational };
}

export type ScenarioInspection = ReturnType<typeof buildScenarioInspection>;

frontend/lib/scenario-list.ts.source:
import type { PlanRunMetadata, StoredScenario, ScenarioAccess } from "./planning";

export const SCENARIO_PAGE_SIZE = 20;

export type StoredScenarioSummary = ScenarioAccess & {
  id: string;
  name: string;
  createdAt: string;
  notes: string;
  plannedBatchCount: number;
  planRun?: PlanRunMetadata;
};

export type ScenarioListPage = {
  items: StoredScenarioSummary[];
  total: number;
  limit: number;
  offset: number;
  hasMore: boolean;
};

export function scenarioSummaryFromStored(scenario: StoredScenario): StoredScenarioSummary {
  return {
    ...scenarioAccess(scenario),
    id: scenario.id,
    name: scenario.name,
    createdAt: scenario.createdAt,
    notes: scenario.notes,
    plannedBatchCount: Math.max(0, Math.trunc(scenario.result.summary.plannedBatchCount)),
    planRun: scenario.result.planRun ?? scenario.seed.activePlanRun,
  };
}

export function parseScenarioListPage(value: unknown): ScenarioListPage {
  if (!value || typeof value !== "object") throw new Error("Senaryo listesi yanıtı geçersiz.");
  const record = value as Record<string, unknown>;
  if (!Array.isArray(record.items)) throw new Error("Senaryo listesi bulunamadı.");
  const items = record.items.map((item) => {
    if (!item || typeof item !== "object") throw new Error("Senaryo özeti geçersiz.");
    const row = item as Record<string, unknown>;
    if (!row.id || !row.name || !row.createdAt) throw new Error("Senaryo özetinde zorunlu alan eksik.");
    return {
      ...scenarioAccess(row),
      id: String(row.id),
      name: String(row.name),
      createdAt: String(row.createdAt),
      notes: String(row.notes ?? ""),
      plannedBatchCount: Math.max(0, Math.trunc(Number(row.plannedBatchCount) || 0)),
      planRun: row.planRun && typeof row.planRun === "object" ? row.planRun as PlanRunMetadata : undefined,
    };
  });
  const total = Math.max(items.length, Math.trunc(Number(record.total) || 0));
  const limit = Math.max(1, Math.trunc(Number(record.limit) || SCENARIO_PAGE_SIZE));
  const offset = Math.max(0, Math.trunc(Number(record.offset) || 0));
  return { items, total, limit, offset, hasMore: Boolean(record.hasMore) };
}

export function scenarioAccess(row: ScenarioAccess | Record<string, unknown>): ScenarioAccess {
  return { ownerId: typeof row.ownerId === "string" ? row.ownerId : null, ownerName: typeof row.ownerName === "string" ? row.ownerName : null,
    revision: Number(row.revision) || 0, updatedAt: typeof row.updatedAt === "string" ? row.updatedAt : undefined,
    shared: row.shared === true, canEdit: row.canEdit === true, legacy: row.legacy === true,
    sourceId: typeof row.sourceId === "string" ? row.sourceId : null, sourceRevision: Number(row.sourceRevision) || null };
}

