import catalogJson from "../data/product-setup-families.json";

export type ProductSetupFamily = "center-pin" | "piston";

export const PRODUCT_SETUP_FAMILIES: readonly ProductSetupFamily[] = ["piston", "center-pin"];

const FAMILY_VALUES = new Set<ProductSetupFamily>(["center-pin", "piston"]);
const catalog = catalogJson as Record<ProductSetupFamily, string[]>;
const familyByProduct = new Map<string, ProductSetupFamily>();

for (const family of ["center-pin", "piston"] as const) {
  for (const rawProduct of catalog[family]) {
    const product = rawProduct.trim().toUpperCase();
    const existing = familyByProduct.get(product);
    if (existing && existing !== family) throw new Error(`${product} hem ${existing} hem ${family} setup ailesinde tanımlı.`);
    familyByProduct.set(product, family);
  }
}

export function normalizeProductSetupFamily(value: unknown): ProductSetupFamily | undefined {
  return typeof value === "string" && FAMILY_VALUES.has(value as ProductSetupFamily)
    ? value as ProductSetupFamily
    : undefined;
}

export function catalogProductSetupFamily(productCode: string): ProductSetupFamily | undefined {
  return familyByProduct.get(productCode.trim().toUpperCase());
}

export function resolvedProductSetupFamily(productCode: string, storedFamily?: unknown): ProductSetupFamily | undefined {
  return normalizeProductSetupFamily(storedFamily) ?? catalogProductSetupFamily(productCode);
}

export function productSetupFamilyLabel(family: ProductSetupFamily | undefined): string {
  return family === "piston" ? "Piston" : family === "center-pin" ? "Center Pin" : "Aile tanımsız";
}

export function productSetupFamilyDescription(family: ProductSetupFamily | undefined): string {
  if (!family) return "Ürün ailesi henüz tanımlanmadı; setup sınıfı hesaplanamaz.";
  return family === "piston"
    ? "Center Pin ürününe geçişte 5 saat setup uygulanır."
    : "Piston ürününe geçişte 5 saat setup uygulanır.";
}

export function productSetupFamilyCatalog(): Readonly<Record<ProductSetupFamily, readonly string[]>> {
  return catalog;
}

