import { activeWipLots, wipStageLabel } from "./wip-ledger";
import { factoryNowSerial } from "./factory-time";
import { formatExcelDate } from "./planning";
import { formatInteger } from "./number-format";
import type { PlanningSeed, WipLot, WipMovementKind } from "./planning";

/**
 * Tavsiyeler → Hareketsiz şarjlar (T07). A charge with physical WIP and no
 * production movement for the threshold (default 30 days) needs a physical
 * check. Nothing is deleted or scrapped automatically.
 */
export type AdviceSettings = { version: 1; staleChargeDays: number };
export const DEFAULT_STALE_CHARGE_DAYS = 30;

/** Real production events. Notes, count/stage corrections, holds and parameter edits are not movement. */
export const PRODUCTION_MOVEMENT_KINDS: WipMovementKind[] = ["created", "split", "process-completed", "delivered", "scrapped"];

export function defaultAdviceSettings(): AdviceSettings {
  return { version: 1, staleChargeDays: DEFAULT_STALE_CHARGE_DAYS };
}

export function validateAdviceSettings(value: unknown): AdviceSettings {
  const settings = value as AdviceSettings;
  if (!settings || typeof settings !== "object" || settings.version !== 1 || !Number.isInteger(settings.staleChargeDays) || settings.staleChargeDays < 1 || settings.staleChargeDays > 365) {
    throw new Error("Hareketsiz şarj eşiği 1–365 tam gün olmalıdır.");
  }
  return { version: 1, staleChargeDays: settings.staleChargeDays };
}

export function staleChargeDays(seed: Pick<PlanningSeed, "adviceSettings">): number {
  const days = seed.adviceSettings?.staleChargeDays;
  return Number.isInteger(days) && days! >= 1 && days! <= 365 ? days! : DEFAULT_STALE_CHARGE_DAYS;
}

export type StaleCharge = {
  lotId: string;
  chargeId: string;
  workOrder: string;
  product: string;
  quantity: number;
  stage: string;
  /** Factory serial of the last production movement; undefined means no recorded time. */
  lastMovementAt?: number;
  lastMovementLabel: string;
  idleDays?: number;
  unknown: boolean;
};

/** The physical lot chain that shares one charge identity (parent lots and splits). */
function lineage(seed: PlanningSeed, lot: WipLot): Set<string> {
  const ids = new Set<string>([lot.id]);
  let parent = lot.parentLotId;
  while (parent && !ids.has(parent)) { ids.add(parent); parent = seed.wipLots?.find(item => item.id === parent)?.parentLotId; }
  return ids;
}

export function lastProductionMovement(seed: PlanningSeed, lot: WipLot): { at?: number; label: string } {
  const ids = lineage(seed, lot);
  const candidates: Array<{ at: number; label: string }> = [];
  for (const movement of seed.wipMovements ?? []) {
    if (!ids.has(movement.lotId) || !PRODUCTION_MOVEMENT_KINDS.includes(movement.kind) || !Number.isFinite(movement.occurredAt)) continue;
    candidates.push({ at: movement.occurredAt, label: movement.kind });
  }
  for (const step of lot.completedSteps ?? []) if (Number.isFinite(step.end) && step.end > 0) candidates.push({ at: step.end, label: `${step.process}-completed` });
  const latest = candidates.sort((a, b) => b.at - a.at)[0];
  return latest ? { at: latest.at, label: latest.label } : { label: "Kayıtlı üretim hareketi yok" };
}

export function staleCharges(seed: PlanningSeed, now = factoryNowSerial()): StaleCharge[] {
  const threshold = staleChargeDays(seed);
  const running = new Set((seed.processCurrentJobs ?? []).map(job => job.wipLotId));
  const rows: StaleCharge[] = [];
  for (const lot of activeWipLots(seed)) {
    if (lot.availableQuantity <= 0 || running.has(lot.id) || lot.stage === "delivered" || lot.stage === "scrapped") continue;
    const last = lastProductionMovement(seed, lot);
    const idleDays = last.at === undefined ? undefined : Math.floor(now - last.at);
    if (idleDays !== undefined && idleDays < threshold) continue;
    rows.push({
      lotId: lot.id, chargeId: lot.sourceBatchId ?? lot.id, workOrder: lot.workOrder, product: lot.product, quantity: lot.availableQuantity,
      stage: wipStageLabel(lot.stage, false), lastMovementAt: last.at, lastMovementLabel: last.label, idleDays, unknown: last.at === undefined,
    });
  }
  return rows.sort((a, b) => Number(a.unknown) - Number(b.unknown) || (b.idleDays ?? 0) - (a.idleDays ?? 0) || a.lotId.localeCompare(b.lotId));
}

export type StaleChargeAdvice = {
  id: string;
  kind: "stale-charge";
  product: string;
  title: string;
  detail: string;
  benefit: string;
  actionLabel: string;
  action: { type: "inspect-stale-charge"; lotId: string; chargeId: string; lastMovementAt?: number; idleDays?: number };
};

/** Tavsiyeler rows; independent of plan state. Separate from buildPlanningAdvice to keep its action union stable. */
export function buildStaleChargeAdvice(seed: PlanningSeed, now = factoryNowSerial()): StaleChargeAdvice[] {
  const threshold = staleChargeDays(seed);
  return staleCharges(seed, now).map(charge => ({
    id: `stale-charge:${charge.lotId}`, kind: "stale-charge", product: charge.product,
    title: charge.unknown
      ? `${charge.workOrder || charge.chargeId} · Son üretim hareketinin zamanı bilinmiyor`
      : `${charge.workOrder || charge.chargeId} · ${charge.idleDays} gündür üretim hareketi yok (eşik ${threshold} gün)`,
    detail: `${charge.product} · ${formatInteger(charge.quantity)} adet · ${charge.stage} · Son üretim hareketi: ${charge.lastMovementAt === undefined ? "kayıt yok" : `${formatExcelDate(charge.lastMovementAt)} (${charge.idleDays} gün önce)`}.`,
    benefit: "Şarjın fiziksel olarak hâlâ yerinde olup olmadığını kontrol edin. Uygulama stoğu silmez veya hurdaya ayırmaz.",
    actionLabel: "Şarjı incele",
    action: { type: "inspect-stale-charge", lotId: charge.lotId, chargeId: charge.chargeId, lastMovementAt: charge.lastMovementAt, idleDays: charge.idleDays },
  }));
}

