import {
  orderDeliveryMilestones,
  productionQuantityByTurningDate,
  type Order,
  type PlannedBatch,
  type PlanningSeed,
  type ScenarioResult,
} from "./planning";
import { buildDeliveryReadinessEvents, deliveryReadyQuantityFromEvents, type DeliveryReadinessEvent } from "./delivery-readiness";

export type WeeklyProductStatus = {
  product: string;
  required: number;
  ready: number;
  shortage: number;
};

export type WeeklyPlanStatus = {
  id: string;
  label: string;
  dueDate: string;
  newDemand: number;
  required: number;
  ready: number;
  shortage: number;
  riskProductCount: number;
  products: WeeklyProductStatus[];
  excludedFromPlan?: boolean;
};

export type BatchSplitInsight = {
  interrupted: true;
  justifiedByDeadline: boolean;
  interveningProduct: string;
  interveningDueDate: string;
  resumedDueDate: string;
};

type ProductCheckpoint = {
  date: string;
  quantity: number;
};

export type PlannedBatchDemandOrigin = {
  weekLabel: string;
  shortDateLabel: string;
  dateLabel: string;
  label: string;
};

function inputDateSerial(value: string): number {
  return value ? (Date.parse(`${value}T00:00:00Z`) - Date.UTC(1899, 11, 30)) / 86_400_000 : 0;
}

function routedQuantityByDate(seed: PlanningSeed, events: DeliveryReadinessEvent[], product: string, serial: number): number {
  return deliveryReadyQuantityFromEvents(seed, events, product, serial);
}

function checkpointsForOrder(order: Order): ProductCheckpoint[] {
  const byDate = new Map<string, number>();
  for (const milestone of orderDeliveryMilestones(order)) {
    if (!milestone.date) continue;
    byDate.set(milestone.date, Math.max(byDate.get(milestone.date) ?? 0, milestone.quantity));
  }
  if (order.dueDate) byDate.set(order.dueDate, Math.max(byDate.get(order.dueDate) ?? 0, order.quantity));
  let previousQuantity = 0;
  return [...byDate.entries()]
    .map(([date, quantity]) => ({ date, quantity }))
    .sort((left, right) => left.date.localeCompare(right.date))
    .map((checkpoint) => {
      const incrementalQuantity = Math.max(0, checkpoint.quantity - previousQuantity);
      previousQuantity = Math.max(previousQuantity, checkpoint.quantity);
      return { ...checkpoint, quantity: incrementalQuantity };
    });
}

function weekLabel(seed: PlanningSeed, dueDate: string): string {
  const matchingWeek = seed.customerDemand?.weeks.find((week) => week.weekEnd === dueDate);
  if (matchingWeek) return `W${String(matchingWeek.isoWeek).padStart(2, "0")}`;
  const activeStart = seed.customerDemand?.weeks.find((week) => week.id === seed.customerDemand?.activeScope.startWeekId)?.weekStart
    ?? seed.customerDemand?.weeks[0]?.weekStart;
  if (activeStart && dueDate < activeStart) return "Devreden";
  return new Intl.DateTimeFormat("tr-TR", { day: "2-digit", month: "short", timeZone: "UTC" }).format(new Date(`${dueDate}T00:00:00Z`));
}

function isoWeekForDate(value: string): { year: number; week: number } | null {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
  const date = new Date(`${value}T00:00:00Z`);
  if (!Number.isFinite(date.getTime())) return null;
  const thursday = new Date(date);
  thursday.setUTCDate(thursday.getUTCDate() - (thursday.getUTCDay() + 6) % 7 + 3);
  const firstThursday = new Date(Date.UTC(thursday.getUTCFullYear(), 0, 4));
  firstThursday.setUTCDate(firstThursday.getUTCDate() - (firstThursday.getUTCDay() + 6) % 7 + 3);
  return { year: thursday.getUTCFullYear(), week: 1 + Math.round((thursday.getTime() - firstThursday.getTime()) / (7 * 86_400_000)) };
}

export function plannedBatchDemandOrigin(
  seed: PlanningSeed,
  batch: Pick<PlannedBatch, "demandDueDate" | "demandCheckpointId">,
): PlannedBatchDemandOrigin | null {
  const dueDate = batch.demandDueDate ?? "";
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dueDate)) return null;
  const matchingWeek = seed.customerDemand?.weeks.find((week) => week.id === batch.demandCheckpointId || week.weekEnd === dueDate);
  const checkpoint = batch.demandCheckpointId?.match(/^(\d{4})-W(\d{1,2})$/);
  const derived = isoWeekForDate(dueDate);
  const year = matchingWeek?.isoYear ?? (checkpoint ? Number(checkpoint[1]) : derived?.year);
  const week = matchingWeek?.isoWeek ?? (checkpoint ? Number(checkpoint[2]) : derived?.week);
  if (!year || !week) return null;
  const weekLabel = `W${String(week).padStart(2, "0")}.${year}`;
  const shortDateLabel = new Intl.DateTimeFormat("tr-TR", { day: "2-digit", month: "short", timeZone: "UTC" }).format(new Date(`${dueDate}T00:00:00Z`));
  const dateLabel = new Intl.DateTimeFormat("tr-TR", { day: "2-digit", month: "short", year: "numeric", timeZone: "UTC" }).format(new Date(`${dueDate}T00:00:00Z`));
  return { weekLabel, shortDateLabel, dateLabel, label: `${weekLabel} · ${dateLabel}` };
}

function excludedPriorBacklogStatus(
  seed: PlanningSeed,
  result: Pick<ScenarioResult, "batches">,
  readinessEvents: DeliveryReadinessEvent[],
): WeeklyPlanStatus | null {
  const demand = seed.customerDemand;
  if (!demand || (seed.activePlanRun?.includePriorBacklog ?? true)) return null;
  const startIndex = demand.weeks.findIndex((week) => week.id === demand.activeScope.startWeekId);
  const activeWeek = demand.weeks[startIndex];
  if (!activeWeek) return null;
  const dueSerial = inputDateSerial(activeWeek.weekStart) - 2;
  const dueDate = new Date(Date.UTC(1899, 11, 30) + dueSerial * 86_400_000).toISOString().slice(0, 10);
  const products = demand.products.map((product) => {
    const required = Math.max(0, startIndex === 0
      ? product.priorDemand
      : product.weeklyDemands[startIndex - 1]?.cumulativeQuantity ?? product.priorDemand);
    const available = seed.activePlanRun?.optimizationGoal === "coarse"
      ? productionQuantityByTurningDate(seed, result.batches as PlannedBatch[], product.product, dueSerial)
      : routedQuantityByDate(seed, readinessEvents, product.product, dueSerial);
    const ready = Math.min(required, available);
    return { product: product.product.toUpperCase(), required, ready, shortage: Math.max(0, required - ready) };
  }).filter((product) => product.required > 0);
  const required = products.reduce((sum, product) => sum + product.required, 0);
  if (required <= 0) return null;
  const ready = products.reduce((sum, product) => sum + product.ready, 0);
  return {
    id: "excluded-prior-backlog",
    label: "Devreden açık",
    dueDate,
    newDemand: required,
    required,
    ready,
    shortage: Math.max(0, required - ready),
    riskProductCount: products.filter((product) => product.shortage > 0).length,
    products,
    excludedFromPlan: true,
  };
}

export function buildWeeklyPlanStatus(
  seed: PlanningSeed,
  result: Pick<ScenarioResult, "batches">,
  readinessEvents = buildDeliveryReadinessEvents(seed, result),
): WeeklyPlanStatus[] {
  const checkpointsByProduct = new Map<string, ProductCheckpoint[]>();
  for (const order of seed.orders.filter((item) => item.quantity > 0)) {
    const product = order.product.toUpperCase();
    const current = checkpointsByProduct.get(product) ?? [];
    checkpointsByProduct.set(product, [...current, ...checkpointsForOrder(order)]);
  }

  const dates = [...new Set([...checkpointsByProduct.values()].flatMap((checkpoints) => checkpoints.map((checkpoint) => checkpoint.date)))]
    .filter(Boolean)
    .sort();
  let previousRequired = 0;

  const weeklyRows = dates.map((dueDate) => {
    const dueSerial = inputDateSerial(dueDate);
    const products = [...checkpointsByProduct.entries()].map(([product, checkpoints]) => {
      const required = checkpoints
        .filter((checkpoint) => checkpoint.date <= dueDate)
        .reduce((sum, checkpoint) => sum + checkpoint.quantity, 0);
      const available = seed.activePlanRun?.optimizationGoal === "coarse"
        ? productionQuantityByTurningDate(seed, result.batches as PlannedBatch[], product, dueSerial)
        : routedQuantityByDate(seed, readinessEvents, product, dueSerial);
      const ready = Math.min(required, available);
      return { product, required, ready, shortage: Math.max(0, required - ready) };
    }).filter((product) => product.required > 0);
    const required = products.reduce((sum, product) => sum + product.required, 0);
    const ready = products.reduce((sum, product) => sum + product.ready, 0);
    const row: WeeklyPlanStatus = {
      id: dueDate,
      label: weekLabel(seed, dueDate),
      dueDate,
      newDemand: Math.max(0, required - previousRequired),
      required,
      ready,
      shortage: Math.max(0, required - ready),
      riskProductCount: products.filter((product) => product.shortage > 0).length,
      products,
    };
    previousRequired = required;
    return row;
  });
  const excludedPriorBacklog = excludedPriorBacklogStatus(seed, result, readinessEvents);
  return excludedPriorBacklog ? [excludedPriorBacklog, ...weeklyRows] : weeklyRows;
}

export function selectedBatchWeeklyStatus(
  rows: WeeklyPlanStatus[],
  batch: Pick<PlannedBatch, "product" | "demandDueDate"> | null,
): { week: WeeklyPlanStatus; product: WeeklyProductStatus } | null {
  if (!batch?.demandDueDate) return null;
  const week = rows.find((row) => row.dueDate === batch.demandDueDate);
  const product = week?.products.find((item) => item.product === batch.product.toUpperCase());
  return week && product ? { week, product } : null;
}

export function batchSplitInsight(
  batches: PlannedBatch[],
  selectedBatch: Pick<PlannedBatch, "id" | "product" | "machineId" | "demandDueDate"> | null,
): BatchSplitInsight | null {
  if (!selectedBatch) return null;
  const queue = batches
    .filter((batch) => batch.status === "planned" && batch.machineId === selectedBatch.machineId)
    .sort((left, right) => left.start - right.start || left.planColumn - right.planColumn);
  const selectedIndex = queue.findIndex((batch) => batch.id === selectedBatch.id);
  if (selectedIndex < 0) return null;
  let groupStart = selectedIndex;
  let groupEnd = selectedIndex;
  while (groupStart > 0 && queue[groupStart - 1].product === selectedBatch.product) groupStart -= 1;
  while (groupEnd < queue.length - 1 && queue[groupEnd + 1].product === selectedBatch.product) groupEnd += 1;

  const resumedIndex = queue.findIndex((batch, index) => index > groupEnd && batch.product === selectedBatch.product);
  let intervening: PlannedBatch[] = [];
  let resumedDueDate = selectedBatch.demandDueDate ?? "";
  if (resumedIndex >= 0) {
    intervening = queue.slice(groupEnd + 1, resumedIndex);
    resumedDueDate = queue[resumedIndex].demandDueDate ?? "";
  } else {
    let earlierIndex = -1;
    for (let index = groupStart - 1; index >= 0; index -= 1) {
      if (queue[index].product === selectedBatch.product) { earlierIndex = index; break; }
    }
    if (earlierIndex < 0) return null;
    intervening = queue.slice(earlierIndex + 1, groupStart);
  }
  const interruption = intervening
    .filter((batch) => batch.product !== selectedBatch.product)
    .sort((left, right) => (left.demandDueDate || "9999-12-31").localeCompare(right.demandDueDate || "9999-12-31"))[0];
  if (!interruption) return null;
  const interveningDueDate = interruption.demandDueDate ?? "";
  return {
    interrupted: true,
    justifiedByDeadline: Boolean(interveningDueDate && resumedDueDate && interveningDueDate < resumedDueDate),
    interveningProduct: interruption.product,
    interveningDueDate,
    resumedDueDate,
  };
}

