import { processWaitWorkdays } from "./process-waits";
import { flowRule, addDepartmentWorkMinutes } from "./flow-settings";
import { productProcessRoute, processLabel } from "./process-master-data";
import { activeLotInterruptions, finishProductionInterruptions } from "./production-interruptions";
import { productionHistoryLots } from "./production-archive";
import { factoryDateTimeInput, factoryDateTimeToIso, factoryNowSerial } from "./factory-time";
import { processMasterDataForProduct, type ProcessKind } from "./process-master-data";
import type { PlanningSeed, ProductionHistoryAllocationInput, ProductionHistoryEntry, ProductionInventoryStatus, WipLot, WipMovement, WipStage } from "./planning";
import { addFactoryWorkdays, routedDeliveryReadyAt } from "./delivery-calendar";

export type WipOperationInput = {
  confirmedBuffer?: boolean;
  confirmedInterruption?: boolean;
  remainderAction?: "keep" | "scrap";
  lotId: string;
  process: "drilling" | "deburring" | "gkm";
  resourceId: string;
  resourceName: string;
  quantity: number;
  startedAt: number;
  completedAt: number;
  plannedStart?: number;
  plannedEnd?: number;
  recordedAt?: string;
};

const terminalStages = new Set<WipStage>(["delivered", "scrapped"]);

function isoNow(value?: string): string {
  return value ?? new Date().toISOString();
}

function movementId(seed: PlanningSeed, recordedAt: string): string {
  return `wip-move-${recordedAt.replace(/\D/g, "").slice(0, 17)}-${(seed.wipMovements ?? []).length + 1}`;
}

function lotId(seed: PlanningSeed, sourceId: string): string {
  const base = `wip-${sourceId}`;
  if (!(seed.wipLots ?? []).some((lot) => lot.id === base)) return base;
  let ordinal = 2;
  while ((seed.wipLots ?? []).some((lot) => lot.id === `${base}-${ordinal}`)) ordinal += 1;
  return `${base}-${ordinal}`;
}

function appendMovement(seed: PlanningSeed, movement: Omit<WipMovement, "id">): WipMovement {
  const value = { ...movement, id: movementId(seed, movement.recordedAt) };
  seed.wipMovements = [...(seed.wipMovements ?? []), value].slice(-2_000);
  return value;
}

export function addWipWaitWorkdays(seed: PlanningSeed, startValue: number, workdaysValue: number): number {
  return addFactoryWorkdays(seed, startValue, workdaysValue);
}

export function wipStageLabel(stage: WipStage, ready = false): string {
  return ({
    "unclassified": "Konumu doğrulanmalı",
    "quality-hold": ready ? "Delmeye hazır" : "Kalite bekliyor",
    "drilling-queue": "Delme bekliyor",
    "deburring-queue": "Çapak alma bekliyor",
    "washing-buffer": ready ? "GKM’ye hazır" : "Yıkama tamponunda",
    "gkm-buffer": ready ? "GKM’ye hazır" : "GKM öncesi bekliyor",
    "gkm-queue": "GKM bekliyor",
    "delivery-ready": ready ? "Teslimata hazır" : "Paketleme & Final Kontrol",
    "on-hold": "Blokeli",
    "delivered": "Teslim edildi",
    "scrapped": "Iskarta",
  })[stage];
}

export function nextProcessForWipStage(stage: WipStage): WipLot["nextProcess"] {
  if (stage === "quality-hold" || stage === "drilling-queue") return "drilling";
  if (stage === "deburring-queue") return "deburring";
  if (stage === "washing-buffer" || stage === "gkm-buffer" || stage === "gkm-queue") return "gkm";
  return undefined;
}

export function activeWipLots(seed: Pick<PlanningSeed, "wipLots">): WipLot[] {
  return (seed.wipLots ?? []).filter((lot) => lot.availableQuantity > 0 && !terminalStages.has(lot.stage));
}

/** One Torna → Delme wait: an Akış Ayarı rule wins; otherwise Proses bekleme süreleri workdays. */
function turningReadyAt(seed: PlanningSeed, completedAt: number, family: WipLot["family"], applyCurrentFlow: boolean): number {
  if (!applyCurrentFlow) return addWipWaitWorkdays(seed, completedAt, 1);
  const rule = flowRule(seed, family, "turning", "drilling");
  if (rule) return rule.mode === "static" ? addDepartmentWorkMinutes(seed, completedAt, rule.minutes) : completedAt;
  return addWipWaitWorkdays(seed, completedAt, processWaitWorkdays(seed, "turning"));
}

export function registerTurningCompletion(
  seed: PlanningSeed,
  history: ProductionHistoryEntry,
  recordedAt = history.archivedAt,
  applyCurrentFlow = true,
): WipLot | undefined {
  const existing = (seed.wipLots ?? []).find((lot) => lot.sourceHistoryEntryId === history.id && !lot.parentLotId);
  if (existing) return existing;
  const product = processMasterDataForProduct(seed.processMasterData, history.product);
  if (!product || history.process !== "turning" || history.completedQuantity <= 0 || history.inventoryStatus !== "semi-finished") return undefined;
  const createdAt = isoNow(recordedAt);
  const created: WipLot = {
    id: lotId(seed, history.id),
    interruptionIds: history.interruptionIds ? [...history.interruptionIds] : undefined,
    sourceHistoryEntryId: history.id,
    sourceBatchId: history.sourceBatchId,
    workOrder: history.workOrder.trim(),
    product: history.product.trim().toUpperCase(),
    family: product.family,
    originalQuantity: history.completedQuantity,
    availableQuantity: history.completedQuantity,
    deliveredQuantity: 0,
    scrappedQuantity: 0,
    stage: turningReadyAt(seed, history.completedAt, product.family, applyCurrentFlow) > history.completedAt ? "quality-hold" : "drilling-queue",
    nextProcess: "drilling",
    readyAt: turningReadyAt(seed, history.completedAt, product.family, applyCurrentFlow),
    completedSteps: [{
      process: "turning",
      resourceId: history.machineId,
      resourceName: history.machineName,
      start: history.start,
      end: history.completedAt,
      plannedStart: history.start,
      plannedEnd: history.plannedEnd,
      quantity: history.completedQuantity,
      recordedAt: createdAt,
    }],
    createdAt,
    updatedAt: createdAt,
  };
  if (product.route) applyCustomRouteProgress(seed, created, "turning", history.completedAt);
  if (applyCurrentFlow) applyCompletedFlow(seed, created, "turning", history.completedAt);
  seed.wipLots = [...(seed.wipLots ?? []), created];
  appendMovement(seed, {
    lotId: created.id,
    kind: "created",
    quantity: created.availableQuantity,
    toStage: created.stage,
    occurredAt: history.completedAt,
    recordedAt: createdAt,
    note: "Torna tamamlanmasından otomatik yarı mamül kaydı",
  });
  return created;
}

export function hydrateWipFromProductionHistory(seed: PlanningSeed): void {
  seed.wipLots = seed.wipLots ?? [];
  seed.wipMovements = seed.wipMovements ?? [];
  for (const entry of seed.productionHistory ?? []) registerTurningCompletion(seed, entry, entry.statusChangedAt || entry.archivedAt, false);
}

function applyCustomRouteProgress(seed: PlanningSeed, lot: WipLot, process: ProcessKind, completedAt: number): void {
  const product = processMasterDataForProduct(seed.processMasterData, lot.product)!;
  const next = product.route![product.route!.indexOf(process) + 1];
  if (next && next !== "turning") {
    const parameter = product.processes.find(item => item.process === next)!;
    lot.nextProcess = next;
    lot.stage = next === "drilling" ? (processWaitWorkdays(seed, process) > 0 ? "quality-hold" : "drilling-queue")
      : next === "deburring" ? "deburring-queue" : processWaitWorkdays(seed, process) > 0 ? "gkm-buffer" : "gkm-queue";
    lot.readyAt = addWipWaitWorkdays(seed, completedAt, processWaitWorkdays(seed, process));
  } else {
    lot.stage = "delivery-ready";
    delete lot.nextProcess;
    lot.readyAt = routedDeliveryReadyAt(seed, completedAt, undefined, process);
  }
}

function applyCompletedFlow(seed: PlanningSeed, lot: WipLot, process: ProcessKind, completedAt: number): void {
  const rule = flowRule(seed, lot.family, process, lot.nextProcess ?? "delivery");
  if (!rule) return;
  lot.readyAt = rule.mode === "static" ? addDepartmentWorkMinutes(seed, completedAt, rule.minutes) : completedAt;
  if (lot.nextProcess === "drilling") lot.stage = lot.readyAt > completedAt ? "quality-hold" : "drilling-queue";
  if (lot.nextProcess === "gkm") lot.stage = lot.readyAt > completedAt ? "washing-buffer" : "gkm-queue";
}

function advanceStage(seed: PlanningSeed, lot: WipLot, process: WipOperationInput["process"], completedAt: number): void {
  if (processMasterDataForProduct(seed.processMasterData, lot.product)?.route) {
    applyCustomRouteProgress(seed, lot, process, completedAt);
  } else if (process === "drilling" && lot.family === "piston") {
    lot.stage = "deburring-queue";
    lot.nextProcess = "deburring";
    lot.readyAt = addWipWaitWorkdays(seed, completedAt, processWaitWorkdays(seed, process));
  } else if (process === "drilling") {
    lot.stage = processWaitWorkdays(seed, process) > 0 ? "washing-buffer" : "gkm-queue";
    lot.nextProcess = "gkm";
    lot.readyAt = addWipWaitWorkdays(seed, completedAt, processWaitWorkdays(seed, process));
  } else if (process === "deburring") {
    lot.stage = processWaitWorkdays(seed, process) > 0 ? "gkm-buffer" : "gkm-queue";
    lot.nextProcess = "gkm";
    lot.readyAt = addWipWaitWorkdays(seed, completedAt, processWaitWorkdays(seed, process));
  } else {
    lot.stage = "delivery-ready";
    delete lot.nextProcess;
    lot.readyAt = routedDeliveryReadyAt(seed, completedAt, undefined, process);
  }
  applyCompletedFlow(seed, lot, process, completedAt);
  // A carry-over marker belongs to the operation that was rolled forward.
  // Once that operation is completed, the following stage must use its newly
  // calculated real readiness date instead of inheriting the old marker.
  delete lot.rolledForwardFrom;
  delete lot.rolledForwardAt;
}

/** Planned/released readiness used for scheduling and starting new work. */
export function wipOperationReadyAt(lot: Pick<WipLot, "readyAt" | "rolledForwardFrom">): number {
  return lot.rolledForwardFrom ?? lot.readyAt;
}

/** Actual chronology for recording completed work; never invent a missing predecessor. */
export function wipCompletionEarliestAt(seed: PlanningSeed, lot: WipLot): number {
  const route = processMasterDataForProduct(seed.processMasterData, lot.product)?.route
    ?? (lot.family === "piston" ? ["turning", "drilling", "deburring", "gkm"] : ["turning", "drilling", "gkm"]);
  const index = lot.stage === "delivery-ready" ? route.length : route.indexOf(lot.nextProcess!);
  const predecessors = route.slice(0, index);
  if (index <= 0 || lot.stage === "on-hold" || lot.stage === "unclassified" || terminalStages.has(lot.stage)) return wipOperationReadyAt(lot);
  const steps = predecessors.map(process => lot.completedSteps.find(step => step.process === process));
  if (steps.some(step => !step || !Number.isFinite(step.end))) return wipOperationReadyAt(lot);
  const actualEnd = Math.max(...lot.completedSteps.map(step => step.end));
  return Number.isFinite(actualEnd) ? actualEnd : wipOperationReadyAt(lot);
}

/** Explicit routes require every active step; legacy records retain the GKM gate. */
export function completedDeliveryRouteEnd(seed: PlanningSeed, lot: WipLot): number | undefined {
  const route = processMasterDataForProduct(seed.processMasterData, lot.product)?.route;
  const required = route ?? ["gkm"];
  if (!required.length) return undefined;
  const steps = required.map(process => lot.completedSteps.find(step => step.process === process));
  if (steps.some(step => !step || !Number.isFinite(step.end))) return undefined;
  return Math.max(...steps.map(step => step!.end));
}

/** Releases only an actual completed stage's waiting allowance, never a route step. */
export function releaseWipBuffer(seed: PlanningSeed, lotId: string, occurredAt: number, confirmed: boolean, recordedAt = new Date().toISOString()): WipLot {
  const lot = seed.wipLots?.find((item) => item.id === lotId);
  if (!lot || lot.availableQuantity <= 0) throw new Error("Açık yarı mamül bulunamadı.");
  const customRoute = processMasterDataForProduct(seed.processMasterData, lot.product)?.route;
  const previousProcess = customRoute
    ? lot.stage === "delivery-ready" ? customRoute.at(-1) : customRoute[customRoute.indexOf(lot.nextProcess!) - 1]
    : ({ "quality-hold": "turning", "washing-buffer": "drilling", "gkm-buffer": "deburring", "delivery-ready": "gkm" } as Record<string, string>)[lot.stage];
  const previous = lot.completedSteps.find((step) => step.process === previousProcess);
  if (!previous || !Number.isFinite(previous.end) || !Number.isFinite(occurredAt) || occurredAt < previous.end) throw new Error("Bekleme yalnız önceki proses gerçekten tamamlandıktan sonra kaldırılabilir.");
  if (!confirmed) throw new Error("Proses kontrolünün tamamlandığını onaylayın.");
  if (occurredAt >= wipOperationReadyAt(lot)) throw new Error("Bu şarjın bekleme süresi zaten tamamlanmış.");
  const previousReadyAt = wipOperationReadyAt(lot);
  lot.readyAt = occurredAt;
  delete lot.rolledForwardFrom;
  delete lot.rolledForwardAt;
  lot.updatedAt = recordedAt;
  appendMovement(seed, { lotId: lot.id, kind: "buffer-released", quantity: lot.availableQuantity, fromStage: lot.stage, toStage: lot.stage, occurredAt, recordedAt,
    note: lot.stage === "delivery-ready" ? "Proses kontrol ve paketleme tamamlandı onayıyla teslimat tamponu kaldırıldı." : "İlgili kontrol / yıkama tamamlandı onayıyla proses tamponu kaldırıldı.", previousReadyAt });
  return lot;
}

function assertResourceEligibility(seed: PlanningSeed, lot: WipLot, input: WipOperationInput): void {
  const product = processMasterDataForProduct(seed.processMasterData, lot.product);
  if (product?.route) {
    if (!product.route.includes(input.process)) throw new Error("Bu proses ürün rotasında Pasif.");
    for (const process of product.route.filter(item => item !== "turning")) {
      const parameter = product.processes.find(item => item.process === process);
      if (!parameter || !Number.isFinite(parameter.waitWorkdaysBefore) || parameter.waitWorkdaysBefore < 0) throw new Error("Aktif proses parametreleri eksik; ürün rotasını kontrol edin.");
    }
  }
  const parameter = product?.processes.find((item) => item.process === input.process);
  if (!parameter) throw new Error(`${lot.product} için ${input.process} prosesi tanımlı değil.`);
  if (!parameter.resourcePriority.includes(input.resourceId)) throw new Error(`${input.resourceId}, ${lot.product} için uygun bir iş merkezi değil.`);
}

export function completeWipOperation(seed: PlanningSeed, input: WipOperationInput): { completed: WipLot; remainder?: WipLot } {
  const source = (seed.wipLots ?? []).find((lot) => lot.id === input.lotId);
  if (!source) throw new Error("Yarı mamül şarjı bulunamadı.");
  if (activeLotInterruptions(seed, source).length && !input.confirmedInterruption) throw new Error("Üretim sonlanmadı, yine de üretime alayım mı? Devam etmek için onaylayın.");
  if (source.stage === "on-hold") throw new Error("Blokeli yarı mamül işleme alınamaz.");
  if (terminalStages.has(source.stage)) throw new Error("Kapanmış yarı mamül işleme alınamaz.");
  if (source.nextProcess !== input.process) throw new Error(`Sıradaki operasyon ${source.nextProcess ?? "tanımlı değil"}.`);
  if (!Number.isInteger(input.quantity) || input.quantity <= 0 || input.quantity > source.availableQuantity) throw new Error("Tamamlanan adet, yarı mamül bakiyesini aşmayan pozitif tam sayı olmalıdır.");
  if (input.remainderAction && input.remainderAction !== "keep" && input.remainderAction !== "scrap") throw new Error("Kalan miktar işlemini seçin.");
  if (!Number.isFinite(input.startedAt) || !Number.isFinite(input.completedAt) || input.completedAt < input.startedAt) throw new Error("Operasyon başlangıç ve bitiş tarihlerini kontrol edin.");
  const early = input.startedAt + 1e-8 < wipOperationReadyAt(source);
  if (early && !input.confirmedBuffer) throw new Error("Planlanan beklemeden erken tamamlama için ilgili kontrol / yıkamanın tamamlandığını onaylayın.");
  if (input.startedAt + 1e-8 < wipCompletionEarliestAt(seed, source)) throw new Error("Operasyon önceki gerçek proses bitişinden önce başlayamaz; eksik proses kaydını kontrol edin.");
  assertResourceEligibility(seed, source, input);
  const scrapQuantity = source.availableQuantity - input.quantity;
  const scrapHistory = input.remainderAction === "scrap" && scrapQuantity > 0
    ? seed.productionHistory?.find((entry) => entry.id === source.sourceHistoryEntryId && entry.inventoryStatus === "semi-finished")
    : undefined;
  if (input.remainderAction === "scrap" && scrapQuantity > 0 && (!scrapHistory || scrapHistory.completedQuantity < scrapQuantity || scrapHistory.originalQuantity < scrapQuantity)) {
    throw new Error("Iskarta için yarı mamül ve üretim arşivi eşleşmiyor.");
  }

  const recordedAt = isoNow(input.recordedAt);
  const fromStage = source.stage;
  let completed = source;
  let remainder: WipLot | undefined;
  if (input.quantity < source.availableQuantity) {
    source.originalQuantity -= input.quantity;
    source.availableQuantity -= input.quantity;
    source.updatedAt = recordedAt;
    completed = {
      ...JSON.parse(JSON.stringify(source)) as WipLot,
      id: lotId(seed, source.sourceHistoryEntryId),
      parentLotId: source.id,
      originalQuantity: input.quantity,
      availableQuantity: input.quantity,
      deliveredQuantity: 0,
      scrappedQuantity: 0,
      createdAt: recordedAt,
      updatedAt: recordedAt,
    };
    seed.wipLots = [...(seed.wipLots ?? []), completed];
    remainder = source;
    appendMovement(seed, {
      lotId: source.id,
      kind: "split",
      quantity: input.quantity,
      fromStage,
      toStage: source.stage,
      occurredAt: input.completedAt,
      recordedAt,
      note: `${completed.id} kısmi operasyon için ayrıldı`,
    });
  }

  if (remainder && input.remainderAction === "scrap") {
    const history = scrapHistory!;
    const scrapId = `${history.id}-iskarta-${crypto.randomUUID()}`;
    const processName = ({ drilling: "Delme", deburring: "Çapak Alma", gkm: "GKM" } as const)[input.process];
    const scrapReason = `${processName} sırasında ${scrapQuantity.toLocaleString("tr-TR")} adet ıskarta.`;
    if (history.completedQuantity === scrapQuantity) {
      history.inventoryStatus = "scrapped";
      history.scrappedAt = recordedAt;
      history.statusChangedAt = recordedAt;
      history.splitKind = "scrap";
      history.statusChangeReason = scrapReason;
      delete history.statusChangedBy;
    } else {
      history.completedQuantity -= scrapQuantity;
      history.originalQuantity -= scrapQuantity;
      seed.productionHistory = [...(seed.productionHistory ?? []), {
        ...history,
        id: scrapId,
        sourceEntryId: history.id,
        originalQuantity: scrapQuantity,
        completedQuantity: scrapQuantity,
        inventoryStatus: "scrapped",
        statusChangedAt: recordedAt,
        scrappedAt: recordedAt,
        splitKind: "scrap",
        statusChangeReason: scrapReason,
        statusChangedBy: undefined,
      }];
      remainder.sourceHistoryEntryId = scrapId;
    }
    scrapWipQuantity(seed, remainder.id, scrapQuantity, input.completedAt, recordedAt);
    finishProductionInterruptions(seed, source.id, input.process, input.completedAt);
  }

  if (!remainder) finishProductionInterruptions(seed, source.id, input.process, input.completedAt);
  if (early) {
    appendMovement(seed, { lotId: completed.id, kind: "buffer-released", quantity: input.quantity,
      fromStage, toStage: fromStage, occurredAt: input.startedAt, recordedAt,
      previousReadyAt: wipOperationReadyAt(completed),
      note: "Fiili tamamlama sırasında ilgili kontrol / yıkama tamamlandı onayıyla yalnız tamamlanan adedin planlanan beklemesi kaldırıldı." });
  }
  completed.completedSteps = [...completed.completedSteps, {
    process: input.process,
    resourceId: input.resourceId,
    resourceName: input.resourceName,
    start: input.startedAt,
    end: input.completedAt,
    plannedStart: input.plannedStart,
    plannedEnd: input.plannedEnd,
    quantity: input.quantity,
    recordedAt,
  }];
  advanceStage(seed, completed, input.process, input.completedAt);
  completed.updatedAt = recordedAt;
  appendMovement(seed, {
    lotId: completed.id,
    kind: "process-completed",
    quantity: input.quantity,
    fromStage,
    toStage: completed.stage,
    process: input.process,
    resourceId: input.resourceId,
    occurredAt: input.completedAt,
    recordedAt,
  });
  return { completed, remainder };
}

export function correctWipStage(seed: PlanningSeed, lotIdValue: string, stage: WipStage, occurredAt: number, note = "Manuel konum doğrulaması", recordedAtValue?: string): WipLot {
  const lot = (seed.wipLots ?? []).find((item) => item.id === lotIdValue);
  if (!lot) throw new Error("Yarı mamül şarjı bulunamadı.");
  if (terminalStages.has(lot.stage)) throw new Error("Teslim edilmiş veya ıskartaya ayrılmış şarjın konumu değiştirilemez.");
  if (!Number.isFinite(occurredAt)) throw new Error("Konum tarihi geçersiz.");
  const recordedAt = isoNow(recordedAtValue);
  const fromStage = lot.stage;
  if (stage === "on-hold") {
    lot.heldFromStage = lot.stage;
    lot.heldNextProcess = lot.nextProcess;
    delete lot.nextProcess;
  } else {
    delete lot.heldFromStage;
    delete lot.heldNextProcess;
    lot.nextProcess = nextProcessForWipStage(stage);
  }
  lot.stage = stage;
  lot.readyAt = occurredAt;
  lot.updatedAt = recordedAt;
  appendMovement(seed, { lotId: lot.id, kind: stage === "on-hold" ? "hold" : "stage-corrected", quantity: lot.availableQuantity, fromStage, toStage: stage, occurredAt, recordedAt, note });
  return lot;
}

export function releaseWipHold(seed: PlanningSeed, lotIdValue: string, occurredAt: number, recordedAtValue?: string): WipLot {
  const lot = (seed.wipLots ?? []).find((item) => item.id === lotIdValue);
  if (!lot || lot.stage !== "on-hold") throw new Error("Serbest bırakılacak blokeli yarı mamül bulunamadı.");
  const recordedAt = isoNow(recordedAtValue);
  const nextStage = lot.heldFromStage && lot.heldFromStage !== "on-hold" ? lot.heldFromStage : "unclassified";
  lot.stage = nextStage;
  lot.nextProcess = lot.heldNextProcess ?? nextProcessForWipStage(nextStage);
  lot.readyAt = occurredAt;
  lot.updatedAt = recordedAt;
  delete lot.heldFromStage;
  delete lot.heldNextProcess;
  appendMovement(seed, { lotId: lot.id, kind: "release", quantity: lot.availableQuantity, fromStage: "on-hold", toStage: nextStage, occurredAt, recordedAt });
  return lot;
}

const relatedLots = productionHistoryLots;

function consumeLots(seed: PlanningSeed, lots: WipLot[], quantityValue: number, kind: "delivered" | "scrapped", occurredAt: number, recordedAt: string): void {
  let quantity = quantityValue;
  const eligible = kind === "delivered"
    ? lots.filter((lot) => lot.stage === "delivery-ready" && Math.floor(lot.readyAt) <= Math.floor(occurredAt))
    : lots.filter((lot) => lot.availableQuantity > 0 && !terminalStages.has(lot.stage));
  const available = eligible.reduce((sum, lot) => sum + lot.availableQuantity, 0);
  if (quantity > available) {
    throw new Error(kind === "delivered" ? `Teslimata hazır yarı mamül yalnızca ${available.toLocaleString("tr-TR")} adet.` : `Iskartaya ayrılabilir yarı mamül yalnızca ${available.toLocaleString("tr-TR")} adet.`);
  }
  for (const lot of eligible.sort((left, right) => left.readyAt - right.readyAt || left.createdAt.localeCompare(right.createdAt))) {
    if (quantity <= 0) break;
    const consumed = Math.min(quantity, lot.availableQuantity);
    const fromStage = lot.stage;
    lot.availableQuantity -= consumed;
    if (kind === "delivered") lot.deliveredQuantity += consumed;
    else lot.scrappedQuantity += consumed;
    if (lot.availableQuantity === 0) {
      if (kind === "scrapped") {
        lot.scrappedFromStage = fromStage;
        lot.scrappedNextProcess = lot.nextProcess;
      }
      lot.stage = kind;
      delete lot.nextProcess;
    }
    lot.updatedAt = recordedAt;
    appendMovement(seed, { lotId: lot.id, kind, quantity: consumed, fromStage, toStage: lot.stage, occurredAt, recordedAt });
    quantity -= consumed;
  }
}

export function deliverWipQuantity(seed: PlanningSeed, lotId: string, quantity: number, occurredAt: number, recordedAt: string): void {
  const lot = seed.wipLots?.find((item) => item.id === lotId);
  const completedAt = lot ? completedDeliveryRouteEnd(seed, lot) : undefined;
  if (!lot || lot.stage !== "delivery-ready" || completedAt === undefined || completedAt > occurredAt) throw new Error("Aktif üretim rotası (GKM aktifse GKM dahil) tamamlanmadan teslimat yapılamaz.");
  if (!Number.isInteger(quantity) || quantity <= 0 || !Number.isFinite(occurredAt) || occurredAt < wipOperationReadyAt(lot)) throw new Error("Teslim adedini ve hazır olma zamanını kontrol edin.");
  consumeLots(seed, [lot], quantity, "delivered", occurredAt, recordedAt);
}

export function scrapWipQuantity(seed: PlanningSeed, lotId: string, quantity: number, occurredAt: number, recordedAt: string): void {
  const lot = seed.wipLots?.find(item => item.id === lotId);
  if (!lot || !Number.isInteger(quantity) || quantity <= 0 || !Number.isFinite(occurredAt)) throw new Error("Iskarta miktarını ve şarjı kontrol edin.");
  consumeLots(seed, [lot], quantity, "scrapped", occurredAt, recordedAt);
}

export function applyHistoryAllocationToWip(seed: PlanningSeed, entry: ProductionHistoryEntry, input: ProductionHistoryAllocationInput, recordedAtValue?: string, deliveryEntryId?: string): void {
  const lots = relatedLots(seed, entry);
  if (!lots.length) {
    if (input.deliveredQuantity > 0) throw new Error("Teslimat için doğrulanmış bir WIP rota kaydı bulunamadı.");
    return;
  }
  const recordedAt = isoNow(recordedAtValue);
  const timed = input.deliveryDate.includes("T");
  const deliveryIso = timed ? factoryDateTimeToIso(input.deliveryDate) : "";
  if (input.deliveredQuantity > 0 && timed && (!deliveryIso || factoryDateTimeInput(deliveryIso) !== input.deliveryDate)) throw new Error("Geçerli bir teslim tarihi ve saati seçin.");
  const deliveryAt = timed ? factoryNowSerial(deliveryIso)
    : input.deliveryDate ? Date.parse(`${input.deliveryDate}T00:00:00Z`) / 86_400_000 + 25_569 : input.completedAt;
  if (input.deliveredQuantity > 0 && timed && deliveryAt > factoryNowSerial(recordedAt)) throw new Error("Teslim tarihi ve saati şu andan sonra olamaz.");
  const deliveryLots = timed ? lots.filter(lot => lot.availableQuantity > 0 && lot.stage === "delivery-ready"
    && (completedDeliveryRouteEnd(seed, lot) ?? Infinity) <= deliveryAt
    && lot.completedSteps.every(step => Number.isFinite(step.end) && step.end <= deliveryAt)
    && (wipOperationReadyAt(lot) <= deliveryAt || input.confirmedDeliveryBuffer === true)) : lots;
  if (input.deliveredQuantity > 0 && timed && deliveryLots.reduce((sum, lot) => sum + lot.availableQuantity, 0) < input.deliveredQuantity) {
    throw new Error("Seçilen saatte yeterli miktar teslimata hazır değil. Aktif prosesleri tamamlayın; erken teslimat için proses kontrol ve paketlemenin tamamlandığını onaylayın.");
  }
  const before = new Map(lots.map(lot => [lot.id, lot.deliveredQuantity]));
  if (input.deliveredQuantity > 0 && timed) {
    let left = input.deliveredQuantity;
    for (const lot of deliveryLots.sort((a, b) => a.readyAt - b.readyAt || a.createdAt.localeCompare(b.createdAt))) {
      const amount = Math.min(left, lot.availableQuantity);
      if (!amount) continue;
      const early = deliveryAt < wipOperationReadyAt(lot);
      const readiness = { readyAt: lot.readyAt, rolledForwardFrom: lot.rolledForwardFrom, rolledForwardAt: lot.rolledForwardAt };
      if (early) releaseWipBuffer(seed, lot.id, deliveryAt, true, recordedAt);
      deliverWipQuantity(seed, lot.id, amount, deliveryAt, recordedAt);
      if (early) {
        const release = seed.wipMovements?.findLast(movement => movement.lotId === lot.id && movement.kind === "buffer-released");
        if (release) release.quantity = amount;
        if (lot.availableQuantity > 0) Object.assign(lot, readiness);
      }
      left -= amount;
      if (!left) break;
    }
  } else if (input.deliveredQuantity > 0) consumeLots(seed, deliveryLots, input.deliveredQuantity, "delivered", deliveryAt, recordedAt);
  const shipped = seed.productionHistory?.find(item => item.inventoryStatus === "delivered" && (!deliveryEntryId || item.id === deliveryEntryId) && (item.id === entry.id || item.sourceEntryId === entry.id) && !item.wipAllocations && item.completedQuantity === input.deliveredQuantity);
  if (shipped) shipped.wipAllocations = lots.map(lot => ({ lotId: lot.id, quantity: lot.deliveredQuantity - (before.get(lot.id) ?? 0) })).filter(item => item.quantity > 0);
  const remainder = input.actualQuantity - input.deliveredQuantity;
  if (remainder > 0 && input.remainderAction === "scrap") consumeLots(seed, lots, remainder, "scrapped", input.completedAt, recordedAt);
}

export function applyHistoryStatusToWip(seed: PlanningSeed, entry: ProductionHistoryEntry, nextStatus: ProductionInventoryStatus, occurredAt: number, recordedAtValue?: string, note = "", actor = "Planlama oturumu"): void {
  const lots = relatedLots(seed, entry);
  if (!lots.length) {
    if (nextStatus === "delivered") throw new Error("Teslimat için doğrulanmış bir WIP rota kaydı bulunamadı.");
    return;
  }
  if (entry.inventoryStatus === nextStatus) return;
  // Voiding a scrap archive row hides it; its physical loss was already recorded.
  if (entry.inventoryStatus === "scrapped" && nextStatus === "voided") return;
  const recordedAt = isoNow(recordedAtValue);
  if (nextStatus === "delivered") consumeLots(seed, lots, entry.completedQuantity, "delivered", occurredAt, recordedAt);
  else if (nextStatus === "scrapped" || nextStatus === "voided") consumeLots(seed, lots, entry.completedQuantity, "scrapped", occurredAt, recordedAt);
  else if (nextStatus === "semi-finished") {
    // A scrap return reverses scrap only; a shared lot may also contain shipments.
    const fromScrap = entry.inventoryStatus === "scrapped";
    const balance = (lot: WipLot) => fromScrap ? lot.scrappedQuantity : lot.deliveredQuantity;
    const restorable = lots.filter(lot => balance(lot) > 0);
    if (restorable.reduce((sum, lot) => sum + balance(lot), 0) < entry.completedQuantity) {
      throw new Error(fromScrap ? "Iskarta kaydının yarı mamül bakiyesi yetersiz. Arşiv ve şarj eşleşmesini kontrol edin." : "Teslimat kaydının yarı mamül bakiyesi yetersiz. Arşiv ve şarj eşleşmesini kontrol edin.");
    }
    let remaining = entry.completedQuantity;
    for (const lot of restorable) {
      if (remaining <= 0) break;
      const restored = Math.min(remaining, balance(lot));
      if (fromScrap) lot.scrappedQuantity -= restored;
      else lot.deliveredQuantity -= restored;
      lot.availableQuantity += restored;
      lot.stage = fromScrap ? lot.scrappedFromStage ?? "delivery-ready" : "delivery-ready";
      lot.nextProcess = fromScrap ? lot.scrappedNextProcess ?? nextProcessForWipStage(lot.stage) : undefined;
      if (fromScrap && lot.scrappedQuantity === 0) {
        delete lot.scrappedFromStage;
        delete lot.scrappedNextProcess;
      }
      lot.readyAt = occurredAt;
      lot.updatedAt = recordedAt;
      appendMovement(seed, { lotId: lot.id, kind: "restored", quantity: restored, fromStage: fromScrap ? "scrapped" : "delivered", toStage: lot.stage, occurredAt, recordedAt, note: note.trim() || "Arşivden yarı mamule geri alındı", actor });
      remaining -= restored;
    }
  }
}

export function syncWipWithHistoryEdit(seed: PlanningSeed, entry: ProductionHistoryEntry, actualQuantity: number, completedAt: number, recordedAtValue?: string, correctionLotId?: string): void {
  const lots = relatedLots(seed, entry);
  if (!lots.length) return;
  const open = lots.filter(lot => lot.availableQuantity > 0 && !terminalStages.has(lot.stage));
  const sameDate = Math.floor(completedAt) === Math.floor(entry.completedAt);
  const delta = actualQuantity - entry.completedQuantity;
  if (!delta && sameDate) return;
  if (entry.inventoryStatus !== "semi-finished") throw new Error("Teslim edilmiş miktarı teslimat düzenleme penceresinden değiştirin.");
  if (open.length !== 1 && !correctionLotId) throw new Error("Bu kayıt birden fazla açık şarja bölünmüş. Adet farkının uygulanacağı şarjı seçin.");
  const lot = correctionLotId ? open.find(item => item.id === correctionLotId) : open[0];
  if (!lot) throw new Error("Seçilen şarj artık açık değil. Güncel kaydı yeniden seçin.");
  if (lot.availableQuantity + delta <= 0) throw new Error("Yeni adet teslim / ıskarta miktarından büyük olmalıdır. Tamamını kaldırmak için ıskarta işlemini kullanın.");
  if (!sameDate && (lots.length !== 1 || lot.completedSteps.length !== 1 || lot.deliveredQuantity || lot.scrappedQuantity)) throw new Error("Sonraki prosese geçmiş şarjın Torna tarihi değiştirilemez; adet ayrı olarak düzeltilebilir.");
  const changedAt = isoNow(recordedAtValue);
  lot.originalQuantity += delta;
  lot.availableQuantity += delta;
  if (lot.completedSteps.length === 1 && !lot.deliveredQuantity && !lot.scrappedQuantity) {
    lot.completedSteps[0] = { ...lot.completedSteps[0], end: sameDate ? entry.completedAt : completedAt, quantity: lot.originalQuantity };
    if (!sameDate) lot.readyAt = addWipWaitWorkdays(seed, completedAt, processWaitWorkdays(seed, "turning"));
  }

  lot.updatedAt = changedAt;
  appendMovement(seed, { lotId: lot.id, kind: "quantity-corrected", quantity: Math.abs(delta), fromStage: lot.stage, toStage: lot.stage, occurredAt: completedAt, recordedAt: changedAt, note: `Fiili adet ${entry.completedQuantity} → ${actualQuantity} olarak düzeltildi; geçmiş proses kayıtları korundu.` });
}

